eral; this is\n// for runtime-internal construction and for tests.\nfunc NewAgent(provider LlmProvider, systemPrompt string, maxTokens Int, tools []Tool) Agent {\n\trequireDistinctToolNames(tools)\n\treturn Agent{Provider: provider, SystemPrompt: systemPrompt, MaxTokens: maxTokens, Tools: tools}\n}\n\n// requireDistinctToolNames refuses two tools under one name. The dispatch is a name lookup,\n// so a duplicate meant the first silently won \226\128\148 a program composing tool lists\n// (`List.append (serverTools \226\128\166) [tool \226\128\166]`) could shadow an endpoint tool with a different\n// implementation and never learn it, and the vendors reject the duplicate declaration\n// with a 400 anyway. Failing closed here names the collision. The emitted `Agent { \226\128\166 }`\n// literal does not pass through NewAgent, so runLoop checks again before the first call.\nfunc requireDistinctToolNames(tools []Tool) {\n\tseen := make(map[string]struct{}, len(tools))\n\tfor _, tool := range tools {\n\t\tif _, duplicate := seen[tool.Name]; duplicate {\n\t\t\tpanic(fmt.Sprintf(\"Tesl.Agent: duplicate tool name %q \226\128\148 every tool offered to the \"+\n\t\t\t\t\"model must have a distinct name (a later tool would silently shadow the first)\",\n\t\t\t\ttool.Name))\n\t\t}\n\t\tseen[tool.Name] = struct{}{}\n\t}\n}\n\n// AgentReply is one completed turn: the final assistant text, what it cost, and how many\n// tools fired getting there.\ntype AgentReply struct {\n\tText       string\n\tusage      LlmUsage\n\ttoolCalls  Int\n\tstopReason string\n}\n\nfunc ReplyText(reply AgentReply) string { return reply.Text }\n\n// ReplyTokens is input plus output. Cache reads and writes are accounted separately by\n// the providers that report them and are not billed as either.\nfunc ReplyTokens(reply AgentReply) Int {\n\treturn Add(reply.usage.Input, reply.usage.Output)\n}\n\nfunc ReplyToolCalls(reply AgentReply) Int { return reply.toolCalls }\n\n// ReplyStopReason is why the turn ended: the provider's reason (end-turn, tool-use,\n// max-tokens, refusal, other) or the loop's own (aborted, budget-exceeded). A caller that\n// persists the transcript of an aborted turn should know it is persisting a partial one.\nfunc ReplyStopReason(reply AgentReply) string { return reply.stopReason }\n\n// \226\148\128\226\148\128 Transcript \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// AgentBlock is one piece of an assistant or tool turn. The variants are distinguished\n// by Kind rather than by a sum type because this shape is also the persisted JSON, and a\n// tagged struct round-trips through encoding/json without a custom unmarshaller.\ntype AgentBlock struct {\n\tKind    string          `json:\"kind\"`\n\tText    string          `json:\"text,omitempty\"`\n\tID      string          `json:\"id,omitempty\"`\n\tName    string          `json:\"name,omitempty\"`\n\tArgs    json.RawMessage `json:\"args,omitempty\"`\n\tResults []toolResult    `json:\"results,omitempty\"`\n}\n\n// AgentMessage is one turn of the transcript. A user turn carries Text; assistant and\n// tool turns carry Content blocks.\ntype AgentMessage struct {\n\tRole    string       `json:\"role\"`\n\tText    string       `json:\"text,omitempty\"`\n\tContent []AgentBlock `json:\"content,omitempty\"`\n}\n\nfunc userMessage(prompt string) AgentMessage {\n\treturn AgentMessage{Role: \"user\", Text: prompt}\n}\n\n// assistantMessage reconstructs the model's turn for the transcript: its text, then one\n// block per tool it asked for. An empty text with no tool calls produces no blocks, and\n// the caller drops the turn rather than recording an empty one.\nfunc assistantMessage(response LlmResponse) AgentMessage {\n\tblocks := make([]AgentBlock, 0, 1+len(response.ToolCalls))\n\tif response.Text != \"\" {\n\t\tblocks = append(blocks, AgentBlock{Kind: \"text\", Text: response.Text})\n\t}\n\tfor _, call := range response.ToolCalls {\n\t\tblocks = append(blocks, AgentBlock{\n\t\t\tKind: \"tool-use\", ID: call.ID, Name: call.Name, Args: call.Args,\n\t\t})\n\t}\n\treturn AgentMessage{Role: \"assistant\", Content: blocks}\n}\n\nfunc toolMessage(results []toolResult) AgentMessage {\n\treturn AgentMessage{\n\t\tRole:    \"tool\",\n\t\tContent: []AgentBlock{{Kind: \"tool-result\", Results: results}},\n\t}\n}\n\nfunc mergeUsage(into, from LlmUsage) LlmUsage {\n\treturn LlmUsage{\n\t\tInput:      Add(into.Input, from.Input),\n\t\tOutput:     Add(into.Output, from.Output),\n\t\tCacheRead:  Add(into.CacheRead, from.CacheRead),\n\t\tCacheWrite: Add(into.CacheWrite, from.CacheWrite),\n\t}\n}\n\n// \226\148\128\226\148\128 The loop \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// runLoop drives provider round-trips until the model stops asking for tools, and\n// answers the final reply plus the FULL transcript \226\128\148 the transcript is what a\n// conversation threads into its next turn.\n//\n// onStep, when non-nil, is called once per loop step: as each tool is dispatched, and\n// once with the final text. It never runs while a database connection is held.\n//\n// An aborted or over-budget turn is answered, not raised: the reply carries no text and a\n// stop reason of `aborted` or `budget-exceeded`, and the transcript holds every step that\n// completed \226\128\148 each tool_use paired with its tool_result \226\128\148 so a conversation persisted from\n// it is well-formed and the next turn can continue it. The step stream sees\n// \"aborted: <why>\" and then the closing \"text: \" a consumer waits for.\nfunc runLoop(agent Agent, provider LlmProvider, messages []AgentMessage,\n\tonStep func(string), streamTokens bool) (AgentReply, []AgentMessage) {\n\trequireDistinctToolNames(agent.Tools)\n\tif err := validateTranscript(messages); err != nil {\n\t\tpanic(\"Tesl.Agent: conversation rejected: \" + err.Error())\n\t}\n\tusage := LlmUsage{}\n\ttoolCalls := 0\n\ttoolResultBytes := 0\n\tstarted := time.Now()\n\tdeadline := millisDuration(agentTurnTimeoutMs())\n\tstep := func(event string) {\n\t\tif onStep != nil {\n\t\t\tonStep(event)\n\t\t}\n\t}\n\tendTurn := func(stopReason, why string) (AgentReply, []AgentMessage) {\n\t\tstep(\"aborted: \" + why)\n\t\tstep(\"text: \")\n\t\treturn AgentReply{\n\t\t\tusage:      usage,\n\t\t\ttoolCalls:  FromInt64(int64(toolCalls)),\n\t\t\tstopReason: stopReason,\n\t\t}, messages\n\t}\n\tfor iteration := 0; ; iteration++ {\n\t\tif iteration >= maxAgentIterations {\n\t\t\treturn endTurn(stopAborted, fmt.Sprintf(\n\t\t\t\t\"tool-calling loop exceeded %d iterations\", maxAgentIterations))\n\t\t}\n\t\tif elapsed := time.Since(started); elapsed > deadline {\n\t\t\treturn endTurn(stopBudgetExceeded, fmt.Sprintf(\n\t\t\t\t\"turn exceeded its %dms wall-clock budget (TESL_AI_TURN_TIMEOUT_MS)\",\n\t\t\t\tagentTurnTimeoutMs()))\n\t\t}\n\t\tif toolResultBytes > maxTurnToolResultBytes {\n\t\t\treturn endTurn(stopBudgetExceeded, fmt.Sprintf(\n\t\t\t\t\"tool results exceeded the turn's %d-byte budget\", maxTurnToolResultBytes))\n\t\t}\n\t\trequest := LlmRequest{\n\t\t\tSystem:    agent.SystemPrompt,\n\t\t\tMaxTokens: agent.MaxTokens,\n\t\t\tMessages:  messages,\n\t\t\tTools:     toolDecls(agent),\n\t\t}\n\t\tif onStep != nil && streamTokens {\n\t\t\trequest.OnDelta = func(partial string) { step(\"text-delta: \" + partial) }\n\t\t}\n\t\tresponse, timedOut := callProvider(provider, request)\n\t\tif timedOut != nil {\n\t\t\treturn endTurn(stopAborted, timedOut.Error())\n\t\t}\n\t\tusage = mergeUsage(usage, response.Usage)\n\t\tif len(response.ToolCalls) == 0 {\n\t\t\tif response.Text != \"\" {\n\t\t\t\tmessages = append(messages, assistantMessage(response))\n\t\t\t}\n\t\t\tstep(\"text: \" + response.Text)\n\t\t\treturn AgentReply{\n\t\t\t\tText:       response.Text,\n\t\t\t\tusage:      usage,\n\t\t\t\ttoolCalls:  FromInt64(int64(toolCalls)),\n\t\t\t\tstopReason: response.StopReason,\n\t\t\t}, messages\n\t\t}\n\t\tdispatched := response.ToolCalls\n\t\tif len(dispatched) > maxToolCallsPerStep {\n\t\t\tdispatched = dispatched[:maxToolCallsPerStep]\n\t\t}\n\t\tfor _, call := range dispatched {\n\t\t\tstep(\"tool: \" + call.Name)\n\t\t}\n\t\tresults := make([]toolResult, 0, len(response.ToolCalls))\n\t\t// The wall-clock budget is re-checked BEFORE EACH dispatch, not once per iteration:\n\t\t// a step of 32 slow tools would otherwise run to completion however far past the\n\t\t// budget it went (the whitebox campaign measured a 6\195\151 overshoot). A call that finds\n\t\t// the budget spent is answered as is_error, never run.\n\t\tran := 0\n\t\tfor _, call := range dispatched {\n\t\t\tif elapsed := time.Since(started); elapsed > deadline {\n\t\t\t\tbreak\n\t\t\t}\n\t\t\tresult := boundedToolResult(runToolCall(agent, call))\n\t\t\ttoolResultBytes += len(result.Content)\n\t\t\tresults = append(results, result)\n\t\t\tran++\n\t\t}\n\t\tfor _, call := range dispatched[ran:] {\n\t\t\tresults = append(results, refusedToolResult(call,\n\t\t\t\t\"turn budget exhausted before this tool call: not dispatched\"))\n\t\t}\n\t\tfor _, call := range response.ToolCalls[len(dispatched):] {\n\t\t\tresults = append(results, refusedToolResult(call, fmt.Sprintf(\n\t\t\t\t\"too many tool calls in one step (limit %d): not dispatched\", maxToolCallsPerStep)))\n\t\t}\n\t\tmessages = append(messages, assistantMessage(response), toolMessage(results))\n\t\ttoolCalls += len(dispatched)\n\t}\n}\n\n// callProvider runs one round-trip, reporting a provider TIMEOUT as a value and letting every\n// other failure propagate. Only the timeout is the loop's to absorb: the turn so far is\n// intact and worth answering. A mock's exhaustion trap, a 401, a non-JSON body are bugs the\n// caller must see.\nfunc callProvider(provider LlmProvider, request LlmRequest) (response LlmResponse, timedOut error) {\n\tdefer func() {\n\t\traised := recover()\n\t\tif raised == nil {\n\t\t\treturn\n\t\t}\n\t\tvar timeout providerTimeout\n\t\tif err, isError := raised.(error); isError && errors.As(err, &timeout) {\n\t\t\tresponse, timedOut = LlmResponse{}, timeout\n\t\t\treturn\n\t\t}\n\t\tpanic(raised)\n\t}()\n\treturn provider.call(request), nil\n}\n\n// toolDecls renders the agent's tools as the provider sees them. A tool whose schema is\n// not parseable JSON is still offered, described as an open object \226\128\148 the schema is model\n// GUIDANCE, and the validator remains authoritative either way.\nfunc toolDecls(agent Agent) []LlmToolDecl {\n\tif len(agent.Tools) == 0 {\n\t\treturn nil\n\t}\n\tdecls := make([]LlmToolDecl, 0, len(agent.Tools))\n\tfor _, tool := range agent.Tools {\n\t\tschema := json.RawMessage(tool.Schema)\n\t\tif !json.Valid(schema) {\n\t\t\tschema = json.RawMessage(`{\"type\":\"object\"}`)\n\t\t}\n\t\tdecls = append(decls, LlmToolDecl{\n\t\t\tName: tool.Name, Description: tool.Description, Schema: schema,\n\t\t})\n\t}\n\treturn decls\n}\n\n// \226\148\128\226\148\128 Inference entry points \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// Ask runs the full loop and answers the final text. A tool-augmented agent still works\n// through it; the tools just do not show up in the answer.\nfunc Ask(agent Agent, prompt string) string {\n\treturn AskReply(agent, prompt).Text\n}\n\n// AskReply runs the full loop and answers text, usage, and tool count.\nfunc AskReply(agent Agent, prompt string) AgentReply {\n\treply, _ := runLoop(agent, agent.Provider, []AgentMessage{userMessage(prompt)}, nil, false)\n\treturn reply\n}\n\n// AskWith overrides the provider for THIS call only \226\128\148 the BYOK path. The agent's own\n// binding, its system prompt, and its tools are untouched.\nfunc AskWith(agent Agent, prompt string, provider LlmProvider) AgentReply {\n\treply, _ := runLoop(agent, provider, []AgentMessage{userMessage(prompt)}, nil, false)\n\treturn reply\n}\n\n// AgentPublisher is a Tesl `String -> Unit`. The empty struct is what Unit erases to, so\n// this is the type an emitted lambda and an emitted `fn \226\128\166 -> Unit` both already have \226\128\148\n// naming it here is what lets either be passed straight through with no adapter.\ntype AgentPublisher = func(string) struct{}\n\n// stepCallback adapts a Tesl publisher to the loop's own callback, discarding the Unit.\nfunc stepCallback(publisher AgentPublisher) func(string) {\n\treturn func(event string) { _ = publisher(event) }\n}\n\n// AgentRun runs the loop to completion, calling publisher once per step. It is what a\n// worker job body calls: the publisher closes over a channel publish, so the SAME\n// channel/SSE path streams the agent's progress.\nfunc AgentRun(agent Agent, prompt string, publisher AgentPublisher) AgentReply {\n\tif publisher == nil {\n\t\tpanic(\"agentRun: publisher must be a function String -> Unit\")\n\t}\n\treply, _ := runLoop(agent, agent.Provider,\n\t\t[]AgentMessage{userMessage(prompt)}, stepCallback(publisher), false)\n\treturn reply\n}\n\n// AskFor asks for a typed value: run the loop, hand the final text to decode, and on\n// failure append the error to the prompt and re-ask, up to maxRetries extra times.\n//\n// decode reports failure by trapping \226\128\148 which is what a codec decode does \226\128\148 so the retry\n// is driven by recovering it here rather than by a second error channel the emitted\n// decoder would have to thread.\nfunc AskFor[A any](agent Agent, prompt string, decode func(string) A, maxRetries Int) A {\n\tretries, exact := maxRetries.Int64()\n\tif !exact || retries < 0 {\n\t\tretries = 0\n\t}\n\tattempt := prompt\n\tfor left := retries; ; left-- {\n\t\treply := AskReply(agent, attempt)\n\t\t// An aborted turn has no text to decode, and re-asking would spend the same budget\n\t\t// again for the same reason. There is no partial value to answer, so this is a trap.\n\t\tif reply.stopReason == stopAborted || reply.stopReason == stopBudgetExceeded {\n\t\t\tpanic(\"askFor: the turn ended without a reply (\" + reply.stopReason + \")\")\n\t\t}\n\t\tdecoded, failure := recovered(func() any { return decode(reply.Text) })\n\t\tif failure == \"\" {\n\t\t\ttyped, ok := decoded.(A)\n\t\t\tif !ok {\n\t\t\t\tpanic(\"askFor: decoder returned an unexpected type\")\n\t\t\t}\n\t\t\treturn typed\n\t\t}\n\t\tif left <= 0 {\n\t\t\tplural := \"ies\"\n\t\t\tif retries == 1 {\n\t\t\t\tplural = \"y\"\n\t\t\t}\n\t\t\tpanic(fmt.Sprintf(\"askFor: structured output did not decode after %d retr%s: %s\",\n\t\t\t\tretries, plural, failure))\n\t\t}\n\t\tattempt = prompt +\n\t\t\t\"\\n\\nYour previous reply could not be parsed: \" + failure +\n\t\t\t\"\\nReturn ONLY valid JSON matching the requested shape.\"\n\t}\n}\n\n// \226\148\128\226\148\128 Conversation \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// Conversation is an agent bound to the transcript so far. Turn N sees turns 1..N-1\n// because Converse threads the whole transcript into the loop.\ntype Conversation struct {\n\tagent    Agent\n\tmessages []AgentMessage\n}\n\n// ConversationTurn is one turn's outcome: the reply, and the conversation advanced by\n// this turn for the caller to thread into the next one.\ntype ConversationTurn struct {\n\treply        AgentReply\n\tconversation Conversation\n}\n\nfunc NewConversation(agent Agent) Conversation {\n\treturn Conversation{agent: agent}\n}\n\nfunc Converse(conversation Conversation, prompt string) ConversationTurn {\n\treturn converseWith(conversation, prompt, nil, false)\n}\n\n// ConverseStreaming is Converse with progress: publish is called with \"tool: <name>\" as\n// each tool fires, \"text-delta: <part>\" as the model generates, and \"text: <reply>\" once\n// the turn completes. A consumer that only reads \"text:\" keeps working \226\128\148 it ignores the\n// prefixes it does not know.\nfunc ConverseStreaming(conversation Conversation, prompt string,\n\tpublish AgentPublisher) ConversationTurn {\n\tif publish == nil {\n\t\tpanic(\"converseStreaming: third argument must be a function String -> Unit\")\n\t}\n\treturn converseWith(conversation, prompt, stepCallback(publish), true)\n}\n\nfunc converseWith(conversation Conversation, prompt string,\n\tonStep func(string), streamTokens bool) ConversationTurn {\n\thistory := make([]AgentMessage, 0, len(conversation.messages)+2)\n\thistory = append(history, conversation.messages...)\n\thistory = append(history, userMessage(prompt))\n\treply, transcript := runLoop(conversation.agent, conversation.agent.Provider,\n\t\thistory, onStep, streamTokens)\n\treturn ConversationTurn{\n\t\treply:        reply,\n\t\tconversation: Conversation{agent: conversation.agent, messages: transcript},\n\t}\n}\n\nfunc TurnReply(turn ConversationTurn) AgentReply { return turn.reply }\n\nfunc TurnConversation(turn ConversationTurn) Conversation { return turn.conversation }\n\nfunc ConversationLength(conversation Conversation) Int {\n\treturn FromInt64(int64(len(conversation.messages)))\n}\n\n// ConversationJSON serialises the transcript for the program to persist. The shape is\n// this runtime's own \226\128\148 ConversationFrom is its only reader \226\128\148 but it is deliberately\n// legible: the prompts and replies appear as themselves, so a stored row can be read.\n//\n// The shape is versioned: `{\"v\":1,\"messages\":[\226\128\166]}`. The version is what lets a later\n// runtime read a row this one wrote and know which rules it was written under; the bare\n// array the first Go runtime wrote is read as v1, because it IS v1 \226\128\148 the same messages,\n// validated by the same rules.\nfunc ConversationJSON(conversation Conversation) string {\n\tmessages := conversation.messages\n\tif messages == nil {\n\t\tmessages = []AgentMessage{}\n\t}\n\tencoded, err := json.Marshal(conversationEnvelope{Version: conversationVersion, Messages: messages})\n\tif err != nil {\n\t\tpanic(\"conversationJson: history could not be serialized: \" + err.Error())\n\t}\n\treturn string(encoded)\n}\n\nconst conversationVersion = 1\n\ntype conversationEnvelope struct {\n\tVersion  int            `json:\"v\"`\n\tMessages []AgentMessage `json:\"messages\"`\n}\n\n// A persisted transcript is INPUT. The program stores it and reads it back, typically one\n// row per user, and whoever can write that row \226\128\148 a DB-write bug elsewhere, an import\n// feature, a shared table \226\128\148 would otherwise write straight into the model's context: a\n// stored `{\"role\":\"system\"}` became a second system message on the OpenAI wire, an unknown\n// block kind trapped in the Anthropic renderer on every later turn, and there was no size\n// bound at all. So the decode is a validation, and the renderers may assume its outcome.\nconst (\n\tmaxConversationBytes    = 16 * 1024 * 1024\n\tmaxConversationMessages = 10000\n)\n\n// ConversationFrom restores a transcript previously produced by ConversationJSON and\n// binds it to agent. A history that is not one this runtime could have written is refused\n// here, at the boundary, with a message naming what was wrong \226\128\148 not later, inside a\n// provider renderer.\nfunc ConversationFrom(agent Agent, history string) Conversation {\n\tif strings.TrimSpace(history) == \"\" {\n\t\treturn Conversation{agent: agent}\n\t}\n\tmessages, err := decodeConversationHistory(history)\n\tif err != nil {\n\t\tpanic(\"conversationFrom: \" + err.Error())\n\t}\n\treturn Conversation{agent: agent, messages: messages}\n}\n\nfunc decodeConversationHistory(history string) ([]AgentMessage, error) {\n\tif len(history) > maxConversationBytes {\n\t\treturn nil, fmt.Errorf(\"history of %d bytes exceeds the %d-byte limit\",\n\t\t\tlen(history), maxConversationBytes)\n\t}\n\ttrimmed := strings.TrimSpace(history)\n\tvar messages []AgentMessage\n\tif strings.HasPrefix(trimmed, \"[\") {\n\t\t// The unversioned shape of the first Go runtime: a bare message array, read as v1.\n\t\tif err := json.Unmarshal([]byte(trimmed), &messages); err != nil {\n\t\t\treturn nil, errors.New(\"history is not valid JSON: \" + err.Error())\n\t\t}\n\t} else {\n\t\tvar envelope conversationEnvelope\n\t\tif err := json.Unmarshal([]byte(trimmed), &envelope); err != nil {\n\t\t\treturn nil, errors.New(\"history is not valid JSON: \" + err.Error())\n\t\t}\n\t\tif envelope.Version != conversationVersion {\n\t\t\treturn nil, fmt.Errorf(\"history version %d is not supported (this runtime reads v%d)\",\n\t\t\t\tenvelope.Version, conversationVersion)\n\t\t}\n\t\tmessages = envelope.Messages\n\t}\n\tif err := validateTranscript(messages); err != nil {\n\t\treturn nil, err\n\t}\n\treturn messages, nil\n}\n\n// validateTranscript admits exactly the messages the loop itself produces \226\128\148 the roles it\n// writes, the block kinds it writes, each kind under the role it writes it under \226\128\148 and\n// nothing else. The renderers in agent_provider.go rely on this: a kind not listed here\n// never reaches them.\nfunc validateTranscript(messages []AgentMessage) error {\n\tif len(messages) > maxConversationMessages {\n\t\treturn fmt.Errorf(\"history of %d messages exceeds the %d-message limit\",\n\t\t\tlen(messages), maxConversationMessages)\n\t}\n\tfor index, message := range messages {\n\t\twhere := fmt.Sprintf(\"message %d\", index)\n\t\tswitch message.Role {\n\t\tcase \"user\":\n\t\t\tif len(message.Content) != 0 {\n\t\t\t\treturn errors.New(where + \": a user turn carries text, not content blocks\")\n\t\t\t}\n\t\tcase \"assistant\":\n\t\t\tfor _, block := range message.Content {\n\t\t\t\tswitch block.Kind {\n\t\t\t\tcase \"text\", \"tool-use\":\n\t\t\t\tcase \"tool-result\":\n\t\t\t\t\treturn errors.New(where + \": a tool-result block belongs to a tool turn, not an assistant turn\")\n\t\t\t\tdefault:\n\t\t\t\t\treturn fmt.Errorf(\"%s: unknown content block kind %q\", where, block.Kind)\n\t\t\t\t}\n\t\t\t}\n\t\tcase \"tool\":\n\t\t\tif len(message.Content) == 0 {\n\t\t\t\treturn errors.New(where + \": a tool turn carries tool-result blocks\")\n\t\t\t}\n\t\t\tfor _, block := range message.Content {\n\t\t\t\tif block.Kind != \"tool-result\" {\n\t\t\t\t\treturn fmt.Errorf(\"%s: a tool turn may only carry tool-result blocks, not %q\",\n\t\t\t\t\t\twhere, block.Kind)\n\t\t\t\t}\n\t\t\t}\n\t\tdefault:\n\t\t\treturn fmt.Errorf(\"%s: role %q is not one this runtime writes (user, assistant, tool)\",\n\t\t\t\twhere, message.Role)\n\t\t}\n\t}\n\treturn nil\n}\n\n// \226\148\128\226\148\128 Typed decoding at the model boundary \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// Everything a model produces is UNTRUSTED text. The two entry points below are where it\n// becomes a typed value, and both go through the program's own codec \226\128\148 the same decode an\n// HTTP request body gets \226\128\148 so a proof a type carries is established here or not at all.\n// Neither returns an error: a failure TRAPS, which is what lets AskFor retry and what\n// turns a bad tool argument into an is_error result the model reads.\n\n// DecodeAs decodes a JSON string as the named type. typeName appears only in the failure\n// message; which decoder runs was decided at compile time, from the literal type name at\n// the call site.\nfunc DecodeAs[T any](typeName, jsonText string, decode func(any) Check[T]) T {\n\t// ParseJSON, not json.Unmarshal: it reads numbers as json.Number, which is what an\n\t// arbitrary-precision Int decodes from. Unmarshalling into `any` would hand the codec a\n\t// float64 and quietly round anything above 2^53 \226\128\148 the same reason the HTTP body path\n\t// goes through it.\n\traw, err := ParseJSON([]byte(jsonText))\n\tif err != nil {\n\t\tpanic(\"decodeAs: not valid JSON: \" + err.Error())\n\t}\n\tresult := decode(raw)\n\tvalue, ok := result.Value()\n\tif !ok {\n\t\tpanic(\"decodeAs: decoded value failed validation: \" + result.Message())\n\t}\n\t_ = typeName\n\treturn value\n}\n\n// ToolArguments parses a tool call's argument JSON into its fields. A payload that is not\n// a JSON object is a trap: the schema asked for an object, and reading a scalar as one\n// would silently give every argument its zero value.\nfunc ToolArguments(argsJSON string) map[string]any {\n\t// Through ParseJSON for the reason DecodeAs is: an Int-typed tool parameter reads its\n\t// digits, and a float64 would round the large ones.\n\tparsed, err := ParseJSON([]byte(argsJSON))\n\tif err != nil {\n\t\tpanic(\"tool: arguments were not valid JSON: \" + err.Error())\n\t}\n\tfields, ok := parsed.(map[string]any)\n\tif !ok {\n\t\tpanic(\"tool: expected a JSON object of arguments\")\n\t}\n\treturn fields\n}\n\nfunc toolArgValue(fields map[string]any, name string) any {\n\tvalue, present := fields[name]\n\tif !present {\n\t\tpanic(\"tool: missing required argument: \" + name)\n\t}\n\treturn value\n}\n\nfunc ToolArgString(fields map[string]any, name string) string {\n\ttext, err := DecodeStringValue(toolArgValue(fields, name))\n\tif err != nil {\n\t\tpanic(\"tool: argument \" + name + \" must be a string\")\n\t}\n\treturn text\n}\n\n// ToolArgInt refuses a fractional number rather than truncating it. A model that answered\n// 2.5 for a count did not mean 2, and silently agreeing with it is how a wrong quantity\n// reaches a tool body. DecodeIntValue is the same reader a codec uses, so the digits \226\128\148 not\n// a float64 \226\128\148 are what the value comes from.\nfunc ToolArgInt(fields map[string]any, name string) Int {\n\tvalue, err := DecodeIntValue(toolArgValue(fields, name))\n\tif err != nil {\n\t\tpanic(\"tool: argument \" + name + \" must be an integer\")\n\t}\n\treturn value\n}\n\nfunc ToolArgFloat(fields map[string]any, name string) float64 {\n\tnumber, err := DecodeFloatValue(toolArgValue(fields, name))\n\tif err != nil {\n\t\tpanic(\"tool: argument \" + name + \" must be a number\")\n\t}\n\treturn number\n}\n\nfunc ToolArgBool(fields map[string]any, name string) bool {\n\tvalue, err := DecodeBoolValue(toolArgValue(fields, name))\n\tif err != nil {\n\t\tpanic(\"tool: argument \" + name + \" must be a boolean\")\n\t}\n\treturn value\n}\n\n// ToolArgPosixMillis reads the epoch-millisecond integer the schema describes. The\n// description is what keeps a model from sending seconds or a formatted date; this is\n// what refuses one that did anyway.\nfunc ToolArgPosixMillis(fields map[string]any, name string) PosixMillis {\n\treturn PosixMillis{Value: ToolArgInt(fields, name)}\n}\n\n// ToolArgMoney reads `{minorUnits, currency}`. Extra keys are tolerated \226\128\148 a model that\n// echoes back the enriched `display` field a Money tool RESULT carries is being helpful,\n// not wrong \226\128\148 but minor units are never inferred from a major-unit amount.\nfunc ToolArgMoney(fields map[string]any, name string) Money {\n\tobject, ok := toolArgValue(fields, name).(map[string]any)\n\tif !ok {\n\t\tpanic(\"tool: argument \" + name + \" must be an object {minorUnits, currency}\")\n\t}\n\tminorUnits, present := object[\"minorUnits\"]\n\tif !present {\n\t\tpanic(\"tool: argument \" + name + \" is missing minorUnits\")\n\t}\n\tunits, err := DecodeIntValue(minorUnits)\n\tif err != nil {\n\t\tpanic(\"tool: argument \" + name + \" must have integer minorUnits\")\n\t}\n\tcode, present := object[\"currency\"]\n\tif !present {\n\t\tpanic(\"tool: argument \" + name + \" is missing currency\")\n\t}\n\ttext, isText := code.(string)\n\tif !isText {\n\t\tpanic(\"tool: argument \" + name + \" has unknown currency code\")\n\t}\n\tcurrency, known := CurrencyFromCode(text).Value()\n\tif !known {\n\t\tpanic(\"tool: argument \" + name + \" has unknown currency code: \" + text)\n\t}\n\treturn Money{MinorUnits: units, Currency: currency}\n}\n\n// ToolDispatchWith captures a tool dispatch's leading argument, leaving the model to supply\n// only the validated one. A partial application in the surface \226\128\148 `tool \226\128\166 validateSpec\n// (dispatchReport conversationId)` \226\128\148 is what makes a tool PER-TURN: the captured value is\n// the program's, so the model chooses what the report is about and cannot choose whose\n// conversation it lands in.\nfunc ToolDispatchWith[Captured, Argument any](\n\tdispatch func(Captured, Argument) string, captured Captured) func(Argument) string {\n\treturn func(argument Argument) string { return dispatch(captured, argument) }\n}\n");
  ("agent_endpoint.go", "package teslrt\n\nimport (\n\t\"crypto/rand\"\n\t\"encoding/hex\"\n\t\"fmt\"\n)\n\n// Server endpoints as agent tools \226\128\148 the runtime half of `serverTools` and `humanActions`.\n//\n// `serverTools MyServer user` produces one tool per endpoint the user's proof covers, and\n// each of those tools IS the endpoint: the same handler, called with the same authenticated\n// user, so every ownership and authorization check in the handler body runs unchanged. What\n// the emitter generates per endpoint is the argument decode and the call; what lives here is\n// what both need to behave like the HTTP boundary \226\128\148 a rejection reaching the model as an\n// is_error result rather than as a crash.\n//\n// `humanActions MyServer user` is the complement: one INERT tool per endpoint the user's\n// proof does NOT cover. It is inert by construction \226\128\148 HumanActions takes the server's NAME,\n// never the server, so there is no path from a request descriptor back to a handler.\n\n// ToolArgDecoded reads one argument through a type's own codec \226\128\148 the same decode an HTTP\n// request body goes through, so a tool argument can never be validated more weakly than the\n// endpoint's boundary.\nfunc ToolArgDecoded[T any](fields map[string]any, name string, decode func(any) Check[T]) T {\n\treturn ToolChecked(name, decode(toolArgValue(fields, name)))\n}\n\n// ToolChecked unwraps a check on a tool argument, reporting a rejection with the check's own\n// message. The message reaches the MODEL as the is_error result, which is what lets it\n// correct the argument and try again.\nfunc ToolChecked[T any](name string, result Check[T]) T {\n\tvalue, ok := result.Value()\n\tif !ok {\n\t\tpanic(fmt.Sprintf(\"argument %s: %s\", name, result.Message()))\n\t}\n\treturn value\n}\n\n// ToolRejection is deferred by an emitted endpoint dispatch. A handler that rejects answers\n// the HTTP client with a status; called as a tool it has no response to write, so the\n// rejection becomes the tool_result text \226\128\148 carrying the status, because \"not found (HTTP\n// 404)\" tells the model something \"not found\" alone does not.\n//\n// Anything else re-panics unchanged: the agent loop already contains a trapping tool body as\n// an is_error result, and rewriting the message here would only hide where it came from.\nfunc ToolRejection() {\n\traised := recover()\n\tif raised == nil {\n\t\treturn\n\t}\n\tif rejection, ok := raised.(RequestRejection); ok {\n\t\tpanic(fmt.Sprintf(\"%s (HTTP %d)\", rejection.Message, rejection.Status))\n\t}\n\tpanic(raised)\n}\n\n// HumanActionSpec is one endpoint the agent may NOT perform, as the human sees it.\ntype HumanActionSpec struct {\n\tName        string\n\tDescription string\n\tSchema      string\n}\n\nfunc HumanActionOf(name, description, schema string) HumanActionSpec {\n\treturn HumanActionSpec{Name: name, Description: description, Schema: schema}\n}\n\n// humanActionSuffix is appended to every human action's description. The model has to be\n// told what calling the tool does, or it reports the action as done.\nconst humanActionSuffix = \"  (You cannot perform this action yourself. Calling this tool\" +\n\t\" asks the human to perform it via a button in their app; you will be told the result\" +\n\t\" in a later turn.)\"\n\n// HumanActions builds one inert tool per excluded endpoint.\n//\n// The server NAME is what it takes, and all it takes: with no route table and no handler in\n// reach, there is no in-process path from a request descriptor back to a call. The agent\n// chooses WHICH excluded action to ask for and prefills its arguments; the human's browser\n// resolves the action tag to a real URL from generated client code and performs the call\n// under their own session, where the endpoint re-checks auth. So the agent can neither\n// fabricate an action, relabel it, redirect it, nor perform it.\nfunc HumanActions(serverName string, actions []HumanActionSpec) []Tool {\n\ttools := make([]Tool, 0, len(actions))\n\tfor _, action := range actions {\n\t\tname := action.Name\n\t\ttools = append(tools, ToolOf(name, action.Description+humanActionSuffix, action.Schema,\n\t\t\t// The prefill is advisory: the human confirms the arguments and the real\n\t\t\t// endpoint re-validates them. Well-formedness is all that is checked, so the\n\t\t\t// request can be displayed.\n\t\t\tToolArguments,\n\t\t\tfunc(prefill map[string]any) string {\n\t\t\t\treturn humanActionRequest(serverName, name, prefill)\n\t\t\t}))\n\t}\n\treturn tools\n}\n\nfunc humanActionRequest(serverName, action string, prefill map[string]any) string {\n\treturn EncodeJSON(map[string]any{\n\t\t\"kind\":   \"human-action-request\",\n\t\t\"server\": serverName,\n\t\t\"action\": action,\n\t\t\"args\":   prefill,\n\t\t// An unguessable handle correlates the request with the result the human's\n\t\t// completed action produces, so it can re-enter the loop as a later turn.\n\t\t\"handle\": freshActionHandle(),\n\t})\n}\n\nfunc freshActionHandle() string {\n\traw := make([]byte, 16)\n\tif _, err := rand.Read(raw); err != nil {\n\t\tpanic(\"humanAction: could not generate a correlation handle: \" + err.Error())\n\t}\n\treturn hex.EncodeToString(raw)\n}\n");
  ("agent_provider.go", "package teslrt\n\nimport (\n\t\"encoding/json\"\n\t\"fmt\"\n\t\"io\"\n\t\"net/http\"\n\t\"strconv\"\n\t\"strings\"\n\t\"time\"\n)\n\n// The real LLM providers.\n//\n// Each one is a translation layer and nothing more: it renders the normalised request\n// (agent.go) into a vendor's wire format, posts it through providerHTTPPost \226\128\148 the outbound\n// path of httpclient.go under the provider's own deadline, so the network is gated by\n// `httpClient`, judged by the SSRF containment, and interceptable by the same `stubHttp`\n// double every other outbound call is \226\128\148 and normalises the answer back. The agent loop\n// never learns which vendor it is talking to.\n//\n// TOKEN STREAMING is not implemented against a real provider yet. `converseStreaming` and\n// `agentRun` still publish every event they promise, in order, and a mock provider still\n// synthesizes per-word deltas; what a real provider does not do here is emit `text-delta:`\n// AS the model generates. The reply arrives complete and is published as one delta, so a UI\n// renders the answer in one step instead of typing it out. Nothing is lost but the\n// incremental rendering, and closing it needs a streaming HTTP body in the runtime, which\n// httpclient.go does not have yet.\n\nconst anthropicVersion = \"2023-06-01\"\n\nconst (\n\tanthropicEndpoint = \"https://api.anthropic.com/v1/messages\"\n\topenaiEndpoint    = \"https://api.openai.com/v1/chat/completions\"\n\tmistralEndpoint   = \"https://api.mistral.ai/v1/chat/completions\"\n)\n\n// AnthropicProvider talks to the Messages API.\nfunc AnthropicProvider(apiKey, model string) LlmProvider {\n\treturn ProviderOf(func(request LlmRequest) LlmResponse {\n\t\theaders := []Tuple2[string, string]{\n\t\t\t{Tuple2First: \"x-api-key\", Tuple2Second: apiKey},\n\t\t\t{Tuple2First: \"anthropic-version\", Tuple2Second: anthropicVersion},\n\t\t\t{Tuple2First: \"content-type\", Tuple2Second: \"application/json\"},\n\t\t}\n\t\tbody := anthropicRequest{\n\t\t\tModel:     model,\n\t\t\tMaxTokens: providerMaxTokens(request),\n\t\t\tSystem:    request.System,\n\t\t\tMessages:  anthropicMessages(request.Messages),\n\t\t\tTools:     anthropicTools(request.Tools),\n\t\t}\n\t\tanswer := providerPost(\"anthropic\", anthropicEndpoint, headers, body)\n\t\tvar decoded anthropicResponse\n\t\tproviderDecode(\"anthropic\", answer, &decoded)\n\t\treturn anthropicNormalize(decoded, request)\n\t})\n}\n\n// OpenAIProvider talks to the Chat Completions API.\nfunc OpenAIProvider(apiKey, model string) LlmProvider {\n\treturn openAIWireProvider(apiKey, model, openaiEndpoint)\n}\n\n// MistralProvider speaks the OpenAI chat-completions format at Mistral's endpoint, which is\n// what Mistral serves \226\128\148 the only difference is where it is posted.\nfunc MistralProvider(apiKey, model string) LlmProvider {\n\treturn openAIWireProvider(apiKey, model, mistralEndpoint)\n}\n\n// LocalProvider is the escape hatch for a self-hosted OpenAI-compatible server \226\128\148 llama.cpp,\n// vLLM, Ollama's /v1. The endpoint is the program's to name, so no default applies.\nfunc LocalProvider(endpoint, model string) LlmProvider {\n\treturn openAIWireProvider(\"\", model, endpoint)\n}\n\nfunc openAIWireProvider(apiKey, model, endpoint string) LlmProvider {\n\treturn ProviderOf(func(request LlmRequest) LlmResponse {\n\t\theaders := []Tuple2[string, string]{\n\t\t\t{Tuple2First: \"content-type\", Tuple2Second: \"application/json\"},\n\t\t}\n\t\t// A local server usually wants no credential at all; sending an empty Bearer\n\t\t// would be a header it has to ignore.\n\t\tif apiKey != \"\" {\n\t\t\theaders = append(headers,\n\t\t\t\tTuple2[string, string]{Tuple2First: \"authorization\", Tuple2Second: \"Bearer \" + apiKey})\n\t\t}\n\t\tbody := openaiRequest{\n\t\t\tModel:     model,\n\t\t\tMaxTokens: providerMaxTokens(request),\n\t\t\tMessages:  openaiMessages(request.System, request.Messages),\n\t\t\tTools:     openaiTools(request.Tools),\n\t\t}\n\t\tanswer := providerPost(\"openai\", endpoint, headers, body)\n\t\tvar decoded openaiResponse\n\t\tproviderDecode(\"openai\", answer, &decoded)\n\t\treturn openaiNormalize(decoded, request)\n\t})\n}\n\n// \226\148\128\226\148\128 Shared plumbing \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// providerMaxTokens defaults the budget the way the Racket runtime does, so an agent built\n// without one is not a request with `max_tokens: 0`.\nfunc providerMaxTokens(request LlmRequest) int64 {\n\tvalue, exact := request.MaxTokens.Int64()\n\tif !exact || value <= 0 {\n\t\treturn 1024\n\t}\n\treturn value\n}\n\n// \226\148\128\226\148\128 The provider round-trip \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// An LLM call is not an ordinary outbound call. A Messages API response of a few thousand\n// tokens routinely takes longer than TESL_HTTP_TIMEOUT_MS (30 s), and raising that knob for\n// the model would widen the deadline of every other egress in the program. So the provider\n// path has its own deadline, TESL_AI_TIMEOUT_MS (default 120000), and reaches the network\n// through the SAME pieces httpclient.go's verbs use \226\128\148 URL parsing, the CR/LF header guard,\n// the `stubHttp` double, the per-host transport that carries the SSRF egress judgement and\n// the TLS policy, and the response-body cap. Only the deadline differs; nothing about what\n// the call may reach does.\n//\n// A 429 or a 5xx is retried a bounded number of times with backoff: the API is stateless,\n// so a repeated request has no side effect, and a transient upstream fault should not end\n// a turn that already ran tools. A 4xx other than 429 is not retried \226\128\148 it is the request\n// that is wrong, and the same request will be wrong again.\n\nfunc aiTimeoutMs() int { return envPositiveInt(\"TESL_AI_TIMEOUT_MS\", 120000) }\n\n// providerAttempts is the total number of tries for one round-trip: the first call and\n// two retries.\nconst providerAttempts = 3\n\n// providerRetryBackoff is the pause before retry number `retry` (1-based). A variable so the\n// runtime's tests can run the retry path without sleeping through it.\nvar providerRetryBackoff = func(retry int) time.Duration {\n\treturn time.Duration(retry) * 500 * time.Millisecond\n}\n\n// maxProviderErrorBytes bounds how much of an upstream error body is echoed into the trap.\n// The whole body \226\128\148 up to the 10 MiB response cap \226\128\148 went into logs, telemetry, and, when the\n// agent was itself a tool, back into another model's context.\nconst maxProviderErrorBytes = 2048\n\nfunc providerPost(who, endpoint string, headers []Tuple2[string, string], body any) string {\n\tencoded, err := json.Marshal(body)\n\tif err != nil {\n\t\tpanic(who + \": request could not be encoded: \" + err.Error())\n\t}\n\tfor attempt := 1; ; attempt++ {\n\t\tresponse := providerHTTPPost(who, endpoint, headers, string(encoded))\n\t\tstatus, exact := response.Status.Int64()\n\t\tif exact && status < 400 {\n\t\t\treturn response.Body\n\t\t}\n\t\tretryable := exact && (status == http.StatusTooManyRequests || status >= 500)\n\t\tif retryable && attempt < providerAttempts {\n\t\t\ttime.Sleep(providerRetryBackoff(attempt))\n\t\t\tcontinue\n\t\t}\n\t\tattempts := \"\"\n\t\tif attempt > 1 {\n\t\t\tattempts = fmt.Sprintf(\" after %d attempts\", attempt)\n\t\t}\n\t\tpanic(fmt.Sprintf(\"%s: API error (HTTP %s)%s: %s\", who, response.Status.String(), attempts,\n\t\t\tproviderErrorDetail(response.Body)))\n\t}\n}\n\n// providerErrorDetail is what a failed call reports about the upstream body: the vendor's\n// own `error.message` when the body has one (every provider here wraps errors that way),\n// otherwise the body itself, cut to maxProviderErrorBytes.\nfunc providerErrorDetail(body string) string {\n\tvar envelope struct {\n\t\tError json.RawMessage `json:\"error\"`\n\t}\n\tif json.Unmarshal([]byte(body), &envelope) == nil && len(envelope.Error) > 0 {\n\t\tvar structured struct {\n\t\t\tMessage string `json:\"message\"`\n\t\t}\n\t\tif json.Unmarshal(envelope.Error, &structured) == nil && structured.Message != \"\" {\n\t\t\treturn truncateProviderText(structured.Message)\n\t\t}\n\t\tvar plain string\n\t\tif json.Unmarshal(envelope.Error, &plain) == nil && plain != \"\" {\n\t\t\treturn truncateProviderText(plain)\n\t\t}\n\t}\n\treturn truncateProviderText(body)\n}\n\nfunc truncateProviderText(text string) string {\n\tif len(text) <= maxProviderErrorBytes {\n\t\treturn text\n\t}\n\treturn text[:maxProviderErrorBytes] + fmt.Sprintf(\"\226\128\166 (%d bytes truncated)\",\n\t\tlen(text)-maxProviderErrorBytes)\n}\n\n// providerHTTPPost is one POST to the provider under the AI deadline. It mirrors\n// httpRequest/httpRequestNetwork step for step so the two cannot drift in what they permit;\n// the one thing it does differently is the client timeout.\nfunc providerHTTPPost(who, endpoint string, headers []Tuple2[string, string], body string) HttpResponse {\n\tparsed := parseOutboundURL(endpoint)\n\twire, secretHeaders := outboundHeaders(headers)\n\tif answer, stubbed := stubbedProviderAnswer(who, endpoint, body); stubbed {\n\t\treturn answer\n\t}\n\trequest, err := http.NewRequest(http.MethodPost, endpoint, strings.NewReader(body))\n\tif err != nil {\n\t\tpanic(fmt.Sprintf(\"%s: HTTP POST to %s failed: %s\", who, endpoint, err.Error()))\n\t}\n\trequest.Header = wire\n\tif telemetryTraceEnabled() && request.Header.Get(\"traceparent\") == \"\" {\n\t\trequest.Header.Set(\"traceparent\", \"00-\"+telemetryID(16)+\"-\"+telemetryID(8)+\"-01\")\n\t}\n\tclient := &http.Client{\n\t\tTransport: outboundTransport(parsed.Hostname()),\n\t\tTimeout:   millisDuration(aiTimeoutMs()),\n\t\t// A vendor endpoint is a fixed URL and the API key rides in its headers, so no\n\t\t// redirect is followed at all \226\128\148 the same policy the SSO legs use.\n\t\tCheckRedirect: redirectCheck(redirectRefused, parsed, secretHeaders),\n\t}\n\tresponse, err := client.Do(request)\n\tif err != nil {\n\t\t// A connect timeout counts too: a vendor that cannot be reached and one that never\n\t\t// finishes answering leave the turn in the same state, worth answering as `aborted`.\n\t\tif isTimeout(err) {\n\t\t\tpanic(providerTimeout{who: who, millis: aiTimeoutMs()})\n\t\t}\n\t\tpanic(who + \": \" + strings.TrimPrefix(requestFailure(http.MethodPost, endpoint, err), \"HttpClient: \"))\n\t}\n\tif response == nil {\n\t\tpanic(fmt.Sprintf(\"%s: HTTP POST to %s failed: no response\", who, endpoint))\n\t}\n\tdefer func() { _ = response.Body.Close() }()\n\tlimit := httpMaxResponseBytes()\n\traw, err := io.ReadAll(io.LimitReader(response.Body, int64(limit)+1))\n\tif err != nil {\n\t\tif isTimeout(err) {\n\t\t\tpanic(providerTimeout{who: who, millis: aiTimeoutMs()})\n\t\t}\n\t\tpanic(fmt.Sprintf(\"%s: HTTP POST to %s failed: %s\", who, endpoint, err.Error()))\n\t}\n\tif len(raw) > limit {\n\t\tpanic(fmt.Sprintf(\"%s: response body exceeds the %d-byte cap\", who, limit))\n\t}\n\treturn HttpResponse{\n\t\tStatus:  FromInt64(int64(response.StatusCode)),\n\t\tBody:    string(raw),\n\t\tHeaders: responseHeaders(response.Header),\n\t}\n}\n\n// stubbedProviderAnswer consults the `stubHttp` table the way every outbound call does. A\n// `stubHttpTimeout` rule raises the transport's timeout message; here that is re-raised as\n// the provider timeout, so a test that stubs a slow model exercises the same `aborted` path\n// a real deadline drives.\nfunc stubbedProviderAnswer(who, endpoint, body string) (answer HttpResponse, stubbed bool) {\n\tdefer func() {\n\t\traised := recover()\n\t\tif raised == nil {\n\t\t\treturn\n\t\t}\n\t\tif message, isText := raised.(string); isText && strings.Contains(message, \" timed out after \") {\n\t\t\tpanic(providerTimeout{who: who, millis: aiTimeoutMs()})\n\t\t}\n\t\tpanic(raised)\n\t}()\n\treturn httpStubAnswer(http.MethodPost, endpoint, &body)\n}\n\nfunc providerDecode(who, body string, into any) {\n\tif err := json.Unmarshal([]byte(body), into); err != nil {\n\t\tpanic(who + \": provider returned non-JSON body: \" + err.Error())\n\t}\n}\n\n// deliverWholeReply publishes a completed reply as a single delta. It is what stands in for\n// per-token streaming against a real provider; see the note at the top of this file.\nfunc deliverWholeReply(request LlmRequest, text string) {\n\tif request.OnDelta != nil && text != \"\" {\n\t\trequest.OnDelta(text)\n\t}\n}\n\nfunc tokenCount(value int64) Int { return FromInt64(value) }\n\n// \226\148\128\226\148\128 Anthropic \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\ntype anthropicRequest struct {\n\tModel     string             `json:\"model\"`\n\tMaxTokens int64              `json:\"max_tokens\"`\n\tSystem    string             `json:\"system\"`\n\tMessages  []anthropicMessage `json:\"messages\"`\n\tTools     []anthropicTool    `json:\"tools\"`\n}\n\ntype anthropicTool struct {\n\tName        string          `json:\"name\"`\n\tDescription string          `json:\"description\"`\n\tInputSchema json.RawMessage `json:\"input_schema\"`\n}\n\n// Content is either a string (a plain user turn) or a block list, which is why it is `any`\n// rather than a slice: Anthropic accepts both and the transcript carries both.\ntype anthropicMessage struct {\n\tRole    string `json:\"role\"`\n\tContent any    `json:\"content\"`\n}\n\ntype anthropicBlock struct {\n\tType      string          `json:\"type\"`\n\tText      string          `json:\"text,omitempty\"`\n\tID        string          `json:\"id,omitempty\"`\n\tName      string          `json:\"name,omitempty\"`\n\tInput     json.RawMessage `json:\"input,omitempty\"`\n\tToolUseID string          `json:\"tool_use_id,omitempty\"`\n\tContent   string          `json:\"content,omitempty\"`\n\tIsError   bool            `json:\"is_error,omitempty\"`\n}\n\nfunc anthropicTools(tools []LlmToolDecl) []anthropicTool {\n\tdecls := make([]anthropicTool, 0, len(tools))\n\tfor _, tool := range tools {\n\t\tdecls = append(decls, anthropicTool{\n\t\t\tName: tool.Name, Description: tool.Description, InputSchema: tool.Schema,\n\t\t})\n\t}\n\treturn decls\n}\n\nfunc anthropicMessages(messages []AgentMessage) []anthropicMessage {\n\trendered := make([]anthropicMessage, 0, len(messages))\n\tfor _, message := range messages {\n\t\t// Anthropic has only \"user\" and \"assistant\": a tool RESULT is a content block\n\t\t// sent back as the user. Passing \"tool\" through is an HTTP 400 that makes every\n\t\t// tool-using agent unusable on this provider.\n\t\trole := message.Role\n\t\tif role == \"tool\" {\n\t\t\trole = \"user\"\n\t\t}\n\t\tif len(message.Content) == 0 {\n\t\t\trendered = append(rendered, anthropicMessage{Role: role, Content: message.Text})\n\t\t\tcontinue\n\t\t}\n\t\tblocks := []anthropicBlock{}\n\t\tfor _, block := range message.Content {\n\t\t\tswitch block.Kind {\n\t\t\tcase \"text\":\n\t\t\t\tblocks = append(blocks, anthropicBlock{Type: \"text\", Text: block.Text})\n\t\t\tcase \"tool-use\":\n\t\t\t\tblocks = append(blocks, anthropicBlock{\n\t\t\t\t\tType: \"tool_use\", ID: block.ID, Name: block.Name, Input: block.Args,\n\t\t\t\t})\n\t\t\tcase \"tool-result\":\n\t\t\t\tfor _, result := range block.Results {\n\t\t\t\t\tblocks = append(blocks, anthropicBlock{\n\t\t\t\t\t\tType: \"tool_result\", ToolUseID: result.ID,\n\t\t\t\t\t\tContent: result.Content, IsError: result.IsError,\n\t\t\t\t\t})\n\t\t\t\t}\n\t\t\tdefault:\n\t\t\t\t// Unreachable for a validated transcript: validateTranscript (agent.go) admits\n\t\t\t\t// only the three kinds above, at ConversationFrom and again at the top of\n\t\t\t\t// runLoop, so a poisoned row is rejected there with a message \226\128\148 it used to\n\t\t\t\t// trap HERE, on every later turn of that conversation. A block that somehow\n\t\t\t\t// still has no wire form contributes nothing rather than ending the turn.\n\t\t\t\tcontinue\n\t\t\t}\n\t\t}\n\t\trendered = append(rendered, anthropicMessage{Role: role, Content: blocks})\n\t}\n\treturn rendered\n}\n\ntype anthropicResponse struct {\n\tContent []struct {\n\t\tType  string          `json:\"type\"`\n\t\tText  string          `json:\"text\"`\n\t\tID    string          `json:\"id\"`\n\t\tName  string          `json:\"name\"`\n\t\tInput json.RawMessage `json:\"input\"`\n\t} `json:\"content\"`\n\tStopReason string `json:\"stop_reason\"`\n\tUsage      struct {\n\t\tInput      int64 `json:\"input_tokens\"`\n\t\tOutput     int64 `json:\"output_tokens\"`\n\t\tCacheRead  int64 `json:\"cache_read_input_tokens\"`\n\t\tCacheWrite int64 `json:\"cache_creation_input_tokens\"`\n\t} `json:\"usage\"`\n}\n\nfunc anthropicNormalize(decoded anthropicResponse, request LlmRequest) LlmResponse {\n\ttext := \"\"\n\tcalls := []LlmToolCall{}\n\tfor _, block := range decoded.Content {\n\t\tswitch block.Type {\n\t\tcase \"text\":\n\t\t\ttext += block.Text\n\t\tcase \"tool_use\":\n\t\t\targs := block.Input\n\t\t\tif len(args) == 0 {\n\t\t\t\targs = json.RawMessage(\"{}\")\n\t\t\t}\n\t\t\tcalls = append(calls, LlmToolCall{ID: block.ID, Name: block.Name, Args: args})\n\t\t}\n\t}\n\tdeliverWholeReply(request, text)\n\treturn LlmResponse{\n\t\tText: text,\n\t\tUsage: LlmUsage{\n\t\t\tInput:      tokenCount(decoded.Usage.Input),\n\t\t\tOutput:     tokenCount(decoded.Usage.Output),\n\t\t\tCacheRead:  tokenCount(decoded.Usage.CacheRead),\n\t\t\tCacheWrite: tokenCount(decoded.Usage.CacheWrite),\n\t\t},\n\t\tToolCalls:  calls,\n\t\tStopReason: anthropicStopReason(decoded.StopReason),\n\t}\n}\n\nfunc anthropicStopReason(reason string) string {\n\tswitch reason {\n\tcase \"end_turn\":\n\t\treturn \"end-turn\"\n\tcase \"tool_use\":\n\t\treturn \"tool-use\"\n\tcase \"max_tokens\":\n\t\treturn \"max-tokens\"\n\tcase \"refusal\":\n\t\treturn \"refusal\"\n\tdefault:\n\t\treturn \"other\"\n\t}\n}\n\n// \226\148\128\226\148\128 OpenAI wire format \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\ntype openaiRequest struct {\n\tModel     string          `json:\"model\"`\n\tMaxTokens int64           `json:\"max_tokens\"`\n\tMessages  []openaiMessage `json:\"messages\"`\n\tTools     []openaiTool    `json:\"tools\"`\n}\n\ntype openaiTool struct {\n\tType     string           `json:\"type\"`\n\tFunction openaiToolSchema `json:\"function\"`\n}\n\ntype openaiToolSchema struct {\n\tName        string          `json:\"name\"`\n\tDescription string          `json:\"description\"`\n\tStrict      bool            `json:\"strict\"`\n\tParameters  json.RawMessage `json:\"parameters\"`\n}\n\ntype openaiMessage struct {\n\tRole       string           `json:\"role\"`\n\tContent    string           `json:\"content\"`\n\tToolCallID string           `json:\"tool_call_id,omitempty\"`\n\tToolCalls  []openaiToolCall `json:\"tool_calls,omitempty\"`\n}\n\ntype openaiToolCall struct {\n\tID       string             `json:\"id\"`\n\tType     string             `json:\"type\"`\n\tFunction openaiToolCallBody `json:\"function\"`\n}\n\ntype openaiToolCallBody struct {\n\tName string `json:\"name\"`\n\t// OpenAI carries the arguments as a JSON STRING, not as an object.\n\tArguments string `json:\"arguments\"`\n}\n\nfunc openaiTools(tools []LlmToolDecl) []openaiTool {\n\tdecls := make([]openaiTool, 0, len(tools))\n\tfor _, tool := range tools {\n\t\tdecls = append(decls, openaiTool{\n\t\t\tType: \"function\",\n\t\t\tFunction: openaiToolSchema{\n\t\t\t\tName: tool.Name, Description: tool.Description,\n\t\t\t\tStrict: true, Parameters: tool.Schema,\n\t\t\t},\n\t\t})\n\t}\n\treturn decls\n}\n\nfunc openaiMessages(system string, messages []AgentMessage) []openaiMessage {\n\trendered := []openaiMessage{}\n\tif system != \"\" {\n\t\trendered = append(rendered, openaiMessage{Role: \"system\", Content: system})\n\t}\n\tfor _, message := range messages {\n\t\tif len(message.Content) == 0 {\n\t\t\trendered = append(rendered, openaiMessage{Role: message.Role, Content: message.Text})\n\t\t\tcontinue\n\t\t}\n\t\tif message.Role == \"tool\" {\n\t\t\t// One message per result. A turn where the model called several tools has\n\t\t\t// several results, and every one has to come back under its own call id.\n\t\t\tfor _, block := range message.Content {\n\t\t\t\tfor _, result := range block.Results {\n\t\t\t\t\trendered = append(rendered, openaiMessage{\n\t\t\t\t\t\tRole: \"tool\", ToolCallID: result.ID, Content: result.Content,\n\t\t\t\t\t})\n\t\t\t\t}\n\t\t\t}\n\t\t\tcontinue\n\t\t}\n\t\ttext := \"\"\n\t\tcalls := []openaiToolCall{}\n\t\tfor _, block := range message.Content {\n\t\t\tswitch block.Kind {\n\t\t\tcase \"text\":\n\t\t\t\ttext += block.Text\n\t\t\tcase \"tool-use\":\n\t\t\t\targuments := string(block.Args)\n\t\t\t\tif arguments == \"\" {\n\t\t\t\t\targuments = \"{}\"\n\t\t\t\t}\n\t\t\t\tcalls = append(calls, openaiToolCall{\n\t\t\t\t\tID: block.ID, Type: \"function\",\n\t\t\t\t\tFunction: openaiToolCallBody{Name: block.Name, Arguments: arguments},\n\t\t\t\t})\n\t\t\t}\n\t\t}\n\t\trendered = append(rendered, openaiMessage{\n\t\t\tRole: message.Role, Content: text, ToolCalls: calls,\n\t\t})\n\t}\n\treturn rendered\n}\n\ntype openaiResponse struct {\n\tChoices []struct {\n\t\tMessage struct {\n\t\t\tContent   string           `json:\"content\"`\n\t\t\tToolCalls []openaiToolCall `json:\"tool_calls\"`\n\t\t} `json:\"message\"`\n\t\tFinishReason string `json:\"finish_reason\"`\n\t} `json:\"choices\"`\n\tUsage struct {\n\t\tPrompt       int64 `json:\"prompt_tokens\"`\n\t\tCompletion   int64 `json:\"completion_tokens\"`\n\t\tPromptDetail struct {\n\t\t\tCached int64 `json:\"cached_tokens\"`\n\t\t} `json:\"prompt_tokens_details\"`\n\t} `json:\"usage\"`\n}\n\nfunc openaiNormalize(decoded openaiResponse, request LlmRequest) LlmResponse {\n\ttext := \"\"\n\tfinish := \"\"\n\tcalls := []LlmToolCall{}\n\tif len(decoded.Choices) > 0 {\n\t\tchoice := decoded.Choices[0]\n\t\ttext = choice.Message.Content\n\t\tfinish = choice.FinishReason\n\t\tfor _, call := range choice.Message.ToolCalls {\n\t\t\t// Only a `function` call names one of OUR tools; any other type (a vendor's\n\t\t\t// built-in tool, say) is nothing this loop declared and nothing it may dispatch.\n\t\t\t// An absent type is tolerated: some OpenAI-compatible local servers omit it.\n\t\t\tif call.Type != \"\" && call.Type != \"function\" {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\t// The id is what the result is sent back under. With an empty one the tool\n\t\t\t// would run, and the vendor would then reject the next round-trip \226\128\148 the side\n\t\t\t// effect kept, the turn lost. Refusing before the dispatch is the fail-closed\n\t\t\t// order.\n\t\t\tif call.ID == \"\" {\n\t\t\t\tpanic(\"openai: tool call \" + strconv.Quote(call.Function.Name) +\n\t\t\t\t\t\" has no id \226\128\148 the result could not be returned to the model\")\n\t\t\t}\n\t\t\targuments := call.Function.Arguments\n\t\t\tif arguments == \"\" {\n\t\t\t\targuments = \"{}\"\n\t\t\t}\n\t\t\tif !json.Valid([]byte(arguments)) {\n\t\t\t\tpanic(\"openai: tool arguments were not valid JSON: \" + strconv.Quote(arguments))\n\t\t\t}\n\t\t\tcalls = append(calls, LlmToolCall{\n\t\t\t\tID: call.ID, Name: call.Function.Name, Args: json.RawMessage(arguments),\n\t\t\t})\n\t\t}\n\t}\n\tdeliverWholeReply(request, text)\n\treturn LlmResponse{\n\t\tText: text,\n\t\tUsage: LlmUsage{\n\t\t\tInput:     tokenCount(decoded.Usage.Prompt),\n\t\t\tOutput:    tokenCount(decoded.Usage.Completion),\n\t\t\tCacheRead: tokenCount(decoded.Usage.PromptDetail.Cached),\n\t\t},\n\t\tToolCalls:  calls,\n\t\tStopReason: openaiStopReason(finish, len(calls) > 0),\n\t}\n}\n\nfunc openaiStopReason(finish string, hasTools bool) string {\n\tif hasTools {\n\t\treturn \"tool-use\"\n\t}\n\tswitch finish {\n\tcase \"stop\":\n\t\treturn \"end-turn\"\n\tcase \"tool_calls\":\n\t\treturn \"tool-use\"\n\tcase \"length\":\n\t\treturn \"max-tokens\"\n\tcase \"content_filter\":\n\t\treturn \"refusal\"\n\tdefault:\n\t\treturn \"other\"\n\t}\n}\n");
  ("apitest.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"io\"\n\t\"net/http\"\n\t\"net/http/httptest\"\n\t\"strings\"\n)\n\n// In-process driving of an emitted server, for Tesl's `api-test` blocks.\n//\n// The request never leaves the process \226\128\148 no socket, no port to collide with \226\128\148 which is\n// what makes these usable as ordinary `go test` cases. Racket's api-tests dispatch the\n// same way (`dispatch-api-test-request` calls the server's own router rather than opening\n// a connection), so the two backends exercise the same layer.\ntype ApiResponse struct {\n\tStatus Int\n\t// The body as a PARSED JSON value, not as text.  An api-test inspects it without types\n\t// (`resp.body.userId`), which is the ergonomics the Racket surface has:\n\t// `api-test-field-access-ref` normalises the response and hands back the parsed body, so a\n\t// raw string here would have made every assertion a string-compare against serialised\n\t// JSON \226\128\148 a different language for the same test.\n\tBody    JsonValue\n\tHeaders Dict[string, string]\n}\n\n// ApiRequest dispatches one request and captures the response. `body` is sent as-is;\n// `cookies` are `name=value` pairs; `headers` are sent as written, which is what the\n// `headers { \226\128\166 }` modifier means \226\128\148 a test signing its own payload puts the tag in a header, and\n// a header value is transport text, not JSON.\nfunc ApiRequest(server Server, method, path, body string, cookies []string,\n\theaders []Tuple2[string, string]) ApiResponse {\n\trequest := newApiTestRequest(method, path, body)\n\t// A REQUEST cookie is just `name=value` on the wire \226\128\148 it carries none of the\n\t// Secure/HttpOnly/SameSite attributes a response cookie does, so the header is built\n\t// directly rather than through http.Cookie (which would also make gosec flag a\n\t// missing-attributes issue that cannot apply here).\n\tif len(cookies) > 0 {\n\t\trequest.Header.Set(\"Cookie\", strings.Join(cookies, \"; \"))\n\t}\n\tfor _, header := range headers {\n\t\t// HOST is not an ordinary header in Go: the request carries it in its own field, and a\n\t\t// value left in the header map is ignored by everything that reads it \226\128\148 including the\n\t\t// Host check a `publicOrigin` server applies. A test that sends `Host` means the host\n\t\t// the request is FOR, so it lands where that check looks.\n\t\tif strings.EqualFold(header.Tuple2First, \"Host\") {\n\t\t\trequest.Host = header.Tuple2Second\n\t\t\tcontinue\n\t\t}\n\t\t// Added rather than set: a test may send the same header twice deliberately, and the\n\t\t// server side is what decides which value wins.\n\t\trequest.Header.Add(header.Tuple2First, header.Tuple2Second)\n\t}\n\t// A body implies JSON unless the test said otherwise. The Racket harness hands the dispatcher\n\t// an already-parsed body, so \"the body is JSON\" is true there by construction; here the request\n\t// is real, and without this every `post \226\128\166 body { \226\128\166 }` would meet the server's own\n\t// content-type check (415) instead of the handler. Set only when the test did NOT choose a\n\t// content type \226\128\148 sending `text/plain` deliberately is how a test asserts that check.\n\tif body != \"\" && request.Header.Get(\"Content-Type\") == \"\" {\n\t\trequest.Header.Set(\"Content-Type\", \"application/json\")\n\t}\n\trecorder := httptest.NewRecorder()\n\tserver.ServeHTTP(recorder, request)\n\tresult := recorder.Result()\n\traw, _ := io.ReadAll(result.Body)\n\t// The RESPONSE headers, as the Dict an api-test reads: last-wins on a repeated name, the\n\t// same rule NewHttpRequest applies inbound.\n\t//\n\t// SET-COOKIE is the ONE exception, and it is chosen rather than accidental. A response\n\t// that both sets and clears a cookie is completely ordinary \226\128\148 the SSO callback emits\n\t//\n\t//\tSet-Cookie: __Host-session=<token>; \226\128\166      \226\134\144 the session it just minted\n\t//\tSet-Cookie: __Host-oauth=; Max-Age=0       \226\134\144 the spent in-flight state\n\t//\n\t// and last-wins made the surviving line the CLEARED cookie, so feeding it back carried\n\t// no session and the very next request 401'd. A wrong-but-plausible value rather than an\n\t// error, which reads as \"the login flow is broken\" instead of \"the harness dropped a\n\t// header\". So the surviving line is the FIRST that actually sets something; with only\n\t// clears present the last one still wins. Racket's `response-headers->hash` decides the\n\t// same way, in one place, so `responseCookie` needs no rule of its own.\n\tresponseHeaders := DictEmpty[string, string]()\n\tfor name, values := range result.Header {\n\t\tif len(values) == 0 {\n\t\t\tcontinue\n\t\t}\n\t\tsurviving := values[len(values)-1]\n\t\tif strings.EqualFold(name, \"Set-Cookie\") {\n\t\t\tfor _, line := range values {\n\t\t\t\tif cookieLineSetsAValue(line) {\n\t\t\t\t\tsurviving = line\n\t\t\t\t\tbreak\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tresponseHeaders = DictInsert(responseHeaders, strings.ToLower(name),\n\t\t\tsurviving, stringKeyLess)\n\t}\n\treturn ApiResponse{\n\t\tStatus:  FromInt64(int64(result.StatusCode)),\n\t\tBody:    JsonParseBody(string(raw)),\n\t\tHeaders: responseHeaders,\n\t}\n}\n\n// newApiTestRequest builds the in-process request. `httptest.NewRequest` PANICS on a path it\n// cannot parse \226\128\148 it assembles a request line and reads it back, so a space or a bad escape in\n// the path surfaces as Go's `malformed HTTP version \"b HTTP/1.0\"`. Since issue #45 the path may\n// be any String expression, so that is reachable from a test, and left alone it would crash the\n// whole test binary with a message about HTTP versions. The trap here names the path and the\n// test it belongs to instead \226\128\148 a trap rather than a 400-shaped response, because every other\n// mistake in an api-test's own text (a `fieldAt` on a non-object, an `arrayAt` out of range)\n// is a trap too, and a 400 would read as the SERVER's verdict on a request it never saw.\nfunc newApiTestRequest(method, path, body string) (request *http.Request) {\n\tdefer func() {\n\t\tif recovered := recover(); recovered != nil {\n\t\t\tpanic(fmt.Sprintf(\"api-test: cannot build the request %s %q: %v\", method, path, recovered))\n\t\t}\n\t}()\n\treturn httptest.NewRequest(method, path, strings.NewReader(body))\n}\n\n// The status predicates Tesl.ApiTest exposes.\nfunc StatusOk(status Int) bool          { return statusInRange(status, 200, 300) }\nfunc StatusClientError(status Int) bool { return statusInRange(status, 400, 500) }\nfunc StatusServerError(status Int) bool { return statusInRange(status, 500, 600) }\n\nfunc statusInRange(status Int, low, high int64) bool {\n\tvalue, ok := status.Int64()\n\treturn ok && value >= low && value < high\n}\n\n// cookieLineSetsAValue reports whether a `Set-Cookie` line assigns a non-empty value. A\n// `Max-Age=0` clear assigns none, so it can never shadow a real cookie.\nfunc cookieLineSetsAValue(line string) bool {\n\t// Cut at the first `;` rather than indexing a split: a split result is a slice whose\n\t// emptiness nothing here guarantees to a reader (or to nilaway), and the pair is\n\t// everything before the first attribute either way.\n\tpair := line\n\tif at := strings.Index(line, \";\"); at >= 0 {\n\t\tpair = line[:at]\n\t}\n\tpair = strings.TrimSpace(pair)\n\tat := strings.Index(pair, \"=\")\n\treturn at >= 0 && len(pair) > at+1\n}\n");
  ("apitest_json.go", "package teslrt\n\nimport (\n\t\"encoding/json\"\n\t\"fmt\"\n\t\"math/big\"\n\t\"sort\"\n\t\"strings\"\n)\n\n// The api-test view of a JSON value.\n//\n// Inside an `api-test` block a response body is inspected WITHOUT types \226\128\148 `resp.body.userId`\n// is deliberately untyped, and the checker types it as a fresh variable so the assertion\n// reads like the JSON it is checking. That ergonomics is the point, so this type mirrors what\n// the Racket api-test surface does rather than inventing a typed view: a field that is not\n// there is NULL rather than an error (`api-test-field-access-ref` returns `'null`), and the\n// predicates below are the same ones `tesl/api-test.rkt` exports, with the same argument\n// order.\n//\n// `raw` holds the parsed shape: nil for JSON null or a missing field, `json.Number` for a\n// number (so an exact integer stays exact), string, bool, `[]any`, `map[string]any`.\ntype JsonValue struct {\n\traw any\n}\n\n// DebugValue exposes the parsed api-test body as the same expandable tree as typed records.\n// JsonValue's raw payload stays private to the assertion runtime, but the debugger still needs\n// to show the keys a test can read (for example, response.body.message).\nfunc (value JsonValue) DebugValue(evaluateName string) DebugValue {\n\treturn debugJSONValue(value.raw, evaluateName, 0)\n}\n\nfunc debugJSONValue(value any, evaluateName string, depth int) DebugValue {\n\tresult := DebugValue{Type: debugJSONType(value), Display: debugJSONDisplay(value), EvaluateName: evaluateName}\n\tif depth >= 8 {\n\t\treturn result\n\t}\n\tswitch typed := value.(type) {\n\tcase map[string]any:\n\t\tkeys := make([]string, 0, len(typed))\n\t\tfor key := range typed {\n\t\t\tkeys = append(keys, key)\n\t\t}\n\t\tsort.Strings(keys)\n\t\tfor _, key := range keys {\n\t\t\tchild := debugJSONValue(typed[key], debugJSONJoinField(evaluateName, key), depth+1)\n\t\t\tchild.Name = key\n\t\t\tresult.Children = append(result.Children, child)\n\t\t}\n\tcase []any:\n\t\tfor index, item := range typed {\n\t\t\tchild := debugJSONValue(item, fmt.Sprintf(\"%s[%d]\", evaluateName, index), depth+1)\n\t\t\tchild.Name = fmt.Sprintf(\"[%d]\", index)\n\t\t\tresult.Children = append(result.Children, child)\n\t\t}\n\t}\n\treturn result\n}\n\nfunc debugJSONType(value any) string {\n\tswitch value.(type) {\n\tcase nil:\n\t\treturn \"JsonNull\"\n\tcase string:\n\t\treturn \"String\"\n\tcase bool:\n\t\treturn \"Bool\"\n\tcase json.Number:\n\t\treturn \"Number\"\n\tcase []any:\n\t\treturn \"JsonArray\"\n\tcase map[string]any:\n\t\treturn \"JsonObject\"\n\tdefault:\n\t\treturn \"JsonValue\"\n\t}\n}\n\nfunc debugJSONDisplay(value any) string {\n\tif value == nil {\n\t\treturn \"null\"\n\t}\n\treturn fmt.Sprint(value)\n}\n\nfunc debugJSONJoinField(base, field string) string {\n\tif base == \"\" {\n\t\treturn field\n\t}\n\treturn base + \".\" + field\n}\n\nfunc JsonNull() JsonValue { return JsonValue{} }\n\n// JsonOf wraps an already-parsed shape.\nfunc JsonOf(raw any) JsonValue { return JsonValue{raw: raw} }\n\n// JsonValueOf wraps an ORDINARY Tesl value for the api-test JSON surface. Racket's predicates\n// normalise whatever they are given (`api-test-normalize-json` runs the value\226\134\146jsexpr walk\n// first), so `hasField \"k\" job` on a plain record and `isNotNull err` on a String are\n// legitimate assertions there. This is that normalisation, applied once at the boundary\n// instead of inside each predicate.\nfunc JsonValueOf(value any) JsonValue { return JsonValue{raw: jsonNormalize(value)} }\n\n// JsonRaw is for the runtime's own use (comparing, printing); emitted code goes through the\n// helpers below.\nfunc (value JsonValue) JsonRaw() any { return value.raw }\n\n// JsonParseBody parses a response body for inspection. An empty body is JSON null \226\128\148 a\n// handler that answered `204` has nothing to inspect, and that is not a test failure by\n// itself.\n//\n// A body that is NOT JSON is the body as TEXT, which is what Racket's api-test holds: it\n// keeps the raw string and lets a field read on it answer null. Not every response a server\n// sends is JSON \226\128\148 the SSO failure page is a fixed HTML document \226\128\148 and trapping here made\n// `expect resp.status == 401` fail on a response whose STATUS was exactly what the test\n// asked about.\n//\n// A body that STARTS like a JSON document (`{`, `[` or `\"`) and then fails to parse is the\n// one case that traps, naming the body. That shape is never a legitimate text response \226\128\148 it is\n// a JSON producer that went wrong (a server that answered `{\"value\":+Inf}`, or a test's own\n// `body { \226\128\166 }` template with a typo) \226\128\148 and degrading it to a string turned the failure into\n// `resp.body.label` reading null three assertions later, with nothing pointing at the body.\nfunc JsonParseBody(body string) JsonValue {\n\ttrimmed := strings.TrimSpace(body)\n\tif trimmed == \"\" {\n\t\treturn JsonNull()\n\t}\n\tparsed, err := ParseJSON([]byte(trimmed))\n\tif err != nil {\n\t\tif looksLikeJSONDocument(trimmed) {\n\t\t\tpanic(fmt.Sprintf(\"api-test: the body starts like JSON but does not parse (%v): %s\",\n\t\t\t\terr, bodyPrefix(trimmed)))\n\t\t}\n\t\treturn JsonOf(body)\n\t}\n\treturn JsonOf(parsed)\n}\n\nfunc looksLikeJSONDocument(trimmed string) bool {\n\treturn strings.HasPrefix(trimmed, \"{\") || strings.HasPrefix(trimmed, \"[\") ||\n\t\tstrings.HasPrefix(trimmed, \"\\\"\")\n}\n\n// bodyPrefix is enough of a body to recognise it in a trap message, and no more: the body may\n// be a megabyte, and the message is for a test log.\nfunc bodyPrefix(body string) string {\n\tconst limit = 200\n\tif len(body) <= limit {\n\t\treturn body\n\t}\n\treturn body[:limit] + \"\226\128\166\"\n}\n\n// JsonFieldOf is `value.field` inside an api-test: a missing key \226\128\148 or a field read on\n// anything that is not an object \226\128\148 is NULL, matching `api-test-field-access-ref`. That is\n// what lets `expect isNull resp.body.missing` be written at all.\nfunc JsonFieldOf(value JsonValue, key string) JsonValue {\n\tfields, ok := value.raw.(map[string]any)\n\tif !ok {\n\t\treturn JsonNull()\n\t}\n\tfound, present := fields[key]\n\tif !present {\n\t\treturn JsonNull()\n\t}\n\treturn JsonOf(found)\n}\n\n// \226\148\128\226\148\128 The Tesl.ApiTest predicates, in Tesl's argument order \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nfunc JsonIsNull(value JsonValue) bool {\n\tif value.raw == nil {\n\t\treturn true\n\t}\n\t// Racket also treats the STRING \"null\" as null here, because a body that spelled null as\n\t// text would otherwise read as present.\n\ttext, ok := value.raw.(string)\n\treturn ok && text == \"null\"\n}\n\nfunc JsonIsNotNull(value JsonValue) bool { return !JsonIsNull(value) }\n\n// JsonLength counts an array, an object's keys, or a string's characters; anything else is a\n// trap naming what it got, as Racket's `jsonLength` does.\nfunc JsonLength(value JsonValue) Int {\n\tswitch typed := value.raw.(type) {\n\tcase []any:\n\t\treturn FromInt64(int64(len(typed)))\n\tcase map[string]any:\n\t\treturn FromInt64(int64(len(typed)))\n\tcase string:\n\t\treturn FromInt64(int64(len([]rune(typed))))\n\tdefault:\n\t\tpanic(fmt.Sprintf(\"jsonLength: expected an array, object, or string, got %s\",\n\t\t\tjsonTypeName(value.raw)))\n\t}\n}\n\nfunc JsonHasLength(expected Int, value JsonValue) bool {\n\treturn Compare(expected, JsonLength(value)) == 0\n}\n\nfunc JsonIsEmpty(value JsonValue) bool {\n\treturn Compare(JsonLength(value), FromInt64(0)) == 0\n}\n\nfunc JsonIsNotEmpty(value JsonValue) bool { return !JsonIsEmpty(value) }\n\nfunc JsonHasField(key string, value JsonValue) bool {\n\tfields, ok := value.raw.(map[string]any)\n\tif !ok {\n\t\tpanic(\"hasField: expected a JSON object, got \" + jsonTypeName(value.raw))\n\t}\n\t_, present := fields[key]\n\treturn present\n}\n\n// JsonFieldAt is `fieldAt`: like a field read, but it insists the value IS an object.\nfunc JsonFieldAt(key string, value JsonValue) JsonValue {\n\tfields, ok := value.raw.(map[string]any)\n\tif !ok {\n\t\tpanic(\"fieldAt: expected a JSON object, got \" + jsonTypeName(value.raw))\n\t}\n\tfound, present := fields[key]\n\tif !present {\n\t\treturn JsonNull()\n\t}\n\treturn JsonOf(found)\n}\n\nfunc JsonArrayAt(index Int, value JsonValue) JsonValue {\n\telements, ok := value.raw.([]any)\n\tif !ok {\n\t\tpanic(\"arrayAt: expected a JSON array, got \" + jsonTypeName(value.raw))\n\t}\n\tat, exact := index.Int64()\n\tif !exact || at < 0 || at >= int64(len(elements)) {\n\t\tpanic(fmt.Sprintf(\"arrayAt: index %s is out of range for array of length %d\",\n\t\t\tindex.String(), len(elements)))\n\t}\n\treturn JsonOf(elements[at])\n}\n\n// \226\148\128\226\148\128 The coercing accessors \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nfunc JsonAsInt(value JsonValue) Int {\n\tnumber, ok := value.raw.(json.Number)\n\tif !ok {\n\t\tpanic(\"jsonInt: expected a JSON number, got \" + jsonTypeName(value.raw))\n\t}\n\tparsed, valid := new(big.Int).SetString(number.String(), 10)\n\tif !valid {\n\t\tpanic(\"jsonInt: expected an integer, got \" + number.String())\n\t}\n\treturn fromBig(parsed)\n}\n\nfunc JsonAsString(value JsonValue) string {\n\ttext, ok := value.raw.(string)\n\tif !ok {\n\t\tpanic(\"jsonString: expected a JSON string, got \" + jsonTypeName(value.raw))\n\t}\n\treturn text\n}\n\nfunc JsonAsBool(value JsonValue) bool {\n\tflag, ok := value.raw.(bool)\n\tif !ok {\n\t\tpanic(\"jsonBool: expected a JSON boolean, got \" + jsonTypeName(value.raw))\n\t}\n\treturn flag\n}\n\n// \226\148\128\226\148\128 Comparison \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// JsonEqual compares an untyped JSON value against an ENCODED Tesl value \226\128\148 the same `any`\n// shape the response encoder builds, so the two directions cannot disagree about what a\n// value looks like as JSON.\n//\n// This is what makes `expect resp.body.age == 7` work: on Racket both sides are ordinary\n// values by then and `equal?` decides, so the comparison has to be structural here too.\nfunc JsonEqual(value JsonValue, other any) bool {\n\treturn jsonSame(value.raw, jsonNormalize(other))\n}\n\n// JsonContains is `jsonContains needle value`: substring for two strings, and otherwise\n// \"needle is contained in value\" \226\128\148 every field the needle names matches, recursively.\nfunc JsonContains(needle any, value JsonValue) bool {\n\twanted := jsonNormalize(needle)\n\tif needleText, ok := wanted.(string); ok {\n\t\tif valueText, ok := value.raw.(string); ok {\n\t\t\treturn strings.Contains(valueText, needleText)\n\t\t}\n\t}\n\treturn jsonMatch(wanted, value.raw)\n}\n\n// jsonNormalize maps an encoded Tesl value onto the shapes a parsed body uses, so that an\n// `Int` compares against a `json.Number` and a nested record against an object.\nfunc jsonNormalize(value any) any {\n\tswitch typed := value.(type) {\n\tcase nil:\n\t\treturn nil\n\tcase JsonValue:\n\t\treturn typed.raw\n\tcase Int:\n\t\treturn json.Number(typed.String())\n\tcase json.Number, string, bool:\n\t\treturn typed\n\tcase float64:\n\t\treturn json.Number(FormatFloat(typed))\n\tcase []any:\n\t\tout := make([]any, len(typed))\n\t\tfor index, element := range typed {\n\t\t\tout[index] = jsonNormalize(element)\n\t\t}\n\t\treturn out\n\tcase map[string]any:\n\t\tout := make(map[string]any, len(typed))\n\t\tfor key, element := range typed {\n\t\t\tout[key] = jsonNormalize(element)\n\t\t}\n\t\treturn out\n\tdefault:\n\t\treturn typed\n\t}\n}\n\nfunc jsonSame(left, right any) bool {\n\tswitch typedLeft := left.(type) {\n\tcase nil:\n\t\treturn right == nil\n\tcase json.Number:\n\t\treturn jsonNumbersEqual(typedLeft, right)\n\tcase string:\n\t\ttext, ok := right.(string)\n\t\treturn ok && text == typedLeft\n\tcase bool:\n\t\tflag, ok := right.(bool)\n\t\treturn ok && flag == typedLeft\n\tcase []any:\n\t\tother, ok := right.([]any)\n\t\tif !ok || len(other) != len(typedLeft) {\n\t\t\treturn false\n\t\t}\n\t\tfor index, element := range typedLeft {\n\t\t\tif !jsonSame(element, other[index]) {\n\t\t\t\treturn false\n\t\t\t}\n\t\t}\n\t\treturn true\n\tcase map[string]any:\n\t\tother, ok := right.(map[string]any)\n\t\tif !ok || len(other) != len(typedLeft) {\n\t\t\treturn false\n\t\t}\n\t\tfor key, element := range typedLeft {\n\t\t\tcounterpart, present := other[key]\n\t\t\tif !present || !jsonSame(element, counterpart) {\n\t\t\t\treturn false\n\t\t\t}\n\t\t}\n\t\treturn true\n\tdefault:\n\t\treturn false\n\t}\n}\n\n// Numbers compare by VALUE, not by text: `1` and `1.0` are the same JSON number, and an\n// exact integer beyond int64 still compares exactly.\nfunc jsonNumbersEqual(left json.Number, right any) bool {\n\tother, ok := right.(json.Number)\n\tif !ok {\n\t\treturn false\n\t}\n\tleftInt, leftExact := new(big.Int).SetString(left.String(), 10)\n\trightInt, rightExact := new(big.Int).SetString(other.String(), 10)\n\tif leftExact && rightExact {\n\t\treturn leftInt.Cmp(rightInt) == 0\n\t}\n\tleftFloat, leftErr := left.Float64()\n\trightFloat, rightErr := other.Float64()\n\treturn leftErr == nil && rightErr == nil && leftFloat == rightFloat\n}\n\n// jsonMatch is containment rather than equality: every key the needle names must match, and\n// extra keys in the value are fine.\nfunc jsonMatch(needle, value any) bool {\n\tswitch typedNeedle := needle.(type) {\n\tcase map[string]any:\n\t\tother, ok := value.(map[string]any)\n\t\tif !ok {\n\t\t\treturn false\n\t\t}\n\t\tfor key, element := range typedNeedle {\n\t\t\tcounterpart, present := other[key]\n\t\t\tif !present || !jsonMatch(element, counterpart) {\n\t\t\t\treturn false\n\t\t\t}\n\t\t}\n\t\treturn true\n\tcase []any:\n\t\tother, ok := value.([]any)\n\t\tif !ok {\n\t\t\treturn false\n\t\t}\n\t\t// Every element of the needle must appear somewhere in the value, in any position:\n\t\t// an array assertion is about membership, not about the whole array.\n\t\tfor _, element := range typedNeedle {\n\t\t\tfound := false\n\t\t\tfor _, candidate := range other {\n\t\t\t\tif jsonMatch(element, candidate) {\n\t\t\t\t\tfound = true\n\t\t\t\t\tbreak\n\t\t\t\t}\n\t\t\t}\n\t\t\tif !found {\n\t\t\t\treturn false\n\t\t\t}\n\t\t}\n\t\treturn true\n\tdefault:\n\t\treturn jsonSame(needle, value)\n\t}\n}\n\n// JsonListOf lifts a typed slice into the `any` shape `JsonEqual` compares against, so a\n// list can be compared with a JSON array without the emitter building the conversion inline.\nfunc JsonListOf[Element any](elements []Element) []any {\n\tout := make([]any, len(elements))\n\tfor index, element := range elements {\n\t\tout[index] = element\n\t}\n\treturn out\n}\n\n// JsonIncludesWhere is `includesWhere { \"field\": value, \226\128\166 } array`: does SOME element of the\n// array match every field the pattern names? `excludesWhere` is its negation.\n//\n// The pattern is a containment test per element, not equality, so an element with extra fields\n// still matches \226\128\148 an event stream carries ids and timestamps a test has no business pinning.\n// What is NOT tolerated is a pattern field the element does not have at all: that is a typo in\n// the test rather than a non-match, and reporting it as \"no element matched\" would send the\n// author looking at the program instead of at the assertion.\nfunc JsonIncludesWhere(pattern any, value JsonValue) bool {\n\treturn jsonArrayMatches(\"includesWhere\", pattern, value)\n}\n\nfunc JsonExcludesWhere(pattern any, value JsonValue) bool {\n\treturn !jsonArrayMatches(\"excludesWhere\", pattern, value)\n}\n\nfunc jsonArrayMatches(who string, pattern any, value JsonValue) bool {\n\tfields, ok := jsonNormalize(pattern).(map[string]any)\n\tif !ok {\n\t\tpanic(fmt.Sprintf(\"%s: expected a `{ \\\"field\\\": value }` pattern, got %s\",\n\t\t\twho, jsonTypeName(jsonNormalize(pattern))))\n\t}\n\telements, ok := value.raw.([]any)\n\tif !ok {\n\t\tpanic(fmt.Sprintf(\"%s: expected a JSON array, got %s\", who, jsonTypeName(value.raw)))\n\t}\n\tmatched := false\n\tfor _, element := range elements {\n\t\tobject, ok := element.(map[string]any)\n\t\tif !ok {\n\t\t\tpanic(fmt.Sprintf(\"%s: expected every array element to be a JSON object, got %s\",\n\t\t\t\twho, jsonTypeName(element)))\n\t\t}\n\t\telementMatches := true\n\t\tfor key, expected := range fields {\n\t\t\tfound, present := object[key]\n\t\t\tif !present {\n\t\t\t\tnames := make([]string, 0, len(object))\n\t\t\t\tfor name := range object {\n\t\t\t\t\tnames = append(names, name)\n\t\t\t\t}\n\t\t\t\tsort.Strings(names)\n\t\t\t\tpanic(fmt.Sprintf(\n\t\t\t\t\t\"%s: looking for field %q but element does not have it\\n  element has: %s\",\n\t\t\t\t\twho, key, strings.Join(names, \", \")))\n\t\t\t}\n\t\t\tif !jsonMatch(expected, found) {\n\t\t\t\telementMatches = false\n\t\t\t}\n\t\t}\n\t\tif elementMatches {\n\t\t\tmatched = true\n\t\t}\n\t}\n\treturn matched\n}\n\n// ApiTestFragment renders one `{\226\128\166}` slot of an api-test string template.\n//\n// The value goes through the same value\226\134\146JSON walk `api-test-string-fragment` performs in\n// dsl/test-support.rkt, and what comes out is rendered as TEXT: a string as itself, anything\n// else the way Racket's `~a` writes that jsexpr. That includes the two odd ones \226\128\148 a boolean\n// reads `#t`/`#f` and a JSON null reads `null` \226\128\148 because a template that interpolated one has\n// to produce the same request on both backends, and picking Go's spelling instead would be a\n// difference only a failing test would reveal.\nfunc ApiTestFragment(value any) string {\n\tswitch typed := value.(type) {\n\tcase string:\n\t\treturn typed\n\tcase bool:\n\t\tif typed {\n\t\t\treturn \"#t\"\n\t\t}\n\t\treturn \"#f\"\n\tcase Int:\n\t\treturn typed.String()\n\tcase float64:\n\t\treturn FormatFloat(typed)\n\tcase nil:\n\t\treturn \"null\"\n\tdefault:\n\t\treturn EncodeJSONValue(typed)\n\t}\n}\n");
  ("cache.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"strings\"\n\t\"sync\"\n\t\"time\"\n)\n\n// `cache C = Cache { \226\128\166 }`: a keyed store with per-entry expiry.\n//\n// WHAT THIS IS AND IS NOT. On Racket a cache reads and writes a `tesl_cache` TABLE whenever a\n// PostgreSQL runtime is bound, and its own in-memory hash otherwise \226\128\148 and nothing binds one\n// until `call-with-database`, so the in-memory store is what a program actually uses unless it\n// opens a connection. This is that store, with the same rules:\n//\n//\tan entry with no TTL never expires;\n//\ta TTL is seconds from the moment of the SET, not from the declaration;\n//\ta READ is what notices expiry \226\128\148 the entry is removed and the read answers Nothing, so a\n//\tstale value can never be returned, and no sweeper goroutine is needed;\n//\t`invalidate` matches a LITERAL prefix, not a LIKE pattern. Racket's PostgreSQL path spells\n//\tthat `left(key, length($1)) = $1` precisely because `key LIKE $1 || '%'` treats `%` in the\n//\tprefix as a wildcard \226\128\148 a prefix containing one would wipe far more than it names.\n//\n// The value is typed: `valueType: String` makes it a `Cache[string]`, so a hit needs no decode\n// and cannot answer the wrong shape. That is a departure from Racket, which stores JSON text in\n// the table and decodes on read \226\128\148 the JSON round trip exists there because a SQL column has to\n// hold something, and it is precisely what this store does not need.\n//\n// BOUNDS. A cache keyed on request data (the spec's own `\"user_<id>_*\"` example) is a memory\n// sink unless something reclaims it, and a read-driven expiry reclaims nothing a program\n// never reads again. So the store is bounded two ways: expired entries are swept on a write\n// once per second, and the entry count is capped \226\128\148 a write past the cap evicts expired\n// entries first and then the OLDEST write, so a hot key set survives and a churned one does\n// not accumulate. Neither changes what a read can answer: a live value or Nothing.\ntype cacheEntry[V any] struct {\n\tvalue V\n\t// expiresAt is Unix seconds, or 0 for \"never\" \226\128\148 the same distinction Racket makes with\n\t// a #f expiry.\n\texpiresAt int64\n\t// seq is the write's position in the cache's own sequence; what \"oldest\" means.\n\tseq int64\n}\n\n// defaultCacheMaxEntries bounds one cache declaration's entry count.\nconst defaultCacheMaxEntries = 100000\n\n// cacheNow is the clock, a variable so the runtime's own tests can move it.\nvar cacheNow = func() int64 { return time.Now().Unix() }\n\ntype Cache[V any] struct {\n\tmutex sync.Mutex\n\t// entries is allocated with the cache and never becomes nil again \226\128\148 a nil map here would\n\t// be a nil flow into every operation that reads or writes it.\n\tentries map[string]cacheEntry[V]\n\t// defaultTTL is `defaultTtl:` in seconds, or 0 when the declaration omits it.\n\tdefaultTTL int64\n\tmaxEntries int\n\t// writes is the FIFO of (key, seq) in write order, from which the oldest live entry is\n\t// found in amortised O(1): an entry whose key now maps to a newer seq is stale and\n\t// skipped. It is trimmed whenever it grows past twice the entry count.\n\twrites    []cacheWrite\n\tnextSeq   int64\n\tlastSweep int64\n\t// backend is the DURABLE store \226\128\148 the `tesl_cache` table \226\128\148 when the declaration names a\n\t// Postgres-backed database (`NewCacheOn` in pgstores.go attaches it); nil otherwise.\n\t// Each operation asks `durable()` and uses the map above when the backend is absent or\n\t// its database is not bound: a `test` block without `with database` keeps the in-memory\n\t// cache, a served program shares the table with every other instance.\n\tbackend cacheBackend\n}\n\n// cacheBackend is what a durable cache answers, in this file's vocabulary: a value or a miss,\n// a TTL in seconds (0 = never expires), a literal prefix. It names no driver type, and it is\n// NOT generic: values cross it as `any` (the backend holds the declaration's codec, so what\n// comes back is the value type), because a generic backend's methods are invisible to the\n// `unused` lint that gates emitted code when a program declares no cache.\ntype cacheBackend interface {\n\tactive() bool\n\tget(key string) (any, bool)\n\tset(key string, value any, ttlSeconds int64)\n\tdel(key string)\n\tinvalidatePrefix(prefix string)\n\treset()\n}\n\n// durable answers the backend this call runs against, or nil for the in-memory path.\nfunc (cache *Cache[V]) durable() cacheBackend {\n\tif backend := cache.backend; backend != nil && backend.active() {\n\t\treturn backend\n\t}\n\treturn nil\n}\n\ntype cacheWrite struct {\n\tkey string\n\tseq int64\n}\n\n// NewCache is what a `cache` declaration becomes: one package-level value per declaration.\nfunc NewCache[V any](defaultTTLSeconds int64) *Cache[V] {\n\treturn &Cache[V]{entries: map[string]cacheEntry[V]{}, defaultTTL: defaultTTLSeconds,\n\t\tmaxEntries: defaultCacheMaxEntries}\n}\n\n// CacheGet answers the live value, or Nothing on a miss OR an expired entry \226\128\148 and removes the\n// expired one on the way out, so the next read does no work either.\nfunc CacheGet[V any](cache *Cache[V], key string) Maybe[V] {\n\tif backend := cache.durable(); backend != nil {\n\t\tif value, found := backend.get(key); found {\n\t\t\tif typed, ok := value.(V); ok {\n\t\t\t\treturn Something(typed)\n\t\t\t}\n\t\t\tpanic(fmt.Sprintf(\"cache: the stored value decoded to %T, not the declared value type\", value))\n\t\t}\n\t\treturn Nothing[V]()\n\t}\n\tcache.mutex.Lock()\n\tdefer cache.mutex.Unlock()\n\tentry, found := cache.entries[key]\n\tif !found {\n\t\treturn Nothing[V]()\n\t}\n\tif entry.expiresAt != 0 && cacheNow() > entry.expiresAt {\n\t\tdelete(cache.entries, key)\n\t\treturn Nothing[V]()\n\t}\n\treturn Something(entry.value)\n}\n\n// CacheSet stores under the declaration's default TTL.\nfunc CacheSet[V any](cache *Cache[V], key string, value V) struct{} {\n\treturn cacheStore(cache, key, value, cache.defaultTTL)\n}\n\n// CacheSetTTL stores under an explicit TTL in seconds, which overrides the declaration's.\nfunc CacheSetTTL[V any](cache *Cache[V], key string, value V, ttlSeconds Int) struct{} {\n\tseconds, exact := ttlSeconds.Int64()\n\tif !exact || seconds < 0 {\n\t\tpanic(\"Cache.set: \" + ttlSeconds.String() + \" is not a TTL in seconds\")\n\t}\n\treturn cacheStore(cache, key, value, seconds)\n}\n\nfunc cacheStore[V any](cache *Cache[V], key string, value V, ttlSeconds int64) struct{} {\n\tif backend := cache.durable(); backend != nil {\n\t\tbackend.set(key, value, ttlSeconds)\n\t\treturn struct{}{}\n\t}\n\tcache.mutex.Lock()\n\tdefer cache.mutex.Unlock()\n\tnow := cacheNow()\n\tif now != cache.lastSweep {\n\t\t// At most one sweep per clock second, so a burst of writes into a large cache does\n\t\t// not pay an O(n) scan on each of them.\n\t\tcache.sweepExpired(now)\n\t}\n\tif _, present := cache.entries[key]; !present && len(cache.entries) >= cache.maxEntries {\n\t\tcache.sweepExpired(now)\n\t\tfor len(cache.entries) >= cache.maxEntries {\n\t\t\tif !cache.evictOldest() {\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t}\n\texpiresAt := int64(0)\n\tif ttlSeconds > 0 {\n\t\texpiresAt = now + ttlSeconds\n\t}\n\tcache.nextSeq++\n\tcache.entries[key] = cacheEntry[V]{value: value, expiresAt: expiresAt, seq: cache.nextSeq}\n\tcache.writes = append(cache.writes, cacheWrite{key: key, seq: cache.nextSeq})\n\tif len(cache.writes) > 2*len(cache.entries)+16 {\n\t\tcache.compactWrites()\n\t}\n\treturn struct{}{}\n}\n\n// sweepExpired removes every entry whose TTL has passed. The caller holds the mutex.\nfunc (cache *Cache[V]) sweepExpired(now int64) {\n\tcache.lastSweep = now\n\tfor key, entry := range cache.entries {\n\t\tif entry.expiresAt != 0 && now > entry.expiresAt {\n\t\t\tdelete(cache.entries, key)\n\t\t}\n\t}\n}\n\n// evictOldest removes the entry with the earliest live write, skipping FIFO records that\n// name a key since overwritten or deleted. It answers false when nothing is left to evict.\nfunc (cache *Cache[V]) evictOldest() bool {\n\tfor len(cache.writes) > 0 {\n\t\toldest := cache.writes[0]\n\t\tcache.writes = cache.writes[1:]\n\t\tif entry, present := cache.entries[oldest.key]; present && entry.seq == oldest.seq {\n\t\t\tdelete(cache.entries, oldest.key)\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// compactWrites drops the stale FIFO records so the FIFO stays proportional to the entries\n// rather than to the write history.\nfunc (cache *Cache[V]) compactWrites() {\n\tlive := make([]cacheWrite, 0, len(cache.entries))\n\tfor _, write := range cache.writes {\n\t\tif entry, present := cache.entries[write.key]; present && entry.seq == write.seq {\n\t\t\tlive = append(live, write)\n\t\t}\n\t}\n\tcache.writes = live\n}\n\n// CacheDelete evicts one key. Deleting a key that is not there is not an error \226\128\148 the point of\n// the call is the state afterwards.\nfunc CacheDelete[V any](cache *Cache[V], key string) struct{} {\n\tif backend := cache.durable(); backend != nil {\n\t\tbackend.del(key)\n\t\treturn struct{}{}\n\t}\n\tcache.mutex.Lock()\n\tdefer cache.mutex.Unlock()\n\tdelete(cache.entries, key)\n\treturn struct{}{}\n}\n\n// CacheInvalidatePrefix evicts every key that BEGINS WITH prefix, literally.\nfunc CacheInvalidatePrefix[V any](cache *Cache[V], prefix string) struct{} {\n\tif backend := cache.durable(); backend != nil {\n\t\tbackend.invalidatePrefix(prefix)\n\t\treturn struct{}{}\n\t}\n\tcache.mutex.Lock()\n\tdefer cache.mutex.Unlock()\n\tfor key := range cache.entries {\n\t\tif strings.HasPrefix(key, prefix) {\n\t\t\tdelete(cache.entries, key)\n\t\t}\n\t}\n\treturn struct{}{}\n}\n\n// CacheReset empties the store, for a test block that starts from an empty one. It is the\n// cache's counterpart of `TableTruncate`, and exists for the same reason: one block's entries\n// must not be another's.\nfunc CacheReset[V any](cache *Cache[V]) {\n\tif backend := cache.durable(); backend != nil {\n\t\tbackend.reset()\n\t\treturn\n\t}\n\tcache.mutex.Lock()\n\tdefer cache.mutex.Unlock()\n\tcache.entries = map[string]cacheEntry[V]{}\n\tcache.writes = nil\n}\n");
  ("check.go", "package teslrt\n\nimport \"fmt\"\n\n// Check is the erased runtime result of a Tesl check. Proof identities remain a\n// compiler concern; runtime retains only success/failure and the checked value.\ntype Check[T any] struct {\n\tvalue   T\n\tstatus  int\n\tmessage string\n\tok      bool\n\t// shape marks \"the JSON is not this shape\" as opposed to \"this value is invalid\"; see\n\t// RejectShape. It is a FLAG rather than a reserved status, because the status is also what\n\t// a leaked rejection writes on the wire, and a sentinel status of 0 there is not a\n\t// response \226\128\148 `WriteHeader(0)` panics.\n\tshape bool\n}\n\nfunc Accept[T any](value T) Check[T] {\n\treturn Check[T]{value: value, ok: true}\n}\n\nfunc Reject[T any](status int, message string) Check[T] {\n\treturn Check[T]{status: status, message: message}\n}\n\nfunc (result Check[T]) OK() bool {\n\treturn result.ok\n}\n\nfunc (result Check[T]) Value() (T, bool) {\n\treturn result.value, result.ok\n}\n\nfunc (result Check[T]) Status() int {\n\treturn result.status\n}\n\nfunc (result Check[T]) Message() string {\n\treturn result.message\n}\n\n// MustCheck unwraps a statically expected successful check and fails closed if\n// a caller ignored rejection propagation.\nfunc MustCheck[T any](result Check[T]) T {\n\tif !result.ok {\n\t\tpanic(fmt.Sprintf(\"Tesl check rejected with status %d: %s\", result.status, result.message))\n\t}\n\treturn result.value\n}\n\n// RequestRejection is a check rejection consumed inside a HANDLER body. It travels as a\n// panic because a handler's Go signature returns its value type, with nowhere to put a\n// failure \226\128\148 and the router turns it back into a response carrying the check's own status.\n//\n// That is the Racket behaviour, not an invention: `dsl/web.rkt` installs the\n// raise-on-escaping-failure wrapper for every function kind EXCEPT `handler`, so a\n// rejection reached in a handler body flows out as the response's status (422, 404, \226\128\166)\n// rather than as a server error. Reporting 500 there would turn \"you sent an invalid age\"\n// into \"this server is broken\".\ntype RequestRejection struct {\n\tStatus  int\n\tMessage string\n}\n\n// Error makes a rejection print as its MESSAGE wherever a panic value is formatted \226\128\148 which is\n// what a failed job records (`runJob` keeps `fmt.Sprint(recovered)` as the attempt's error).\n// Racket records `check-fail-message` there, the bare text, so a struct dump would be a\n// different string on the two backends for the same program.\nfunc (rejection RequestRejection) Error() string {\n\treturn rejection.Message\n}\n\n// MustCheckRequest is `MustCheck` at the request boundary: same unwrapping, but a rejection\n// answers the client instead of crashing the request.\nfunc MustCheckRequest[T any](result Check[T]) T {\n\tif !result.ok {\n\t\tpanic(RequestRejection{Status: result.status, Message: result.message})\n\t}\n\treturn result.value\n}\n\n// RejectShape reports that the JSON simply is not this shape \226\128\148 a missing or mistyped field \226\128\148\n// as opposed to a VALIDATION failure from a `via` or cross-check, which carries the status the\n// check itself chose.\n//\n// The distinction is load-bearing when a codec has several alternatives. Racket's\n// registry loop treats a raised decode exception as \"try the next decoder\" while a\n// check failure is remembered (the FIRST one wins) and still lets a later alternative\n// succeed. Collapsing the two would report \"required field \\\"userName\\\" not found\" \226\128\148\n// the last alternative's shape complaint \226\128\148 in place of the real 400 the first\n// alternative's check produced.\n// A shape rejection still carries 400, so a decoder with no alternatives behind it (a DERIVED\n// record decoder) can answer the client with it directly.\nfunc RejectShape[T any](message string) Check[T] {\n\treturn Check[T]{status: 400, message: message, shape: true}\n}\n\n// IsShapeMismatch reports whether a failure means \"not this shape\" rather than \"this\n// value is invalid\".\nfunc (result Check[T]) IsShapeMismatch() bool {\n\treturn !result.ok && result.shape\n}\n");
  ("control.go", "package teslrt\n\n// If evaluates and returns only the branch selected by condition.\nfunc If[T any](condition bool, whenTrue, whenFalse func() T) T {\n\tif condition {\n\t\treturn whenTrue()\n\t}\n\treturn whenFalse()\n}\n\n// Boxed holds a value behind a pointer, and Unboxed reads it back.\n//\n// A RECURSIVE ADT is why these exist: `type Expr = Lit Int | Add Expr Expr` cannot hold an\n// Expr by value in Go (a struct containing itself has no finite size), so a self-referential\n// payload field is a pointer and the emitter goes through these two functions at every\n// construction and every read. Keeping the indirection in one pair of named functions is\n// what makes it invisible in the emitted code's SHAPE: a pattern binding still reads as one\n// call, not as a nil test the reader has to trust.\n//\n// Unboxed traps on a nil pointer rather than answering a zero value. Nothing the emitter\n// produces can construct one \226\128\148 every boxed field is filled by Boxed at construction \226\128\148 so a\n// nil here is a broken invariant, and a fabricated zero Expr would turn it into a silently\n// wrong answer somewhere further along.\nfunc Boxed[T any](value T) *T {\n\treturn &value\n}\n\nfunc Unboxed[T any](boxed *T) T {\n\tif boxed == nil {\n\t\tpanic(\"recursive value: a payload field was never filled\")\n\t}\n\treturn *boxed\n}\n\n// BoolRank orders a Bool: false before true, which is how Racket sorts `#f` and `#t`. It\n// exists because Go has no `<` on bools and an `order p.done asc` column needs one.\nfunc BoolRank(value bool) int {\n\tif value {\n\t\treturn 1\n\t}\n\treturn 0\n}\n\n// \226\148\128\226\148\128 Partial application \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// `add 1` in Tesl is a function of the remaining argument. Go has no partial application,\n// so the emitter goes through these: each supplies the leading arguments and hands back a\n// closure over the rest.\n//\n// They are named functions rather than inline literals for the reason the comparators are:\n// go/printer decides whether a function literal fits on one line by a threshold the emitter\n// cannot predict, so an inline closure reformats under gofmt at some sizes and not others \226\128\148\n// and a gofmt diff on emitted code is an emitter bug. A call to one of these is one\n// expression at every size.\n//\n// The family stops at three parameters because that is what the surface reaches for; a\n// wider one is refused at emission rather than answered by a guess.\n\nfunc Apply1Of2[A, B, R any](fn func(A, B) R, first A) func(B) R {\n\treturn func(second B) R { return fn(first, second) }\n}\n\n// Apply1Of3 answers a CHAIN of one-argument functions, not a two-argument one: Tesl's\n// partial application is curried, so `blend 1` is a function of `b` that answers a function\n// of `c`. The Racket runtime is curried the same way, and a flat `withA 2 3` is an arity\n// error there \226\128\148 so the shape here is the surface's, not Go's convenience.\nfunc Apply1Of3[A, B, C, R any](fn func(A, B, C) R, first A) func(B) func(C) R {\n\treturn func(second B) func(C) R {\n\t\treturn func(third C) R { return fn(first, second, third) }\n\t}\n}\n\nfunc Apply2Of3[A, B, C, R any](fn func(A, B, C) R, first A, second B) func(C) R {\n\treturn func(third C) R { return fn(first, second, third) }\n}\n");
  ("crypto.go", "package teslrt\n\nimport (\n\t\"crypto/hmac\"\n\t\"crypto/rand\"\n\t\"crypto/sha256\"\n\t\"crypto/sha512\"\n\t\"crypto/subtle\"\n\t\"encoding/base64\"\n\t\"encoding/hex\"\n\t\"fmt\"\n\t\"os\"\n\t\"strings\"\n)\n\n// `Tesl.Crypto`: message authentication, digests and tokens.\n//\n// Every primitive here is Go's standard library, and each one is the same primitive the Racket\n// runtime calls into libsodium for \226\128\148 HMAC-SHA256, SHA-256, SHA-512, the OS CSPRNG \226\128\148 so a value\n// produced by one backend verifies on the other. What is NOT here is password storage\n// (`hashPassword`/`checkPassword`/`needsRehash`): Racket uses libsodium's Argon2id, Go's\n// standard library has no Argon2, and matching it means taking on\n// `golang.org/x/crypto/argon2` \226\128\148 a dependency decision, not an implementation detail, since a\n// PBKDF2 substitute would produce hashes the Racket side cannot verify. The emitter refuses\n// those three by name until that is decided.\n//\n// The SHAPE of the surface is the security argument, and it is preserved exactly:\n//\n//\ta Signature cannot be compared          \226\128\148 only `CheckSignature` consumes one, and it\n//\t                                          compares in constant time, so the classic\n//\t                                          timing-unsafe `==` on a MAC tag is unwritable;\n//\ta Secret cannot be printed              \226\128\148 it holds a SecretString, which redacts;\n//\tthe transport forms are one-way pairs   \226\128\148 hex/base64 in and out, because a tag is public\n//\t                                          data that travels in a header.\n\n// Secret is the stdlib's own secret: what `requireSecret` answers. It is a secret NEWTYPE\n// like any a program declares, so it prints as \"[redacted]\", compares in constant time, and\n// reaches an outbound header only through `HttpClient.bearer`/`secretHeader`.\ntype Secret struct {\n\tValue SecretString\n}\n\n// Signature is an opaque MAC tag, held as lowercase hex \226\128\148 the same representation the Racket\n// runtime keeps, so a tag crossing between them is the same string.\ntype Signature struct {\n\tValue string\n}\n\n// RequireSecret is `requireSecret`: the environment value, or a trap. An unset variable is a\n// configuration error, so it fails at the read rather than flowing on as an empty secret.\nfunc RequireSecret(name string) Secret {\n\tvalue, present := os.LookupEnv(name)\n\tif !present || value == \"\" {\n\t\tpanic(fmt.Sprintf(\"requireSecret: environment variable %s is not set (or is empty)\", name))\n\t}\n\treturn Secret{Value: MakeSecret(value)}\n}\n\nfunc hmacSha256Bytes(key, data string) []byte {\n\tmac := hmac.New(sha256.New, []byte(key))\n\t_, _ = mac.Write([]byte(data))\n\treturn mac.Sum(nil)\n}\n\n// SignWith is `Crypto.signWith key payload`: HMAC-SHA256, configuration first and subject\n// last, so `payload |> signWith key` reads correctly.\nfunc SignWith(key Secret, payload string) Signature {\n\treturn Signature{Value: hex.EncodeToString(hmacSha256Bytes(key.Value.Reveal(), payload))}\n}\n\n// CheckSignature is `Crypto.checkSignature key sig payload`. The constant-time compare lives\n// in here, where it cannot be got wrong \226\128\148 which is why there is no `constantTimeEquals` on the\n// surface at all. A malformed tag fails the verification cleanly rather than trapping: it\n// arrived from a header, so it is untrusted input, not a program error.\nfunc CheckSignature(key Secret, sig Signature, payload string) Check[string] {\n\texpected := hmacSha256Bytes(key.Value.Reveal(), payload)\n\tactual, err := hex.DecodeString(sig.Value)\n\tif err != nil || !hmac.Equal(expected, actual) {\n\t\treturn Reject[string](401, \"signature does not match\")\n\t}\n\treturn Accept(payload)\n}\n\n// SignatureHex is the transport form: a tag you produced, for a header or a body. A MAC tag is\n// public data, so this is not an unwrap of a secret \226\128\148 but it DOES make\n// `signatureHex a == signatureHex b` expressible, which is the timing-unsafe comparison, and\n// that is what the SEC002 diagnostic is for.\nfunc SignatureHex(sig Signature) string { return sig.Value }\n\n// SignatureFromHex is the inbound half: a webhook's tag arrives as hex in a header. Parsing\n// untrusted input is safe here \226\128\148 the result can still only be consumed by a verification.\nfunc SignatureFromHex(text string) Signature { return Signature{Value: text} }\n\n// SignatureBase64 is the base64 transport form (Standard Webhooks puts the tag in\n// `webhook-signature: v1,<base64>`).\nfunc SignatureBase64(sig Signature) string {\n\traw, err := hex.DecodeString(sig.Value)\n\tif err != nil {\n\t\t// The tag came from `signatureFromHex` on untrusted input; re-encoding it is not the\n\t\t// place to fail, and an unparseable tag has no base64 form.\n\t\treturn \"\"\n\t}\n\treturn base64.StdEncoding.EncodeToString(raw)\n}\n\n// SignatureFromBase64 is the inbound half for a base64 tag. Malformed input yields a tag that\n// cannot match any MAC, so the verification fails cleanly \226\128\148 the Racket side's decoder is\n// lenient in the same direction (it never turns bad input into an error the program sees).\nfunc SignatureFromBase64(text string) Signature {\n\traw, err := base64.StdEncoding.DecodeString(strings.TrimSpace(text))\n\tif err != nil {\n\t\treturn Signature{}\n\t}\n\treturn Signature{Value: hex.EncodeToString(raw)}\n}\n\n// Fingerprint is `Crypto.fingerprint`: a stable content digest for ETags, cache keys, dedup\n// and idempotency keys. NOT for passwords \226\128\148 a fast digest of a password is exactly the mistake\n// `hashPassword` exists to prevent.\nfunc Fingerprint(content string) string {\n\tsum := sha256.Sum256([]byte(content))\n\treturn hex.EncodeToString(sum[:])\n}\n\n// keyFingerprintLabel is hashed in so a key fingerprint can never coincide with\n// `Fingerprint` of the same string. The trailing NUL is part of the label, as on the Racket\n// side, so the two backends produce the same fingerprint for the same key.\nvar keyFingerprintLabel = []byte(\"tesl-key-fingerprint-v1\\x00\")\n\n// KeyFingerprint answers \"did I load the right key?\" \226\128\148 a short identifier that is safe to log.\n// Truncated to 8 bytes so it reads as an identifier rather than as something to compare\n// cryptographically; it is NOT proof of key possession.\nfunc KeyFingerprint(key Secret) string {\n\tsum := sha256.Sum256(append(append([]byte{}, keyFingerprintLabel...),\n\t\t[]byte(key.Value.Reveal())...))\n\treturn hex.EncodeToString(sum[:8])\n}\n\n// RandomToken is 256 bits from the OS CSPRNG, base64url with no padding (43 characters).\n// There is deliberately no length parameter: a caller who can pass 4 will.\nfunc RandomToken() string {\n\tbuffer := make([]byte, 32)\n\tif _, err := rand.Read(buffer); err != nil {\n\t\tpanic(\"Crypto.randomToken: no source of randomness: \" + err.Error())\n\t}\n\treturn base64.RawURLEncoding.EncodeToString(buffer)\n}\n\n// The expert aliases: the friendly names above are the ones a newcomer can pick correctly, and\n// these exist so someone who already knows what they want can say it.\n\nfunc Sha256Hex(content string) string { return Fingerprint(content) }\n\nfunc Sha512Hex(content string) string {\n\tsum := sha512.Sum512([]byte(content))\n\treturn hex.EncodeToString(sum[:])\n}\n\n// \226\148\128\226\148\128 The authenticating-proxy edge binding (`Tesl.Proxy`) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// ProxyVerifyBinding compares a request-supplied proxy-binding header against the app's\n// configured shared secret, in constant time, and accepts only on a match.\n//\n// The proof it mints on the Tesl side (`ProxyBound presented`) erases here like every\n// other, but what the proof is worth does not: the fact can be obtained ONLY through this\n// verification, so a function that demands it is reachable only by a value that was\n// actually checked against stored material. That is the whole difference from trusting an\n// `X-Auth-User`-style header, which asserts a network topology nothing verifies.\n//\n// Constant time for the reason Crypto.checkSignature is: a comparison that returns early\n// tells a caller how much of the secret it guessed.\nfunc ProxyVerifyBinding(configured Secret, presented string) Check[string] {\n\tif subtle.ConstantTimeCompare([]byte(configured.Value.Reveal()), []byte(presented)) == 1 {\n\t\treturn Accept(presented)\n\t}\n\t// A 401, not a 403: the request has not proved who it is, which is what an unmatched\n\t// binding means \226\128\148 and it is the status the Racket runtime answers with.\n\treturn Reject[string](401, \"proxy binding does not match\")\n}\n");
  ("debug.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"path/filepath\"\n\t\"reflect\"\n\tgoruntime \"runtime\"\n\t\"sort\"\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n\t\"time\"\n\t\"unicode/utf8\"\n)\n\n// DebugABIVersion identifies the language-neutral checkpoint metadata contract.\nconst DebugABIVersion = 1\n\ntype SourceLocation struct {\n\tFile   string `json:\"file\"`\n\tLine   int    `json:\"line\"`\n\tColumn int    `json:\"column\"`\n}\n\ntype debugValueProvider interface {\n\tDebugValue(string) DebugValue\n}\n\n// DebugValueOf builds the expandable value tree used by the DAP adapter. The evaluator name is\n// carried into children so a client can inspect a field using the same expression it sees in the\n// Tesl source. Feature-specific values can provide DebugValue without making the core debugger\n// depend on an optional runtime file.\nfunc DebugValueOf(value any, evaluateName string) DebugValue {\n\tif provider, ok := value.(debugValueProvider); ok {\n\t\treturn provider.DebugValue(evaluateName)\n\t}\n\treturn debugReflectValue(reflect.ValueOf(value), evaluateName, 0)\n}\n\nfunc debugReflectValue(value reflect.Value, evaluateName string, depth int) DebugValue {\n\tif !value.IsValid() {\n\t\treturn DebugValue{Type: \"null\", Display: \"null\", EvaluateName: evaluateName}\n\t}\n\tfor value.Kind() == reflect.Interface || value.Kind() == reflect.Pointer {\n\t\tif value.IsNil() {\n\t\t\treturn DebugValue{Type: value.Type().String(), Display: \"nil\", EvaluateName: evaluateName}\n\t\t}\n\t\tvalue = value.Elem()\n\t}\n\tif value.CanInterface() {\n\t\tif provider, ok := value.Interface().(debugValueProvider); ok {\n\t\t\treturn provider.DebugValue(evaluateName)\n\t\t}\n\t\tif integer, ok := value.Interface().(Int); ok {\n\t\t\treturn DebugValue{Type: \"Int\", Display: integer.String(), EvaluateName: evaluateName}\n\t\t}\n\t}\n\tresult := DebugValue{Type: value.Type().String(), Display: fmt.Sprint(value.Interface()), EvaluateName: evaluateName}\n\tif depth >= 8 {\n\t\treturn result\n\t}\n\tswitch value.Kind() {\n\tcase reflect.Struct:\n\t\tfor index := 0; index < value.NumField(); index++ {\n\t\t\tfield := value.Type().Field(index)\n\t\t\tif field.PkgPath != \"\" || !value.Field(index).CanInterface() {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tname := strings.ToLower(field.Name[:1]) + field.Name[1:]\n\t\t\tchild := debugReflectValue(value.Field(index), joinDebugField(evaluateName, name), depth+1)\n\t\t\tchild.Name = name\n\t\t\tresult.Children = append(result.Children, child)\n\t\t}\n\tcase reflect.Slice, reflect.Array:\n\t\tfor index := 0; index < value.Len(); index++ {\n\t\t\tname := fmt.Sprintf(\"[%d]\", index)\n\t\t\tchild := debugReflectValue(value.Index(index), evaluateName+name, depth+1)\n\t\t\tchild.Name = name\n\t\t\tresult.Children = append(result.Children, child)\n\t\t}\n\tcase reflect.Map:\n\t\tkeys := value.MapKeys()\n\t\tsort.Slice(keys, func(left, right int) bool {\n\t\t\treturn fmt.Sprint(keys[left].Interface()) < fmt.Sprint(keys[right].Interface())\n\t\t})\n\t\tfor _, key := range keys {\n\t\t\tname := fmt.Sprint(key.Interface())\n\t\t\tchild := debugReflectValue(value.MapIndex(key), joinDebugField(evaluateName, name), depth+1)\n\t\t\tchild.Name = name\n\t\t\tresult.Children = append(result.Children, child)\n\t\t}\n\tcase reflect.Invalid, reflect.Bool,\n\t\treflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,\n\t\treflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr,\n\t\treflect.Float32, reflect.Float64, reflect.Complex64, reflect.Complex128,\n\t\treflect.Chan, reflect.Func, reflect.Interface, reflect.Pointer,\n\t\treflect.String, reflect.UnsafePointer:\n\t\t// Scalar and opaque values have no expandable children.\n\t}\n\treturn result\n}\n\nfunc joinDebugField(base, field string) string {\n\tif base == \"\" {\n\t\treturn field\n\t}\n\treturn base + \".\" + field\n}\n\n// Bounded returns a copy safe for a wire value tree. It limits depth, child count,\n// and UTF-8 display bytes while preserving the fact that truncation occurred.\nfunc (value DebugValue) Bounded(maxDepth, maxChildren, maxDisplayBytes int) DebugValue {\n\tif maxDepth < 0 {\n\t\tmaxDepth = 0\n\t}\n\tif maxChildren < 0 {\n\t\tmaxChildren = 0\n\t}\n\tif maxDisplayBytes > 0 && len(value.Display) > maxDisplayBytes {\n\t\tvalue.Display = truncateDebugDisplay(value.Display, maxDisplayBytes)\n\t\tvalue.Truncated = true\n\t}\n\tif maxDepth == 0 {\n\t\tif len(value.Children) > 0 {\n\t\t\tvalue.Children = nil\n\t\t\tvalue.Truncated = true\n\t\t}\n\t\treturn value\n\t}\n\tif len(value.Children) > maxChildren {\n\t\tvalue.Children = value.Children[:maxChildren]\n\t\tvalue.Truncated = true\n\t}\n\tfor index := range value.Children {\n\t\tvalue.Children[index] = value.Children[index].Bounded(maxDepth-1, maxChildren, maxDisplayBytes)\n\t}\n\treturn value\n}\n\nfunc truncateDebugDisplay(value string, limit int) string {\n\tif limit <= 0 {\n\t\treturn \"\"\n\t}\n\tif utf8.ValidString(value) {\n\t\tfor len(value) > limit {\n\t\t\tvalue = value[:len(value)-1]\n\t\t\tfor !utf8.ValidString(value) {\n\t\t\t\tvalue = value[:len(value)-1]\n\t\t\t}\n\t\t}\n\t\treturn value\n\t}\n\treturn strings.ToValidUTF8(value[:limit], \"\")\n}\n\nfunc safeDebugValue(accessor func() DebugValue) (value DebugValue) {\n\tdefer func() {\n\t\tif recover() != nil {\n\t\t\tvalue = DebugValue{Type: \"unavailable\", Display: \"[unavailable]\", Truncated: true}\n\t\t}\n\t}()\n\treturn accessor().Bounded(8, 100, 4096)\n}\n\ntype DebugLocal struct {\n\tName     string            `json:\"name\"`\n\tType     string            `json:\"type\"`\n\tValue    DebugValue        `json:\"value\"`\n\tAccessor func() DebugValue `json:\"-\"`\n}\n\n// DebugFrame is emitted at a checkpoint. IDs are compiler-generated and remain stable\n// across runs for the same module/function/source location.\ntype DebugFrame struct {\n\tVersion  int            `json:\"version\"`\n\tID       string         `json:\"id\"`\n\tFunction string         `json:\"function\"`\n\tLocation SourceLocation `json:\"location\"`\n\tTest     string         `json:\"test,omitempty\"`\n\tDepth    int            `json:\"depth\"`\n\tLocals   []DebugLocal   `json:\"locals,omitempty\"`\n}\n\ntype DebugEvent struct {\n\tKind       string       `json:\"kind\"`\n\tFrame      DebugFrame   `json:\"frame\"`\n\tStack      []DebugFrame `json:\"stack,omitempty\"`\n\tRendezvous string       `json:\"rendezvous,omitempty\"`\n}\n\ntype DebugSnapshot struct {\n\tPaused     bool              `json:\"paused\"`\n\tFrame      DebugFrame        `json:\"frame\"`\n\tStack      []DebugFrame      `json:\"stack\"`\n\tRuntime    DebugRuntimeState `json:\"runtime\"`\n\tRendezvous string            `json:\"rendezvous,omitempty\"`\n}\n\ntype DebugListener func(DebugEvent)\n\ntype DebugStepMode string\n\nconst (\n\tDebugStepNone DebugStepMode = \"\"\n\tDebugStepIn   DebugStepMode = \"in\"\n\tDebugStepOver DebugStepMode = \"over\"\n\tDebugStepOut  DebugStepMode = \"out\"\n\n\tDebugRendezvousComplete = \"complete\"\n\tDebugRendezvousTimedOut = \"timed-out\"\n\tdebugRendezvousTimeout  = time.Second\n)\n\ntype DebugBreakpoint struct {\n\tID           string\n\tFile         string\n\tLine         int\n\tCondition    func(DebugFrame) bool\n\tHitCondition func(int) bool\n\thitCount     int\n}\n\ntype DebugBreakpointResult struct {\n\tID       string\n\tVerified bool\n\tMessage  string\n}\n\n// Debugger receives checkpoints only while a listener is attached. Unattached debug\n// programs therefore execute the same application code as release programs.\ntype Debugger struct {\n\tmutex          sync.Mutex\n\tcondition      *sync.Cond\n\tlistener       DebugListener\n\tbreakpoints    map[string]*DebugBreakpoint\n\tpaused         bool\n\tstopping       bool\n\tpauseRequested bool\n\t// PauseTimeout bounds how long ONE stop may hold application goroutines\n\t// before the debugger auto-resumes. Zero (the default) waits forever \226\128\148\n\t// correct while a human is stepping in a live session, because resuming\n\t// under them would corrupt their mental model of \"paused\". The attach/DAP\n\t// servers set this from TESL_DEBUG_PAUSE_TIMEOUT_MS so a client that dies\n\t// mid-stop (SIGKILL, laptop sleep) cannot wedge a long-running service.\n\tPauseTimeout      time.Duration\n\tlastFrame         DebugFrame\n\tlastSnapshot      DebugSnapshot\n\tstepMode          DebugStepMode\n\tstepOrigin        DebugFrame\n\tstoppedExec       uint64\n\tstacks            map[uint64][]DebugFrame\n\tquiescent         map[uint64]int\n\tparticipants      map[uint64]struct{}\n\tparked            map[uint64]struct{}\n\trendezvousTimeout time.Duration\n}\n\ntype DebugScope struct {\n\tdebugger  *Debugger\n\tframeID   string\n\texecution uint64\n\tonce      sync.Once\n}\n\ntype DebugQuiescentScope struct {\n\tdebugger  *Debugger\n\texecution uint64\n\tonce      sync.Once\n}\n\nfunc NewDebugger() *Debugger {\n\tdebugger := &Debugger{\n\t\tbreakpoints:       make(map[string]*DebugBreakpoint),\n\t\tstacks:            make(map[uint64][]DebugFrame),\n\t\tquiescent:         make(map[uint64]int),\n\t\tparticipants:      make(map[uint64]struct{}),\n\t\tparked:            make(map[uint64]struct{}),\n\t\trendezvousTimeout: debugRendezvousTimeout,\n\t}\n\tdebugger.condition = sync.NewCond(&debugger.mutex)\n\treturn debugger\n}\n\nfunc init() {\n\tdebugLifecycleQuiesce = func() func() {\n\t\tquiescent := DebugQuiesce()\n\t\treturn quiescent.Resume\n\t}\n}\n\n// Quiesce marks the current execution as blocked in runtime lifecycle work.\n// Its stack remains available, but it cannot hold a cooperative stop open.\n// Resume waits behind an established or collecting stop before returning to\n// instrumented Tesl code.\nfunc (debugger *Debugger) Quiesce() *DebugQuiescentScope {\n\texecution := debugExecutionID()\n\tdebugger.mutex.Lock()\n\tdebugger.quiescent[execution]++\n\tif debugger.stopping {\n\t\tdelete(debugger.participants, execution)\n\t\tdelete(debugger.parked, execution)\n\t\tdebugger.condition.Broadcast()\n\t}\n\tdebugger.mutex.Unlock()\n\treturn &DebugQuiescentScope{debugger: debugger, execution: execution}\n}\n\nfunc (scope *DebugQuiescentScope) Resume() {\n\tif scope == nil {\n\t\treturn\n\t}\n\tscope.once.Do(func() {\n\t\tscope.debugger.mutex.Lock()\n\t\tif count := scope.debugger.quiescent[scope.execution]; count <= 1 {\n\t\t\tdelete(scope.debugger.quiescent, scope.execution)\n\t\t\tscope.debugger.waitAtBarrier(scope.execution)\n\t\t} else {\n\t\t\tscope.debugger.quiescent[scope.execution] = count - 1\n\t\t}\n\t\tscope.debugger.mutex.Unlock()\n\t})\n}\n\nfunc (debugger *Debugger) Attach(listener DebugListener) func() {\n\tdebugger.mutex.Lock()\n\tdebugger.listener = listener\n\tdebugger.mutex.Unlock()\n\treturn func() { debugger.Detach() }\n}\n\n// Detach ends the session: application goroutines resume, and the retained stop\n// frame (request-scoped locals) is dropped so a later client cannot read it.\nfunc (debugger *Debugger) Detach() {\n\tdebugger.mutex.Lock()\n\tdebugger.listener = nil\n\tdebugger.paused = false\n\tdebugger.stopping = false\n\tdebugger.pauseRequested = false\n\tdebugger.stepMode = DebugStepNone\n\tdebugger.lastFrame = DebugFrame{}\n\tdebugger.lastSnapshot = DebugSnapshot{}\n\tdebugger.stoppedExec = 0\n\tclear(debugger.participants)\n\tclear(debugger.parked)\n\tdebugger.condition.Broadcast()\n\tdebugger.mutex.Unlock()\n}\n\nfunc (debugger *Debugger) Enter(frame DebugFrame) *DebugScope {\n\texecution := debugExecutionID()\n\tdebugger.mutex.Lock()\n\tdebugger.waitAtBarrier(execution)\n\tstack := debugger.stacks[execution]\n\tframe.Depth = len(stack)\n\tdebugger.stacks[execution] = append(stack, frame)\n\tdebugger.mutex.Unlock()\n\treturn &DebugScope{debugger: debugger, frameID: frame.ID, execution: execution}\n}\n\nfunc (scope *DebugScope) Leave() {\n\tif scope == nil {\n\t\treturn\n\t}\n\tscope.once.Do(func() {\n\t\tscope.debugger.mutex.Lock()\n\t\tstack := scope.debugger.stacks[scope.execution]\n\t\texecutionEnded := false\n\t\tfor index := len(stack) - 1; index >= 0; index-- {\n\t\t\tif stack[index].ID == scope.frameID {\n\t\t\t\tstack = append(stack[:index], stack[index+1:]...)\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t\tif len(stack) == 0 {\n\t\t\texecutionEnded = true\n\t\t\tdelete(scope.debugger.stacks, scope.execution)\n\t\t\tdelete(scope.debugger.quiescent, scope.execution)\n\t\t\tif scope.debugger.stopping {\n\t\t\t\tdelete(scope.debugger.participants, scope.execution)\n\t\t\t\tdelete(scope.debugger.parked, scope.execution)\n\t\t\t\tscope.debugger.condition.Broadcast()\n\t\t\t}\n\t\t} else {\n\t\t\tscope.debugger.stacks[scope.execution] = stack\n\t\t}\n\t\tscope.debugger.mutex.Unlock()\n\t\tif executionEnded {\n\t\t\tclearDebugSQLCaptureForExecution(scope.execution)\n\t\t}\n\t})\n}\n\nfunc (debugger *Debugger) updateStackFrame(execution uint64, frame DebugFrame) {\n\tstack, present := debugger.stacks[execution]\n\tif !present || len(stack) == 0 {\n\t\treturn\n\t}\n\tfor index := len(stack); index > 0; index-- {\n\t\tframeIndex := index - 1\n\t\tif stack[frameIndex].ID == frame.ID {\n\t\t\tframe.Depth = frameIndex\n\t\t\tstack[frameIndex] = frame\n\t\t\tdebugger.stacks[execution] = stack\n\t\t\treturn\n\t\t}\n\t}\n}\n\n// debugExecutionID supplies execution-local storage for debug builds without\n// changing the generated checkpoint ABI. Go exposes no goroutine-local API; the\n// runtime stack header is therefore read only while debugging is active.\nfunc debugExecutionID() uint64 {\n\tvar buffer [64]byte\n\tcount := goruntime.Stack(buffer[:], false)\n\tfields := strings.Fields(string(buffer[:count]))\n\tif len(fields) < 2 {\n\t\treturn 0\n\t}\n\tid, _ := strconv.ParseUint(fields[1], 10, 64)\n\treturn id\n}\n\n// waitAtBarrier parks an execution at an instrumentation boundary. Callers hold\n// debugger.mutex. Executions already active when a stop begins acknowledge the\n// rendezvous; executions starting later wait without extending that finite set.\nfunc (debugger *Debugger) waitAtBarrier(execution uint64) bool {\n\twaited := false\n\tfor debugger.stopping || debugger.paused {\n\t\twaited = true\n\t\tif _, participates := debugger.participants[execution]; participates {\n\t\t\tdebugger.parked[execution] = struct{}{}\n\t\t\tdebugger.condition.Broadcast()\n\t\t}\n\t\tdebugger.condition.Wait()\n\t}\n\treturn waited\n}\n\nfunc (debugger *Debugger) barrierComplete() bool {\n\tfor execution := range debugger.participants {\n\t\tif _, parked := debugger.parked[execution]; !parked {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n\nfunc (debugger *Debugger) breakpointHit(frame DebugFrame) bool {\n\tfor _, breakpoint := range debugger.breakpoints {\n\t\tif !sameSourceFile(breakpoint.File, frame.Location.File) || breakpoint.Line != frame.Location.Line {\n\t\t\tcontinue\n\t\t}\n\t\tbreakpoint.hitCount++\n\t\tif breakpoint.Condition != nil && !breakpoint.Condition(frame) {\n\t\t\tcontinue\n\t\t}\n\t\tif breakpoint.HitCondition != nil && !breakpoint.HitCondition(breakpoint.hitCount) {\n\t\t\tcontinue\n\t\t}\n\t\treturn true\n\t}\n\treturn false\n}\n\nfunc sameSourceFile(left, right string) bool {\n\tif left == right {\n\t\treturn true\n\t}\n\tleftAbsolute, leftErr := filepath.Abs(left)\n\trightAbsolute, rightErr := filepath.Abs(right)\n\treturn leftErr == nil && rightErr == nil && filepath.Clean(leftAbsolute) == filepath.Clean(rightAbsolute)\n}\n\nfunc (debugger *Debugger) Checkpoint(frame DebugFrame) {\n\tdebugger.mutex.Lock()\n\tlistener := debugger.listener\n\tif listener == nil {\n\t\tdebugger.mutex.Unlock()\n\t\treturn\n\t}\n\tdebugger.mutex.Unlock()\n\texecution := debugExecutionID()\n\tfor index := range frame.Locals {\n\t\tif frame.Locals[index].Accessor != nil {\n\t\t\tframe.Locals[index].Value = safeDebugValue(frame.Locals[index].Accessor)\n\t\t\tframe.Locals[index].Accessor = nil\n\t\t}\n\t}\n\tdebugger.mutex.Lock()\n\tif debugger.waitAtBarrier(execution) {\n\t\tdebugger.mutex.Unlock()\n\t\treturn\n\t}\n\tlistener = debugger.listener\n\tstack := debugger.stacks[execution]\n\tif len(stack) > 0 {\n\t\tframe.Depth = len(stack) - 1\n\t\tdebugger.updateStackFrame(execution, frame)\n\t}\n\tstepHit := debugger.stepMode != DebugStepNone && debugger.stepMatches(frame)\n\tif listener == nil || (!debugger.pauseRequested && !stepHit && !debugger.breakpointHit(frame)) {\n\t\tdebugger.mutex.Unlock()\n\t\treturn\n\t}\n\tdebugger.pauseRequested = false\n\tdebugger.stepMode = DebugStepNone\n\tdebugger.stopping = true\n\tclear(debugger.participants)\n\tclear(debugger.parked)\n\tfor active := range debugger.stacks {\n\t\tif debugger.quiescent[active] == 0 {\n\t\t\tdebugger.participants[active] = struct{}{}\n\t\t}\n\t}\n\tdebugger.participants[execution] = struct{}{}\n\tdebugger.parked[execution] = struct{}{}\n\trendezvousTimedOut := false\n\trendezvousTimer := time.AfterFunc(debugger.rendezvousTimeout, func() {\n\t\tdebugger.mutex.Lock()\n\t\trendezvousTimedOut = true\n\t\tdebugger.condition.Broadcast()\n\t\tdebugger.mutex.Unlock()\n\t})\n\tfor !debugger.barrierComplete() && debugger.listener != nil && !rendezvousTimedOut {\n\t\tdebugger.condition.Wait()\n\t}\n\trendezvousTimer.Stop()\n\tlistener = debugger.listener\n\tif listener == nil || !debugger.stopping {\n\t\tdebugger.stopping = false\n\t\tclear(debugger.participants)\n\t\tclear(debugger.parked)\n\t\tdebugger.condition.Broadcast()\n\t\tdebugger.mutex.Unlock()\n\t\treturn\n\t}\n\tdebugger.stopping = false\n\tdebugger.paused = true\n\tdebugger.stoppedExec = execution\n\tdebugger.lastFrame = frame\n\tstack = append([]DebugFrame(nil), debugger.stacks[execution]...)\n\trendezvous := DebugRendezvousComplete\n\tif !debugger.barrierComplete() {\n\t\trendezvous = DebugRendezvousTimedOut\n\t}\n\tdebugger.lastSnapshot = DebugSnapshot{Paused: true, Frame: frame, Stack: stack, Rendezvous: rendezvous}\n\tdebugger.mutex.Unlock()\n\truntimeState := debugRuntimeStateSnapshotForExecution(execution)\n\tdebugger.mutex.Lock()\n\tif debugger.paused && debugger.stoppedExec == execution {\n\t\tdebugger.lastSnapshot.Runtime = runtimeState\n\t}\n\tpublish := debugger.paused && debugger.stoppedExec == execution\n\tlistener = debugger.listener\n\tdebugger.mutex.Unlock()\n\tif !publish || listener == nil {\n\t\treturn\n\t}\n\tlistener(DebugEvent{Kind: \"stopped\", Frame: frame, Stack: stack, Rendezvous: rendezvous})\n\tdebugger.mutex.Lock()\n\t// The auto-resume guard: one timer per stop. It re-checks under the mutex\n\t// (a human Continue may have won the race) and broadcasts so every waiting\n\t// checkpoint re-evaluates `paused`. Stopped when the wait ends first.\n\tif debugger.PauseTimeout > 0 {\n\t\ttimer := time.AfterFunc(debugger.PauseTimeout, func() {\n\t\t\tdebugger.mutex.Lock()\n\t\t\tif debugger.paused {\n\t\t\t\tdebugger.paused = false\n\t\t\t\tdebugger.lastFrame = DebugFrame{}\n\t\t\t\tdebugger.lastSnapshot = DebugSnapshot{}\n\t\t\t\tdebugger.stoppedExec = 0\n\t\t\t\tclear(debugger.participants)\n\t\t\t\tclear(debugger.parked)\n\t\t\t\tdebugger.condition.Broadcast()\n\t\t\t}\n\t\t\tdebugger.mutex.Unlock()\n\t\t})\n\t\tdefer timer.Stop()\n\t}\n\tfor debugger.paused && debugger.listener != nil {\n\t\tdebugger.condition.Wait()\n\t}\n\tdebugger.mutex.Unlock()\n}\n\nfunc (debugger *Debugger) stepMatches(frame DebugFrame) bool {\n\tswitch debugger.stepMode {\n\tcase DebugStepIn:\n\t\treturn true\n\tcase DebugStepOver:\n\t\treturn frame.Function == debugger.stepOrigin.Function\n\tcase DebugStepOut:\n\t\treturn frame.Function != debugger.stepOrigin.Function\n\tcase DebugStepNone:\n\t\treturn false\n\tdefault:\n\t\treturn false\n\t}\n}\n\nfunc (debugger *Debugger) SetBreakpoints(breakpoints []DebugBreakpoint) []DebugBreakpointResult {\n\tdebugger.mutex.Lock()\n\tdefer debugger.mutex.Unlock()\n\tdebugger.breakpoints = make(map[string]*DebugBreakpoint, len(breakpoints))\n\tresults := make([]DebugBreakpointResult, 0, len(breakpoints))\n\tfor index := range breakpoints {\n\t\tbreakpoint := breakpoints[index]\n\t\tif breakpoint.ID == \"\" {\n\t\t\tbreakpoint.ID = fmt.Sprintf(\"bp-%d\", index+1)\n\t\t}\n\t\tbreakpoint.hitCount = 0\n\t\tcopy := breakpoint\n\t\tdebugger.breakpoints[breakpoint.ID] = &copy\n\t\tresults = append(results, DebugBreakpointResult{ID: breakpoint.ID, Verified: breakpoint.File != \"\" && breakpoint.Line >= 0})\n\t}\n\treturn results\n}\n\nfunc (debugger *Debugger) ClearBreakpoints() {\n\tdebugger.mutex.Lock()\n\tdebugger.breakpoints = make(map[string]*DebugBreakpoint)\n\tdebugger.mutex.Unlock()\n}\n\nfunc (debugger *Debugger) Pause() {\n\tdebugger.mutex.Lock()\n\tdebugger.stepMode = DebugStepNone\n\tdebugger.pauseRequested = true\n\tdebugger.mutex.Unlock()\n}\n\n// Continue resumes every waiting checkpoint and forgets the stop frame: once the\n// program is running again its request state must not stay readable via snapshot.\nfunc (debugger *Debugger) Continue() {\n\tdebugger.mutex.Lock()\n\tdebugger.stepMode = DebugStepNone\n\tdebugger.paused = false\n\tdebugger.stopping = false\n\tdebugger.lastFrame = DebugFrame{}\n\tdebugger.lastSnapshot = DebugSnapshot{}\n\tdebugger.stoppedExec = 0\n\tclear(debugger.participants)\n\tclear(debugger.parked)\n\tdebugger.condition.Broadcast()\n\tdebugger.mutex.Unlock()\n}\n\nfunc (debugger *Debugger) Step(mode DebugStepMode) bool {\n\tif mode != DebugStepIn && mode != DebugStepOver && mode != DebugStepOut {\n\t\treturn false\n\t}\n\tdebugger.mutex.Lock()\n\tdefer debugger.mutex.Unlock()\n\tif !debugger.paused {\n\t\treturn false\n\t}\n\tdebugger.stepMode = mode\n\tdebugger.stepOrigin = debugger.lastFrame\n\tdebugger.paused = false\n\tdebugger.lastFrame = DebugFrame{}\n\tdebugger.lastSnapshot = DebugSnapshot{}\n\tdebugger.stoppedExec = 0\n\tclear(debugger.participants)\n\tclear(debugger.parked)\n\tdebugger.condition.Broadcast()\n\treturn true\n}\n\nfunc (debugger *Debugger) Snapshot() (DebugFrame, bool) {\n\tdebugger.mutex.Lock()\n\tdefer debugger.mutex.Unlock()\n\treturn debugger.lastFrame, debugger.paused\n}\n\nfunc (debugger *Debugger) StackSnapshot() []DebugFrame {\n\tdebugger.mutex.Lock()\n\tdefer debugger.mutex.Unlock()\n\tif debugger.paused {\n\t\treturn append([]DebugFrame(nil), debugger.lastSnapshot.Stack...)\n\t}\n\treturn append([]DebugFrame(nil), debugger.stacks[debugExecutionID()]...)\n}\n\nfunc (debugger *Debugger) SnapshotState() DebugSnapshot {\n\tdebugger.mutex.Lock()\n\tdefer debugger.mutex.Unlock()\n\tif !debugger.paused {\n\t\treturn DebugSnapshot{}\n\t}\n\tsnapshot := debugger.lastSnapshot\n\tsnapshot.Stack = append([]DebugFrame(nil), snapshot.Stack...)\n\treturn snapshot\n}\n\nvar DefaultDebugger = NewDebugger()\n\nfunc Checkpoint(frame DebugFrame) { DefaultDebugger.Checkpoint(frame) }\n\nfunc DebugEnter(frame DebugFrame) *DebugScope { return DefaultDebugger.Enter(frame) }\n\nfunc DebugQuiesce() *DebugQuiescentScope { return DefaultDebugger.Quiesce() }\n");
  ("debug_control.go", "package teslrt\n\nimport (\n\t\"bufio\"\n\t\"crypto/rand\"\n\t\"crypto/subtle\"\n\t\"encoding/hex\"\n\t\"encoding/json\"\n\t\"errors\"\n\t\"fmt\"\n\t\"net\"\n\t\"os\"\n\t\"path/filepath\"\n\t\"runtime\"\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n\t\"time\"\n)\n\nconst (\n\tDebugProtocolVersion = 1\n\tdebugMaxControlLine  = 1 << 20\n\t// DebugPortFile and DebugTokenFile are written under <root>/.tesl-stuff/ when\n\t// the environment selects the loopback TCP fallback, so attach tooling can\n\t// discover the endpoint AND prove it is allowed to drive it.\n\tDebugPortFile  = \"debug.port\"\n\tDebugTokenFile = \"debug.token\"\n\t// DebugTokenEnv lets a launcher that already knows the port (it chose it) hand\n\t// the child the token to require, instead of reading the token file back.\n\tDebugTokenEnv         = \"TESL_DEBUG_TOKEN\" // #nosec G101 -- the NAME of the variable, not a credential.\n\tdebugTokenBytes       = 32\n\tdebugHandshakeTimeout = 5 * time.Second\n\tdebugWriteTimeout     = time.Second\n\tdebugMaxPendingTCP    = 16\n\tdebugMaxClients       = 16\n\tdebugMaxUnixPathBytes = 100\n)\n\ntype DebugControlRequest struct {\n\tID          string                `json:\"id\"`\n\tCommand     string                `json:\"command\"`\n\tBreakpoints []DebugBreakpointSpec `json:\"breakpoints,omitempty\"`\n\t// Token authenticates the handshake on a TCP endpoint. Unix endpoints are\n\t// authenticated by the socket's file permissions and ignore it.\n\tToken string `json:\"token,omitempty\"`\n}\n\ntype DebugBreakpointSpec struct {\n\tID        string `json:\"id,omitempty\"`\n\tFile      string `json:\"file\"`\n\tLine      int    `json:\"line\"`\n\tCondition string `json:\"condition,omitempty\"`\n\tHit       string `json:\"hit,omitempty\"`\n}\n\ntype DebugControlResponse struct {\n\tID     string             `json:\"id,omitempty\"`\n\tResult json.RawMessage    `json:\"result,omitempty\"`\n\tError  *DebugControlError `json:\"error,omitempty\"`\n}\n\ntype DebugControlError struct {\n\tCode    string `json:\"code\"`\n\tMessage string `json:\"message\"`\n}\n\ntype DebugStoppedEvent struct {\n\tEvent      string       `json:\"event\"`\n\tFrame      DebugFrame   `json:\"frame\"`\n\tStack      []DebugFrame `json:\"stack,omitempty\"`\n\tRendezvous string       `json:\"rendezvous,omitempty\"`\n}\n\ntype DebugHandshake struct {\n\tVersion      int      `json:\"version\"`\n\tRuntime      string   `json:\"runtime\"`\n\tABIVersion   int      `json:\"abiVersion\"`\n\tCapabilities []string `json:\"capabilities\"`\n}\n\ntype debugConditionValue struct {\n\ttext    string\n\tnumber  int64\n\thasNum  bool\n\tbool    bool\n\thasBool bool\n}\n\ntype DebugControlServer struct {\n\tdebugger *Debugger\n\tlistener net.Listener\n\tpath     string\n\tdone     chan struct{}\n\tclosed   chan struct{}\n\tmutex    sync.Mutex\n\t// clients holds only AUTHENTICATED connections: they receive stopped events and\n\t// hold the debugger attached. pending holds connections that have not completed\n\t// a handshake yet (TCP only); they receive nothing and are closed with the server.\n\tclients        map[net.Conn]struct{}\n\tpending        map[net.Conn]struct{}\n\twriters        map[net.Conn]*sync.Mutex\n\tconfigured     chan struct{}\n\tconfiguredOnce sync.Once\n\t// token is the hex credential a TCP client must present in its first message.\n\t// Empty on Unix endpoints, where filesystem permissions are the credential.\n\ttoken            string\n\thandshakeTimeout time.Duration\n\twriteTimeout     time.Duration\n\tmaxPendingTCP    int\n\tmaxClients       int\n\t// files are the discovery files (port/token) this server wrote and removes on Close.\n\tfiles []string\n}\n\n// StartDebugControl creates an owner-only Unix-domain endpoint and starts the\n// versioned control server. Existing socket files are removed only when they are\n// actually sockets; regular files are never overwritten.\nfunc (debugger *Debugger) StartDebugControl(path string) (*DebugControlServer, error) {\n\tif path == \"\" {\n\t\treturn nil, errors.New(\"debug control: socket path is empty\")\n\t}\n\tif err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil { // #nosec G703 -- debug endpoint path is intentionally caller-selected.\n\t\treturn nil, fmt.Errorf(\"debug control: create endpoint directory: %w\", err)\n\t}\n\tif err := os.Chmod(filepath.Dir(path), 0o700); err != nil { // #nosec G302,G703 -- tighten the private endpoint directory.\n\t\treturn nil, fmt.Errorf(\"debug control: protect endpoint directory: %w\", err)\n\t}\n\tif directory, err := os.Stat(filepath.Dir(path)); err != nil { // #nosec G703 -- path is the configured local debug endpoint.\n\t\treturn nil, fmt.Errorf(\"debug control: inspect endpoint directory: %w\", err)\n\t} else if directory.Mode().Perm()&0o077 != 0 {\n\t\treturn nil, errors.New(\"debug control: endpoint directory is not owner-only\")\n\t}\n\tif info, err := os.Lstat(path); err == nil { // #nosec G703 -- inspect only the configured debug endpoint.\n\t\tif info.Mode()&os.ModeSocket == 0 {\n\t\t\treturn nil, errors.New(\"debug control: endpoint exists and is not a socket\")\n\t\t}\n\t\tif err := os.Remove(path); err != nil { // #nosec G703 -- remove only a verified stale socket.\n\t\t\treturn nil, fmt.Errorf(\"debug control: remove stale endpoint: %w\", err)\n\t\t}\n\t} else if !errors.Is(err, os.ErrNotExist) {\n\t\treturn nil, fmt.Errorf(\"debug control: inspect endpoint: %w\", err)\n\t}\n\tlistener, err := net.Listen(\"unix\", path)\n\tif err != nil {\n\t\treturn nil, fmt.Errorf(\"debug control: listen: %w\", err)\n\t}\n\tif err := os.Chmod(path, 0o600); err != nil { // #nosec G703 -- protect the configured debug socket.\n\t\t_ = listener.Close()\n\t\t_ = os.Remove(path) // #nosec G703 -- remove only the socket just created.\n\t\treturn nil, fmt.Errorf(\"debug control: protect endpoint: %w\", err)\n\t}\n\treturn newDebugControlServer(debugger, listener, path, \"\"), nil\n}\n\n// StartDebugControlTCP provides the loopback fallback for platforms without\n// usable Unix sockets. Port zero asks the OS for an available port. Loopback is\n// shared by every local user, so the endpoint mints a fresh per-launch token\n// (see Token) and refuses every command until a client has presented it.\nfunc (debugger *Debugger) StartDebugControlTCP(port int) (*DebugControlServer, error) {\n\ttoken, err := NewDebugToken()\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\treturn debugger.StartDebugControlTCPWithToken(port, token)\n}\n\n// StartDebugControlTCPWithToken is StartDebugControlTCP with a caller-chosen\n// token \226\128\148 for a launcher that generated the credential itself and passes it to\n// the child through DebugTokenEnv. The token must be NewDebugToken-shaped.\nfunc (debugger *Debugger) StartDebugControlTCPWithToken(port int, token string) (*DebugControlServer, error) {\n\tif port < 0 || port > 65535 {\n\t\treturn nil, errors.New(\"debug control: TCP port outside 0..65535\")\n\t}\n\tif err := ValidateDebugToken(token); err != nil {\n\t\treturn nil, err\n\t}\n\tlistener, err := net.Listen(\"tcp4\", \"127.0.0.1:\"+strconv.Itoa(port))\n\tif err != nil {\n\t\treturn nil, fmt.Errorf(\"debug control: listen on loopback: %w\", err)\n\t}\n\tserver := newDebugControlServer(debugger, listener, \"\", token)\n\treturn server, nil\n}\n\n// NewDebugToken returns a fresh 32-byte crypto/rand credential, hex encoded.\nfunc NewDebugToken() (string, error) {\n\traw := make([]byte, debugTokenBytes)\n\tif _, err := rand.Read(raw); err != nil {\n\t\treturn \"\", fmt.Errorf(\"debug control: generate token: %w\", err)\n\t}\n\treturn hex.EncodeToString(raw), nil\n}\n\n// ValidateDebugToken accepts exactly the shape NewDebugToken produces, so a\n// truncated or hand-typed credential is refused at startup rather than silently\n// weakening the endpoint.\nfunc ValidateDebugToken(token string) error {\n\traw, err := hex.DecodeString(token)\n\tif err != nil || len(raw) != debugTokenBytes {\n\t\treturn errors.New(\"debug control: token must be 32 bytes, hex encoded\")\n\t}\n\treturn nil\n}\n\n// Token is the credential a TCP client must send as `token` in its handshake.\n// Empty for Unix endpoints.\nfunc (server *DebugControlServer) Token() string { return server.token }\n\n// Port is the bound TCP port, or zero for a Unix endpoint.\nfunc (server *DebugControlServer) Port() int {\n\tif address, ok := server.listener.Addr().(*net.TCPAddr); ok {\n\t\treturn address.Port\n\t}\n\treturn 0\n}\n\n// StartDebugControlFromEnvironment is the debug-build launch seam. It remains\n// inert unless TESL_DEBUG is enabled, while explicit socket/port variables make\n// test and attach launchers deterministic.\nfunc StartDebugControlFromEnvironment() (*DebugControlServer, error) {\n\tapplyEnvPauseTimeout(DefaultDebugger)\n\tif socket := os.Getenv(\"TESL_DEBUG_SOCKET\"); socket != \"\" {\n\t\treturn DefaultDebugger.StartDebugControl(socket)\n\t}\n\tif port := os.Getenv(\"TESL_DEBUG_PORT\"); port != \"\" {\n\t\tvalue, err := strconv.Atoi(port)\n\t\tif err != nil {\n\t\t\treturn nil, fmt.Errorf(\"debug control: invalid TESL_DEBUG_PORT: %w\", err)\n\t\t}\n\t\ttoken := os.Getenv(DebugTokenEnv)\n\t\tif token == \"\" {\n\t\t\tif token, err = NewDebugToken(); err != nil {\n\t\t\t\treturn nil, err\n\t\t\t}\n\t\t}\n\t\treturn startEnvironmentDebugTCP(value, token)\n\t}\n\tenabled := os.Getenv(\"TESL_DEBUG\")\n\tif enabled != \"1\" && enabled != \"true\" {\n\t\treturn nil, nil\n\t}\n\tsocket := filepath.Join(debugRootFromEnvironment(), \".tesl-stuff\", \"debug.sock\")\n\tif runtime.GOOS == \"windows\" || len([]byte(socket)) > debugMaxUnixPathBytes {\n\t\ttoken, err := NewDebugToken()\n\t\tif err != nil {\n\t\t\treturn nil, err\n\t\t}\n\t\treturn startEnvironmentDebugTCP(0, token)\n\t}\n\treturn DefaultDebugger.StartDebugControl(socket)\n}\n\nfunc startEnvironmentDebugTCP(port int, token string) (*DebugControlServer, error) {\n\tserver, err := DefaultDebugger.StartDebugControlTCPWithToken(port, token)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\t// The TCP fallback has no socket file to discover, so publish the port and\n\t// credential under the project. Both files are owner-only.\n\tif err := server.writeDiscoveryFiles(filepath.Join(debugRootFromEnvironment(), \".tesl-stuff\")); err != nil {\n\t\t_ = server.Close()\n\t\treturn nil, err\n\t}\n\treturn server, nil\n}\n\nfunc debugRootFromEnvironment() string {\n\tif root := os.Getenv(\"TESL_DEBUG_ROOT\"); root != \"\" {\n\t\treturn root\n\t}\n\treturn \".\"\n}\n\n// writeDiscoveryFiles publishes DebugPortFile and DebugTokenFile under directory\n// with owner-only permissions. Pre-existing files are replaced, never followed:\n// a planted symlink must not redirect the credential.\nfunc (server *DebugControlServer) writeDiscoveryFiles(directory string) error {\n\tif err := os.MkdirAll(directory, 0o700); err != nil { // #nosec G703 -- discovery directory is the configured debug root.\n\t\treturn fmt.Errorf(\"debug control: create discovery directory: %w\", err)\n\t}\n\tentries := []struct{ name, contents string }{\n\t\t{DebugPortFile, strconv.Itoa(server.Port()) + \"\\n\"},\n\t\t{DebugTokenFile, server.token + \"\\n\"},\n\t}\n\tfor _, entry := range entries {\n\t\tpath := filepath.Join(directory, entry.name)\n\t\tif err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) { // #nosec G703 -- replace only the runtime's own discovery file.\n\t\t\treturn fmt.Errorf(\"debug control: replace %s: %w\", entry.name, err)\n\t\t}\n\t\tfile, err := createPrivateDebugFile(path)\n\t\tif err != nil {\n\t\t\treturn fmt.Errorf(\"debug control: write %s: %w\", entry.name, err)\n\t\t}\n\t\tserver.mutex.Lock()\n\t\tserver.files = append(server.files, path)\n\t\tserver.mutex.Unlock()\n\t\t_, writeErr := file.WriteString(entry.contents)\n\t\tif closeErr := file.Close(); writeErr == nil {\n\t\t\twriteErr = closeErr\n\t\t}\n\t\tif writeErr != nil {\n\t\t\treturn fmt.Errorf(\"debug control: write %s: %w\", entry.name, writeErr)\n\t\t}\n\t}\n\treturn nil\n}\n\n// applyEnvPauseTimeout reads TESL_DEBUG_PAUSE_TIMEOUT_MS (milliseconds) into\n// debugger.PauseTimeout. Unset or invalid leaves the current value \226\128\148 zero by\n// default, i.e. an interactive session waits forever for its human.\nfunc applyEnvPauseTimeout(debugger *Debugger) {\n\tif raw := os.Getenv(\"TESL_DEBUG_PAUSE_TIMEOUT_MS\"); raw != \"\" {\n\t\tif value, err := strconv.ParseInt(raw, 10, 64); err == nil && value > 0 {\n\t\t\tdebugger.PauseTimeout = time.Duration(value) * time.Millisecond\n\t\t}\n\t}\n}\n\nfunc newDebugControlServer(debugger *Debugger, listener net.Listener, path, token string) *DebugControlServer {\n\tserver := &DebugControlServer{\n\t\tdebugger:         debugger,\n\t\tlistener:         listener,\n\t\tpath:             path,\n\t\tdone:             make(chan struct{}),\n\t\tclosed:           make(chan struct{}),\n\t\tclients:          make(map[net.Conn]struct{}),\n\t\tpending:          make(map[net.Conn]struct{}),\n\t\twriters:          make(map[net.Conn]*sync.Mutex),\n\t\tconfigured:       make(chan struct{}),\n\t\ttoken:            token,\n\t\thandshakeTimeout: debugHandshakeTimeout,\n\t\twriteTimeout:     debugWriteTimeout,\n\t\tmaxPendingTCP:    debugMaxPendingTCP,\n\t\tmaxClients:       debugMaxClients,\n\t}\n\t// The debugger is attached per authenticated client (see admit/release), not\n\t// here: an endpoint with no client must behave exactly like a release build.\n\tgo server.acceptLoop()\n\treturn server\n}\n\nfunc (server *DebugControlServer) Endpoint() string { return server.listener.Addr().String() }\n\n// WaitForConfiguration holds a compiler-launched target until its DAP client has\n// installed the initial breakpoint set. It is deliberately opt-in: ordinary debug\n// runs and attach sessions keep their existing start behavior.\nfunc (server *DebugControlServer) WaitForConfiguration() {\n\tselect {\n\tcase <-server.configured:\n\tcase <-server.done:\n\t}\n}\n\nfunc (server *DebugControlServer) acceptLoop() {\n\tdefer close(server.closed)\n\tfor {\n\t\tconnection, err := server.listener.Accept()\n\t\tif err != nil {\n\t\t\tselect {\n\t\t\tcase <-server.done:\n\t\t\t\treturn\n\t\t\tdefault:\n\t\t\t}\n\t\t\tcontinue\n\t\t}\n\t\tif connection == nil {\n\t\t\treturn\n\t\t}\n\t\tserver.mutex.Lock()\n\t\tif server.token != \"\" && len(server.pending) >= server.maxPendingTCP {\n\t\t\tserver.mutex.Unlock()\n\t\t\t_ = connection.Close()\n\t\t\tcontinue\n\t\t}\n\t\tserver.pending[connection] = struct{}{}\n\t\tserver.writers[connection] = &sync.Mutex{}\n\t\tserver.mutex.Unlock()\n\t\tgo server.handleConnection(connection)\n\t}\n}\n\n// admit promotes a connection to an authenticated client. The first client\n// attaches the debugger; later ones share the session up to the hard client cap.\nfunc (server *DebugControlServer) admit(connection net.Conn) bool {\n\tserver.mutex.Lock()\n\tdefer server.mutex.Unlock()\n\tdelete(server.pending, connection)\n\tselect {\n\tcase <-server.done:\n\t\t// A handshake racing Close must not re-attach the debugger to a dead endpoint.\n\t\treturn false\n\tdefault:\n\t}\n\tif _, already := server.clients[connection]; already {\n\t\treturn true\n\t}\n\tif len(server.clients) >= server.maxClients {\n\t\treturn false\n\t}\n\tif len(server.clients) == 0 {\n\t\tserver.debugger.Attach(server.broadcast)\n\t}\n\tserver.clients[connection] = struct{}{}\n\treturn true\n}\n\n// release forgets a connection. Only the LAST authenticated client leaving\n// detaches the debugger: a lost client must never leave application goroutines\n// paused, but one client's exit must not end another client's session, and a\n// connection that never authenticated has no session to end.\nfunc (server *DebugControlServer) release(connection net.Conn) {\n\tserver.mutex.Lock()\n\tdefer server.mutex.Unlock()\n\tdelete(server.pending, connection)\n\tdelete(server.writers, connection)\n\tif _, authenticated := server.clients[connection]; !authenticated {\n\t\treturn\n\t}\n\tdelete(server.clients, connection)\n\tif len(server.clients) == 0 {\n\t\tserver.debugger.Detach()\n\t}\n}\n\nfunc (server *DebugControlServer) authenticates(request DebugControlRequest) bool {\n\tif request.Command != \"handshake\" {\n\t\treturn false\n\t}\n\treturn subtle.ConstantTimeCompare([]byte(request.Token), []byte(server.token)) == 1\n}\n\nfunc (server *DebugControlServer) writeTo(connection net.Conn, write func() error) error {\n\tserver.mutex.Lock()\n\twriter := server.writers[connection]\n\ttimeout := server.writeTimeout\n\tserver.mutex.Unlock()\n\tif writer == nil {\n\t\treturn net.ErrClosed\n\t}\n\twriter.Lock()\n\tdefer writer.Unlock()\n\tif err := connection.SetWriteDeadline(time.Now().Add(timeout)); err != nil {\n\t\treturn err\n\t}\n\terr := write()\n\tif clearErr := connection.SetWriteDeadline(time.Time{}); err == nil {\n\t\terr = clearErr\n\t}\n\treturn err\n}\n\nfunc (server *DebugControlServer) reply(connection net.Conn, encoder *json.Encoder, response DebugControlResponse) error {\n\treturn server.writeTo(connection, func() error { return encoder.Encode(response) })\n}\n\nfunc (server *DebugControlServer) handleConnection(connection net.Conn) {\n\tif connection == nil {\n\t\treturn\n\t}\n\tdefer func() {\n\t\tserver.release(connection)\n\t\t_ = connection.Close()\n\t}()\n\t// Unix endpoints are authenticated by the socket's owner-only permissions, so\n\t// the connection is a client from its first byte (a handshake, if sent, is\n\t// answered like any other command). TCP endpoints admit nothing before a\n\t// handshake carrying the token.\n\tauthenticated := server.token == \"\"\n\tif authenticated {\n\t\tif !server.admit(connection) {\n\t\t\treturn\n\t\t}\n\t} else {\n\t\tserver.mutex.Lock()\n\t\thandshakeTimeout := server.handshakeTimeout\n\t\tserver.mutex.Unlock()\n\t\tif err := connection.SetReadDeadline(time.Now().Add(handshakeTimeout)); err != nil {\n\t\t\treturn\n\t\t}\n\t}\n\tscanner := bufio.NewScanner(connection)\n\tscanner.Buffer(make([]byte, 4096), debugMaxControlLine)\n\tencoder := json.NewEncoder(connection)\n\tfor scanner.Scan() {\n\t\tvar request DebugControlRequest\n\t\tdecoder := json.NewDecoder(strings.NewReader(scanner.Text()))\n\t\tdecoder.DisallowUnknownFields()\n\t\tdecodeErr := decoder.Decode(&request)\n\t\tif !authenticated {\n\t\t\tif decodeErr != nil || !server.authenticates(request) {\n\t\t\t\t// Closed at once: no session, no events, and nothing learned beyond\n\t\t\t\t// \"a credential is required\". The compare is constant-time.\n\t\t\t\t_ = server.reply(connection, encoder, DebugControlResponse{ID: request.ID, Error: &DebugControlError{\n\t\t\t\t\tCode: \"unauthorized\", Message: \"first message must be a handshake carrying the endpoint token\",\n\t\t\t\t}})\n\t\t\t\treturn\n\t\t\t}\n\t\t\tauthenticated = true\n\t\t\tif !server.admit(connection) {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tif err := connection.SetReadDeadline(time.Time{}); err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t}\n\t\tif decodeErr != nil || request.Command == \"\" {\n\t\t\t_ = server.reply(connection, encoder, DebugControlResponse{ID: request.ID, Error: &DebugControlError{\n\t\t\t\tCode: \"invalid-request\", Message: \"invalid control request\",\n\t\t\t}})\n\t\t\tcontinue\n\t\t}\n\t\tresponse, closeConnection := server.handleRequest(request)\n\t\tif err := server.reply(connection, encoder, response); err != nil || closeConnection {\n\t\t\treturn\n\t\t}\n\t}\n}\n\nfunc (server *DebugControlServer) handleRequest(request DebugControlRequest) (DebugControlResponse, bool) {\n\tresult := func(value any) DebugControlResponse {\n\t\tencoded, _ := json.Marshal(value)\n\t\treturn DebugControlResponse{ID: request.ID, Result: encoded}\n\t}\n\terrorResponse := func(code, message string) DebugControlResponse {\n\t\treturn DebugControlResponse{ID: request.ID, Error: &DebugControlError{Code: code, Message: message}}\n\t}\n\tswitch request.Command {\n\tcase \"handshake\":\n\t\treturn result(DebugHandshake{\n\t\t\tVersion: DebugProtocolVersion, Runtime: \"go\", ABIVersion: DebugABIVersion,\n\t\t\tCapabilities: []string{\"breakpoints\", \"conditions\", \"hit-counts\", \"pause\", \"snapshot\", \"continue\", \"step-in\", \"step-over\", \"step-out\", \"detach\"},\n\t\t}), false\n\tcase \"ping\":\n\t\treturn result(map[string]bool{\"ok\": true}), false\n\tcase \"set-breakpoints\":\n\t\tbreakpoints := make([]DebugBreakpoint, 0, len(request.Breakpoints))\n\t\tfor _, specification := range request.Breakpoints {\n\t\t\tcondition, err := compileDebugCondition(specification.Condition)\n\t\t\tif err != nil {\n\t\t\t\treturn errorResponse(\"invalid-condition\", err.Error()), false\n\t\t\t}\n\t\t\thitCondition, err := parseHitCondition(specification.Hit)\n\t\t\tif err != nil {\n\t\t\t\treturn errorResponse(\"invalid-hit-condition\", err.Error()), false\n\t\t\t}\n\t\t\tbreakpoints = append(breakpoints, DebugBreakpoint{\n\t\t\t\tID: specification.ID, File: specification.File, Line: specification.Line,\n\t\t\t\tCondition:    condition,\n\t\t\t\tHitCondition: hitCondition,\n\t\t\t})\n\t\t}\n\t\treturn result(server.debugger.SetBreakpoints(breakpoints)), false\n\tcase \"configuration-done\":\n\t\t// DAP sends this only after all per-source breakpoint updates. Releasing on\n\t\t// the first set-breakpoints request races when VS Code has breakpoints in\n\t\t// several files and sends the target file later.\n\t\tserver.configuredOnce.Do(func() { close(server.configured) })\n\t\treturn result(map[string]bool{\"ok\": true}), false\n\tcase \"clear-breakpoints\":\n\t\tserver.debugger.ClearBreakpoints()\n\t\treturn result(map[string]bool{\"ok\": true}), false\n\tcase \"pause\":\n\t\tserver.debugger.Pause()\n\t\treturn result(map[string]bool{\"ok\": true}), false\n\tcase \"continue\":\n\t\tserver.debugger.Continue()\n\t\treturn result(map[string]bool{\"ok\": true}), false\n\tcase \"step-in\", \"step-over\", \"step-out\":\n\t\tmode := DebugStepIn\n\t\tswitch request.Command {\n\t\tcase \"step-over\":\n\t\t\tmode = DebugStepOver\n\t\tcase \"step-out\":\n\t\t\tmode = DebugStepOut\n\t\t}\n\t\tif !server.debugger.Step(mode) {\n\t\t\treturn errorResponse(\"not-stopped\", \"step requires a stopped debugger\"), false\n\t\t}\n\t\treturn result(map[string]bool{\"ok\": true}), false\n\tcase \"snapshot\":\n\t\treturn result(server.debugger.SnapshotState()), false\n\tcase \"detach\":\n\t\treturn result(map[string]bool{\"ok\": true}), true\n\tdefault:\n\t\treturn errorResponse(\"unknown-command\", \"unsupported control command: \"+request.Command), false\n\t}\n}\n\nfunc splitCondition(value, separator string) []string {\n\tparts := []string{}\n\tstart := 0\n\tinString := false\n\tescaped := false\n\tfor index := 0; index < len(value); index++ {\n\t\tcharacter := value[index]\n\t\tif inString {\n\t\t\tif escaped {\n\t\t\t\tescaped = false\n\t\t\t} else if character == '\\\\' {\n\t\t\t\tescaped = true\n\t\t\t} else if character == '\"' {\n\t\t\t\tinString = false\n\t\t\t}\n\t\t\tcontinue\n\t\t}\n\t\tif character == '\"' {\n\t\t\tinString = true\n\t\t\tcontinue\n\t\t}\n\t\tif strings.HasPrefix(value[index:], separator) {\n\t\t\tparts = append(parts, value[start:index])\n\t\t\tstart = index + len(separator)\n\t\t\tindex += len(separator) - 1\n\t\t}\n\t}\n\tif len(parts) == 0 {\n\t\treturn []string{value}\n\t}\n\treturn append(parts, value[start:])\n}\n\nfunc conditionOperand(frame DebugFrame, operand string) (debugConditionValue, bool) {\n\toperand = strings.TrimSpace(operand)\n\tif len(operand) >= 2 && operand[0] == '\"' && operand[len(operand)-1] == '\"' {\n\t\tvalue, err := strconv.Unquote(operand)\n\t\treturn debugConditionValue{text: value}, err == nil\n\t}\n\tif value, err := strconv.ParseInt(operand, 10, 64); err == nil {\n\t\treturn debugConditionValue{text: operand, number: value, hasNum: true}, true\n\t}\n\tif operand == \"true\" || operand == \"false\" {\n\t\treturn debugConditionValue{text: operand, bool: operand == \"true\", hasBool: true}, true\n\t}\n\tvar value string\n\tswitch operand {\n\tcase \"file\":\n\t\tvalue = frame.Location.File\n\tcase \"line\":\n\t\tvalue = strconv.Itoa(frame.Location.Line)\n\tcase \"column\":\n\t\tvalue = strconv.Itoa(frame.Location.Column)\n\tcase \"function\":\n\t\tvalue = frame.Function\n\tcase \"id\":\n\t\tvalue = frame.ID\n\tcase \"depth\":\n\t\tvalue = strconv.Itoa(frame.Depth)\n\tcase \"test\":\n\t\tvalue = frame.Test\n\tdefault:\n\t\tfound := false\n\t\tfor _, local := range frame.Locals {\n\t\t\tif local.Name == operand {\n\t\t\t\tvalue = local.Value.Display\n\t\t\t\tfound = true\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t\tif !found {\n\t\t\treturn debugConditionValue{}, false\n\t\t}\n\t}\n\tif number, err := strconv.ParseInt(value, 10, 64); err == nil {\n\t\treturn debugConditionValue{text: value, number: number, hasNum: true}, true\n\t}\n\tif value == \"true\" || value == \"false\" {\n\t\treturn debugConditionValue{text: value, bool: value == \"true\", hasBool: true}, true\n\t}\n\treturn debugConditionValue{text: value}, true\n}\n\nfunc compileDebugCondition(specification string) (func(DebugFrame) bool, error) {\n\tspecification = strings.TrimSpace(specification)\n\tif specification == \"\" {\n\t\treturn nil, nil\n\t}\n\tif strings.Contains(specification, \"===\") || strings.Contains(specification, \"!==\") {\n\t\treturn nil, errors.New(\"condition supports ==, !=, >=, <=, >, and < only\")\n\t}\n\tif strings.HasPrefix(specification, \"!\") {\n\t\tinner, err := compileDebugCondition(strings.TrimSpace(specification[1:]))\n\t\tif err != nil || inner == nil {\n\t\t\tif err == nil {\n\t\t\t\terr = errors.New(\"condition negation requires an expression\")\n\t\t\t}\n\t\t\treturn nil, err\n\t\t}\n\t\treturn func(frame DebugFrame) bool { return !inner(frame) }, nil\n\t}\n\tfor _, logical := range []string{\"||\", \"&&\"} {\n\t\tparts := splitCondition(specification, logical)\n\t\tif len(parts) > 1 {\n\t\t\tconditions := make([]func(DebugFrame) bool, 0, len(parts))\n\t\t\tfor _, part := range parts {\n\t\t\t\tcondition, err := compileDebugCondition(part)\n\t\t\t\tif err != nil || condition == nil {\n\t\t\t\t\tif err == nil {\n\t\t\t\t\t\terr = errors.New(\"logical condition requires expressions on both sides\")\n\t\t\t\t\t}\n\t\t\t\t\treturn nil, err\n\t\t\t\t}\n\t\t\t\tconditions = append(conditions, condition)\n\t\t\t}\n\t\t\treturn func(frame DebugFrame) bool {\n\t\t\t\tif logical == \"||\" {\n\t\t\t\t\tfor _, condition := range conditions {\n\t\t\t\t\t\tif condition(frame) {\n\t\t\t\t\t\t\treturn true\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\treturn false\n\t\t\t\t}\n\t\t\t\tfor _, condition := range conditions {\n\t\t\t\t\tif !condition(frame) {\n\t\t\t\t\t\treturn false\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\treturn true\n\t\t\t}, nil\n\t\t}\n\t}\n\toperators := []string{\"==\", \"!=\", \">=\", \"<=\", \">\", \"<\"}\n\tfor _, operator := range operators {\n\t\tif index := strings.Index(specification, operator); index >= 0 {\n\t\t\tleft, right := strings.TrimSpace(specification[:index]), strings.TrimSpace(specification[index+len(operator):])\n\t\t\tif left == \"\" || right == \"\" {\n\t\t\t\treturn nil, errors.New(\"condition requires two operands\")\n\t\t\t}\n\t\t\treturn func(frame DebugFrame) bool {\n\t\t\t\tleftValue, leftOK := conditionOperand(frame, left)\n\t\t\t\trightValue, rightOK := conditionOperand(frame, right)\n\t\t\t\tif !leftOK || !rightOK {\n\t\t\t\t\treturn false\n\t\t\t\t}\n\t\t\t\tif leftValue.hasNum && rightValue.hasNum {\n\t\t\t\t\treturn compareConditionNumbers(leftValue.number, rightValue.number, operator)\n\t\t\t\t}\n\t\t\t\tif leftValue.hasBool && rightValue.hasBool {\n\t\t\t\t\tif operator == \"==\" {\n\t\t\t\t\t\treturn leftValue.bool == rightValue.bool\n\t\t\t\t\t}\n\t\t\t\t\tif operator == \"!=\" {\n\t\t\t\t\t\treturn leftValue.bool != rightValue.bool\n\t\t\t\t\t}\n\t\t\t\t\treturn false\n\t\t\t\t}\n\t\t\t\tswitch operator {\n\t\t\t\tcase \"==\":\n\t\t\t\t\treturn leftValue.text == rightValue.text\n\t\t\t\tcase \"!=\":\n\t\t\t\t\treturn leftValue.text != rightValue.text\n\t\t\t\tcase \">\":\n\t\t\t\t\treturn leftValue.text > rightValue.text\n\t\t\t\tcase \">=\":\n\t\t\t\t\treturn leftValue.text >= rightValue.text\n\t\t\t\tcase \"<\":\n\t\t\t\t\treturn leftValue.text < rightValue.text\n\t\t\t\tcase \"<=\":\n\t\t\t\t\treturn leftValue.text <= rightValue.text\n\t\t\t\tdefault:\n\t\t\t\t\treturn false\n\t\t\t\t}\n\t\t\t}, nil\n\t\t}\n\t}\n\treturn nil, errors.New(\"condition must compare fields, locals, or literals\")\n}\n\nfunc compareConditionNumbers(left, right int64, operator string) bool {\n\tswitch operator {\n\tcase \"==\":\n\t\treturn left == right\n\tcase \"!=\":\n\t\treturn left != right\n\tcase \">\":\n\t\treturn left > right\n\tcase \">=\":\n\t\treturn left >= right\n\tcase \"<\":\n\t\treturn left < right\n\tcase \"<=\":\n\t\treturn left <= right\n\tdefault:\n\t\treturn false\n\t}\n}\n\nfunc (server *DebugControlServer) broadcast(event DebugEvent) {\n\tmessage, err := json.Marshal(DebugStoppedEvent{Event: event.Kind, Frame: event.Frame, Stack: event.Stack, Rendezvous: event.Rendezvous})\n\tif err != nil {\n\t\treturn\n\t}\n\tmessage = append(message, '\\n')\n\tserver.mutex.Lock()\n\tclients := make([]net.Conn, 0, len(server.clients))\n\tfor client := range server.clients {\n\t\tclients = append(clients, client)\n\t}\n\tserver.mutex.Unlock()\n\tfor _, client := range clients {\n\t\tgo func() {\n\t\t\tremaining := message\n\t\t\terr := server.writeTo(client, func() error {\n\t\t\t\tfor len(remaining) > 0 {\n\t\t\t\t\twritten, writeErr := client.Write(remaining)\n\t\t\t\t\tif writeErr != nil {\n\t\t\t\t\t\treturn writeErr\n\t\t\t\t\t}\n\t\t\t\t\tif written == 0 {\n\t\t\t\t\t\treturn errors.New(\"debug control: zero-byte write\")\n\t\t\t\t\t}\n\t\t\t\t\tremaining = remaining[written:]\n\t\t\t\t}\n\t\t\t\treturn nil\n\t\t\t})\n\t\t\tif err != nil {\n\t\t\t\tserver.release(client)\n\t\t\t\t_ = client.Close()\n\t\t\t}\n\t\t}()\n\t}\n}\n\nfunc (server *DebugControlServer) Close() error {\n\tselect {\n\tcase <-server.done:\n\t\treturn nil\n\tdefault:\n\t\tclose(server.done)\n\t}\n\t_ = server.listener.Close()\n\tserver.mutex.Lock()\n\tif len(server.clients) > 0 {\n\t\tserver.debugger.Detach()\n\t}\n\tfor client := range server.clients {\n\t\t_ = client.Close()\n\t}\n\tfor connection := range server.pending {\n\t\t_ = connection.Close()\n\t}\n\tserver.clients = make(map[net.Conn]struct{})\n\tserver.pending = make(map[net.Conn]struct{})\n\tserver.writers = make(map[net.Conn]*sync.Mutex)\n\tfiles := server.files\n\tserver.files = nil\n\tserver.mutex.Unlock()\n\t<-server.closed\n\tvar firstErr error\n\tfor _, file := range files {\n\t\tif err := os.Remove(file); err != nil && !errors.Is(err, os.ErrNotExist) && firstErr == nil { // #nosec G703 -- remove only the discovery files this server wrote.\n\t\t\tfirstErr = err\n\t\t}\n\t}\n\tif server.path != \"\" {\n\t\tif err := os.Remove(server.path); err != nil && firstErr == nil { // #nosec G703 -- the socket this server created.\n\t\t\tfirstErr = err\n\t\t}\n\t}\n\treturn firstErr\n}\n\nfunc parseHitCondition(specification string) (func(int) bool, error) {\n\tspecification = strings.TrimSpace(specification)\n\tif specification == \"\" {\n\t\treturn nil, nil\n\t}\n\toperator := \"==\"\n\tvalue := specification\n\tfor _, candidate := range []string{\"%\", \">=\", \"<=\", \">\", \"<\", \"==\"} {\n\t\tif strings.HasPrefix(specification, candidate) {\n\t\t\toperator, value = candidate, strings.TrimSpace(specification[len(candidate):])\n\t\t\tbreak\n\t\t}\n\t}\n\tcount, err := strconv.Atoi(value)\n\tif err != nil || count <= 0 {\n\t\treturn nil, errors.New(\"hit condition must be a positive integer with ==, >=, <=, >, <, or %\")\n\t}\n\treturn func(hit int) bool {\n\t\tswitch operator {\n\t\tcase \"%\":\n\t\t\treturn hit%count == 0\n\t\tcase \">=\":\n\t\t\treturn hit >= count\n\t\tcase \"<=\":\n\t\t\treturn hit <= count\n\t\tcase \">\":\n\t\t\treturn hit > count\n\t\tcase \"<\":\n\t\t\treturn hit < count\n\t\tdefault:\n\t\t\treturn hit == count\n\t\t}\n\t}, nil\n}\n\n// CompileDebugCondition exposes the bounded condition grammar to debugger adapters.\nfunc CompileDebugCondition(specification string) (func(DebugFrame) bool, error) {\n\treturn compileDebugCondition(specification)\n}\n\n// ParseHitCondition exposes hit-count parsing to debugger adapters.\nfunc ParseHitCondition(specification string) (func(int) bool, error) {\n\treturn parseHitCondition(specification)\n}\n");
  ("debug_file_unix.go", "//go:build !windows\n\npackage teslrt\n\nimport \"os\"\n\nfunc createPrivateDebugFile(path string) (*os.File, error) {\n\treturn os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600) // #nosec G304 -- caller-selected debugger endpoint file; exclusive creation refuses an existing file or symlink.\n}\n");
  ("debug_file_windows.go", "//go:build windows\n\npackage teslrt\n\nimport (\n\t\"os\"\n\t\"unsafe\"\n\n\t\"golang.org/x/sys/windows\"\n)\n\n// Apply the protected current-user DACL at creation, before writing the token.\n// Chmod(0600) only controls the read-only attribute on Windows and is insufficient.\nfunc createPrivateDebugFile(path string) (*os.File, error) {\n\tuser, err := windows.GetCurrentProcessToken().GetTokenUser()\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tsd, err := windows.SecurityDescriptorFromString(\"D:P(A;;FA;;;\" + user.User.Sid.String() + \")\")\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tname, err := windows.UTF16PtrFromString(path)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tattributes := windows.SecurityAttributes{Length: uint32(unsafe.Sizeof(windows.SecurityAttributes{})), SecurityDescriptor: sd}\n\thandle, err := windows.CreateFile(name, windows.GENERIC_WRITE, 0, &attributes, windows.CREATE_NEW, windows.FILE_ATTRIBUTE_NORMAL, 0)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\treturn os.NewFile(uintptr(handle), path), nil\n}\n");
  ("debug_state.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"sort\"\n\t\"sync\"\n\t\"sync/atomic\"\n\t\"time\"\n)\n\ntype DebugDomainItem struct {\n\tName  string     `json:\"name\"`\n\tKind  string     `json:\"kind\"`\n\tType  string     `json:\"type,omitempty\"`\n\tValue DebugValue `json:\"value\"`\n}\n\ntype DebugDomainState struct {\n\tQueues  []DebugDomainItem `json:\"queues,omitempty\"`\n\tCaches  []DebugDomainItem `json:\"caches,omitempty\"`\n\tSSE     []DebugDomainItem `json:\"sse,omitempty\"`\n\tEmail   []DebugDomainItem `json:\"email,omitempty\"`\n\tWorkers []DebugDomainItem `json:\"workers,omitempty\"`\n}\n\ntype DebugSQLCapture struct {\n\tOperation string       `json:\"operation,omitempty\"`\n\tSQL       string       `json:\"sql\"`\n\tParams    []DebugValue `json:\"params,omitempty\"`\n\tTable     string       `json:\"table,omitempty\"`\n\tPreview   string       `json:\"preview,omitempty\"`\n\tRowCount  int          `json:\"row-count,omitempty\"`\n\tThisLine  bool         `json:\"this-line,omitempty\"`\n}\n\ntype DebugRuntimeState struct {\n\tDomain DebugDomainState `json:\"domain\"`\n\tSQL    *DebugSQLCapture `json:\"sql,omitempty\"`\n}\n\ntype DebugDomainProvider func() DebugDomainState\n\ntype debugProviderEntry struct {\n\tid       uint64\n\tprovider DebugDomainProvider\n}\n\nvar debugState = struct {\n\tsync.RWMutex\n\tproviders []debugProviderEntry\n\tsql       map[uint64]debugSQLCaptureEntry\n\tnextID    uint64\n}{sql: make(map[uint64]debugSQLCaptureEntry)}\n\ntype debugSQLCaptureEntry struct {\n\tid      uint64\n\tcapture *DebugSQLCapture\n}\n\nfunc RegisterDebugDomainProvider(provider DebugDomainProvider) func() {\n\tdebugState.Lock()\n\tdebugState.nextID++\n\tid := debugState.nextID\n\tdebugState.providers = append(debugState.providers, debugProviderEntry{id: id, provider: provider})\n\tdebugState.Unlock()\n\treturn func() {\n\t\tdebugState.Lock()\n\t\tfor index, registered := range debugState.providers {\n\t\t\tif registered.id == id {\n\t\t\t\tdebugState.providers = append(debugState.providers[:index], debugState.providers[index+1:]...)\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t\tdebugState.Unlock()\n\t}\n}\n\nfunc SetDebugSQLCapture(capture *DebugSQLCapture) {\n\tsetDebugSQLCapture(debugExecutionID(), capture)\n}\n\nfunc ClearDebugSQLCapture() {\n\tclearDebugSQLCaptureForExecution(debugExecutionID())\n}\n\nfunc DebugRuntimeStateSnapshot() DebugRuntimeState {\n\treturn debugRuntimeStateSnapshotForExecution(debugExecutionID())\n}\n\n// debugRuntimeStateSnapshotForExecution returns SQL state owned by one Tesl\n// execution. Domain providers are process-wide and are sampled only after the\n// debugger's cooperative execution barrier has completed.\nfunc debugRuntimeStateSnapshotForExecution(execution uint64) DebugRuntimeState {\n\tdebugState.RLock()\n\tproviders := append([]debugProviderEntry(nil), debugState.providers...)\n\tsql := cloneDebugSQL(debugState.sql[execution].capture)\n\tdebugState.RUnlock()\n\tstate := DebugRuntimeState{SQL: sql}\n\tfor _, provider := range providers {\n\t\tif provider.provider != nil {\n\t\t\tstate.Domain = mergeDebugDomainState(state.Domain, provider.provider())\n\t\t}\n\t}\n\treturn state\n}\n\nfunc setDebugSQLCapture(execution uint64, capture *DebugSQLCapture) uint64 {\n\tdebugState.Lock()\n\tdefer debugState.Unlock()\n\tif capture == nil {\n\t\tdelete(debugState.sql, execution)\n\t\treturn 0\n\t}\n\tdebugState.nextID++\n\tid := debugState.nextID\n\tdebugState.sql[execution] = debugSQLCaptureEntry{id: id, capture: cloneDebugSQL(capture)}\n\treturn id\n}\n\nfunc clearDebugSQLCaptureForExecution(execution uint64) {\n\tdebugState.Lock()\n\tdelete(debugState.sql, execution)\n\tdebugState.Unlock()\n}\n\nfunc updateDebugSQLCapture(execution, id uint64, rowCount int) {\n\tdebugState.Lock()\n\tentry, present := debugState.sql[execution]\n\tif present && entry.id == id {\n\t\tentry.capture.RowCount = rowCount\n\t\tdebugState.sql[execution] = entry\n\t}\n\tdebugState.Unlock()\n}\n\nfunc mergeDebugDomainState(left, right DebugDomainState) DebugDomainState {\n\tleft.Queues = append(left.Queues, cloneDebugDomainItems(right.Queues)...)\n\tleft.Caches = append(left.Caches, cloneDebugDomainItems(right.Caches)...)\n\tleft.SSE = append(left.SSE, cloneDebugDomainItems(right.SSE)...)\n\tleft.Email = append(left.Email, cloneDebugDomainItems(right.Email)...)\n\tleft.Workers = append(left.Workers, cloneDebugDomainItems(right.Workers)...)\n\treturn left\n}\n\nfunc cloneDebugDomainItems(items []DebugDomainItem) []DebugDomainItem {\n\tclone := make([]DebugDomainItem, len(items))\n\tfor index, item := range items {\n\t\tclone[index] = item\n\t\tclone[index].Value = cloneDebugValue(item.Value)\n\t}\n\treturn clone\n}\n\nfunc cloneDebugValue(value DebugValue) DebugValue {\n\tvalue.Children = cloneDebugValues(value.Children)\n\treturn value\n}\n\nfunc cloneDebugValues(values []DebugValue) []DebugValue {\n\tclone := make([]DebugValue, len(values))\n\tfor index, value := range values {\n\t\tclone[index] = cloneDebugValue(value)\n\t}\n\treturn clone\n}\n\nfunc cloneDebugSQL(capture *DebugSQLCapture) *DebugSQLCapture {\n\tif capture == nil {\n\t\treturn nil\n\t}\n\tclone := *capture\n\tclone.Params = cloneDebugValues(capture.Params)\n\treturn &clone\n}\n\nfunc debugValueOf(value any) DebugValue {\n\treturn DebugValue{Type: fmt.Sprintf(\"%T\", value), Display: fmt.Sprint(value)}\n}\n\nfunc RegisterDebugQueue(queue *Queue) func() {\n\treturn RegisterDebugDomainProvider(func() DebugDomainState {\n\t\tqueue.mutex.Lock()\n\t\tdefer queue.mutex.Unlock()\n\t\tjobs := make([]DebugValue, 0, len(queue.jobs))\n\t\tpending, dead := 0, 0\n\t\tordered := make([]*queuedJob, 0, len(queue.jobs))\n\t\tfor _, job := range queue.jobs {\n\t\t\tordered = append(ordered, job)\n\t\t}\n\t\tsort.Slice(ordered, func(left, right int) bool { return ordered[left].seq < ordered[right].seq })\n\t\tfor _, job := range ordered {\n\t\t\tif job.status == jobPending {\n\t\t\t\tpending++\n\t\t\t}\n\t\t\tif job.status == jobDead {\n\t\t\t\tdead++\n\t\t\t}\n\t\t\tjobs = append(jobs, DebugValue{Type: \"Job\", Display: fmt.Sprintf(\"%s \226\128\148 %s\", job.status, debugValueOf(job.payload).Display)})\n\t\t}\n\t\treturn DebugDomainState{Queues: []DebugDomainItem{{\n\t\t\tName: queue.name, Kind: \"queue\", Type: \"Queue\",\n\t\t\tValue: DebugValue{Type: \"Queue\", Display: fmt.Sprintf(\"%d pending, %d dead\", pending, dead), Children: jobs},\n\t\t}}}\n\t})\n}\n\nfunc RegisterDebugCache[V any](cache *Cache[V], name string) func() {\n\treturn RegisterDebugDomainProvider(func() DebugDomainState {\n\t\tcache.mutex.Lock()\n\t\tdefer cache.mutex.Unlock()\n\t\tchildren := make([]DebugValue, 0, len(cache.entries))\n\t\tnow := time.Now().Unix()\n\t\tfor key, entry := range cache.entries {\n\t\t\tif entry.expiresAt != 0 && now > entry.expiresAt {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tchildren = append(children, DebugValue{Type: \"CacheEntry\", Display: key + \" = \" + debugValueOf(entry.value).Display})\n\t\t}\n\t\tsort.Slice(children, func(left, right int) bool { return children[left].Display < children[right].Display })\n\t\treturn DebugDomainState{Caches: []DebugDomainItem{{\n\t\t\tName: name, Kind: \"cache\", Type: \"Cache\",\n\t\t\tValue: DebugValue{Type: \"Cache\", Display: fmt.Sprintf(\"%d entries\", len(children)), Children: children},\n\t\t}}}\n\t})\n}\n\nfunc RegisterDebugSSE(channel *SseChannel) func() {\n\treturn RegisterDebugDomainProvider(func() DebugDomainState {\n\t\tchannel.mutex.Lock()\n\t\tdefer channel.mutex.Unlock()\n\t\tchildren := make([]DebugValue, 0, len(channel.listeners))\n\t\tfor key, listeners := range channel.listeners {\n\t\t\tchildren = append(children, DebugValue{Type: \"SSEKey\", Display: fmt.Sprintf(\"%s: %d connected client(s)\", key, len(listeners))})\n\t\t}\n\t\tsort.Slice(children, func(left, right int) bool { return children[left].Display < children[right].Display })\n\t\treturn DebugDomainState{SSE: []DebugDomainItem{{\n\t\t\tName: channel.name, Kind: \"sse\", Type: \"SseChannel\",\n\t\t\tValue: DebugValue{Type: \"SseChannel\", Display: fmt.Sprintf(\"%d connected client(s)\", channel.active), Children: children},\n\t\t}}}\n\t})\n}\n\nfunc RegisterDebugOutbox(outbox *Outbox, name string) func() {\n\treturn RegisterDebugDomainProvider(func() DebugDomainState {\n\t\toutbox.mutex.Lock()\n\t\tdefer outbox.mutex.Unlock()\n\t\tchildren := make([]DebugValue, 0, len(outbox.messages))\n\t\tfor _, message := range outbox.messages {\n\t\t\tchildren = append(children, DebugValue{Type: \"Email\", Display: fmt.Sprintf(\"email -> %s [%d]\", message.Subject, message.Status)})\n\t\t}\n\t\treturn DebugDomainState{Email: []DebugDomainItem{{\n\t\t\tName: name, Kind: \"email\", Type: \"Outbox\",\n\t\t\tValue: DebugValue{Type: \"Outbox\", Display: fmt.Sprintf(\"%d messages\", len(children)), Children: children},\n\t\t}}}\n\t})\n}\n\nfunc RegisterDebugWorkers(queue *Queue, total int, dead bool) func() {\n\tpool := &debugWorkerPool{queue: queue, total: total, dead: dead}\n\treturn registerDebugWorkerPool(pool)\n}\n\ntype debugWorkerPool struct {\n\tqueue  *Queue\n\ttotal  int\n\tdead   bool\n\tactive atomic.Int64\n}\n\nfunc registerDebugWorkerPool(pool *debugWorkerPool) func() {\n\treturn RegisterDebugDomainProvider(func() DebugDomainState {\n\t\tlabel := pool.queue.name + \" workers\"\n\t\tif pool.dead {\n\t\t\tlabel = pool.queue.name + \" dead workers\"\n\t\t}\n\t\treturn DebugDomainState{Workers: []DebugDomainItem{{\n\t\t\tName: label, Kind: \"worker\", Type: \"WorkerPool\",\n\t\t\tValue: DebugValue{Type: \"WorkerPool\", Display: fmt.Sprintf(\"%d live / %d total\", pool.active.Load(), pool.total)},\n\t\t}}}\n\t})\n}\n\nfunc DebugStartWorkers(queue *Queue, handler func(any) JobOutcome, concurrency int, dead bool) struct{} {\n\tif concurrency < 1 {\n\t\tconcurrency = 1\n\t}\n\tpool := &debugWorkerPool{queue: queue, total: concurrency, dead: dead}\n\tremove := registerDebugWorkerPool(pool)\n\t_ = remove\n\treturn startWorkers(queue, handler, concurrency, dead, func(active bool) {\n\t\tif active {\n\t\t\tpool.active.Add(1)\n\t\t} else {\n\t\t\tpool.active.Add(-1)\n\t\t}\n\t})\n}\n");
  ("debug_sql.go", "package teslrt\n\nimport (\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n)\n\nfunc DebugPgSql(plan PgPlan) PgPlan {\n\tvar captures sync.Map\n\twrapped := PgPlan{\n\t\tSQL: plan.SQL,\n\t\tArgs: func() []any {\n\t\t\targuments := plan.arguments()\n\t\t\tparams := make([]DebugValue, len(arguments))\n\t\t\tfor index, argument := range arguments {\n\t\t\t\tparams[index] = debugValueOf(argument)\n\t\t\t}\n\t\t\toperation, table := debugSQLMetadata(plan.SQL)\n\t\t\texecution := debugExecutionID()\n\t\t\tcaptureID := setDebugSQLCapture(execution, &DebugSQLCapture{\n\t\t\t\tOperation: operation, SQL: plan.SQL, Params: params, Table: table,\n\t\t\t\tPreview: debugSQLPreview(plan.SQL, params),\n\t\t\t})\n\t\t\tcaptures.Store(execution, captureID)\n\t\t\treturn arguments\n\t\t},\n\t}\n\t// Plan executors defer Capture before entering the driver. LoadAndDelete therefore\n\t// consumes the mapping once on success or panic; a failed operation keeps row count zero.\n\twrapped.Capture = func(rowCount int) {\n\t\texecution := debugExecutionID()\n\t\tif captureID, present := captures.LoadAndDelete(execution); present {\n\t\t\tif id, valid := captureID.(uint64); valid {\n\t\t\t\tupdateDebugSQLCapture(execution, id, rowCount)\n\t\t\t}\n\t\t}\n\t}\n\t// The explaining probe rides along unchanged: it runs only on an empty result and is not\n\t// the statement the capture describes.\n\twrapped.Probe, wrapped.ProbeArgs = plan.Probe, plan.ProbeArgs\n\treturn wrapped\n}\nfunc debugSQLMetadata(statement string) (string, string) {\n\twords := strings.Fields(statement)\n\tif len(words) == 0 {\n\t\treturn \"\", \"\"\n\t}\n\toperation := strings.ToLower(strings.Trim(words[0], \"\\\"`;,()\"))\n\tfor index, word := range words {\n\t\tswitch strings.ToLower(strings.Trim(word, \"\\\"`;,()\")) {\n\t\tcase \"from\", \"into\", \"update\", \"table\":\n\t\t\tif index+1 < len(words) {\n\t\t\t\treturn operation, strings.Trim(words[index+1], \"\\\"`;,()\")\n\t\t\t}\n\t\t}\n\t}\n\treturn operation, \"\"\n}\n\nfunc debugSQLPreview(statement string, params []DebugValue) string {\n\tvar preview strings.Builder\n\tfor index := 0; index < len(statement); {\n\t\tif statement[index] != '$' {\n\t\t\tpreview.WriteByte(statement[index])\n\t\t\tindex++\n\t\t\tcontinue\n\t\t}\n\t\tend := index + 1\n\t\tfor end < len(statement) && statement[end] >= '0' && statement[end] <= '9' {\n\t\t\tend++\n\t\t}\n\t\tif end == index+1 {\n\t\t\tpreview.WriteByte(statement[index])\n\t\t\tindex++\n\t\t\tcontinue\n\t\t}\n\t\tparameter, err := strconv.Atoi(statement[index+1 : end])\n\t\tif err != nil || parameter < 1 || parameter > len(params) {\n\t\t\tpreview.WriteString(statement[index:end])\n\t\t\tindex = end\n\t\t\tcontinue\n\t\t}\n\t\tparam := params[parameter-1]\n\t\tliteral := \"'\" + strings.ReplaceAll(param.Display, \"'\", \"''\") + \"'\"\n\t\tpreview.WriteString(literal)\n\t\tindex = end\n\t}\n\treturn preview.String()\n}\n");
  ("debug_value.go", "package teslrt\n\n// Debug builds replace this no-op from debug.go. DebugValue remains available\n// in release emission, so HTTP lifecycle code can call the hook without taking\n// a dependency on debug-only runtime files.\nvar debugLifecycleQuiesce = func() func() { return func() {} }\n\n// DebugValue is the bounded, language-neutral value tree exchanged with debug clients.\n// The type is available to api-test runtime code without shipping the debug control machinery.\ntype DebugValue struct {\n\tName         string       `json:\"name,omitempty\"`\n\tEvaluateName string       `json:\"evaluateName,omitempty\"`\n\tType         string       `json:\"type\"`\n\tDisplay      string       `json:\"display\"`\n\tChildren     []DebugValue `json:\"children,omitempty\"`\n\tTruncated    bool         `json:\"truncated,omitempty\"`\n}\n");
  ("dict.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"slices\"\n)\n\n// Dict is Tesl's `Dict k v`, held as entries kept SORTED BY KEY.\n//\n// Two forces pick this representation over a Go map. First, a Go map cannot be keyed\n// by teslrt.Int at all \226\128\148 it is deliberately non-comparable \226\128\148 so a map would need an\n// emitter-supplied key encoding and would still store the original key alongside it.\n// Second, and more important: Go randomises map iteration order per run, while the\n// Racket backend iterates a hash whose order is unspecified but stable within a run\n// (tesl/dict.rkt uses `hash-keys` and `in-hash`, and says so: \"hash has no order\").\n// Emitting raw map order would therefore make a Tesl program's output differ between\n// runs of the SAME binary \226\128\148 strictly worse than the Racket behavior. Sorted order is\n// deterministic, reproducible, and a defensible reading of an operation the language\n// leaves unspecified.\n//\n// Costs, accepted: lookup is O(log n) rather than O(1), and insert is O(n) because a\n// Tesl Dict is immutable and every write copies (the same rule as List \226\128\148 see list.go).\n// Racket's persistent hash is asymptotically better; Tesl dicts are typically small\n// (headers, cookies, config) and this keeps the runtime auditable.\n//\n// Ordering is supplied by the emitter, which knows the concrete key type at every call\n// site \226\128\148 the same device used for list equality and sorting.\ntype Dict[K any, V any] struct {\n\tEntries []DictEntry[K, V]\n}\n\ntype DictEntry[K any, V any] struct {\n\tKey   K\n\tValue V\n}\n\nfunc DictEmpty[K any, V any]() Dict[K, V] {\n\treturn Dict[K, V]{}\n}\n\nfunc DictSize[K any, V any](d Dict[K, V]) Int {\n\treturn FromInt64(int64(len(d.Entries)))\n}\n\nfunc DictIsEmpty[K any, V any](d Dict[K, V]) bool {\n\treturn len(d.Entries) == 0\n}\n\n// dictSearch returns the entry index for key, and whether it was present.\nfunc dictSearch[K any, V any](d Dict[K, V], key K, less func(K, K) bool) (int, bool) {\n\treturn slices.BinarySearchFunc(d.Entries, key, func(entry DictEntry[K, V], key K) int {\n\t\tswitch {\n\t\tcase less(entry.Key, key):\n\t\t\treturn -1\n\t\tcase less(key, entry.Key):\n\t\t\treturn 1\n\t\tdefault:\n\t\t\treturn 0\n\t\t}\n\t})\n}\n\nfunc DictLookup[K any, V any](d Dict[K, V], key K, less func(K, K) bool) Maybe[V] {\n\tif index, found := dictSearch(d, key, less); found {\n\t\treturn Something(d.Entries[index].Value)\n\t}\n\treturn Nothing[V]()\n}\n\nfunc DictMember[K any, V any](d Dict[K, V], key K, less func(K, K) bool) bool {\n\t_, found := dictSearch(d, key, less)\n\treturn found\n}\n\n// DictInsert replaces any existing entry for key. It is a WRITER, so it allocates\n// rather than touching the caller's entries.\nfunc DictInsert[K any, V any](d Dict[K, V], key K, value V, less func(K, K) bool) Dict[K, V] {\n\tindex, found := dictSearch(d, key, less)\n\tif found {\n\t\tentries := make([]DictEntry[K, V], len(d.Entries))\n\t\tcopy(entries, d.Entries)\n\t\tentries[index] = DictEntry[K, V]{Key: key, Value: value}\n\t\treturn Dict[K, V]{Entries: entries}\n\t}\n\tentries := make([]DictEntry[K, V], 0, len(d.Entries)+1)\n\tentries = append(entries, d.Entries[:index]...)\n\tentries = append(entries, DictEntry[K, V]{Key: key, Value: value})\n\tentries = append(entries, d.Entries[index:]...)\n\treturn Dict[K, V]{Entries: entries}\n}\n\nfunc DictRemove[K any, V any](d Dict[K, V], key K, less func(K, K) bool) Dict[K, V] {\n\tindex, found := dictSearch(d, key, less)\n\tif !found {\n\t\treturn d\n\t}\n\tentries := make([]DictEntry[K, V], 0, len(d.Entries)-1)\n\tentries = append(entries, d.Entries[:index]...)\n\tentries = append(entries, d.Entries[index+1:]...)\n\treturn Dict[K, V]{Entries: entries}\n}\n\n// DictUnion is LEFT-BIASED: a key in both dicts keeps the left dict's value, which is what\n// `hash-union #:combine (lambda (_v2 v1) v1)` does in tesl/dict.rkt. Both operands are already\n// in key order, so this is a merge rather than a series of inserts \226\128\148 O(n+m) against O(n log m).\nfunc DictUnion[K any, V any](left, right Dict[K, V], less func(K, K) bool) Dict[K, V] {\n\tentries := make([]DictEntry[K, V], 0, len(left.Entries)+len(right.Entries))\n\tleftAt, rightAt := 0, 0\n\tfor leftAt < len(left.Entries) && rightAt < len(right.Entries) {\n\t\tleftKey := left.Entries[leftAt].Key\n\t\trightKey := right.Entries[rightAt].Key\n\t\tswitch {\n\t\tcase less(leftKey, rightKey):\n\t\t\tentries = append(entries, left.Entries[leftAt])\n\t\t\tleftAt++\n\t\tcase less(rightKey, leftKey):\n\t\t\tentries = append(entries, right.Entries[rightAt])\n\t\t\trightAt++\n\t\tdefault:\n\t\t\t// The same key on both sides: the left value wins, and the right one is dropped.\n\t\t\tentries = append(entries, left.Entries[leftAt])\n\t\t\tleftAt++\n\t\t\trightAt++\n\t\t}\n\t}\n\tentries = append(entries, left.Entries[leftAt:]...)\n\tentries = append(entries, right.Entries[rightAt:]...)\n\treturn Dict[K, V]{Entries: entries}\n}\n\n// sameKey is equality derived from the ordering the emitter supplies: neither key\n// orders before the other.\nfunc sameKey[K any](left, right K, less func(K, K) bool) bool {\n\treturn !less(left, right) && !less(right, left)\n}\n\n// DictKeys, DictValues, and DictToList all iterate in key order, so a Tesl program's\n// output does not depend on which backend ran it or on Go's map seed.\nfunc DictKeys[K any, V any](d Dict[K, V]) []K {\n\tkeys := make([]K, len(d.Entries))\n\tfor index, entry := range d.Entries {\n\t\tkeys[index] = entry.Key\n\t}\n\treturn keys\n}\n\nfunc DictValues[K any, V any](d Dict[K, V]) []V {\n\tvalues := make([]V, len(d.Entries))\n\tfor index, entry := range d.Entries {\n\t\tvalues[index] = entry.Value\n\t}\n\treturn values\n}\n\nfunc DictToList[K any, V any](d Dict[K, V]) []Tuple2[K, V] {\n\tpairs := make([]Tuple2[K, V], len(d.Entries))\n\tfor index, entry := range d.Entries {\n\t\tpairs[index] = Tuple2[K, V]{Tuple2First: entry.Key, Tuple2Second: entry.Value}\n\t}\n\treturn pairs\n}\n\n// DictFromList lets LATER duplicates win, matching tesl/dict.rkt's `for/hash`.\n//\n// Sorted once rather than inserted one at a time: n inserts would be O(n\194\178), where a\n// stable sort plus a dedup pass is O(n log n). Stability is what makes \"later wins\"\n// well defined \226\128\148 equal keys keep their input order, so the last of each run is the\n// one to keep.\nfunc DictFromList[K any, V any](pairs []Tuple2[K, V], less func(K, K) bool) Dict[K, V] {\n\tentries := make([]DictEntry[K, V], len(pairs))\n\tfor index, pair := range pairs {\n\t\tentries[index] = DictEntry[K, V]{Key: pair.Tuple2First, Value: pair.Tuple2Second}\n\t}\n\tslices.SortStableFunc(entries, func(left, right DictEntry[K, V]) int {\n\t\tswitch {\n\t\tcase less(left.Key, right.Key):\n\t\t\treturn -1\n\t\tcase less(right.Key, left.Key):\n\t\t\treturn 1\n\t\tdefault:\n\t\t\treturn 0\n\t\t}\n\t})\n\t// Compacts in place: `entries` was just allocated here, so nothing else can see it,\n\t// and each write lands at an index at or below the one being read.\n\tkept := entries[:0]\n\tfor index := 0; index < len(entries); index++ {\n\t\tlast := index\n\t\tfor last+1 < len(entries) && sameKey(entries[last].Key, entries[last+1].Key, less) {\n\t\t\tlast++\n\t\t}\n\t\tkept = append(kept, entries[last])\n\t\tindex = last\n\t}\n\treturn Dict[K, V]{Entries: kept}\n}\n\n// DictEqualBy compares two dicts entry by entry. Since both are kept in key order, a\n// single pass suffices \226\128\148 no lookup per key. Key and value comparisons are supplied by\n// the emitter, which knows both concrete types at the comparison site.\nfunc DictEqualBy[K any, V any](\n\tleft, right Dict[K, V], keyEqual func(K, K) bool, valueEqual func(V, V) bool,\n) bool {\n\tif len(left.Entries) != len(right.Entries) {\n\t\treturn false\n\t}\n\tfor index := range left.Entries {\n\t\tif !keyEqual(left.Entries[index].Key, right.Entries[index].Key) {\n\t\t\treturn false\n\t\t}\n\t\tif !valueEqual(left.Entries[index].Value, right.Entries[index].Value) {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n\n// stringKeyLess is the ordering a String-keyed Dict is built with \226\128\148 the comparator the emitter\n// passes at every `Dict.lookup` on String keys. It lives here rather than with the HTTP request\n// snapshot that first needed it: `Tesl.JWT`'s claims are a String-keyed Dict too, and a program\n// that signs a token need not serve HTTP.\nfunc stringKeyLess(left, right string) bool { return left < right }\n\n// DictSingleton is `Dict.singleton`: the one-entry dict, which is how a claims dict or a\n// single-key lookup table is usually written.\nfunc DictSingleton[K any, V any](key K, value V) Dict[K, V] {\n\treturn Dict[K, V]{Entries: []DictEntry[K, V]{{Key: key, Value: value}}}\n}\n\n// DictRequireKey is `check Dict.requireKey key d`: it answers the SAME dict, and what a caller\n// gains is the `HasKey` proof that makes `Dict.get` reachable. The proof erases here, so what\n// survives is the rejection \226\128\148 a 400, because a missing key in a request-shaped dict is bad input\n// rather than a broken program.\nfunc DictRequireKey[K any, V any](d Dict[K, V], key K, less func(K, K) bool) Check[Dict[K, V]] {\n\tif _, found := dictSearch(d, key, less); found {\n\t\treturn Accept(d)\n\t}\n\treturn Reject[Dict[K, V]](400, fmt.Sprintf(\"expected key %v to be present in Dict\", key))\n}\n\n// DictGet is `Dict.get`: the value for a key the caller has PROVEN present. The proof is what\n// makes it total, and it erases \226\128\148 so this traps rather than answering a zero value, which is the\n// only honest thing left if a caller ever reached it without the proof.\nfunc DictGet[K any, V any](d Dict[K, V], key K, less func(K, K) bool) V {\n\tif index, found := dictSearch(d, key, less); found {\n\t\treturn d.Entries[index].Value\n\t}\n\tpanic(fmt.Sprintf(\"Dict.get: key %v is not present \226\128\148 a `check Dict.requireKey` must prove it \"+\n\t\t\"first\", key))\n}\n");
  ("env.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"math/big\"\n\t\"os\"\n)\n\n// Reading the environment is an effect Tesl gates behind the `envRead` capability, which\n// the checker enforces; nothing about that survives to run time.\n//\n// An EMPTY variable counts as unset everywhere here, which is what `tesl/private/runtime.rkt`\n// does (`empty-string->false`): `FOO=` and an absent `FOO` are the same answer, so a blank\n// value in a deployment cannot look like a configured one.\nfunc envRaw(name string) (string, bool) {\n\tvalue := os.Getenv(name)\n\tif value == \"\" {\n\t\treturn \"\", false\n\t}\n\treturn value, true\n}\n\n// EnvMaybe is `env`: the value, or Nothing when unset.\nfunc EnvMaybe(name string) Maybe[string] {\n\tif value, ok := envRaw(name); ok {\n\t\treturn Something(value)\n\t}\n\treturn Nothing[string]()\n}\n\n// EnvString is `envString`: the value, or the fallback when unset.\nfunc EnvString(name, fallback string) string {\n\tif value, ok := envRaw(name); ok {\n\t\treturn value\n\t}\n\treturn fallback\n}\n\n// EnvInt is `envInt`: the value parsed as an exact integer, or the fallback when unset. A\n// SET-but-unparseable value is a configuration error and traps \226\128\148 it must not quietly become\n// the fallback, or a typo'd port would look like a deliberate default.\nfunc EnvInt(name string, fallback Int) Int {\n\tvalue, ok := envRaw(name)\n\tif !ok {\n\t\treturn fallback\n\t}\n\tparsed, valid := new(big.Int).SetString(value, 10)\n\tif !valid {\n\t\tpanic(fmt.Sprintf(\"envInt: invalid integer environment value %s=%s\", name, value))\n\t}\n\treturn fromBig(parsed)\n}\n\n// RequireEnv is `requireEnv`: the value, or a trap. An unset variable is a configuration\n// error, so it fails at the read rather than flowing on as an empty string.\nfunc RequireEnv(name string) string {\n\tvalue, ok := envRaw(name)\n\tif !ok {\n\t\tpanic(fmt.Sprintf(\"requireEnv: environment variable %s is not set (or is empty)\", name))\n\t}\n\treturn value\n}\n");
  ("either.go", "package teslrt\n\n// Either is Tesl's `Either a b`: Left carries the error-ish side, Right the value.\n// Like Maybe it lives in the runtime because an Either crosses module boundaries, and\n// it uses the same flat tag+payload shape the emitter generates for a user ADT.\n//\n// The zero value is a Left holding the zero value of A, matching the tag order below.\n// That is deliberate rather than incidental: a zero Either must not read as a Right\n// and hand out a fabricated value.\ntype Either[A any, B any] struct {\n\tTag        EitherTag\n\tLeftValue  A\n\tRightValue B\n}\n\n// EitherTag identifies which side an Either holds. The constants are an enum-like set\n// so the `exhaustive` linter can verify a switch over them.\ntype EitherTag int\n\nconst (\n\tEitherLeft EitherTag = iota\n\tEitherRight\n)\n\n// Left and Right exist for hand-written runtime code and readable tests; emitted code\n// writes the composite literal directly.\nfunc Left[A any, B any](value A) Either[A, B] {\n\treturn Either[A, B]{Tag: EitherLeft, LeftValue: value}\n}\n\nfunc Right[A any, B any](value B) Either[A, B] {\n\treturn Either[A, B]{Tag: EitherRight, RightValue: value}\n}\n\n// IsRight reports which side is held.\nfunc (e Either[A, B]) IsRight() bool {\n\treturn e.Tag == EitherRight\n}\n\n// EitherPartition splits a list of Either into its Left payloads and its Right payloads, in\n// input order, as `Either.partition` does in tesl/either.rkt. It answers the two lists as a\n// Tuple2 rather than two values, because Tesl has no multiple return.\nfunc EitherPartition[A any, B any](values []Either[A, B]) Tuple2[[]A, []B] {\n\tlefts := make([]A, 0, len(values))\n\trights := make([]B, 0, len(values))\n\tfor _, value := range values {\n\t\tif value.Tag == EitherRight {\n\t\t\trights = append(rights, value.RightValue)\n\t\t} else {\n\t\t\tlefts = append(lefts, value.LeftValue)\n\t\t}\n\t}\n\treturn Tuple2[[]A, []B]{Tuple2First: lefts, Tuple2Second: rights}\n}\n\n// The Either combinators, as tesl/either.tesl writes them. The ones taking a FUNCTION\n// (`map`, `mapLeft`, `andThen`) are emitted inline instead \226\128\148 the emitter inlines a callback\n// rather than passing a Go func value, which is the same rule the list leaves follow.\n\nfunc EitherIsLeft[A any, B any](value Either[A, B]) bool {\n\treturn value.Tag == EitherLeft\n}\n\nfunc EitherIsRight[A any, B any](value Either[A, B]) bool {\n\treturn value.Tag == EitherRight\n}\n\nfunc EitherFromLeft[A any, B any](value Either[A, B]) Maybe[A] {\n\tif value.Tag == EitherLeft {\n\t\treturn Something(value.LeftValue)\n\t}\n\treturn Nothing[A]()\n}\n\nfunc EitherFromRight[A any, B any](value Either[A, B]) Maybe[B] {\n\tif value.Tag == EitherRight {\n\t\treturn Something(value.RightValue)\n\t}\n\treturn Nothing[B]()\n}\n\n// EitherWithDefault takes the default FIRST, as the Tesl signature does.\nfunc EitherWithDefault[A any, B any](fallback B, value Either[A, B]) B {\n\tif value.Tag == EitherRight {\n\t\treturn value.RightValue\n\t}\n\treturn fallback\n}\n\n// EitherToMaybe forgets WHICH left it was: a Left becomes Nothing.\nfunc EitherToMaybe[A any, B any](value Either[A, B]) Maybe[B] {\n\tif value.Tag == EitherRight {\n\t\treturn Something(value.RightValue)\n\t}\n\treturn Nothing[B]()\n}\n\n// EitherFromMaybe supplies the left a Nothing has no value for.\nfunc EitherFromMaybe[A any, B any](leftValue A, value Maybe[B]) Either[A, B] {\n\tif value.Tag == MaybeSomething {\n\t\treturn Right[A, B](value.SomethingValue)\n\t}\n\treturn Left[A, B](leftValue)\n}\n");
  ("email.go", "package teslrt\n\nimport (\n\t\"crypto/tls\"\n\t\"fmt\"\n\t\"net\"\n\t\"net/smtp\"\n\t\"os\"\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n\t\"time\"\n)\n\n// `email E = Email { \226\128\166 }` and the two operations on it: `Email.send` and `startEmailWorker`.\n//\n// SENDING IS ENQUEUEING, not delivering. `Email.send` appends to an OUTBOX and returns; the\n// worker delivers. That is Racket's shape (its send writes a `tesl_email_outbox` row, or\n// appends to an in-memory list when no PostgreSQL runtime is bound) and it is the shape that\n// makes a handler's latency independent of the mail server's.\n//\n// The retry rule is Racket's too: at most 5 attempts, the next one no sooner than\n// 5 * 2^attempts minutes after the last \226\128\148 5, 10, 20, 40, 80. A message that exhausts them is\n// DEAD, not silently dropped: it stays in the outbox with that status, so it can be counted.\ntype EmailBodyTag int\n\nconst (\n\tEmailBodyText EmailBodyTag = iota\n\tEmailBodyHTML\n\tEmailBodyRich\n)\n\n// EmailBody is the `EmailBody(..)` ADT. It lives in the runtime for the reason Maybe does: it\n// crosses module boundaries, and two packages declaring their own would be different Go types.\n// The ADT is what makes a body-less email unconstructible \226\128\148 there is no variant for one.\ntype EmailBody struct {\n\tTag  EmailBodyTag\n\tText string\n\tHTML string\n}\n\nfunc TextBody(content string) EmailBody {\n\treturn EmailBody{Tag: EmailBodyText, Text: content}\n}\n\nfunc HTMLBody(content string) EmailBody {\n\treturn EmailBody{Tag: EmailBodyHTML, HTML: content}\n}\n\nfunc RichBody(text, html string) EmailBody {\n\treturn EmailBody{Tag: EmailBodyRich, Text: text, HTML: html}\n}\n\n// EmailStatus is where a message is in its life. A DEAD message is kept rather than dropped:\n// \"we gave up on this one\" is information the sender needs.\ntype EmailStatus int\n\nconst (\n\tEmailPending EmailStatus = iota\n\tEmailSent\n\tEmailDead\n)\n\ntype EmailMessage struct {\n\t// id is the message's identity inside its outbox \226\128\148 the counterpart of the\n\t// `tesl_email_outbox` row id. The worker records THIS across the unlocked delivery\n\t// window, never a slice index: a prune or a reset that runs while a message is on the\n\t// wire rebuilds the slice, and an index taken before that points at a different message\n\t// (or past the end) afterwards. Assigned by the outbox; zero means \"not yet\".\n\tid         uint64\n\tclaimToken string\n\tTo         string\n\tSubject    string\n\tBody       EmailBody\n\tStatus     EmailStatus\n\tAttempts   int\n\t// NextAttemptAt is when the worker may try again; zero means \"now\".\n\tNextAttemptAt time.Time\n\tSentAt        time.Time\n}\n\n// SmtpSettings is what the declaration's `smtp: SmtpConfig { \226\128\166 }` says.\ntype SmtpSettings struct {\n\tHost     string\n\tPort     int\n\tUsername string\n\tPassword string\n\tTLS      bool\n}\n\n// Outbox is one email declaration: its settings plus the messages waiting on them.\ntype Outbox struct {\n\tmutex    sync.Mutex\n\tsettings SmtpSettings\n\tmessages []EmailMessage\n\t// nextID is the last id handed out; ids start at 1 so a zero is always \"unassigned\".\n\tnextID uint64\n\t// started guards the worker, so a `startEmailWorker` called twice runs one.\n\tstarted bool\n\t// deliver is what the worker calls per message \226\128\148 DeliverEmail in production. A seam\n\t// rather than a direct call so the runtime's own tests can stand in a delivery that\n\t// stalls or traps without a network.\n\tdeliver func(SmtpSettings, EmailMessage) error\n\t// backend is the DURABLE outbox \226\128\148 the `tesl_email_outbox` table \226\128\148 when the declaration\n\t// names a Postgres-backed database (`NewOutboxOn` in pgstores.go attaches it); nil\n\t// otherwise. Each operation asks `durable()` and uses the in-memory slice above when the\n\t// backend is absent or its database is not bound, so a `test` block without\n\t// `with database` keeps the in-memory outbox and a served program gets the table.\n\tbackend outboxBackend\n}\n\n// outboxBackend is what a durable outbox answers. Like queueBackend it speaks this file's\n// vocabulary (EmailMessage values, an error per delivery) and names no driver type.\ntype outboxBackend interface {\n\tactive() bool\n\t// send stores a pending message. The CRLF check has already run.\n\tsend(message EmailMessage)\n\t// claimDue takes up to `limit` due pending messages for THIS process, so two instances\n\t// never deliver the same one; a claimed message another instance crashed on is released\n\t// after a fixed window.\n\tclaimDue(limit int) []EmailMessage\n\t// recordOutcome marks a claimed message sent, or counts a failed attempt with backoff\n\t// and, at emailMaxAttempts, dead.\n\trecordOutcome(message EmailMessage, err error) bool\n\tmessages() []EmailMessage\n\treset()\n\tprune(keep time.Duration)\n}\n\nfunc NewOutbox(settings SmtpSettings) *Outbox {\n\treturn &Outbox{settings: settings, deliver: DeliverEmail}\n}\n\n// durable answers the backend this call runs against, or nil for the in-memory path.\nfunc (outbox *Outbox) durable() outboxBackend {\n\tif backend := outbox.backend; backend != nil && backend.active() {\n\t\treturn backend\n\t}\n\treturn nil\n}\n\n// emailClaimBatch is one because the worker delivers serially: a row is claimed immediately\n// before its SMTP call, never left waiting behind other deliveries while its lease ages.\nconst emailClaimBatch = 1\n\n// emailMaxAttempts and the backoff below are tesl/email.rkt's, so a message that fails on one\n// backend is retried on the same schedule by the other.\nconst emailMaxAttempts = 5\n\nfunc emailRetryDelay(attempts int) time.Duration {\n\treturn time.Duration(5*(1<<attempts)) * time.Minute\n}\n\n// emailPollInterval is how often the worker looks for due messages \226\128\148 Racket's 5 seconds.\nconst emailPollInterval = 5 * time.Second\n\n// \226\148\128\226\148\128 Deadlines \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// The spec's rule is that EVERY outbound call has a deadline, so a hung upstream can never pin\n// a worker indefinitely. SMTP is an outbound call: a server that accepts the TCP connection and\n// never greets would otherwise block the (single) delivery goroutine forever, and with it every\n// message behind the stalled one. The knobs are the mail counterpart of the HTTP client's, with\n// the same defaults and the same shape (deployment tuning by environment variable, not a\n// per-call argument):\n//\n//\tTESL_SMTP_CONNECT_TIMEOUT_MS   10000   reaching the host\n//\tTESL_SMTP_TIMEOUT_MS           30000   the whole exchange: greeting through QUIT\n\nfunc smtpConnectTimeoutMs() int { return envPositiveInt(\"TESL_SMTP_CONNECT_TIMEOUT_MS\", 10000) }\nfunc smtpTimeoutMs() int        { return envPositiveInt(\"TESL_SMTP_TIMEOUT_MS\", 30000) }\n\n// HeaderFieldSafe reports whether a header-bound field may be used as it stands. A CR or LF in\n// a recipient or a subject would inject arbitrary RFC 2822 headers \226\128\148 Bcc exfiltration,\n// spoofing, a forged body \226\128\148 and both fields are user-influenced.\n//\n// Rejecting beats sanitising: a newline in either field is always a bug or an attack, and\n// stripping it would deliver a message the author did not write.\nfunc HeaderFieldSafe(value string) bool {\n\treturn !strings.ContainsAny(value, \"\\r\\n\")\n}\n\n// SendEmail enqueues one message. The CRLF guard runs HERE, at the boundary where the value\n// enters the system, rather than at delivery: a rejected message must never reach the outbox,\n// or it would sit there being retried.\nfunc SendEmail(outbox *Outbox, to, subject string, body EmailBody) struct{} {\n\tfor _, field := range []struct{ name, value string }{\n\t\t{\"recipient\", to}, {\"subject\", subject},\n\t} {\n\t\tif !HeaderFieldSafe(field.value) {\n\t\t\tpanic(\"email \" + field.name +\n\t\t\t\t\" contains a CR/LF newline \226\128\148 header injection rejected\")\n\t\t}\n\t}\n\tif backend := outbox.durable(); backend != nil {\n\t\t// The insert runs on the calling goroutine's open transaction when there is one\n\t\t// (the executor picks it up), which is what makes `Email.send` atomic with the\n\t\t// surrounding writes: a rolled-back handler leaves no row and sends no mail.\n\t\tbackend.send(EmailMessage{To: to, Subject: subject, Body: body, Status: EmailPending})\n\t\treturn struct{}{}\n\t}\n\toutbox.mutex.Lock()\n\tdefer outbox.mutex.Unlock()\n\toutbox.nextID++\n\toutbox.messages = append(outbox.messages, EmailMessage{\n\t\tid: outbox.nextID, To: to, Subject: subject, Body: body, Status: EmailPending,\n\t})\n\treturn struct{}{}\n}\n\n// StartEmailWorker starts delivery in the background: one goroutine polling every 5 seconds,\n// exactly as the Racket worker does, and a second one dropping sent messages older than 24\n// hours so a long-lived process does not accumulate them.\n//\n// Answers Tesl's Unit so the emitted `main` can return it like any other statement.\nfunc StartEmailWorker(outbox *Outbox) struct{} {\n\toutbox.mutex.Lock()\n\talready := outbox.started\n\toutbox.started = true\n\toutbox.mutex.Unlock()\n\tif already {\n\t\treturn struct{}{}\n\t}\n\tgo runEmailWorker(outbox, emailPollInterval, nil)\n\tgo func() {\n\t\tfor {\n\t\t\ttime.Sleep(time.Hour)\n\t\t\tpruneSentEmailGuarded(outbox, 24*time.Hour)\n\t\t}\n\t}()\n\treturn struct{}{}\n}\n\n// runEmailWorker is the delivery loop: every `interval` it tries the due messages once, and\n// it keeps going whatever happens inside an iteration. A `stop` of nil never fires, which is\n// the production shape; the runtime's tests pass a channel so the loop can be ended.\n//\n// The recover is per ITERATION and it is what keeps a mail problem a mail problem. This loop\n// runs on its own goroutine, and a panic on a goroutine that nothing recovers is fatal for the\n// whole process \226\128\148 the HTTP server, the queue workers, everything \226\128\148 not just for the message\n// that tripped it. Delivery itself already converts a trap into a failed attempt (see\n// deliverPending); this outer guard is for anything else, and it reports rather than swallows,\n// so a loop that keeps trapping is visible in the log.\nfunc runEmailWorker(outbox *Outbox, interval time.Duration, stop <-chan struct{}) {\n\tfor {\n\t\tselect {\n\t\tcase <-stop:\n\t\t\treturn\n\t\tcase <-time.After(interval):\n\t\t}\n\t\trunEmailWorkerIteration(outbox)\n\t}\n}\n\nfunc runEmailWorkerIteration(outbox *Outbox) {\n\tdefer func() {\n\t\tif trap := recover(); trap != nil {\n\t\t\tfmt.Fprintf(os.Stderr, \"tesl: email worker recovered from a trap: %v\\n\", trap)\n\t\t}\n\t}()\n\tdeliverPending(outbox)\n}\n\n// deliverPending takes every message whose next attempt is due and tries it once.\n//\n// The lock is NOT held across delivery \226\128\148 a message on the wire must not stall `Email.send` in\n// a request handler \226\128\148 and that is why the due messages are remembered by id. Between the\n// unlock and the re-lock, PruneSentEmail or ResetOutbox may have rebuilt the slice; a message\n// that is no longer there has its result dropped, since there is nothing left to attribute it\n// to, and a message that has moved is found where it now is rather than where it was.\nfunc deliverPending(outbox *Outbox) {\n\tif backend := outbox.durable(); backend != nil {\n\t\tdeliverClaimed(outbox, backend)\n\t\treturn\n\t}\n\toutbox.mutex.Lock()\n\tif outbox.settings.Host == \"\" {\n\t\t// No server configured \226\128\148 which is what an unset `SMTP_HOST` means. Messages STAY\n\t\t// pending rather than burning their five attempts against a host that does not\n\t\t// exist: the configuration is what is missing, not the mail.\n\t\toutbox.mutex.Unlock()\n\t\treturn\n\t}\n\tpending := []EmailMessage{}\n\tfor index := range outbox.messages {\n\t\tmessage := &outbox.messages[index]\n\t\tif message.Status != EmailPending || time.Now().Before(message.NextAttemptAt) {\n\t\t\tcontinue\n\t\t}\n\t\tif message.id == 0 {\n\t\t\t// A message placed in the store without going through SendEmail (the runtime's\n\t\t\t// own tests do this) still needs an identity to be found again by.\n\t\t\toutbox.nextID++\n\t\t\tmessage.id = outbox.nextID\n\t\t}\n\t\tpending = append(pending, *message)\n\t}\n\tsettings := outbox.settings\n\tdeliver := outbox.deliver\n\tif deliver == nil {\n\t\tdeliver = DeliverEmail\n\t}\n\toutbox.mutex.Unlock()\n\n\tfor _, message := range pending {\n\t\terr := deliverOne(deliver, settings, message)\n\t\toutbox.mutex.Lock()\n\t\trecord := outbox.lookupLocked(message.id)\n\t\tif record == nil {\n\t\t\t// Pruned or reset while on the wire: no row to write the outcome to. The failure\n\t\t\t// is still worth a line \226\128\148 it happened \226\128\148 but there is nothing to retry.\n\t\t\tif err != nil {\n\t\t\t\tfmt.Fprintf(os.Stderr, \"tesl: email delivery to %s failed (message no longer in the outbox): %v\\n\",\n\t\t\t\t\tmessage.To, err)\n\t\t\t}\n\t\t\toutbox.mutex.Unlock()\n\t\t\tcontinue\n\t\t}\n\t\tif err == nil {\n\t\t\trecord.Status = EmailSent\n\t\t\trecord.SentAt = time.Now()\n\t\t} else {\n\t\t\trecord.Attempts++\n\t\t\tif record.Attempts >= emailMaxAttempts {\n\t\t\t\trecord.Status = EmailDead\n\t\t\t} else {\n\t\t\t\trecord.NextAttemptAt = time.Now().Add(emailRetryDelay(record.Attempts))\n\t\t\t}\n\t\t\t// The failure is reported rather than swallowed: a worker that silently drops\n\t\t\t// every message looks identical to one with nothing to do.\n\t\t\tfmt.Fprintf(os.Stderr, \"tesl: email delivery to %s failed (attempt %d): %v\\n\",\n\t\t\t\trecord.To, record.Attempts, err)\n\t\t}\n\t\toutbox.mutex.Unlock()\n\t}\n}\n\n// deliverClaimed is deliverPending against the durable outbox: only messages this process\n// has CLAIMED are delivered, so several instances polling one table never send the same mail\n// twice, and each outcome is written back to the row rather than to a slice. The serial worker\n// claims one message immediately before delivery, so no later message spends another message's\n// SMTP timeout consuming its ownership window.\nfunc deliverClaimed(outbox *Outbox, backend outboxBackend) {\n\toutbox.mutex.Lock()\n\tsettings := outbox.settings\n\tdeliver := outbox.deliver\n\toutbox.mutex.Unlock()\n\tif settings.Host == \"\" {\n\t\t// Same rule as the in-memory path: no server configured means the messages wait.\n\t\treturn\n\t}\n\tif deliver == nil {\n\t\tdeliver = DeliverEmail\n\t}\n\tfor {\n\t\tclaimed := backend.claimDue(emailClaimBatch)\n\t\tfor _, message := range claimed {\n\t\t\t// Durable backends carry their lease identity on the message so recordOutcome\n\t\t\t// can fence this exact attempt. Keep the carrier observable in memory-only\n\t\t\t// emitted runtimes too, where the PostgreSQL implementation is omitted.\n\t\t\t_ = message.claimToken\n\t\t\terr := deliverOne(deliver, settings, message)\n\t\t\tapplied := backend.recordOutcome(message, err)\n\t\t\tif applied && err != nil {\n\t\t\t\tfmt.Fprintf(os.Stderr, \"tesl: email delivery to %s failed (attempt %d): %v\\n\",\n\t\t\t\t\tmessage.To, message.Attempts+1, err)\n\t\t\t}\n\t\t}\n\t\tif len(claimed) < emailClaimBatch {\n\t\t\treturn\n\t\t}\n\t}\n}\n\n// lookupLocked finds the message with `id`, or nil when it is gone. Caller holds the mutex;\n// the pointer is into the slice and is only valid until the mutex is released.\nfunc (outbox *Outbox) lookupLocked(id uint64) *EmailMessage {\n\tif id == 0 {\n\t\treturn nil\n\t}\n\tfor index := range outbox.messages {\n\t\tif outbox.messages[index].id == id {\n\t\t\treturn &outbox.messages[index]\n\t\t}\n\t}\n\treturn nil\n}\n\n// deliverOne runs one delivery and answers a trap as an ERROR, so a panicking delivery is a\n// failed attempt \226\128\148 counted, backed off, eventually dead \226\128\148 and not the end of the worker.\nfunc deliverOne(deliver func(SmtpSettings, EmailMessage) error, settings SmtpSettings, message EmailMessage) (err error) {\n\tdefer func() {\n\t\tif trap := recover(); trap != nil {\n\t\t\terr = fmt.Errorf(\"email delivery trapped: %v\", trap)\n\t\t}\n\t}()\n\treturn deliver(settings, message)\n}\n\n// DeliverEmail sends ONE message over SMTP, building the same minimal RFC 2822 header the\n// Racket runtime builds \226\128\148 From/To/Subject/MIME-Version plus a content type chosen by which\n// half of the body is present, so an HTML body arrives as HTML.\nfunc DeliverEmail(settings SmtpSettings, message EmailMessage) error {\n\tif !HeaderFieldSafe(message.To) || !HeaderFieldSafe(message.Subject) {\n\t\treturn fmt.Errorf(\"email header contains a CR/LF newline\")\n\t}\n\t// Which half is sent is decided by the VARIANT, not by which string happens to be\n\t// non-empty: an `HtmlBody \"\"` is still an HTML message, and asking the payload would\n\t// silently retype it as text.\n\tcontentType := \"text/plain; charset=utf-8\"\n\tpayload := message.Body.Text\n\tif message.Body.Tag == EmailBodyHTML || message.Body.Tag == EmailBodyRich {\n\t\tcontentType = \"text/html; charset=utf-8\"\n\t\tpayload = message.Body.HTML\n\t}\n\theader := \"From: \" + settings.Username + \"\\r\\n\" +\n\t\t\"To: \" + message.To + \"\\r\\n\" +\n\t\t\"Subject: \" + message.Subject + \"\\r\\n\" +\n\t\t\"MIME-Version: 1.0\\r\\n\" +\n\t\t\"Content-Type: \" + contentType + \"\\r\\n\"\n\taddress := net.JoinHostPort(settings.Host, strconv.Itoa(settings.Port))\n\n\t// Not `smtp.Dial`: it has no deadline of any kind. The connection is dialed with the\n\t// connect timeout and then given ONE absolute deadline for the whole exchange, so a server\n\t// that accepts and never greets, or stalls halfway through DATA, hands back an i/o timeout\n\t// error \226\128\148 which the worker treats like any other failed attempt. The deadline is on the\n\t// raw connection, so it also covers the STARTTLS handshake layered over it.\n\tconn, err := net.DialTimeout(\"tcp\", address, millisDuration(smtpConnectTimeoutMs()))\n\tif err != nil {\n\t\treturn err\n\t}\n\tif err := conn.SetDeadline(time.Now().Add(millisDuration(smtpTimeoutMs()))); err != nil {\n\t\t_ = conn.Close()\n\t\treturn err\n\t}\n\tclient, err := smtp.NewClient(conn, settings.Host)\n\tif err != nil {\n\t\t_ = conn.Close()\n\t\treturn err\n\t}\n\tdefer func() { _ = client.Close() }()\n\tif settings.TLS {\n\t\t// STARTTLS with the server's own name verified: skipping verification here would\n\t\t// make the encryption decorative, since anything on the path could terminate it.\n\t\tif err := client.StartTLS(&tls.Config{\n\t\t\tServerName: settings.Host,\n\t\t\tMinVersion: tls.VersionTLS12,\n\t\t}); err != nil {\n\t\t\treturn err\n\t\t}\n\t}\n\t// Authenticate only when the server ASKS for it. A server that advertises no AUTH would\n\t// reject the command, and failing there would mean a relay that needs no credentials\n\t// could never be used.\n\t//\n\t// `smtp.PlainAuth` refuses to hand over the password on an unencrypted connection\n\t// (localhost aside). That is a deliberate floor and not worked around here: a credential\n\t// sent in the clear is readable by everything on the path.\n\tif supported, _ := client.Extension(\"AUTH\"); supported && settings.Username != \"\" {\n\t\tauth := smtp.PlainAuth(\"\", settings.Username, settings.Password, settings.Host)\n\t\tif err := client.Auth(auth); err != nil {\n\t\t\treturn err\n\t\t}\n\t}\n\tif err := client.Mail(settings.Username); err != nil {\n\t\treturn err\n\t}\n\tif err := client.Rcpt(message.To); err != nil {\n\t\treturn err\n\t}\n\twriter, err := client.Data()\n\tif err != nil {\n\t\treturn err\n\t}\n\tif _, err := writer.Write([]byte(header + \"\\r\\n\" + payload)); err != nil {\n\t\t_ = writer.Close()\n\t\treturn err\n\t}\n\tif err := writer.Close(); err != nil {\n\t\treturn err\n\t}\n\treturn client.Quit()\n}\n\n// PruneSentEmail drops delivered messages older than `keep`.\n// pruneSentEmailGuarded is the background pruner's call: on a durable outbox the prune is a\n// statement, and a database that is unreachable at that moment must not unwind this\n// goroutine \226\128\148 an unrecovered panic here ended the whole process (the same class as the\n// queue worker's store failure). Reported, and retried an hour later.\nfunc pruneSentEmailGuarded(outbox *Outbox, keep time.Duration) {\n\tdefer func() {\n\t\tif trap := recover(); trap != nil {\n\t\t\tfmt.Fprintf(os.Stderr, \"tesl: email pruner could not reach the outbox store: %v\\n\", trap)\n\t\t}\n\t}()\n\tPruneSentEmail(outbox, keep)\n}\n\nfunc PruneSentEmail(outbox *Outbox, keep time.Duration) {\n\tif backend := outbox.durable(); backend != nil {\n\t\tbackend.prune(keep)\n\t\treturn\n\t}\n\toutbox.mutex.Lock()\n\tdefer outbox.mutex.Unlock()\n\t// A FRESH slice rather than `outbox.messages[:0]`: reusing the backing array aliases the\n\t// store with a value that has already been read out of it, and nilaway reads the reuse as\n\t// a nil flow into the field.\n\tkept := make([]EmailMessage, 0, len(outbox.messages))\n\tfor _, message := range outbox.messages {\n\t\tif message.Status == EmailSent && time.Since(message.SentAt) > keep {\n\t\t\tcontinue\n\t\t}\n\t\tkept = append(kept, message)\n\t}\n\toutbox.messages = kept\n}\n\n// \226\148\128\226\148\128 Inspection seams \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// Not Tesl-surface names: they exist so the runtime's own tests can assert what was enqueued,\n// and so the per-test reset can empty an outbox the way it empties a table.\n\nfunc OutboxMessages(outbox *Outbox) []EmailMessage {\n\tif backend := outbox.durable(); backend != nil {\n\t\treturn backend.messages()\n\t}\n\toutbox.mutex.Lock()\n\tdefer outbox.mutex.Unlock()\n\tout := make([]EmailMessage, len(outbox.messages))\n\tcopy(out, outbox.messages)\n\treturn out\n}\n\nfunc ResetOutbox(outbox *Outbox) {\n\tif backend := outbox.durable(); backend != nil {\n\t\tbackend.reset()\n\t\treturn\n\t}\n\toutbox.mutex.Lock()\n\tdefer outbox.mutex.Unlock()\n\t// An EMPTY slice, not nil: the field is read by every other operation, and a nil there is\n\t// a nil flow into all of them as far as nilaway is concerned.\n\toutbox.messages = []EmailMessage{}\n}\n");
  ("float.go", "package teslrt\n\nimport (\n\t\"math\"\n\t\"strconv\"\n)\n\n// Tesl's Float is Go's float64. Two things about it are NOT the Go default, and both\n// are decided in roadmap/next/migrate_to_golang.md (\"Float decisions\"):\n//\n//   - Rendering adopts Go's shortest-round-trip digits and layout, plus one deviation:\n//     a `.0` is appended when the result carries neither `.` nor `e`. Tesl has both\n//     arbitrary-precision Int and Float, so a bare `1` would make the two\n//     indistinguishable in logs, interpolation, and test expectations.\n//   - Equality is STRUCTURAL, not IEEE: NaN equals NaN and 0.0 does not equal -0.0,\n//     matching Racket's `equal?`. IEEE `==` is not an equivalence relation, which\n//     would cost a record or Dict key holding NaN its own reflexivity. Postgres\n//     independently agrees that NaN = NaN.\n//\n// Ordering, by contrast, IS plain IEEE in both backends, so it needs no helper here.\nfunc FormatFloat(value float64) string {\n\tswitch {\n\tcase math.IsNaN(value):\n\t\treturn \"NaN\"\n\tcase math.IsInf(value, 1):\n\t\treturn \"+Inf\"\n\tcase math.IsInf(value, -1):\n\t\treturn \"-Inf\"\n\t}\n\trendered := strconv.FormatFloat(value, 'g', -1, 64)\n\tfor index := 0; index < len(rendered); index++ {\n\t\tif rendered[index] == '.' || rendered[index] == 'e' {\n\t\t\treturn rendered\n\t\t}\n\t}\n\treturn rendered + \".0\"\n}\n\n// FloatEqual is Racket `equal?` on flonums: reflexive for NaN, and distinguishing the\n// two zeros. Both differ from Go's `==`.\nfunc FloatEqual(left, right float64) bool {\n\tif math.IsNaN(left) || math.IsNaN(right) {\n\t\treturn math.IsNaN(left) && math.IsNaN(right)\n\t}\n\tif left == 0 && right == 0 {\n\t\treturn math.Signbit(left) == math.Signbit(right)\n\t}\n\treturn left == right\n}\n\n// FloatKeyLess is the ordering Dict and Set use for Float KEYS, and it is deliberately\n// NOT the IEEE ordering that user-visible comparisons and List.sort use.\n//\n// Dict and Set are sorted, so their binary search derives key equivalence from the\n// comparator: \"neither side is less\" means \"same key\". Native `<` breaks that in two\n// ways, and both are real lookup bugs rather than output-order quirks:\n//\n//   - Every comparison involving NaN is false, so a NaN key looks equivalent to whatever\n//     value the search happens to probe. `SetMember(NaN, {1,2,3})` returned TRUE with the\n//     native comparator, and inserting NaN was a no-op.\n//   - Native ordering treats -0.0 and +0.0 as equal, while FloatEqual deliberately\n//     distinguishes them, so the two collapsed into one key.\n//\n// The law this function must satisfy, and which float_test.go checks exhaustively:\n//\n//\tFloatEqual(a, b)  ==  !FloatKeyLess(a, b) && !FloatKeyLess(b, a)\n//\n// All NaNs form ONE key-equivalence class (matching FloatEqual) and sort before every\n// number; -0.0 sorts immediately before +0.0. Where the NaN class sits is internal and is\n// not Tesl language semantics \226\128\148 only the equivalence classes are.\nfunc FloatKeyLess(left, right float64) bool {\n\tleftIsNaN, rightIsNaN := math.IsNaN(left), math.IsNaN(right)\n\tif leftIsNaN || rightIsNaN {\n\t\treturn leftIsNaN && !rightIsNaN\n\t}\n\tif left == right {\n\t\t// Only -0.0 and +0.0 reach here as distinct values.\n\t\treturn math.Signbit(left) && !math.Signbit(right)\n\t}\n\treturn left < right\n}\n\n// FloatKey is a COMPARABLE key whose equality is exactly `FloatEqual`'s, so a map keyed by it\n// answers the same question the language's `==` answers.\n//\n// Neither the value nor its raw bits will do. `float64` as a map key makes -0.0 and +0.0 the same\n// key (the language distinguishes them) and every NaN a distinct one (the language makes all NaNs\n// equal). Raw bits fix the first and worsen the second \226\128\148 two NaNs with different payloads are\n// different bit patterns. So NaN collapses to ONE sentinel and everything else keeps its bits.\nfunc FloatKey(value float64) uint64 {\n\tif math.IsNaN(value) {\n\t\t// A quiet NaN with a zero payload: one canonical key for every NaN, and not a value any\n\t\t// non-NaN float can produce.\n\t\treturn math.Float64bits(math.NaN())\n\t}\n\treturn math.Float64bits(value)\n}\n\n// ParseFloat accepts what Tesl's `Float.parse` accepts: a decimal float, with no\n// leading or trailing space and no Racket reader syntax.\nfunc ParseFloat(text string) Maybe[float64] {\n\tvalue, err := strconv.ParseFloat(text, 64)\n\tif err != nil {\n\t\treturn Nothing[float64]()\n\t}\n\treturn Something(value)\n}\n\nfunc FloatAbs(value float64) float64 {\n\treturn math.Abs(value)\n}\n\n// FloatMin and FloatMax propagate NaN and distinguish the zeros, matching Racket's\n// `min`/`max` on flonums rather than Go's built-in min/max.\nfunc FloatMin(left, right float64) float64 {\n\treturn math.Min(left, right)\n}\n\nfunc FloatMax(left, right float64) float64 {\n\treturn math.Max(left, right)\n}\n\n// FloatFloor, FloatCeil, and FloatRound return an INT, not a Float: tesl/float.rkt\n// wraps each in `inexact->exact`, and their declared Tesl signatures are\n// `Float -> Int`. FloatRound rounds HALF TO EVEN, because that is what Racket's\n// `round` does on a flonum \226\128\148 `math.Round` would round half away from zero and disagree\n// on every exact .5.\n//\n// NaN and infinity have no integer value. Racket RAISES there (`inexact->exact` has no\n// exact representation for them) and the declared Tesl signature is `Float -> Int`\n// rather than `-> Maybe Int`, so these panic rather than inventing a value or widening\n// the type.\nfunc FloatFloor(value float64) Int {\n\treturn mustExactInt(\"Float.floor\", math.Floor(value))\n}\n\nfunc FloatCeil(value float64) Int {\n\treturn mustExactInt(\"Float.ceil\", math.Ceil(value))\n}\n\nfunc FloatRound(value float64) Int {\n\treturn mustExactInt(\"Float.round\", math.RoundToEven(value))\n}\n\nfunc mustExactInt(who string, value float64) Int {\n\tconverted, err := FromFloat64(value)\n\tif err != nil {\n\t\tpanic(who + \": no exact integer for NaN or infinity\")\n\t}\n\treturn converted\n}\n\nfunc FloatClamp(value, low, high float64) float64 {\n\treturn math.Max(low, math.Min(high, value))\n}\n\n// FloatSqrt is bit-identical to Racket's, since both defer to the IEEE-exact\n// operation. The other transcendentals are NOT: they are rejected in the emitter\n// rather than emitted divergent.\nfunc FloatSqrt(value float64) float64 {\n\treturn math.Sqrt(value)\n}\n\n// FloatPow answers NaN wherever the result has no REAL value, which is every negative base with\n// a non-integer exponent. Racket's `expt` returns a COMPLEX number there \226\128\148 a value no Tesl Float\n// can hold, and a bug this port found in `tesl/float.rkt` (fixed to answer NaN as well).\n//\n// The guard is not decoration: C's `pow`, which `math.Pow` follows, makes two deliberate\n// exceptions \226\128\148 `pow(-1, \194\177Inf)` is 1 and `pow(-4, +Inf)` is +Inf \226\128\148 on the grounds that \194\177Inf is\n// \"even\". A Tesl Float is a real number and (-1)^\226\136\158 has no real value, so those answer NaN here\n// too, and the two backends agree at every input rather than at most of them.\nfunc FloatPow(base, exponent float64) float64 {\n\tnonInteger := math.IsInf(exponent, 0) || math.IsNaN(exponent) ||\n\t\texponent != math.Trunc(exponent)\n\tif base < 0 && nonInteger {\n\t\treturn math.NaN()\n\t}\n\treturn math.Pow(base, exponent)\n}\n\n// FloatFromInt is exact up to 2^53 and rounds beyond it, like Racket's exact->inexact.\nfunc FloatFromInt(value Int) float64 {\n\treturn value.Float64()\n}\n\n// FloatToInt truncates toward zero. NaN and infinity are not integers, so this\n// mirrors Int.fromFloat by refusing them.\nfunc FloatToInt(value float64) Maybe[Int] {\n\tconverted, err := FromFloat64(value)\n\tif err != nil {\n\t\treturn Nothing[Int]()\n\t}\n\treturn Something(converted)\n}\n\n// FloatRequireNonZero is Tesl's `Float.requireNonZero` check: the proof erases, the\n// rejection does not. Negative zero is zero.\nfunc FloatRequireNonZero(value float64) Check[float64] {\n\tif value == 0 {\n\t\treturn Reject[float64](400, \"expected a non-zero float\")\n\t}\n\treturn Accept(value)\n}\n\n// FloatToIntTruncating is Tesl's `Float.toInt`, whose declared signature is\n// `Float -> Int`: it truncates toward zero and panics on NaN or infinity, exactly where\n// Racket's `inexact->exact` raises. FloatToInt above is the Maybe-returning form used\n// by hand-written runtime code.\nfunc FloatToIntTruncating(value float64) Int {\n\treturn mustExactInt(\"Float.toInt\", math.Trunc(value))\n}\n\n// FloatRequireNonNegative is Tesl's `Float.requireNonNegative`, the check that\n// discharges `Float.sqrt`'s FloatNonNegative obligation. Zero is accepted: sqrt(0) is\n// 0, so requiring strict positivity would reject a well-defined call.\nfunc FloatRequireNonNegative(value float64) Check[float64] {\n\tif math.IsNaN(value) || value < 0 {\n\t\treturn Reject[float64](422, \"expected a non-negative float\")\n\t}\n\treturn Accept(value)\n}\n\n// The Float ARITHMETIC surface (`Float.add` and friends), for code that prefers named\n// operations to operators. Plain IEEE arithmetic \226\128\148 the same thing `a + b` emits.\nfunc FloatAdd(left, right float64) float64 { return left + right }\n\nfunc FloatSub(left, right float64) float64 { return left - right }\n\nfunc FloatMul(left, right float64) float64 { return left * right }\n\n// FloatDiv's divisor carries a `FloatNonZero` proof, which erases; division by zero would\n// otherwise be \194\177Inf, which is what Racket's `/` on a flonum gives too. No guard is added\n// here: adding one would make the emitted program behave differently from `a / b`, and the\n// proof is the enforcement.\nfunc FloatDiv(left, right float64) float64 { return left / right }\n\n// The predicates. NaN is its own case in every one of them: `Float.isNaN x` is the only way to\n// ask, because every comparison with NaN is false \226\128\148 which is exactly why `isPositive`,\n// `isNegative` and `isZero` all answer false for it rather than one of them accidentally\n// answering true.\nfunc FloatIsNaN(value float64) bool { return math.IsNaN(value) }\n\nfunc FloatIsInfinite(value float64) bool { return math.IsInf(value, 0) }\n\nfunc FloatIsPositive(value float64) bool { return value > 0 }\n\nfunc FloatIsNegative(value float64) bool { return value < 0 }\n\nfunc FloatIsZero(value float64) bool { return value == 0 }\n\n// FloatSign answers a FLOAT (1.0, -1.0, 0.0), not an Int: it composes with float arithmetic,\n// which is what a sign is used for. NaN has no sign, and answering 0.0 for it would claim it is\n// zero \226\128\148 so it answers NaN, which propagates the way every other NaN operation does.\nfunc FloatSign(value float64) float64 {\n\tswitch {\n\tcase math.IsNaN(value):\n\t\treturn value\n\tcase value > 0:\n\t\treturn 1.0\n\tcase value < 0:\n\t\treturn -1.0\n\tdefault:\n\t\treturn 0.0\n\t}\n}\n\n// FloatInfinity and FloatNaN are the two named constants. They are functions rather than package\n// variables so nothing can assign to them.\nfunc FloatInfinity() float64 { return math.Inf(1) }\n\nfunc FloatNaN() float64 { return math.NaN() }\n\n// \226\148\128\226\148\128 The transcendentals \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// These forward to Go's `math`, and they DIVERGE from the Racket runtime: sin, cos and tan\n// differ on 22 %, 22 % and 34 % of inputs respectively (up to 9,214 ulps near a zero of the\n// function), and exp on 0.09 %. That divergence rate says the two implementations differ,\n// not which is right \226\128\148 ulp-of-result exaggerates a small absolute error near a zero \226\128\148 and\n// deciding needs a correctly-rounded reference rather than a diff against Racket. The\n// maintainer's call (2026-08-12) is to use Go's and record the divergence, not to block on\n// it, so a program that computes a sine gets an answer here instead of a refusal.\n//\n// FloatLog is the one that does NOT forward, because Go's math.Log is wrong rather than\n// merely different; see its own note.\n\nfunc FloatSin(value float64) float64 { return math.Sin(value) }\n\nfunc FloatCos(value float64) float64 { return math.Cos(value) }\n\nfunc FloatTan(value float64) float64 { return math.Tan(value) }\n\nfunc FloatExp(value float64) float64 { return math.Exp(value) }\n\n// FloatLog wraps math.Log rather than forwarding to it. Go's returns\n// -709.0895657128241 for EVERY subnormal input \226\128\148 Log(5e-324) and Log(2.5e-323) give the\n// same answer, and both are wrong (the true values are about -744.44 and -742.83). Scaling\n// a subnormal into the normal range and subtracting the scale back out reproduces both\n// exactly. Everything else forwards unchanged.\nfunc FloatLog(value float64) float64 {\n\tif value > 0 && value < smallestNormalFloat {\n\t\treturn math.Log(value*subnormalLogScale) - subnormalLogShift\n\t}\n\treturn math.Log(value)\n}\n\nconst (\n\t// The smallest positive NORMAL float64: below this the mantissa loses bits, which is\n\t// exactly where math.Log stops distinguishing inputs.\n\tsmallestNormalFloat = 2.2250738585072014e-308\n\t// 2^100, and 100\194\183ln2 \226\128\148 the scale up and the amount to take back off.\n\tsubnormalLogScale = 1267650600228229401496703205376.0\n\tsubnormalLogShift = 69.31471805599453\n)\n");
  ("hostclass.go", "package teslrt\n\nimport (\n\t\"net\"\n\t\"os\"\n\t\"strconv\"\n\t\"strings\"\n)\n\n// Address-range classification \226\128\148 the decision behind SSRF egress containment.\n//\n// The dangerous SSRF targets (cloud metadata at 169.254.169.254, RFC1918, CGNAT,\n// unique-local, link-local, 0.0.0.0/8, and the IETF-reserved IPv4 blocks that are never\n// routed on the public Internet) are refused for every outbound call, judged by the\n// address actually CONNECTED TO rather than by the hostname: `evil.example.com` can resolve\n// to 127.0.0.1 or to the metadata address, so a name check decides nothing.\n//\n// The range table is deliberately a copy of ONE Racket table\n// (`dsl/private/host-classify.rkt`), including the refusal wording, because a `.tesl`\n// application asking `Net.isForbiddenHost` and the runtime refusing to dial must agree\n// about what \"private\" means. The counterpart to `Tesl.Net`'s full host normalization \226\128\148\n// the `inet_aton` spellings (`2130706433`, `0x7f.0.0.1`) and DNS-name syntax \226\128\148 is not here:\n// this entry point judges an address a resolver already produced, and a spelling that\n// cannot be parsed is refused rather than guessed at.\n//\n// FAIL CLOSED: anything not recognizable as a public, routable address is refused.\ntype addressClass int\n\nconst (\n\tclassInvalid addressClass = iota\n\tclassPublic\n\tclassLoopback\n\tclassUnspecified\n\tclassLinkLocal\n\tclassPrivate\n\tclassCGNAT\n\tclassMulticast\n\tclassReserved\n)\n\n// classifyAddress parses a bare address (an IPv6 zone id is tolerated and dropped) and\n// answers its class along with whether it denotes an IPv4 address. An IPv6 spelling that\n// EMBEDS an IPv4 address (mapped, compatible, NAT64, 6to4) denotes that IPv4 address \226\128\148 the\n// fold is the classic bypass, so it happens before classification, never after.\nfunc classifyAddress(raw string) (addressClass, bool) {\n\tclass, v4 := classifyParsed(raw)\n\treturn class, v4 != nil\n}\n\n// classifyParsed is classifyAddress plus the IPv4 address the verdict was reached on (nil\n// for a native IPv6 address or an unparseable one), so the label functions below name the\n// block the FOLDED address falls in rather than re-parsing the spelling.\nfunc classifyParsed(raw string) (addressClass, net.IP) {\n\ttext := strings.ToLower(strings.TrimSpace(raw))\n\tif zone := strings.IndexByte(text, '%'); zone >= 0 {\n\t\ttext = text[:zone]\n\t}\n\taddress := net.ParseIP(text)\n\tif address == nil {\n\t\treturn classInvalid, nil\n\t}\n\tif v4 := embeddedIPv4(address); v4 != nil {\n\t\treturn ipv4Class(v4), v4\n\t}\n\tif v4 := address.To4(); v4 != nil {\n\t\treturn ipv4Class(v4), v4\n\t}\n\treturn ipv6Class(address.To16()), nil\n}\n\n// embeddedIPv4 answers the IPv4 address an IPv6 literal embeds, or nil.\n//\n// `net.IP.To4` already folds the IPv4-mapped form (`::ffff:a.b.c.d`). The others reach the\n// same IPv4 host through a translator or a tunnel, so a classifier that judged them as IPv6\n// (all \"public\") would let `64:ff9b::a9fe:a9fe` reach the metadata service on any host with\n// a NAT64 path:\n//\n//\t::a.b.c.d            the deprecated IPv4-COMPATIBLE form (RFC 4291 \194\1672.5.5.1);\n//\t64:ff9b::/96         the NAT64 well-known prefix (RFC 6052 \194\1672.1), IPv4 in the last 32 bits;\n//\t64:ff9b:1::/48       the NAT64 local-use prefix (RFC 8215); translators carve /96s out of\n//\t                     it, so the last 32 bits are the IPv4 address there too;\n//\t2002::/16            6to4 (RFC 3056), IPv4 in bits 16..47.\n//\n// `::` and `::1` are their own addresses and are NOT folded \226\128\148 otherwise the IPv6 loopback\n// would be classified through the 0.0.0.0/8 branch.\nfunc embeddedIPv4(address net.IP) net.IP {\n\tfull := address.To16()\n\tif full == nil || address.To4() != nil {\n\t\treturn nil\n\t}\n\tswitch {\n\tcase full[0] == 0x20 && full[1] == 0x02:\n\t\treturn net.IPv4(full[2], full[3], full[4], full[5]).To4()\n\tcase prefixIs(full, 0x00, 0x64, 0xff, 0x9b, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00),\n\t\tprefixIs(full, 0x00, 0x64, 0xff, 0x9b, 0x00, 0x01):\n\t\treturn net.IPv4(full[12], full[13], full[14], full[15]).To4()\n\t}\n\tfor _, octet := range full[:12] {\n\t\tif octet != 0 {\n\t\t\treturn nil\n\t\t}\n\t}\n\tif full[12] == 0 && full[13] == 0 {\n\t\treturn nil\n\t}\n\treturn net.IPv4(full[12], full[13], full[14], full[15]).To4()\n}\n\nfunc prefixIs(full net.IP, prefix ...byte) bool {\n\tif len(full) < len(prefix) {\n\t\treturn false\n\t}\n\tfor index, octet := range prefix {\n\t\tif full[index] != octet {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n\nfunc ipv4Class(v4 net.IP) addressClass {\n\tfirst, second := v4[0], v4[1]\n\tswitch {\n\tcase first == 0:\n\t\treturn classUnspecified // 0.0.0.0/8 \"this network\"\n\tcase first == 127:\n\t\treturn classLoopback // 127.0.0.0/8\n\tcase first == 10:\n\t\treturn classPrivate // 10.0.0.0/8\n\tcase first == 169 && second == 254:\n\t\treturn classLinkLocal // 169.254.0.0/16 (cloud metadata)\n\tcase first == 172 && second >= 16 && second <= 31:\n\t\treturn classPrivate // 172.16.0.0/12\n\tcase first == 192 && second == 168:\n\t\treturn classPrivate // 192.168.0.0/16\n\tcase first == 100 && second >= 64 && second <= 127:\n\t\treturn classCGNAT // 100.64.0.0/10\n\tcase first >= 224:\n\t\treturn classMulticast // 224.0.0.0/4 and the reserved space above it\n\tcase reservedIPv4Label(v4) != \"\":\n\t\t// The IETF special-purpose blocks that are never routed publicly (RFC 6890). A name\n\t\t// resolving into one is either misconfiguration or a probe for what answers there\n\t\t// locally \226\128\148 192.0.0.0/24 in particular is the IPv4 Service Continuity prefix some\n\t\t// CLAT/DS-Lite hosts bind on-box.\n\t\treturn classReserved\n\tdefault:\n\t\treturn classPublic\n\t}\n}\n\n// reservedIPv4Label names the IETF-reserved block an address falls in, or \"\" for none.\nfunc reservedIPv4Label(v4 net.IP) string {\n\tif len(v4) < 4 {\n\t\t// classReserved is only ever paired with a folded IPv4, but the analyser cannot see\n\t\t// that pairing across the call, and a nil here must be \"no label\", not a panic.\n\t\treturn \"\"\n\t}\n\tfirst, second, third := v4[0], v4[1], v4[2]\n\tswitch {\n\tcase first == 192 && second == 0 && third == 0:\n\t\treturn \"reserved 192.0.0.0/24 (IETF protocol assignments)\"\n\tcase first == 192 && second == 0 && third == 2:\n\t\treturn \"documentation 192.0.2.0/24 (TEST-NET-1)\"\n\tcase first == 198 && (second == 18 || second == 19):\n\t\treturn \"benchmarking 198.18.0.0/15\"\n\tcase first == 198 && second == 51 && third == 100:\n\t\treturn \"documentation 198.51.100.0/24 (TEST-NET-2)\"\n\tcase first == 203 && second == 0 && third == 113:\n\t\treturn \"documentation 203.0.113.0/24 (TEST-NET-3)\"\n\tdefault:\n\t\treturn \"\"\n\t}\n}\n\nfunc ipv6Class(full net.IP) addressClass {\n\tif full == nil {\n\t\treturn classInvalid\n\t}\n\tgroup0 := uint16(full[0])<<8 | uint16(full[1])\n\tswitch {\n\tcase full.Equal(net.IPv6unspecified):\n\t\treturn classUnspecified // ::\n\tcase full.Equal(net.IPv6loopback):\n\t\treturn classLoopback // ::1\n\tcase group0&0xffc0 == 0xfe80:\n\t\treturn classLinkLocal // fe80::/10\n\tcase group0&0xfe00 == 0xfc00:\n\t\treturn classPrivate // fc00::/7 unique-local\n\tcase group0&0xff00 == 0xff00:\n\t\treturn classMulticast // ff00::/8\n\tdefault:\n\t\treturn classPublic\n\t}\n}\n\n// IPForbiddenReason names the range that makes an address unsafe to dial, or \"\" when the\n// address is public and routable. The wording matches the Racket runtime's, so a refusal\n// reads the same on both backends.\nfunc IPForbiddenReason(address string) string {\n\tclass, v4 := classifyParsed(address)\n\tisIPv4 := v4 != nil\n\tswitch class {\n\tcase classPublic:\n\t\treturn \"\"\n\tcase classLoopback:\n\t\tif isIPv4 {\n\t\t\treturn \"loopback 127.0.0.0/8\"\n\t\t}\n\t\treturn \"IPv6 loopback ::1\"\n\tcase classUnspecified:\n\t\tif isIPv4 {\n\t\t\treturn \"0.0.0.0/8 (this network)\"\n\t\t}\n\t\treturn \"unspecified ::\"\n\tcase classLinkLocal:\n\t\tif isIPv4 {\n\t\t\treturn \"link-local 169.254.0.0/16\"\n\t\t}\n\t\treturn \"IPv6 link-local fe80::/10\"\n\tcase classPrivate:\n\t\tif isIPv4 {\n\t\t\treturn rfc1918Label(v4)\n\t\t}\n\t\treturn \"IPv6 unique-local fc00::/7\"\n\tcase classCGNAT:\n\t\treturn \"CGNAT 100.64.0.0/10\"\n\tcase classMulticast:\n\t\tif isIPv4 {\n\t\t\treturn \"multicast/reserved >= 224.0.0.0\"\n\t\t}\n\t\treturn \"IPv6 multicast ff00::/8\"\n\tcase classReserved:\n\t\tif label := reservedIPv4Label(v4); label != \"\" {\n\t\t\treturn label\n\t\t}\n\t\treturn \"unrecognized address form (fail-closed)\"\n\tcase classInvalid:\n\t\treturn \"unrecognized address form (fail-closed)\"\n\t}\n\t// Unreachable: every class is answered above. A class added later lands here, and refusing\n\t// is the only safe answer for a range whose policy nobody has decided yet.\n\treturn \"unrecognized address form (fail-closed)\"\n}\n\n// rfc1918Label names the specific private block, so the refusal is actionable. It takes the\n// FOLDED IPv4 address, so a NAT64 or 6to4 spelling of 10.0.0.1 is labelled as 10.0.0.0/8.\nfunc rfc1918Label(v4 net.IP) string {\n\tif len(v4) != net.IPv4len {\n\t\treturn \"a private range\"\n\t}\n\tswitch v4[0] {\n\tcase 10:\n\t\treturn \"private 10.0.0.0/8\"\n\tcase 172:\n\t\treturn \"private 172.16.0.0/12\"\n\tdefault:\n\t\treturn \"private 192.168.0.0/16\"\n\t}\n}\n\n// HostLoopback reports whether a HOST (not a resolved address) can only be reached from\n// this machine. Used solely to bound the two development escapes below; the default secure\n// path never consults it.\nfunc HostLoopback(host string) bool {\n\tlowered := strings.ToLower(strings.TrimSpace(host))\n\tlowered = strings.TrimSuffix(strings.TrimPrefix(lowered, \"[\"), \"]\")\n\tif lowered == \"localhost\" || strings.HasSuffix(lowered, \".localhost\") {\n\t\treturn true\n\t}\n\tclass, _ := classifyAddress(lowered)\n\treturn class == classLoopback\n}\n\n// SsrfAllowLoopback reports whether loopback egress is permitted: it is the one private\n// range local development legitimately dials, so a non-deployed build allows it and a\n// deployed build refuses unless TESL_HTTP_ALLOW_LOOPBACK_EGRESS opts back in.\nfunc SsrfAllowLoopback() bool {\n\tif !envPresent(\"TESL_DEPLOYED\") {\n\t\treturn true\n\t}\n\treturn envTruthy(\"TESL_HTTP_ALLOW_LOOPBACK_EGRESS\")\n}\n\n// SsrfEgressRefusal is the egress verdict for a resolved peer address: \"\" to allow.\nfunc SsrfEgressRefusal(peer string) string {\n\treason := IPForbiddenReason(peer)\n\tswitch {\n\tcase reason == \"\":\n\t\treturn \"\"\n\tcase HostLoopback(peer) && SsrfAllowLoopback():\n\t\treturn \"\"\n\tdefault:\n\t\treturn reason\n\t}\n}\n\n// \226\148\128\226\148\128 Runtime configuration knobs \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// These read the process environment for the RUNTIME's own tuning (deadlines, egress\n// policy), which is a different question from Tesl's `env` surface in env.go: there an\n// empty variable counts as unset, because a blank deployment value must not look like a\n// configured one. Here presence is what a flag means, mirroring Racket's `getenv`.\n\nfunc envPresent(name string) bool {\n\t_, present := os.LookupEnv(name)\n\treturn present\n}\n\n// envTruthy accepts the same four spellings the Racket runtime does, so a deployment's\n// existing value keeps its meaning across backends.\nfunc envTruthy(name string) bool {\n\tvalue, present := os.LookupEnv(name)\n\tif !present {\n\t\treturn false\n\t}\n\tswitch strings.ToLower(strings.TrimSpace(value)) {\n\tcase \"1\", \"true\", \"yes\", \"on\":\n\t\treturn true\n\tdefault:\n\t\treturn false\n\t}\n}\n\n// envPositiveInt reads a positive-integer env knob, falling back to `fallback` for an\n// absent, empty, or unparseable value. Read fresh per call, not at init: a test or an\n// operator can retune a deadline without a restart.\nfunc envPositiveInt(name string, fallback int) int {\n\tvalue, present := os.LookupEnv(name)\n\tif !present {\n\t\treturn fallback\n\t}\n\tparsed, err := strconv.Atoi(strings.TrimSpace(value))\n\tif err != nil || parsed <= 0 {\n\t\treturn fallback\n\t}\n\treturn parsed\n}\n");
  ("hostname.go", "package teslrt\n\nimport (\n\t\"strconv\"\n\t\"strings\"\n)\n\n// Host classification for `Tesl.Net`, and the host half of `Tesl.Url`.\n//\n// This is a rule-for-rule port of `dsl/private/host-classify.rkt`, not a wrapper over Go's\n// `net.ParseIP`, and the difference is the whole point: `net.ParseIP` accepts the strict\n// dotted quad and NOTHING ELSE, while a resolver \226\128\148 and therefore curl, and therefore an\n// attacker's URL \226\128\148 also accepts `2130706433`, `0x7f.0.0.1` and `127.1`, all of which are\n// 127.0.0.1. A classifier that does not know those spellings answers \"public\" for the\n// loopback address, which is the parser differential this module exists to close.\n//\n// Every range table below is the one `hostclass.go` already uses for a resolved address, so\n// the ranges a `.tesl` program checks and the ranges the HTTP client refuses cannot diverge.\n\nfunc asciiDigit(c byte) bool { return c >= '0' && c <= '9' }\n\nfunc hexDigit(c byte) bool {\n\treturn asciiDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')\n}\n\n// hostChar is what a DNS LABEL may hold. `_` is not legal in a hostname per RFC 1123 but IS\n// legal in the names applications look up (`_dmarc.example.com`), and refusing it here would\n// make Url.parse reject URLs that resolve. Everything else \226\128\148 `%` included, so a\n// percent-encoded host can never smuggle a delimiter past this \226\128\148 is refused.\nfunc hostChar(c byte) bool {\n\treturn (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || asciiDigit(c) ||\n\t\tc == '-' || c == '_'\n}\n\n// parseIPv4Strict reads the canonical dotted quad: exactly four decimal octets in [0,255].\n// The four octets are an ARRAY rather than a slice, here and throughout: \"exactly four\" is\n// the invariant every caller relies on when it indexes, and an array is where the compiler\n// enforces it instead of a length check nobody re-reads.\nfunc parseIPv4Strict(text string) ([4]int, bool) {\n\tvar octets [4]int\n\tparts := strings.Split(text, \".\")\n\tif len(parts) != 4 {\n\t\treturn octets, false\n\t}\n\tfor at, part := range parts {\n\t\tif len(part) == 0 || len(part) > 3 {\n\t\t\treturn octets, false\n\t\t}\n\t\tfor index := 0; index < len(part); index++ {\n\t\t\tif !asciiDigit(part[index]) {\n\t\t\t\treturn octets, false\n\t\t\t}\n\t\t}\n\t\tvalue, err := strconv.Atoi(part)\n\t\tif err != nil || value < 0 || value > 255 {\n\t\t\treturn octets, false\n\t\t}\n\t\toctets[at] = value\n\t}\n\treturn octets, true\n}\n\n// parseInetPart reads one `inet_aton` component: `0x`/`0X` is hex, a leading `0` is octal,\n// anything else is decimal.\nfunc parseInetPart(part string) (uint64, bool) {\n\tswitch {\n\tcase len(part) == 0:\n\t\treturn 0, false\n\tcase len(part) > 2 && part[0] == '0' && (part[1] == 'x' || part[1] == 'X'):\n\t\tbody := part[2:]\n\t\tfor index := 0; index < len(body); index++ {\n\t\t\tif !hexDigit(body[index]) {\n\t\t\t\treturn 0, false\n\t\t\t}\n\t\t}\n\t\tvalue, err := strconv.ParseUint(body, 16, 64)\n\t\treturn value, err == nil\n\tcase len(part) > 1 && part[0] == '0':\n\t\tbody := part[1:]\n\t\tfor index := 0; index < len(body); index++ {\n\t\t\tif body[index] < '0' || body[index] > '7' {\n\t\t\t\treturn 0, false\n\t\t\t}\n\t\t}\n\t\tvalue, err := strconv.ParseUint(body, 8, 64)\n\t\treturn value, err == nil\n\tdefault:\n\t\tfor index := 0; index < len(part); index++ {\n\t\t\tif !asciiDigit(part[index]) {\n\t\t\t\treturn 0, false\n\t\t\t}\n\t\t}\n\t\tvalue, err := strconv.ParseUint(part, 10, 64)\n\t\treturn value, err == nil\n\t}\n}\n\n// parseIPv4Any reads every spelling inet_aton accepts, reduced to four octets:\n//\n//\ta          32-bit    2130706433 -> 127.0.0.1\n//\ta.b        b 24-bit  127.1      -> 127.0.0.1\n//\ta.b.c      c 16-bit  127.0.1    -> 127.0.0.1\n//\ta.b.c.d    octets    0x7f.0.0.1 -> 127.0.0.1\n//\n// Not-an-address (a DNS name, or garbage) answers false.\nfunc parseIPv4Any(text string) ([4]int, bool) {\n\tvar octets [4]int\n\tparts := strings.Split(text, \".\")\n\tif len(parts) < 1 || len(parts) > 4 {\n\t\treturn octets, false\n\t}\n\t// Every part but the LAST is one octet; the last one carries whatever bits remain.\n\tvar packed uint64\n\ttailBits := uint(8 * (4 - (len(parts) - 1)))\n\tfor at, part := range parts {\n\t\tvalue, ok := parseInetPart(part)\n\t\tif !ok {\n\t\t\treturn octets, false\n\t\t}\n\t\tif at == len(parts)-1 {\n\t\t\tif tailBits < 64 && value >= uint64(1)<<tailBits {\n\t\t\t\treturn octets, false\n\t\t\t}\n\t\t\tpacked = packed<<tailBits | value\n\t\t\tcontinue\n\t\t}\n\t\tif value > 255 {\n\t\t\treturn octets, false\n\t\t}\n\t\tpacked = packed<<8 | value\n\t}\n\toctets = [4]int{\n\t\tint(packed >> 24 & 255), int(packed >> 16 & 255),\n\t\tint(packed >> 8 & 255), int(packed & 255),\n\t}\n\treturn octets, true\n}\n\nfunc ipv4Text(octets [4]int) string {\n\tparts := make([]string, 0, 4)\n\tfor _, octet := range octets {\n\t\tparts = append(parts, strconv.Itoa(octet))\n\t}\n\treturn strings.Join(parts, \".\")\n}\n\n// parseIPv6 reads a literal WITHOUT brackets and WITHOUT a zone id into eight 16-bit groups.\n// It handles `::` compression and the embedded dotted-quad tail (`::ffff:127.0.0.1`).\nfunc parseIPv6(raw string) ([8]int, bool) {\n\tvar full [8]int\n\ttext := strings.ToLower(raw)\n\tif len(text) == 0 {\n\t\treturn full, false\n\t}\n\tfor index := 0; index < len(text); index++ {\n\t\tc := text[index]\n\t\tif !hexDigit(c) && c != ':' && c != '.' {\n\t\t\treturn full, false\n\t\t}\n\t}\n\tat := strings.Index(text, \"::\")\n\tif at < 0 {\n\t\tgroups, ok := ipv6GroupsOf(text)\n\t\tif !ok || len(groups) != 8 {\n\t\t\treturn full, false\n\t\t}\n\t\tcopy(full[:], groups)\n\t\treturn full, true\n\t}\n\t// More than one `::` is not a literal.\n\tif strings.Contains(text[at+2:], \"::\") {\n\t\treturn full, false\n\t}\n\thead, tail := text[:at], text[at+2:]\n\theadGroups := []int{}\n\tif head != \"\" {\n\t\tparsed, ok := ipv6GroupsOf(head)\n\t\tif !ok {\n\t\t\treturn full, false\n\t\t}\n\t\theadGroups = parsed\n\t}\n\ttailGroups := []int{}\n\tif tail != \"\" {\n\t\tparsed, ok := ipv6GroupsOf(tail)\n\t\tif !ok {\n\t\t\treturn full, false\n\t\t}\n\t\ttailGroups = parsed\n\t}\n\t// `::` stands for AT LEAST one zero group, so a run that already fills all eight is not\n\t// a literal \226\128\148 it is the same address written two ways, and only one of them is legal.\n\tif 8-len(headGroups)-len(tailGroups) < 1 {\n\t\treturn full, false\n\t}\n\tcopy(full[:], headGroups)\n\tcopy(full[8-len(tailGroups):], tailGroups)\n\treturn full, true\n}\n\n// ipv6GroupsOf splits a colon-separated run into 16-bit groups. The LAST element may be a\n// dotted quad, which expands to two groups.\nfunc ipv6GroupsOf(run string) ([]int, bool) {\n\tparts := strings.Split(run, \":\")\n\tif len(parts) == 0 {\n\t\treturn nil, false\n\t}\n\tgroups := []int{}\n\tfor index, part := range parts {\n\t\tif part == \"\" {\n\t\t\treturn nil, false\n\t\t}\n\t\tif strings.Contains(part, \".\") {\n\t\t\t// Only legal as the final element.\n\t\t\tif index != len(parts)-1 {\n\t\t\t\treturn nil, false\n\t\t\t}\n\t\t\toctets, ok := parseIPv4Strict(part)\n\t\t\tif !ok {\n\t\t\t\treturn nil, false\n\t\t\t}\n\t\t\treturn append(groups, octets[0]<<8|octets[1], octets[2]<<8|octets[3]), true\n\t\t}\n\t\tif len(part) < 1 || len(part) > 4 {\n\t\t\treturn nil, false\n\t\t}\n\t\tfor at := 0; at < len(part); at++ {\n\t\t\tif !hexDigit(part[at]) {\n\t\t\t\treturn nil, false\n\t\t\t}\n\t\t}\n\t\tvalue, err := strconv.ParseUint(part, 16, 32)\n\t\tif err != nil {\n\t\t\treturn nil, false\n\t\t}\n\t\tgroups = append(groups, int(value))\n\t}\n\treturn groups, true\n}\n\n// ipv6Text writes RFC 5952 form: lowercase hex, no leading zeros, the LONGEST run of two or\n// more zero groups compressed to `::` (leftmost on a tie).\nfunc ipv6Text(groups [8]int) string {\n\tbestStart, bestLength := -1, 0\n\trunStart, runLength := -1, 0\n\t// The run is closed inside the loop when it ENDS and once more after it, rather than by\n\t// walking one index past the end: a sentinel iteration reads as an out-of-range index to\n\t// every reader, human and analyser alike.\n\tfor index, group := range groups {\n\t\tif group == 0 {\n\t\t\tif runStart < 0 {\n\t\t\t\trunStart = index\n\t\t\t}\n\t\t\trunLength++\n\t\t\tcontinue\n\t\t}\n\t\tif runLength > bestLength {\n\t\t\tbestStart, bestLength = runStart, runLength\n\t\t}\n\t\trunStart, runLength = -1, 0\n\t}\n\tif runLength > bestLength {\n\t\tbestStart, bestLength = runStart, runLength\n\t}\n\trender := func(from, to int) string {\n\t\tparts := make([]string, 0, to-from)\n\t\tfor index := from; index < to; index++ {\n\t\t\tparts = append(parts, strconv.FormatInt(int64(groups[index]), 16))\n\t\t}\n\t\treturn strings.Join(parts, \":\")\n\t}\n\tif bestStart < 0 || bestLength < 2 {\n\t\treturn render(0, len(groups))\n\t}\n\treturn render(0, bestStart) + \"::\" + render(bestStart+bestLength, len(groups))\n}\n\n// ipv6EmbeddedIPv4 folds `::ffff:a.b.c.d` (IPv4-mapped) and the deprecated `::a.b.c.d`\n// (IPv4-compatible) to the dotted quad they denote \226\128\148 the same address for every purpose a\n// classifier cares about, and the fold an attacker relies on being skipped. `::` and `::1`\n// are their own addresses and are NOT folded, or the IPv6 loopback would land in 0.0.0.0/8.\nfunc ipv6EmbeddedIPv4(groups [8]int) ([4]int, bool) {\n\tvar octets [4]int\n\tzeroHead := true\n\tfor index := 0; index < 5; index++ {\n\t\tif groups[index] != 0 {\n\t\t\tzeroHead = false\n\t\t\tbreak\n\t\t}\n\t}\n\tif !zeroHead {\n\t\treturn octets, false\n\t}\n\tembedded := func() [4]int {\n\t\treturn [4]int{groups[6] >> 8, groups[6] & 255, groups[7] >> 8, groups[7] & 255}\n\t}\n\tif groups[5] == 0xffff {\n\t\treturn embedded(), true\n\t}\n\tif groups[5] == 0 && groups[6] != 0 {\n\t\treturn embedded(), true\n\t}\n\treturn octets, false\n}\n\nfunc ipv4OctetsClass(octets [4]int) addressClass {\n\tfirst, second := octets[0], octets[1]\n\tswitch {\n\tcase first == 0:\n\t\treturn classUnspecified\n\tcase first == 127:\n\t\treturn classLoopback\n\tcase first == 10:\n\t\treturn classPrivate\n\tcase first == 169 && second == 254:\n\t\treturn classLinkLocal\n\tcase first == 172 && second >= 16 && second <= 31:\n\t\treturn classPrivate\n\tcase first == 192 && second == 168:\n\t\treturn classPrivate\n\tcase first == 100 && second >= 64 && second <= 127:\n\t\treturn classCGNAT\n\tcase first >= 224:\n\t\treturn classMulticast\n\tdefault:\n\t\treturn classPublic\n\t}\n}\n\nfunc ipv6GroupsClass(groups [8]int) addressClass {\n\tallZero := true\n\tfor _, group := range groups {\n\t\tif group != 0 {\n\t\t\tallZero = false\n\t\t\tbreak\n\t\t}\n\t}\n\tif allZero {\n\t\treturn classUnspecified\n\t}\n\tloopback := groups[7] == 1\n\tfor index := 0; index < 7; index++ {\n\t\tif groups[index] != 0 {\n\t\t\tloopback = false\n\t\t\tbreak\n\t\t}\n\t}\n\tif loopback {\n\t\treturn classLoopback\n\t}\n\tswitch first := groups[0]; {\n\tcase first&0xffc0 == 0xfe80:\n\t\treturn classLinkLocal\n\tcase first&0xfe00 == 0xfc00:\n\t\treturn classPrivate\n\tcase first&0xff00 == 0xff00:\n\t\treturn classMulticast\n\tdefault:\n\t\treturn classPublic\n\t}\n}\n\n// NormalizeHost canonicalises a URL HOST COMPONENT \226\128\148 the bracketed IPv6 form included.\n// Answers false when the input is not a host this module will vouch for, which every caller\n// reads as \"refuse\".\n//\n//\t\"LOCALHOST.\"         -> \"localhost\"\n//\t\"2130706433\"         -> \"127.0.0.1\"\n//\t\"0x7f.0.0.1\"         -> \"127.0.0.1\"\n//\t\"[::FFFF:127.0.0.1]\" -> \"127.0.0.1\"\n//\t\"[2606:4700::1111]\"  -> \"2606:4700::1111\"\n//\t\"exa mple.com\"       -> refused\nfunc NormalizeHost(raw string) (string, bool) {\n\tif len(raw) == 0 {\n\t\treturn \"\", false\n\t}\n\tif raw[0] == '[' {\n\t\t// A bracketed literal is IPv6 only, and a zone id is refused: it is meaningless\n\t\t// off-host and is a classic parser differential.\n\t\tif raw[len(raw)-1] != ']' {\n\t\t\treturn \"\", false\n\t\t}\n\t\tgroups, ok := parseIPv6(raw[1 : len(raw)-1])\n\t\tif !ok {\n\t\t\treturn \"\", false\n\t\t}\n\t\tif v4, folded := ipv6EmbeddedIPv4(groups); folded {\n\t\t\treturn ipv4Text(v4), true\n\t\t}\n\t\treturn ipv6Text(groups), true\n\t}\n\tif strings.ContainsAny(raw, \"]:/?#@\\\\%[\") {\n\t\treturn \"\", false\n\t}\n\tlower := strings.ToLower(raw)\n\t// Strip ONE root-anchoring trailing dot; `a..` stays invalid below.\n\tstripped := lower\n\tif len(lower) > 1 && lower[len(lower)-1] == '.' {\n\t\tstripped = lower[:len(lower)-1]\n\t}\n\tif stripped == \"\" || len(stripped) > 253 {\n\t\treturn \"\", false\n\t}\n\t// Numeric in ANY inet_aton spelling means it IS an address, not a name.\n\tif octets, ok := parseIPv4Any(stripped); ok {\n\t\treturn ipv4Text(octets), true\n\t}\n\t// `last` is carried out of the loop rather than indexed afterwards: an empty label\n\t// already fails, so the final one is whatever the loop saw last, and a host with no\n\t// labels at all leaves it \"\" \226\128\148 which the all-digits test below reads as a refusal.\n\tlast := \"\"\n\tfor _, label := range strings.Split(stripped, \".\") {\n\t\tif len(label) < 1 || len(label) > 63 {\n\t\t\treturn \"\", false\n\t\t}\n\t\tfor index := 0; index < len(label); index++ {\n\t\t\tif !hostChar(label[index]) {\n\t\t\t\treturn \"\", false\n\t\t\t}\n\t\t}\n\t\tlast = label\n\t}\n\t// An all-numeric FINAL label is never a DNS name (RFC 3696): it is a malformed address\n\t// literal \226\128\148 `999.999.999.999`, `0xzz.1`, an out-of-range 32-bit decimal. Answering\n\t// \"domain name\" there would be the fail-OPEN reading, since a caller takes that to mean\n\t// \"not an address literal\".\n\tallDigits := true\n\tfor index := 0; index < len(last); index++ {\n\t\tif !asciiDigit(last[index]) {\n\t\t\tallDigits = false\n\t\t\tbreak\n\t\t}\n\t}\n\tif allDigits {\n\t\treturn \"\", false\n\t}\n\treturn stripped, true\n}\n\n// HostClass is the `Tesl.Net` classification, in the same flat tag struct every other ADT\n// that crosses a module boundary uses. A program `case`s over it exhaustively, which is what\n// makes \"did you handle link-local?\" a question the compiler answers.\ntype HostClass struct {\n\tTag HostClassTag\n}\n\n// HostClassTag identifies which class a HostClass holds. An enum-like set, so the\n// `exhaustive` linter can verify a switch over it.\ntype HostClassTag int\n\nconst (\n\tHostClassLoopback HostClassTag = iota\n\tHostClassPrivate\n\tHostClassLinkLocal\n\tHostClassCgnat\n\tHostClassMulticast\n\tHostClassUnspecified\n\tHostClassPublic\n\tHostClassDomainName\n\tHostClassInvalid\n)\n\n// ClassifyHost answers the class of a URL host component.\n//\n// A `localhost` name \226\128\148 and any `*.localhost` name \226\128\148 is LOOPBACK, not a domain name: RFC 6761\n// reserves it and resolvers are required to map it to the loopback address, so treating it\n// as an ordinary name would be a bypass by definition.\n//\n// A domain name may still RESOLVE to a forbidden address; deciding that needs a resolver and\n// connect-pinning, which is the HTTP client's job rather than a string check's.\nfunc ClassifyHost(raw string) HostClass {\n\thost, ok := NormalizeHost(raw)\n\tif !ok {\n\t\treturn HostClass{Tag: HostClassInvalid}\n\t}\n\tif octets, ok := parseIPv4Strict(host); ok {\n\t\treturn HostClass{Tag: hostClassTag(ipv4OctetsClass(octets))}\n\t}\n\tif groups, ok := parseIPv6(host); ok {\n\t\treturn HostClass{Tag: hostClassTag(ipv6GroupsClass(groups))}\n\t}\n\tif host == \"localhost\" || strings.HasSuffix(host, \".localhost\") {\n\t\treturn HostClass{Tag: HostClassLoopback}\n\t}\n\treturn HostClass{Tag: HostClassDomainName}\n}\n\nfunc hostClassTag(class addressClass) HostClassTag {\n\tswitch class {\n\tcase classLoopback:\n\t\treturn HostClassLoopback\n\tcase classPrivate:\n\t\treturn HostClassPrivate\n\tcase classLinkLocal:\n\t\treturn HostClassLinkLocal\n\tcase classCGNAT:\n\t\treturn HostClassCgnat\n\tcase classMulticast:\n\t\treturn HostClassMulticast\n\tcase classUnspecified:\n\t\treturn HostClassUnspecified\n\tcase classPublic:\n\t\treturn HostClassPublic\n\tcase classReserved:\n\t\t// IETF reserved / TEST-NET / benchmarking blocks have no `Tesl.Net` constructor of\n\t\t// their own; they are never routable, so the surface reports them as Invalid (the\n\t\t// SSRF guard refuses them through IPForbiddenReason regardless).\n\t\treturn HostClassInvalid\n\tcase classInvalid:\n\t\treturn HostClassInvalid\n\tdefault:\n\t\treturn HostClassInvalid\n\t}\n}\n\n// NormalizeHostMaybe is the `Tesl.Net` surface: the canonical host, or Nothing.\nfunc NormalizeHostMaybe(raw string) Maybe[string] {\n\tif host, ok := NormalizeHost(raw); ok {\n\t\treturn Something(host)\n\t}\n\treturn Nothing[string]()\n}\n\nfunc NetIsLoopback(raw string) bool  { return ClassifyHost(raw).Tag == HostClassLoopback }\nfunc NetIsPrivate(raw string) bool   { return ClassifyHost(raw).Tag == HostClassPrivate }\nfunc NetIsLinkLocal(raw string) bool { return ClassifyHost(raw).Tag == HostClassLinkLocal }\nfunc NetIsCgnat(raw string) bool     { return ClassifyHost(raw).Tag == HostClassCgnat }\nfunc NetIsMulticast(raw string) bool { return ClassifyHost(raw).Tag == HostClassMulticast }\n\n// NetIsIPLiteral reports whether the host IS an address literal in some spelling, as opposed\n// to a DNS name. A `localhost` name is NOT a literal, though it IS loopback.\nfunc NetIsIPLiteral(raw string) bool {\n\thost, ok := NormalizeHost(raw)\n\tif !ok {\n\t\treturn false\n\t}\n\tif _, isV4 := parseIPv4Strict(host); isV4 {\n\t\treturn true\n\t}\n\t_, isV6 := parseIPv6(host)\n\treturn isV6\n}\n\n// NetIsIPv4Mapped reports whether the host was WRITTEN as an IPv4-mapped or IPv4-compatible\n// IPv6 literal \226\128\148 the spelling a hand-written check misses most often.\nfunc NetIsIPv4Mapped(raw string) bool {\n\ttext := raw\n\tif len(text) > 1 && text[0] == '[' && text[len(text)-1] == ']' {\n\t\ttext = text[1 : len(text)-1]\n\t}\n\tgroups, ok := parseIPv6(text)\n\tif !ok {\n\t\treturn false\n\t}\n\t_, folded := ipv6EmbeddedIPv4(groups)\n\treturn folded\n}\n\n// NetIsForbiddenHost is the one-line outbound guard: true for every host this runtime can\n// already tell is not a public destination \226\128\148 any non-public address literal in any spelling,\n// the `localhost` names, and anything unparseable. Fail-closed by construction: there is no\n// \"probably fine\" answer.\nfunc NetIsForbiddenHost(raw string) bool {\n\tswitch ClassifyHost(raw).Tag {\n\tcase HostClassPublic, HostClassDomainName:\n\t\treturn false\n\tcase HostClassLoopback, HostClassPrivate, HostClassLinkLocal, HostClassCgnat,\n\t\tHostClassMulticast, HostClassUnspecified, HostClassInvalid:\n\t\treturn true\n\tdefault:\n\t\treturn true\n\t}\n}\n");
  ("httpclient.go", "package teslrt\n\nimport (\n\t\"context\"\n\t\"crypto/rand\"\n\t\"crypto/tls\"\n\t\"encoding/hex\"\n\t\"errors\"\n\t\"fmt\"\n\t\"io\"\n\t\"net\"\n\t\"net/http\"\n\t\"net/url\"\n\t\"os\"\n\t\"sort\"\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n\t\"syscall\"\n\t\"time\"\n)\n\n// millisDuration turns one of the millisecond knobs into a deadline.\nfunc millisDuration(millis int) time.Duration {\n\treturn time.Duration(millis) * time.Millisecond\n}\n\n// Outbound HTTP \226\128\148 the `Tesl.HttpClient` surface.\n//\n// The `httpClient` capability that gates every call here is a COMPILE-TIME grant, so\n// nothing about it survives to run time; what does survive is the set of protections a\n// call cannot opt out of:\n//\n//\tCR/LF header guard    a `\\r\\n` in a header name or value would split the request and\n//\t                      inject arbitrary headers, so it is refused before anything is sent;\n//\tSSRF containment      the peer address actually connected to is judged (hostclass.go), so\n//\t                      a public name resolving to 169.254.169.254 or 127.0.0.1 is refused;\n//\tverified TLS          certificate chain AND hostname, with one loopback-only development\n//\t                      escape;\n//\tdeadlines             a hung upstream fails the call rather than pinning the caller \226\128\148\n//\t                      inside a worker that is the difference between a failed job (which\n//\t                      retries and dead-letters) and a job that never finishes;\n//\ta response-body cap   an unbounded read of a hostile response is a memory DoS;\n//\ta redirect policy     a 3xx is a fresh request to a location the UPSTREAM chose: no\n//\t                      https\226\134\146http downgrade, no carrying secret headers to another origin,\n//\t                      at most five hops, and none at all for the SSO legs (see\n//\t                      `redirectPolicy` below).\n//\n// When tracing is enabled, outbound calls receive a W3C traceparent header unless the caller\n// supplied one explicitly. This keeps propagation deterministic and prevents an upstream trace\n// from being silently replaced.\ntype HttpResponse struct {\n\tStatus Int\n\tBody   string\n\t// Response headers in name order \226\128\148 one entry per value, so a repeated header\n\t// (`Set-Cookie`) keeps all of its values. Go's header map has no order of its own, so\n\t// sorting is what makes the list deterministic; Racket preserves wire order instead, and\n\t// a test that depends on either ordering is testing the transport, not the program.\n\tHeaders []Tuple2[string, string]\n}\n\n// \226\148\128\226\148\128 Deadlines \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// Env vars rather than per-call arguments, matching the Racket runtime: a deadline is\n// deployment tuning of the same kind as the response-body cap, and a per-call timeout would\n// put an operational concern into all four public signatures.\n//\n//\tTESL_HTTP_CONNECT_TIMEOUT_MS   10000   reaching the host\n//\tTESL_HTTP_TIMEOUT_MS           30000   the whole response (status + body)\n//\tTESL_HTTP_MAX_RESPONSE_BYTES   10 MiB  the most a response body may occupy\n\nfunc httpConnectTimeoutMs() int { return envPositiveInt(\"TESL_HTTP_CONNECT_TIMEOUT_MS\", 10000) }\nfunc httpReadTimeoutMs() int    { return envPositiveInt(\"TESL_HTTP_TIMEOUT_MS\", 30000) }\n\nfunc httpMaxResponseBytes() int {\n\treturn envPositiveInt(\"TESL_HTTP_MAX_RESPONSE_BYTES\", 10*1024*1024)\n}\n\n// \226\148\128\226\148\128 Header hygiene \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// HttpHeaderFieldSafe reports whether a header name or value can go on the wire: a CR or LF\n// would end the field and let the rest be read as further headers or a second request.\nfunc HttpHeaderFieldSafe(field string) bool {\n\treturn !strings.ContainsAny(field, \"\\r\\n\")\n}\n\nfunc requireHeaderFieldSafe(what, field string) string {\n\tif !HttpHeaderFieldSafe(field) {\n\t\tpanic(fmt.Sprintf(\n\t\t\t\"HttpClient: outbound %s contains a CR/LF newline \226\128\148 header injection rejected\", what))\n\t}\n\treturn field\n}\n\n// \226\148\128\226\148\128 Secret-carrying headers \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// `HttpClient.bearer k` and `HttpClient.secretHeader \"X-Api-Key\" k` are the sanctioned way\n// a `secret` reaches the wire, replacing the `\"Bearer \" ++ key.value` that `secret` makes\n// impossible. Their Tesl type is `Tuple2 String String`, so the value half IS a Go string \226\128\148\n// which means the plaintext cannot be what it holds, or `Tuple2.second (bearer k)` would\n// hand a program the secret it is not allowed to see.\n//\n// So the value half is a HANDLE: unguessable text that names the plaintext in a\n// process-local table. Every String operation on it sees the handle, printing it shows only\n// \"[redacted]\", and this file is the one place that trades a handle back for the bytes that\n// go on the socket. The handle carries a per-process random nonce because it is otherwise\n// forgeable: a program that could construct the handle text from user input would make the\n// client send OUR secret to an attacker's URL.\nvar (\n\tsecretHeaderNonce = newSecretHeaderNonce()\n\tsecretHeaderStore sync.Map // handle string -> plaintext string\n\tsecretHeaderSeq   int64\n\tsecretHeaderMutex sync.Mutex\n)\n\nfunc newSecretHeaderNonce() string {\n\tbuffer := make([]byte, 16)\n\tif _, err := rand.Read(buffer); err != nil {\n\t\tpanic(\"HttpClient: no source of randomness for secret headers: \" + err.Error())\n\t}\n\treturn hex.EncodeToString(buffer)\n}\n\nfunc secretHeaderHandle(plaintext string) string {\n\tsecretHeaderMutex.Lock()\n\tsecretHeaderSeq++\n\tsequence := secretHeaderSeq\n\tsecretHeaderMutex.Unlock()\n\thandle := SecretRedaction + \"\\x00\" + secretHeaderNonce + \":\" + strconv.FormatInt(sequence, 10)\n\tsecretHeaderStore.Store(handle, plaintext)\n\treturn handle\n}\n\n// isSecretHeaderHandle recognises the handle SHAPE. It is what the redirect policy keys on:\n// a header whose value came through `bearer`/`secretHeader` is one the caller meant as a\n// credential, whatever its name.\nfunc isSecretHeaderHandle(value string) bool {\n\treturn strings.HasPrefix(value, SecretRedaction+\"\\x00\")\n}\n\n// revealHeaderValue is THE unwrap point: a secret-header handle becomes plaintext here and\n// nowhere else. Anything that is not a handle is already the value it looks like.\nfunc revealHeaderValue(value string) string {\n\tif !isSecretHeaderHandle(value) {\n\t\treturn value\n\t}\n\tif plaintext, found := secretHeaderStore.Load(value); found {\n\t\tif text, ok := plaintext.(string); ok {\n\t\t\treturn text\n\t\t}\n\t}\n\t// A handle shape from another process (or a forgery attempt) names no plaintext here.\n\t// Sending the handle text would leak nothing, but it would also silently authenticate as\n\t// nobody, so it fails instead.\n\tpanic(\"HttpClient: this secret header value does not belong to this process\")\n}\n\n// HttpSecretHeader is `HttpClient.secretHeader name k`.\nfunc HttpSecretHeader(name string, secret SecretString) Tuple2[string, string] {\n\treturn makeSecretHeader(name, secret, \"\")\n}\n\n// HttpBearer is `HttpClient.bearer k`: the Authorization header for a bearer token.\nfunc HttpBearer(secret SecretString) Tuple2[string, string] {\n\treturn makeSecretHeader(\"Authorization\", secret, \"Bearer \")\n}\n\nfunc makeSecretHeader(name string, secret SecretString, prefix string) Tuple2[string, string] {\n\treturn Tuple2[string, string]{\n\t\tTuple2First:  requireHeaderFieldSafe(\"header name\", name),\n\t\tTuple2Second: secretHeaderHandle(prefix + secret.Reveal()),\n\t}\n}\n\n// \226\148\128\226\148\128 The four verbs \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nfunc HttpGet(target string, headers []Tuple2[string, string]) HttpResponse {\n\treturn httpRequest(\"GET\", target, headers, nil)\n}\n\nfunc HttpPost(target string, headers []Tuple2[string, string], body string) HttpResponse {\n\treturn httpRequest(\"POST\", target, headers, &body)\n}\n\nfunc HttpPut(target string, headers []Tuple2[string, string], body string) HttpResponse {\n\treturn httpRequest(\"PUT\", target, headers, &body)\n}\n\nfunc HttpDelete(target string, headers []Tuple2[string, string]) HttpResponse {\n\treturn httpRequest(\"DELETE\", target, headers, nil)\n}\n\nfunc httpRequest(method, target string, headers []Tuple2[string, string], body *string) HttpResponse {\n\treturn httpRequestPolicy(method, target, headers, body, redirectGuarded)\n}\n\n// httpRequestPolicy is the one path every outbound call takes \226\128\148 the four `HttpClient` verbs\n// with `redirectGuarded`, the SSO legs with `redirectRefused` \226\128\148 so the two differ in the\n// redirect rule and in NOTHING else: same URL validation, same header guard, same stubs.\nfunc httpRequestPolicy(method, target string, headers []Tuple2[string, string], body *string,\n\tpolicy redirectPolicy) HttpResponse {\n\tparsed := parseOutboundURL(target)\n\t// The header guard runs BEFORE the test double is consulted, so a stubbed call is still a\n\t// well-formed one and a header-injection bug cannot hide behind a stub.\n\twire, secretHeaders := outboundHeaders(headers)\n\tif answer, stubbed := httpStubAnswer(method, target, body); stubbed {\n\t\treturn answer\n\t}\n\treturn httpRequestNetwork(method, target, parsed, wire, body,\n\t\tredirectCheck(policy, parsed, secretHeaders))\n}\n\nfunc parseOutboundURL(target string) *url.URL {\n\tparsed, err := url.Parse(target)\n\tif err != nil {\n\t\tpanic(fmt.Sprintf(\"HttpClient: invalid URL %q: %s\", target, err.Error()))\n\t}\n\tif parsed.Scheme != \"http\" && parsed.Scheme != \"https\" {\n\t\tpanic(fmt.Sprintf(\"HttpClient: invalid URL %q: expected an http or https scheme\", target))\n\t}\n\tif parsed.Hostname() == \"\" {\n\t\tpanic(fmt.Sprintf(\"HttpClient: invalid URL %q: could not parse host\", target))\n\t}\n\treturn parsed\n}\n\n// outboundHeaders checks every field and reveals the secret-carrying ones. A header list is\n// ordered and may repeat a name, so it becomes an http.Header by APPENDING rather than\n// setting \226\128\148 `Set` would drop all but the last of a repeated header. The second result names\n// the headers that were secret handles, for the redirect policy.\nfunc outboundHeaders(headers []Tuple2[string, string]) (http.Header, []string) {\n\twire := http.Header{}\n\tvar secretHeaders []string\n\tfor _, header := range headers {\n\t\tcanonical := http.CanonicalHeaderKey(requireHeaderFieldSafe(\"header name\", header.Tuple2First))\n\t\tif isSecretHeaderHandle(header.Tuple2Second) {\n\t\t\tsecretHeaders = append(secretHeaders, canonical)\n\t\t}\n\t\tvalue := requireHeaderFieldSafe(\"header value\", revealHeaderValue(header.Tuple2Second))\n\t\twire[canonical] = append(wire[canonical], value)\n\t}\n\treturn wire, secretHeaders\n}\n\n// \226\148\128\226\148\128 Redirects \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// A 3xx names a location the UPSTREAM chose, so following it is a fresh request to an\n// attacker-influenced URL. The dialer's egress check does run again on that hop (the\n// transport is shared), but three things it cannot see are decided here:\n//\n//\tno downgrade        https\226\134\146http is refused. A `Bearer` token or an API key would travel in\n//\t                    cleartext on the second hop, and Go itself never refuses a downgrade.\n//\tsecrets stay home   a request carrying `HttpClient.bearer`/`secretHeader` values may not be\n//\t                    redirected to another scheme or host. Go strips `Authorization` and\n//\t                    `Cookie` when the DOMAIN changes but forwards every other header, so an\n//\t                    `X-Api-Key` followed a 302 to whatever host it named. The whole call\n//\t                    fails \226\128\148 a trap, like every other client failure \226\128\148 rather than quietly\n//\t                    continuing without the header: a caller who attached a credential\n//\t                    expects it sent, and a 401 from the wrong host would be a puzzle.\n//\ta hop cap           five rather than Go's ten; a loop is a slow failure either way.\n//\n// `redirectRefused` is the SSO legs' policy: the 3xx IS the response (`http.ErrUseLastResponse`),\n// and a non-200 is a failed leg. A provider's token, discovery, JWKS or userinfo endpoint is\n// configured or discovered, never a location a response chose.\ntype redirectPolicy int\n\nconst (\n\tredirectGuarded redirectPolicy = iota\n\tredirectRefused\n)\n\nconst maxRedirects = 5\n\n// redirectCheck builds the `http.Client.CheckRedirect` hook for one call. `original` is the\n// URL the caller asked for \226\128\148 the origin its secret headers were meant for \226\128\148 and\n// `secretHeaders` names the headers that came through a secret handle. Every refusal reads\n// \"refused redirect\", which `requestFailure` recognises as a refusal rather than a fault.\nfunc redirectCheck(policy redirectPolicy, original *url.URL,\n\tsecretHeaders []string) func(*http.Request, []*http.Request) error {\n\treturn func(next *http.Request, via []*http.Request) error {\n\t\tif policy == redirectRefused {\n\t\t\treturn http.ErrUseLastResponse\n\t\t}\n\t\tif len(via) > maxRedirects {\n\t\t\treturn fmt.Errorf(\"refused redirect to %s: more than %d redirects\", next.URL, maxRedirects)\n\t\t}\n\t\tif len(via) > 0 && via[len(via)-1].URL.Scheme == \"https\" && next.URL.Scheme != \"https\" {\n\t\t\treturn fmt.Errorf(\"refused redirect from %s to %s: an https request is not \"+\n\t\t\t\t\"downgraded to http\", via[len(via)-1].URL, next.URL)\n\t\t}\n\t\tsameOrigin := strings.EqualFold(next.URL.Scheme, original.Scheme) &&\n\t\t\tstrings.EqualFold(next.URL.Host, original.Host)\n\t\tif sameOrigin {\n\t\t\treturn nil\n\t\t}\n\t\tif len(secretHeaders) > 0 {\n\t\t\treturn fmt.Errorf(\"refused redirect to %s: the request carries secret headers (%s) \"+\n\t\t\t\t\"that must not leave %s://%s\", next.URL, strings.Join(secretHeaders, \", \"),\n\t\t\t\toriginal.Scheme, original.Host)\n\t\t}\n\t\t// The transport's TLS config was computed for the ORIGINAL host. With the development\n\t\t// escape engaged for a loopback host, a redirect elsewhere would carry the disabled\n\t\t// verification along to a host the escape never covered.\n\t\tif tlsInsecureDevEscape(original.Hostname()) {\n\t\t\treturn fmt.Errorf(\"refused redirect to %s: TESL_HTTP_TLS_INSECURE_DEV relaxes TLS \"+\n\t\t\t\t\"verification for the loopback host %s only\", next.URL, original.Hostname())\n\t\t}\n\t\treturn nil\n\t}\n}\n\nfunc httpRequestNetwork(method, target string, parsed *url.URL, wire http.Header,\n\tbody *string, checkRedirect func(*http.Request, []*http.Request) error) HttpResponse {\n\tvar reader io.Reader\n\tif body != nil {\n\t\treader = strings.NewReader(*body)\n\t}\n\trequest, err := http.NewRequest(method, target, reader)\n\tif err != nil {\n\t\tpanic(fmt.Sprintf(\"HttpClient: HTTP %s to %s failed: %s\", method, target, err.Error()))\n\t}\n\trequest.Header = wire\n\tif telemetryTraceEnabled() && request.Header.Get(\"traceparent\") == \"\" {\n\t\trequest.Header.Set(\"traceparent\", \"00-\"+telemetryID(16)+\"-\"+telemetryID(8)+\"-01\")\n\t}\n\tclient := &http.Client{\n\t\tTransport: outboundTransport(parsed.Hostname()),\n\t\tTimeout:   millisDuration(httpReadTimeoutMs()),\n\t\t// A redirect is a fresh request to an attacker-influenced location. The shared\n\t\t// transport gives it the same egress treatment as the first hop; `redirectCheck`\n\t\t// decides the rest \226\128\148 downgrade, origin change with secrets, hop cap, or none at all.\n\t\tCheckRedirect: checkRedirect,\n\t}\n\tresponse, err := client.Do(request)\n\tif err != nil {\n\t\tpanic(requestFailure(method, target, err))\n\t}\n\tif response == nil {\n\t\t// net/http never answers with neither a response nor an error; a transport that did\n\t\t// would make the reads below a nil dereference rather than a failed call.\n\t\tpanic(fmt.Sprintf(\"HttpClient: HTTP %s to %s failed: no response\", method, target))\n\t}\n\tdefer func() { _ = response.Body.Close() }()\n\tlimit := httpMaxResponseBytes()\n\traw, err := io.ReadAll(io.LimitReader(response.Body, int64(limit)+1))\n\tif err != nil {\n\t\tpanic(fmt.Sprintf(\"HttpClient: HTTP %s to %s failed: %s\", method, target, err.Error()))\n\t}\n\tif len(raw) > limit {\n\t\tpanic(fmt.Sprintf(\"HttpClient: response body exceeds the %d-byte cap\", limit))\n\t}\n\treturn HttpResponse{\n\t\tStatus:  FromInt64(int64(response.StatusCode)),\n\t\tBody:    string(raw),\n\t\tHeaders: responseHeaders(response.Header),\n\t}\n}\n\n// requestFailure turns a transport error into the message the Racket client raises for the\n// same condition, because the test double's traps are written to match it byte for byte \226\128\148 a\n// test that asserts on a timeout must describe what production logs.\n//\n// net/http wraps everything in a `Get \"url\": \226\128\166` url.Error, so the reason is unwrapped first;\n// otherwise every failure would read as a repeat of the URL.\nfunc requestFailure(method, target string, err error) string {\n\tmessage := err.Error()\n\tvar urlErr *url.Error\n\tif errors.As(err, &urlErr) {\n\t\tmessage = urlErr.Err.Error()\n\t}\n\t// The egress refusal is raised by the dialer's Control hook, so it arrives buried in a\n\t// dial error. It is a REFUSAL, not a transport fault, and reads as one.\n\tif index := strings.Index(message, \"SSRF: refused egress\"); index >= 0 {\n\t\treturn \"HttpClient: \" + message[index:]\n\t}\n\t// Likewise a redirect the policy refused: `CheckRedirect` errors come back wrapped in the\n\t// url.Error for the redirect TARGET, and the refusal is the message, not the target.\n\tif index := strings.Index(message, \"refused redirect\"); index >= 0 {\n\t\treturn \"HttpClient: \" + message[index:]\n\t}\n\tif isTimeout(err) {\n\t\t// A deadline that expired during the DIAL is the connect deadline; anything later is\n\t\t// the response deadline. Racket names them separately for the same reason: they are\n\t\t// tuned by different env vars.\n\t\tif dialTimeout(err) {\n\t\t\treturn fmt.Sprintf(\"HttpClient: connect to %s timed out after %dms\",\n\t\t\t\ttarget, httpConnectTimeoutMs())\n\t\t}\n\t\treturn fmt.Sprintf(\"HttpClient: HTTP %s to %s timed out after %dms\",\n\t\t\tmethod, target, httpReadTimeoutMs())\n\t}\n\treturn fmt.Sprintf(\"HttpClient: HTTP %s to %s failed: %s\", method, target, message)\n}\n\nfunc isTimeout(err error) bool {\n\tvar timeout interface{ Timeout() bool }\n\tif errors.As(err, &timeout) && timeout.Timeout() {\n\t\treturn true\n\t}\n\treturn errors.Is(err, context.DeadlineExceeded)\n}\n\nfunc dialTimeout(err error) bool {\n\tvar opErr *net.OpError\n\tif !errors.As(err, &opErr) || opErr == nil {\n\t\treturn false\n\t}\n\treturn opErr.Op == \"dial\" && opErr.Timeout()\n}\n\nfunc responseHeaders(header http.Header) []Tuple2[string, string] {\n\theaders := make([]Tuple2[string, string], 0, len(header))\n\tnames := make([]string, 0, len(header))\n\tfor name := range header {\n\t\tnames = append(names, name)\n\t}\n\tsort.Strings(names)\n\tfor _, name := range names {\n\t\tfor _, value := range header[name] {\n\t\t\theaders = append(headers, Tuple2[string, string]{Tuple2First: name, Tuple2Second: value})\n\t\t}\n\t}\n\treturn headers\n}\n\n// outboundTransport is built per call because both of its policies depend on the target\n// host: the egress judgement is per connection, and the TLS development escape is\n// loopback-only. Connection reuse is given up for that, which costs a handshake on a\n// repeated call and buys a policy that cannot be inherited from an earlier, different one.\nfunc outboundTransport(host string) *http.Transport {\n\tdialer := &net.Dialer{\n\t\tTimeout: millisDuration(httpConnectTimeoutMs()),\n\t\t// Control runs after resolution with the address that is ABOUT to be connected, and\n\t\t// the connect then uses that same address. There is therefore no check-then-rebind\n\t\t// gap: a DNS answer cannot be swapped for an internal address after being judged.\n\t\tControl: func(_network, address string, _conn syscall.RawConn) error {\n\t\t\tpeer, _, err := net.SplitHostPort(address)\n\t\t\tif err != nil {\n\t\t\t\treturn fmt.Errorf(\"SSRF: refused egress to an unparseable peer address %q\", address)\n\t\t\t}\n\t\t\tif reason := SsrfEgressRefusal(peer); reason != \"\" {\n\t\t\t\treturn fmt.Errorf(\"SSRF: refused egress to %s \226\128\148 it resolves to %s, which is %s\",\n\t\t\t\t\thost, peer, reason)\n\t\t\t}\n\t\t\treturn nil\n\t\t},\n\t}\n\treturn &http.Transport{\n\t\tDialContext:       dialer.DialContext,\n\t\tTLSClientConfig:   outboundTLSConfig(host),\n\t\tForceAttemptHTTP2: true,\n\t\tDisableKeepAlives: true,\n\t}\n}\n\n// outboundTLSConfig verifies the peer's certificate chain AND hostname \226\128\148 Go's default, kept\n// explicit here because the one escape below is the only thing allowed to weaken it.\nfunc outboundTLSConfig(host string) *tls.Config {\n\tif tlsInsecureDevEscape(host) {\n\t\t// #nosec G402 -- The single development escape, and the reason it is safe: it engages\n\t\t// only when TESL_HTTP_TLS_INSECURE_DEV is set, only in a build that is not\n\t\t// TESL_DEPLOYED, and only for a loopback host, so the peer is a service on this\n\t\t// machine. It exists so a developer can talk to a local service presenting a\n\t\t// self-signed certificate; for any routable host the branch is not taken.\n\t\treturn &tls.Config{MinVersion: tls.VersionTLS12, InsecureSkipVerify: true}\n\t}\n\treturn &tls.Config{MinVersion: tls.VersionTLS12}\n}\n\nvar (\n\ttlsDevWarnActive  sync.Once\n\ttlsDevWarnRefused sync.Once\n)\n\nfunc tlsInsecureDevEscape(host string) bool {\n\tif envPresent(\"TESL_DEPLOYED\") || !envTruthy(\"TESL_HTTP_TLS_INSECURE_DEV\") {\n\t\treturn false\n\t}\n\tif HostLoopback(host) {\n\t\ttlsDevWarnActive.Do(func() {\n\t\t\tfmt.Fprintln(os.Stderr, \"WARNING: TESL_HTTP_TLS_INSECURE_DEV active -- HTTPS \"+\n\t\t\t\t\"certificate verification is DISABLED for loopback hosts only. \"+\n\t\t\t\t\"Never enable this in production.\")\n\t\t})\n\t\treturn true\n\t}\n\ttlsDevWarnRefused.Do(func() {\n\t\tfmt.Fprintf(os.Stderr, \"WARNING: TESL_HTTP_TLS_INSECURE_DEV is set but host %q is \"+\n\t\t\t\"not loopback -- TLS verification stays ON.\\n\", host)\n\t})\n\treturn false\n}\n");
  ("httpstub.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"strings\"\n\t\"sync\"\n)\n\n// The outbound-HTTP test double.\n//\n// Without it, every handler or worker that talks to an external service has an untestable\n// branch \226\128\148 and the branches most worth covering (an upstream 500, malformed JSON, a timeout)\n// are exactly the ones a real upstream will not produce on demand. A test declares its\n// answers up front:\n//\n//\tstubHttp        \"GET\"  \"https://rates.test/v1\"  200 \"{\\\"usd\\\":110}\"\n//\tstubHttpFailure \"POST\" \"https://rates.test/log\" \"connection refused\"\n//\tstubHttpTimeout \"GET\"  \"https://rates.test/slow\"\n//\n// and asserts afterwards with httpCalled / httpCallCount / httpLastBody.\n//\n// SCOPE. The table is cleared at the top of every emitted test function, so rules and the\n// call log cannot leak from one test block into the next \226\128\148 the isolation the Racket side gets\n// from a parameter that unwinds with the test body. Go's `go test` runs a package's tests\n// sequentially unless a test opts into t.Parallel, which emitted tests never do, so one\n// package-level table is enough and a stub is visible to the goroutines a test starts\n// (a queue worker's outbound call is the case that matters).\n//\n// PRODUCTION. `active` is false until an emitted test clears the table, and only a test file\n// does that, so a production build can never answer a call from here. That is a weaker\n// guarantee than Racket's (where the double lives in a module a production run does not\n// instantiate at all) and it is the strongest one available inside a single Go package.\ntype httpStubRule struct {\n\tmethod  string\n\turl     string\n\tkind    httpStubKind\n\tstatus  int64\n\tpayload string // the canned body, the failure message, or \"\" for a timeout\n}\n\ntype httpStubKind int\n\nconst (\n\thttpStubRespond httpStubKind = iota\n\thttpStubFail\n\thttpStubTimeout\n)\n\ntype httpStubCall struct {\n\tmethod string\n\turl    string\n\tbody   string\n}\n\nvar httpStubs = struct {\n\tmutex  sync.Mutex\n\tactive bool\n\trules  []httpStubRule\n\tcalls  []httpStubCall\n}{}\n\n// ResetHttpStubs gives the current test a fresh, empty stub table. Emitted test functions\n// call it before their first statement.\nfunc ResetHttpStubs() {\n\thttpStubs.mutex.Lock()\n\tdefer httpStubs.mutex.Unlock()\n\thttpStubs.active = true\n\thttpStubs.rules = nil\n\thttpStubs.calls = nil\n}\n\nfunc requireStubScope(who string) {\n\tif !httpStubs.active {\n\t\tpanic(who + \": outbound-HTTP stubs are only available inside a test body.\\n\" +\n\t\t\t\"  Call this from a `test`, `api-test`, or `load-test` block \226\128\148 the stub\\n\" +\n\t\t\t\"  scope is created per test so nothing leaks between them.\")\n\t}\n}\n\n// \226\148\128\226\148\128 Declaring a stub \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// StubHttp declares a canned response. Rules are consulted in DECLARATION order (first\n// match wins), so a specific stub declared before a `\"*\"` catch-all keeps winning;\n// re-declaring the exact same (method, url) pattern REPLACES the earlier rule in place, so a\n// later line in the same test overrides an earlier one rather than being shadowed by it.\nfunc StubHttp(method, target string, status Int, body string) struct{} {\n\tvalue, exact := status.Int64()\n\tif !exact {\n\t\tpanic(\"stubHttp: expected an Int status\")\n\t}\n\treturn addHTTPStubRule(\"stubHttp\", httpStubRule{\n\t\tmethod: method, url: target, kind: httpStubRespond, status: value, payload: body,\n\t})\n}\n\n// StubHttpFailure declares that the call fails the way a refused connection does.\nfunc StubHttpFailure(method, target, message string) struct{} {\n\treturn addHTTPStubRule(\"stubHttpFailure\", httpStubRule{\n\t\tmethod: method, url: target, kind: httpStubFail, payload: message,\n\t})\n}\n\n// StubHttpTimeout declares that the call blows its deadline.\nfunc StubHttpTimeout(method, target string) struct{} {\n\treturn addHTTPStubRule(\"stubHttpTimeout\", httpStubRule{\n\t\tmethod: method, url: target, kind: httpStubTimeout,\n\t})\n}\n\nfunc addHTTPStubRule(who string, rule httpStubRule) struct{} {\n\trequireStubScope(who)\n\thttpStubs.mutex.Lock()\n\tdefer httpStubs.mutex.Unlock()\n\tfor index, existing := range httpStubs.rules {\n\t\tif existing.method == rule.method && existing.url == rule.url {\n\t\t\thttpStubs.rules[index] = rule\n\t\t\treturn struct{}{}\n\t\t}\n\t}\n\thttpStubs.rules = append(httpStubs.rules, rule)\n\treturn struct{}{}\n}\n\n// \226\148\128\226\148\128 Matching \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// httpStubPatternMatches is deliberately NOT a regex: a stub pattern is a test fixture, and\n// `*` plus a trailing-`*` prefix covers every shape the lessons need without putting a second\n// pattern language into the surface. Method matching is case-insensitive; URL matching is not.\nfunc httpStubPatternMatches(pattern, value string, foldCase bool) bool {\n\tif foldCase {\n\t\tpattern = strings.ToLower(pattern)\n\t\tvalue = strings.ToLower(value)\n\t}\n\tswitch {\n\tcase pattern == \"*\":\n\t\treturn true\n\tcase strings.HasSuffix(pattern, \"*\"):\n\t\treturn strings.HasPrefix(value, strings.TrimSuffix(pattern, \"*\"))\n\tdefault:\n\t\treturn pattern == value\n\t}\n}\n\nfunc (rule httpStubRule) matches(method, target string) bool {\n\treturn httpStubPatternMatches(rule.method, method, true) &&\n\t\thttpStubPatternMatches(rule.url, target, false)\n}\n\n// httpStubAnswer is the seam tesl/http-client.rkt reaches through its hook parameter.\n// `false` means no stub is in force, which is only possible when the test declared no stubs\n// at all \226\128\148 so an existing test that really wants the network behaves as before. Once a test\n// declares its first stub, an unmatched call is a loud failure instead of a silent live\n// request.\nfunc httpStubAnswer(method, target string, body *string) (HttpResponse, bool) {\n\thttpStubs.mutex.Lock()\n\tif !httpStubs.active {\n\t\thttpStubs.mutex.Unlock()\n\t\treturn HttpResponse{}, false\n\t}\n\tsent := \"\"\n\tif body != nil {\n\t\tsent = *body\n\t}\n\t// The call is recorded BEFORE it is matched, so `httpCalled` sees a call that then failed\n\t// for want of a stub \226\128\148 which is what a test asserting on the failure needs.\n\thttpStubs.calls = append(httpStubs.calls,\n\t\thttpStubCall{method: strings.ToUpper(method), url: target, body: sent})\n\trules := make([]httpStubRule, len(httpStubs.rules))\n\tcopy(rules, httpStubs.rules)\n\thttpStubs.mutex.Unlock()\n\n\tif len(rules) == 0 {\n\t\treturn HttpResponse{}, false\n\t}\n\tfor _, rule := range rules {\n\t\tif !rule.matches(method, target) {\n\t\t\tcontinue\n\t\t}\n\t\tswitch rule.kind {\n\t\tcase httpStubTimeout:\n\t\t\t// Byte-for-byte the message the real deadline produces, so a test written against\n\t\t\t// the stub matches what production logs.\n\t\t\tpanic(fmt.Sprintf(\"HttpClient: HTTP %s to %s timed out after %dms\",\n\t\t\t\tstrings.ToUpper(method), target, httpReadTimeoutMs()))\n\t\tcase httpStubFail:\n\t\t\tpanic(fmt.Sprintf(\"HttpClient: HTTP %s to %s failed: %s\",\n\t\t\t\tstrings.ToUpper(method), target, rule.payload))\n\t\tcase httpStubRespond:\n\t\t\treturn HttpResponse{\n\t\t\t\tStatus:  FromInt64(rule.status),\n\t\t\t\tBody:    rule.payload,\n\t\t\t\tHeaders: []Tuple2[string, string]{},\n\t\t\t}, true\n\t\t}\n\t}\n\tpanic(fmt.Sprintf(\"HttpClient: no stub matches %s %s\\n\"+\n\t\t\"  This test declared outbound-HTTP stubs, so no call reaches the network.\\n\"+\n\t\t\"  declared: %s\\n\"+\n\t\t\"  hint: add `stubHttp %q %q 200 \\\"\226\128\166\\\"`, or widen a pattern with a trailing *.\",\n\t\tstrings.ToUpper(method), target, describeHTTPStubRules(rules),\n\t\tstrings.ToUpper(method), target))\n}\n\nfunc describeHTTPStubRules(rules []httpStubRule) string {\n\tif len(rules) == 0 {\n\t\treturn \"(none)\"\n\t}\n\tdescribed := make([]string, 0, len(rules))\n\tfor _, rule := range rules {\n\t\tswitch rule.kind {\n\t\tcase httpStubRespond:\n\t\t\tdescribed = append(described,\n\t\t\t\tfmt.Sprintf(\"%s %s -> status %d\", rule.method, rule.url, rule.status))\n\t\tcase httpStubFail:\n\t\t\tdescribed = append(described,\n\t\t\t\tfmt.Sprintf(\"%s %s -> failure %q\", rule.method, rule.url, rule.payload))\n\t\tcase httpStubTimeout:\n\t\t\tdescribed = append(described, fmt.Sprintf(\"%s %s -> timeout\", rule.method, rule.url))\n\t\t}\n\t}\n\treturn strings.Join(described, \"\\n            \")\n}\n\n// \226\148\128\226\148\128 Asserting on the calls made \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nfunc matchingHTTPCalls(who, method, target string) []httpStubCall {\n\trequireStubScope(who)\n\thttpStubs.mutex.Lock()\n\tdefer httpStubs.mutex.Unlock()\n\tmatched := make([]httpStubCall, 0, len(httpStubs.calls))\n\tfor _, call := range httpStubs.calls {\n\t\tif httpStubPatternMatches(method, call.method, true) &&\n\t\t\thttpStubPatternMatches(target, call.url, false) {\n\t\t\tmatched = append(matched, call)\n\t\t}\n\t}\n\treturn matched\n}\n\nfunc HttpCallCount(method, target string) Int {\n\treturn FromInt64(int64(len(matchingHTTPCalls(\"httpCallCount\", method, target))))\n}\n\nfunc HttpCalled(method, target string) bool {\n\treturn len(matchingHTTPCalls(\"httpCalled\", method, target)) > 0\n}\n\n// HttpLastBody is the body of the most recent matching call, or a trap naming the calls that\n// were made \226\128\148 a test asserting on a body it never sent is a broken test, not a false one.\nfunc HttpLastBody(method, target string) string {\n\tmatched := matchingHTTPCalls(\"httpLastBody\", method, target)\n\tif len(matched) == 0 {\n\t\tpanic(fmt.Sprintf(\"httpLastBody: no outbound %s call matched %q\\n  calls made: %s\",\n\t\t\tmethod, target, describeHTTPCallsMade()))\n\t}\n\treturn matched[len(matched)-1].body\n}\n\nfunc describeHTTPCallsMade() string {\n\thttpStubs.mutex.Lock()\n\tdefer httpStubs.mutex.Unlock()\n\tif len(httpStubs.calls) == 0 {\n\t\treturn \"(none)\"\n\t}\n\tdescribed := make([]string, 0, len(httpStubs.calls))\n\tfor _, call := range httpStubs.calls {\n\t\tdescribed = append(described, call.method+\" \"+call.url)\n\t}\n\treturn strings.Join(described, \", \")\n}\n");
  ("int.go", "// Package teslrt contains the small, audited runtime core used by emitted Tesl\n// programs.\npackage teslrt\n\nimport (\n\t\"errors\"\n\t\"hash/fnv\"\n\t\"math\"\n\t\"math/big\"\n)\n\nvar (\n\tErrDivisionByZero = errors.New(\"teslrt.Int: division by zero\")\n\tErrNegativePower  = errors.New(\"teslrt.Int: negative exponent\")\n\tErrPowTooLarge    = errors.New(\"teslrt.Int: exponent is too large for Int.pow (the result would exceed 1048576 bits)\")\n\tErrInvalidFloat   = errors.New(\"teslrt.Int: NaN and infinity are not integers\")\n\tErrInvalidInt     = errors.New(\"teslrt.Int: invalid decimal integer\")\n)\n\n// maxPowResultBits bounds the bit length of an Int.pow RESULT. It is a denial-of-service\n// bound, not a numeric limit: Int stays arbitrary-precision, and the checked int64 fast\n// path plus the math/big spill apply unchanged to every power below it. Without a bound\n// an exponent taken from a request (`Int.pow base n`) pins a core for minutes and\n// allocates gigabytes before the handler's recover ever runs \226\128\148 math/big exponentiation\n// is not interruptible. 1<<20 bits is a 128 KiB result, far past anything an integer\n// program computes on purpose, and still costs only milliseconds to produce.\nconst maxPowResultBits = 1 << 20\n\n// Int is Tesl's arbitrary-precision integer. The zero value is zero.\n//\n// big is non-nil exactly when the value is outside the int64 range. noCompare\n// makes raw == and map[Int] compile errors; callers must use Equal and Key.\ntype Int struct {\n\tnoCompare [0]func()\n\tsmall     int64\n\tbig       *big.Int\n}\n\n// IntKey is the canonical, comparable key for an Int.\ntype IntKey string\n\nfunc FromInt64(value int64) Int {\n\treturn Int{small: value}\n}\n\n// maxDecimalDigits bounds the decimal text ANY Int is parsed from \226\128\148 a JSON literal, a path\n// capture, `String.toInt`. `big.Int.SetString` is quadratic in the digit count, so a\n// 900 000-digit path segment (well under the 1 MiB header limit) cost ~1.7 s of CPU before\n// the capture's own check ever ran. One bound at the one choke point, rather than per caller:\n// the first fix capped only the JSON path and the whitebox campaign walked in through the\n// other two. 4096 digits is ~13 600 bits, far beyond any value a program can mean.\nconst maxDecimalDigits = 4096\n\n// ErrIntTooLong is the refusal for a decimal text over maxDecimalDigits.\nvar ErrIntTooLong = errors.New(\"integer literal has more than 4096 digits\")\n\n// ParseDecimal parses an optional sign followed by one or more decimal digits.\nfunc ParseDecimal(value string) (Int, error) {\n\tif len(value) > maxDecimalDigits+1 {\n\t\treturn Int{}, ErrIntTooLong\n\t}\n\tif !validDecimal(value, true) {\n\t\treturn Int{}, ErrInvalidInt\n\t}\n\tn, ok := new(big.Int).SetString(value, 10)\n\tif !ok {\n\t\treturn Int{}, ErrInvalidInt\n\t}\n\treturn fromBig(n), nil\n}\n\nfunc MustParseDecimal(value string) Int {\n\tn, err := ParseDecimal(value)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\treturn n\n}\n\n// FromFloat64 truncates toward zero, matching Tesl's Int.fromFloat semantics.\nfunc FromFloat64(value float64) (Int, error) {\n\tif math.IsNaN(value) || math.IsInf(value, 0) {\n\t\treturn Int{}, ErrInvalidFloat\n\t}\n\tn, _ := big.NewFloat(value).Int(nil)\n\treturn fromBig(n), nil\n}\n\nfunc fromBig(value *big.Int) Int {\n\tif value == nil {\n\t\treturn Int{}\n\t}\n\tif value.IsInt64() {\n\t\treturn FromInt64(value.Int64())\n\t}\n\treturn Int{big: new(big.Int).Set(value)}\n}\n\n// bigInt always returns a new value. No operation may mutate an Int operand.\nfunc (n Int) bigInt() *big.Int {\n\t_ = n.noCompare\n\tif n.big == nil {\n\t\treturn big.NewInt(n.small)\n\t}\n\treturn new(big.Int).Set(n.big)\n}\n\nfunc validDecimal(value string, allowPlus bool) bool {\n\tif value == \"\" {\n\t\treturn false\n\t}\n\tstart := 0\n\tif value[0] == '-' || (allowPlus && value[0] == '+') {\n\t\tstart = 1\n\t}\n\tif start == len(value) {\n\t\treturn false\n\t}\n\tfor i := start; i < len(value); i++ {\n\t\tif value[i] < '0' || value[i] > '9' {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n\nfunc Add(left, right Int) Int {\n\tif left.big == nil && right.big == nil {\n\t\tif (right.small > 0 && left.small <= math.MaxInt64-right.small) ||\n\t\t\t(right.small < 0 && left.small >= math.MinInt64-right.small) ||\n\t\t\tright.small == 0 {\n\t\t\treturn FromInt64(left.small + right.small)\n\t\t}\n\t}\n\treturn fromBig(new(big.Int).Add(left.bigInt(), right.bigInt()))\n}\n\nfunc Sub(left, right Int) Int {\n\tif left.big == nil && right.big == nil {\n\t\tif (right.small > 0 && left.small >= math.MinInt64+right.small) ||\n\t\t\t(right.small < 0 && left.small <= math.MaxInt64+right.small) ||\n\t\t\tright.small == 0 {\n\t\t\treturn FromInt64(left.small - right.small)\n\t\t}\n\t}\n\treturn fromBig(new(big.Int).Sub(left.bigInt(), right.bigInt()))\n}\n\nfunc Mul(left, right Int) Int {\n\tif left.big == nil && right.big == nil {\n\t\tif left.small == 0 || right.small == 0 {\n\t\t\treturn Int{}\n\t\t}\n\t\tif (left.small != math.MinInt64 || right.small != -1) &&\n\t\t\t(right.small != math.MinInt64 || left.small != -1) {\n\t\t\tproduct := left.small * right.small\n\t\t\tif product/right.small == left.small {\n\t\t\t\treturn FromInt64(product)\n\t\t\t}\n\t\t}\n\t}\n\treturn fromBig(new(big.Int).Mul(left.bigInt(), right.bigInt()))\n}\n\nfunc Neg(value Int) Int {\n\tif value.big == nil && value.small != math.MinInt64 {\n\t\treturn FromInt64(-value.small)\n\t}\n\treturn fromBig(new(big.Int).Neg(value.bigInt()))\n}\n\n// IntGcd is Racket's `gcd`: always NON-NEGATIVE, and gcd(0, 0) is 0. The sign of either\n// operand does not reach the answer, which is what makes `gcd a b == gcd (-a) b` hold.\nfunc IntGcd(left, right Int) Int {\n\tfirst := new(big.Int).Abs(left.bigInt())\n\tsecond := new(big.Int).Abs(right.bigInt())\n\treturn fromBig(new(big.Int).GCD(nil, nil, first, second))\n}\n\n// IntLcm is Racket's `lcm`: non-negative, and 0 whenever either operand is 0 (there is no\n// smaller common multiple than 0 in that case, and dividing by gcd(0,0) would trap).\nfunc IntLcm(left, right Int) Int {\n\tfirst := new(big.Int).Abs(left.bigInt())\n\tsecond := new(big.Int).Abs(right.bigInt())\n\tif first.Sign() == 0 || second.Sign() == 0 {\n\t\treturn FromInt64(0)\n\t}\n\tdivisor := new(big.Int).GCD(nil, nil, first, second)\n\treturn fromBig(new(big.Int).Div(new(big.Int).Mul(first, second), divisor))\n}\n\nfunc Abs(value Int) Int {\n\tif value.Sign() >= 0 {\n\t\treturn value\n\t}\n\treturn Neg(value)\n}\n\n// Quo truncates toward zero.\nfunc Quo(dividend, divisor Int) (Int, error) {\n\tif divisor.IsZero() {\n\t\treturn Int{}, ErrDivisionByZero\n\t}\n\tif dividend.big == nil && divisor.big == nil &&\n\t\t(dividend.small != math.MinInt64 || divisor.small != -1) {\n\t\treturn FromInt64(dividend.small / divisor.small), nil\n\t}\n\treturn fromBig(new(big.Int).Quo(dividend.bigInt(), divisor.bigInt())), nil\n}\n\n// MustQuo is used by emitted code after Tesl has proved the divisor non-zero.\n// It still fails closed if compiler/runtime invariants drift.\nfunc MustQuo(dividend, divisor Int) Int {\n\tvalue, err := Quo(dividend, divisor)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\treturn value\n}\n\n// Rem is the truncating remainder. A non-zero result has the dividend's sign.\nfunc Rem(dividend, divisor Int) (Int, error) {\n\tif divisor.IsZero() {\n\t\treturn Int{}, ErrDivisionByZero\n\t}\n\tif dividend.big == nil && divisor.big == nil {\n\t\treturn FromInt64(dividend.small % divisor.small), nil\n\t}\n\treturn fromBig(new(big.Int).Rem(dividend.bigInt(), divisor.bigInt())), nil\n}\n\nfunc MustRem(dividend, divisor Int) Int {\n\tvalue, err := Rem(dividend, divisor)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\treturn value\n}\n\n// Mod matches Racket modulo: a non-zero result has the divisor's sign.\nfunc Mod(dividend, divisor Int) (Int, error) {\n\tremainder, err := Rem(dividend, divisor)\n\tif err != nil || remainder.IsZero() || remainder.Sign() == divisor.Sign() {\n\t\treturn remainder, err\n\t}\n\treturn Add(remainder, divisor), nil\n}\n\nfunc MustMod(dividend, divisor Int) Int {\n\tvalue, err := Mod(dividend, divisor)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\treturn value\n}\n\n// Pow is base^exponent for a non-negative exponent. The result's size is bounded BEFORE\n// exponentiating (see maxPowResultBits): bits(base^n) <= bits(base)*n, so the bound is\n// decided from the operands alone in constant time, and an exponent that does not even\n// fit int64 is refused by the same rule without ever being converted.\nfunc Pow(base, exponent Int) (Int, error) {\n\tif exponent.Sign() < 0 {\n\t\treturn Int{}, ErrNegativePower\n\t}\n\t// |base| <= 1 (0, 1, -1) is cheap for ANY exponent: the result is 0, 1 or -1, so it\n\t// is decided here rather than measured against the bound.\n\tbaseBits := base.bigInt().BitLen()\n\tif baseBits <= 1 {\n\t\tswitch {\n\t\tcase exponent.IsZero():\n\t\t\treturn FromInt64(1), nil\n\t\tcase base.IsZero():\n\t\t\treturn Int{}, nil\n\t\tcase base.Sign() > 0 || exponent.IsEven():\n\t\t\treturn FromInt64(1), nil\n\t\tdefault:\n\t\t\treturn FromInt64(-1), nil\n\t\t}\n\t}\n\t// |base| >= 2 from here, so baseBits >= 2 and any exponent beyond int64 is already\n\t// past the bound. The division form avoids overflowing baseBits*power.\n\tpower, fits := exponent.Int64()\n\tif !fits || power > int64(maxPowResultBits)/int64(baseBits) {\n\t\treturn Int{}, ErrPowTooLarge\n\t}\n\treturn fromBig(new(big.Int).Exp(base.bigInt(), big.NewInt(power), nil)), nil\n}\n\nfunc GCD(left, right Int) Int {\n\treturn fromBig(new(big.Int).GCD(nil, nil, left.bigInt(), right.bigInt()))\n}\n\nfunc LCM(left, right Int) Int {\n\tif left.IsZero() || right.IsZero() {\n\t\treturn Int{}\n\t}\n\tgcd := GCD(left, right)\n\tquotient, err := Quo(Abs(left), gcd)\n\tif err != nil {\n\t\tpanic(\"unreachable: non-zero gcd\")\n\t}\n\treturn Mul(quotient, Abs(right))\n}\n\nfunc Min(left, right Int) Int {\n\tif Compare(left, right) <= 0 {\n\t\treturn left\n\t}\n\treturn right\n}\n\nfunc Max(left, right Int) Int {\n\tif Compare(left, right) >= 0 {\n\t\treturn left\n\t}\n\treturn right\n}\n\nfunc Clamp(value, low, high Int) Int {\n\treturn Max(low, Min(high, value))\n}\n\nfunc Compare(left, right Int) int {\n\tif left.big == nil && right.big == nil {\n\t\tswitch {\n\t\tcase left.small < right.small:\n\t\t\treturn -1\n\t\tcase left.small > right.small:\n\t\t\treturn 1\n\t\tdefault:\n\t\t\treturn 0\n\t\t}\n\t}\n\treturn left.bigInt().Cmp(right.bigInt())\n}\n\nfunc Equal(left, right Int) bool {\n\treturn Compare(left, right) == 0\n}\n\nfunc (n Int) Sign() int {\n\tif n.big != nil {\n\t\treturn n.big.Sign()\n\t}\n\tswitch {\n\tcase n.small < 0:\n\t\treturn -1\n\tcase n.small > 0:\n\t\treturn 1\n\tdefault:\n\t\treturn 0\n\t}\n}\n\nfunc (n Int) IsZero() bool {\n\treturn n.big == nil && n.small == 0\n}\n\nfunc (n Int) IsPositive() bool {\n\treturn n.Sign() > 0\n}\n\nfunc (n Int) IsNegative() bool {\n\treturn n.Sign() < 0\n}\n\nfunc (n Int) IsEven() bool {\n\tif n.big == nil {\n\t\treturn n.small%2 == 0\n\t}\n\treturn n.big.Bit(0) == 0\n}\n\nfunc (n Int) IsOdd() bool {\n\treturn !n.IsEven()\n}\n\nfunc (n Int) Digits() int {\n\ttext := n.String()\n\tif text[0] == '-' {\n\t\treturn len(text) - 1\n\t}\n\treturn len(text)\n}\n\nfunc (n Int) String() string {\n\tif n.big == nil {\n\t\treturn big.NewInt(n.small).String()\n\t}\n\treturn n.big.String()\n}\n\nfunc (n Int) Int64() (int64, bool) {\n\tif n.big != nil {\n\t\treturn 0, false\n\t}\n\treturn n.small, true\n}\n\nfunc (n Int) Float64() float64 {\n\tif n.big == nil {\n\t\treturn float64(n.small)\n\t}\n\tvalue, _ := new(big.Float).SetInt(n.big).Float64()\n\treturn value\n}\n\nfunc (n Int) Key() IntKey {\n\treturn IntKey(n.String())\n}\n\nfunc (n Int) Hash64() uint64 {\n\thash := fnv.New64a()\n\t_, _ = hash.Write([]byte(n.String()))\n\treturn hash.Sum64()\n}\n\nfunc (n Int) MarshalJSON() ([]byte, error) {\n\treturn []byte(n.String()), nil\n}\n\nfunc (n *Int) UnmarshalJSON(data []byte) error {\n\ttext := string(data)\n\tif !validJSONInteger(text) {\n\t\treturn ErrInvalidInt\n\t}\n\tvalue, err := ParseDecimal(text)\n\tif err != nil {\n\t\treturn err\n\t}\n\t*n = value\n\treturn nil\n}\n\nfunc validJSONInteger(value string) bool {\n\tif len(value) > maxDecimalDigits+1 || !validDecimal(value, false) {\n\t\treturn false\n\t}\n\tstart := 0\n\tif value[0] == '-' {\n\t\tstart = 1\n\t}\n\tif value[start] == '0' && len(value)-start > 1 {\n\t\treturn false\n\t}\n\treturn true\n}\n\n// IntNonZero and IntNonNegative are Tesl's `Int.nonZero` / `Int.nonNegative`\n// checks: the proof they mint erases, the rejection does not. The messages and the\n// 400 status are observable behavior and match the Racket implementations.\nfunc IntNonZero(value Int) Check[Int] {\n\tif value.IsZero() {\n\t\treturn Reject[Int](400, \"expected a non-zero integer\")\n\t}\n\treturn Accept(value)\n}\n\nfunc IntNonNegative(value Int) Check[Int] {\n\tif value.Sign() < 0 {\n\t\treturn Reject[Int](400, \"expected a non-negative integer\")\n\t}\n\treturn Accept(value)\n}\n\n// The Tesl.Int leaves the emitter calls as plain functions. Clamp, Pow, IsEven and IsOdd\n// already exist above; these are the wrappers for what is otherwise only a method, plus\n// the sign and power shapes Tesl's own signatures describe.\n\n// IntSign is -1, 0 or 1, matching Int.sign in tesl/int.rkt.\nfunc IntSign(value Int) Int {\n\treturn FromInt64(int64(value.Sign()))\n}\n\nfunc IntIsEven(value Int) bool {\n\treturn value.IsEven()\n}\n\nfunc IntIsOdd(value Int) bool {\n\treturn value.IsOdd()\n}\n\nfunc IntToString(value Int) string {\n\treturn value.String()\n}\n\n// MustPow raises rather than returning an error, matching Int.pow in tesl/int.rkt, which\n// rejects a negative exponent outright: there is no integer result, and Float.pow is the\n// function for a fractional one. An exponent past maxPowResultBits traps the same way\n// (ErrPowTooLarge); inside a handler, callHandler turns the trap into a sanitized 500.\nfunc MustPow(base, exponent Int) Int {\n\tresult, err := Pow(base, exponent)\n\tif err != nil {\n\t\tpanic(\"Int.pow: \" + err.Error())\n\t}\n\treturn result\n}\n");
  ("int32.go", "package teslrt\n\nimport \"math/big\"\n\n// `Tesl.Int32` \226\128\148 a JS-safe, 32-bit-bounded integer for wire and storage boundaries.\n//\n// `Int32` is NOMINAL at the type level (it does not unify with `Int`) and at run time it IS its\n// underlying integer \226\128\148 `tesl/int32.rkt` says exactly that, and the Go emitter follows by\n// rendering the type as `teslrt.Int`. Nothing here carries a wrapper, so an Int32 crossing into\n// `Int` arithmetic costs nothing and the two backends store the same value.\n//\n// The split that makes the type worth having: an operation that CANNOT leave [-2^31, 2^31)\n// answers the value, and one that CAN answers a `Maybe`. That is a property of the operation,\n// not of the inputs, so it is visible in the signature rather than discovered at run time.\nvar (\n\tint32Low  = FromInt64(-2147483648)\n\tint32High = FromInt64(2147483647)\n)\n\n// Int32InRange is the ONE range decision every operation below funnels through.\nfunc Int32InRange(value Int) bool {\n\treturn Compare(value, int32Low) >= 0 && Compare(value, int32High) <= 0\n}\n\nfunc int32Narrow(value Int) Maybe[Int] {\n\tif Int32InRange(value) {\n\t\treturn Something(value)\n\t}\n\treturn Nothing[Int]()\n}\n\n// Int32MinValue and Int32MaxValue are the bounds, as values rather than calls \226\128\148 that is how\n// `Int32.minValue` reads in Tesl.\nvar (\n\tInt32MinValue = int32Low\n\tInt32MaxValue = int32High\n)\n\n// \226\148\128\226\148\128 Conversions \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nfunc Int32FromInt(value Int) Maybe[Int] { return int32Narrow(value) }\n\n// Int32ToInt is total: widening always fits.\nfunc Int32ToInt(value Int) Int { return value }\n\n// Int32FromIntClamped saturates. Total, and explicit in the name that it CHANGES the value \226\128\148\n// use `Int32.fromInt` where out-of-range has to be visible.\nfunc Int32FromIntClamped(value Int) Int {\n\treturn Max(int32Low, Min(int32High, value))\n}\n\nfunc Int32Parse(text string) Maybe[Int] {\n\tparsed := StringToInt(text)\n\tif !parsed.IsSomething() {\n\t\treturn Nothing[Int]()\n\t}\n\treturn int32Narrow(parsed.SomethingValue)\n}\n\n// Int32FromFloat truncates toward zero, then range-checks. A NaN or an infinity has no integer\n// truncation, so it is Nothing rather than a trap.\nfunc Int32FromFloat(value float64) Maybe[Int] {\n\ttruncated := FloatToInt(value)\n\tif !truncated.IsSomething() {\n\t\treturn Nothing[Int]()\n\t}\n\treturn int32Narrow(truncated.SomethingValue)\n}\n\nfunc Int32ToFloat(value Int) float64 { return value.Float64() }\n\nfunc Int32ToString(value Int) string { return value.String() }\n\n// \226\148\128\226\148\128 Range-closed operations \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nfunc Int32Min(left, right Int) Int { return Min(left, right) }\n\nfunc Int32Max(left, right Int) Int { return Max(left, right) }\n\nfunc Int32Clamp(value, low, high Int) Int { return Max(low, Min(high, value)) }\n\n// Int32Modulo is the remainder, which |b| \226\137\164 2^31 keeps in range. The divisor carries an\n// `IsNonZero` proof, which erases \226\128\148 so the zero guard here is what is left of it, and it traps\n// with the message `tesl/int32.rkt` raises.\nfunc Int32Modulo(dividend, divisor Int) Int {\n\tif divisor.IsZero() {\n\t\tpanic(\"Int32.modulo: division by zero \226\128\148 use `check Int32.nonZero(b)` before calling Int32.modulo\")\n\t}\n\treturn MustRem(dividend, divisor)\n}\n\n// \226\148\128\226\148\128 Operations that can leave the range \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nfunc Int32Add(left, right Int) Maybe[Int] { return int32Narrow(Add(left, right)) }\n\nfunc Int32Subtract(left, right Int) Maybe[Int] { return int32Narrow(Sub(left, right)) }\n\nfunc Int32Multiply(left, right Int) Maybe[Int] { return int32Narrow(Mul(left, right)) }\n\n// Negate and Abs overflow on exactly one input: -2^31 has no positive counterpart.\nfunc Int32Negate(value Int) Maybe[Int] { return int32Narrow(Neg(value)) }\n\nfunc Int32Abs(value Int) Maybe[Int] { return int32Narrow(Abs(value)) }\n\n// Int32Pow answers Nothing for a negative exponent (an integer power would be fractional) and\n// for an out-of-range result. The exponent is bounded BEFORE the power is taken: 2^2000000000\n// cannot fit either way, and computing that bignum first would burn memory to reach the same\n// Nothing. |base| > 1 needs at most 31 doublings to leave the range; 0, 1 and -1 never do.\nfunc Int32Pow(base, exponent Int) Maybe[Int] {\n\tif exponent.Sign() < 0 {\n\t\treturn Nothing[Int]()\n\t}\n\tif Compare(Abs(base), FromInt64(1)) > 0 && Compare(exponent, FromInt64(31)) > 0 {\n\t\treturn Nothing[Int]()\n\t}\n\traised, err := Pow(base, exponent)\n\tif err != nil {\n\t\treturn Nothing[Int]()\n\t}\n\treturn int32Narrow(raised)\n}\n\n// Int32Divide is integer division truncating toward zero. The divisor carries an `IsNonZero`\n// proof; Nothing covers the single overflowing quotient, -2^31 / -1 = 2^31.\nfunc Int32Divide(dividend, divisor Int) Maybe[Int] {\n\tif divisor.IsZero() {\n\t\tpanic(\"Int32.divide: division by zero \226\128\148 use `check Int32.nonZero(b)` before calling Int32.divide\")\n\t}\n\treturn int32Narrow(MustQuo(dividend, divisor))\n}\n\n// \226\148\128\226\148\128 Predicates and queries \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nfunc Int32IsPositive(value Int) bool { return value.IsPositive() }\n\nfunc Int32IsNegative(value Int) bool { return value.IsNegative() }\n\nfunc Int32IsZero(value Int) bool { return value.IsZero() }\n\nfunc Int32IsEven(value Int) bool { return value.IsEven() }\n\nfunc Int32IsOdd(value Int) bool { return value.IsOdd() }\n\n// Int32Sign answers an `Int` rather than an Int32, so it composes with Int arithmetic and\n// compares against Int literals \226\128\148 the shape `Int.sign` has.\nfunc Int32Sign(value Int) Int { return FromInt64(int64(value.Sign())) }\n\n// Int32Digits counts the digits of the magnitude, so zero has one.\nfunc Int32Digits(value Int) Int {\n\treturn FromInt64(int64(len(new(big.Int).Abs(value.bigInt()).String())))\n}\n\n// \226\148\128\226\148\128 Proof-minting checks \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// The proofs erase, so what is left is the predicate and its refusal.\n\nfunc Int32NonZero(value Int) Check[Int] {\n\tif value.IsZero() {\n\t\treturn Reject[Int](400, \"expected a non-zero Int32\")\n\t}\n\treturn Accept(value)\n}\n\nfunc Int32NonNegative(value Int) Check[Int] {\n\tif value.IsNegative() {\n\t\treturn Reject[Int](400, \"expected a non-negative Int32\")\n\t}\n\treturn Accept(value)\n}\n");
  ("json.go", "package teslrt\n\nimport (\n\t\"encoding/json\"\n\t\"errors\"\n\t\"fmt\"\n\t\"io\"\n\t\"math\"\n\t\"math/big\"\n\t\"sort\"\n\t\"strings\"\n)\n\n// JSON decoding for codecs.\n//\n// The one non-obvious requirement is INTEGER PRECISION. Tesl's Int is arbitrary\n// precision and Racket's JSON reader returns exact integers, so `{\"n\": 1234567890123\n// 45678901234567890}` round-trips there. Go's encoding/json decodes a number into\n// float64 when the target is `any`, which would silently round that to\n// 1.2345678901234568e+29 \226\128\148 wrong, and only for values above 2^53, so small tests would\n// never catch it. Every parse therefore goes through UseNumber and integers are read\n// from the decimal digits.\n//\n// Object key ORDER on the way out is alphabetical, matching Racket's `jsexpr->string`\n// (verified: it sorts). Go's own map marshalling sorts too, but a struct would emit in\n// field-declaration order, so encoding goes through a map rather than a generated\n// struct \226\128\148 the response bytes are observable and the two backends must agree.\n\n// ParseJSON parses a request body. A parse failure is the caller's to report, matching\n// the \"Malformed JSON payload\" 400 the Racket server produces.\n//\n// The body must be EXACTLY ONE JSON value. `json.Decoder` reads a stream, so on its own it\n// would accept `{\"n\":1} garbage` and `{\"n\":1}{\"n\":2}` and answer the first document \226\128\148 which\n// is not what Racket's `string->jsexpr` does (it rejects trailing content) and is the seam a\n// proxy or WAF that parsed the same bytes as \"malformed\" would disagree with the app across.\n// The check is a second Decode that must hit EOF: `decoder.More()` is not enough because it\n// answers false for a stray `}` as well as for the end of input.\nfunc ParseJSON(data []byte) (any, error) {\n\tdecoder := json.NewDecoder(strings.NewReader(string(data)))\n\tdecoder.UseNumber()\n\tvar value any\n\tif err := decoder.Decode(&value); err != nil {\n\t\treturn nil, err\n\t}\n\tvar trailing any\n\tif err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {\n\t\treturn nil, errors.New(\"unexpected content after the JSON value\")\n\t}\n\treturn value, nil\n}\n\n// maxJSONIntegerDigits bounds the decimal literal an `Int` field accepts. `big.Int.SetString`\n// is quadratic in the digit count, so a 1 MiB body of digits \226\128\148 inside the body cap \226\128\148 costs\n// about two seconds of CPU per request: an amplification vector rather than a hang, closed\n// by refusing the literal before the conversion starts. 4096 digits is ~13600 bits, far past\n// any quantity a program models as an Int.\nconst maxJSONIntegerDigits = maxDecimalDigits\n\n// parseJSONInteger is the one place a JSON number becomes an `Int`, for the field and value\n// decoders alike. The messages name the SHAPE of what arrived and never echo it: a decode\n// error is answered to the client as the 400 body, and reflecting a 1 MiB submitted value\n// (in Go `map[...]` syntax, no less) back at it is noise at best.\nfunc parseJSONInteger(raw any) (Int, error) {\n\tnumber, ok := raw.(json.Number)\n\tif !ok {\n\t\treturn Int{}, fmt.Errorf(\"expected JSON integer, got %s\", jsonTypeName(raw))\n\t}\n\tdigits := number.String()\n\tif len(digits) > maxJSONIntegerDigits {\n\t\treturn Int{}, fmt.Errorf(\"JSON integer has %d digits; at most %d are accepted\",\n\t\t\tlen(digits), maxJSONIntegerDigits)\n\t}\n\tvalue, ok := new(big.Int).SetString(digits, 10)\n\tif !ok {\n\t\treturn Int{}, errors.New(\"expected JSON integer, got a non-integer number\")\n\t}\n\treturn fromBig(value), nil\n}\n\n// jsonField returns the raw value at key. A missing field is an error rather than a\n// zero value: Racket raises `codec: required field \"x\" not found in JSON` here, and the\n// server turns any decode exception into a generic 400 \226\128\148 so the TEXT is not observable\n// by default, but the failure must still happen.\nfunc jsonField(object any, key string) (any, error) {\n\tfields, ok := object.(map[string]any)\n\tif !ok {\n\t\treturn nil, fmt.Errorf(\"codec: expected a JSON object\")\n\t}\n\tvalue, present := fields[key]\n\tif !present {\n\t\treturn nil, fmt.Errorf(\"codec: required field %q not found in JSON\", key)\n\t}\n\treturn value, nil\n}\n\n// HasJSONField reports whether a key is present, for an alternative that only applies\n// when a field exists.\nfunc HasJSONField(object any, key string) bool {\n\tfields, ok := object.(map[string]any)\n\tif !ok {\n\t\treturn false\n\t}\n\t_, present := fields[key]\n\treturn present\n}\n\nfunc DecodeStringField(object any, key string) (string, error) {\n\traw, err := jsonField(object, key)\n\tif err != nil {\n\t\treturn \"\", err\n\t}\n\ttext, ok := raw.(string)\n\tif !ok {\n\t\treturn \"\", fmt.Errorf(\"expected JSON string, got %s\", jsonTypeName(raw))\n\t}\n\treturn text, nil\n}\n\n// DecodeIntField reads the decimal digits rather than a float64, so an integer wider\n// than 2^53 survives.\nfunc DecodeIntField(object any, key string) (Int, error) {\n\traw, err := jsonField(object, key)\n\tif err != nil {\n\t\treturn Int{}, err\n\t}\n\treturn parseJSONInteger(raw)\n}\n\nfunc DecodeBoolField(object any, key string) (bool, error) {\n\traw, err := jsonField(object, key)\n\tif err != nil {\n\t\treturn false, err\n\t}\n\tflag, ok := raw.(bool)\n\tif !ok {\n\t\treturn false, fmt.Errorf(\"expected JSON boolean, got %s\", jsonTypeName(raw))\n\t}\n\treturn flag, nil\n}\n\nfunc DecodeFloatField(object any, key string) (float64, error) {\n\traw, err := jsonField(object, key)\n\tif err != nil {\n\t\treturn 0, err\n\t}\n\tnumber, ok := raw.(json.Number)\n\tif !ok {\n\t\treturn 0, fmt.Errorf(\"expected JSON number, got %s\", jsonTypeName(raw))\n\t}\n\treturn number.Float64()\n}\n\n// DecodeStringValue decodes an already-extracted value, for a nested codec whose field\n// was read by the caller (an `adtJson` type decodes from a bare JSON string).\nfunc DecodeStringValue(raw any) (string, error) {\n\ttext, ok := raw.(string)\n\tif !ok {\n\t\treturn \"\", fmt.Errorf(\"expected JSON string, got %s\", jsonTypeName(raw))\n\t}\n\treturn text, nil\n}\n\nfunc JSONFieldValue(object any, key string) (any, error) {\n\treturn jsonField(object, key)\n}\n\n// jsonTypeName names a parsed JSON shape for an error message. It lives HERE rather than beside\n// the api-test assertions because `json.go` ships with every program while the api-test half\n// does not, and the ADT tag decoder below needs it.\nfunc jsonTypeName(raw any) string {\n\tswitch raw.(type) {\n\tcase nil:\n\t\treturn \"null\"\n\tcase json.Number:\n\t\treturn \"number\"\n\tcase string:\n\t\treturn \"string\"\n\tcase bool:\n\t\treturn \"boolean\"\n\tcase []any:\n\t\treturn \"array\"\n\tcase map[string]any:\n\t\treturn \"object\"\n\tdefault:\n\t\treturn fmt.Sprintf(\"%T\", raw)\n\t}\n}\n\n// DecodeAdtTag reads the constructor name an `adtJson` codec decodes from. Racket's generated\n// decoder accepts BOTH shapes \226\128\148 `{\"tag\": \"Ctor\"}`, which is what its encoder writes, and a bare\n// \"Ctor\" string, which is what an Elm or hand-written client may send \226\128\148 so this does too.\nfunc DecodeAdtTag(raw any) (string, error) {\n\tswitch typed := raw.(type) {\n\tcase string:\n\t\treturn typed, nil\n\tcase map[string]any:\n\t\tfound, present := typed[\"tag\"]\n\t\tif !present {\n\t\t\treturn \"\", fmt.Errorf(\"expected {\\\"tag\\\": ...} or a string, got an object with no tag\")\n\t\t}\n\t\tname, ok := found.(string)\n\t\tif !ok {\n\t\t\treturn \"\", fmt.Errorf(\"expected a string tag, got %s\", jsonTypeName(found))\n\t\t}\n\t\treturn name, nil\n\tdefault:\n\t\treturn \"\", fmt.Errorf(\"expected {\\\"tag\\\": ...} or a string, got %s\", jsonTypeName(raw))\n\t}\n}\n\n// EncodeJSON renders an object. Keys are emitted in sorted order to match Racket, which\n// is why this takes a map rather than marshalling a generated struct.\nfunc EncodeJSON(fields map[string]any) string {\n\tvar builder strings.Builder\n\tbuilder.WriteByte('{')\n\tkeys := make([]string, 0, len(fields))\n\tfor key := range fields {\n\t\tkeys = append(keys, key)\n\t}\n\tsort.Strings(keys)\n\tfor index, key := range keys {\n\t\tif index > 0 {\n\t\t\tbuilder.WriteByte(',')\n\t\t}\n\t\tname, _ := json.Marshal(key)\n\t\tbuilder.Write(name)\n\t\tbuilder.WriteByte(':')\n\t\tbuilder.WriteString(EncodeJSONValue(fields[key]))\n\t}\n\tbuilder.WriteByte('}')\n\treturn builder.String()\n}\n\n// EncodeJSONValue renders one value. `Int` is rendered from its decimal digits so a\n// bignum is not routed through a float, and a nested object keeps the sorted-key rule.\n//\n// A NON-FINITE Float TRAPS. JSON has no NaN or infinity, and `FormatFloat` \226\128\148 the display\n// formatter \226\128\148 spells them `NaN`/`+Inf`/`-Inf`, which a client's JSON parser rejects: a handler\n// answering `Float.exp 1000.0` would send a `200 application/json` whose body is not JSON.\n// Racket's `jsexpr->string` raises on `+inf.0`, and this is that raise; `writeResponse` turns\n// it into the sanitized 500 every other trap becomes. `null` was the alternative and is worse:\n// it would let the overflow pass as \"no value\" and be stored or summed downstream.\nfunc EncodeJSONValue(value any) string {\n\tswitch typed := value.(type) {\n\tcase Int:\n\t\treturn typed.String()\n\tcase map[string]any:\n\t\treturn EncodeJSON(typed)\n\tcase []any:\n\t\tparts := make([]string, len(typed))\n\t\tfor index, element := range typed {\n\t\t\tparts[index] = EncodeJSONValue(element)\n\t\t}\n\t\treturn \"[\" + strings.Join(parts, \",\") + \"]\"\n\tcase float64:\n\t\tif math.IsNaN(typed) || math.IsInf(typed, 0) {\n\t\t\tpanic(\"codec: a Float \" + FormatFloat(typed) + \" cannot be encoded as JSON\")\n\t\t}\n\t\treturn FormatFloat(typed)\n\tdefault:\n\t\tencoded, err := json.Marshal(typed)\n\t\tif err != nil {\n\t\t\tpanic(\"codec: value cannot be encoded as JSON\")\n\t\t}\n\t\treturn string(encoded)\n\t}\n}\n\n// DecodeObjectShape is the shape check a DERIVED record decoder runs before reading any\n// field: a record with no `codec` block still decodes from JSON, and the rule it follows is\n// the Racket runtime's generic decode (dsl/types.rkt `jsexpr->typed-value`) \226\128\148 the object's\n// keys must be EXACTLY the record's fields. A missing field is a 400 because the field has no\n// value to take, and an EXTRA field is a 400 too, which is the surprising half: silently\n// ignoring unknown keys is how a typo'd field name becomes a silent default.\nfunc DecodeObjectShape(raw any, typeName string, expected []string) (map[string]any, error) {\n\tfields, ok := raw.(map[string]any)\n\tif !ok {\n\t\treturn nil, fmt.Errorf(\"expected record JSON for type %s, got %s\", typeName, jsonTypeName(raw))\n\t}\n\tmissing := make([]string, 0, len(expected))\n\tfor _, name := range expected {\n\t\tif _, present := fields[name]; !present {\n\t\t\tmissing = append(missing, name)\n\t\t}\n\t}\n\tif len(missing) > 0 {\n\t\treturn nil, fmt.Errorf(\"record JSON for type %s is missing field%s (%s)\",\n\t\t\ttypeName, plural(len(missing)), strings.Join(missing, \" \"))\n\t}\n\textra := make([]string, 0, len(fields))\n\tfor name := range fields {\n\t\tif !containsName(expected, name) {\n\t\t\textra = append(extra, name)\n\t\t}\n\t}\n\tif len(extra) > 0 {\n\t\tsort.Strings(extra)\n\t\treturn nil, fmt.Errorf(\"record JSON for type %s has unexpected field%s (%s)\",\n\t\t\ttypeName, plural(len(extra)), strings.Join(extra, \" \"))\n\t}\n\treturn fields, nil\n}\n\nfunc plural(count int) string {\n\tif count == 1 {\n\t\treturn \"\"\n\t}\n\treturn \"s\"\n}\n\nfunc containsName(names []string, wanted string) bool {\n\tfor _, name := range names {\n\t\tif name == wanted {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// The value-level counterparts of the DecodeXField helpers, for a derived decoder that has\n// already taken the object apart (and for a list element, which has no key at all).\n\nfunc DecodeIntValue(raw any) (Int, error) {\n\treturn parseJSONInteger(raw)\n}\n\nfunc DecodeBoolValue(raw any) (bool, error) {\n\tflag, ok := raw.(bool)\n\tif !ok {\n\t\treturn false, fmt.Errorf(\"expected JSON boolean, got %s\", jsonTypeName(raw))\n\t}\n\treturn flag, nil\n}\n\nfunc DecodeFloatValue(raw any) (float64, error) {\n\tnumber, ok := raw.(json.Number)\n\tif !ok {\n\t\treturn 0, fmt.Errorf(\"expected JSON number, got %s\", jsonTypeName(raw))\n\t}\n\treturn number.Float64()\n}\n\n// DecodeListValue decodes a JSON array element-wise through `element`, so a derived decoder\n// composes over `List T` without the emitter writing the loop at every use.\nfunc DecodeListValue[Element any](raw any, element func(any) (Element, error)) ([]Element, error) {\n\titems, ok := raw.([]any)\n\tif !ok {\n\t\treturn nil, fmt.Errorf(\"expected JSON array, got %s\", jsonTypeName(raw))\n\t}\n\tout := make([]Element, 0, len(items))\n\tfor _, item := range items {\n\t\tdecoded, err := element(item)\n\t\tif err != nil {\n\t\t\treturn nil, err\n\t\t}\n\t\tout = append(out, decoded)\n\t}\n\treturn out, nil\n}\n\n// CheckedDecoder adapts a codec's `Check`-answering decoder to the `(value, error)` shape\n// the container readers walk with, so one loop decodes a list of scalars and a list of\n// records alike. The check's own message is carried through, which is what the client sees.\nfunc CheckedDecoder[T any](decode func(any) Check[T]) func(any) (T, error) {\n\treturn func(raw any) (T, error) {\n\t\tresult := decode(raw)\n\t\tvalue, ok := result.Value()\n\t\tif !ok {\n\t\t\treturn value, errors.New(result.Message())\n\t\t}\n\t\treturn value, nil\n\t}\n}\n\n// The column-decoder half of the ADT wire shape: reading a stored `{\"tag\": \226\128\166, \"fields\": {\226\128\166}}`\n// back into the value it was written from.\n//\n// Each of these PANICS on a mismatch rather than answering a zero value. A column holds data\n// this build wrote, so a field of the wrong shape is corruption or an incompatible schema \226\128\148\n// the same line the tag switch takes for a tag it has no constructor for. A request body is\n// the opposite case and goes through the `Decode*` functions above, which answer an error.\n\n// ParseColumnJSON parses the text of a jsonb column that holds an ADT.\n//\n// It accepts BOTH shapes a Tesl backend writes there. This backend writes a JSON object.\n// `dsl/sql.rkt` binds the serialised value as a STRING parameter, so a row written by the\n// Racket backend holds a jsonb string whose contents are that object \226\128\148 `\"{\\\"tag\\\":\\\"Low\\\"}\"`\n// rather than `{\"tag\": \"Low\"}`. The Racket reader accepts either, and this one has to as well:\n// a service being ported reads the rows it already has, and refusing the incumbent shape would\n// make every existing ADT column unreadable.\n//\n// Exactly ONE layer is unwrapped. A stored value that is a string all the way down is not an\n// ADT under either backend's encoding, and unwrapping repeatedly would turn a corrupt column\n// into a plausible one.\nfunc ParseColumnJSON(data []byte) (any, error) {\n\tparsed, err := ParseJSON(data)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\ttext, isText := parsed.(string)\n\tif !isText {\n\t\treturn parsed, nil\n\t}\n\treturn ParseJSON([]byte(text))\n}\n\n// MustJSONFields is the `fields` object of a stored variant.\nfunc MustJSONFields(parsed any, typeName, variant string) any {\n\tobject, isObject := parsed.(map[string]any)\n\tif !isObject {\n\t\tpanic(\"database: a \" + typeName + \" column does not hold a JSON object\")\n\t}\n\tfields, present := object[\"fields\"]\n\tif !present {\n\t\tpanic(\"database: a \" + typeName + \" column's \" + variant + \" carries fields, but the \" +\n\t\t\t\"stored value has no \\\"fields\\\" object\")\n\t}\n\treturn fields\n}\n\n// MustJSONField is one labelled field of that object.\nfunc MustJSONField(fields any, label string) any {\n\tobject, isObject := fields.(map[string]any)\n\tif !isObject {\n\t\tpanic(\"database: a stored variant's \\\"fields\\\" is not a JSON object\")\n\t}\n\tvalue, present := object[label]\n\tif !present {\n\t\tpanic(\"database: a stored variant is missing the field \" + label)\n\t}\n\treturn value\n}\n\nfunc MustDecodeString(raw any) string {\n\tvalue, err := DecodeStringValue(raw)\n\tif err != nil {\n\t\tpanic(\"database: \" + err.Error())\n\t}\n\treturn value\n}\n\nfunc MustDecodeInt(raw any) Int {\n\tvalue, err := DecodeIntValue(raw)\n\tif err != nil {\n\t\tpanic(\"database: \" + err.Error())\n\t}\n\treturn value\n}\n\nfunc MustDecodeFloat(raw any) float64 {\n\tnumber, isNumber := raw.(json.Number)\n\tif !isNumber {\n\t\tpanic(\"database: expected a stored number\")\n\t}\n\tvalue, err := number.Float64()\n\tif err != nil {\n\t\tpanic(\"database: \" + err.Error())\n\t}\n\treturn value\n}\n\nfunc MustDecodeBool(raw any) bool {\n\tvalue, isBool := raw.(bool)\n\tif !isBool {\n\t\tpanic(\"database: expected a stored boolean\")\n\t}\n\treturn value\n}\n\n// MustEncodeJSON re-serialises a decoded sub-value, so a NESTED ADT field can go through the\n// same column decoder its own type already has rather than needing a second one.\nfunc MustEncodeJSON(raw any) []byte {\n\tencoded, err := json.Marshal(raw)\n\tif err != nil {\n\t\tpanic(\"database: a stored value does not re-encode: \" + err.Error())\n\t}\n\treturn encoded\n}\n\n// MaybeOfJSON reads a stored `Maybe` field.\n//\n// A `Maybe` inside a variant is written as the TAGGED shape every other ADT gets \226\128\148\n// `{\"tag\":\"Nothing\"}` / `{\"tag\":\"Something\",\"fields\":{\"value\":\226\128\166}}` \226\128\148 because that is what the\n// value encoder and `dsl/types.rkt` both write for it. It is NOT a JSON null: null is what a\n// nullable COLUMN holds, and a field inside a stored variant is not a column.\nfunc MaybeOfJSON[A any](raw any, decode func(any) A) Maybe[A] {\n\tobject, isObject := raw.(map[string]any)\n\tif !isObject {\n\t\tpanic(\"database: a stored Maybe field is not a JSON object\")\n\t}\n\ttag, _ := object[\"tag\"].(string)\n\tswitch tag {\n\tcase \"Nothing\":\n\t\treturn Nothing[A]()\n\tcase \"Something\":\n\t\treturn Something(decode(MustJSONField(MustJSONFields(raw, \"Maybe\", \"Something\"), \"value\")))\n\tdefault:\n\t\tpanic(\"database: a stored Maybe field holds an unknown tag \" + tag)\n\t}\n}\n");
  ("jws.go", "package teslrt\n\nimport (\n\t\"crypto\"\n\t\"crypto/ecdsa\"\n\t\"crypto/elliptic\"\n\t\"crypto/rsa\"\n\t\"crypto/sha256\"\n\t\"encoding/base64\"\n\t\"encoding/json\"\n\t\"math/big\"\n\t\"strings\"\n)\n\n// RS256/ES256 JWS signature verification for OIDC ID tokens \226\128\148 VERIFY only, no signing.\n//\n// A port of `dsl/private/jws-verify.rkt`. That module builds a SubjectPublicKeyInfo DER by\n// hand and hands it to libcrypto; Go's standard library takes the key components directly,\n// so the DER encoder has no counterpart here. Every REFUSAL does, and the refusals are the\n// product: alg:none, an HMAC alg on an ID token (sign-with-the-public-key), an alg outside\n// the pinned set, key material NOMINATED by the token header (jwk/jku/x5u/x5c) or a `crit`\n// header, a five-segment JWE, an RSA modulus below 2048 bits, and an unknown `kid`.\n//\n// Fail-closed everywhere: every path that is not a verified signature answers a reason.\n\n// nominatedHeaderKeys let a TOKEN choose the key it is verified against, which is the\n// oldest JWS bypass there is. Their mere presence is a refusal \226\128\148 not \"ignored\".\nvar nominatedHeaderKeys = []string{\"jwk\", \"jku\", \"x5u\", \"x5c\", \"crit\"}\n\n// base64URLBytes decodes a JWS segment or a JWK component. Strict for the same reason\n// jwt.go's decoder is: a signature must have ONE spelling, so a token string cannot be\n// re-encoded into an equivalent that a text-keyed control does not recognise.\nfunc base64URLBytes(text string) ([]byte, bool) {\n\tdecoded, err := base64.RawURLEncoding.Strict().DecodeString(strings.TrimRight(text, \"=\"))\n\tif err != nil {\n\t\treturn nil, false\n\t}\n\treturn decoded, true\n}\n\n// jwkKey is one JSON Web Key, in the shape the fields are read from.\ntype jwkKey struct {\n\tKid string `json:\"kid\"`\n\tKty string `json:\"kty\"`\n\tCrv string `json:\"crv\"`\n\tN   string `json:\"n\"`\n\tE   string `json:\"e\"`\n\tX   string `json:\"x\"`\n\tY   string `json:\"y\"`\n}\n\ntype jwkSet struct {\n\tKeys []jwkKey `json:\"keys\"`\n}\n\n// selectJwk picks the key the token names. With no `kid`, a set of exactly ONE key is\n// usable and a larger one is not: guessing which of several signed a token is how a\n// verifier ends up accepting the wrong signer.\nfunc selectJwk(set jwkSet, kid string) (jwkKey, bool) {\n\tif kid != \"\" {\n\t\tfor _, key := range set.Keys {\n\t\t\tif key.Kid == kid {\n\t\t\t\treturn key, true\n\t\t\t}\n\t\t}\n\t\treturn jwkKey{}, false\n\t}\n\tif len(set.Keys) == 1 {\n\t\treturn set.Keys[0], true\n\t}\n\treturn jwkKey{}, false\n}\n\n// verifyJws answers \"\" on a valid signature, or a short reason. `pinned` is the set of algs\n// the caller will accept, already intersected with what this implements.\nfunc verifyJws(token string, set jwkSet, pinned []string) string {\n\tparts := strings.Split(token, \".\")\n\tswitch {\n\tcase len(parts) == 5:\n\t\treturn \"a JWE (five-segment) token is not accepted\"\n\tcase len(parts) != 3:\n\t\treturn \"malformed JWS\"\n\t}\n\trawHeader, ok := base64URLBytes(parts[0])\n\tif !ok {\n\t\treturn \"unparseable JWS header\"\n\t}\n\tvar header map[string]any\n\tif json.Unmarshal(rawHeader, &header) != nil {\n\t\treturn \"unparseable JWS header\"\n\t}\n\tfor _, nominated := range nominatedHeaderKeys {\n\t\tif _, present := header[nominated]; present {\n\t\t\treturn \"token header nominates its own key (jwk/jku/x5u/x5c/crit) \226\128\148 refused\"\n\t\t}\n\t}\n\talg, _ := header[\"alg\"].(string)\n\tkid, _ := header[\"kid\"].(string)\n\tswitch {\n\tcase alg == \"\":\n\t\treturn \"alg absent\"\n\tcase strings.EqualFold(alg, \"none\"):\n\t\treturn \"alg:none refused\"\n\tcase strings.HasPrefix(strings.ToUpper(alg), \"HS\"):\n\t\treturn \"HMAC alg on an ID token refused\"\n\t}\n\tpermitted := false\n\tfor _, each := range pinned {\n\t\tif each == alg {\n\t\t\tpermitted = true\n\t\t}\n\t}\n\tif !permitted {\n\t\treturn \"alg not in the pinned set\"\n\t}\n\tkey, found := selectJwk(set, kid)\n\tif !found {\n\t\treturn \"no JWKS key matches the token kid\"\n\t}\n\tif alg == \"RS256\" && key.Kty != \"RSA\" {\n\t\treturn \"RS256 requires an RSA key\"\n\t}\n\tif alg == \"ES256\" && key.Kty != \"EC\" {\n\t\treturn \"ES256 requires an EC key\"\n\t}\n\tsignature, ok := base64URLBytes(parts[2])\n\tif !ok {\n\t\treturn \"malformed signature\"\n\t}\n\tdigest := sha256.Sum256([]byte(parts[0] + \".\" + parts[1]))\n\tif alg == \"RS256\" {\n\t\treturn verifyRS256(key, digest[:], signature)\n\t}\n\treturn verifyES256(key, digest[:], signature)\n}\n\nfunc verifyRS256(key jwkKey, digest, signature []byte) string {\n\tmodulus, okN := base64URLBytes(key.N)\n\texponent, okE := base64URLBytes(key.E)\n\tif !okN || !okE || len(modulus) == 0 || len(exponent) == 0 {\n\t\treturn \"unparseable RSA key\"\n\t}\n\t// The modulus bound is on its SIGNIFICANT bits: a leading zero byte is DER padding, not\n\t// key material, and counting it would let a 2040-bit key pass as 2048.\n\ttrimmed := modulus\n\tfor len(trimmed) > 1 && trimmed[0] == 0 {\n\t\ttrimmed = trimmed[1:]\n\t}\n\tif len(trimmed)*8 < 2048 {\n\t\treturn \"RSA modulus below 2048 bits\"\n\t}\n\tpublic := &rsa.PublicKey{\n\t\tN: new(big.Int).SetBytes(modulus),\n\t\tE: int(new(big.Int).SetBytes(exponent).Int64()),\n\t}\n\tif rsa.VerifyPKCS1v15(public, crypto.SHA256, digest, signature) != nil {\n\t\treturn \"signature verification failed\"\n\t}\n\treturn \"\"\n}\n\nfunc verifyES256(key jwkKey, digest, signature []byte) string {\n\tif key.Crv != \"P-256\" {\n\t\treturn \"unsupported EC curve\"\n\t}\n\tx, okX := base64URLBytes(key.X)\n\ty, okY := base64URLBytes(key.Y)\n\tif !okX || !okY {\n\t\treturn \"unparseable EC key\"\n\t}\n\t// A JWS ES256 signature is the raw r||s pair, 32 bytes each \226\128\148 not the DER\n\t// ECDSA-Sig-Value an ASN.1 verifier expects, which is why it is split rather than parsed.\n\tif len(signature) != 64 {\n\t\treturn \"malformed signature\"\n\t}\n\tpublic := &ecdsa.PublicKey{\n\t\tCurve: elliptic.P256(),\n\t\tX:     new(big.Int).SetBytes(x),\n\t\tY:     new(big.Int).SetBytes(y),\n\t}\n\tr := new(big.Int).SetBytes(signature[:32])\n\ts := new(big.Int).SetBytes(signature[32:])\n\tif !ecdsa.Verify(public, digest, r, s) {\n\t\treturn \"signature verification failed\"\n\t}\n\treturn \"\"\n}\n");
  ("jwt.go", "package teslrt\n\nimport (\n\t\"crypto/hmac\"\n\t\"encoding/base64\"\n\t\"encoding/json\"\n\t\"fmt\"\n\t\"sort\"\n\t\"strings\"\n\t\"sync\"\n\t\"time\"\n)\n\n// `Tesl.JWT`: the one blessed session token \226\128\148 HS256, in one fixed cookie, with no options.\n//\n// The signature is HMAC-SHA256 over `header.payload`, which is `Tesl.Crypto`'s primitive, so a\n// token minted by either backend verifies on the other. Verification never PARSES the header:\n// it recomputes the MAC over the received bytes verbatim, which is why a foreign token, or one\n// minted before `kid` was stamped, verifies exactly the same.\n//\n// The rules below are the Racket runtime's, and several of them are fail-closed decisions worth\n// keeping visible rather than re-deriving:\n//\n//\ta structurally malformed token is a 401, never a trap \226\128\148 it comes off the wire, so\n//\t`Cookie: session=garbage` must not be a client-triggerable 500;\n//\tan unreadable `exp` means EXPIRED, not absent \226\128\148 skipping the check would accept such a\n//\ttoken forever;\n//\ta missing `exp` is accepted, because `exp` is OPTIONAL per RFC 7519 and Tesl cannot mint a\n//\ttoken without one, so this only admits a foreign token;\n//\trenewal refuses without a usable `iat`, because an unbounded-age token must not be\n//\trenewable \226\128\148 that bound is what makes \"no server-side revocation\" a defensible design.\ntype JwtToken struct {\n\tValue string\n}\n\nconst (\n\t// The renewable window and the hard stop on a renewed session's total lifetime. The cap is\n\t// named rather than derived: applying a multiplier to a shorter TTL silently yields a cap\n\t// nobody chose.\n\tjwtTTLSeconds         = 3600\n\tjwtAbsoluteMaxSeconds = 12 * jwtTTLSeconds\n\t// `ShortSession`: 15 minutes renewable against an 8-hour (workday) cap. The pair is named\n\t// rather than derived from the TTL \226\128\148 applying the 12\195\151 multiplier to 15 minutes would yield a\n\t// 3-hour cap nobody chose. Same two numbers as `tesl/jwt.rkt`'s `short-session`.\n\tjwtShortTTLSeconds         = 900\n\tjwtShortAbsoluteMaxSeconds = 8 * 3600\n\t// The only tolerance granted to an `iat` ahead of this machine's clock: enough for ordinary\n\t// NTP drift between replicas, too small to meaningfully extend a session.\n\tjwtMaxClockSkewSeconds = 60\n)\n\n// \226\148\128\226\148\128 The session policy \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// Lives HERE rather than beside the SSO routes because it is a property of the TOKEN: it decides\n// the renewable window and the hard stop on a renewed session's total lifetime, and the SSO\n// cookie's Max-Age is a consumer of the first number rather than its owner. It was in\n// `sso_route.go`, which ships only with the SSO surface \226\128\148 so a program that used `JWT.sign`\n// without `sso` could not build once signing started reading the policy.\n// The session policy the `sessionPolicy` clause selects. It decides the session cookie's\n// Max-Age, so it is runtime state rather than a constant: a program that asks for\n// ShortSession must not be handed a StandardSession cookie by the other backend.\nvar (\n\tsessionPolicyMutex sync.RWMutex\n\tsessionPolicyTTL   = jwtTTLSeconds\n)\n\n// SetSessionPolicy is the `sessionPolicy` clause, applied at boot. The two names are a\n// CLOSED set on the surface, so an unknown one is a compile error rather than a default\n// here; this takes the ttl the emitter resolved from the name.\nfunc SetSessionPolicy(ttlSeconds int) {\n\tsessionPolicyMutex.Lock()\n\tdefer sessionPolicyMutex.Unlock()\n\tsessionPolicyTTL = ttlSeconds\n}\n\nfunc sessionPolicySeconds() int {\n\tsessionPolicyMutex.RLock()\n\tdefer sessionPolicyMutex.RUnlock()\n\treturn sessionPolicyTTL\n}\n\n// sessionPolicyAbsoluteMaxSeconds is the hard stop on a RENEWED session's total lifetime under\n// the active policy. Read here rather than fixed at the JWT layer because the policy is one\n// choice with two numbers: `ShortSession` that renewed against a 12-hour cap would be a shorter\n// window guarding the same total exposure, which is not what the clause says.\nfunc sessionPolicyAbsoluteMaxSeconds() int {\n\tif sessionPolicySeconds() == jwtShortTTLSeconds {\n\t\treturn jwtShortAbsoluteMaxSeconds\n\t}\n\treturn jwtAbsoluteMaxSeconds\n}\n\n// SessionPolicyTTL maps the surface's closed keyword set to its ttl in seconds. It lives\n// here rather than in the emitter so both backends read one table.\nfunc SessionPolicyTTL(name string) int {\n\tif name == \"ShortSession\" {\n\t\treturn jwtShortTTLSeconds\n\t}\n\treturn jwtTTLSeconds\n}\n\n// The OPTIONAL previous signing key. Verification accepts a token signed by either the current\n// key or this one, which is the overlap that lets a leaked key be rotated WITHOUT logging every\n// user out; signing and renewal always use the current key, so the slot drains on its own.\nvar (\n\tpreviousSessionKeyMutex sync.RWMutex\n\tpreviousSessionKey      *Secret\n)\n\n// SecretPointer is the one-line adapter the emitter needs: `SetPreviousSessionKey` takes a\n// pointer so that \"no previous key\" is a distinct state from \"the empty secret\", and an emitted\n// boot line has an expression rather than a variable to take the address of.\nfunc SecretPointer(secret Secret) *Secret { return &secret }\n\n// SetPreviousSessionKey installs (or, with nil, clears) the rotation overlap. Clearing it while\n// rotating the current key is the global kill switch.\nfunc SetPreviousSessionKey(key *Secret) {\n\tpreviousSessionKeyMutex.Lock()\n\tdefer previousSessionKeyMutex.Unlock()\n\tpreviousSessionKey = key\n}\n\n// The OPTIONAL revocation hook the `sessionRevoked` server clause installs.\n//\n// Consulted ONLY when a session RENEWS \226\128\148 never on the verify path, which stays byte-identical\n// and stateless. That bounds revocation latency to the renewable window at the cost of one read\n// per session per TTL, which is the trade `tesl/jwt.rkt` documents and makes.\nvar (\n\tsessionRevokedMutex sync.RWMutex\n\tsessionRevokedHook  func(subject string, issuedAtSeconds int64) bool\n)\n\n// SetSessionRevokedHook installs (or, with nil, clears) the renewal-time revocation check.\n// The hook takes the `sub` claim and `iat` in epoch SECONDS and answers true for a session that\n// may no longer renew.\nfunc SetSessionRevokedHook(hook func(subject string, issuedAtSeconds int64) bool) {\n\tsessionRevokedMutex.Lock()\n\tdefer sessionRevokedMutex.Unlock()\n\tsessionRevokedHook = hook\n}\n\n// sessionRevoked FAILS CLOSED: a hook that panics \226\128\148 a failing dbRead, a nil map \226\128\148 denies the\n// renewal rather than allowing it, which is the answer `tesl/jwt.rkt` gives for the same case\n// (\"any error from the hook denies the renewal\").\nfunc sessionRevoked(subject string, issuedAtSeconds int64) (revoked bool) {\n\tsessionRevokedMutex.RLock()\n\thook := sessionRevokedHook\n\tsessionRevokedMutex.RUnlock()\n\tif hook == nil {\n\t\treturn false\n\t}\n\tdefer func() {\n\t\tif recovered := recover(); recovered != nil {\n\t\t\trevoked = true\n\t\t}\n\t}()\n\treturn hook(subject, issuedAtSeconds)\n}\n\nfunc sessionKeys(current Secret) []string {\n\tpreviousSessionKeyMutex.RLock()\n\tdefer previousSessionKeyMutex.RUnlock()\n\tkeys := []string{current.Value.Reveal()}\n\tif previousSessionKey != nil {\n\t\tkeys = append(keys, previousSessionKey.Value.Reveal())\n\t}\n\treturn keys\n}\n\nfunc jwtNowSeconds() int64 { return time.Now().Unix() }\n\nfunc base64URL(raw []byte) string { return base64.RawURLEncoding.EncodeToString(raw) }\n\n// decodeBase64URL accepts the padded spelling too: a token arrives from another implementation,\n// and padding is the commonest harmless deviation.\n//\n// Both decoders are STRICT: the trailing bits a final character carries beyond the payload\n// must be zero. Without that, one signature has several spellings \226\128\148 flip a padding bit in the\n// last character and the token STRING changes while the bytes it decodes to do not \226\128\148 so a\n// denylist, a dedup key or an audit trail keyed on the token text can be sidestepped by an\n// equivalent spelling. A canonical encoder (ours, and every conforming one) never emits them.\nfunc decodeBase64URL(text string) ([]byte, bool) {\n\tif raw, err := base64.RawURLEncoding.Strict().DecodeString(text); err == nil {\n\t\treturn raw, true\n\t}\n\traw, err := base64.URLEncoding.Strict().DecodeString(text)\n\treturn raw, err == nil\n}\n\n// jwtHeader is assembled by string append rather than by marshalling a map, so the field order\n// is fixed (alg, typ, kid) and stable. `kid` is DERIVED from the key \226\128\148 a domain-separated,\n// truncated digest that is safe to log and is not proof of key possession \226\128\148 so there is no knob\n// here either, and no accessor: stamping is the part that is expensive to retrofit.\nfunc jwtHeader(key Secret) string {\n\treturn base64URL([]byte(`{\"alg\":\"HS256\",\"typ\":\"JWT\",\"kid\":\"` + KeyFingerprint(key) + `\"}`))\n}\n\nfunc jwtSignature(key, signingInput string) []byte {\n\treturn hmacSha256Bytes(key, signingInput)\n}\n\n// jwtPayload renders the claims. Keys are sorted so a token is a function of its claims and not\n// of map iteration order; `iat` and `exp` are NUMBERS, as RFC 7519 requires, while every claim a\n// program supplies is a String.\nfunc jwtPayload(claims Dict[string, string], issuedAt, expiresAt int64) string {\n\tvar builder strings.Builder\n\tbuilder.WriteString(\"{\")\n\tnames := make([]string, 0, len(claims.Entries))\n\tfor _, entry := range claims.Entries {\n\t\tnames = append(names, entry.Key)\n\t}\n\tsort.Strings(names)\n\tfor _, name := range names {\n\t\tvalue, _ := DictLookup(claims, name, stringKeyLess).Value()\n\t\tencoded, err := json.Marshal(value)\n\t\tif err != nil {\n\t\t\tpanic(\"JWT.sign: a claim value could not be encoded: \" + err.Error())\n\t\t}\n\t\tkey, err := json.Marshal(name)\n\t\tif err != nil {\n\t\t\tpanic(\"JWT.sign: a claim name could not be encoded: \" + err.Error())\n\t\t}\n\t\tbuilder.Write(key)\n\t\tbuilder.WriteString(\":\")\n\t\tbuilder.Write(encoded)\n\t\tbuilder.WriteString(\",\")\n\t}\n\tfmt.Fprintf(&builder, `\"iat\":%d,\"exp\":%d}`, issuedAt, expiresAt)\n\treturn base64URL([]byte(builder.String()))\n}\n\n// JwtSign is `JWT.sign`. It stamps BOTH `iat` and `exp` itself: `exp` because a caller who can\n// choose an expiry can choose ten years, and `iat` because renewal reads it to bound the total\n// lifetime of a session.\nfunc JwtSign(claims Dict[string, string], key Secret) JwtToken {\n\tfor _, reserved := range []string{\"exp\", \"iat\"} {\n\t\tif _, present := DictLookup(claims, reserved, stringKeyLess).Value(); present {\n\t\t\tpanic(fmt.Sprintf(\n\t\t\t\t\"JWT.sign: %s is not yours to set: JWT.sign stamps it itself, and there is no \"+\n\t\t\t\t\t\"parameter for it. Remove %s from the claims. If you need a credential that \"+\n\t\t\t\t\t\"outlives a session, a JWT is the wrong tool: use `Crypto.randomToken` and \"+\n\t\t\t\t\t\"store only its `Crypto.fingerprint`, which you can revoke.\", reserved, reserved))\n\t\t}\n\t}\n\tnow := jwtNowSeconds()\n\treturn signClaims(claims, key, now, now+int64(sessionPolicySeconds()))\n}\n\nfunc signClaims(claims Dict[string, string], key Secret, issuedAt, expiresAt int64) JwtToken {\n\tsigningInput := jwtHeader(key) + \".\" + jwtPayload(claims, issuedAt, expiresAt)\n\treturn JwtToken{\n\t\tValue: signingInput + \".\" + base64URL(jwtSignature(key.Value.Reveal(), signingInput)),\n\t}\n}\n\n// verifiedClaims is the parsed payload of a token whose signature checked out.\ntype verifiedClaims struct {\n\traw map[string]any\n}\n\n// verifyToken is the shared half of `JWT.verify` and `JWT.renew`, so the signature comparison,\n// the malformed-token rejections and the expiry rule cannot drift between verifying and\n// renewing.\nfunc verifyToken(token JwtToken, key Secret) (verifiedClaims, Check[Dict[string, string]]) {\n\tparts := strings.Split(token.Value, \".\")\n\tif len(parts) != 3 {\n\t\treturn verifiedClaims{}, Reject[Dict[string, string]](401, \"Invalid JWT format\")\n\t}\n\tsigningInput := parts[0] + \".\" + parts[1]\n\t// A signature segment that is not valid base64url falls through to the comparison with an\n\t// empty tag (which fails) rather than raising out of the handler.\n\tactual, _ := decodeBase64URL(parts[2])\n\tmatched := false\n\tfor _, candidate := range sessionKeys(key) {\n\t\t// Every candidate is compared in constant time; the NUMBER of keys (one or two) is not\n\t\t// secret.\n\t\tif hmac.Equal(jwtSignature(candidate, signingInput), actual) {\n\t\t\tmatched = true\n\t\t}\n\t}\n\tif !matched {\n\t\treturn verifiedClaims{}, Reject[Dict[string, string]](401, \"Invalid JWT signature\")\n\t}\n\tpayload, ok := decodeBase64URL(parts[1])\n\tif !ok {\n\t\treturn verifiedClaims{}, Reject[Dict[string, string]](401, \"Malformed JWT payload\")\n\t}\n\tdecoded, err := ParseJSON(payload)\n\tif err != nil {\n\t\treturn verifiedClaims{}, Reject[Dict[string, string]](401, \"Malformed JWT payload\")\n\t}\n\tclaims, isObject := decoded.(map[string]any)\n\tif !isObject {\n\t\treturn verifiedClaims{}, Reject[Dict[string, string]](401, \"Malformed JWT payload\")\n\t}\n\tif jwtExpired(claims) {\n\t\treturn verifiedClaims{}, Reject[Dict[string, string]](401, \"JWT token has expired\")\n\t}\n\treturn verifiedClaims{raw: claims}, Check[Dict[string, string]]{}\n}\n\n// jwtExpired reads `exp`. A MISSING claim means no expiry check (it is optional per the RFC and\n// Tesl always stamps one, so this only admits a foreign token); an UNREADABLE one means expired,\n// because skipping the check on a claim that cannot be read would accept the token forever.\nfunc jwtExpired(claims map[string]any) bool {\n\texpiry, present := claims[\"exp\"]\n\tif !present {\n\t\treturn false\n\t}\n\tseconds, ok := jsonSeconds(expiry)\n\tif !ok {\n\t\treturn true\n\t}\n\treturn seconds < jwtNowSeconds()\n}\n\nfunc jsonSeconds(value any) (int64, bool) {\n\tnumber, ok := value.(json.Number)\n\tif !ok {\n\t\treturn 0, false\n\t}\n\tif exact, err := number.Int64(); err == nil {\n\t\treturn exact, true\n\t}\n\t// A non-integral or oversized numeric claim: read it as a float and floor it, so a token\n\t// written by an implementation that emits `1.7853556e9` is still judged rather than refused.\n\tif approximate, err := number.Float64(); err == nil {\n\t\treturn int64(approximate), true\n\t}\n\treturn 0, false\n}\n\n// claimText renders a claim value as a String, which is what `Dict String String` promises. The\n// rule is `JWT.decode`'s, applied to verification too: a string is itself, a number or boolean\n// is its JSON text, null is \"null\", and an array or object is its compact JSON text.\n//\n// A note for authorization: an array claim decodes to JSON TEXT, which IS substring-matchable \226\128\148\n// do not branch on `String.contains` over it.\nfunc claimText(value any) string {\n\tswitch typed := value.(type) {\n\tcase nil:\n\t\treturn \"null\"\n\tcase string:\n\t\treturn typed\n\tcase bool:\n\t\tif typed {\n\t\t\treturn \"true\"\n\t\t}\n\t\treturn \"false\"\n\tcase json.Number:\n\t\treturn typed.String()\n\tdefault:\n\t\tencoded, err := json.Marshal(typed)\n\t\tif err != nil {\n\t\t\treturn fmt.Sprint(typed)\n\t\t}\n\t\treturn string(encoded)\n\t}\n}\n\nfunc claimsDict(claims map[string]any) Dict[string, string] {\n\tout := DictEmpty[string, string]()\n\tfor name, value := range claims {\n\t\tout = DictInsert(out, name, claimText(value), stringKeyLess)\n\t}\n\treturn out\n}\n\n// JwtVerify is `JWT.verify`: the claims of a token whose signature and expiry check out, or a\n// 401. On success the claims carry an `Authentic` fact, which erases \226\128\148 what it buys is that\n// \"trusted a cookie without verifying it\" stops compiling.\nfunc JwtVerify(token JwtToken, key Secret) Check[Dict[string, string]] {\n\tverified, rejection := verifyToken(token, key)\n\tif verified.raw == nil {\n\t\treturn rejection\n\t}\n\treturn Accept(claimsDict(verified.raw))\n}\n\n// JwtDecode is `JWT.decode`: the claims WITHOUT verifying anything. It exists for reading a\n// token you have not authenticated (an `iss` to decide which key to check it with, say), and\n// its result must never be trusted \226\128\148 which is why it mints no fact.\nfunc JwtDecode(token JwtToken) Dict[string, string] {\n\tparts := strings.Split(token.Value, \".\")\n\tif len(parts) != 3 {\n\t\tpanic(\"JWT.decode: malformed JWT: expected three dot-separated segments\")\n\t}\n\tpayload, ok := decodeBase64URL(parts[1])\n\tif !ok {\n\t\tpanic(\"JWT.decode: malformed JWT payload: not base64url\")\n\t}\n\tdecoded, err := ParseJSON(payload)\n\tif err != nil {\n\t\tpanic(\"JWT.decode: malformed JWT payload: \" + err.Error())\n\t}\n\tclaims, isObject := decoded.(map[string]any)\n\tif !isObject {\n\t\tpanic(\"JWT.decode: malformed JWT payload: the claims must be a JSON object\")\n\t}\n\treturn claimsDict(claims)\n}\n\n// JwtRenew is `JWT.renew`: it slides the session window forward, preserving every claim and the\n// ORIGINAL `iat`, so an active user is never logged out mid-task while an idle one still expires.\n//\n// It exists as a function because re-signing by hand is a trap: the verified claims contain\n// `exp` and `iat`, `JWT.sign` refuses both, and an author who rebuilds the dict to strip them\n// silently drops any claim they forget \226\128\148 downgrading the session on every renewal.\n//\n// It REFUSES when the token carries no usable `iat` (absent, not an exact non-negative integer,\n// or dated in the future beyond the skew allowance), or when the session has lived its absolute\n// maximum. Renewal is presented WITH the token, so a captured token can be renewed exactly as a\n// legitimate one can; the hard stop is what keeps \"a captured token is useful for a bounded\n// time\" true in a design with no server-side revocation.\nfunc JwtRenew(token JwtToken, key Secret) Check[JwtToken] {\n\tverified, rejection := verifyToken(token, key)\n\tif verified.raw == nil {\n\t\treturn Reject[JwtToken](rejection.Status(), rejection.Message())\n\t}\n\tnow := jwtNowSeconds()\n\tissuedAt, usable := jsonSeconds(verified.raw[\"iat\"])\n\tif !usable || issuedAt < 0 || issuedAt > now+jwtMaxClockSkewSeconds {\n\t\treturn Reject[JwtToken](401, \"Session cannot be renewed: no usable issued-at claim\")\n\t}\n\tif now-issuedAt > int64(sessionPolicyAbsoluteMaxSeconds()) {\n\t\treturn Reject[JwtToken](401, \"Session has reached its maximum lifetime\")\n\t}\n\t// Revocation at the renewal boundary, after the lifetime checks and before any new token is\n\t// minted: the same position and the same message `tesl/jwt.rkt` uses.\n\tif sessionRevoked(claimText(verified.raw[\"sub\"]), issuedAt) {\n\t\treturn Reject[JwtToken](401, \"Session cannot be renewed: session revoked\")\n\t}\n\t// Every claim travels across except the two this function owns.\n\tcarried := DictEmpty[string, string]()\n\tfor name, value := range verified.raw {\n\t\tif name == \"exp\" || name == \"iat\" {\n\t\t\tcontinue\n\t\t}\n\t\tcarried = DictInsert(carried, name, claimText(value), stringKeyLess)\n\t}\n\treturn Accept(signClaims(carried, key, issuedAt, now+int64(sessionPolicySeconds())))\n}\n\n// JwtTokenText is the token as it travels \226\128\148 what a cookie writer puts on the wire.\nfunc JwtTokenText(token JwtToken) string { return token.Value }\n");
  ("list.go", "package teslrt\n\nimport (\n\t\"slices\"\n\t\"strings\"\n)\n\n// Tesl's `List a` is a Go slice, which buys idiomatic, readable emitted code. A Tesl\n// list is immutable, and nothing in a Tesl program can mutate one, so aliasing is\n// only ever observable if a function in THIS FILE writes into a backing array some\n// other Tesl value can still see. That gives the one invariant this file must never\n// break:\n//\n//\tONLY WRITERS ALLOCATE. READERS MAY ALIAS.\n//\n// So Take/Drop/Tail return plain sub-slice views in O(1), while the writers \226\128\148\n// anything append-like, plus SortBy, which sorts in place \226\128\148 build a fresh array\n// first. The combination that would be a soundness bug is a zero-copy view PLUS a\n// capacity-reusing append: `append(xs[:2], v)` writes index 2, which a longer live\n// value still sees. Since both halves live here, forbidding capacity reuse in the\n// writers is sufficient, and copying in the readers would be redundant.\n//\n// Any list writer added later must honour the same rule.\n//\n// Views are BOUNDED, because a slice keeps its whole backing array alive: a\n// `List.take 1` of a 10,000-row query result would otherwise pin all 10,000 rows for\n// as long as that one-element value lives. See boundedView.\n//\n// Remaining consequence, accepted deliberately: this is an invariant of the runtime,\n// not of the emitted module code. A Go author who sheds Tesl and appends to a Take\n// result reintroduces the classic aliasing bug \226\128\148 out of scope by design, rather than\n// paid for with O(n) on every read.\n//\n// Functions needing equality or ordering take it as a parameter. A generic Go\n// function cannot compare a `T` \226\128\148 `teslrt.Int` is deliberately non-comparable \226\128\148 but\n// the EMITTER knows the concrete element type at every call site and passes the\n// comparison in.\nfunc ListLength[T any](xs []T) Int {\n\treturn FromInt64(int64(len(xs)))\n}\n\nfunc ListIsEmpty[T any](xs []T) bool {\n\treturn len(xs) == 0\n}\n\n// ListHead is Nothing for an empty list rather than a panic: Tesl's `List.head`\n// returns `Maybe a`.\nfunc ListHead[T any](xs []T) Maybe[T] {\n\tif len(xs) == 0 {\n\t\treturn Nothing[T]()\n\t}\n\treturn Something(xs[0])\n}\n\n// ListTail drops the first element, or Nothing when there is none. The result is a\n// (bounded) view: no writer can reach the shared array \226\128\148 see the invariant above.\nfunc ListTail[T any](xs []T) Maybe[[]T] {\n\tif len(xs) == 0 {\n\t\treturn Nothing[[]T]()\n\t}\n\treturn Something(boundedView(xs[1:], xs))\n}\n\nfunc ListLast[T any](xs []T) Maybe[T] {\n\tif len(xs) == 0 {\n\t\treturn Nothing[T]()\n\t}\n\treturn Something(xs[len(xs)-1])\n}\n\n// ListAppend is a WRITER, so it allocates: appending into either input's spare\n// capacity is exactly the mutation the invariant above forbids.\nfunc ListAppend[T any](left, right []T) []T {\n\tout := make([]T, 0, len(left)+len(right))\n\tout = append(out, left...)\n\tout = append(out, right...)\n\treturn out\n}\n\n// ListTake and ListDrop are READERS: they return bounded views, clamping the count to\n// the list length. A negative count is a programming error the Racket backend rejects\n// at runtime, so it panics here rather than silently behaving like zero.\nfunc ListTake[T any](count Int, xs []T) []T {\n\treturn boundedView(xs[:clampCount(\"List.take\", count, len(xs))], xs)\n}\n\nfunc ListDrop[T any](count Int, xs []T) []T {\n\treturn boundedView(xs[clampCount(\"List.drop\", count, len(xs)):], xs)\n}\n\n// viewSlack is the array size a view may pin outright. Below it the retention is\n// irrelevant and a copy would be pure overhead.\nconst viewSlack = 32\n\n// boundedView keeps a reader O(1) while capping how much array a small result can\n// pin: past the slack, a view may retain at most twice its own length, and otherwise\n// copies. The copy costs O(len(out)) \226\128\148 by construction less than half the memory it\n// releases \226\128\148 so this cannot turn a cheap read into an expensive one.\nfunc boundedView[T any](out, source []T) []T {\n\tif cap(source) > viewSlack && cap(source) > 2*len(out) {\n\t\treturn cloneExact(out)\n\t}\n\treturn out\n}\n\nfunc clampCount(who string, count Int, length int) int {\n\tif count.Sign() < 0 {\n\t\tpanic(who + \": count must be non-negative\")\n\t}\n\tvalue, ok := count.Int64()\n\tif !ok || value > int64(length) {\n\t\treturn length\n\t}\n\treturn int(value)\n}\n\nfunc ListReverse[T any](xs []T) []T {\n\tout := make([]T, len(xs))\n\tfor index, value := range xs {\n\t\tout[len(xs)-1-index] = value\n\t}\n\treturn out\n}\n\nfunc ListSum(xs []Int) Int {\n\ttotal := FromInt64(0)\n\tfor _, value := range xs {\n\t\ttotal = Add(total, value)\n\t}\n\treturn total\n}\n\n// ListProduct is the product of every element, and of NO element it is 1 \226\128\148 the identity, which\n// is what `(apply * '())` answers in tesl/list.rkt. Answering 0 for the empty list would make\n// `product (xs ++ ys)` stop agreeing with `product xs * product ys`.\nfunc ListProduct(xs []Int) Int {\n\ttotal := FromInt64(1)\n\tfor _, value := range xs {\n\t\ttotal = Mul(total, value)\n\t}\n\treturn total\n}\n\nfunc ListMemberBy[T any](needle T, xs []T, equal func(T, T) bool) bool {\n\tfor _, value := range xs {\n\t\tif equal(needle, value) {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// ListUniqueKeyed keeps the FIRST occurrence and preserves order, in ONE pass over a map \226\128\148 the\n// same complexity as Racket's hash-based `List.unique`.\n//\n// The emitter picks this whenever it can hand the element type a COMPARABLE key whose equality is\n// exactly the language's `==` on that type: the value itself for String and Bool, `Int.Key()` for\n// an unbounded integer, `FloatKey` for a Float (see the note there \226\128\148 neither the float nor its raw\n// bits would do), and the base's key through a newtype. Anything else \226\128\148 an ADT, a record, a\n// container, a `secret` whose comparison must stay constant-time \226\128\148 goes through `ListUniqueBy`,\n// which is a linear scan per element and therefore quadratic.\nfunc ListUniqueKeyed[T any, K comparable](xs []T, key func(T) K) []T {\n\tout := make([]T, 0, len(xs))\n\tseen := make(map[K]struct{}, len(xs))\n\tfor _, value := range xs {\n\t\tk := key(value)\n\t\tif _, already := seen[k]; already {\n\t\t\tcontinue\n\t\t}\n\t\tseen[k] = struct{}{}\n\t\tout = append(out, value)\n\t}\n\treturn out\n}\n\n// ListUniqueBy is the same answer for an element type with no comparable key. It is QUADRATIC \226\128\148\n// one linear scan per element \226\128\148 which is why the keyed form above exists and is preferred.\nfunc ListUniqueBy[T any](xs []T, equal func(T, T) bool) []T {\n\tout := make([]T, 0, len(xs))\n\tfor _, value := range xs {\n\t\tif !ListMemberBy(value, out, equal) {\n\t\t\tout = append(out, value)\n\t\t}\n\t}\n\treturn out\n}\n\n// ListSortBy is STABLE, matching Racket's `sort`, and sorts a copy so the input\n// value is untouched.\nfunc ListSortBy[T any](xs []T, less func(T, T) bool) []T {\n\tout := cloneExact(xs)\n\tslices.SortStableFunc(out, func(left, right T) int {\n\t\tswitch {\n\t\tcase less(left, right):\n\t\t\treturn -1\n\t\tcase less(right, left):\n\t\t\treturn 1\n\t\tdefault:\n\t\t\treturn 0\n\t\t}\n\t})\n\treturn out\n}\n\nfunc ListEqualBy[T any](left, right []T, equal func(T, T) bool) bool {\n\tif len(left) != len(right) {\n\t\treturn false\n\t}\n\tfor index := range left {\n\t\tif !equal(left[index], right[index]) {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n\n// cloneExact gives a writer a private array to work in.\nfunc cloneExact[T any](xs []T) []T {\n\tout := make([]T, len(xs))\n\tcopy(out, xs)\n\treturn out\n}\n\n// StringSplit matches Racket's `string-split` with #:trim? #f: separators are not\n// collapsed, leading and trailing empties are kept, and splitting \"\" yields [\"\"].\nfunc StringSplit(s, sep string) []string {\n\tif s == \"\" {\n\t\treturn []string{\"\"}\n\t}\n\treturn strings.Split(s, sep)\n}\n\nfunc StringJoin(parts []string, sep string) string {\n\treturn strings.Join(parts, sep)\n}\n\n// exactCount converts a proven-non-negative Int to a length. The frontend has already\n// discharged `IsNonNegative`, so a negative value here means the emitter let an unproven\n// call through; a count that does not fit cannot be allocated at all, and Racket would\n// exhaust memory attempting it, so both panic rather than silently truncating to a\n// wrong-length list.\nfunc exactCount(who string, count Int) int {\n\tif count.Sign() < 0 {\n\t\tpanic(who + \": count must be non-negative\")\n\t}\n\tvalue, ok := count.Int64()\n\tif !ok || value > int64(maxAllocElements) {\n\t\tpanic(who + \": count is too large to allocate\")\n\t}\n\treturn int(value)\n}\n\n// maxAllocElements bounds a single constructed list. Not a language limit \226\128\148 a\n// denial-of-service bound. exactCount checks it BEFORE any `make`, so a request-controlled\n// count is a recoverable panic (a sanitized 500 inside a handler) rather than an\n// uncatchable out-of-memory kill: 1<<26 Ints is 1 GiB, which the runtime can refuse\n// cleanly, whereas the previous 1<<31 was 32 GiB and died in the allocator.\nconst maxAllocElements = 1 << 26\n\n// ListRange is start INCLUSIVE to end EXCLUSIVE, matching `for/list ([i (in-range \226\128\166)])`\n// in tesl/list.rkt, and empty when start >= end.\nfunc ListRange(start, end Int) []Int {\n\tif Compare(start, end) >= 0 {\n\t\treturn []Int{}\n\t}\n\tspan := exactCount(\"List.range\", Sub(end, start))\n\tout := make([]Int, span)\n\tcurrent := start\n\tfor index := range out {\n\t\tout[index] = current\n\t\tcurrent = Add(current, FromInt64(1))\n\t}\n\treturn out\n}\n\n// ListRepeat holds n copies of one value. `n` carries an IsNonNegative proof, so the\n// check here is containment rather than the enforcement.\nfunc ListRepeat[T any](value T, n Int) []T {\n\tout := make([]T, exactCount(\"List.repeat\", n))\n\tfor index := range out {\n\t\tout[index] = value\n\t}\n\treturn out\n}\n\n// ListConcat flattens ONE level, like `List.concat`/`List.flatten`. It sizes the result\n// first, so a list of n lists costs one allocation rather than n appends.\nfunc ListConcat[T any](xss [][]T) []T {\n\ttotal := 0\n\tfor _, xs := range xss {\n\t\ttotal += len(xs)\n\t}\n\tout := make([]T, 0, total)\n\tfor _, xs := range xss {\n\t\tout = append(out, xs...)\n\t}\n\treturn out\n}\n\n// ListMaximum and ListMinimum are Nothing for the empty list. Ordering comes in from the\n// emitter, which knows the concrete element type at each call site.\nfunc ListMaximum[T any](xs []T, less func(T, T) bool) Maybe[T] {\n\tif len(xs) == 0 {\n\t\treturn Nothing[T]()\n\t}\n\tbest := xs[0]\n\tfor _, value := range xs[1:] {\n\t\tif less(best, value) {\n\t\t\tbest = value\n\t\t}\n\t}\n\treturn Something(best)\n}\n\nfunc ListMinimum[T any](xs []T, less func(T, T) bool) Maybe[T] {\n\tif len(xs) == 0 {\n\t\treturn Nothing[T]()\n\t}\n\tbest := xs[0]\n\tfor _, value := range xs[1:] {\n\t\tif less(value, best) {\n\t\t\tbest = value\n\t\t}\n\t}\n\treturn Something(best)\n}\n");
  ("loadtest.go", "package teslrt\n\nimport (\n\t\"math\"\n\t\"sort\"\n\t\"testing\"\n\t\"time\"\n)\n\n// The load-test harness: an OPEN-MODEL scheduler, so latency measures what a client would see.\n//\n// Every rule here is copied from `dsl/load-test.rkt` deliberately, because the point of having it\n// on both backends is that the two sets of numbers are comparable:\n//\n//\trequests are sent at a FIXED arrival rate regardless of how long the last one took, and\n//\tlatency is measured from the SCHEDULED send time \226\128\148 a closed model (send, wait, send) hides\n//\texactly the queueing a load test exists to find, which is coordinated omission;\n//\twarm-up runs until p99 is steady (CV < 5% across three consecutive 2-second windows) or 30\n//\tseconds pass, and warm-up requests are NOT measured \226\128\148 otherwise the first JIT/allocation\n//\tcosts land in the p99 the assertion reads;\n//\tpercentiles are taken from the sorted sample by index (floor(p*n)), which is the same\n//\testimator, so a p99 here and a p99 there mean the same thing;\n//\tthe report is the same six lines, so a diff of two runs is a diff of the numbers.\n//\n// One request at a time, from one goroutine: the Racket harness is single-threaded, and matching\n// that is what makes the comparison about the RUNTIME rather than about how each harness spreads\n// work over cores.\nconst (\n\twarmupWindow      = 2 * time.Second\n\twarmupCVThreshold = 0.05\n\twarmupConsecutive = 3\n\twarmupMax         = 30 * time.Second\n)\n\n// LoadTestResult is the sample a run produced, in milliseconds.\ntype LoadTestResult struct {\n\tLatencies  []float64\n\tErrors     int\n\tTotal      int\n\tDurationS  float64\n\tThroughput float64\n\tErrorRate  float64\n}\n\n// RunLoadTest drives `request` at `rate` requests per second for `duration` seconds and reports\n// the sample. `request` answers the response status (an error is reported as 0), so the harness\n// can count a 4xx/5xx as an error without knowing anything about the program.\nfunc RunLoadTest(rate int, durationSeconds int, request func() int) LoadTestResult {\n\tif rate < 1 {\n\t\trate = 1\n\t}\n\tinterval := time.Duration(float64(time.Second) / float64(rate))\n\tresult := LoadTestResult{}\n\n\t// One request, measured from the time it was SCHEDULED to be sent.\n\tsend := func(scheduled time.Time) float64 {\n\t\tstatus := request()\n\t\tlatency := float64(time.Since(scheduled).Nanoseconds()) / 1e6\n\t\tresult.Total++\n\t\tif status == 0 || status >= 400 {\n\t\t\tresult.Errors++\n\t\t}\n\t\treturn latency\n\t}\n\n\t// \226\148\128\226\148\128 Warm-up: not measured \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\twarmupStart := time.Now()\n\twindowStart := time.Now()\n\twindow := []float64{}\n\trecent := []float64{}\n\tscheduled := time.Now()\n\tfor time.Since(warmupStart) < warmupMax {\n\t\twindow = append(window, send(scheduled))\n\t\tif time.Since(windowStart) >= warmupWindow {\n\t\t\trecent = append(recent, percentileOf(window, 0.99))\n\t\t\tif len(recent) > warmupConsecutive {\n\t\t\t\trecent = recent[len(recent)-warmupConsecutive:]\n\t\t\t}\n\t\t\tif len(recent) == warmupConsecutive &&\n\t\t\t\tcoefficientOfVariation(recent) < warmupCVThreshold {\n\t\t\t\tbreak\n\t\t\t}\n\t\t\twindow = window[:0]\n\t\t\twindowStart = time.Now()\n\t\t}\n\t\tscheduled = scheduled.Add(interval)\n\t\tif wait := time.Until(scheduled); wait > 0 {\n\t\t\ttime.Sleep(wait)\n\t\t}\n\t}\n\n\t// \226\148\128\226\148\128 Measurement \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\tresult.Total = 0\n\tresult.Errors = 0\n\tmeasureStart := time.Now()\n\tmeasureEnd := measureStart.Add(time.Duration(durationSeconds) * time.Second)\n\tscheduled = time.Now()\n\tfor time.Now().Before(measureEnd) {\n\t\tresult.Latencies = append(result.Latencies, send(scheduled))\n\t\tscheduled = scheduled.Add(interval)\n\t\tif wait := time.Until(scheduled); wait > 0 {\n\t\t\ttime.Sleep(wait)\n\t\t}\n\t}\n\tresult.DurationS = time.Since(measureStart).Seconds()\n\tif result.DurationS > 0 {\n\t\tresult.Throughput = float64(len(result.Latencies)) / result.DurationS\n\t}\n\tif result.Total > 0 {\n\t\tresult.ErrorRate = float64(result.Errors) / float64(result.Total)\n\t}\n\treturn result\n}\n\n// percentileOf takes the value at floor(p*n) of the sorted sample \226\128\148 the same estimator the Racket\n// harness uses, so the two report the same number for the same sample.\nfunc percentileOf(latencies []float64, p float64) float64 {\n\tif len(latencies) == 0 {\n\t\treturn math.Inf(1)\n\t}\n\tsorted := make([]float64, len(latencies))\n\tcopy(sorted, latencies)\n\tsort.Float64s(sorted)\n\tindex := int(math.Floor(p * float64(len(sorted))))\n\tif index >= len(sorted) {\n\t\tindex = len(sorted) - 1\n\t}\n\treturn sorted[index]\n}\n\nfunc coefficientOfVariation(values []float64) float64 {\n\tif len(values) < 2 {\n\t\treturn 1.0\n\t}\n\tsum := 0.0\n\tfor _, value := range values {\n\t\tsum += value\n\t}\n\tmean := sum / float64(len(values))\n\tif mean <= 0 {\n\t\treturn 1.0\n\t}\n\tvariance := 0.0\n\tfor _, value := range values {\n\t\tvariance += (value - mean) * (value - mean)\n\t}\n\tvariance /= float64(len(values) - 1)\n\treturn math.Sqrt(variance) / mean\n}\n\n// LoadTestMetric answers one of the metrics an `assert` names.\nfunc (result LoadTestResult) LoadTestMetric(name string) float64 {\n\tswitch name {\n\tcase \"p50\":\n\t\treturn percentileOf(result.Latencies, 0.50)\n\tcase \"p95\":\n\t\treturn percentileOf(result.Latencies, 0.95)\n\tcase \"p99\":\n\t\treturn percentileOf(result.Latencies, 0.99)\n\tcase \"p99.9\":\n\t\treturn percentileOf(result.Latencies, 0.999)\n\tcase \"errorRate\":\n\t\treturn result.ErrorRate\n\tcase \"throughput\":\n\t\treturn result.Throughput\n\tdefault:\n\t\tpanic(\"load-test: unknown metric \" + name)\n\t}\n}\n\n// ReportLoadTest prints the same six lines the Racket harness prints, so two runs diff cleanly.\n// It goes to the test log rather than stdout because a load test IS a test here.\nfunc ReportLoadTest(teslT *testing.T, result LoadTestResult) {\n\tteslT.Helper()\n\tteslT.Logf(\"  Load test results (%d requests in %.1fs):\", len(result.Latencies),\n\t\tresult.DurationS)\n\tteslT.Logf(\"    p50:  %.1fms  p95: %.1fms  p99: %.1fms  p99.9: %.1fms\",\n\t\tresult.LoadTestMetric(\"p50\"), result.LoadTestMetric(\"p95\"),\n\t\tresult.LoadTestMetric(\"p99\"), result.LoadTestMetric(\"p99.9\"))\n\tminimum, maximum := math.Inf(1), 0.0\n\tfor _, latency := range result.Latencies {\n\t\tminimum = math.Min(minimum, latency)\n\t\tmaximum = math.Max(maximum, latency)\n\t}\n\tif len(result.Latencies) == 0 {\n\t\tminimum = 0\n\t}\n\tteslT.Logf(\"    min: %.1fms  max: %.1fms  throughput: %.1frps  errors: %.2f%%\",\n\t\tminimum, maximum, result.Throughput, result.ErrorRate*100)\n\tteslT.Logf(\"    (measurements include in-process harness overhead)\")\n}\n\n// AssertLoadTest fails the test when a metric misses its threshold, naming the actual value \226\128\148\n// which is the whole content of a load-test failure.\nfunc AssertLoadTest(teslT *testing.T, result LoadTestResult, metric, operator string,\n\tthreshold float64) {\n\tteslT.Helper()\n\tactual := result.LoadTestMetric(metric)\n\tpassed := false\n\tswitch operator {\n\tcase \"<\":\n\t\tpassed = actual < threshold\n\tcase \"<=\":\n\t\tpassed = actual <= threshold\n\tcase \">\":\n\t\tpassed = actual > threshold\n\tcase \">=\":\n\t\tpassed = actual >= threshold\n\tdefault:\n\t\tpanic(\"load-test: unknown comparison \" + operator)\n\t}\n\tif !passed {\n\t\tteslT.Fatalf(\"load-test: assertion failed: %s %s %g (actual: %.2f)\",\n\t\t\tmetric, operator, threshold, actual)\n\t}\n}\n\n// NoteLoadTestBaseline records that a `baseline` clause was declared, WITHOUT comparing against\n// one.\n//\n// Neither backend stores baselines: `dsl/load-test.rkt` prints\n// \"in-process baselines; store/compare deferred\" and moves on, and this says the same thing in the\n// same place. The note exists because the alternative \226\128\148 accepting the clause silently \226\128\148 would read\n// as a regression check that ran, and refusing it would make a load test that runs on Racket fail\n// to compile here.\n//\n// Implementing real baselines is a language feature owed to BOTH backends (a stored format, a\n// location, and a decision about what CI does with a regression), not a migration item.\nfunc NoteLoadTestBaseline(teslT *testing.T, name string) {\n\tteslT.Helper()\n\tteslT.Logf(\"    (baseline %q \226\128\148 in-process baselines; store/compare deferred)\", name)\n}\n\n// NoteLoadTestRegression is the same for a regression ASSERTION, which needs the baseline the line\n// above does not store. It does not fail the test: a check that cannot run has not failed.\nfunc NoteLoadTestRegression(teslT *testing.T, metric string, ratio float64) {\n\tteslT.Helper()\n\tteslT.Logf(\"    (baseline regression check for %s with ratio %g \226\128\148 baseline comparison not yet stored)\",\n\t\tmetric, ratio)\n}\n\n// LoadTestStatus is what a request thunk answers: the status an api-test response carries, or 0\n// when the request trapped. A trap is an error rather than a crash, because a load test that\n// dies on the first 500 measures nothing.\nfunc LoadTestStatus(response ApiResponse) int {\n\tstatus, exact := response.Status.Int64()\n\tif !exact {\n\t\treturn 0\n\t}\n\treturn int(status)\n}\n");
  ("maybe.go", "package teslrt\n\n// Maybe is Tesl's `Maybe a`. It lives in the runtime rather than being emitted per\n// module because a `Maybe` crosses module boundaries: two emitted packages that\n// each declared their own would produce incompatible Go types.\n//\n// The representation is the same flat tag+payload struct the emitter generates for\n// a user ADT, and Tag is exported for exactly that reason \226\128\148 an emitted package in\n// another module has to read it. The zero value is Nothing, matching Go's\n// zero-value convention as well as the tag order below.\ntype Maybe[A any] struct {\n\tTag            MaybeTag\n\tSomethingValue A\n}\n\n// MaybeTag identifies which variant a Maybe holds. The constants are an enum-like\n// set so the `exhaustive` linter can verify a switch over them.\ntype MaybeTag int\n\nconst (\n\tMaybeNothing MaybeTag = iota\n\tMaybeSomething\n)\n\n// Nothing is the empty Maybe. Emitted code writes the composite literal directly;\n// this exists for hand-written runtime code and for readable tests.\nfunc Nothing[A any]() Maybe[A] {\n\treturn Maybe[A]{Tag: MaybeNothing}\n}\n\n// Something wraps a present value.\nfunc Something[A any](value A) Maybe[A] {\n\treturn Maybe[A]{Tag: MaybeSomething, SomethingValue: value}\n}\n\n// IsSomething reports whether a value is present.\nfunc (m Maybe[A]) IsSomething() bool {\n\treturn m.Tag == MaybeSomething\n}\n\n// Value returns the wrapped value and whether it was present. The payload of a\n// Nothing is the zero value of A and must not be read as data; this signature\n// makes that impossible to do by accident.\nfunc (m Maybe[A]) Value() (A, bool) {\n\tif m.Tag != MaybeSomething {\n\t\tvar zero A\n\t\treturn zero, false\n\t}\n\treturn m.SomethingValue, true\n}\n");
  ("money.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"math/big\"\n\t\"strconv\"\n\t\"strings\"\n)\n\n// `Tesl.Money` \226\128\148 money as EXACT MINOR UNITS plus a currency, never as a float.\n//\n// The whole point of the type is that an amount cannot drift: cents are integers, arithmetic\n// on them is exact, and the only operations that round say so in their name. Where a rounding\n// does happen \226\128\148 a fractional scale, a currency conversion, a rate materialising into an amount\n// \226\128\148 it is ROUND HALF EVEN on an exact rational, which is what `tesl/money.rkt` does, so the\n// same program lands on the same cent on both backends.\n//\n// Two rules that look small and are not:\n//\n//   - a float factor is exactified DECIMAL-FAITHFULLY (0.9155 becomes 1831/2000, not the\n//     binary-float 0.91549999\226\128\166). Without it, 1000 \195\151 0.9155 = 915.4999\226\128\166 quietly rounds DOWN and\n//     the half-even contract is dodged;\n//   - `minorDigits` is per currency and load-bearing: it drives display AND the digit shift\n//     when converting between currencies with different scales (JPY has 0, USD has 2, BHD 3).\n\ntype Currency struct {\n\tCode        string\n\tMinorDigits int\n}\n\ntype Money struct {\n\tMinorUnits Int\n\tCurrency   Currency\n}\n\n// ExchangeRate carries PROVENANCE (`AsOf`) beside the rate, because a rate without a time is\n// not a fact about anything. The rate itself is stored as an exact rational: conversion math\n// never touches a float.\ntype ExchangeRate struct {\n\tFrom Currency\n\tTo   Currency\n\tRate *big.Rat\n\tAsOf PosixMillis\n}\n\n// MoneyRate is money PER quantity \226\128\148 an hourly rate, a price per kilogram. The algebra runs on\n// `PerCanonical` (minor units per SI-canonical denominator unit: per second, per kilogram);\n// the label pair is presentation, and the boundary unit a rate quantizes to.\ntype MoneyRate struct {\n\tPerCanonical *big.Rat\n\tCurrency     Currency\n\tLabelFactor  *big.Rat\n\tLabel        string\n}\n\n// MoneyOf is what a `Money.usd 1000` constructor becomes. The code and the digit count are\n// baked in by the emitter from the same ISO table the Racket constructors come from, and they\n// come LAST so the emitted call reads argument-then-constants.\nfunc MoneyOf(minorUnits Int, code string, minorDigits int) Money {\n\treturn Money{MinorUnits: minorUnits, Currency: Currency{Code: code, MinorDigits: minorDigits}}\n}\n\n// CurrencyOf is a `Usd` / `Sek` constructor: the currency itself, with no amount.\nfunc CurrencyOf(code string, minorDigits int) Currency {\n\treturn Currency{Code: code, MinorDigits: minorDigits}\n}\n\nfunc MoneyMinorUnits(money Money) Int    { return money.MinorUnits }\nfunc MoneyCurrency(money Money) Currency { return money.Currency }\n\nfunc CurrencyCode(currency Currency) string     { return currency.Code }\nfunc CurrencyMinorDigits(currency Currency) Int { return FromInt64(int64(currency.MinorDigits)) }\n\n// CurrencyFromCode resolves an ISO 4217 code at run time \226\128\148 the one place a currency is chosen\n// rather than written. An unknown code is Nothing, not a trap: the string usually came from\n// outside the program.\nfunc CurrencyFromCode(code string) Maybe[Currency] {\n\tif currency, found := currencyTable[code]; found {\n\t\treturn Something(currency)\n\t}\n\treturn Nothing[Currency]()\n}\n\n// MoneyFromMinorUnits builds an amount in a currency chosen at run time.\nfunc MoneyFromMinorUnits(currency Currency, minorUnits Int) Money {\n\treturn Money{MinorUnits: minorUnits, Currency: currency}\n}\n\n// \226\148\128\226\148\128 Arithmetic \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// MoneyScale multiplies by an exact integer \226\128\148 quantity \195\151 unit price stays exact, so it never\n// rounds and needs no rounding rule.\nfunc MoneyScale(money Money, factor Int) Money {\n\treturn Money{MinorUnits: Mul(money.MinorUnits, factor), Currency: money.Currency}\n}\n\n// MoneyScaleBy multiplies by a FRACTIONAL factor (interest, VAT, a discount): the factor is\n// exactified decimal-faithfully, the multiplication runs exact, and the result rounds half-even\n// back to whole minor units. It is deliberately not `*`: fractional money scaling rounds, so it\n// has to be a named, visible operation.\nfunc MoneyScaleBy(money Money, factor float64) Money {\n\tscaled := new(big.Rat).Mul(ratOfInt(money.MinorUnits), ratOfFloat(\"Money.scaleBy\", factor))\n\treturn Money{MinorUnits: fromBig(roundHalfEven(scaled)), Currency: money.Currency}\n}\n\nfunc MoneyNegate(money Money) Money {\n\treturn Money{MinorUnits: Sub(FromInt64(0), money.MinorUnits), Currency: money.Currency}\n}\n\nfunc MoneyAbs(money Money) Money {\n\tif Compare(money.MinorUnits, FromInt64(0)) < 0 {\n\t\treturn MoneyNegate(money)\n\t}\n\treturn money\n}\n\nfunc MoneyIsZero(money Money) bool { return Compare(money.MinorUnits, FromInt64(0)) == 0 }\n\nfunc MoneyIsNegative(money Money) bool { return Compare(money.MinorUnits, FromInt64(0)) < 0 }\n\n// MoneyAdd and MoneySubtract are SAME-CURRENCY operations. A mismatch traps rather than\n// picking a side: the checker's `SameCurrency` proof is what makes them total, so reaching\n// here with two currencies means that proof was bypassed.\nfunc MoneyAdd(left, right Money) Money {\n\trequireSameCurrency(\"Money.add\", left, right)\n\treturn Money{MinorUnits: Add(left.MinorUnits, right.MinorUnits), Currency: left.Currency}\n}\n\nfunc MoneySubtract(left, right Money) Money {\n\trequireSameCurrency(\"Money.subtract\", left, right)\n\treturn Money{MinorUnits: Sub(left.MinorUnits, right.MinorUnits), Currency: left.Currency}\n}\n\n// MoneyCompare answers -1 / 0 / 1 on minor units, which are comparable because the currency\n// is the same.\nfunc MoneyCompare(left, right Money) Int {\n\trequireSameCurrency(\"Money.compare\", left, right)\n\treturn FromInt64(int64(Compare(left.MinorUnits, right.MinorUnits)))\n}\n\nfunc requireSameCurrency(who string, left, right Money) {\n\tif left.Currency.Code != right.Currency.Code {\n\t\tpanic(fmt.Sprintf(\"%s: expected amounts in the same currency, got %s vs %s\",\n\t\t\twho, left.Currency.Code, right.Currency.Code))\n\t}\n}\n\n// \226\148\128\226\148\128 Display \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// symbolPrefix is the handful of currencies conventionally written symbol-first; everything\n// else renders amount-then-code (\"10.50 SEK\").\nvar symbolPrefix = map[string]string{\"USD\": \"$\", \"EUR\": \"\226\130\172\", \"GBP\": \"\194\163\", \"JPY\": \"\194\165\"}\n\n// MoneyDisplay renders an amount the way `tesl-money-display` does, digits driven by the\n// currency: USD 1000 \226\134\146 \"$10.00\", JPY 1000 \226\134\146 \"\194\1651000\", SEK 1050 \226\134\146 \"10.50 SEK\", and a negative\n// amount keeps its sign in front of the symbol.\nfunc MoneyDisplay(money Money) string {\n\tmagnitude := MoneyAbs(money).MinorUnits\n\tamount := magnitude.String()\n\tif money.Currency.MinorDigits > 0 {\n\t\tdivisor := new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(money.Currency.MinorDigits)), nil)\n\t\tmajor, minor := new(big.Int).QuoRem(magnitude.bigInt(), divisor, new(big.Int))\n\t\tminorText := minor.String()\n\t\tpadding := money.Currency.MinorDigits - len(minorText)\n\t\tamount = major.String() + \".\" + strings.Repeat(\"0\", padding) + minorText\n\t}\n\tsign := \"\"\n\tif MoneyIsNegative(money) {\n\t\tsign = \"-\"\n\t}\n\tif prefix, found := symbolPrefix[money.Currency.Code]; found {\n\t\treturn sign + prefix + amount\n\t}\n\treturn sign + amount + \" \" + money.Currency.Code\n}\n\n// \226\148\128\226\148\128 Exchange rates and conversion \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nfunc ExchangeRateMake(from, to Currency, rate float64, asOf PosixMillis) ExchangeRate {\n\treturn ExchangeRate{From: from, To: to, Rate: ratOfFloat(\"ExchangeRate.make\", rate), AsOf: asOf}\n}\n\nfunc ExchangeRateFromCurrency(rate ExchangeRate) Currency { return rate.From }\nfunc ExchangeRateToCurrency(rate ExchangeRate) Currency   { return rate.To }\nfunc ExchangeRateAsOf(rate ExchangeRate) PosixMillis      { return rate.AsOf }\n\n// ExchangeRateRate answers the rate as a Float \226\128\148 a lossy view of an exact value, which is why\n// the conversion math never goes through it.\nfunc ExchangeRateRate(rate ExchangeRate) float64 {\n\tvalue, _ := rate.Rate.Float64()\n\treturn value\n}\n\n// convertedMinorUnits is\n//\n//\tminor_dst = round-half-even(minor_src \195\151 rate \195\151 10^(digits_dst \226\136\146 digits_src))\n//\n// on exact rationals throughout. The digit shift rescales between minor-unit magnitudes, so\n// converting JPY (0 digits) into USD (2 digits) multiplies by 100 rather than losing the cents.\nfunc convertedMinorUnits(rate ExchangeRate, money Money) Int {\n\tshift := new(big.Rat).SetInt(new(big.Int).Exp(big.NewInt(10),\n\t\tbig.NewInt(int64(abs(rate.To.MinorDigits-rate.From.MinorDigits))), nil))\n\tif rate.To.MinorDigits < rate.From.MinorDigits {\n\t\tshift = new(big.Rat).Inv(shift)\n\t}\n\tproduct := new(big.Rat).Mul(ratOfInt(money.MinorUnits), rate.Rate)\n\tproduct = product.Mul(product, shift)\n\treturn fromBig(roundHalfEven(product))\n}\n\nfunc abs(value int) int {\n\tif value < 0 {\n\t\treturn -value\n\t}\n\treturn value\n}\n\n// MoneyConvert is the UNPROVEN path: a rate whose FROM currency is not the amount's is an Err\n// the caller has to handle, not a trap.\nfunc MoneyConvert(rate ExchangeRate, money Money) Result[Money, string] {\n\tif rate.From.Code != money.Currency.Code {\n\t\treturn MakeErr[Money, string](fmt.Sprintf(\"exchange rate is FROM %s but amount is in %s\",\n\t\t\trate.From.Code, money.Currency.Code))\n\t}\n\treturn MakeOk[Money, string](Money{MinorUnits: convertedMinorUnits(rate, money), Currency: rate.To})\n}\n\n// MoneyConvertChecked is the proof-gated path: `RateFor r m` guarantees the currencies match,\n// so this is total given the proof. A mismatch here means the proof layer was bypassed, and it\n// fails loudly rather than converting at a rate that does not apply.\nfunc MoneyConvertChecked(rate ExchangeRate, money Money) Money {\n\tif rate.From.Code != money.Currency.Code {\n\t\tpanic(fmt.Sprintf(\"Money.convertChecked: exchange rate is FROM %s but amount is in %s\"+\n\t\t\t\" \226\128\148 this needs a RateFor proof (use `check Money.requireRateFor(r, m)` first)\",\n\t\t\trate.From.Code, money.Currency.Code))\n\t}\n\treturn Money{MinorUnits: convertedMinorUnits(rate, money), Currency: rate.To}\n}\n\n// \226\148\128\226\148\128 The checks that mint the proofs \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// Each answers the value the proof is about, so the caller binds it and carries the proof; the\n// proof itself erases here, and what survives is the validation and its 400.\n\nfunc MoneyRequireNonNegative(money Money) Check[Money] {\n\tif MoneyIsNegative(money) {\n\t\treturn Reject[Money](400, \"amount must be non-negative\")\n\t}\n\treturn Accept(money)\n}\n\nfunc MoneyRequireSameCurrency(left, right Money) Check[Money] {\n\tif left.Currency.Code != right.Currency.Code {\n\t\treturn Reject[Money](400, fmt.Sprintf(\n\t\t\t\"expected amounts in the same currency, got %s vs %s\",\n\t\t\tleft.Currency.Code, right.Currency.Code))\n\t}\n\treturn Accept(right)\n}\n\nfunc MoneyRequireRateFor(rate ExchangeRate, money Money) Check[Money] {\n\tif rate.From.Code != money.Currency.Code {\n\t\treturn Reject[Money](400, fmt.Sprintf(\n\t\t\t\"exchange rate is FROM %s but amount is in %s\",\n\t\t\trate.From.Code, money.Currency.Code))\n\t}\n\treturn Accept(money)\n}\n\n// \226\148\128\226\148\128 Money per quantity \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// MoneyRateOf is a fixed-denominator constructor (`MoneyRate.perHour`): the amount IS the price\n// per label unit, so per-canonical is that amount divided by the canonical units in one label\n// unit \226\128\148 3600 for an hour, 1/1000 for a litre.\nfunc MoneyRateOf(money Money, canonicalPerLabel *big.Rat, label string) MoneyRate {\n\treturn MoneyRate{\n\t\tPerCanonical: new(big.Rat).Quo(ratOfInt(money.MinorUnits), canonicalPerLabel),\n\t\tCurrency:     money.Currency,\n\t\tLabelFactor:  canonicalPerLabel,\n\t\tLabel:        label,\n\t}\n}\n\n// MoneyRateOfLabel and MoneyRateDivLabel are the shapes EMITTED code calls: the label factor\n// arrives as a fraction of plain integers, so an emitted module needs no big-number import of\n// its own for what is a compile-time constant.\nfunc MoneyRateOfLabel(money Money, labelNum, labelDen int64, label string) MoneyRate {\n\treturn MoneyRateOf(money, big.NewRat(labelNum, labelDen), label)\n}\n\nfunc MoneyRateDivLabel(money Money, quantity float64, labelNum, labelDen int64,\n\tlabel string) MoneyRate {\n\treturn MoneyRateDiv(money, quantity, big.NewRat(labelNum, labelDen), label)\n}\n\n// MoneyRateDiv is `money / quantity`. The label pair comes from the checker's type, so a rate\n// displays and quantizes per HOUR rather than per second \226\128\148 a realistic hourly rate would\n// otherwise quantize to zero at a boundary.\nfunc MoneyRateDiv(money Money, quantity float64, canonicalPerLabel *big.Rat, label string) MoneyRate {\n\tif quantity == 0 {\n\t\tpanic(\"MoneyRate: division by a zero quantity\")\n\t}\n\treturn MoneyRate{\n\t\tPerCanonical: new(big.Rat).Quo(ratOfInt(money.MinorUnits),\n\t\t\tratOfFloat(\"MoneyRate\", quantity)),\n\t\tCurrency:    money.Currency,\n\t\tLabelFactor: canonicalPerLabel,\n\t\tLabel:       label,\n\t}\n}\n\n// MoneyRateMul is `rate \195\151 quantity` \226\128\148 the ONE place a rate becomes an amount, and so the one\n// half-even rounding in the algebra.\nfunc MoneyRateMul(rate MoneyRate, quantity float64) Money {\n\tproduct := new(big.Rat).Mul(rate.PerCanonical, ratOfFloat(\"MoneyRate\", quantity))\n\treturn Money{MinorUnits: fromBig(roundHalfEven(product)), Currency: rate.Currency}\n}\n\n// MoneyRateScale rescales a rate by a scalar, exactly: nothing rounds until an amount\n// materialises.\nfunc MoneyRateScale(rate MoneyRate, factor float64) MoneyRate {\n\treturn MoneyRate{\n\t\tPerCanonical: new(big.Rat).Mul(rate.PerCanonical, ratOfFloat(\"MoneyRate\", factor)),\n\t\tCurrency:     rate.Currency,\n\t\tLabelFactor:  rate.LabelFactor,\n\t\tLabel:        rate.Label,\n\t}\n}\n\nfunc MoneyRateCurrency(rate MoneyRate) Currency { return rate.Currency }\n\n// MoneyRateDisplay renders the rate's amount per DISPLAY unit \226\128\148 \"950.00 SEK/h\", \"$0.25/kg\".\n// The rounding is for rendering only; the stored rate stays exact.\nfunc MoneyRateDisplay(rate MoneyRate) string {\n\tperLabel := new(big.Rat).Mul(rate.PerCanonical, rate.LabelFactor)\n\tamount := Money{MinorUnits: fromBig(roundHalfEven(perLabel)), Currency: rate.Currency}\n\treturn MoneyDisplay(amount) + \"/\" + rate.Label\n}\n\n// \226\148\128\226\148\128 Exact-rational helpers \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nfunc ratOfInt(value Int) *big.Rat {\n\treturn new(big.Rat).SetInt(value.bigInt())\n}\n\n// ratOfFloat exactifies a float DECIMAL-FAITHFULLY: the shortest round-trip decimal of a\n// float64 is exactly the decimal the author wrote, so 0.9155 becomes 1831/2000 rather than the\n// binary-float value just under it. Racket reaches for the same trick\n// (`number->string` + `decimal-as-exact`), and for the same reason: without it a rate of\n// 0.9155 applied to 1000 lands on 915.4999\226\128\166 and rounds DOWN, dodging the half-even contract.\nfunc ratOfFloat(who string, value float64) *big.Rat {\n\ttext := strconv.FormatFloat(value, 'g', -1, 64)\n\trat, ok := new(big.Rat).SetString(text)\n\tif !ok {\n\t\tpanic(who + \": factor must be a finite number, got \" + text)\n\t}\n\treturn rat\n}\n\n// roundHalfEven rounds an exact rational to an integer, breaking a tie toward the EVEN\n// neighbour \226\128\148 the rule Racket's `round` follows on exact rationals, and the one that does not\n// bias a long series of roundings upward.\nfunc roundHalfEven(value *big.Rat) *big.Int {\n\tquotient, remainder := new(big.Int).QuoRem(value.Num(), value.Denom(), new(big.Int))\n\tif remainder.Sign() == 0 {\n\t\treturn quotient\n\t}\n\t// Compare |remainder| with half the denominator, without leaving the integers.\n\ttwiceRemainder := new(big.Int).Abs(remainder)\n\ttwiceRemainder.Lsh(twiceRemainder, 1)\n\tcomparison := twiceRemainder.Cmp(value.Denom())\n\troundAway := comparison > 0\n\tif comparison == 0 {\n\t\t// A tie goes to the even neighbour: away from zero only when truncation left an odd\n\t\t// quotient.\n\t\troundAway = quotient.Bit(0) == 1\n\t}\n\tif !roundAway {\n\t\treturn quotient\n\t}\n\tif value.Sign() < 0 {\n\t\treturn quotient.Sub(quotient, big.NewInt(1))\n\t}\n\treturn quotient.Add(quotient, big.NewInt(1))\n}\n");
  ("currency_data.go", "package teslrt\n\n// Generated by scripts/gen-currencies.py from the ISO 4217 active list.\n// DO NOT EDIT BY HAND \226\128\148 regenerate and commit when ISO 4217 changes.\n// 155 currencies. minorDigits is load-bearing (rounding and\n// Money.display): USD=2, JPY=0, BHD=3.\n//\n// A `Money.usd 1000` constructor needs no table \226\128\148 the emitter bakes the code and the\n// digits into the call. What needs one is `Currency.fromCode`, the single place a\n// currency is chosen at RUN time.\nvar currencyTable = map[string]Currency{\n\t\"AED\": {Code: \"AED\", MinorDigits: 2},\n\t\"AFN\": {Code: \"AFN\", MinorDigits: 2},\n\t\"ALL\": {Code: \"ALL\", MinorDigits: 2},\n\t\"AMD\": {Code: \"AMD\", MinorDigits: 2},\n\t\"ANG\": {Code: \"ANG\", MinorDigits: 2},\n\t\"AOA\": {Code: \"AOA\", MinorDigits: 2},\n\t\"ARS\": {Code: \"ARS\", MinorDigits: 2},\n\t\"AUD\": {Code: \"AUD\", MinorDigits: 2},\n\t\"AWG\": {Code: \"AWG\", MinorDigits: 2},\n\t\"AZN\": {Code: \"AZN\", MinorDigits: 2},\n\t\"BAM\": {Code: \"BAM\", MinorDigits: 2},\n\t\"BBD\": {Code: \"BBD\", MinorDigits: 2},\n\t\"BDT\": {Code: \"BDT\", MinorDigits: 2},\n\t\"BGN\": {Code: \"BGN\", MinorDigits: 2},\n\t\"BHD\": {Code: \"BHD\", MinorDigits: 3},\n\t\"BIF\": {Code: \"BIF\", MinorDigits: 0},\n\t\"BMD\": {Code: \"BMD\", MinorDigits: 2},\n\t\"BND\": {Code: \"BND\", MinorDigits: 2},\n\t\"BOB\": {Code: \"BOB\", MinorDigits: 2},\n\t\"BRL\": {Code: \"BRL\", MinorDigits: 2},\n\t\"BSD\": {Code: \"BSD\", MinorDigits: 2},\n\t\"BTN\": {Code: \"BTN\", MinorDigits: 2},\n\t\"BWP\": {Code: \"BWP\", MinorDigits: 2},\n\t\"BYN\": {Code: \"BYN\", MinorDigits: 2},\n\t\"BZD\": {Code: \"BZD\", MinorDigits: 2},\n\t\"CAD\": {Code: \"CAD\", MinorDigits: 2},\n\t\"CDF\": {Code: \"CDF\", MinorDigits: 2},\n\t\"CHF\": {Code: \"CHF\", MinorDigits: 2},\n\t\"CLP\": {Code: \"CLP\", MinorDigits: 0},\n\t\"CNY\": {Code: \"CNY\", MinorDigits: 2},\n\t\"COP\": {Code: \"COP\", MinorDigits: 2},\n\t\"CRC\": {Code: \"CRC\", MinorDigits: 2},\n\t\"CUP\": {Code: \"CUP\", MinorDigits: 2},\n\t\"CVE\": {Code: \"CVE\", MinorDigits: 2},\n\t\"CZK\": {Code: \"CZK\", MinorDigits: 2},\n\t\"DJF\": {Code: \"DJF\", MinorDigits: 0},\n\t\"DKK\": {Code: \"DKK\", MinorDigits: 2},\n\t\"DOP\": {Code: \"DOP\", MinorDigits: 2},\n\t\"DZD\": {Code: \"DZD\", MinorDigits: 2},\n\t\"EGP\": {Code: \"EGP\", MinorDigits: 2},\n\t\"ERN\": {Code: \"ERN\", MinorDigits: 2},\n\t\"ETB\": {Code: \"ETB\", MinorDigits: 2},\n\t\"EUR\": {Code: \"EUR\", MinorDigits: 2},\n\t\"FJD\": {Code: \"FJD\", MinorDigits: 2},\n\t\"FKP\": {Code: \"FKP\", MinorDigits: 2},\n\t\"GBP\": {Code: \"GBP\", MinorDigits: 2},\n\t\"GEL\": {Code: \"GEL\", MinorDigits: 2},\n\t\"GHS\": {Code: \"GHS\", MinorDigits: 2},\n\t\"GIP\": {Code: \"GIP\", MinorDigits: 2},\n\t\"GMD\": {Code: \"GMD\", MinorDigits: 2},\n\t\"GNF\": {Code: \"GNF\", MinorDigits: 0},\n\t\"GTQ\": {Code: \"GTQ\", MinorDigits: 2},\n\t\"GYD\": {Code: \"GYD\", MinorDigits: 2},\n\t\"HKD\": {Code: \"HKD\", MinorDigits: 2},\n\t\"HNL\": {Code: \"HNL\", MinorDigits: 2},\n\t\"HTG\": {Code: \"HTG\", MinorDigits: 2},\n\t\"HUF\": {Code: \"HUF\", MinorDigits: 2},\n\t\"IDR\": {Code: \"IDR\", MinorDigits: 2},\n\t\"ILS\": {Code: \"ILS\", MinorDigits: 2},\n\t\"INR\": {Code: \"INR\", MinorDigits: 2},\n\t\"IQD\": {Code: \"IQD\", MinorDigits: 3},\n\t\"IRR\": {Code: \"IRR\", MinorDigits: 2},\n\t\"ISK\": {Code: \"ISK\", MinorDigits: 0},\n\t\"JMD\": {Code: \"JMD\", MinorDigits: 2},\n\t\"JOD\": {Code: \"JOD\", MinorDigits: 3},\n\t\"JPY\": {Code: \"JPY\", MinorDigits: 0},\n\t\"KES\": {Code: \"KES\", MinorDigits: 2},\n\t\"KGS\": {Code: \"KGS\", MinorDigits: 2},\n\t\"KHR\": {Code: \"KHR\", MinorDigits: 2},\n\t\"KMF\": {Code: \"KMF\", MinorDigits: 0},\n\t\"KPW\": {Code: \"KPW\", MinorDigits: 2},\n\t\"KRW\": {Code: \"KRW\", MinorDigits: 0},\n\t\"KWD\": {Code: \"KWD\", MinorDigits: 3},\n\t\"KYD\": {Code: \"KYD\", MinorDigits: 2},\n\t\"KZT\": {Code: \"KZT\", MinorDigits: 2},\n\t\"LAK\": {Code: \"LAK\", MinorDigits: 2},\n\t\"LBP\": {Code: \"LBP\", MinorDigits: 2},\n\t\"LKR\": {Code: \"LKR\", MinorDigits: 2},\n\t\"LRD\": {Code: \"LRD\", MinorDigits: 2},\n\t\"LSL\": {Code: \"LSL\", MinorDigits: 2},\n\t\"LYD\": {Code: \"LYD\", MinorDigits: 3},\n\t\"MAD\": {Code: \"MAD\", MinorDigits: 2},\n\t\"MDL\": {Code: \"MDL\", MinorDigits: 2},\n\t\"MGA\": {Code: \"MGA\", MinorDigits: 2},\n\t\"MKD\": {Code: \"MKD\", MinorDigits: 2},\n\t\"MMK\": {Code: \"MMK\", MinorDigits: 2},\n\t\"MNT\": {Code: \"MNT\", MinorDigits: 2},\n\t\"MOP\": {Code: \"MOP\", MinorDigits: 2},\n\t\"MRU\": {Code: \"MRU\", MinorDigits: 2},\n\t\"MUR\": {Code: \"MUR\", MinorDigits: 2},\n\t\"MVR\": {Code: \"MVR\", MinorDigits: 2},\n\t\"MWK\": {Code: \"MWK\", MinorDigits: 2},\n\t\"MXN\": {Code: \"MXN\", MinorDigits: 2},\n\t\"MYR\": {Code: \"MYR\", MinorDigits: 2},\n\t\"MZN\": {Code: \"MZN\", MinorDigits: 2},\n\t\"NAD\": {Code: \"NAD\", MinorDigits: 2},\n\t\"NGN\": {Code: \"NGN\", MinorDigits: 2},\n\t\"NIO\": {Code: \"NIO\", MinorDigits: 2},\n\t\"NOK\": {Code: \"NOK\", MinorDigits: 2},\n\t\"NPR\": {Code: \"NPR\", MinorDigits: 2},\n\t\"NZD\": {Code: \"NZD\", MinorDigits: 2},\n\t\"OMR\": {Code: \"OMR\", MinorDigits: 3},\n\t\"PAB\": {Code: \"PAB\", MinorDigits: 2},\n\t\"PEN\": {Code: \"PEN\", MinorDigits: 2},\n\t\"PGK\": {Code: \"PGK\", MinorDigits: 2},\n\t\"PHP\": {Code: \"PHP\", MinorDigits: 2},\n\t\"PKR\": {Code: \"PKR\", MinorDigits: 2},\n\t\"PLN\": {Code: \"PLN\", MinorDigits: 2},\n\t\"PYG\": {Code: \"PYG\", MinorDigits: 0},\n\t\"QAR\": {Code: \"QAR\", MinorDigits: 2},\n\t\"RON\": {Code: \"RON\", MinorDigits: 2},\n\t\"RSD\": {Code: \"RSD\", MinorDigits: 2},\n\t\"RUB\": {Code: \"RUB\", MinorDigits: 2},\n\t\"RWF\": {Code: \"RWF\", MinorDigits: 0},\n\t\"SAR\": {Code: \"SAR\", MinorDigits: 2},\n\t\"SBD\": {Code: \"SBD\", MinorDigits: 2},\n\t\"SCR\": {Code: \"SCR\", MinorDigits: 2},\n\t\"SDG\": {Code: \"SDG\", MinorDigits: 2},\n\t\"SEK\": {Code: \"SEK\", MinorDigits: 2},\n\t\"SGD\": {Code: \"SGD\", MinorDigits: 2},\n\t\"SHP\": {Code: \"SHP\", MinorDigits: 2},\n\t\"SLE\": {Code: \"SLE\", MinorDigits: 2},\n\t\"SOS\": {Code: \"SOS\", MinorDigits: 2},\n\t\"SRD\": {Code: \"SRD\", MinorDigits: 2},\n\t\"SSP\": {Code: \"SSP\", MinorDigits: 2},\n\t\"STN\": {Code: \"STN\", MinorDigits: 2},\n\t\"SVC\": {Code: \"SVC\", MinorDigits: 2},\n\t\"SYP\": {Code: \"SYP\", MinorDigits: 2},\n\t\"SZL\": {Code: \"SZL\", MinorDigits: 2},\n\t\"THB\": {Code: \"THB\", MinorDigits: 2},\n\t\"TJS\": {Code: \"TJS\", MinorDigits: 2},\n\t\"TMT\": {Code: \"TMT\", MinorDigits: 2},\n\t\"TND\": {Code: \"TND\", MinorDigits: 3},\n\t\"TOP\": {Code: \"TOP\", MinorDigits: 2},\n\t\"TRY\": {Code: \"TRY\", MinorDigits: 2},\n\t\"TTD\": {Code: \"TTD\", MinorDigits: 2},\n\t\"TWD\": {Code: \"TWD\", MinorDigits: 2},\n\t\"TZS\": {Code: \"TZS\", MinorDigits: 2},\n\t\"UAH\": {Code: \"UAH\", MinorDigits: 2},\n\t\"UGX\": {Code: \"UGX\", MinorDigits: 0},\n\t\"USD\": {Code: \"USD\", MinorDigits: 2},\n\t\"UYU\": {Code: \"UYU\", MinorDigits: 2},\n\t\"UZS\": {Code: \"UZS\", MinorDigits: 2},\n\t\"VES\": {Code: \"VES\", MinorDigits: 2},\n\t\"VND\": {Code: \"VND\", MinorDigits: 0},\n\t\"VUV\": {Code: \"VUV\", MinorDigits: 0},\n\t\"WST\": {Code: \"WST\", MinorDigits: 2},\n\t\"XAF\": {Code: \"XAF\", MinorDigits: 0},\n\t\"XCD\": {Code: \"XCD\", MinorDigits: 2},\n\t\"XOF\": {Code: \"XOF\", MinorDigits: 0},\n\t\"XPF\": {Code: \"XPF\", MinorDigits: 0},\n\t\"YER\": {Code: \"YER\", MinorDigits: 2},\n\t\"ZAR\": {Code: \"ZAR\", MinorDigits: 2},\n\t\"ZMW\": {Code: \"ZMW\", MinorDigits: 2},\n\t\"ZWG\": {Code: \"ZWG\", MinorDigits: 2},\n}\n");
  ("database.go", "package teslrt\n\nimport (\n\t\"context\"\n\t\"sync\"\n\t\"sync/atomic\"\n\n\t\"github.com/jackc/pgx/v5\"\n)\n\n// A `database D = Database { \226\128\166 }` declaration at run time, and the dispatch that decides\n// whether a query reads the in-memory table or the PostgreSQL server.\n//\n// WHY THE DISPATCH IS DYNAMIC. Which store an entity's rows live in is NOT a property of the\n// entity: it is a property of whether something has CONNECTED. Racket's `select-many` asks\n// `database-runtime-for-entity`, which answers a connection only while a `with database D`\n// is active and only for an entity D manages; outside that extent the very same query reads\n// the in-memory source. That is not an accident of the implementation \226\128\148 it is what lets a\n// `test` block exercise a Postgres-backed entity with no server anywhere. So the emitted\n// code carries BOTH forms for an entity of a Postgres-backed database (the Go predicate and\n// the SQL statement), and picks here, exactly as Racket picks there.\n//\n// A program whose databases are all `backend: Memory` never reaches this file: its entities\n// emit the plain `Table*` calls they always did, and its go.mod requires nothing.\ntype Database struct {\n\t// Name as the declaration writes it, which is what a refusal names.\n\tName string\n\t// Config and Tables are what a connection needs: the DSN parts and the schema to create.\n\tConfig PostgresConfig\n\tTables []PostgresTable\n\n\tmutex sync.RWMutex\n\t// The live connection, non-nil only inside `with database D`.\n\topen *PostgresDB\n}\n\n// The database `with database D` most recently bound, program-wide.\n//\n// Racket holds this in ONE parameter (`current-database-runtime`), so at most one database is\n// connected at a time and `transaction { \226\128\166 }` needs no argument to know which server it opens a\n// transaction on \226\128\148 it opens one on whatever is bound. That is the model reproduced here, rather\n// than a per-declaration binding that would have to invent an answer for a `transaction` written\n// where two databases are in scope.\nvar boundDatabase atomic.Pointer[Database]\n\nvar databaseBindings = struct {\n\tmutex sync.Mutex\n\tcond  *sync.Cond\n\towner uint64\n\tdepth int\n}{}\n\nfunc init() {\n\tdatabaseBindings.cond = sync.NewCond(&databaseBindings.mutex)\n}\n\n// acquireDatabaseBinding serializes process-wide bindings while allowing the same goroutine\n// to nest them. The API has no context or handle to carry a binding explicitly, so overlap\n// cannot be made request-local without changing generated programs; serialization makes the\n// existing process-global contract deterministic instead of letting scopes unbind each other.\nfunc acquireDatabaseBinding() {\n\towner := goroutineID()\n\tdatabaseBindings.mutex.Lock()\n\tfor databaseBindings.owner != 0 && databaseBindings.owner != owner {\n\t\tdatabaseBindings.cond.Wait()\n\t}\n\tdatabaseBindings.owner = owner\n\tdatabaseBindings.depth++\n\tdatabaseBindings.mutex.Unlock()\n}\n\nfunc releaseDatabaseBinding() {\n\towner := goroutineID()\n\tdatabaseBindings.mutex.Lock()\n\tdefer databaseBindings.mutex.Unlock()\n\tif databaseBindings.owner != owner || databaseBindings.depth == 0 {\n\t\tpanic(\"database: binding released by a goroutine that does not own it\")\n\t}\n\tdatabaseBindings.depth--\n\tif databaseBindings.depth == 0 {\n\t\tdatabaseBindings.owner = 0\n\t\tdatabaseBindings.cond.Broadcast()\n\t}\n}\n\n// NewDatabase, PostgresTableOf and PostgresColumnOf are what a `database` declaration emits.\n// They are constructors rather than struct literals because gofmt ALIGNS the values in a\n// multi-line composite literal and breaks the alignment run at a nested multi-line value \226\128\148 a\n// rule the emitter would have to reproduce exactly, at every shape, forever. A call whose\n// arguments sit one per line is stable at every size instead.\nfunc NewDatabase(name string, config PostgresConfig, tables []PostgresTable) *Database {\n\treturn &Database{Name: name, Config: config, Tables: tables}\n}\n\nfunc PostgresTableOf(name string, columns ...PostgresColumn) PostgresTable {\n\treturn PostgresTable{Name: name, Columns: columns}\n}\n\n// PostgresTableWithIndexes is the same table plus its declared UNIQUE indexes, which the\n// bootstrap creates. Kept separate from PostgresTableOf so a table with none stays a one-line\n// call in emitted code.\nfunc PostgresTableWithIndexes(name string, unique []PostgresIndex,\n\tcolumns ...PostgresColumn) PostgresTable {\n\treturn PostgresTable{Name: name, Columns: columns, Unique: unique}\n}\n\nfunc PostgresIndexOf(name string, columns ...string) PostgresIndex {\n\treturn PostgresIndex{Name: name, Columns: columns}\n}\n\nfunc PostgresColumnOf(name, columnType string, primaryKey, nullable bool) PostgresColumn {\n\treturn PostgresColumn{Name: name, Type: columnType, PrimaryKey: primaryKey, Nullable: nullable}\n}\n\n// WithDatabase is `with database D { \226\128\166 }`: it connects, runs the body with D bound, and\n// unbinds afterwards \226\128\148 including when the body panics, since a check failure unwinds through\n// here and the next block must not inherit a binding from it.\n//\n// The POOL is not closed on the way out, unlike Racket's `disconnect-database`. `OpenPostgres`\n// is idempotent per configuration, so the second `with database D` in a program reuses the\n// first one's pool rather than paying a fresh handshake; a pool that outlives the block holds\n// idle connections, which is what a pool is for. Nothing observable differs \226\128\148 a query outside\n// the block does not reach the server either way, because the binding is what routes it.\nfunc WithDatabase(database *Database, body func()) {\n\tconnection := OpenPostgres(database.Config, database.Tables)\n\tacquireDatabaseBinding()\n\tdatabase.mutex.Lock()\n\tprevious := database.open\n\tdatabase.open = connection\n\tdatabase.mutex.Unlock()\n\tpreviousBound := boundDatabase.Swap(database)\n\tdefer func() {\n\t\tboundDatabase.Store(previousBound)\n\t\tdatabase.mutex.Lock()\n\t\tdatabase.open = previous\n\t\tdatabase.mutex.Unlock()\n\t\treleaseDatabaseBinding()\n\t}()\n\tbody()\n}\n\n// bound answers the connection a statement should run on, or nil for the in-memory store.\nfunc (database *Database) bound() *PostgresDB {\n\tif database == nil {\n\t\treturn nil\n\t}\n\tdatabase.mutex.RLock()\n\tdefer database.mutex.RUnlock()\n\treturn database.open\n}\n\n// \226\148\128\226\148\128 Transactions \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// A transaction has to run every statement on ONE connection, so the executor a statement\n// picks up has to follow the code that opened it \226\128\148 and that code is an ordinary Tesl function\n// which may call other ordinary Tesl functions, none of which carry a handle.\n//\n// Racket solves this with a parameter, which is THREAD-local, and its web server serves each\n// request on its own thread. The faithful Go reading of \"thread-local\" for a server that\n// serves each request on its own goroutine is goroutine-local, so that is what this is: the\n// open transaction is keyed by goroutine id, and a statement finds it only from inside the\n// goroutine that began it. Two requests in two transactions therefore cannot see each other's\n// uncommitted rows, which a package-level handle would get wrong.\n//\n// The one place this differs from Racket: a goroutine STARTED inside a transaction does not\n// inherit it, where a Racket thread created inside a `parameterize` does. A transaction body\n// that spawns work and expects that work to join the transaction is refused by the emitter\n// rather than silently running outside it.\nvar openTransactions sync.Map // goroutine id -> pgx.Tx\n\n// WithTransaction is `transaction { \226\128\166 }`: the body runs atomically with respect to a trap.\n// Against PostgreSQL it is a real BEGIN/COMMIT, rolled back if the body panics so a check\n// failure halfway through leaves nothing behind. Against the in-memory store it is the same\n// PROMISE kept a different way \226\128\148 see `WithMemoryTransaction` \226\128\148 because the spec says the\n// transaction rolls back on any exception and does not carve the Memory store out of that, and\n// `tesl test` runs on the Memory store: a test asserting atomicity has to observe the same\n// outcome production does.\nfunc WithTransaction(body func()) {\n\tdatabase := boundDatabase.Load()\n\tconnection := database.bound()\n\tif connection == nil {\n\t\tWithMemoryTransaction(body)\n\t\treturn\n\t}\n\t// The lease bound applies to acquiring the connection and issuing BEGIN, not to the body:\n\t// the body's own statements each run under their own lease (see the executors), and the\n\t// commit gets a fresh bound below, so a transaction may legitimately outlive one lease.\n\tbeginCtx, cancelBegin := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\tdefer cancelBegin()\n\ttransaction, err := connection.pool.Begin(beginCtx)\n\tif err != nil {\n\t\tpanic(pgFailure(\"transaction: cannot begin\", err))\n\t}\n\tkey := goroutineID()\n\tif _, nested := openTransactions.Load(key); nested {\n\t\t// Racket nests by starting a SAVEPOINT; until that is built, a nested block would\n\t\t// silently commit the outer one at its own end, so it is refused here rather than\n\t\t// answered with weaker atomicity than it claims.\n\t\t_ = transaction.Rollback(beginCtx)\n\t\tpanic(\"transaction: a transaction is already open on database \" + database.Name)\n\t}\n\topenTransactions.Store(key, transaction)\n\tcommitted := false\n\tdefer func() {\n\t\topenTransactions.Delete(key)\n\t\tif !committed {\n\t\t\tctx, cancel := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\t\t\tdefer cancel()\n\t\t\t_ = transaction.Rollback(ctx)\n\t\t}\n\t}()\n\tbody()\n\tcommitCtx, cancelCommit := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\tdefer cancelCommit()\n\tif err := transaction.Commit(commitCtx); err != nil {\n\t\tpanic(pgFailure(\"transaction: cannot commit\", err))\n\t}\n\tcommitted = true\n}\n\n// currentTransaction is the open transaction for THIS goroutine, if any.\nfunc currentTransaction() pgx.Tx {\n\tif found, open := openTransactions.Load(goroutineID()); open {\n\t\tif transaction, ok := found.(pgx.Tx); ok {\n\t\t\treturn transaction\n\t\t}\n\t}\n\treturn nil\n}\n");
  ("dbquery.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"strings\"\n\n\t\"github.com/jackc/pgx/v5\"\n)\n\n// The query dispatchers for an entity of a Postgres-backed database.\n//\n// Each takes BOTH forms of the same query \226\128\148 the Go predicate the in-memory store needs and the\n// statement the server needs \226\128\148 and runs whichever the binding selects (see database.go). They\n// exist only for entities a `backend: Postgres` database manages; a Memory-backed entity emits\n// the plain `Table*` call directly, so nothing about a memory-only program changes.\n//\n// WHY THE ARGUMENTS ARE A THUNK. Both forms sit at the same call site, which is what keeps them\n// from drifting apart \226\128\148 but only one of them RUNS. Were the arguments a plain slice they would\n// be evaluated on the way in even when the memory path is taken, and a `where` operand that\n// reads the clock, draws a random value or fails a check would then run where the memory-only\n// emission never ran it. The thunk is what makes \"emitted twice\" mean \"evaluated once, on the\n// path that is taken\".\n//\n// The statement's TEXT never contains a value: every operand is a `$n` placeholder, so nothing\n// a request sends can change what a statement SAYS.\ntype PgPlan struct {\n\tSQL string\n\t// Args is nil for a statement with no placeholders.\n\tArgs    func() []any\n\tCapture func(int)\n\t// Probe is a second statement a dispatcher may run to EXPLAIN an empty result \226\128\148 for\n\t// `updateAndReturnOne`, the `select count(*)` over the same predicate that tells \"no row\n\t// matched\" from \"more than one row matched\". Empty for every other plan.\n\tProbe     string\n\tProbeArgs func() []any\n}\n\n// PgSql is the constructor the emitter calls. A function rather than a struct literal because\n// gofmt aligns the keys of a multi-line composite literal and breaks the alignment run at a\n// nested multi-line value; a call with the argument thunk last is stable at every size.\nfunc PgSql(statement string, args func() []any) PgPlan {\n\treturn PgPlan{SQL: statement, Args: args}\n}\n\n// PgSqlProbed is `PgSql` plus the explaining probe (see PgPlan.Probe).\nfunc PgSqlProbed(statement string, args func() []any, probe string, probeArgs func() []any) PgPlan {\n\treturn PgPlan{SQL: statement, Args: args, Probe: probe, ProbeArgs: probeArgs}\n}\n\nfunc (plan PgPlan) probeArguments() []any {\n\tif plan.ProbeArgs == nil {\n\t\treturn nil\n\t}\n\treturn plan.ProbeArgs()\n}\n\nfunc (plan PgPlan) arguments() []any {\n\tif plan.Args == nil {\n\t\treturn nil\n\t}\n\treturn plan.Args()\n}\n\n// DbSelect is `select \226\128\166 [order \226\128\166] [limit \226\128\166] [offset \226\128\166]`. `less` is nil when the query has no\n// order clause; on the server side the ordering and the range are already in the statement.\nfunc DbSelect[Row any](database *Database, table *Table[Row], match func(Row) bool,\n\tless func(Row, Row) bool, offset, limit int, plan PgPlan,\n\tscan func(pgx.CollectableRow) (Row, error)) []Row {\n\tif connection := database.bound(); connection != nil {\n\t\treturn PgQueryPlan(connection, plan, scan)\n\t}\n\tif less == nil {\n\t\treturn TableSelectRange(table, match, offset, limit)\n\t}\n\treturn TableSelectSorted(table, match, less, offset, limit)\n}\n\n// DbSelectOne is `selectOne`: the statement carries `limit 1`, so \"no row\" is the only thing\n// left to decide and both paths decide it the same way.\nfunc DbSelectOne[Row any](database *Database, table *Table[Row], match func(Row) bool,\n\tless func(Row, Row) bool, plan PgPlan,\n\tscan func(pgx.CollectableRow) (Row, error)) Maybe[Row] {\n\tif connection := database.bound(); connection != nil {\n\t\treturn PgQueryOnePlan(connection, plan, scan)\n\t}\n\tif less == nil {\n\t\treturn TableSelectOne(table, match)\n\t}\n\treturn TableSelectOneSorted(table, match, less)\n}\n\n// DbCount is `selectCount`. The server counts in the database rather than shipping rows to be\n// counted here, which is the whole reason an aggregate is a separate query shape.\nfunc DbCount[Row any](database *Database, table *Table[Row], match func(Row) bool,\n\tplan PgPlan) Int {\n\tif connection := database.bound(); connection != nil {\n\t\treturn PgCountPlan(connection, plan)\n\t}\n\treturn TableCount(table, match)\n}\n\n// DbSum is `selectSum` over a scalar column. The statement is `coalesce(sum(col), 0)`, so a\n// sum over no rows is zero on both paths rather than NULL on one of them.\nfunc DbSum[Row any, Value any](database *Database, table *Table[Row], match func(Row) bool,\n\tproject func(Row) Value, combine func(Value, Value) Value, zero Value, plan PgPlan,\n\tscan func(pgx.Row) (Value, error)) Value {\n\tif connection := database.bound(); connection != nil {\n\t\treturn PgScalarPlan(connection, plan, scan)\n\t}\n\treturn TableFold(table, match, project, combine, zero)\n}\n\n// DbSumMoney is `selectSum` over a MONEY column, whose two refusals (an empty row set has no\n// currency for its zero; two currencies have no common total) need two more facts than the sum\n// itself. Both come back in ONE statement \226\128\148 `sum`, `count(distinct currency)`, `min(currency)`\n// \226\128\148 which is the shape `dsl/sql.rkt` uses, so neither path makes a second pass over the rows.\nfunc DbSumMoney[Row any](database *Database, table *Table[Row], match func(Row) bool,\n\tproject func(Row) Money, entity, field string, plan PgPlan) Money {\n\tif connection := database.bound(); connection != nil {\n\t\treturn PgSumMoneyPlan(connection, plan, entity, field)\n\t}\n\treturn TableSumMoney(table, match, project, entity, field)\n}\n\n// DbExtreme is `selectMax` / `selectMin`: `max(col)` / `min(col)` on the server, and the same\n// `Maybe` on both paths, since SQL's aggregate over no rows is NULL where Tesl says Nothing.\nfunc DbExtreme[Row any, Value any](database *Database, table *Table[Row], match func(Row) bool,\n\tproject func(Row) Value, better func(Value, Value) bool, plan PgPlan,\n\tscan func(pgx.Row) (Maybe[Value], error)) Maybe[Value] {\n\tif connection := database.bound(); connection != nil {\n\t\treturn PgScalarPlan(connection, plan, scan)\n\t}\n\treturn TableExtreme(table, match, project, better)\n}\n\n// DbInsert is `insert`. The duplicate-key refusal is the SERVER's on the Postgres path \226\128\148 the\n// primary key column carries the constraint \226\128\148 and the emitted `conflicts` comparison on the\n// memory path, which is what makes the two agree about which programs run.\n//\n// The arguments are read off the ROW rather than emitted a second time from the same field\n// expressions: a row whose `createdAt` is `Time.nowMillis()` would otherwise be STORED with one\n// instant and ANSWERED with another.\nfunc DbInsert[Row any](database *Database, table *Table[Row], entity string, row Row,\n\tconflicts func(Row, Row) bool, statement string, bind func(Row) []any,\n\tunique ...UniqueIndex[Row]) Row {\n\tif connection := database.bound(); connection != nil {\n\t\t// A declared `unique index` is a real index on the server, created by the bootstrap,\n\t\t// so the constraint is enforced where the rows are rather than twice.\n\t\tPgExec(connection, statement, bind(row))\n\t\treturn row\n\t}\n\treturn TableInsert(table, entity, row, conflicts, unique...)\n}\n\n// DbInsertMany inserts in order. One statement per row rather than a multi-row VALUES list, so\n// a row conflicting with an EARLIER row of the same batch is refused exactly where it would be\n// if the two had been inserted separately \226\128\148 Racket's `insert-many!` is a loop over\n// `insert-one!`, and a single statement would instead fail the whole batch at a different point.\n// The rows are only known at run time, so the statement is fixed and its ARGUMENTS are read off\n// each row by the emitter's binder \226\128\148 the one place in this file where a plan cannot be a value.\nfunc DbInsertMany[Row any](database *Database, table *Table[Row], entity string, rows []Row,\n\tconflicts func(Row, Row) bool, statement string, bind func(Row) []any,\n\tunique ...UniqueIndex[Row]) struct{} {\n\tif connection := database.bound(); connection != nil {\n\t\tfor _, row := range rows {\n\t\t\tPgExec(connection, statement, bind(row))\n\t\t}\n\t\treturn struct{}{}\n\t}\n\treturn TableInsertMany(table, entity, rows, conflicts, unique...)\n}\n\n// DbUpdate is `update \226\128\166 set \226\128\166`. Nothing is reported back: a plain update is a statement.\nfunc DbUpdate[Row any](database *Database, table *Table[Row], match func(Row) bool,\n\tapply func(Row) Row, plan PgPlan, unique ...UniqueIndex[Row]) struct{} {\n\tif connection := database.bound(); connection != nil {\n\t\tPgExecPlan(connection, plan)\n\t\treturn struct{}{}\n\t}\n\treturn TableUpdate(table, match, apply, unique...)\n}\n\n// DbUpdateReturnOne is `updateAndReturnOne`: the statement carries `returning`, and a predicate\n// that matched nothing is a failure on both paths rather than a zero value.\nfunc DbUpdateReturnOne[Row any](database *Database, table *Table[Row], match func(Row) bool,\n\tapply func(Row) Row, plan PgPlan, scan func(pgx.CollectableRow) (Row, error),\n\tunique ...UniqueIndex[Row]) Row {\n\tif connection := database.bound(); connection != nil {\n\t\tupdated := pgUpdateReturnOne(connection, plan, scan)\n\t\tif len(updated) == 0 {\n\t\t\tpanic(\"updateAndReturnOne: no row matched\")\n\t\t}\n\t\treturn updated[0]\n\t}\n\treturn TableUpdateReturnOne(table, match, apply, unique...)\n}\n\n// pgUpdateReturnOne runs the emitted `update \226\128\166 where <pred> and (select count(*) from \226\128\166\n// where <pred>) = 1 returning \226\128\166` statement. The count guard is what makes \"one row\" a\n// server-side guarantee: with two or more matches the statement updates NOTHING. A first\n// version selected the row by `ctid` through a scalar subquery, which raised\n// cardinality_violation for the ambiguous case but MISSED the row under contention \226\128\148 a\n// concurrent writer moves the row to a new ctid, and the outer TID scan keeps the statement's\n// snapshot, so an existing row answered \"no row matched\" (whitebox campaign, 2026-09-02).\n// The count form re-checks the predicate on the row's latest version instead. An empty\n// result is then explained by the plan's probe, so the ambiguous case still gets its own\n// trap \226\128\148 the same message the Memory table raises.\nfunc pgUpdateReturnOne[Row any](db *PostgresDB, plan PgPlan,\n\tscan func(pgx.CollectableRow) (Row, error)) []Row {\n\tupdated := PgQueryPlan(db, plan, scan)\n\tif len(updated) == 0 && plan.Probe != \"\" {\n\t\tmatched, exact := PgCount(db, plan.Probe, plan.probeArguments()).Int64()\n\t\tif exact && matched > 1 {\n\t\t\tpanic(updateReturnOneAmbiguous)\n\t\t}\n\t}\n\treturn updated\n}\n\n// DbDelete is `delete`.\nfunc DbDelete[Row any](database *Database, table *Table[Row], match func(Row) bool,\n\tplan PgPlan) struct{} {\n\tif connection := database.bound(); connection != nil {\n\t\tPgExecPlan(connection, plan)\n\t\treturn struct{}{}\n\t}\n\treturn TableDelete(table, match)\n}\n\n// DbTruncate empties an entity's store, for a test block that starts from an empty one.\nfunc DbTruncate[Row any](database *Database, table *Table[Row], tableName string) {\n\tif connection := database.bound(); connection != nil {\n\t\tPgTruncate(connection, tableName)\n\t\treturn\n\t}\n\tTableTruncate(table)\n}\n\n// DbDeleteCount is `deleteAndReturnResult`. On the server the count comes back from the\n// statement's own tag, so the rows are counted once on either path.\nfunc DbDeleteCount[Row any](database *Database, table *Table[Row], match func(Row) bool,\n\tplan PgPlan) Int {\n\tif connection := database.bound(); connection != nil {\n\t\treturn FromInt64(PgExecPlan(connection, plan))\n\t}\n\treturn TableDeleteCount(table, match)\n}\n\n// DbUpsert is `upsert \226\128\166 onConflict [c] doUpdate [u]`. On a Postgres-backed database the SERVER\n// decides the conflict \226\128\148 `insert \226\128\166 on conflict (c) do update set u = EXCLUDED.u` is one\n// statement and one round trip, and the conflict target is the unique index the bootstrap\n// created \226\128\148 so the memory path's find-then-merge has no counterpart there. Off a connection it\n// is exactly that find-then-merge, which is what makes a test exercise the same program.\nfunc DbUpsert[Row any](database *Database, table *Table[Row], entity string, row Row,\n\tmatches func(Row, Row) bool, merge func(Row, Row) Row, conflicts func(Row, Row) bool,\n\tstatement string, bind func(Row) []any, unique ...UniqueIndex[Row]) Row {\n\tif connection := database.bound(); connection != nil {\n\t\tPgExec(connection, statement, bind(row))\n\t\treturn row\n\t}\n\treturn TableUpsert(table, entity, row, matches, merge, conflicts, unique...)\n}\n\n// DbGroupFold is the grouped aggregate. On a Postgres-backed database the GROUPING is the\n// server's \226\128\148 `select <key>, <agg> \226\128\166 group by 1 order by 1` \226\128\148 because shipping every row here to\n// bucket it is the thing a grouped aggregate exists to avoid; the scanner reads one (key, value)\n// pair per row. Off a connection it folds the in-memory table, and both answer in ascending key\n// order, which is the contract rather than an accident of iteration.\nfunc DbGroupFold[Row any, Key any, Value any](\n\tdatabase *Database, table *Table[Row],\n\tmatch func(Row) bool,\n\tkey func(Row) Key, less func(Key, Key) bool, equal func(Key, Key) bool,\n\tstep func(Value, Row) Value, zero Value,\n\tplan PgGroupPlan, scan func(pgx.CollectableRow) (Tuple2[Key, Value], error),\n) []Tuple2[Key, Value] {\n\tif connection := database.bound(); connection != nil {\n\t\tstatement, arguments := plan.statement()\n\t\treturn PgQuery(connection, statement, arguments, scan)\n\t}\n\treturn TableGroupFold(table, match, key, less, equal, step, zero)\n}\n\n// PgGroupPlan is a grouped aggregate's statement in PIECES rather than as one string.\n//\n// The bucket expression depends on the ZONE, and a zone is a value the program supplies at run\n// time (`minutesPerDay(zone: TimeZone)`), so the statement cannot be baked at compile time \226\128\148\n// `dsl/sql.rkt` composes the same one per call for the same reason. The pieces are what the\n// emitter knows statically; the zone-dependent part is assembled here, so the two backends\n// cannot drift on where a bucket starts.\ntype PgGroupPlan struct {\n\t// The aggregate over the group, already rendered: `count(*)`, `coalesce(sum(\"minutes\"), 0)`.\n\tAggregate string\n\t// The qualified, quoted table.\n\tTable string\n\t// The `where \226\128\166` fragment, or \"\" \226\128\148 with its own `$1..$n` placeholders.\n\tWhere string\n\t// The where fragment's arguments. The bucket's own argument follows them.\n\tArgs []any\n\t// The quoted group column.\n\tColumn string\n\t// \"\" groups by the column itself; otherwise the calendar unit (Hour|Day|Week|Month|Year).\n\tUnit string\n\tZone PgGroupZone\n}\n\n// statement renders the plan, and the bucket expression with it.\n//\n// A NAMED zone hands the DST-correct work to PostgreSQL's own tzdata \226\128\148\n// `date_trunc(u, ts at time zone $z) at time zone $z` \226\128\148 which mirrors the engine's two-step\n// semantics (instant \226\134\146 local wall clock \226\134\146 truncate \226\134\146 back), and PG's `date_trunc('week')` is\n// the ISO Monday week the engine uses. A FIXED offset is integer arithmetic on the millisecond\n// column for hour/day/week, and `date_trunc` on the UTC-shifted timestamp for month/year,\n// because those two are calendar units rather than fixed spans.\nfunc (plan PgGroupPlan) statement() (string, []any) {\n\targuments := append([]any{}, plan.Args...)\n\tplaceholder := func(value any) string {\n\t\targuments = append(arguments, value)\n\t\treturn fmt.Sprintf(\"$%d\", len(arguments))\n\t}\n\tunit := strings.ToLower(plan.Unit)\n\t// The unit is the one part of this statement that lands in SQL TEXT rather than a parameter\n\t// (`date_trunc` takes a literal field name), so it is checked against the closed set the\n\t// emitter can produce. Nothing user-supplied reaches it today \226\128\148 `Time.truncHour` and its\n\t// four siblings are the only sources \226\128\148 and this is what keeps that true if a later surface\n\t// lets a unit come from a value.\n\tswitch unit {\n\tcase \"\", \"hour\", \"day\", \"week\", \"month\", \"year\":\n\tdefault:\n\t\tpanic(\"database: \" + unit + \" is not a grouping unit (hour, day, week, month, year)\")\n\t}\n\tbucket := plan.Column\n\tswitch {\n\tcase unit == \"\":\n\tcase !plan.Zone.Fixed && plan.Zone.Name != \"\":\n\t\tzone := placeholder(plan.Zone.Name)\n\t\tbucket = fmt.Sprintf(\n\t\t\t\"(extract(epoch from (date_trunc('%s', to_timestamp((%s)::double precision / 1000.0) \"+\n\t\t\t\t\"at time zone %s) at time zone %s))::bigint * 1000)\",\n\t\t\tunit, plan.Column, zone, zone)\n\tdefault:\n\t\toffset := placeholder(int64(plan.Zone.OffsetMinutes) * 60000)\n\t\tlocal := fmt.Sprintf(\"(%s + %s)\", plan.Column, offset)\n\t\t// Floor to a multiple of n, with the sign of the dividend handled: `%` in SQL keeps the\n\t\t// dividend's sign, and a bucket before the epoch must round DOWN.\n\t\tfloorTo := func(value string, n int64) string {\n\t\t\treturn fmt.Sprintf(\"(%s - (((%s %% %d) + %d) %% %d))\", value, value, n, n, n)\n\t\t}\n\t\tswitch unit {\n\t\tcase \"hour\":\n\t\t\tbucket = fmt.Sprintf(\"(%s - %s)\", floorTo(local, 3600000), offset)\n\t\tcase \"day\":\n\t\t\tbucket = fmt.Sprintf(\"(%s - %s)\", floorTo(local, 86400000), offset)\n\t\tcase \"week\":\n\t\t\t// Epoch day 0 is a Thursday, so the ISO Monday week is the week grid shifted by\n\t\t\t// three days \226\128\148 the same +3/-3 the engine applies.\n\t\t\tshifted := fmt.Sprintf(\"(%s + 259200000)\", local)\n\t\t\tbucket = fmt.Sprintf(\"((%s - 259200000) - %s)\", floorTo(shifted, 604800000), offset)\n\t\tdefault:\n\t\t\tbucket = fmt.Sprintf(\n\t\t\t\t\"((extract(epoch from date_trunc('%s', to_timestamp((%s)::double precision / 1000.0) \"+\n\t\t\t\t\t\"at time zone 'UTC'))::bigint * 1000) - %s)\",\n\t\t\t\tunit, local, offset)\n\t\t}\n\t}\n\twhere := \"\"\n\tif plan.Where != \"\" {\n\t\twhere = \" \" + plan.Where\n\t}\n\treturn fmt.Sprintf(\"select %s, %s from %s%s group by 1 order by 1\",\n\t\tbucket, plan.Aggregate, plan.Table, where), arguments\n}\n");
  ("postgres.go", "package teslrt\n\nimport (\n\t\"context\"\n\t\"errors\"\n\t\"fmt\"\n\t\"math/big\"\n\t\"os\"\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n\t\"time\"\n\n\t\"github.com/jackc/pgx/v5\"\n\t\"github.com/jackc/pgx/v5/pgconn\"\n\t\"github.com/jackc/pgx/v5/pgtype\"\n\t\"github.com/jackc/pgx/v5/pgxpool\"\n)\n\n// The PostgreSQL backend: `database D = Database { \226\128\166 backend: Postgres (\226\128\166) }`.\n//\n// This is the second approved non-stdlib dependency (`github.com/jackc/pgx/v5`), and it ships\n// only with a program that declares a Postgres database \226\128\148 a Memory-backed program still emits a\n// go.mod requiring nothing. Go has no Postgres driver in its standard library, so there is no\n// substitute available the way `crypto/hmac` was for MACs.\n//\n// WHAT THE COMPILER DOES AND WHAT THIS DOES. Every statement is built at COMPILE time: the\n// emitter turns a `select \226\128\166 where \226\128\166` into SQL text with `$1`-style placeholders plus the\n// arguments, because the query's shape is known statically and building it here would mean\n// re-deriving what the emitter already knows. So this file holds the connection, the schema\n// bootstrap, the value mapping, and the four executors \226\128\148 nothing that decides what a query says.\n//\n// THE COLUMN TYPES ARE THE RACKET RUNTIME'S, not a fresh choice. They have to be, or a table\n// created by one backend is unreadable by the other:\n//\n//\tInt          NUMERIC             arbitrary precision, lossless at any magnitude\n//\tInt32        INTEGER             the opt-in compact width\n//\tFloat        DOUBLE PRECISION\n//\tString       TEXT\n//\tBool         BOOLEAN\n//\tPosixMillis  BIGINT              the one deliberate exception to Int \226\134\146 NUMERIC\n//\n// A newtype takes its base's column type; a `Maybe X` column is X's type, nullable.\n//\n// WHICH PROGRAMS GET THIS FILE. Only one that declares a Postgres-backed database: the driver\n// and its dependency chain have no place in a binary that never opens a connection, the same\n// argument that gates the HTTP half. A declared database is still INERT until something\n// connects \226\128\148 `with database D` is the only thing that does \226\128\148 so a `test` block over a\n// Postgres-backed entity runs against the in-memory table with no server anywhere, which is\n// the dispatch `database.go` performs.\ntype PostgresConfig struct {\n\tDBName   string\n\tUser     string\n\tPassword string\n\tHost     string\n\tPort     int\n\t// PoolSize is the maximum number of live connections. Zero preserves Tesl's omitted\n\t// poolSize default of 10.\n\tPoolSize int\n\t// SocketDir selects a Unix-socket connection (`SocketConnection`), which is how a local\n\t// cluster is usually reached; when it is set, Host and Port are ignored.\n\tSocketDir string\n\tSchema    string\n}\n\n// PostgresColumn describes one column, as the entity declares it.\ntype PostgresColumn struct {\n\tName       string\n\tType       string\n\tPrimaryKey bool\n\tNullable   bool\n}\n\n// PostgresTable is an entity's table, named as the entity names it.\ntype PostgresTable struct {\n\tName    string\n\tColumns []PostgresColumn\n\t// The declared UNIQUE indexes. A plain index is a performance hint with no observable\n\t// effect and is not created here; a unique one is an INVARIANT, and the two backends have\n\t// to agree about which programs run.\n\tUnique []PostgresIndex\n}\n\n// PostgresIndex is one declared index: the name `dsl/sql.rkt` derives (`<table>_<cols>_idx`,\n// or an explicit `as \"\226\128\166\"`) and the columns it covers. The NAME matters \226\128\148 a table shared with\n// the Racket backend must not end up with two indexes doing the same job.\ntype PostgresIndex struct {\n\tName    string\n\tColumns []string\n}\n\n// PostgresDB is a live pool plus the schema every statement is qualified with.\ntype PostgresDB struct {\n\tpool           *pgxpool.Pool\n\tschema         string\n\tbootstrapMutex sync.Mutex\n\toutboxReady    bool // protected by bootstrapMutex; runtime DDL runs before first binding\n}\n\ntype postgresInitialization struct {\n\tdone    chan struct{}\n\tdb      *PostgresDB\n\tfailure any\n}\n\nvar postgresConnectOnce sync.Map // schema+dsn -> *postgresInitialization\n\n// OpenPostgres connects, creates the schema and the declared tables if they are absent, and\n// answers a pool. It is idempotent per configuration: a program with several databases on one\n// cluster opens one pool per configuration rather than one per call site.\n//\n// The environment wins over the declaration for the password and the host, because those are\n// deployment facts rather than program facts: `PGPASSWORD`, `PGHOST` and `PGPORT` are the names\n// every other Postgres client already reads, so a deployment does not need a Tesl-specific one.\nfunc OpenPostgres(config PostgresConfig, tables []PostgresTable) *PostgresDB {\n\tdsn := postgresDSN(config)\n\tpoolConfig := postgresPoolConfig(config, dsn)\n\tkey := fmt.Sprintf(\"%s\\x00%s\\x00%d\", config.Schema, dsn, poolConfig.MaxConns)\n\tcreated := &postgresInitialization{done: make(chan struct{})}\n\tactual, loaded := postgresConnectOnce.LoadOrStore(key, created)\n\tinitialization, ok := actual.(*postgresInitialization)\n\tif !ok {\n\t\tpanic(\"database: connection registry holds an unexpected value\")\n\t}\n\tif !loaded {\n\t\tinitializePostgres(key, initialization, poolConfig, config.Schema, tables)\n\t} else {\n\t\t<-initialization.done\n\t}\n\tif initialization.failure != nil {\n\t\tpanic(initialization.failure)\n\t}\n\tif initialization.db == nil {\n\t\tpanic(\"database: PostgreSQL initialization completed without a pool\")\n\t}\n\tif loaded {\n\t\tctx, cancel := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\t\tinitialization.db.bootstrap(ctx, tables)\n\t\tcancel()\n\t}\n\treturn initialization.db\n}\n\nfunc initializePostgres(key string, initialization *postgresInitialization,\n\tpoolConfig *pgxpool.Config, schema string, tables []PostgresTable) {\n\tdefer close(initialization.done)\n\tvar pool *pgxpool.Pool\n\tdefer func() {\n\t\tif failure := recover(); failure != nil {\n\t\t\tif pool != nil {\n\t\t\t\tpool.Close()\n\t\t\t}\n\t\t\tinitialization.failure = failure\n\t\t\tpostgresConnectOnce.CompareAndDelete(key, initialization)\n\t\t}\n\t}()\n\tctx, cancel := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\tdefer cancel()\n\tvar err error\n\tpool, err = pgxpool.NewWithConfig(ctx, poolConfig)\n\tif err != nil {\n\t\tpanic(\"database: cannot connect to PostgreSQL: \" + err.Error())\n\t}\n\tdb := &PostgresDB{pool: pool, schema: schema}\n\tdb.bootstrap(ctx, tables)\n\tinitialization.db = db\n}\n\nconst defaultPostgresPoolSize = 10\n\nfunc postgresPoolConfig(config PostgresConfig, dsn string) *pgxpool.Config {\n\tpoolConfig, err := pgxpool.ParseConfig(dsn)\n\tif err != nil {\n\t\tpanic(\"database: invalid PostgreSQL configuration: \" + err.Error())\n\t}\n\tsize := config.PoolSize\n\tif size == 0 {\n\t\tsize = defaultPostgresPoolSize\n\t}\n\t// validPostgresPoolSize proves size fits pgx's int32 limit.\n\tpoolConfig.MaxConns = int32(validPostgresPoolSize(size)) // #nosec G115 -- range validated above\n\treturn poolConfig\n}\n\nfunc validPostgresPoolSize(size int) int {\n\tconst maxPoolSize = int64(1<<31 - 1)\n\tif size < 1 || int64(size) > maxPoolSize {\n\t\tpanic(fmt.Sprintf(\"database: poolSize must be between 1 and %d\", maxPoolSize))\n\t}\n\treturn size\n}\n\n// PgPoolSize lowers `envInt name fallback` in PostgresConfig.poolSize.\nfunc PgPoolSize(name string, fallback int) int {\n\ttext := os.Getenv(name)\n\tif text == \"\" {\n\t\treturn validPostgresPoolSize(fallback)\n\t}\n\tparsed, err := strconv.ParseInt(text, 10, 32)\n\tif err != nil || parsed < 1 {\n\t\tpanic(fmt.Sprintf(\"envInt: invalid positive pool size environment value %s=%s\", name, text))\n\t}\n\treturn validPostgresPoolSize(int(parsed))\n}\n\n// PgPort reads a port out of the environment, falling back to the number the declaration\n// wrote. It is not `EnvInt`: a Tesl `Int` is unbounded and a port is an ordinary `int`, and a\n// value that is not a port at all is the declaration's fallback rather than a zero \226\128\148 a zero\n// port would silently become \"let the OS choose\", which is not what an unset variable means.\nfunc PgPort(name string, fallback int) int {\n\ttext := os.Getenv(name)\n\tif text == \"\" {\n\t\treturn fallback\n\t}\n\tparsed, err := strconv.Atoi(text)\n\tif err != nil || parsed <= 0 || parsed > 65535 {\n\t\treturn fallback\n\t}\n\treturn parsed\n}\n\nfunc postgresDSN(config PostgresConfig) string {\n\tsettings := []string{}\n\tadd := func(key, value string) {\n\t\tif value != \"\" {\n\t\t\tsettings = append(settings, key+\"=\"+value)\n\t\t}\n\t}\n\tadd(\"dbname\", config.DBName)\n\tadd(\"user\", config.User)\n\tpassword := config.Password\n\tif fromEnv := os.Getenv(\"PGPASSWORD\"); fromEnv != \"\" {\n\t\tpassword = fromEnv\n\t}\n\tadd(\"password\", password)\n\tif config.SocketDir != \"\" {\n\t\tadd(\"host\", config.SocketDir)\n\t} else {\n\t\thost := config.Host\n\t\tif fromEnv := os.Getenv(\"PGHOST\"); fromEnv != \"\" {\n\t\t\thost = fromEnv\n\t\t}\n\t\tadd(\"host\", host)\n\t\tport := config.Port\n\t\tif fromEnv := os.Getenv(\"PGPORT\"); fromEnv != \"\" {\n\t\t\tif parsed, err := strconv.Atoi(fromEnv); err == nil {\n\t\t\t\tport = parsed\n\t\t\t}\n\t\t}\n\t\tif port > 0 {\n\t\t\tadd(\"port\", strconv.Itoa(port))\n\t\t}\n\t}\n\treturn strings.Join(settings, \" \")\n}\n\n// bootstrap creates the schema, declared tables, and the runtime-owned pub/sub outbox before\n// the Database can be bound. `if not exists` throughout: a second process starting at the same\n// time must not fail. Application tables are never altered; the outbox's idempotent ALTERs are\n// runtime metadata rather than application migration machinery.\nfunc (db *PostgresDB) bootstrap(ctx context.Context, tables []PostgresTable) {\n\tdb.bootstrapMutex.Lock()\n\tdefer db.bootstrapMutex.Unlock()\n\tif db.schema != \"\" {\n\t\tif _, err := db.pool.Exec(ctx,\n\t\t\t\"create schema if not exists \"+quoteIdentifier(db.schema)); err != nil {\n\t\t\tpanic(\"database: cannot create schema \" + db.schema + \": \" + err.Error())\n\t\t}\n\t}\n\tfor _, table := range tables {\n\t\tdefinitions := make([]string, 0, len(table.Columns))\n\t\tfor _, column := range table.Columns {\n\t\t\tdefinition := quoteIdentifier(column.Name) + \" \" + column.Type\n\t\t\tswitch {\n\t\t\tcase column.PrimaryKey:\n\t\t\t\tdefinition += \" PRIMARY KEY\"\n\t\t\tcase !column.Nullable:\n\t\t\t\tdefinition += \" NOT NULL\"\n\t\t\t}\n\t\t\tdefinitions = append(definitions, definition)\n\t\t}\n\t\tstatement := fmt.Sprintf(\"create table if not exists %s (%s)\",\n\t\t\tdb.QualifiedTable(table.Name), strings.Join(definitions, \", \"))\n\t\tif _, err := db.pool.Exec(ctx, statement); err != nil {\n\t\t\tpanic(\"database: cannot create table \" + table.Name + \": \" + err.Error())\n\t\t}\n\t\tfor _, index := range table.Unique {\n\t\t\tcolumns := make([]string, 0, len(index.Columns))\n\t\t\tfor _, column := range index.Columns {\n\t\t\t\tcolumns = append(columns, quoteIdentifier(column))\n\t\t\t}\n\t\t\tindexStatement := fmt.Sprintf(\"create unique index if not exists %s on %s (%s)\",\n\t\t\t\tquoteIdentifier(index.Name), db.QualifiedTable(table.Name),\n\t\t\t\tstrings.Join(columns, \", \"))\n\t\t\tif _, err := db.pool.Exec(ctx, indexStatement); err != nil {\n\t\t\t\tpanic(\"database: cannot create unique index \" + index.Name + \": \" + err.Error())\n\t\t\t}\n\t\t}\n\t}\n\t// Even ALTER ... ADD COLUMN IF NOT EXISTS takes ACCESS EXCLUSIVE. Repeating\n\t// runtime upgrades on every WithDatabase can block behind an ordinary outbox\n\t// reader/publisher, including this process's own active dispatcher. New\n\t// application declarations above still bootstrap against the retained pool.\n\tif !db.outboxReady {\n\t\tif err := createPubsubOutbox(ctx, db); err != nil {\n\t\t\tpanic(\"database: cannot create the pub/sub outbox: \" + err.Error())\n\t\t}\n\t\tif err := normalizeLegacyPubsubRows(db); err != nil {\n\t\t\tpanic(\"database: cannot upgrade the pub/sub outbox: \" + err.Error())\n\t\t}\n\t\tdb.outboxReady = true\n\t}\n}\n\n// QualifiedTable is `\"schema\".\"table\"`, quoted so a name that needs quoting works and a name\n// that does not is unchanged.\nfunc (db *PostgresDB) QualifiedTable(table string) string {\n\tif db.schema == \"\" {\n\t\treturn quoteIdentifier(table)\n\t}\n\treturn quoteIdentifier(db.schema) + \".\" + quoteIdentifier(table)\n}\n\n// quoteIdentifier doubles any embedded quote, which is the only escape a quoted SQL identifier\n// has. Identifiers here come from the PROGRAM (an entity's declared table name), never from a\n// request, but quoting is what keeps that true if one ever does.\nfunc quoteIdentifier(name string) string {\n\treturn `\"` + strings.ReplaceAll(name, `\"`, `\"\"`) + `\"`\n}\n\n// \226\148\128\226\148\128 Executing \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// Four executors, because a Tesl query is one of four shapes. Each takes SQL the EMITTER built,\n// so nothing here decides what a query says.\n\n// Every statement goes through `executor` rather than through the pool directly: inside a\n// `transaction { \226\128\166 }` the statements have to share ONE connection, and the transaction is the\n// only thing that knows which. Both *pgxpool.Pool and pgx.Tx answer this shape, so the choice\n// is made once, here, rather than at each of the executors below.\ntype pgExecutor interface {\n\tQuery(ctx context.Context, sql string, arguments ...any) (pgx.Rows, error)\n\tQueryRow(ctx context.Context, sql string, arguments ...any) pgx.Row\n\tExec(ctx context.Context, sql string, arguments ...any) (pgconn.CommandTag, error)\n}\n\nfunc (db *PostgresDB) executor() pgExecutor {\n\tif transaction := currentTransaction(); transaction != nil {\n\t\treturn transaction\n\t}\n\treturn db.pool\n}\n\n// \226\148\128\226\148\128 The lease \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// Every statement runs under ONE bound, the pool lease: the time a request may wait for a\n// connection from the pool plus the time its statement may then take. `TESL_PG_POOL_LEASE_TIMEOUT_MS`\n// sets it (default 10 s), as the spec documents; the bootstrap and the transaction's BEGIN and\n// COMMIT use the same bound, so there is one knob rather than a scattering of literals.\n//\n// When the bound is exceeded the request is answered 503 rather than 500. A saturated pool is\n// not a broken server: it is a full one, and `503` with \"try again\" is what tells a client (and\n// a load balancer) to do exactly that, where a 500 tells it to give up. `pgFailure` is where a\n// driver error becomes one or the other.\n\nconst defaultPgLeaseTimeout = 10 * time.Second\n\n// pgLeaseTimeout reads the knob on every call rather than once, because it is cheap and a test\n// that sets the environment must not be answered from a cache made by an earlier test. A value\n// that is not a positive number is refused loudly: silently running with the default would hide\n// a misspelled deployment setting until the first saturation.\nfunc pgLeaseTimeout() time.Duration {\n\ttext := strings.TrimSpace(os.Getenv(\"TESL_PG_POOL_LEASE_TIMEOUT_MS\"))\n\tif text == \"\" {\n\t\treturn defaultPgLeaseTimeout\n\t}\n\tparsed, err := strconv.ParseInt(text, 10, 64)\n\tif err != nil || parsed < 1 {\n\t\tpanic(\"database: TESL_PG_POOL_LEASE_TIMEOUT_MS must be a positive number of milliseconds, not \" +\n\t\t\tstrconv.Quote(text))\n\t}\n\treturn time.Duration(parsed) * time.Millisecond\n}\n\n// The rejection a lease that ran out becomes: `callHandler` maps a RequestRejection to the\n// response it names, so a saturated pool answers 503 instead of the generic 500 any other trap\n// becomes. The message is deliberately generic \226\128\148 it reaches the client.\nvar pgDatabaseBusy = RequestRejection{Status: 503, Message: \"database busy, try again\"}\n\n// pgFailure is the panic value for a driver error: the lease running out (the pool never handed\n// over a connection in time, or the statement did not finish in time) is the 503 rejection, and\n// anything else keeps the driver's own text under `prefix`, for the operator log.\nfunc pgFailure(prefix string, err error) any {\n\tif errors.Is(err, context.DeadlineExceeded) || pgconn.Timeout(err) {\n\t\treturn pgDatabaseBusy\n\t}\n\treturn prefix + \": \" + err.Error()\n}\n\n// PgQuery runs a select and scans every row through `scan`.\nfunc PgQuery[Row any](db *PostgresDB, statement string, arguments []any,\n\tscan func(pgx.CollectableRow) (Row, error)) []Row {\n\tctx, cancel := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\tdefer cancel()\n\trows, err := db.executor().Query(ctx, statement, arguments...)\n\tif err != nil {\n\t\tpanic(pgFailure(\"database\", err))\n\t}\n\tcollected, err := pgx.CollectRows(rows, scan)\n\tif err != nil {\n\t\tpanic(pgFailure(\"database\", err))\n\t}\n\treturn collected\n}\n\nfunc PgQueryPlan[Row any](db *PostgresDB, plan PgPlan,\n\tscan func(pgx.CollectableRow) (Row, error)) []Row {\n\trowCount := 0\n\tif plan.Capture != nil {\n\t\tdefer func() { plan.Capture(rowCount) }()\n\t}\n\trows := PgQuery(db, plan.SQL, plan.arguments(), scan)\n\trowCount = len(rows)\n\treturn rows\n}\n\n// PgQueryOne is `selectOne`: the first row, or Nothing. `limit 1` is the emitter's job, so this\n// only decides what \"no row\" means.\nfunc PgQueryOne[Row any](db *PostgresDB, statement string, arguments []any,\n\tscan func(pgx.CollectableRow) (Row, error)) Maybe[Row] {\n\trows := PgQuery(db, statement, arguments, scan)\n\tif len(rows) == 0 {\n\t\treturn Nothing[Row]()\n\t}\n\treturn Something(rows[0])\n}\n\nfunc PgQueryOnePlan[Row any](db *PostgresDB, plan PgPlan,\n\tscan func(pgx.CollectableRow) (Row, error)) Maybe[Row] {\n\trows := PgQueryPlan(db, plan, scan)\n\tif len(rows) == 0 {\n\t\treturn Nothing[Row]()\n\t}\n\treturn Something(rows[0])\n}\n\n// PgExec runs a statement that answers no rows, and reports how many it touched.\nfunc PgExec(db *PostgresDB, statement string, arguments []any) int64 {\n\tctx, cancel := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\tdefer cancel()\n\ttag, err := db.executor().Exec(ctx, statement, arguments...)\n\tif err != nil {\n\t\tpanic(pgFailure(\"database\", err))\n\t}\n\treturn tag.RowsAffected()\n}\n\nfunc PgExecPlan(db *PostgresDB, plan PgPlan) int64 {\n\trowCount := 0\n\tif plan.Capture != nil {\n\t\tdefer func() { plan.Capture(rowCount) }()\n\t}\n\trows := PgExec(db, plan.SQL, plan.arguments())\n\trowCount = int(rows)\n\treturn rows\n}\n\n// PgCount is `count \226\128\166 from \226\128\166`: one row, one number.\nfunc PgCount(db *PostgresDB, statement string, arguments []any) Int {\n\tctx, cancel := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\tdefer cancel()\n\trow := db.executor().QueryRow(ctx, statement, arguments...)\n\tvar counted int64\n\tif err := row.Scan(&counted); err != nil {\n\t\tpanic(pgFailure(\"database\", err))\n\t}\n\treturn FromInt64(counted)\n}\n\nfunc PgCountPlan(db *PostgresDB, plan PgPlan) Int {\n\trowCount := 0\n\tif plan.Capture != nil {\n\t\tdefer func() { plan.Capture(rowCount) }()\n\t}\n\tcount := PgCount(db, plan.SQL, plan.arguments())\n\tif value, ok := count.Int64(); ok {\n\t\trowCount = int(value)\n\t}\n\treturn count\n}\n\n// PgScalar is the aggregate executor: one row, one value, scanned by the emitter's own reader\n// because the column's type is the entity's rather than something this file can know.\nfunc PgScalar[Value any](db *PostgresDB, statement string, arguments []any,\n\tscan func(pgx.Row) (Value, error)) Value {\n\tctx, cancel := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\tdefer cancel()\n\tvalue, err := scan(db.executor().QueryRow(ctx, statement, arguments...))\n\tif err != nil {\n\t\tpanic(pgFailure(\"database\", err))\n\t}\n\treturn value\n}\n\nfunc PgScalarPlan[Value any](db *PostgresDB, plan PgPlan,\n\tscan func(pgx.Row) (Value, error)) Value {\n\trowCount := 0\n\tif plan.Capture != nil {\n\t\tdefer func() { plan.Capture(rowCount) }()\n\t}\n\tvalue := PgScalar(db, plan.SQL, plan.arguments(), scan)\n\trowCount = 1\n\treturn value\n}\n\n// PgSumMoney is `selectSum` over a Money column. The statement answers the total, the number of\n// DISTINCT currencies and one witness code in a single row, because the two refusals need those\n// facts and a second query could see a different set of rows than the sum did.\n//\n// A stored code that is not an ISO 4217 currency is data corruption or a schema written by an\n// incompatible build, and it traps rather than decoding into a half-formed Money \226\128\148 Racket's\n// `money-stored-currency` takes the same line.\nfunc PgSumMoney(db *PostgresDB, statement string, arguments []any, entity, field string) Money {\n\tctx, cancel := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\tdefer cancel()\n\tvar total pgtype.Numeric\n\tvar distinct int64\n\tvar witness *string\n\tif err := db.executor().QueryRow(ctx, statement, arguments...).\n\t\tScan(&total, &distinct, &witness); err != nil {\n\t\tpanic(pgFailure(\"database\", err))\n\t}\n\tcurrency := Currency{}\n\tif witness != nil {\n\t\tknown := CurrencyFromCode(*witness)\n\t\tif !known.IsSomething() {\n\t\t\tpanic(\"field \" + field + \" on entity \" + entity + \": stored currency code \" + *witness +\n\t\t\t\t\" is not a known ISO 4217 currency \226\128\148 the column holds corrupt data or was\" +\n\t\t\t\t\" written by an incompatible schema\")\n\t\t}\n\t\tcurrency = known.SomethingValue\n\t}\n\t// A SUM over no rows is NULL, and the row set being empty is what `MoneySumResult` refuses\n\t// (by the distinct count); reading the NULL as zero here lets it say so rather than trapping\n\t// on the column first.\n\tminorUnits := FromInt64(0)\n\tif total.Valid {\n\t\tminorUnits = PgIntOf(total)\n\t}\n\treturn MoneySumResult(entity, field, minorUnits, currency, int(distinct))\n}\n\nfunc PgSumMoneyPlan(db *PostgresDB, plan PgPlan, entity, field string) Money {\n\trowCount := 0\n\tif plan.Capture != nil {\n\t\tdefer func() { plan.Capture(rowCount) }()\n\t}\n\tvalue := PgSumMoney(db, plan.SQL, plan.arguments(), entity, field)\n\trowCount = 1\n\treturn value\n}\n\n// PgTruncate empties a table, for a test block that starts from an empty store. It is the\n// Postgres counterpart of `TableTruncate`, and it exists for the same reason: one test block's\n// rows must not be another's.\nfunc PgTruncate(db *PostgresDB, table string) {\n\tctx, cancel := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\tdefer cancel()\n\tif _, err := db.executor().Exec(ctx, \"truncate table \"+db.QualifiedTable(table)); err != nil {\n\t\t// A table that does not exist yet is not an error here: a test may run before anything\n\t\t// created it, and the bootstrap is what creates it.\n\t\tif !strings.Contains(err.Error(), \"does not exist\") {\n\t\t\tpanic(\"database: cannot truncate \" + table + \": \" + err.Error())\n\t\t}\n\t}\n}\n\n// \226\148\128\226\148\128 Values \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// An `Int` is arbitrary precision on both sides \226\128\148 Tesl's integers are unbounded and the column is\n// NUMERIC \226\128\148 so it travels as a pgtype.Numeric rather than through int64, which would silently\n// fail exactly where the arbitrary precision matters.\n\n// PgInt binds an Int as a NUMERIC parameter. It goes through the decimal TEXT of the value\n// rather than through int64, because a Tesl Int is unbounded and int64 is exactly where that\n// stops being true.\nfunc PgInt(value Int) pgtype.Numeric {\n\tparsed, ok := new(big.Int).SetString(value.String(), 10)\n\tif !ok {\n\t\tpanic(\"database: \" + value.String() + \" is not an integer\")\n\t}\n\treturn pgtype.Numeric{Int: parsed, Exp: 0, Valid: true}\n}\n\n// PgIntOf reads a NUMERIC (or any integer column) back into an Int \226\128\148 a NON-NULL one.\n//\n// A NULL traps. The emitted scanner reads a `Maybe Int` column into a `*pgtype.Numeric` and\n// hands only a non-nil carrier here (`MaybeOfPointer` skips the decode on NULL), a `selectSum`\n// is `coalesce(sum(\226\128\166), 0)`, and `selectMax`/`selectMin` go through the same pointer carrier \226\128\148 so\n// the only way a NULL reaches this function is a column Tesl typed as plain `Int` holding one:\n// schema drift, or a row another tool wrote. Answering 0 there fabricated a balance; TEXT\n// columns already trapped on the same shape, and the two must agree.\nfunc PgIntOf(value pgtype.Numeric) Int {\n\tif !value.Valid || value.Int == nil {\n\t\tpanic(\"database: a NUMERIC column holds NULL where Tesl expects an Int; \" +\n\t\t\t\"declare the field as `Maybe Int` if the column may be NULL\")\n\t}\n\tif value.Exp == 0 {\n\t\treturn fromBig(new(big.Int).Set(value.Int))\n\t}\n\t// A scale the column carries but a Tesl Int cannot: the value is not an integer, and\n\t// answering a truncated one would be a silent wrong answer.\n\tif value.Exp > 0 {\n\t\tscaled := new(big.Int).Set(value.Int)\n\t\tten := big.NewInt(10)\n\t\tfor range int(value.Exp) {\n\t\t\tscaled.Mul(scaled, ten)\n\t\t}\n\t\treturn fromBig(scaled)\n\t}\n\tpanic(\"database: a NUMERIC column holds a fractional value where Tesl expects an Int\")\n}\n\n// PgNull binds a `Maybe X` column: Nothing is SQL NULL, Something is the bound value. The\n// binding of the inner value is the caller's, because only the emitter knows the column's type.\nfunc PgNull[T any](value Maybe[T], bind func(T) any) any {\n\tif !value.IsSomething() {\n\t\treturn nil\n\t}\n\treturn bind(value.SomethingValue)\n}\n\n// MaybeOfPointer reads a nullable column back: a NULL is Nothing, and anything else is decoded\n// by the caller's reader. The reader is a thunk rather than a value so the decode is not run on\n// the NULL \226\128\148 dereferencing the carrier there would panic.\nfunc MaybeOfPointer[Carrier any, Value any](carrier *Carrier, decode func() Value) Maybe[Value] {\n\tif carrier == nil {\n\t\treturn Nothing[Value]()\n\t}\n\treturn Something(decode())\n}\n\n// PgBigint binds a PosixMillis-shaped value, whose column is BIGINT.\nfunc PgBigint(value Int) int64 {\n\texact, ok := value.Int64()\n\tif !ok {\n\t\tpanic(\"database: \" + value.String() + \" does not fit a BIGINT column\")\n\t}\n\treturn exact\n}\n");
  ("units.go", "package teslrt\n\nimport (\n\t\"math\"\n\t\"math/big\"\n)\n\n// `Tesl.Units` \226\128\148 dimensioned quantities.\n//\n// A quantity ERASES to a plain float64: the DIMENSION lives in the compiler's type layer, which\n// is where `meters / seconds = meters per second` is checked and where adding a length to a mass\n// is rejected. Nothing about that survives to run time, so everything here is ordinary\n// arithmetic \226\128\148 the value is already in SI-canonical units by the time it gets here.\n//\n// The per-unit conversions live in units_data.go, generated from `tesl/units.rkt` so the factors\n// have ONE source. What is written by hand is what is not a factor: the affine temperature\n// scales, the polymorphic operations, and the non-zero check.\n\n// Temperature is AFFINE, not a scale factor: 0 \194\176C is 273.15 K, so a Celsius value cannot be\n// converted by multiplying. The resulting quantity is absolute kelvin.\n//\n// (Adding two absolute temperatures type-checks \226\128\148 same dimension \226\128\148 and is rarely meaningful;\n// the manual says so, and the type system deliberately does not try to encode the difference\n// between an absolute temperature and a temperature INTERVAL.)\nfunc TemperatureKelvin(value float64) float64 { return value }\n\nfunc TemperatureCelsius(value float64) float64 { return value + 273.15 }\n\nfunc TemperatureFahrenheit(value float64) float64 {\n\treturn (value-32.0)*(5.0/9.0) + 273.15\n}\n\nfunc TemperatureInKelvin(quantity float64) float64 { return quantity }\n\nfunc TemperatureInCelsius(quantity float64) float64 { return quantity - 273.15 }\n\nfunc TemperatureInFahrenheit(quantity float64) float64 {\n\treturn (quantity-273.15)*1.8 + 32.0\n}\n\n// The polymorphic dimension operations. Each application site is dimension-checked by the\n// compiler \226\128\148 `Units.mul` on a length and a length is an area there \226\128\148 so at run time they are\n// the obvious float operations.\n\nfunc UnitsMul(left, right float64) float64 { return left * right }\n\nfunc UnitsDiv(left, right float64) float64 { return left / right }\n\nfunc UnitsSquare(value float64) float64 { return value * value }\n\nfunc UnitsSqrt(value float64) float64 { return math.Sqrt(value) }\n\nfunc UnitsAbs(value float64) float64 { return math.Abs(value) }\n\nfunc UnitsNegate(value float64) float64 { return -value }\n\nfunc UnitsMin(left, right float64) float64 { return math.Min(left, right) }\n\nfunc UnitsMax(left, right float64) float64 { return math.Max(left, right) }\n\nfunc UnitsSum(values []float64) float64 {\n\ttotal := 0.0\n\tfor _, value := range values {\n\t\ttotal += value\n\t}\n\treturn total\n}\n\n// DurationToMillis and DurationFromMillis bridge a typed Duration and the exact-Int\n// milliseconds `PosixMillis` arithmetic speaks. `toMillis` rounds HALF-EVEN on the exact\n// rational \226\128\148 the Money stance, and the reason a duration that lands exactly between two\n// milliseconds does not drift upward over a long series.\n//\n// The conversion goes through the float's BINARY value, not its shortest decimal \226\128\148 the\n// opposite of what the Money paths do, and deliberately so: `tesl/units.rkt` writes\n// `inexact->exact` here while `tesl/money.rkt` exactifies decimal-faithfully. The difference\n// is observable, so it is matched rather than tidied: 0.0025 s is a hair ABOVE 2.5 ms in\n// binary, so it rounds to 3, where the decimal reading would tie and round to the even 2.\nfunc DurationToMillis(quantity float64) Int {\n\texact := new(big.Rat).SetFloat64(quantity)\n\tif exact == nil {\n\t\t// NaN and the infinities have no exact value to round; a duration that is one of\n\t\t// them is a bug upstream, and answering some millisecond count would hide it.\n\t\tpanic(\"Duration.toMillis: expected a finite duration\")\n\t}\n\tscaled := new(big.Rat).Mul(exact, big.NewRat(1000, 1))\n\treturn fromBig(roundHalfEven(scaled))\n}\n\nfunc DurationFromMillis(millis Int) float64 {\n\tvalue, _ := new(big.Rat).SetInt(millis.bigInt()).Float64()\n\treturn value / 1000.0\n}\n\n// UnitsRequireNonZero is the divisor check: quantities erase to floats, so the SAME\n// `FloatNonZero` predicate that guards float division guards quantity division \226\128\148 `d / t`\n// demands a non-zero divisor proof exactly like every other `/`.\n//\n// The 422 is Racket's: a zero divisor is a value the caller sent, not a broken server.\nfunc UnitsRequireNonZero(quantity float64) Check[float64] {\n\tif quantity == 0 {\n\t\treturn Reject[float64](422, \"expected a non-zero quantity\")\n\t}\n\treturn Accept(quantity)\n}\n");
  ("units_data.go", "package teslrt\n\n// Generated by scripts/gen-go-units.py from this Go conversion table.\n// DO NOT EDIT BY HAND \226\128\148 regenerate and commit when a conversion factor changes.\n//\n// A dimensioned quantity ERASES to a plain float64: the dimension lives in the\n// compiler's type layer, so every function here is ordinary arithmetic. A CONSTRUCTOR\n// converts a value in the named unit to the SI-canonical magnitude (meters, kilograms,\n// seconds, \226\128\166); an ACCESSOR converts back.\n\nfunc LengthMeters(value float64) float64                            { return value * 1.0 }\nfunc LengthKilometers(value float64) float64                        { return value * 1000.0 }\nfunc LengthCentimeters(value float64) float64                       { return value * 0.01 }\nfunc LengthMillimeters(value float64) float64                       { return value * 0.001 }\nfunc LengthMiles(value float64) float64                             { return value * 1609.344 }\nfunc LengthFeet(value float64) float64                              { return value * 0.3048 }\nfunc LengthInches(value float64) float64                            { return value * 0.0254 }\nfunc LengthYards(value float64) float64                             { return value * 0.9144 }\nfunc LengthNauticalMiles(value float64) float64                     { return value * 1852.0 }\nfunc LengthInMeters(quantity float64) float64                       { return quantity / 1.0 }\nfunc LengthInKilometers(quantity float64) float64                   { return quantity / 1000.0 }\nfunc LengthInCentimeters(quantity float64) float64                  { return quantity / 0.01 }\nfunc LengthInMillimeters(quantity float64) float64                  { return quantity / 0.001 }\nfunc LengthInMiles(quantity float64) float64                        { return quantity / 1609.344 }\nfunc LengthInFeet(quantity float64) float64                         { return quantity / 0.3048 }\nfunc LengthInInches(quantity float64) float64                       { return quantity / 0.0254 }\nfunc LengthInYards(quantity float64) float64                        { return quantity / 0.9144 }\nfunc LengthInNauticalMiles(quantity float64) float64                { return quantity / 1852.0 }\nfunc MassKilograms(value float64) float64                           { return value * 1.0 }\nfunc MassGrams(value float64) float64                               { return value * 0.001 }\nfunc MassMilligrams(value float64) float64                          { return value * 0.000001 }\nfunc MassTonnes(value float64) float64                              { return value * 1000.0 }\nfunc MassPounds(value float64) float64                              { return value * 0.45359237 }\nfunc MassOunces(value float64) float64                              { return value * 0.028349523125 }\nfunc MassInKilograms(quantity float64) float64                      { return quantity / 1.0 }\nfunc MassInGrams(quantity float64) float64                          { return quantity / 0.001 }\nfunc MassInMilligrams(quantity float64) float64                     { return quantity / 0.000001 }\nfunc MassInTonnes(quantity float64) float64                         { return quantity / 1000.0 }\nfunc MassInPounds(quantity float64) float64                         { return quantity / 0.45359237 }\nfunc MassInOunces(quantity float64) float64                         { return quantity / 0.028349523125 }\nfunc DurationSeconds(value float64) float64                         { return value * 1.0 }\nfunc DurationMilliseconds(value float64) float64                    { return value * 0.001 }\nfunc DurationMinutes(value float64) float64                         { return value * 60.0 }\nfunc DurationHours(value float64) float64                           { return value * 3600.0 }\nfunc DurationDays(value float64) float64                            { return value * 86400.0 }\nfunc DurationInSeconds(quantity float64) float64                    { return quantity / 1.0 }\nfunc DurationInMilliseconds(quantity float64) float64               { return quantity / 0.001 }\nfunc DurationInMinutes(quantity float64) float64                    { return quantity / 60.0 }\nfunc DurationInHours(quantity float64) float64                      { return quantity / 3600.0 }\nfunc DurationInDays(quantity float64) float64                       { return quantity / 86400.0 }\nfunc SpeedMetersPerSecond(value float64) float64                    { return value * 1.0 }\nfunc SpeedKilometersPerHour(value float64) float64                  { return value * 0.2777777777777778 }\nfunc SpeedMilesPerHour(value float64) float64                       { return value * 0.44704 }\nfunc SpeedKnots(value float64) float64                              { return value * 0.5144444444444445 }\nfunc SpeedInMetersPerSecond(quantity float64) float64               { return quantity / 1.0 }\nfunc SpeedInKilometersPerHour(quantity float64) float64             { return quantity / 0.2777777777777778 }\nfunc SpeedInMilesPerHour(quantity float64) float64                  { return quantity / 0.44704 }\nfunc SpeedInKnots(quantity float64) float64                         { return quantity / 0.5144444444444445 }\nfunc AccelerationMetersPerSecondSquared(value float64) float64      { return value * 1.0 }\nfunc AccelerationInMetersPerSecondSquared(quantity float64) float64 { return quantity / 1.0 }\nfunc AreaSquareMeters(value float64) float64                        { return value * 1.0 }\nfunc AreaSquareKilometers(value float64) float64                    { return value * 1000000.0 }\nfunc AreaHectares(value float64) float64                            { return value * 10000.0 }\nfunc AreaSquareFeet(value float64) float64                          { return value * 0.09290304 }\nfunc AreaAcres(value float64) float64                               { return value * 4046.8564224 }\nfunc AreaInSquareMeters(quantity float64) float64                   { return quantity / 1.0 }\nfunc AreaInSquareKilometers(quantity float64) float64               { return quantity / 1000000.0 }\nfunc AreaInHectares(quantity float64) float64                       { return quantity / 10000.0 }\nfunc AreaInSquareFeet(quantity float64) float64                     { return quantity / 0.09290304 }\nfunc AreaInAcres(quantity float64) float64                          { return quantity / 4046.8564224 }\nfunc VolumeCubicMeters(value float64) float64                       { return value * 1.0 }\nfunc VolumeLiters(value float64) float64                            { return value * 0.001 }\nfunc VolumeMilliliters(value float64) float64                       { return value * 0.000001 }\nfunc VolumeGallons(value float64) float64                           { return value * 0.003785411784 }\nfunc VolumeInCubicMeters(quantity float64) float64                  { return quantity / 1.0 }\nfunc VolumeInLiters(quantity float64) float64                       { return quantity / 0.001 }\nfunc VolumeInMilliliters(quantity float64) float64                  { return quantity / 0.000001 }\nfunc VolumeInGallons(quantity float64) float64                      { return quantity / 0.003785411784 }\nfunc ForceNewtons(value float64) float64                            { return value * 1.0 }\nfunc ForceInNewtons(quantity float64) float64                       { return quantity / 1.0 }\nfunc EnergyJoules(value float64) float64                            { return value * 1.0 }\nfunc EnergyKilojoules(value float64) float64                        { return value * 1000.0 }\nfunc EnergyKilowattHours(value float64) float64                     { return value * 3600000.0 }\nfunc EnergyCalories(value float64) float64                          { return value * 4.184 }\nfunc EnergyInJoules(quantity float64) float64                       { return quantity / 1.0 }\nfunc EnergyInKilojoules(quantity float64) float64                   { return quantity / 1000.0 }\nfunc EnergyInKilowattHours(quantity float64) float64                { return quantity / 3600000.0 }\nfunc EnergyInCalories(quantity float64) float64                     { return quantity / 4.184 }\nfunc PowerWatts(value float64) float64                              { return value * 1.0 }\nfunc PowerKilowatts(value float64) float64                          { return value * 1000.0 }\nfunc PowerHorsepower(value float64) float64                         { return value * 745.6998715822702 }\nfunc PowerInWatts(quantity float64) float64                         { return quantity / 1.0 }\nfunc PowerInKilowatts(quantity float64) float64                     { return quantity / 1000.0 }\nfunc PowerInHorsepower(quantity float64) float64                    { return quantity / 745.6998715822702 }\nfunc FrequencyHertz(value float64) float64                          { return value * 1.0 }\nfunc FrequencyKilohertz(value float64) float64                      { return value * 1000.0 }\nfunc FrequencyInHertz(quantity float64) float64                     { return quantity / 1.0 }\nfunc FrequencyInKilohertz(quantity float64) float64                 { return quantity / 1000.0 }\nfunc PressurePascals(value float64) float64                         { return value * 1.0 }\nfunc PressureKilopascals(value float64) float64                     { return value * 1000.0 }\nfunc PressureBar(value float64) float64                             { return value * 100000.0 }\nfunc PressureInPascals(quantity float64) float64                    { return quantity / 1.0 }\nfunc PressureInKilopascals(quantity float64) float64                { return quantity / 1000.0 }\nfunc PressureInBar(quantity float64) float64                        { return quantity / 100000.0 }\n");
  ("password.go", "package teslrt\n\nimport (\n\t\"crypto/rand\"\n\t\"crypto/subtle\"\n\t\"encoding/base64\"\n\t\"fmt\"\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n\n\t\"golang.org/x/crypto/argon2\"\n)\n\n// Password storage: Argon2id, in the SAME encoding the Racket runtime writes.\n//\n// This is the one place the emitted runtime takes a dependency outside Go's standard library\n// (`golang.org/x/crypto/argon2`), and it is a deliberate, approved decision rather than a\n// convenience: Racket hashes with libsodium's Argon2id, and the two alternatives are both\n// worse. Substituting stdlib PBKDF2 would mint hashes the Racket side cannot verify, so a\n// shared database becomes a silent lockout on migration; hand-writing Argon2id would put\n// hand-rolled cryptography in the runtime. The dependency ships ONLY with this file, which is\n// ONLY emitted for a program that stores passwords, so nothing else carries it.\n//\n// The encoding is the PHC string libsodium's `crypto_pwhash_str` produces at its INTERACTIVE\n// parameters:\n//\n//\t$argon2id$v=19$m=65536,t=2,p=1$<salt>$<hash>\n//\n// with standard-alphabet base64 and no padding, a 16-byte salt and a 32-byte tag. A hash\n// written by either backend therefore verifies on both \226\128\148 which is the whole point, and what a\n// test asserts against a real libsodium string.\nconst (\n\targonMemoryKiB = 64 * 1024 // libsodium crypto_pwhash_MEMLIMIT_INTERACTIVE, in KiB\n\targonTime      = 2         // libsodium crypto_pwhash_OPSLIMIT_INTERACTIVE\n\targonThreads   = 1\n\targonSaltBytes = 16\n\targonKeyBytes  = 32\n\n\t// A password longer than this is refused rather than hashed: hashing is deliberately\n\t// expensive, so an unbounded input is a denial-of-service amplifier. Same limit as the\n\t// Racket runtime's.\n\tmaxPasswordBytes = 1024\n\n\t// The CEILING on what a STORED hash may ask this process to spend. The PHC string's own\n\t// parameters drive `verifyArgon2id`, and the hash column is data: a poisoned row saying\n\t// `m=4194304` would make the next login attempt against it a 4 GiB allocation. The\n\t// ceilings are far above anything this runtime mints (64 MiB, t=2, p=1) and above\n\t// libsodium's SENSITIVE preset (1 GiB, t=4), so every legitimate hash parses; a row above\n\t// them is treated exactly like a foreign encoding \226\128\148 does not verify, needs re-minting.\n\targonMaxMemoryKiB = 1024 * 1024 // 1 GiB\n\targonMaxTime      = 64\n\targonMaxThreads   = 16\n)\n\n// PasswordHash is opaque to Tesl: it holds the PHC string, and a program can store it, verify\n// against it, or ask whether it needs re-minting \226\128\148 never read it apart.\ntype PasswordHash struct {\n\tValue string\n}\n\nfunc requirePasswordLength(who string, plaintext SecretString) {\n\tif len(plaintext.Reveal()) > maxPasswordBytes {\n\t\t// A rejection at the request boundary, not a crash: the input came from a client, and\n\t\t// inside a handler this answers 400 the way any other check rejection does.\n\t\tpanic(RequestRejection{\n\t\t\tStatus: 400,\n\t\t\tMessage: fmt.Sprintf(\n\t\t\t\t\"%s: password is too long: %d bytes, maximum is %d. Reject over-long input at \"+\n\t\t\t\t\t\"the request boundary; hashing it is a denial-of-service amplifier.\",\n\t\t\t\twho, len(plaintext.Reveal()), maxPasswordBytes),\n\t\t})\n\t}\n}\n\n// HashPassword is `Crypto.hashPassword`: a fresh random salt, then Argon2id at the interactive\n// parameters. The `::: HashFor plaintext` half of its Tesl type is compile-time only \226\128\148 the fact\n// is about the argument, and proofs erase \226\128\148 so what it buys is that storing the WRONG\n// password's hash does not compile.\n//\n// The plaintext arrives as a SecretString so that the emitted CALL SITE never handles it as an\n// ordinary string: a `secret Password = String` hands over its payload, and a plain String is\n// wrapped on the way in. The plaintext therefore exists only inside this file.\nfunc HashPassword(plaintext SecretString) PasswordHash {\n\trequirePasswordLength(\"Crypto.hashPassword\", plaintext)\n\tsalt := make([]byte, argonSaltBytes)\n\tif _, err := rand.Read(salt); err != nil {\n\t\tpanic(\"Crypto.hashPassword: no source of randomness: \" + err.Error())\n\t}\n\treturn PasswordHash{Value: encodeArgon2id(salt,\n\t\targon2.IDKey([]byte(plaintext.Reveal()), salt, argonTime, argonMemoryKiB, argonThreads,\n\t\t\targonKeyBytes))}\n}\n\nfunc encodeArgon2id(salt, key []byte) string {\n\traw := base64.RawStdEncoding\n\treturn fmt.Sprintf(\"$argon2id$v=%d$m=%d,t=%d,p=%d$%s$%s\",\n\t\targon2.Version, argonMemoryKiB, argonTime, argonThreads,\n\t\traw.EncodeToString(salt), raw.EncodeToString(key))\n}\n\n// argon2Params is what a stored PHC string says it was minted with.\ntype argon2Params struct {\n\tmemoryKiB uint32\n\ttime      uint32\n\tthreads   uint8\n\tsalt      []byte\n\tkey       []byte\n}\n\n// parseArgon2id reads a stored hash. Anything that is not an Argon2id v19 PHC string \226\128\148 a\n// foreign hash, a scheme that has been dropped, truncated text \226\128\148 fails to parse, and every\n// caller treats that as \"does not verify\" and \"needs re-minting\".\nfunc parseArgon2id(stored string) (argon2Params, bool) {\n\tfields := strings.Split(stored, \"$\")\n\t// \"\", \"argon2id\", \"v=19\", \"m=\226\128\166,t=\226\128\166,p=\226\128\166\", salt, key\n\tif len(fields) != 6 || fields[0] != \"\" || fields[1] != \"argon2id\" {\n\t\treturn argon2Params{}, false\n\t}\n\tif fields[2] != \"v=\"+strconv.Itoa(argon2.Version) {\n\t\treturn argon2Params{}, false\n\t}\n\tvar memory, time uint64\n\tvar threads uint64\n\tfor _, setting := range strings.Split(fields[3], \",\") {\n\t\tname, value, found := strings.Cut(setting, \"=\")\n\t\tif !found {\n\t\t\treturn argon2Params{}, false\n\t\t}\n\t\tparsed, err := strconv.ParseUint(value, 10, 32)\n\t\tif err != nil {\n\t\t\treturn argon2Params{}, false\n\t\t}\n\t\tswitch name {\n\t\tcase \"m\":\n\t\t\tmemory = parsed\n\t\tcase \"t\":\n\t\t\ttime = parsed\n\t\tcase \"p\":\n\t\t\tthreads = parsed\n\t\tdefault:\n\t\t\treturn argon2Params{}, false\n\t\t}\n\t}\n\tif memory == 0 || time == 0 || threads == 0 {\n\t\treturn argon2Params{}, false\n\t}\n\tif memory > argonMaxMemoryKiB || time > argonMaxTime || threads > argonMaxThreads {\n\t\treturn argon2Params{}, false\n\t}\n\traw := base64.RawStdEncoding\n\tsalt, saltErr := raw.DecodeString(fields[4])\n\tkey, keyErr := raw.DecodeString(fields[5])\n\tif saltErr != nil || keyErr != nil || len(salt) == 0 {\n\t\treturn argon2Params{}, false\n\t}\n\t// The tag length is FIXED at 32 bytes: that is what libsodium's `crypto_pwhash_str` writes,\n\t// and pinning it keeps the recomputation below free of a length taken from the stored string\n\t// (which would be an attacker-influenced integer conversion). A hash with any other tag\n\t// length is treated as unparseable \226\128\148 fail closed, and `needsRehash` says to re-mint it.\n\tif len(key) != argonKeyBytes {\n\t\treturn argon2Params{}, false\n\t}\n\treturn argon2Params{\n\t\tmemoryKiB: uint32(memory), time: uint32(time), threads: uint8(threads),\n\t\tsalt: salt, key: key,\n\t}, true\n}\n\nfunc verifyArgon2id(stored, candidate string) bool {\n\tparams, ok := parseArgon2id(stored)\n\tif !ok {\n\t\treturn false\n\t}\n\tcomputed := argon2.IDKey([]byte(candidate), params.salt, params.time, params.memoryKiB,\n\t\tparams.threads, argonKeyBytes)\n\treturn subtle.ConstantTimeCompare(computed, params.key) == 1\n}\n\n// timingEqualiser is a real hash of a random password at the CURRENT parameters, computed once\n// and reused. It exists so that verifying against a MISSING account costs the same as verifying\n// a wrong password \226\128\148 otherwise a login endpoint answers in microseconds for an unknown address\n// and in ~80ms for a known one, which enumerates the user table. Generated rather than\n// hardcoded so it cannot drift from the live parameters.\nvar (\n\ttimingEqualiserOnce sync.Once\n\ttimingEqualiserPHC  string\n)\n\nfunc timingEqualiser() string {\n\ttimingEqualiserOnce.Do(func() {\n\t\tfiller := make([]byte, 32)\n\t\tif _, err := rand.Read(filler); err != nil {\n\t\t\tpanic(\"Crypto.checkPassword: no source of randomness: \" + err.Error())\n\t\t}\n\t\ttimingEqualiserPHC = HashPassword(MakeSecret(string(filler))).Value\n\t})\n\treturn timingEqualiserPHC\n}\n\n// CheckPassword is `Crypto.checkPassword`. It takes a `Maybe PasswordHash` deliberately: a\n// missing account and a wrong password have to cost the same and answer the same, so `Nothing`\n// still performs a full verification \226\128\148 against the timing equaliser \226\128\148 and then fails with the\n// identical message. The caller does not have to know that this problem exists, which is the\n// point.\nfunc CheckPassword(stored Maybe[PasswordHash], candidate SecretString) Check[Maybe[PasswordHash]] {\n\trequirePasswordLength(\"Crypto.checkPassword\", candidate)\n\thash, present := stored.Value()\n\tphc := timingEqualiser()\n\tif present {\n\t\tphc = hash.Value\n\t}\n\tverified := verifyArgon2id(phc, candidate.Reveal())\n\tif !verified || !present {\n\t\treturn Reject[Maybe[PasswordHash]](401, \"invalid credentials\")\n\t}\n\treturn Accept(stored)\n}\n\n// NeedsRehash is `Crypto.needsRehash`: true when the stored hash was minted with weaker\n// parameters than the current ones, or in a format this runtime cannot parse at all (a foreign\n// hash, or one from a scheme that has been dropped) \226\128\148 in both cases the right move on the next\n// successful login is to re-mint, so both answer true.\n//\n// Tesl deliberately does NOT perform the rehash: a crypto function writing to the database\n// would be a hidden effect, and it is one explicit line in the application.\nfunc NeedsRehash(stored PasswordHash) bool {\n\tparams, ok := parseArgon2id(stored.Value)\n\tif !ok {\n\t\treturn true\n\t}\n\treturn params.memoryKiB < argonMemoryKiB || params.time < argonTime ||\n\t\tparams.threads != argonThreads\n}\n");
  ("pgpubsub.go", "package teslrt\n\nimport (\n\t\"context\"\n\t\"errors\"\n\t\"fmt\"\n\t\"os\"\n\tgoruntime \"runtime\"\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n\t\"time\"\n\n\t\"github.com/jackc/pgx/v5\"\n)\n\n// Cross-instance SSE pub/sub on PostgreSQL: `sseChannel C(key) = SseChannel { database: D \226\128\166 }`.\n//\n// A publish delivered only to the listeners of THIS process reaches a browser subscribed on\n// another replica never: with two instances behind a load balancer, half the events vanish.\n// The spec (\194\167 SSE channels) promises what this file implements \226\128\148 a `tesl_pubsub_outbox` table\n// created alongside the entity tables, events published inside `transaction { }` written to\n// it atomically and delivered after commit, and one PostgreSQL LISTEN connection per process\n// for the fan-out. The retired Racket runtime (`tesl/queue.rkt`) did the same, and its two\n// hard-won rules are kept: a NOTIFY carries the outbox ROW ID rather than the payload (every\n// instance SELECTs the same row, so nothing is lost to the 8000-byte NOTIFY limit), and a\n// periodic SWEEP re-reads the outbox so a lost notification or a reconnecting instance still\n// delivers everything.\n//\n// WHAT DIFFERS FROM RACKET, deliberately. Racket delivered the publisher's own event locally\n// after commit and marked the row so the LISTEN path would skip it; here the publisher's own\n// process receives its events through the SAME LISTEN path as every other instance. One path\n// instead of two means one ordering (the outbox's), no per-process \"already delivered\" set\n// that must stay consistent with the deferred-delivery list, and the rolled-back case falls\n// out for free: a row that never committed fires no NOTIFY and is visible to no sweep.\n//\n// WHERE THE FILE SHIPS. Only with a Postgres-backed program \226\128\148 it is the one place the SSE\n// channel meets `*Database` and pgx, and sse.go (always shipped) sees it only through the\n// `pubsubBackend` interface. A channel of a Memory-backed database never touches this file.\n//\n// COMMIT-ORDERED DISPATCH. The row id is allocated by INSERT, not commit, so it is never used\n// as a lifetime delivery cursor. A publisher takes one transaction-scoped advisory lock before\n// drawing dispatch_seq and holds it through commit. Publishers therefore commit in sequence\n// order. The delivery loop reads only that order; NOTIFY is a doorbell, never a delivery path.\n//\n// STARTUP BASELINE. A process does not replay old SSE events. PostgreSQL bootstrap upgrades all\n// visible rows from the former nullable-sequence format before a runtime captures max\n// (dispatch_seq). A legacy transaction that commits later remains NULL and the delivery loop\n// safely sequences it above the baseline under the same advisory lock.\n\nconst (\n\tpubsubNotifyChannel = \"tesl_pubsub\"\n\t// queueNotifyChannel carries the QUEUE NAME as payload: one channel for every queue on the\n\t// database, so the listener connection is shared, and the payload says whose doorbell to\n\t// ring.\n\tqueueNotifyChannel = \"tesl_queue\"\n\tpubsubOutboxTable  = \"tesl_pubsub_outbox\"\n\tpubsubDispatchSeq  = \"tesl_pubsub_dispatch_seq\"\n\t// pubsubSweepBatch bounds every dispatch and delivery query. A full batch yields and runs\n\t// again immediately, so memory and query work are bounded without throttling catch-up.\n\tpubsubSweepBatch = 500\n)\n\n// The intervals are variables so a test can shrink them; production never writes them.\nvar (\n\t// pubsubSweepInterval is how often the outbox is re-read for rows a notification missed.\n\tpubsubSweepInterval = 5 * time.Second\n\t// pubsubBindPollInterval is how often an idle backend checks whether its database has\n\t// been bound yet: the listener cannot start before `with database D`.\n\tpubsubBindPollInterval = 250 * time.Millisecond\n\t// The reconnect backoff after the LISTEN connection drops, doubling up to the maximum.\n\tpubsubReconnectMinBackoff = 200 * time.Millisecond\n\tpubsubReconnectMaxBackoff = 5 * time.Second\n\t// pubsubOutboxRetention is how long a delivered row stays before a sweep prunes it.\n\tpubsubOutboxRetention = time.Hour\n\tpubsubPruneInterval   = time.Minute\n)\n\n// pgPubsub is one process's pub/sub state for one `Database` declaration: the channels\n// declared on it and its single ordered LISTEN/delivery goroutine.\ntype pgPubsub struct {\n\tdatabase *Database\n\n\tmutex sync.Mutex\n\t// channels by declared NAME. A name normally has one channel; a test standing two\n\t// channels in for two instances registers two, and both receive.\n\tchannels map[string][]*SseChannel\n\t// queues by declared name, woken on a `tesl_queue` notification naming them.\n\tqueues map[string][]*Queue\n\t// ready is set once the outbox table exists and the dispatch baseline is captured.\n\tready bool\n\t// dispatchCursor is the highest commit-ordered dispatch sequence this process delivered.\n\tdispatchCursor int64\n\t// deliveryMutex keeps manual/test catch-up calls serialized with the listener. Production\n\t// has only the listener path, but making the invariant local prevents future double delivery.\n\tdeliveryMutex sync.Mutex\n\t// listener is the live LISTEN connection, or nil between connections.\n\tlistener *pgx.Conn\n\n\tctx    context.Context\n\tcancel context.CancelFunc\n\tdone   chan struct{}\n}\n\n// pgPubsubs is the per-database registry: one runtime per `Database` value, created by the\n// first `NewSseChannelOn` naming it.\nvar pgPubsubs sync.Map // *Database -> *pgPubsub\n\n// NewSseChannelOn is what an `sseChannel` declaration with `database: D` emits, where\n// `NewSseChannel` is what a Memory-backed one emits. The channel is an ordinary SseChannel\n// with the database's pub/sub runtime attached, and registered with that runtime under its\n// name so an event arriving from another instance finds it.\nfunc NewSseChannelOn(database *Database, name string) *SseChannel {\n\tchannel := NewSseChannel(name)\n\truntime := pubsubFor(database)\n\truntime.mutex.Lock()\n\truntime.channels[name] = append(runtime.channels[name], channel)\n\truntime.mutex.Unlock()\n\tchannel.backend = runtime\n\treturn channel\n}\n\n// registerQueue hands a durable queue's doorbell to the database's listener.\nfunc (runtime *pgPubsub) registerQueue(queue *Queue) {\n\truntime.mutex.Lock()\n\truntime.queues[queue.name] = append(runtime.queues[queue.name], queue)\n\truntime.mutex.Unlock()\n}\n\n// wakeQueues rings every registered queue named by a `tesl_queue` notification.\nfunc (runtime *pgPubsub) wakeQueues(name string) {\n\truntime.mutex.Lock()\n\tqueues := append([]*Queue(nil), runtime.queues[name]...)\n\truntime.mutex.Unlock()\n\tfor _, queue := range queues {\n\t\tqueue.Wake()\n\t}\n}\n\nfunc pubsubFor(database *Database) *pgPubsub {\n\tif existing, found := pgPubsubs.Load(database); found {\n\t\tif runtime, ok := existing.(*pgPubsub); ok {\n\t\t\treturn runtime\n\t\t}\n\t}\n\tctx, cancel := context.WithCancel(context.Background())\n\tcreated := &pgPubsub{\n\t\tdatabase: database,\n\t\tchannels: map[string][]*SseChannel{},\n\t\tqueues:   map[string][]*Queue{},\n\t\tctx:      ctx,\n\t\tcancel:   cancel,\n\t\tdone:     make(chan struct{}),\n\t}\n\tactual, loaded := pgPubsubs.LoadOrStore(database, created)\n\tif loaded {\n\t\tcancel()\n\t\tif runtime, ok := actual.(*pgPubsub); ok {\n\t\t\treturn runtime\n\t\t}\n\t}\n\tgo created.run()\n\treturn created\n}\n\n// \226\148\128\226\148\128 The publish side \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// active answers whether the database is bound. It also captures the baseline on the current\n// executor, so a first publish inside a pool-size-one transaction never asks the pool for a\n// second connection.\nfunc (runtime *pgPubsub) active() bool {\n\tconnection := runtime.database.bound()\n\tif connection == nil {\n\t\treturn false\n\t}\n\tif err := runtime.prepare(connection); err != nil {\n\t\tpanic(pgFailure(\"publish: cannot prepare the pub/sub outbox\", err))\n\t}\n\treturn true\n}\n\n// publish takes the outbox lock, allocates dispatch_seq, writes the row, and queues NOTIFY in\n// one transaction. If the caller already has a transaction, the lock remains held until that\n// transaction commits; otherwise this method opens the transaction itself.\nfunc (runtime *pgPubsub) publish(channel, key string, encoded string) {\n\tconnection := runtime.database.bound()\n\tif connection == nil {\n\t\t// The binding ended between `active` and here, which only a concurrent unbind can\n\t\t// do; the event is still owed to this process's listeners.\n\t\truntime.deliver(channel, key, encoded)\n\t\treturn\n\t}\n\tctx, cancel := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\tdefer cancel()\n\tif transaction := currentTransaction(); transaction != nil {\n\t\tif _, err := writePubsub(ctx, transaction, connection, channel, key, encoded); err != nil {\n\t\t\tpanic(pgFailure(\"publish\", err))\n\t\t}\n\t} else {\n\t\ttransaction, err := connection.pool.Begin(ctx)\n\t\tif err != nil {\n\t\t\tpanic(pgFailure(\"publish: cannot begin\", err))\n\t\t}\n\t\tcommitted := false\n\t\tdefer func() {\n\t\t\tif !committed {\n\t\t\t\t_ = transaction.Rollback(context.Background())\n\t\t\t}\n\t\t}()\n\t\tif _, err := writePubsub(ctx, transaction, connection, channel, key, encoded); err != nil {\n\t\t\tpanic(pgFailure(\"publish\", err))\n\t\t}\n\t\tif err := transaction.Commit(ctx); err != nil {\n\t\t\tpanic(pgFailure(\"publish: cannot commit\", err))\n\t\t}\n\t\tcommitted = true\n\t}\n\tCounter(\"tesl.sse.pubsub.published\", FromInt64(1), sseChannelAttribute(channel))\n}\n\nfunc writePubsub(ctx context.Context, executor pgExecutor, connection *PostgresDB,\n\tchannel, key, encoded string) (int64, error) {\n\tif _, err := executor.Exec(ctx,\n\t\t`select pg_advisory_xact_lock(hashtextextended(current_database() || ':' || $1, 0))`,\n\t\tconnection.QualifiedTable(pubsubOutboxTable)); err != nil {\n\t\treturn 0, err\n\t}\n\tvar id int64\n\terr := executor.QueryRow(ctx, \"insert into \"+connection.QualifiedTable(pubsubOutboxTable)+\n\t\t` (\"channel\", \"key\", \"payload\", \"dispatch_seq\", \"dispatched_at\") `+\n\t\t`values ($1, $2, $3::jsonb, nextval($4::regclass), clock_timestamp()) returning \"id\"`,\n\t\tchannel, key, encoded, connection.QualifiedTable(pubsubDispatchSeq)).Scan(&id)\n\tif err != nil {\n\t\treturn 0, err\n\t}\n\tif _, err := executor.Exec(ctx, \"select pg_notify($1, $2)\",\n\t\tpubsubNotifyChannel, strconv.FormatInt(id, 10)); err != nil {\n\t\treturn 0, err\n\t}\n\treturn id, nil\n}\n\n// prepare captures the committed dispatch baseline once per runtime. Bootstrap owns the DDL\n// and legacy normalization, so this read is safe through a caller's existing transaction.\nfunc (runtime *pgPubsub) prepare(connection *PostgresDB) error {\n\treturn runtime.prepareOn(connection, connection.executor())\n}\n\nfunc (runtime *pgPubsub) prepareOn(connection *PostgresDB, executor pgExecutor) error {\n\truntime.mutex.Lock()\n\tdefer runtime.mutex.Unlock()\n\tif runtime.ready {\n\t\treturn nil\n\t}\n\tctx, cancel := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\tdefer cancel()\n\tif err := executor.QueryRow(ctx, `select coalesce(max(\"dispatch_seq\"), 0) from `+\n\t\tconnection.QualifiedTable(pubsubOutboxTable)).Scan(&runtime.dispatchCursor); err != nil {\n\t\treturn err\n\t}\n\truntime.ready = true\n\treturn nil\n}\n\n// createPubsubOutbox owns only Tesl's runtime table, sequence, and indexes. The ALTERs are the\n// idempotent upgrade from the original allocation-ordered outbox; they are not application\n// schema migration machinery.\nfunc createPubsubOutbox(ctx context.Context, connection *PostgresDB) error {\n\ttable := connection.QualifiedTable(pubsubOutboxTable)\n\tstatements := []string{\n\t\t`create sequence if not exists ` + connection.QualifiedTable(pubsubDispatchSeq),\n\t\tfmt.Sprintf(`create table if not exists %s (\n\t\"id\" bigserial primary key,\n\t\"channel\" text not null,\n\t\"key\" text not null,\n\t\"payload\" jsonb not null,\n\t\"created_at\" timestamptz not null default now(),\n\t\"dispatch_seq\" bigint,\n\t\"dispatched_at\" timestamptz\n)`, table),\n\t\t`alter table ` + table + ` add column if not exists \"dispatch_seq\" bigint`,\n\t\t`alter table ` + table + ` add column if not exists \"dispatched_at\" timestamptz`,\n\t\t`create unique index if not exists ` + quoteIdentifier(pubsubOutboxTable+\"_dispatch_idx\") +\n\t\t\t` on ` + table + ` (\"dispatch_seq\") where \"dispatch_seq\" is not null`,\n\t\t`create index if not exists ` + quoteIdentifier(pubsubOutboxTable+\"_pending_idx\") +\n\t\t\t` on ` + table + ` (\"id\") where \"dispatch_seq\" is null`,\n\t\t`create index if not exists ` + quoteIdentifier(pubsubOutboxTable+\"_prune_idx\") +\n\t\t\t` on ` + table + ` (\"dispatched_at\") where \"dispatched_at\" is not null`,\n\t}\n\tfor _, statement := range statements {\n\t\tvar err error\n\t\tfor attempt := 0; attempt < 2; attempt++ {\n\t\t\tif _, err = connection.pool.Exec(ctx, statement); err == nil {\n\t\t\t\tbreak\n\t\t\t}\n\t\t\tif !pgDuplicateObject(err) && !strings.Contains(err.Error(), \"already exists\") {\n\t\t\t\treturn err\n\t\t\t}\n\t\t}\n\t\tif err != nil {\n\t\t\treturn err\n\t\t}\n\t}\n\treturn nil\n}\n\n// normalizeLegacyPubsubRows runs during PostgreSQL bootstrap, before the Database can be bound\n// and before a runtime captures its baseline. Each transaction has a fresh lease and handles a\n// bounded batch, avoiding the old single 10-second context across an arbitrarily large outbox.\nfunc normalizeLegacyPubsubRows(connection *PostgresDB) error {\n\tfor {\n\t\tctx, cancel := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\t\tdispatched, err := dispatchLegacyPubsubPending(ctx, connection.pool, connection)\n\t\tcancel()\n\t\tif err != nil {\n\t\t\treturn err\n\t\t}\n\t\tif dispatched < pubsubSweepBatch {\n\t\t\treturn nil\n\t\t}\n\t\tgoruntime.Gosched()\n\t}\n}\n\n// \226\148\128\226\148\128 The delivery side \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// deliver hands one stored event to every local channel of that name. A payload that does\n// not parse is a row another tool wrote, and is skipped rather than allowed to end the\n// listener.\nfunc (runtime *pgPubsub) deliver(channel, key string, encoded string) {\n\tpayload, err := ParseJSON([]byte(encoded))\n\tif err != nil {\n\t\tfmt.Fprintf(os.Stderr, \"tesl: pubsub: outbox row on channel %s holds no JSON: %v\\n\",\n\t\t\tchannel, err)\n\t\treturn\n\t}\n\truntime.mutex.Lock()\n\ttargets := append([]*SseChannel{}, runtime.channels[channel]...)\n\truntime.mutex.Unlock()\n\tfor _, target := range targets {\n\t\tdeliverLocal(target, key, payload)\n\t}\n}\n\nfunc (runtime *pgPubsub) cursor() int64 {\n\truntime.mutex.Lock()\n\tdefer runtime.mutex.Unlock()\n\treturn runtime.dispatchCursor\n}\n\nfunc (runtime *pgPubsub) advance(dispatchSequence int64) {\n\truntime.mutex.Lock()\n\tdefer runtime.mutex.Unlock()\n\tif dispatchSequence > runtime.dispatchCursor {\n\t\truntime.dispatchCursor = dispatchSequence\n\t}\n}\n\n// run is the listener goroutine: wait for the database to be bound, then hold a LISTEN\n// connection for as long as the process lives, reconnecting with backoff when it drops.\nfunc (runtime *pgPubsub) run() {\n\tdefer close(runtime.done)\n\tbackoff := pubsubReconnectMinBackoff\n\tfor {\n\t\tconnection := runtime.database.bound()\n\t\tif connection == nil {\n\t\t\tif !runtime.pause(pubsubBindPollInterval) {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tcontinue\n\t\t}\n\t\tlistened, err := runtime.listenGuarded(connection)\n\t\tif listened {\n\t\t\tbackoff = pubsubReconnectMinBackoff\n\t\t}\n\t\tif runtime.ctx.Err() != nil {\n\t\t\treturn\n\t\t}\n\t\tif err != nil {\n\t\t\tfmt.Fprintf(os.Stderr, \"tesl: pubsub: listener on database %s: %v (reconnecting in %s)\\n\",\n\t\t\t\truntime.database.Name, err, backoff)\n\t\t}\n\t\tif !runtime.pause(backoff) {\n\t\t\treturn\n\t\t}\n\t\tbackoff = min(backoff*2, pubsubReconnectMaxBackoff)\n\t}\n}\n\n// listenGuarded is one connection attempt with any TRAP inside it turned into the error the\n// reconnect loop already handles. The listener goroutine is the\n// process's only path from other instances' events to its subscribers; an unrecovered panic\n// in it (a decode that traps, a driver surprise) would end the whole process rather than\n// one connection.\nfunc (runtime *pgPubsub) listenGuarded(connection *PostgresDB) (listened bool, err error) {\n\tdefer func() {\n\t\tif trap := recover(); trap != nil {\n\t\t\tlistened, err = false, fmt.Errorf(\"listener trapped: %v\", trap)\n\t\t}\n\t}()\n\treturn runtime.listen(connection)\n}\n\n// pause sleeps, or answers false if the runtime was closed meanwhile.\nfunc (runtime *pgPubsub) pause(duration time.Duration) bool {\n\ttimer := time.NewTimer(duration)\n\tdefer timer.Stop()\n\tselect {\n\tcase <-runtime.ctx.Done():\n\t\treturn false\n\tcase <-timer.C:\n\t\treturn true\n\t}\n}\n\n// listen holds ONE dedicated connection: LISTEN, an immediate catch-up sweep, then a loop\n// that waits for a notification and, when none arrives within the sweep interval, sweeps.\n// Everything runs on that one connection and one goroutine \226\128\148 a pool lease is never spent on\n// delivery, so a saturated pool delays requests, not events.\n//\n// The connection is opened from the pool's configuration rather than leased from the pool:\n// a connection that has issued LISTEN must never be handed to another statement, and it\n// lives for the process, which is not what a pool's connections are for. `listened` reports\n// whether LISTEN was established, which is what resets the reconnect backoff.\nfunc (runtime *pgPubsub) listen(connection *PostgresDB) (listened bool, err error) {\n\tconnectCtx, cancelConnect := context.WithTimeout(runtime.ctx, pgLeaseTimeout())\n\tdefer cancelConnect()\n\tconn, err := pgx.ConnectConfig(connectCtx, connection.pool.Config().ConnConfig.Copy())\n\tif err != nil {\n\t\treturn false, err\n\t}\n\tdefer func() {\n\t\tcloseCtx, cancelClose := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\t\tdefer cancelClose()\n\t\t_ = conn.Close(closeCtx)\n\t\truntime.mutex.Lock()\n\t\truntime.listener = nil\n\t\truntime.mutex.Unlock()\n\t}()\n\tif err := runtime.prepareOn(connection, conn); err != nil {\n\t\treturn false, err\n\t}\n\tif _, err := conn.Exec(connectCtx, \"listen \"+quoteIdentifier(pubsubNotifyChannel)); err != nil {\n\t\treturn false, err\n\t}\n\tif _, err := conn.Exec(connectCtx, \"listen \"+quoteIdentifier(queueNotifyChannel)); err != nil {\n\t\treturn false, err\n\t}\n\truntime.mutex.Lock()\n\truntime.listener = conn\n\truntime.mutex.Unlock()\n\n\t// Rows that committed before LISTEN was in place, and rows a previous connection's\n\t// last moments missed.\n\tif err := runtime.drain(conn, connection); err != nil {\n\t\treturn true, err\n\t}\n\tnextSweep := time.Now().Add(pubsubSweepInterval)\n\tnextPrune := time.Now().Add(pubsubPruneInterval)\n\tfor {\n\t\twaitCtx, cancelWait := context.WithDeadline(runtime.ctx, nextSweep)\n\t\tnotification, err := conn.WaitForNotification(waitCtx)\n\t\tcancelWait()\n\t\tswitch {\n\t\tcase err == nil:\n\t\t\tnow := time.Now()\n\t\t\tif notification != nil && notification.Channel == queueNotifyChannel {\n\t\t\t\truntime.wakeQueues(notification.Payload)\n\t\t\t} else if notification != nil && notification.Channel == pubsubNotifyChannel {\n\t\t\t\t// The payload is deliberately ignored. NOTIFY only wakes the same durable,\n\t\t\t\t// ordered path used for reconnect and lost-notification recovery.\n\t\t\t\tif err := runtime.drain(conn, connection); err != nil {\n\t\t\t\t\treturn true, err\n\t\t\t\t}\n\t\t\t\tnextSweep = now.Add(pubsubSweepInterval)\n\t\t\t}\n\t\t\tif !now.Before(nextSweep) {\n\t\t\t\tif err := runtime.drain(conn, connection); err != nil {\n\t\t\t\t\treturn true, err\n\t\t\t\t}\n\t\t\t\tnextSweep = now.Add(pubsubSweepInterval)\n\t\t\t}\n\t\t\tif !now.Before(nextPrune) {\n\t\t\t\tif err := runtime.prune(conn, connection); err != nil {\n\t\t\t\t\treturn true, err\n\t\t\t\t}\n\t\t\t\tnextPrune = now.Add(pubsubPruneInterval)\n\t\t\t}\n\t\t\tcontinue\n\t\tcase errors.Is(err, context.DeadlineExceeded) && runtime.ctx.Err() == nil:\n\t\t\t// The wait ran out, which is the sweep's cue; the connection is intact \226\128\148 pgx\n\t\t\t// resets the read deadline on the way out, and a deadline is not a fatal error\n\t\t\t// to it.\n\t\t\tif err := runtime.drain(conn, connection); err != nil {\n\t\t\t\treturn true, err\n\t\t\t}\n\t\t\tnextSweep = time.Now().Add(pubsubSweepInterval)\n\t\t\tif !time.Now().Before(nextPrune) {\n\t\t\t\tif err := runtime.prune(conn, connection); err != nil {\n\t\t\t\t\treturn true, err\n\t\t\t\t}\n\t\t\t\tnextPrune = time.Now().Add(pubsubPruneInterval)\n\t\t\t}\n\t\tdefault:\n\t\t\treturn true, err\n\t\t}\n\t}\n}\n\ntype pubsubRow struct {\n\tid               int64\n\tdispatchSequence int64\n\tchannel, key     string\n\tencoded          string\n}\n\ntype pgTransactionStarter interface {\n\tBegin(context.Context) (pgx.Tx, error)\n}\n\n// dispatchLegacyPubsubPending upgrades one bounded batch written by the former nullable-sequence\n// format. The explicit transaction makes the ordering proof the same as Publish: take the lock,\n// draw sequence values, and commit before another cooperating publisher can draw one.\nfunc dispatchLegacyPubsubPending(ctx context.Context, starter pgTransactionStarter,\n\tconnection *PostgresDB) (int, error) {\n\ttransaction, err := starter.Begin(ctx)\n\tif err != nil {\n\t\treturn 0, err\n\t}\n\tcommitted := false\n\tdefer func() {\n\t\tif !committed {\n\t\t\t_ = transaction.Rollback(context.Background())\n\t\t}\n\t}()\n\tif _, err := transaction.Exec(ctx,\n\t\t`select pg_advisory_xact_lock(hashtextextended(current_database() || ':' || $1, 0))`,\n\t\tconnection.QualifiedTable(pubsubOutboxTable)); err != nil {\n\t\treturn 0, err\n\t}\n\ttable := connection.QualifiedTable(pubsubOutboxTable)\n\tstatement := `with pending as materialized (` +\n\t\t`select \"id\" from ` + table + ` where \"dispatch_seq\" is null order by \"id\" limit $1) ` +\n\t\t`update ` + table + ` as outbox set ` +\n\t\t`\"dispatch_seq\" = nextval($2::regclass), \"dispatched_at\" = clock_timestamp() ` +\n\t\t`from pending where outbox.\"id\" = pending.\"id\" and outbox.\"dispatch_seq\" is null`\n\ttag, err := transaction.Exec(ctx, statement, int32(pubsubSweepBatch),\n\t\tconnection.QualifiedTable(pubsubDispatchSeq))\n\tif err != nil {\n\t\treturn 0, err\n\t}\n\tif err := transaction.Commit(ctx); err != nil {\n\t\treturn 0, err\n\t}\n\tcommitted = true\n\treturn int(tag.RowsAffected()), nil\n}\n\ntype pubsubDrainStats struct {\n\titerations       int\n\tlegacyChecks     int\n\tdispatchQueries  int\n\tfetchQueries     int\n\tlegacyRows       int\n\trowsRead         int\n\tmaxLegacyBatch   int\n\tmaxDeliveryBatch int\n}\n\n// drainWithStats continuously catches up. Each iteration has bounded SQL and memory, and a full\n// iteration yields before continuing; there is no periodic per-sweep ceiling that can turn a\n// sustained but serviceable publish rate into permanent backlog.\nfunc (runtime *pgPubsub) drainWithStats(conn *pgx.Conn, connection *PostgresDB) (pubsubDrainStats, error) {\n\truntime.deliveryMutex.Lock()\n\tdefer runtime.deliveryMutex.Unlock()\n\tstats := pubsubDrainStats{}\n\tfor {\n\t\tif err := runtime.ctx.Err(); err != nil {\n\t\t\treturn stats, err\n\t\t}\n\t\tctx, cancel := context.WithTimeout(runtime.ctx, pgLeaseTimeout())\n\t\trows, err := conn.Query(ctx, `select \"id\", \"channel\", \"key\", \"payload\"::text, \"dispatch_seq\" from `+\n\t\t\tconnection.QualifiedTable(pubsubOutboxTable)+\n\t\t\t` where \"dispatch_seq\" > $1 order by \"dispatch_seq\" limit $2`,\n\t\t\truntime.cursor(), pubsubSweepBatch)\n\t\tstats.fetchQueries++\n\t\tif err != nil {\n\t\t\tcancel()\n\t\t\treturn stats, err\n\t\t}\n\t\tbatch, err := pgx.CollectRows(rows, func(row pgx.CollectableRow) (pubsubRow, error) {\n\t\t\tvar collected pubsubRow\n\t\t\terr := row.Scan(&collected.id, &collected.channel, &collected.key, &collected.encoded,\n\t\t\t\t&collected.dispatchSequence)\n\t\t\treturn collected, err\n\t\t})\n\t\tcancel()\n\t\tif err != nil {\n\t\t\treturn stats, err\n\t\t}\n\t\tstats.iterations++\n\t\tstats.rowsRead += len(batch)\n\t\tif len(batch) > stats.maxDeliveryBatch {\n\t\t\tstats.maxDeliveryBatch = len(batch)\n\t\t}\n\t\tfor _, row := range batch {\n\t\t\truntime.deliver(row.channel, row.key, row.encoded)\n\t\t\truntime.advance(row.dispatchSequence)\n\t\t}\n\t\tif len(batch) == pubsubSweepBatch {\n\t\t\tgoruntime.Gosched()\n\t\t\tcontinue\n\t\t}\n\n\t\tctx, cancel = context.WithTimeout(runtime.ctx, pgLeaseTimeout())\n\t\tvar legacyPending bool\n\t\terr = conn.QueryRow(ctx, `select exists (select 1 from `+\n\t\t\tconnection.QualifiedTable(pubsubOutboxTable)+` where \"dispatch_seq\" is null)`).Scan(&legacyPending)\n\t\tcancel()\n\t\tstats.legacyChecks++\n\t\tif err != nil {\n\t\t\treturn stats, err\n\t\t}\n\t\tif !legacyPending {\n\t\t\treturn stats, nil\n\t\t}\n\n\t\tctx, cancel = context.WithTimeout(runtime.ctx, pgLeaseTimeout())\n\t\tdispatched, err := dispatchLegacyPubsubPending(ctx, conn, connection)\n\t\tcancel()\n\t\tstats.dispatchQueries++\n\t\tif err != nil {\n\t\t\treturn stats, err\n\t\t}\n\t\tstats.legacyRows += dispatched\n\t\tif dispatched > stats.maxLegacyBatch {\n\t\t\tstats.maxLegacyBatch = dispatched\n\t\t}\n\t\tgoruntime.Gosched()\n\t}\n}\n\nfunc (runtime *pgPubsub) drain(conn *pgx.Conn, connection *PostgresDB) error {\n\t_, err := runtime.drainWithStats(conn, connection)\n\treturn err\n}\n\n// prune deletes rows past the retention. Every instance prunes; the statement is idempotent\n// and cheap, and electing one pruner would be a coordination problem for no gain.\nfunc (runtime *pgPubsub) prune(conn *pgx.Conn, connection *PostgresDB) error {\n\tctx, cancel := context.WithTimeout(runtime.ctx, pgLeaseTimeout())\n\tdefer cancel()\n\t_, err := conn.Exec(ctx, `delete from `+connection.QualifiedTable(pubsubOutboxTable)+\n\t\t` where \"dispatched_at\" < now() - make_interval(secs => $1)`,\n\t\tpubsubOutboxRetention.Seconds())\n\treturn err\n}\n\n// listenerPID answers the backend process id of the live LISTEN connection, or zero between\n// connections \226\128\148 what a test needs to kill it.\n// ListenerPID is the backend pid of this process's LISTEN connection (0 while disconnected);\n// exported for the runtime's own tests, which terminate it to exercise the reconnect.\nfunc (runtime *pgPubsub) ListenerPID() uint32 {\n\truntime.mutex.Lock()\n\tdefer runtime.mutex.Unlock()\n\tif runtime.listener == nil {\n\t\treturn 0\n\t}\n\treturn runtime.listener.PgConn().PID()\n}\n\n// close ends the listener goroutine and forgets the runtime, for a test that stood one up.\n// A program never calls it: the listener lives as long as the process.\n// Close stops the LISTEN loop and waits for it; exported for the runtime's own tests.\nfunc (runtime *pgPubsub) Close() {\n\truntime.cancel()\n\tpgPubsubs.CompareAndDelete(runtime.database, runtime)\n\tselect {\n\tcase <-runtime.done:\n\tcase <-time.After(2 * pgLeaseTimeout()):\n\t}\n}\n");
  ("pgstores.go", "package teslrt\n\nimport (\n\t\"context\"\n\t\"crypto/rand\"\n\t\"encoding/hex\"\n\t\"errors\"\n\t\"fmt\"\n\t\"os\"\n\t\"reflect\"\n\t\"runtime\"\n\t\"strconv\"\n\t\"sync\"\n\t\"sync/atomic\"\n\t\"time\"\n\n\t\"github.com/jackc/pgx/v5\"\n\t\"github.com/jackc/pgx/v5/pgconn\"\n)\n\n// The DURABLE stores: a queue, an email outbox and a cache declared on a Postgres-backed\n// database keep their state in that database rather than in process memory, so several\n// instances of one program work off one job table, a restart loses no job and no unsent\n// mail, and `enqueue` / `Email.send` inside `transaction { \226\128\166 }` commit or roll back with the\n// surrounding writes.\n//\n// WHICH PROGRAMS GET THIS FILE. Only one that declares a Postgres-backed database \226\128\148 the\n// emitter gates it with postgres.go, database.go and dbquery.go \226\128\148 so everything that names\n// `*Database`, `*PostgresDB` or the driver lives HERE. queue.go, email.go and cache.go ship\n// with every program and see only the small package-private interfaces they declare\n// (`queueBackend`, `outboxBackend`, `cacheBackend`), which the three stores below implement.\n//\n// WHEN THE STORE IS USED. A backend is ACTIVE while its database is bound (`with database D`,\n// which `main`'s App does for a served program). Off a binding every operation falls through\n// to the in-memory store the always-shipped file already has, which is what lets a `test`\n// block exercise a durable queue with no server anywhere \226\128\148 the same dispatch dbquery.go\n// performs for an entity's rows.\n//\n// THE TABLES ARE THE RACKET RUNTIME'S in name and meaning (`tesl_jobs`, `tesl_email_outbox`,\n// `tesl_cache`; `for update skip locked` claims; `next_attempt_at` backoff), created lazily\n// with `if not exists` the first time a store touches them, in the database's schema.\n//\n// EVERY STATEMENT RUNS THROUGH THE EXECUTOR (PgExec / PgQuery / PgCount), so one issued on a\n// goroutine with an open transaction joins it. That is the whole of the atomicity story: an\n// `enqueue` in a rolled-back handler leaves no row because the insert WAS the transaction's.\n// The table bootstrap is the one exception \226\128\148 it runs on the pool, because a `create table`\n// that rolled back with a failing body would leave the once-flag set and the table absent.\n\n// \226\148\128\226\148\128 Shared plumbing \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// pgStore is what the three backends share: the database whose binding decides whether\n// they are active, and the table bootstrap.\ntype pgStore struct {\n\tdatabase *Database\n}\n\nfunc (store pgStore) active() bool {\n\treturn store.database.bound() != nil\n}\n\n// connection is the bound connection, for a call that has already passed `active()`. The\n// binding cannot go away between the two under the runtime's own use (a served program binds\n// once, in `main`), so an unbound answer here is a programming error rather than a state.\nfunc (store pgStore) connection() *PostgresDB {\n\tdb := store.database.bound()\n\tif db == nil {\n\t\tpanic(\"database \" + store.database.Name + \" is not bound \226\128\148 a durable store was used outside `with database`\")\n\t}\n\treturn db\n}\n\n// pgTableKey identifies one table on one pool: the bootstrap runs once per key.\ntype pgTableKey struct {\n\tdb    *PostgresDB\n\ttable string\n}\n\n// pgTableOnce is a sync.Once that a PANIC does not complete: a bootstrap the server refused\n// (it was down, the lease ran out) is retried by the next call rather than remembered as done\n// with no table behind it.\ntype pgTableOnce struct {\n\tmutex sync.Mutex\n\tdone  bool\n}\n\nvar pgTablesReady sync.Map // pgTableKey -> *pgTableOnce\n\n// ensureTable creates `table` (and whatever `statements` adds around it \226\128\148 an index) if it is\n// absent, once per pool. Two instances starting together both run `create \226\128\166 if not exists`,\n// and PostgreSQL still reports a duplicate from one of them when the race is tight enough\n// (the catalog's unique index wins where the `if not exists` check lost), so a duplicate-\n// object error is the OTHER instance's success and is tolerated.\nfunc ensureTable(db *PostgresDB, table string, statements func(qualified string) []string) {\n\tkey := pgTableKey{db: db, table: table}\n\tloaded, _ := pgTablesReady.LoadOrStore(key, &pgTableOnce{})\n\tonce, ok := loaded.(*pgTableOnce)\n\tif !ok {\n\t\tpanic(\"database: table bootstrap registry holds an unexpected value\")\n\t}\n\tonce.mutex.Lock()\n\tdefer once.mutex.Unlock()\n\tif once.done {\n\t\treturn\n\t}\n\tfor _, statement := range statements(db.QualifiedTable(table)) {\n\t\tctx, cancel := context.WithTimeout(context.Background(), pgLeaseTimeout())\n\t\t_, err := db.pool.Exec(ctx, statement)\n\t\tcancel()\n\t\tif err != nil && !pgDuplicateObject(err) {\n\t\t\tpanic(\"database: cannot create \" + table + \": \" + err.Error())\n\t\t}\n\t}\n\tonce.done = true\n}\n\n// pgDuplicateObject reports the SQLSTATEs a concurrent `create \226\128\166 if not exists` can raise:\n// duplicate_table, duplicate_object, duplicate_schema, and the unique_violation on the\n// catalog itself that a tight race produces.\nfunc pgDuplicateObject(err error) bool {\n\tvar pgErr *pgconn.PgError\n\tif !errors.As(err, &pgErr) {\n\t\treturn false\n\t}\n\tswitch pgErr.Code {\n\tcase \"42P07\", \"42710\", \"42701\", \"42P06\", \"23505\":\n\t\treturn true\n\t}\n\treturn false\n}\n\n// instanceID names THIS process in a `locked_by` column: hostname, pid and a random suffix,\n// minted once. It is diagnostic \226\128\148 the claim's correctness rests on `skip locked`, not on the\n// name \226\128\148 but a stuck job that says which instance took it is a stuck job that can be found.\nvar (\n\tinstanceIDOnce sync.Once\n\tinstanceIDText string\n)\n\nfunc instanceID() string {\n\tinstanceIDOnce.Do(func() {\n\t\thost, err := os.Hostname()\n\t\tif err != nil || host == \"\" {\n\t\t\thost = \"unknown-host\"\n\t\t}\n\t\tsuffix := make([]byte, 4)\n\t\tif _, err := rand.Read(suffix); err != nil {\n\t\t\tpanic(\"database: cannot draw an instance id: \" + err.Error())\n\t\t}\n\t\tinstanceIDText = host + \":\" + strconv.Itoa(os.Getpid()) + \":\" + hex.EncodeToString(suffix)\n\t})\n\treturn instanceIDText\n}\n\n// jsonbText renders a JSON-ready value as the text a `$n::jsonb` parameter takes.\nfunc jsonbText(value any) string {\n\treturn EncodeJSONValue(value)\n}\n\n// scanText is the one-column text scanner the stores share.\nfunc scanText(row pgx.CollectableRow) (string, error) {\n\tvar text string\n\terr := row.Scan(&text)\n\treturn text, err\n}\n\n// \226\148\128\226\148\128 Queue \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// tesl_jobs holds every queue of the database, told apart by `queue`. A row is one job:\n//\n//\tstatus          pending | processing | dead | dead_processing\n//\tattempts        failed attempts so far\n//\tnext_attempt_at when a pending (or dead) row may be claimed; the backoff lands here\n//\tseq             the claim order \226\128\148 a bigserial, so a retried job keeps its place in line\n//\tlocked_at/by    who is processing it and since when; what the reclaim reads\n//\tclaim_token     identity of the current processing attempt; every outcome is fenced by it\n//\tjob_type        which codec decodes `payload`\n//\n// CLAIM is a single statement \226\128\148 `update \226\128\166 where id = (select \226\128\166 for update skip locked limit\n// 1) returning \226\128\166` \226\128\148 so two workers on two instances cannot take the same row: the second\n// skips the row the first has locked and takes the next. Before each claim, jobs an instance\n// took and never finished (it crashed, or lost the network) are RECLAIMED: a `processing` row\n// whose `locked_at` is older than the visibility timeout goes back to `pending`, while a\n// `dead_processing` row goes back to `dead`. Attempts stay intact in both cases.\n\n// jobsTable is the table name; the schema is the database's.\nconst jobsTable = \"tesl_jobs\"\n\nfunc jobsTableDDL(qualified string) []string {\n\treturn []string{\n\t\t\"create table if not exists \" + qualified + \" (\" +\n\t\t\t\"id text primary key, \" +\n\t\t\t\"queue text not null, \" +\n\t\t\t\"job_type text not null, \" +\n\t\t\t\"payload jsonb not null, \" +\n\t\t\t\"status text not null, \" +\n\t\t\t\"attempts int not null default 0, \" +\n\t\t\t\"next_attempt_at timestamptz not null default now(), \" +\n\t\t\t\"seq bigserial, \" +\n\t\t\t\"locked_at timestamptz, \" +\n\t\t\t\"locked_by text, \" +\n\t\t\t\"claim_token text, \" +\n\t\t\t\"created_at timestamptz not null default now())\",\n\t\t\"alter table \" + qualified + \" add column if not exists claim_token text\",\n\t\t\"create index if not exists \" + quoteIdentifier(jobsTable+\"_claim_idx\") +\n\t\t\t\" on \" + qualified + \" (queue, status, next_attempt_at, seq)\",\n\t}\n}\n\n// queueVisibilityTimeout is how long a `processing` job may go unfinished before another\n// instance may take it over \226\128\148 `TESL_QUEUE_VISIBILITY_TIMEOUT_MS`, default ten minutes. A\n// variable so the runtime's own tests can shrink it without waiting ten minutes for a\n// simulated crash to be noticed.\nvar queueVisibilityTimeout = func() time.Duration {\n\treturn millisDuration(envPositiveInt(\"TESL_QUEUE_VISIBILITY_TIMEOUT_MS\", 600000))\n}\n\n// jobCodec is how one job type crosses the JSONB column: `encode` answers what\n// EncodeJSONValue renders, `decode` takes what ParseJSON produced.\ntype jobCodec struct {\n\ttypeName string\n\tencode   func(any) any\n\tdecode   func(any) (any, error)\n}\n\ntype pgQueueBackend struct {\n\tpgStore\n\tname         string\n\tmaxAttempts  int\n\tbackoff      string\n\tinitialDelay int\n\t// codecs, in registration order; the emitter registers every job type of the queue\n\t// before anything is enqueued.\n\tcodecsMutex sync.RWMutex\n\tcodecs      []jobCodec\n\t// codecByType remembers which codec took a Go type, so the probe below runs once per type.\n\tcodecByType sync.Map     // reflect.Type -> int (index into codecs)\n\tlastReclaim atomic.Int64 // unix nanoseconds of this process's last stale-job sweep\n}\n\n// NewQueueOn is `queue Q = Queue { database: D \226\128\166 }` for a Postgres-backed D: the in-memory\n// queue plus the durable backend. `backoff` is \"exponential\", \"fixed\", \"linear\" or \"\" (no\n// delay between retries); `initialDelaySeconds` is the declaration's `initialDelay`.\nfunc NewQueueOn(database *Database, name string, maxAttempts int, backoff string,\n\tinitialDelaySeconds int) *Queue {\n\tqueue := NewQueue(name, maxAttempts)\n\tif initialDelaySeconds < 0 {\n\t\tinitialDelaySeconds = 0\n\t}\n\tqueue.backend = &pgQueueBackend{pgStore: pgStore{database: database}, name: name,\n\t\tmaxAttempts: queue.maxAttempts, backoff: backoff, initialDelay: initialDelaySeconds}\n\t// The database's LISTEN loop (shared with pub/sub) rings this queue's doorbell when any\n\t// instance commits an enqueue.\n\tpubsubFor(database).registerQueue(queue)\n\treturn queue\n}\n\n// RegisterJobCodec teaches a durable queue one job record type: `typeName` is what the row's\n// `job_type` column says, `encode` renders a payload of that type as a JSON-ready value and\n// `decode` reads one back into the typed Go struct. A queue that carries several job types\n// registers each. On a Memory queue there is nothing to register and the call is a no-op.\n//\n// HOW A PAYLOAD FINDS ITS CODEC. `encode` is opaque here \226\128\148 the emitter writes it as\n// `func(v any) any { return encodeT(v.(T)) }` \226\128\148 so the runtime tries the registered encoders\n// in order and keeps the first that does not refuse the value with a type assertion; the Go\n// type that matched is remembered, so the trial runs once per type per process. A panic that\n// is NOT a type assertion (a NaN Float, say) is the encoder's own and propagates.\nfunc RegisterJobCodec(queue *Queue, typeName string, encode func(any) any,\n\tdecode func(any) (any, error)) struct{} {\n\tbackend, durable := queue.backend.(*pgQueueBackend)\n\tif !durable {\n\t\treturn struct{}{}\n\t}\n\tbackend.codecsMutex.Lock()\n\tdefer backend.codecsMutex.Unlock()\n\tfor index, existing := range backend.codecs {\n\t\tif existing.typeName == typeName {\n\t\t\tbackend.codecs[index] = jobCodec{typeName: typeName, encode: encode, decode: decode}\n\t\t\treturn struct{}{}\n\t\t}\n\t}\n\tbackend.codecs = append(backend.codecs, jobCodec{typeName: typeName, encode: encode, decode: decode})\n\treturn struct{}{}\n}\n\n// tryEncode runs one encoder, answering `refused` when it rejected the value's TYPE.\nfunc tryEncode(codec jobCodec, payload any) (encoded any, refused bool) {\n\tdefer func() {\n\t\tif trap := recover(); trap != nil {\n\t\t\tvar assertion *runtime.TypeAssertionError\n\t\t\tif err, isError := trap.(error); isError && errors.As(err, &assertion) {\n\t\t\t\trefused = true\n\t\t\t\treturn\n\t\t\t}\n\t\t\tpanic(trap)\n\t\t}\n\t}()\n\treturn codec.encode(payload), false\n}\n\n// encodePayload answers the job type and the JSON-ready value for a payload.\nfunc (backend *pgQueueBackend) encodePayload(payload any) (string, any) {\n\tbackend.codecsMutex.RLock()\n\tcodecs := backend.codecs\n\tbackend.codecsMutex.RUnlock()\n\tif len(codecs) == 0 {\n\t\tpanic(\"enqueue: queue \" + backend.name + \" has no job codec registered \226\128\148 \" +\n\t\t\t\"RegisterJobCodec must run for every job type the queue carries\")\n\t}\n\tgoType := reflect.TypeOf(payload)\n\tif found, known := backend.codecByType.Load(goType); known {\n\t\tif index, ok := found.(int); ok && index < len(codecs) {\n\t\t\treturn codecs[index].typeName, codecs[index].encode(payload)\n\t\t}\n\t}\n\tfor index, codec := range codecs {\n\t\tif encoded, refused := tryEncode(codec, payload); !refused {\n\t\t\tbackend.codecByType.Store(goType, index)\n\t\t\treturn codec.typeName, encoded\n\t\t}\n\t}\n\tpanic(fmt.Sprintf(\"enqueue: queue %s has no job codec for a payload of type %T\", backend.name, payload))\n}\n\n// decodePayload reads a row's payload back through the codec its `job_type` names.\nfunc (backend *pgQueueBackend) decodePayload(typeName, payloadText string) (any, error) {\n\tbackend.codecsMutex.RLock()\n\tcodecs := backend.codecs\n\tbackend.codecsMutex.RUnlock()\n\tfor _, codec := range codecs {\n\t\tif codec.typeName == typeName {\n\t\t\tparsed, err := ParseJSON([]byte(payloadText))\n\t\t\tif err != nil {\n\t\t\t\treturn nil, fmt.Errorf(\"payload is not JSON: %w\", err)\n\t\t\t}\n\t\t\treturn codec.decode(parsed)\n\t\t}\n\t}\n\treturn nil, fmt.Errorf(\"no job codec registered for job_type %q\", typeName)\n}\n\nfunc (backend *pgQueueBackend) table() (*PostgresDB, string) {\n\tdb := backend.connection()\n\tensureTable(db, jobsTable, jobsTableDDL)\n\treturn db, db.QualifiedTable(jobsTable)\n}\n\nfunc (backend *pgQueueBackend) enqueue(payload any) string {\n\ttypeName, encoded := backend.encodePayload(payload)\n\tdb, table := backend.table()\n\tid := UUIDv7()\n\tPgExec(db, \"insert into \"+table+\" (id, queue, job_type, payload, status) \"+\n\t\t\"values ($1, $2, $3, $4::jsonb, 'pending')\",\n\t\t[]any{id, backend.name, typeName, jsonbText(encoded)})\n\t// Through the same executor, so inside a `transaction { }` the notification is\n\t// delivered on commit and never for a rollback \226\128\148 workers on every instance wake only\n\t// when the row is visible to them.\n\tPgExec(db, \"select pg_notify($1, $2)\", []any{queueNotifyChannel, backend.name})\n\treturn id\n}\n\n// claimedJob is one row as the claim returns it.\ntype claimedJob struct {\n\tid         string\n\tjobType    string\n\tpayload    string\n\tattempts   int\n\tclaimToken string\n}\n\nfunc scanClaimedJob(row pgx.CollectableRow) (claimedJob, error) {\n\tjob := claimedJob{}\n\tvar attempts int32\n\tif err := row.Scan(&job.id, &job.jobType, &job.payload, &attempts, &job.claimToken); err != nil {\n\t\treturn job, err\n\t}\n\tjob.attempts = int(attempts)\n\treturn job, nil\n}\n\n// queueReclaimInterval bounds how often ONE process sweeps for jobs an instance took and never\n// finished. The sweep is an UPDATE over the queue's processing rows; running it before every\n// claim put it on the hot path of every job (tesl/queue.rkt swept once a minute from its\n// poller thread, and so does this). A variable so the runtime's tests can shrink it.\nvar queueReclaimInterval = time.Minute\n\n// reclaimStuck releases jobs an instance took and never finished, at most once per\n// queueReclaimInterval per process.\nfunc (backend *pgQueueBackend) reclaimStuck(db *PostgresDB, table string) {\n\tnow := time.Now().UnixNano()\n\tlast := backend.lastReclaim.Load()\n\tif now-last < queueReclaimInterval.Nanoseconds() || !backend.lastReclaim.CompareAndSwap(last, now) {\n\t\treturn\n\t}\n\tPgExec(db, \"update \"+table+\" set status = case when status = 'dead_processing' then 'dead' else 'pending' end, \"+\n\t\t\"locked_at = null, locked_by = null, claim_token = null \"+\n\t\t\"where queue = $1 and status in ('processing', 'dead_processing') \"+\n\t\t\"and locked_at < now() - ($2::bigint * interval '1 millisecond')\",\n\t\t[]any{backend.name, queueVisibilityTimeout().Milliseconds()})\n}\n\n// dequeue claims the oldest claimable job with `status` and decodes it. A row whose payload\n// cannot be decoded \226\128\148 its `job_type` has no codec (a job enqueued by a build that knew a type\n// this one does not), or the JSON does not fit \226\128\148 is QUARANTINED rather than dropped or\n// retried: it goes to the dead letter with a `next_attempt_at` of infinity, so it is counted\n// and listed there but never claimed again by either worker, and one line on stderr says so.\n// The claim then moves on to the next row instead of answering \"nothing to do\".\nfunc (backend *pgQueueBackend) dequeue(status string) (string, any, int, string, bool) {\n\tdb, table := backend.table()\n\tbackend.reclaimStuck(db, table)\n\tprocessingStatus := jobProcessing\n\tif status == jobDead {\n\t\tprocessingStatus = jobDeadProcessing\n\t}\n\tfor {\n\t\tclaimToken := UUIDv7()\n\t\trows := PgQuery(db, \"update \"+table+\" set status = $3, locked_at = now(), locked_by = $4, \"+\n\t\t\t\"claim_token = $5 \"+\n\t\t\t\"where id = (select id from \"+table+\" where queue = $1 and status = $2 \"+\n\t\t\t\"and next_attempt_at <= now() order by seq for update skip locked limit 1) \"+\n\t\t\t\"returning id, job_type, payload::text, attempts, claim_token\",\n\t\t\t[]any{backend.name, status, processingStatus, instanceID(), claimToken}, scanClaimedJob)\n\t\tif len(rows) == 0 {\n\t\t\treturn \"\", nil, 0, \"\", false\n\t\t}\n\t\tclaimed := rows[0]\n\t\tpayload, err := backend.decodePayload(claimed.jobType, claimed.payload)\n\t\tif err != nil {\n\t\t\tchanged := PgExec(db, \"update \"+table+\" set status = 'dead', next_attempt_at = 'infinity', \"+\n\t\t\t\t\"locked_at = null, locked_by = null, claim_token = null \"+\n\t\t\t\t\"where id = $1 and status = $3 and claim_token = $2\",\n\t\t\t\t[]any{claimed.id, claimed.claimToken, processingStatus})\n\t\t\tif changed == 1 {\n\t\t\t\tfmt.Fprintf(os.Stderr, \"tesl: queue %s: job %s (job_type %s) cannot be decoded and was \"+\n\t\t\t\t\t\"quarantined in the dead letter: %v\\n\", backend.name, claimed.id, claimed.jobType, err)\n\t\t\t}\n\t\t\tcontinue\n\t\t}\n\t\treturn claimed.id, payload, claimed.attempts, claimed.claimToken, true\n\t}\n}\n\nfunc (backend *pgQueueBackend) complete(id, claimToken string) bool {\n\tdb, table := backend.table()\n\t// Zero rows means this attempt's lease was replaced; its result is discarded.\n\treturn PgExec(db, \"delete from \"+table+\n\t\t\" where id = $1 and status in ('processing', 'dead_processing') and claim_token = $2\",\n\t\t[]any{id, claimToken}) == 1\n}\n\n// retryDelaySeconds is the wait before attempt number `attempts`+1, given `attempts` failures:\n// exponential doubles from the initial delay (N, 2N, 4N, \226\128\166), linear grows by it (N, 2N, 3N,\n// \226\128\166), fixed is always N, and \"\" is no wait at all.\nfunc (backend *pgQueueBackend) retryDelaySeconds(attempts int) int64 {\n\tinitial := int64(backend.initialDelay)\n\tif attempts < 1 {\n\t\tattempts = 1\n\t}\n\tswitch backend.backoff {\n\tcase \"exponential\":\n\t\tshift := attempts - 1\n\t\tif shift > 40 {\n\t\t\tshift = 40\n\t\t}\n\t\treturn initial << shift\n\tcase \"linear\":\n\t\treturn initial * int64(attempts)\n\tcase \"fixed\":\n\t\treturn initial\n\tdefault:\n\t\treturn 0\n\t}\n}\n\n// fail records a failed attempt: back to `pending` after the backoff, or `dead` at\n// maxAttempts \226\128\148 claimable at once by the dead-letter worker.\nfunc (backend *pgQueueBackend) fail(id string, attempts int, claimToken string) bool {\n\tdb, table := backend.table()\n\tnext := attempts + 1\n\tstatus := jobPending\n\tdelay := backend.retryDelaySeconds(next)\n\tif next >= backend.maxAttempts {\n\t\tstatus = jobDead\n\t\tdelay = 0\n\t}\n\tchanged := PgExec(db, \"update \"+table+\" set status = $2, attempts = $3, \"+\n\t\t\"next_attempt_at = now() + ($4::bigint * interval '1 second'), \"+\n\t\t\"locked_at = null, locked_by = null, claim_token = null \"+\n\t\t\"where id = $1 and status = 'processing' and claim_token = $5\",\n\t\t[]any{id, status, int32(min(next, 1<<30)), delay, claimToken}) // #nosec G115 -- clamped above\n\treturn changed == 1\n}\n\nfunc (backend *pgQueueBackend) count(status string) int {\n\tdb, table := backend.table()\n\tcounted, exact := PgCount(db, \"select count(*) from \"+table+\" where queue = $1 and status = $2\",\n\t\t[]any{backend.name, status}).Int64()\n\tif !exact {\n\t\treturn 0\n\t}\n\treturn int(counted)\n}\n\nfunc (backend *pgQueueBackend) deadJobs(queue *Queue) []DeadJob {\n\tdb, table := backend.table()\n\tids := PgQuery(db, \"select id from \"+table+\" where queue = $1 and status = 'dead' order by seq\",\n\t\t[]any{backend.name}, scanText)\n\tdead := make([]DeadJob, 0, len(ids))\n\tfor _, id := range ids {\n\t\tdead = append(dead, DeadJob{ID: id, queue: queue})\n\t}\n\treturn dead\n}\n\n// requeue puts a dead job back in line with a fresh attempt count. Only a row that IS dead\n// moves \226\128\148 one a dead-letter worker has claimed is `dead_processing` and answers false, as the\n// in-memory store does for the same case.\nfunc (backend *pgQueueBackend) requeue(id string) bool {\n\tdb, table := backend.table()\n\tchanged := PgExec(db, \"update \"+table+\" set status = 'pending', attempts = 0, \"+\n\t\t\"next_attempt_at = now(), locked_at = null, locked_by = null, claim_token = null \"+\n\t\t\"where id = $1 and status = 'dead'\", []any{id})\n\treturn changed == 1\n}\n\nfunc (backend *pgQueueBackend) reset() {\n\tdb, table := backend.table()\n\tPgExec(db, \"delete from \"+table+\" where queue = $1\", []any{backend.name})\n}\n\n// \226\148\128\226\148\128 Email outbox \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// tesl_email_outbox is one table per database, shared by every `email` declaration on it\n// (as Racket's was). A row is a message; `status` is pending | sent | dead; a pending row\n// with `locked_at` set is on the wire with some instance, and one whose lock is older than\n// ten minutes is presumed abandoned and claimable again.\n\nconst outboxTable = \"tesl_email_outbox\"\n\nfunc outboxTableDDL(qualified string) []string {\n\treturn []string{\n\t\t\"create table if not exists \" + qualified + \" (\" +\n\t\t\t\"id bigserial primary key, \" +\n\t\t\t\"recipient text, \" +\n\t\t\t\"subject text, \" +\n\t\t\t\"body_kind text, \" +\n\t\t\t\"body_text text, \" +\n\t\t\t\"body_html text, \" +\n\t\t\t\"status text, \" +\n\t\t\t\"attempts int, \" +\n\t\t\t\"next_attempt_at timestamptz, \" +\n\t\t\t\"locked_at timestamptz, \" +\n\t\t\t\"claim_token text, \" +\n\t\t\t\"created_at timestamptz default now(), \" +\n\t\t\t\"sent_at timestamptz)\",\n\t\t\"alter table \" + qualified + \" add column if not exists claim_token text\",\n\t\t\"create index if not exists \" + quoteIdentifier(outboxTable+\"_due_idx\") +\n\t\t\t\" on \" + qualified + \" (status, next_attempt_at, id)\",\n\t}\n}\n\n// emailClaimWindow is how long a claimed message stays another instance's before it may be\n// taken over \226\128\148 long enough for the SMTP exchange and its deadlines, short enough that a\n// crashed instance's mail is not stuck for the day.\nconst emailClaimWindow = 10 * time.Minute\n\ntype pgOutboxBackend struct {\n\tpgStore\n}\n\n// NewOutboxOn is `email E = Email { database: D \226\128\166 }` for a Postgres-backed D.\nfunc NewOutboxOn(database *Database, settings SmtpSettings) *Outbox {\n\toutbox := NewOutbox(settings)\n\toutbox.backend = &pgOutboxBackend{pgStore: pgStore{database: database}}\n\treturn outbox\n}\n\nfunc (backend *pgOutboxBackend) table() (*PostgresDB, string) {\n\tdb := backend.connection()\n\tensureTable(db, outboxTable, outboxTableDDL)\n\treturn db, db.QualifiedTable(outboxTable)\n}\n\n// bodyKind and bodyOfKind are the column form of the EmailBody ADT: the VARIANT is stored,\n// not inferred from which string is non-empty, so `HtmlBody \"\"` comes back as HTML.\nfunc bodyKind(body EmailBody) string {\n\tswitch body.Tag {\n\tcase EmailBodyHTML:\n\t\treturn \"html\"\n\tcase EmailBodyRich:\n\t\treturn \"rich\"\n\tcase EmailBodyText:\n\t\treturn \"text\"\n\tdefault:\n\t\treturn \"text\"\n\t}\n}\n\nfunc bodyOfKind(kind string, text, html *string) EmailBody {\n\tplain, markup := \"\", \"\"\n\tif text != nil {\n\t\tplain = *text\n\t}\n\tif html != nil {\n\t\tmarkup = *html\n\t}\n\tswitch kind {\n\tcase \"html\":\n\t\treturn HTMLBody(markup)\n\tcase \"rich\":\n\t\treturn RichBody(plain, markup)\n\tdefault:\n\t\treturn TextBody(plain)\n\t}\n}\n\nfunc emailStatusOf(text string) EmailStatus {\n\tswitch text {\n\tcase \"sent\":\n\t\treturn EmailSent\n\tcase \"dead\":\n\t\treturn EmailDead\n\tdefault:\n\t\treturn EmailPending\n\t}\n}\n\nfunc (backend *pgOutboxBackend) send(message EmailMessage) {\n\tdb, table := backend.table()\n\tPgExec(db, \"insert into \"+table+\" (recipient, subject, body_kind, body_text, body_html, \"+\n\t\t\"status, attempts, next_attempt_at) values ($1, $2, $3, $4, $5, 'pending', 0, now())\",\n\t\t[]any{message.To, message.Subject, bodyKind(message.Body), message.Body.Text, message.Body.HTML})\n}\n\nconst outboxColumns = \"id, recipient, subject, body_kind, body_text, body_html, status, attempts, \" +\n\t\"next_attempt_at, sent_at, claim_token\"\n\nfunc scanOutboxRow(row pgx.CollectableRow) (EmailMessage, error) {\n\tmessage := EmailMessage{}\n\tvar (\n\t\tid         int64\n\t\trecipient  *string\n\t\tsubject    *string\n\t\tkind       *string\n\t\ttext       *string\n\t\thtml       *string\n\t\tstatus     *string\n\t\tattempts   *int32\n\t\tnext       *time.Time\n\t\tsent       *time.Time\n\t\tclaimToken *string\n\t)\n\tif err := row.Scan(&id, &recipient, &subject, &kind, &text, &html, &status, &attempts,\n\t\t&next, &sent, &claimToken); err != nil {\n\t\treturn message, err\n\t}\n\tif id < 0 {\n\t\treturn message, fmt.Errorf(\"outbox row has a negative id %d\", id)\n\t}\n\tmessage.id = uint64(id)\n\tif recipient != nil {\n\t\tmessage.To = *recipient\n\t}\n\tif subject != nil {\n\t\tmessage.Subject = *subject\n\t}\n\tbodyKindText := \"text\"\n\tif kind != nil {\n\t\tbodyKindText = *kind\n\t}\n\tmessage.Body = bodyOfKind(bodyKindText, text, html)\n\tif status != nil {\n\t\tmessage.Status = emailStatusOf(*status)\n\t}\n\tif attempts != nil {\n\t\tmessage.Attempts = int(*attempts)\n\t}\n\tif next != nil {\n\t\tmessage.NextAttemptAt = *next\n\t}\n\tif sent != nil {\n\t\tmessage.SentAt = *sent\n\t}\n\tif claimToken != nil {\n\t\tmessage.claimToken = *claimToken\n\t}\n\treturn message, nil\n}\n\n// claimDue takes up to `limit` due messages for this pass by stamping `locked_at`. The lock\n// is what keeps a second instance off them: its own claim skips rows with a fresh lock, and\n// `skip locked` covers the instant between two claims running at once.\nfunc (backend *pgOutboxBackend) claimDue(limit int) []EmailMessage {\n\tdb, table := backend.table()\n\tclaimToken := UUIDv7()\n\treturn PgQuery(db, \"update \"+table+\" set locked_at = now(), claim_token = $3 where id in (\"+\n\t\t\"select id from \"+table+\" where status = 'pending' and next_attempt_at <= now() \"+\n\t\t\"and (locked_at is null or locked_at < now() - ($2::bigint * interval '1 millisecond')) \"+\n\t\t\"order by id for update skip locked limit $1) returning \"+outboxColumns,\n\t\t[]any{int32(min(max(limit, 1), 1<<30)), emailClaimWindow.Milliseconds(), claimToken}, // #nosec G115 -- clamped\n\t\tscanOutboxRow)\n}\n\nfunc (backend *pgOutboxBackend) recordOutcome(message EmailMessage, err error) bool {\n\tdb, table := backend.table()\n\tif message.id > uint64(1<<62) {\n\t\tpanic(\"email: outbox row id out of range\")\n\t}\n\tid := int64(message.id) // #nosec G115 -- range checked above\n\t// Zero rows in any branch means the lease was replaced; the stale SMTP result is discarded.\n\tif err == nil {\n\t\treturn PgExec(db, \"update \"+table+\" set status = 'sent', sent_at = now(), locked_at = null, \"+\n\t\t\t\"claim_token = null where id = $1 and status = 'pending' and claim_token = $2\",\n\t\t\t[]any{id, message.claimToken}) == 1\n\t}\n\tattempts := message.Attempts + 1\n\tif attempts >= emailMaxAttempts {\n\t\treturn PgExec(db, \"update \"+table+\" set status = 'dead', attempts = $2, locked_at = null, \"+\n\t\t\t\"claim_token = null where id = $1 and status = 'pending' and claim_token = $3\",\n\t\t\t[]any{id, int32(min(attempts, 1<<30)), message.claimToken}) == 1 // #nosec G115 -- clamped\n\t}\n\treturn PgExec(db, \"update \"+table+\" set attempts = $2, \"+\n\t\t\"next_attempt_at = now() + ($3::bigint * interval '1 millisecond'), locked_at = null, \"+\n\t\t\"claim_token = null where id = $1 and status = 'pending' and claim_token = $4\",\n\t\t[]any{id, int32(min(attempts, 1<<30)), emailRetryDelay(attempts).Milliseconds(),\n\t\t\tmessage.claimToken}) == 1 // #nosec G115 -- clamped\n}\n\nfunc (backend *pgOutboxBackend) messages() []EmailMessage {\n\tdb, table := backend.table()\n\treturn PgQuery(db, \"select \"+outboxColumns+\" from \"+table+\" order by id\", nil, scanOutboxRow)\n}\n\nfunc (backend *pgOutboxBackend) reset() {\n\tdb, table := backend.table()\n\tPgExec(db, \"delete from \"+table, nil)\n}\n\nfunc (backend *pgOutboxBackend) prune(keep time.Duration) {\n\tdb, table := backend.table()\n\tPgExec(db, \"delete from \"+table+\" where status = 'sent' and sent_at < now() - ($1::bigint * interval '1 millisecond')\",\n\t\t[]any{keep.Milliseconds()})\n}\n\n// \226\148\128\226\148\128 Cache \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// tesl_cache is UNLOGGED \226\128\148 no WAL, so a write costs what a cache write should, at the price\n// that a crash empties it, which for a cache is the right trade. One table per database,\n// with every `cache` declaration on it told apart by `cache_name`. The value is JSONB through\n// the declaration's codec; an entry that no longer decodes (the type changed under it) is a\n// miss and is removed, as Racket's was.\n\nconst cacheTable = \"tesl_cache\"\n\nfunc cacheTableDDL(qualified string) []string {\n\treturn []string{\n\t\t\"create unlogged table if not exists \" + qualified + \" (\" +\n\t\t\t\"cache_name text not null, \" +\n\t\t\t\"key text not null, \" +\n\t\t\t\"value jsonb not null, \" +\n\t\t\t\"expires_at timestamptz, \" +\n\t\t\t\"primary key (cache_name, key))\",\n\t}\n}\n\n// cacheSweepInterval bounds how often one process removes a cache's expired rows: a read\n// never answers an expired row (the predicate excludes it), so the sweep is housekeeping and\n// is done opportunistically on a write rather than by a goroutine of its own.\nconst cacheSweepInterval = time.Minute\n\ntype pgCacheBackend struct {\n\tpgStore\n\tname      string\n\tencode    func(any) any\n\tdecode    func(any) (any, error)\n\tlastSweep atomic.Int64 // unix nanoseconds\n}\n\n// NewCacheOn is `cache C = Cache { database: D \226\128\166 }` for a Postgres-backed D: the in-memory\n// cache plus the durable backend. `encode` and `decode` are the value type's JSON codec.\nfunc NewCacheOn[V any](database *Database, name string, defaultTTLSeconds int64,\n\tencode func(V) any, decode func(any) (V, error)) *Cache[V] {\n\tcache := NewCache[V](defaultTTLSeconds)\n\t// The typed codecs are adapted to `any` at the one place the type parameter is known.\n\tcache.backend = &pgCacheBackend{pgStore: pgStore{database: database}, name: name,\n\t\tencode: func(value any) any { return encode(value.(V)) },\n\t\tdecode: func(raw any) (any, error) { return decode(raw) }}\n\treturn cache\n}\n\nfunc (backend *pgCacheBackend) table() (*PostgresDB, string) {\n\tdb := backend.connection()\n\tensureTable(db, cacheTable, cacheTableDDL)\n\treturn db, db.QualifiedTable(cacheTable)\n}\n\nfunc (backend *pgCacheBackend) get(key string) (any, bool) {\n\tdb, table := backend.table()\n\trows := PgQuery(db, \"select value::text from \"+table+\" where cache_name = $1 and key = $2 \"+\n\t\t\"and (expires_at is null or expires_at > now())\", []any{backend.name, key}, scanText)\n\tif len(rows) == 0 {\n\t\treturn nil, false\n\t}\n\tparsed, err := ParseJSON([]byte(rows[0]))\n\tif err == nil {\n\t\tvar value any\n\t\tvalue, err = backend.decode(parsed)\n\t\tif err == nil {\n\t\t\treturn value, true\n\t\t}\n\t}\n\t// An entry this build cannot read is removed so the next read does not pay for it\n\t// again, and reported, since a cache that silently misses on every read of a key looks\n\t// like one that was never written.\n\tfmt.Fprintf(os.Stderr, \"tesl: cache %s: stored value for a key cannot be decoded and was removed: %v\\n\",\n\t\tbackend.name, err)\n\tPgExec(db, \"delete from \"+table+\" where cache_name = $1 and key = $2\", []any{backend.name, key})\n\treturn nil, false\n}\n\nfunc (backend *pgCacheBackend) set(key string, value any, ttlSeconds int64) {\n\tdb, table := backend.table()\n\tbackend.sweepExpired(db, table)\n\tPgExec(db, \"insert into \"+table+\" (cache_name, key, value, expires_at) values ($1, $2, $3::jsonb, \"+\n\t\t\"case when $4::bigint > 0 then now() + ($4::bigint * interval '1 second') else null end) \"+\n\t\t\"on conflict (cache_name, key) do update set value = excluded.value, expires_at = excluded.expires_at\",\n\t\t[]any{backend.name, key, jsonbText(backend.encode(value)), ttlSeconds})\n}\n\n// sweepExpired removes this cache's expired rows, at most once per cacheSweepInterval per\n// process. It runs on the write path only \226\128\148 a hot cache is written to, a cold one has\n// nothing worth sweeping.\nfunc (backend *pgCacheBackend) sweepExpired(db *PostgresDB, table string) {\n\tnow := time.Now().UnixNano()\n\tlast := backend.lastSweep.Load()\n\tif now-last < cacheSweepInterval.Nanoseconds() || !backend.lastSweep.CompareAndSwap(last, now) {\n\t\treturn\n\t}\n\tPgExec(db, \"delete from \"+table+\" where cache_name = $1 and expires_at is not null and expires_at < now()\",\n\t\t[]any{backend.name})\n}\n\nfunc (backend *pgCacheBackend) del(key string) {\n\tdb, table := backend.table()\n\tPgExec(db, \"delete from \"+table+\" where cache_name = $1 and key = $2\", []any{backend.name, key})\n}\n\n// invalidatePrefix removes every key that BEGINS WITH prefix, literally: `left(key,\n// length($2)) = $2` has no pattern semantics, where `key like $2 || '%'` would read a `%` or\n// `_` in the prefix as a wildcard and wipe far more than it names.\nfunc (backend *pgCacheBackend) invalidatePrefix(prefix string) {\n\tdb, table := backend.table()\n\tPgExec(db, \"delete from \"+table+\" where cache_name = $1 and left(key, length($2)) = $2\",\n\t\t[]any{backend.name, prefix})\n}\n\nfunc (backend *pgCacheBackend) reset() {\n\tdb, table := backend.table()\n\tPgExec(db, \"delete from \"+table+\" where cache_name = $1\", []any{backend.name})\n}\n\n// The lint gate on EMITTED code runs this file in every Postgres-backed program, including one\n// that declares no cache, and the `unused` analyser does not follow a generic type's methods\n// through interface dispatch. These assertions are the proof that each backend implements its\n// hook \226\128\148 and the reference that keeps a method used regardless of what the program declares.\nvar (\n\t_ cacheBackend  = (*pgCacheBackend)(nil)\n\t_ queueBackend  = (*pgQueueBackend)(nil)\n\t_ outboxBackend = (*pgOutboxBackend)(nil)\n)\n");
  ("prop.go", "package teslrt\n\nimport (\n\t\"fmt\"\n)\n\n// Property tests: `property \"name\" (n: Int) { \226\128\166 }` inside a `test` block, run many times over\n// generated values.\n//\n// The generators are `dsl/test-support.rkt`'s, value for value, because a property that holds\n// on one backend and fails on the other would otherwise be a difference in what was GENERATED\n// rather than in what the program does:\n//\n//\tInt      uniform in [-1_000_000, 1_000_000]\n//\tBool     a coin flip\n//\tString   \"s\" followed by a number below 1_000_000 \226\128\148 short, printable, and never empty\n//\tList T   0 to 7 elements, each generated by T's own generator\n//\tMaybe T  Nothing or Something, evenly\n//\n// A type with no generator is REFUSED at emission rather than generated as a zero: Racket's\n// fallback produces `0` for anything it does not know, and a property that \"passes\" over 200\n// copies of the same wrong-typed value tests nothing at all.\n//\n// Randomness is unseeded, as Racket's is: a property test is a search for a counterexample,\n// not a fixture, and the same seed every run would search the same 200 points forever. The\n// source is `crypto/rand` through `RandomInt`, for the reason the rest of this runtime uses it\n// \226\128\148 no Tesl surface can seed a generator, so there is nothing to gain from a weak one, and\n// gosec flags math/rand wherever it appears.\n\n// PropRandom is Racket's `tesl-prop-random`: a value in [0, bound). It is also what a custom\n// generator receives its variety from.\nfunc PropRandom(bound Int) Int {\n\tif Compare(bound, FromInt64(1)) < 0 {\n\t\tpanic(\"property generator: bound must be a positive Int, got \" + bound.String())\n\t}\n\treturn RandomInt(FromInt64(0), bound)\n}\n\n// PropInt generates a signed value around zero, so a property meets negatives, zero and\n// positives rather than only the happy side.\nfunc PropInt() Int {\n\treturn RandomInt(FromInt64(-1_000_000), FromInt64(1_000_001))\n}\n\nfunc PropBool() bool {\n\treturn Compare(RandomInt(FromInt64(0), FromInt64(2)), FromInt64(0)) == 0\n}\n\nfunc PropString() string {\n\treturn fmt.Sprintf(\"s%s\", RandomInt(FromInt64(0), FromInt64(1_000_000)).String())\n}\n\n// PropList generates 0 to 7 elements \226\128\148 the empty list included, since that is the case a\n// property over a list most often gets wrong.\nfunc PropList[Element any](element func() Element) []Element {\n\tcount, _ := RandomInt(FromInt64(0), FromInt64(8)).Int64()\n\tout := make([]Element, count)\n\tfor index := range out {\n\t\tout[index] = element()\n\t}\n\treturn out\n}\n\nfunc PropMaybe[Element any](element func() Element) Maybe[Element] {\n\tif Compare(RandomInt(FromInt64(0), FromInt64(2)), FromInt64(0)) == 0 {\n\t\treturn Nothing[Element]()\n\t}\n\treturn Something(element())\n}\n\n// The proof-aware generators.\n//\n// A record field carrying `Int ::: IsPositive n` cannot be drawn from the full Int range:\n// the property would be handed a value its own annotation says is impossible. Racket has\n// the same three, over the same ranges, so a property searches the same space on both\n// backends. Anything else falls back to the plain draw and the proof is not fabricated \226\128\148\n// what makes it true is the checker, not the generator.\n\nfunc PropPositiveInt() Int {\n\treturn Add(FromInt64(1), RandomInt(FromInt64(0), FromInt64(1_000_000)))\n}\n\nfunc PropNonNegativeInt() Int {\n\treturn RandomInt(FromInt64(0), FromInt64(1_000_000))\n}\n\nfunc PropNonZeroInt() Int {\n\tvalue := RandomInt(FromInt64(-1_000_000), FromInt64(1_000_001))\n\tif value.IsZero() {\n\t\treturn FromInt64(1)\n\t}\n\treturn value\n}\n");
  ("queue.go", "package teslrt\n\nimport (\n\t\"container/heap\"\n\t\"fmt\"\n\t\"sort\"\n\t\"sync\"\n\t\"time\"\n)\n\n// An in-memory job queue: the `backend: Memory` counterpart of tesl/queue.rkt's store.\n//\n// Jobs are dequeued in ENQUEUE ORDER. That is parity, not a detail: Racket's store is a\n// hash keyed by job id, and dequeuing it in hash order was a real bug (the PostgreSQL path\n// is `order by created_at asc`), fixed there with a monotonic sequence number. This store\n// keeps the sequence for the same reason.\n//\n// A payload is held as `any` because one queue may carry several job types; the emitter\n// knows them statically and passes a dispatcher that type-switches.\n//\n// BOUND. The store is in-process memory, and an HTTP endpoint that enqueues is a path from\n// the network into it; a pending backlog past maxPendingJobs makes `enqueue` trap rather than\n// grow without limit. The trap is loud by design \226\128\148 a queue that full is a system that has\n// stopped keeping up, and dropping the job silently would hide exactly that.\n//\n// CLAIM. The oldest pending (or dead) job is found through a min-heap on the sequence number\n// rather than a scan of every job, so a claim is O(log n) against a large backlog instead of\n// O(n) per claim (quadratic to drain). The heaps are indexes over `jobs`; the map stays the\n// record, which is also what the debugger's domain dump reads.\ntype Queue struct {\n\tmutex       sync.Mutex\n\tname        string\n\tmaxAttempts int\n\tmaxPending  int\n\tnextSeq     int64\n\tjobs        map[string]*queuedJob\n\tpendingHeap seqHeap\n\tdeadHeap    seqHeap\n\tpending     int\n\t// backend is the DURABLE store, when the declaration names a Postgres-backed database\n\t// (`NewQueueOn` in pgstores.go attaches it); nil for a Memory queue. Every public\n\t// operation asks `durable()` first and falls through to the in-memory store above when\n\t// the backend is absent OR its database is not bound \226\128\148 a `test` block without\n\t// `with database` keeps running on memory, a served program bound by `main`'s App\n\t// runs against the table.\n\tbackend queueBackend\n\t// wake is the worker doorbell: a buffered(1) channel `Enqueue` (and, for a durable\n\t// queue, the LISTEN loop on a `tesl_queue` notification from any instance) signals, and\n\t// an idle worker waits on with a fallback timeout \226\128\148 so a job is picked up within the\n\t// notification round trip rather than at the next poll, and an idle queue costs no\n\t// polling. tesl/queue.rkt did the same with a semaphore fed by a LISTEN thread.\n\twake chan struct{}\n}\n\n// queueBackend is what a durable job store answers. The interface is deliberately the\n// in-memory store's own vocabulary (status strings, attempts, DeadJob values) so the\n// public functions below dispatch with one `if` and neither path grows a semantics of its\n// own. It names no driver type: this file ships with every program, the Postgres\n// implementation (pgstores.go) only with one that declares a Postgres database.\ntype queueBackend interface {\n\t// active reports whether the store's database is bound right now.\n\tactive() bool\n\tenqueue(payload any) string\n\tdequeue(status string) (id string, payload any, attempts int, claimToken string, found bool)\n\tcomplete(id, claimToken string) bool\n\tfail(id string, attempts int, claimToken string) bool\n\tcount(status string) int\n\tdeadJobs(queue *Queue) []DeadJob\n\trequeue(id string) bool\n\treset()\n}\n\n// durable answers the backend this call runs against, or nil for the in-memory path.\nfunc (queue *Queue) durable() queueBackend {\n\tif backend := queue.backend; backend != nil && backend.active() {\n\t\treturn backend\n\t}\n\treturn nil\n}\n\ntype queuedJob struct {\n\tid       string\n\tpayload  any\n\tstatus   string // \"pending\" | \"processing\" | \"dead\" | \"dead_processing\"\n\tattempts int\n\tseq      int64\n}\n\n// JobStatus values a test can ask about.\nconst (\n\tjobPending    = \"pending\"\n\tjobProcessing = \"processing\"\n\tjobDead       = \"dead\"\n\t// A distinct in-flight state preserves which queue a stale claim must return to.\n\tjobDeadProcessing = \"dead_processing\"\n)\n\n// maxPendingJobs bounds one Memory queue's pending backlog.\nconst maxPendingJobs = 100000\n\n// seqHeap orders jobs by sequence number, oldest first. An entry is claimed lazily: a job\n// whose status no longer matches the heap it sits in (it was reset, or requeued out of the\n// dead letter) is skipped when it surfaces, which keeps every transition O(log n) with no\n// index bookkeeping.\ntype seqHeap []*queuedJob\n\nfunc (h seqHeap) Len() int           { return len(h) }\nfunc (h seqHeap) Less(i, j int) bool { return h[i].seq < h[j].seq }\nfunc (h seqHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }\nfunc (h *seqHeap) Push(x any)        { *h = append(*h, x.(*queuedJob)) }\nfunc (h *seqHeap) Pop() (popped any) {\n\told := *h\n\tn := len(old)\n\tpopped = old[n-1]\n\t// The vacated slot is not nil-ed: nilaway forbids a nil in a slice of `*queuedJob`, and\n\t// the slot is overwritten by the next push (the backing array is bounded by the heap's\n\t// high-water mark, which the queue's pending cap bounds in turn).\n\t*h = old[:n-1]\n\treturn popped\n}\nfunc (h *seqHeap) push(job *queuedJob) { heap.Push(h, job) }\n\n// pop answers the oldest job still in `status` and still in the store, discarding stale\n// entries on the way.\nfunc (h *seqHeap) pop(jobs map[string]*queuedJob, status string) (*queuedJob, bool) {\n\tfor h.Len() > 0 {\n\t\tjob := heap.Pop(h).(*queuedJob)\n\t\tif current, present := jobs[job.id]; present && current == job && job.status == status {\n\t\t\treturn job, true\n\t\t}\n\t}\n\treturn nil, false\n}\n\nfunc NewQueue(name string, maxAttempts int) *Queue {\n\tif maxAttempts < 1 {\n\t\tmaxAttempts = 1\n\t}\n\treturn &Queue{name: name, maxAttempts: maxAttempts, maxPending: maxPendingJobs,\n\t\tjobs: map[string]*queuedJob{}, wake: make(chan struct{}, 1)}\n}\n\n// Wake rings the worker doorbell without blocking: a doorbell already rung stays rung once.\nfunc (queue *Queue) Wake() {\n\tselect {\n\tcase queue.wake <- struct{}{}:\n\tdefault:\n\t}\n}\n\n// waitForWork blocks an idle worker until the doorbell rings or `fallback` elapses \226\128\148 the\n// fallback is what catches a notification lost to a reconnecting LISTEN connection.\nfunc (queue *Queue) waitForWork(fallback time.Duration) {\n\ttimer := time.NewTimer(fallback)\n\tdefer timer.Stop()\n\tselect {\n\tcase <-queue.wake:\n\tcase <-timer.C:\n\t}\n}\n\n// Queue metrics, named as tesl/queue.rkt named them so a dashboard survives the backend\n// change: a counter per enqueue and per outcome, and the worker's run time.\nfunc queueMetric(name, queue string, delta int64) {\n\tCounter(name, FromInt64(delta), []Tuple2[string, string]{{Tuple2First: \"tesl.queue\", Tuple2Second: queue}})\n}\n\n// Enqueue stores a payload and answers the new job's id.\n//\n// The id is a UUID v7, NOT a counter: a process-local counter replayed ids after a restart,\n// which let a committed job id collide with a fresh one (the same reasoning as the Racket\n// side's move off gensym).\nfunc Enqueue(queue *Queue, payload any) string {\n\tqueueMetric(\"tesl.queue.enqueued\", queue.name, 1)\n\tif backend := queue.durable(); backend != nil {\n\t\tid := backend.enqueue(payload)\n\t\t// Local workers wake now; workers on other instances wake on the NOTIFY the\n\t\t// backend queued with the row (delivered when the enclosing transaction commits).\n\t\tqueue.Wake()\n\t\treturn id\n\t}\n\tqueue.mutex.Lock()\n\tdefer queue.mutex.Unlock()\n\tif queue.pending >= queue.maxPending {\n\t\tpanic(fmt.Sprintf(\"enqueue: queue %s is full \226\128\148 %d jobs are pending and the in-memory \"+\n\t\t\t\"store is bounded at %d; workers are not keeping up with producers\",\n\t\t\tqueue.name, queue.pending, queue.maxPending))\n\t}\n\tid := UUIDv7()\n\tqueue.nextSeq++\n\tjob := &queuedJob{id: id, payload: payload, status: jobPending, seq: queue.nextSeq}\n\tqueue.jobs[id] = job\n\tqueue.pendingHeap.push(job)\n\tqueue.pending++\n\tqueue.Wake()\n\treturn id\n}\n\nfunc PendingJobCount(queue *Queue) Int {\n\tif backend := queue.durable(); backend != nil {\n\t\treturn FromInt64(int64(backend.count(jobPending)))\n\t}\n\tqueue.mutex.Lock()\n\tdefer queue.mutex.Unlock()\n\treturn FromInt64(int64(queue.pending))\n}\n\nfunc DeadJobCount(queue *Queue) Int {\n\tif backend := queue.durable(); backend != nil {\n\t\treturn FromInt64(int64(backend.count(jobDead)))\n\t}\n\treturn FromInt64(int64(queue.countWithStatus(jobDead)))\n}\n\nfunc (queue *Queue) countWithStatus(status string) int {\n\tqueue.mutex.Lock()\n\tdefer queue.mutex.Unlock()\n\tmatched := 0\n\tfor _, job := range queue.jobs {\n\t\tif job.status == status {\n\t\t\tmatched++\n\t\t}\n\t}\n\treturn matched\n}\n\n// dequeue claims the OLDEST job with `status`, marking it processing. The heap hands back\n// the job itself, not an id to re-read from the map: a second lookup would be a map read\n// whose success only the surrounding lock explains, which is exactly what nilaway (in the\n// emitted-code gate) refuses to take on trust.\nfunc (queue *Queue) dequeue(status string) (string, any, int, string, bool) {\n\tif backend := queue.durable(); backend != nil {\n\t\treturn backend.dequeue(status)\n\t}\n\tqueue.mutex.Lock()\n\tdefer queue.mutex.Unlock()\n\tindex := &queue.pendingHeap\n\tif status == jobDead {\n\t\tindex = &queue.deadHeap\n\t}\n\tjob, found := index.pop(queue.jobs, status)\n\tif !found {\n\t\treturn \"\", nil, 0, \"\", false\n\t}\n\tif status == jobPending {\n\t\tqueue.pending--\n\t}\n\tjob.status = jobProcessing\n\tif status == jobDead {\n\t\tjob.status = jobDeadProcessing\n\t}\n\treturn job.id, job.payload, job.attempts, \"\", true\n}\n\n// DeadJob is one entry in a queue's dead letter. It is OPAQUE to Tesl \226\128\148 `deadJobs` is typed\n// `List DeadJob` and the type has no accessors \226\128\148 so it carries the job's identity for the\n// runtime's use and nothing a program can read: what a test does with the list is count it.\ntype DeadJob struct {\n\tID string\n\t// The queue the job came out of. `requeue job` names no queue \226\128\148 the value carries it, as\n\t// Racket's dead-job carries its queue-spec \226\128\148 so this is what makes that call resolvable.\n\tqueue *Queue\n}\n\n// DeadJobs is the dead letter's contents, oldest first. The order is by enqueue sequence\n// rather than by map iteration, matching the PostgreSQL path's `order by created_at asc`.\nfunc DeadJobs(queue *Queue) []DeadJob {\n\tif backend := queue.durable(); backend != nil {\n\t\treturn backend.deadJobs(queue)\n\t}\n\tqueue.mutex.Lock()\n\tdefer queue.mutex.Unlock()\n\ttype entry struct {\n\t\tid  string\n\t\tseq int64\n\t}\n\tfound := make([]entry, 0, len(queue.jobs))\n\tfor id, job := range queue.jobs {\n\t\tif job.status == jobDead {\n\t\t\tfound = append(found, entry{id: id, seq: job.seq})\n\t\t}\n\t}\n\tsort.Slice(found, func(left, right int) bool { return found[left].seq < found[right].seq })\n\tdead := make([]DeadJob, 0, len(found))\n\tfor _, each := range found {\n\t\tdead = append(dead, DeadJob{ID: each.id, queue: queue})\n\t}\n\treturn dead\n}\n\n// ResetQueue empties the store, for a test block that starts from a fresh queue. The\n// sequence counter is deliberately NOT reset: it only has to be monotonic, and a counter that\n// restarts is how job ids came to repeat once already.\nfunc ResetQueue(queue *Queue) {\n\tif backend := queue.durable(); backend != nil {\n\t\tbackend.reset()\n\t\treturn\n\t}\n\tqueue.mutex.Lock()\n\tdefer queue.mutex.Unlock()\n\tqueue.jobs = map[string]*queuedJob{}\n\tqueue.pendingHeap = nil\n\tqueue.deadHeap = nil\n\tqueue.pending = 0\n}\n\n// JobOutcome is what a worker run produced, for the `expectJobOk` style assertions.\ntype JobOutcome struct {\n\tRan     bool   // a job was claimed at all\n\tOK      bool   // the worker returned without rejecting or trapping\n\tMessage string // the rejection or trap message, when OK is false\n}\n\n// ProcessNextJob runs the next pending job through `handler` and applies the retry rule:\n// success completes the job, failure increments attempts and either re-queues it or \226\128\148 once\n// attempts reach maxAttempts \226\128\148 moves it to the dead letter. Identical to the Racket\n// in-memory path, including that a TRAP counts as a failed attempt rather than propagating.\n//\n// The retry BACKOFF delay is deliberately not simulated on the in-memory path: the in-memory\n// Racket path does not sleep either, and a test that had to wait for an exponential backoff\n// would be a slow test rather than a truthful one. The durable store applies it as the row's\n// `next_attempt_at` (pgstores.go), which the claim respects.\nfunc ProcessNextJob(queue *Queue, handler func(any) JobOutcome) JobOutcome {\n\tid, payload, attempts, claimToken, found := queue.dequeue(jobPending)\n\tif !found {\n\t\treturn JobOutcome{}\n\t}\n\tstarted := time.Now()\n\toutcome := runJob(handler, payload)\n\tHistogram(\"tesl.queue.job.duration\", time.Since(started).Seconds(),\n\t\t[]Tuple2[string, string]{{Tuple2First: \"tesl.queue\", Tuple2Second: queue.name}})\n\tif outcome.OK {\n\t\tif queue.complete(id, claimToken) {\n\t\t\tqueueMetric(\"tesl.queue.completed\", queue.name, 1)\n\t\t}\n\t} else {\n\t\tif queue.fail(id, attempts, claimToken) {\n\t\t\tqueueMetric(\"tesl.queue.failed\", queue.name, 1)\n\t\t}\n\t}\n\toutcome.Ran = true\n\treturn outcome\n}\n\n// ProcessNextDeadJob is the dead-letter counterpart: it claims a job that exhausted its\n// attempts and hands it to the dead-letter worker. A dead job is REMOVED whatever the handler\n// outcome \226\128\148 there is no second dead letter to fall into. A fenced completion is a store failure,\n// not a handler outcome, and is surfaced so the replacement claim is not mistaken for removal.\nfunc ProcessNextDeadJob(queue *Queue, handler func(any) JobOutcome) JobOutcome {\n\tid, payload, _, claimToken, found := queue.dequeue(jobDead)\n\tif !found {\n\t\treturn JobOutcome{}\n\t}\n\toutcome := runJob(handler, payload)\n\tif !queue.complete(id, claimToken) {\n\t\tpanic(\"queue \" + queue.name + \": dead-letter completion lost ownership of job \" + id)\n\t}\n\toutcome.Ran = true\n\treturn outcome\n}\n\n// DrainQueue processes pending jobs until none remain, and reports how many ran. It stops\n// at `limit` attempts so a job that keeps failing back into the queue cannot spin forever.\nfunc DrainQueue(queue *Queue, handler func(any) JobOutcome, limit int) Int {\n\tran := 0\n\tfor ran < limit {\n\t\tif outcome := ProcessNextJob(queue, handler); !outcome.Ran {\n\t\t\tbreak\n\t\t}\n\t\tran++\n\t}\n\treturn FromInt64(int64(ran))\n}\n\n// A worker that traps is a FAILED ATTEMPT, not a crashed process: the Racket path wraps the\n// handler in `with-handlers` and calls fail-job!, so the queue keeps its retry semantics.\nfunc runJob(handler func(any) JobOutcome, payload any) (outcome JobOutcome) {\n\tdefer func() {\n\t\tif recovered := recover(); recovered != nil {\n\t\t\toutcome = JobOutcome{OK: false, Message: fmt.Sprint(recovered)}\n\t\t}\n\t}()\n\treturn handler(payload)\n}\n\nfunc (queue *Queue) complete(id, claimToken string) bool {\n\tif backend := queue.durable(); backend != nil {\n\t\treturn backend.complete(id, claimToken)\n\t}\n\tqueue.mutex.Lock()\n\tdefer queue.mutex.Unlock()\n\tif _, found := queue.jobs[id]; !found {\n\t\treturn false\n\t}\n\tdelete(queue.jobs, id)\n\treturn true\n}\n\nfunc (queue *Queue) fail(id string, attempts int, claimToken string) bool {\n\tif backend := queue.durable(); backend != nil {\n\t\treturn backend.fail(id, attempts, claimToken)\n\t}\n\tqueue.mutex.Lock()\n\tdefer queue.mutex.Unlock()\n\tjob, found := queue.jobs[id]\n\tif !found {\n\t\treturn false\n\t}\n\tjob.attempts = attempts + 1\n\tif job.attempts >= queue.maxAttempts {\n\t\tjob.status = jobDead\n\t\tqueue.deadHeap.push(job)\n\t} else {\n\t\t// The job keeps its sequence number, so a retry goes back to the FRONT of the\n\t\t// line \226\128\148 the order the scan-based claim always had.\n\t\tjob.status = jobPending\n\t\tqueue.pendingHeap.push(job)\n\t\tqueue.pending++\n\t}\n\treturn true\n}\n\n// JobResult is what an api-test's `processNextJob` answers: the job that ran, and \226\128\148 when\n// the worker rejected or trapped \226\128\148 the error alongside it. `JobFailed` carries BOTH, as it\n// does on the Racket side (`JobFailed job error`), so a test can assert on the payload of a\n// job that failed.\n//\n// Runtime-provided like Maybe and Either, since a JobResult crosses module boundaries.\ntype JobResult[Payload any] struct {\n\tTag         JobResultTag\n\tOkJob       Payload\n\tFailedJob   Payload\n\tFailedError string\n}\n\ntype JobResultTag int\n\nconst (\n\tJobResultOk JobResultTag = iota\n\tJobResultFailed\n)\n\nfunc JobOk[Payload any](job Payload) JobResult[Payload] {\n\treturn JobResult[Payload]{Tag: JobResultOk, OkJob: job}\n}\n\nfunc JobFailed[Payload any](job Payload, failure string) JobResult[Payload] {\n\treturn JobResult[Payload]{Tag: JobResultFailed, FailedJob: job, FailedError: failure}\n}\n\n// ExpectJobOk is the api-test assertion: the job, or a trap naming the worker's failure.\nfunc ExpectJobOk[Payload any](result JobResult[Payload]) Payload {\n\tif result.Tag != JobResultOk {\n\t\tpanic(\"expectJobOk: expected JobOk but the worker failed with \" + result.FailedError)\n\t}\n\treturn result.OkJob\n}\n\n// ExpectJobFailed is its counterpart: the job that failed, or a trap.\n// ExpectJobFailed answers the ERROR, not the job: `tesl/api-test.rkt` returns\n// `JobFailed-error` here, and a test written against it (`expect isNotNull err`) reads a\n// message rather than a payload. The job is still reachable through the `JobResult` itself.\nfunc ExpectJobFailed[Payload any](result JobResult[Payload]) string {\n\tif result.Tag != JobResultFailed {\n\t\tpanic(\"expectJobFailed: expected JobFailed but the worker succeeded\")\n\t}\n\treturn result.FailedError\n}\n\n// EmptyQueue is the trap an api-test gets when it asks for a job and there is none \226\128\148 the\n// same failure Racket raises, with the same hint, because the usual cause is that the HTTP\n// action meant to enqueue the job did not run.\nfunc EmptyQueue(queueName, who string) string {\n\treturn fmt.Sprintf(\"%s: queue %s is empty \226\128\148 expected at least one pending job\\n\"+\n\t\t\"hint: did the HTTP action that enqueues the job run and return a success status?\",\n\t\twho, queueName)\n}\n\n// EnqueueJob is `enqueue`, whose Tesl type is Unit: the job id is not surfaced to the\n// program (Racket's enqueue! answers void too), so the id stays internal to the store.\nfunc EnqueueJob(queue *Queue, payload any) struct{} {\n\tEnqueue(queue, payload)\n\treturn struct{}{}\n}\n\n// Requeue resets a dead job to pending with a fresh attempt count, so the workers pick it up\n// again. It answers whether the job was there to reset \226\128\148 a job the dead letter no longer holds\n// is `False` rather than a trap, which is Racket's answer for the same case.\n//\n// \"There\" means IN the dead letter: a job a dead-letter worker has already claimed is in\n// flight, and resetting it to pending would run it twice \226\128\148 once more by an ordinary worker,\n// while the dead-letter worker's completion then deleted whichever copy was left. So an\n// in-flight job answers `False` too: from the dead letter's point of view it has left.\nfunc Requeue(job DeadJob) bool {\n\tif job.queue == nil {\n\t\treturn false\n\t}\n\tif backend := job.queue.durable(); backend != nil {\n\t\treturn backend.requeue(job.ID)\n\t}\n\tjob.queue.mutex.Lock()\n\tdefer job.queue.mutex.Unlock()\n\tfound, present := job.queue.jobs[job.ID]\n\tif !present || found.status != jobDead {\n\t\treturn false\n\t}\n\tfound.status = jobPending\n\tfound.attempts = 0\n\tjob.queue.pendingHeap.push(found)\n\tjob.queue.pending++\n\treturn true\n}\n");
  ("random.go", "package teslrt\n\nimport (\n\t\"crypto/rand\"\n\t\"encoding/hex\"\n\t\"fmt\"\n\t\"math/big\"\n\t\"time\"\n)\n\n// Randomness is an effect Tesl gates behind the `random` capability, which the checker\n// enforces; nothing about that survives to run time.\n//\n// The source is crypto/rand rather than math/rand: a Tesl program cannot seed a generator\n// (there is no such surface), so a predictable stream would be a security property nobody\n// asked for, and gosec flags math/rand for exactly that reason.\n\n// RandomInt is `randomInt lo hi`: a uniform draw from [lo, hi). The caller proves lo < hi \226\128\148\n// the range is a compile-time obligation on the inputs \226\128\148 so an empty range is a trap rather\n// than a silent lo.\nfunc RandomInt(low, high Int) Int {\n\tspan := Sub(high, low)\n\tif Compare(span, FromInt64(1)) < 0 {\n\t\tpanic(\"randomInt: the range is empty (high must be greater than low)\")\n\t}\n\toffset, err := rand.Int(rand.Reader, span.bigInt())\n\tif err != nil {\n\t\tpanic(\"randomInt: no randomness available: \" + err.Error())\n\t}\n\treturn Add(low, fromBig(offset))\n}\n\n// RandomFloat is `randomFloat()`: a uniform draw from [0, 1), a fresh value per call.\n//\n// It is built from 53 random bits divided by 2^53 \226\128\148 the number of bits a float64 can hold\n// exactly \226\128\148 so every representable value in the range is reachable and none is favoured.\nfunc RandomFloat() float64 {\n\tconst bits = 1 << 53\n\tdrawn, err := rand.Int(rand.Reader, big.NewInt(bits))\n\tif err != nil {\n\t\tpanic(\"randomFloat: no randomness available: \" + err.Error())\n\t}\n\treturn float64(drawn.Int64()) / float64(bits)\n}\n\n// GeneratePrefixedId is `generatePrefixedId prefix`: `<prefix>-<32 hex chars>`, 16 CSPRNG\n// bytes rendered as hex, matching `tesl-generate-prefixed-id`. An id is often used as a\n// token, so it must be unguessable \226\128\148 the shape (prefix, dash, 32 hex digits) is part of the\n// contract, since ids land in URLs and databases.\nfunc GeneratePrefixedId(prefix string) string {\n\traw := make([]byte, 16)\n\tif _, err := rand.Read(raw); err != nil {\n\t\tpanic(\"generateId: no randomness available: \" + err.Error())\n\t}\n\treturn prefix + \"-\" + hex.EncodeToString(raw)\n}\n\n// GenerateId is `generateId()`: the same value with an empty prefix, so it still begins\n// with the dash \226\128\148 parity with Racket, which appends the separator unconditionally.\nfunc GenerateId() string {\n\treturn GeneratePrefixedId(\"\")\n}\n\n// UUIDv7 is a time-ordered UUID: 48 bits of Unix milliseconds, then random bits, with the\n// version and variant nibbles set (RFC 9562). The layout matches `uuid-v7-string` in\n// tesl/private/uuid-gen.rkt byte for byte, so an id generated on either backend sorts and\n// parses the same way.\n//\n// Time-ordered matters for the queue: a job id that is monotonic makes \"oldest first\"\n// recoverable from the id alone, and a v4 id would not.\nfunc UUIDv7() string {\n\tmilliseconds := time.Now().UnixMilli()\n\traw := make([]byte, 16)\n\tif _, err := rand.Read(raw[6:]); err != nil {\n\t\tpanic(\"UUID.v7: no randomness available: \" + err.Error())\n\t}\n\t// Masked, not just shifted: the truncation to a byte is the POINT (a 48-bit timestamp\n\t// spread over six bytes), and gosec's integer-overflow check is right to ask that it be\n\t// written explicitly rather than left to conversion.\n\tstamp := uint64(milliseconds)\n\traw[0] = byte((stamp >> 40) & 0xff)\n\traw[1] = byte((stamp >> 32) & 0xff)\n\traw[2] = byte((stamp >> 24) & 0xff)\n\traw[3] = byte((stamp >> 16) & 0xff)\n\traw[4] = byte((stamp >> 8) & 0xff)\n\traw[5] = byte(stamp & 0xff)\n\traw[6] = 0x70 | (raw[6] & 0x0f)\n\traw[8] = 0x80 | (raw[8] & 0x3f)\n\treturn fmt.Sprintf(\"%x-%x-%x-%x-%x\", raw[0:4], raw[4:6], raw[6:8], raw[8:10], raw[10:16])\n}\n\n// UUIDv4 is a RANDOM UUID: 122 random bits with the version and variant nibbles set\n// (RFC 9562), the same layout `uuid-v4-string` writes in tesl/private/uuid-gen.rkt.\n//\n// Randomness comes from crypto/rand, not math/rand, for the reason every id in this file\n// does: a UUID is routinely used as an unguessable handle, and a predictable one is a\n// vulnerability rather than a collision.\nfunc UUIDv4() string {\n\traw := make([]byte, 16)\n\tif _, err := rand.Read(raw); err != nil {\n\t\tpanic(\"UUID.v4: no randomness available: \" + err.Error())\n\t}\n\traw[6] = 0x40 | (raw[6] & 0x0f)\n\traw[8] = 0x80 | (raw[8] & 0x3f)\n\treturn fmt.Sprintf(\"%x-%x-%x-%x-%x\", raw[0:4], raw[4:6], raw[6:8], raw[8:10], raw[10:16])\n}\n\n// ValidUUID reports the 8-4-4-4-12 hex shape, in either case \226\128\148 the same set\n// `uuid-regexp` accepts in tesl/uuid.rkt. It is written as a scan rather than as a regular\n// expression so the runtime carries no regexp engine for one shape.\nfunc ValidUUID(value string) bool {\n\tif len(value) != 36 {\n\t\treturn false\n\t}\n\tfor index := 0; index < len(value); index++ {\n\t\tcharacter := value[index]\n\t\tswitch index {\n\t\tcase 8, 13, 18, 23:\n\t\t\tif character != '-' {\n\t\t\t\treturn false\n\t\t\t}\n\t\tdefault:\n\t\t\tisDigit := character >= '0' && character <= '9'\n\t\t\tisLower := character >= 'a' && character <= 'f'\n\t\t\tisUpper := character >= 'A' && character <= 'F'\n\t\t\tif !isDigit && !isLower && !isUpper {\n\t\t\t\treturn false\n\t\t\t}\n\t\t}\n\t}\n\treturn true\n}\n\n// UUIDValidate is `UUID.validate`: a CHECK, so an invalid string is a 400 the request\n// answers with rather than a trap. The proof it mints (`IsUuid`) erases, so what survives\n// is the string it verified.\nfunc UUIDValidate(value string) Check[string] {\n\tif !ValidUUID(value) {\n\t\treturn Reject[string](400, \"not a valid UUID\")\n\t}\n\treturn Accept(value)\n}\n");
  ("regex.go", "package teslrt\n\nimport (\n\t\"container/list\"\n\t\"regexp\"\n\t\"strconv\"\n\t\"sync\"\n\t\"unicode/utf8\"\n)\n\n// `Tesl.Regex` \226\128\148 regular expressions over String.\n//\n// Every pattern is argument 1 and is a STRING LITERAL the compiler has already checked\n// (`compiler/lib/regex_lint.ml`, VREGEX001-4): it must parse in Tesl's subset, it may not\n// backtrack catastrophically, and each of its capture groups must participate in every\n// successful match. This module is written as if none of that were true, because it is the\n// last line of defence.\n//\n// ONE DELIBERATE DIFFERENCE FROM THE RACKET RUNTIME, and it is a strengthening: Racket's\n// matcher backtracks, so it runs every match in its own thread under a wall-clock deadline\n// (TESL_REGEX_TIMEOUT_MS) to bound a pathological pattern to one slice instead of the\n// process. Go's regexp is RE2 \226\128\148 it runs in time linear in the length of the input and the\n// pattern, and it cannot express the constructs that make backtracking blow up\n// (backreferences, lookaround), which are the same constructs the compiler's lint already\n// refuses. The bound the deadline existed to provide therefore holds by construction, and a\n// timeout knob that can never fire would be a promise about scheduling rather than about\n// work. The INPUT bound is kept: it is about memory, not backtracking.\n//\n// The other property worth naming is in Replace: the replacement is inserted LITERALLY.\n\n// tesl-regex-max-input on the Racket side: an upper bound on the subject, in characters.\nfunc regexMaxInput() int {\n\treturn envPositiveInt(\"TESL_REGEX_MAX_INPUT_BYTES\", 1048576)\n}\n\n// The compile cache is BOUNDED. The compiler only ever emits literal patterns, so a program's\n// working set is a handful of them \226\128\148 but a program that has shed Tesl, or a pattern built\n// from request data, could feed the cache an unbounded stream of distinct patterns, and an\n// unbounded map of compiled programs is a memory sink. An LRU of regexCacheCapacity entries\n// keeps every pattern a real program uses hot while a hostile stream only churns.\nconst regexCacheCapacity = 256\n\nvar (\n\tregexCacheMutex sync.Mutex\n\tregexCache      = map[string]*list.Element{}\n\tregexCacheOrder = list.New() // front = most recently used\n)\n\ntype regexCacheEntry struct {\n\tpattern  string\n\tcompiled *regexp.Regexp\n}\n\n// RegexCompile compiles and memoises a pattern. A pattern that does not compile is a clean\n// trap naming it, not a raw error from the engine.\nfunc RegexCompile(who, pattern string) *regexp.Regexp {\n\tregexCacheMutex.Lock()\n\tif element, cached := regexCache[pattern]; cached {\n\t\tregexCacheOrder.MoveToFront(element)\n\t\tcompiled := element.Value.(regexCacheEntry).compiled\n\t\tregexCacheMutex.Unlock()\n\t\treturn compiled\n\t}\n\tregexCacheMutex.Unlock()\n\tcompiled, err := regexp.Compile(pattern)\n\tif err != nil {\n\t\tpanic(who + \": pattern \" + strconv.Quote(pattern) + \" does not compile: \" + err.Error())\n\t}\n\tregexCacheMutex.Lock()\n\tdefer regexCacheMutex.Unlock()\n\tif element, cached := regexCache[pattern]; cached {\n\t\t// Another goroutine compiled the same pattern between the two locks; keep one.\n\t\tregexCacheOrder.MoveToFront(element)\n\t\treturn element.Value.(regexCacheEntry).compiled\n\t}\n\tfor regexCacheOrder.Len() >= regexCacheCapacity {\n\t\toldest := regexCacheOrder.Back()\n\t\tif oldest == nil {\n\t\t\tbreak\n\t\t}\n\t\tdelete(regexCache, oldest.Value.(regexCacheEntry).pattern)\n\t\tregexCacheOrder.Remove(oldest)\n\t}\n\tregexCache[pattern] = regexCacheOrder.PushFront(regexCacheEntry{pattern: pattern, compiled: compiled})\n\treturn compiled\n}\n\n// regexCacheSize is the number of compiled patterns held, for the runtime's own tests.\nfunc regexCacheSize() int {\n\tregexCacheMutex.Lock()\n\tdefer regexCacheMutex.Unlock()\n\treturn regexCacheOrder.Len()\n}\n\nfunc regexSubject(who, input string) string {\n\tlimit := regexMaxInput()\n\t// Characters, not bytes, matching the Racket runtime's `string-length` \226\128\148 the two agree\n\t// on where the line is for a subject that is not pure ASCII. Counted in place: a\n\t// `[]rune` conversion would allocate four bytes per character of a subject that may be\n\t// a megabyte, just to measure it.\n\tif length := utf8.RuneCountInString(input); length > limit {\n\t\tpanic(who + \": input of \" + strconv.Itoa(length) + \" characters exceeds the \" +\n\t\t\tstrconv.Itoa(limit) + \" character regex input limit\" +\n\t\t\t\"\\n  (raise TESL_REGEX_MAX_INPUT_BYTES if this is intentional)\")\n\t}\n\treturn input\n}\n\n// RegexMatches reports whether the pattern matches ANYWHERE in the input. Anchor with ^ and\n// $ to require a whole-string match.\nfunc RegexMatches(pattern, input string) bool {\n\treturn RegexCompile(\"Regex.matches\", pattern).\n\t\tMatchString(regexSubject(\"Regex.matches\", input))\n}\n\n// RegexFind answers the text of the first match. Nothing and an empty match are different\n// answers, which is why the index form decides rather than the string form.\nfunc RegexFind(pattern, input string) Maybe[string] {\n\tcompiled := RegexCompile(\"Regex.find\", pattern)\n\tsubject := regexSubject(\"Regex.find\", input)\n\tspan := compiled.FindStringIndex(subject)\n\tif span == nil {\n\t\treturn Nothing[string]()\n\t}\n\treturn Something(subject[span[0]:span[1]])\n}\n\n// RegexFindAll answers every non-overlapping match, left to right.\nfunc RegexFindAll(pattern, input string) []string {\n\tfound := RegexCompile(\"Regex.findAll\", pattern).\n\t\tFindAllString(regexSubject(\"Regex.findAll\", input), -1)\n\tif found == nil {\n\t\treturn []string{}\n\t}\n\treturn found\n}\n\n// RegexCaptures answers the capture groups of the first match, in source order, EXCLUDING\n// the whole match \226\128\148 use RegexFind for that. A pattern with no groups answers `Something []`\n// on a match.\n//\n// The list is `List String` rather than `List (Maybe String)` because the compiler rejects\n// patterns whose groups can fail to participate (VREGEX004); the empty string for a\n// non-participating group is unreachable for a checked pattern and exists so this function\n// is total on its own.\nfunc RegexCaptures(pattern, input string) Maybe[[]string] {\n\tmatch := RegexCompile(\"Regex.captures\", pattern).\n\t\tFindStringSubmatch(regexSubject(\"Regex.captures\", input))\n\tif match == nil {\n\t\treturn Nothing[[]string]()\n\t}\n\tgroups := make([]string, 0, len(match)-1)\n\tgroups = append(groups, match[1:]...)\n\treturn Something(groups)\n}\n\n// RegexReplace replaces EVERY match. The replacement is inserted LITERALLY: `$1`, `\\1` and\n// `&` are ordinary characters, not group references, so a replacement built from user data\n// can never be reinterpreted as a substitution directive. Go's ReplaceAllString DOES expand\n// `$1`, which is why this is the Literal form and not that one.\nfunc RegexReplace(pattern, input, replacement string) string {\n\treturn RegexCompile(\"Regex.replace\", pattern).\n\t\tReplaceAllLiteralString(regexSubject(\"Regex.replace\", input), replacement)\n}\n\n// RegexSplit splits on every match. Adjacent matches and matches at the ends produce empty\n// strings, exactly as String.split does.\nfunc RegexSplit(pattern, input string) []string {\n\tparts := RegexCompile(\"Regex.split\", pattern).\n\t\tSplit(regexSubject(\"Regex.split\", input), -1)\n\tif parts == nil {\n\t\treturn []string{}\n\t}\n\treturn parts\n}\n");
  ("request.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"io\"\n\t\"net\"\n\t\"net/http\"\n\t\"os\"\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n)\n\n// RequestScope is the per-request state the Racket runtime keeps in a `parameterize`\n// scope: the cookies a handler has recorded on the response being built.\n//\n// Capabilities are deliberately NOT here. Every capability site in the AST carries a\n// STATIC list of names \226\128\148 `requires [...]`, `withCapabilities [...]`, `serve`, `workers` \226\128\148\n// so the granted set at any point is known at compile time and the checker already\n// verifies each call against it. A runtime check would compare two compile-time constants.\n// Keeping one would also force this scope through every capability-gated function, which\n// is exactly the blast radius the call-graph threading exists to avoid. Racket checks at\n// runtime because its capability set is a dynamic parameter; that mechanism is also what\n// broke capability delegation at deferred tool execution (\"passes test, fails live\"), a\n// failure mode a compile-time-only design does not have.\n//\n// This type exists because Go has no goroutine-local storage. A Racket parameter is\n// thread-local and every request is served on its own thread, so a handler deep in a call\n// chain can call `Http.clearSessionCookie` and the runtime knows which response it belongs\n// to. In Go the scope has to be passed explicitly \226\128\148 and the emitter passes it ONLY to the\n// functions whose call graph actually reaches a scope-using leaf, so ordinary pure\n// functions keep their plain signatures and the emitted code still reads like Go someone\n// would write.\n//\n// A nil scope means \"no live HTTP response\", which is exactly the Racket condition that\n// raises: startup code, `main`, and queue workers have no response to attach a cookie to.\ntype RequestScope struct {\n\t// Full `Set-Cookie` header values, in send order.\n\tcookies []string\n}\n\nfunc NewRequestScope() *RequestScope {\n\treturn &RequestScope{}\n}\n\n// SetCookieHeader records one complete `Set-Cookie` value. LAST CALL WINS PER COOKIE\n// NAME, and send order is otherwise preserved \226\128\148 the same rule dsl/response-cookies.rkt\n// states, so `setSessionCookie` followed by `clearSessionCookie` emits exactly one\n// `Set-Cookie` for that name rather than two contradictory ones.\nfunc (scope *RequestScope) SetCookieHeader(who, value string) {\n\tif scope == nil {\n\t\tpanic(who + \": no HTTP response to attach a cookie to.\\n\" +\n\t\t\t\"  it is only callable while serving an HTTP request \226\128\148 from a handler body, an\\n\" +\n\t\t\t\"  `auth` block, or an SSE subscribe.  Startup, `main` and queue-worker code have\\n\" +\n\t\t\t\"  no HTTP response.\")\n\t}\n\tname := value\n\tif index := strings.IndexByte(value, '='); index >= 0 {\n\t\tname = value[:index]\n\t}\n\tfor index, existing := range scope.cookies {\n\t\texistingName := existing\n\t\tif at := strings.IndexByte(existing, '='); at >= 0 {\n\t\t\texistingName = existing[:at]\n\t\t}\n\t\tif existingName == name {\n\t\t\tscope.cookies[index] = value\n\t\t\treturn\n\t\t}\n\t}\n\tscope.cookies = append(scope.cookies, value)\n}\n\n// CookieHeaders hands back a copy, so a caller cannot reach the scope's own storage.\n//\n// An EMPTY slice rather than nil for \"no scope\": callers range over or index the result, and\n// nilaway is right that a nil return travelling into a slice operation is a nil-panic waiting\n// for the one caller who forgets to check.\nfunc (scope *RequestScope) CookieHeaders() []string {\n\tif scope == nil {\n\t\treturn []string{}\n\t}\n\tout := make([]string, len(scope.cookies))\n\tcopy(out, scope.cookies)\n\treturn out\n}\n\n// The session cookie's shape is fixed by tesl/http.rkt and must match byte for byte:\n// the name is `__Host-`-prefixed (so the browser enforces Secure + host-only + Path=/),\n// and SameSite=Lax rather than Strict so following an ordinary link back into the app\n// arrives authenticated.\nconst (\n\tsessionCookieName       = \"__Host-session\"\n\tsessionCookieAttributes = \"Path=/; HttpOnly; Secure; SameSite=Lax\"\n)\n\n// ClearSessionCookie is the logout half: same cookie, same attributes, empty value and\n// `Max-Age=0`, which is how a browser is told to drop it. It removes the BROWSER's copy\n// and does not invalidate the token \226\128\148 the same documented limitation Racket carries.\n// Returns Tesl's Unit (an empty struct), so the emitted code can use it in value\n// position the way a Tesl expression of type Unit is used.\nfunc ClearSessionCookie(scope *RequestScope) struct{} {\n\tscope.SetCookieHeader(\"Http.clearSessionCookie\",\n\t\tfmt.Sprintf(\"%s=; %s; Max-Age=0\", sessionCookieName, sessionCookieAttributes))\n\treturn struct{}{}\n}\n\n// HttpRequest is what an `auth` function and a handler see of the incoming request.\n// It is a plain value built once per request by the dispatcher \226\128\148 the fields Tesl exposes,\n// nothing more, so an ejecting author is not handed the whole net/http surface.\n//\n// The maps are teslrt.Dict values because that is what Tesl's `Dict.lookup` expects.\n// A Dict is stored sorted by key, and these are built with plain string ordering, which is\n// exactly the comparator the emitter passes at a `Dict.lookup` call site on String keys.\ntype HttpRequest struct {\n\tMethod          string\n\tPath            string\n\tCookies         Dict[string, string]\n\tHeaders         Dict[string, string]\n\tQueryParameters Dict[string, string]\n\tBody            string\n\tClientAddress   string\n}\n\n// ReadRequestBody reads a request body under the SAME cap `dsl/web.rkt` applies.\n//\n// The body is read whole into memory and parsed, so an unbounded one lets a client exhaust\n// memory and CPU with a single request. The limit is `TESL_MAX_BODY_BYTES` when it names a\n// positive number, else 1 MiB \226\128\148 generous for a typed JSON API, and the same default and variable\n// the Racket runtime reads, so the two refuse the same requests.\n//\n// Answers the body plus a status and message: 0 means the body is usable, 413 that it exceeded\n// the cap, 400 that the connection failed mid-read. The caller turns that into a rejection,\n// because a runtime that wrote the response itself would bypass the handler's own error shape.\nfunc ReadRequestBody(request *http.Request) ([]byte, int, string) {\n\tlimit := maxRequestBodyBytes()\n\t// One byte OVER the cap distinguishes \"exactly at the limit\" from \"too long\" without reading\n\t// the rest of an arbitrarily large body.\n\traw, err := io.ReadAll(io.LimitReader(request.Body, int64(limit)+1))\n\tif err != nil {\n\t\treturn nil, 400, \"Missing JSON payload\"\n\t}\n\tif len(raw) > limit {\n\t\treturn nil, 413, \"Request body too large\"\n\t}\n\treturn raw, 0, \"\"\n}\n\n// CheckJSONPayload is the rest of `dsl/web.rkt`'s `parse-json-body`, for an endpoint that\n// DECLARES a body: the content type must say JSON, and the body must not be empty.\n//\n// Emitted only where a payload is declared, which is where Racket applies it \226\128\148 an `auth` that\n// verifies a MAC over the raw bytes reads the body of a request that may legitimately not be JSON\n// at all.\n//\n// Answers a status and message, 0 for \"usable\", the same shape `ReadRequestBody` uses so the\n// emitted handler has one refusal idiom rather than two.\nfunc CheckJSONPayload(request *http.Request, body []byte) (int, string) {\n\t// `Contains` rather than an exact compare: a real content type carries parameters\n\t// (`application/json; charset=utf-8`), and this is the same substring test the Racket side\n\t// makes with `#rx\"application/json\"`.\n\tif !strings.Contains(strings.ToLower(request.Header.Get(\"Content-Type\")), \"application/json\") {\n\t\treturn 415, \"Expected application/json payload\"\n\t}\n\tif len(body) == 0 {\n\t\treturn 400, \"Missing JSON payload\"\n\t}\n\treturn 0, \"\"\n}\n\nfunc maxRequestBodyBytes() int {\n\tmaxBodyOnce.Do(func() {\n\t\tmaxBodyBytes = 1 << 20\n\t\tif declared, err := strconv.Atoi(strings.TrimSpace(os.Getenv(\"TESL_MAX_BODY_BYTES\"))); err == nil && declared > 0 {\n\t\t\tmaxBodyBytes = declared\n\t\t}\n\t})\n\treturn maxBodyBytes\n}\n\nvar (\n\tmaxBodyOnce  sync.Once\n\tmaxBodyBytes int\n)\n\n// NewHttpRequest snapshots the request. Header names are lower-cased so a lookup does not\n// depend on the casing a client happened to send; cookie names are left exactly as sent.\n//\n// A REPEATED name \226\128\148 `?q=first&q=second`, or two `X-Forwarded-For` headers \226\128\148 collapses to the\n// LAST value, because a Dict holds one value per key and that is the answer the Racket runtime\n// gives: both its header and query hashes are built with `for/hash`, which keeps the last\n// binding. Taking the first instead is the natural Go spelling (`Query().Get`) and the wrong\n// one; `tests/query-parameters-tests.tesl` pins the rule.\nfunc NewHttpRequest(request *http.Request, body string, trustedProxies ...string) HttpRequest {\n\theaders := DictEmpty[string, string]()\n\tfor name, values := range request.Header {\n\t\tif len(values) > 0 {\n\t\t\theaders = DictInsert(headers, strings.ToLower(name), values[len(values)-1], stringKeyLess)\n\t\t}\n\t}\n\tcookies := DictEmpty[string, string]()\n\tfor _, cookie := range request.Cookies() {\n\t\tcookies = DictInsert(cookies, cookie.Name, cookie.Value, stringKeyLess)\n\t}\n\tquery := DictEmpty[string, string]()\n\tfor name, values := range request.URL.Query() {\n\t\tif len(values) > 0 {\n\t\t\tquery = DictInsert(query, name, values[len(values)-1], stringKeyLess)\n\t\t}\n\t}\n\treturn HttpRequest{\n\t\tMethod:          request.Method,\n\t\tPath:            request.URL.Path,\n\t\tCookies:         cookies,\n\t\tHeaders:         headers,\n\t\tQueryParameters: query,\n\t\tBody:            body,\n\t\tClientAddress:   clientAddressOf(request, trustedProxies),\n\t}\n}\n\nfunc canonicalClientAddress(raw string) string {\n\tvalue := strings.TrimSpace(raw)\n\tif host, _, err := net.SplitHostPort(value); err == nil {\n\t\tvalue = host\n\t}\n\tvalue = strings.Trim(value, \"[]\")\n\tif ip := net.ParseIP(value); ip != nil {\n\t\treturn ip.String()\n\t}\n\treturn value\n}\n\n// clientAddressOf trusts forwarded addresses only when every hop to the socket is a declared\n// proxy. Walking from the socket toward the client stops at the first undeclared hop, so a\n// prepended client-controlled value is never selected.\nfunc clientAddressOf(request *http.Request, trustedProxies []string) string {\n\tpeer := canonicalClientAddress(request.RemoteAddr)\n\tif len(trustedProxies) == 0 {\n\t\treturn peer\n\t}\n\ttrusted := make(map[string]struct{}, len(trustedProxies))\n\tfor _, proxy := range trustedProxies {\n\t\ttrusted[canonicalClientAddress(proxy)] = struct{}{}\n\t}\n\tchain := make([]string, 0, len(request.Header.Values(\"X-Forwarded-For\"))+1)\n\tfor _, header := range request.Header.Values(\"X-Forwarded-For\") {\n\t\tfor _, value := range strings.Split(header, \",\") {\n\t\t\tif value = canonicalClientAddress(value); value != \"\" {\n\t\t\t\tchain = append(chain, value)\n\t\t\t}\n\t\t}\n\t}\n\tif peer != \"\" {\n\t\tchain = append(chain, peer)\n\t}\n\tfor index := len(chain) - 1; index >= 0; index-- {\n\t\tif _, isTrusted := trusted[chain[index]]; !isTrusted {\n\t\t\treturn chain[index]\n\t\t}\n\t}\n\tpanic(\"HttpRequest.clientAddress: trustedProxies declared but the forwarded chain has no untrusted hop\")\n}\n\n// SetSessionCookie is `Http.setSessionCookie`: the ONE blessed session transport. The name is\n// `__Host-`-prefixed so the browser enforces Secure, host-only and Path=/, and the lifetime\n// matches the token's own TTL \226\128\148 a cookie that outlived its token would only produce 401s.\n// The TTL is the `sessionPolicy` clause's (`sessionPolicySeconds`), the same number `JWT.sign`\n// stamps into `exp` and the SSO callback writes: under `ShortSession` a hard-coded 3600 kept\n// a dead 900-second token in the browser for 45 minutes, so the two session writers disagreed.\n//\n// There is no name parameter and no attribute parameter: every option here is a way to get it\n// wrong, and the fixed shape is what makes `Http.sessionToken` able to read it back.\nfunc SetSessionCookie(scope *RequestScope, token JwtToken) struct{} {\n\t// The value must LOOK like a signed token \226\128\148 three non-empty base64url segments. A session\n\t// cookie carrying anything else is a misuse (writing an unverified cookie value straight\n\t// back, say), and writing it would mint a session out of attacker-supplied text. Racket\n\t// applies the same shape check for the same reason, and the trap is contained by the\n\t// router's sanitized 500 rather than reaching the client.\n\tif !looksLikeJWT(token.Value) {\n\t\tpanic(fmt.Sprintf(\"Http.setSessionCookie: expected a JwtToken produced by `JWT.sign`, \"+\n\t\t\t\"got %q.\\n  A session cookie must carry a signed token; this value is not a\\n\"+\n\t\t\t\"  well-formed JWT and will not be written to the response.\", token.Value))\n\t}\n\tscope.SetCookieHeader(\"Http.setSessionCookie\",\n\t\tfmt.Sprintf(\"%s=%s; %s; Max-Age=%d\",\n\t\t\tsessionCookieName, token.Value, sessionCookieAttributes, sessionPolicySeconds()))\n\treturn struct{}{}\n}\n\n// looksLikeJWT is the wire SHAPE only \226\128\148 `header.payload.signature`, base64url \226\128\148 never a\n// verification. Deciding whether a token is authentic is `JWT.verify`'s job, and conflating the\n// two here would be the more dangerous kind of check: one that looks like a guarantee.\nfunc looksLikeJWT(value string) bool {\n\tsegments := strings.Split(value, \".\")\n\tif len(segments) != 3 {\n\t\treturn false\n\t}\n\tfor _, segment := range segments {\n\t\tif segment == \"\" {\n\t\t\treturn false\n\t\t}\n\t\tfor _, character := range segment {\n\t\t\tisBase64URL := (character >= 'A' && character <= 'Z') ||\n\t\t\t\t(character >= 'a' && character <= 'z') ||\n\t\t\t\t(character >= '0' && character <= '9') ||\n\t\t\t\tcharacter == '_' || character == '-'\n\t\t\tif !isBase64URL {\n\t\t\t\treturn false\n\t\t\t}\n\t\t}\n\t}\n\treturn true\n}\n\n// SessionToken is `Http.sessionToken`: the reader, so the fixed cookie name is written down\n// once rather than spelled out at every call site \226\128\148 where a typo is a permanent 401. It is pure\n// and ungated; `JWT.verify` is what sits between this and a fact.\nfunc SessionToken(request HttpRequest) Maybe[JwtToken] {\n\tvalue, found := DictLookup(request.Cookies, sessionCookieName, stringKeyLess).Value()\n\tif !found {\n\t\treturn Nothing[JwtToken]()\n\t}\n\treturn Something(JwtToken{Value: value})\n}\n\n// ResponseCookie is the api-test reader: the session cookie a response set, as a\n// Cookie-header-ready `name=value` pair, so a round-trip test can feed it straight back. The\n// ATTRIBUTES are stripped deliberately \226\128\148 assert those against the raw `set-cookie` header,\n// which is the full line.\nfunc ResponseCookie(response ApiResponse) Maybe[string] {\n\tline, found := DictLookup(response.Headers, \"set-cookie\", stringKeyLess).Value()\n\tif !found {\n\t\treturn Nothing[string]()\n\t}\n\t// The pair is everything up to the first `;`. Indexed only after a length check: a split\n\t// result is a slice whose emptiness nothing here guarantees to a reader (or to nilaway).\n\tsegments := strings.Split(line, \";\")\n\tif len(segments) == 0 {\n\t\treturn Nothing[string]()\n\t}\n\tpair := strings.TrimSpace(segments[0])\n\tif !strings.Contains(pair, \"=\") {\n\t\treturn Nothing[string]()\n\t}\n\treturn Something(pair)\n}\n");
  ("result.go", "package teslrt\n\n// Result is Tesl's `Result ok err`: Ok carries the value, Err the failure. Like Maybe and\n// Either it lives in the runtime because a Result crosses module boundaries, and it uses\n// the same flat tag+payload shape the emitter generates for a user ADT.\n//\n// The zero value is an Ok holding the zero value of Ok \226\128\148 the tag order below \226\128\148 which is the\n// one asymmetry worth stating: a zero Result reads as success. Emitted code never produces\n// one (every construction names a constructor), and Tesl has no way to observe an\n// uninitialised value, so this is a Go-level note rather than a semantic choice.\ntype Result[Ok any, Err any] struct {\n\tTag      ResultTag\n\tOkValue  Ok\n\tErrValue Err\n}\n\n// ResultTag identifies which side a Result holds. The constants are an enum-like set so the\n// `exhaustive` linter can verify a switch over them.\ntype ResultTag int\n\nconst (\n\tResultOk ResultTag = iota\n\tResultErr\n)\n\n// MakeOk and MakeErr exist for hand-written runtime code and readable tests; emitted code\n// writes the composite literal directly. They are not named `Ok`/`Err` because those are\n// the FIELD-bearing type parameters above, and a function may not share a name with them.\nfunc MakeOk[Ok any, Err any](value Ok) Result[Ok, Err] {\n\treturn Result[Ok, Err]{Tag: ResultOk, OkValue: value}\n}\n\nfunc MakeErr[Ok any, Err any](failure Err) Result[Ok, Err] {\n\treturn Result[Ok, Err]{Tag: ResultErr, ErrValue: failure}\n}\n\n// IsOk reports which side is held.\nfunc (r Result[Ok, Err]) IsOk() bool {\n\treturn r.Tag == ResultOk\n}\n");
  ("secret.go", "package teslrt\n\nimport (\n\t\"crypto/subtle\"\n\t\"database/sql/driver\"\n\t\"fmt\"\n\t\"io\"\n)\n\n// SecretRedaction is the one string every sink substitutes for a secret's payload.\n//\n// Fixed, and deliberately carrying no length, prefix or hash of the value: partial\n// disclosure in a log or a debugger is the convenience that erodes the guarantee. Same text\n// as `secret-redaction-text` in dsl/types.rkt, so the two backends redact identically.\nconst SecretRedaction = \"[redacted]\"\n\n// SecretString is the payload of a `secret` newtype over String.\n//\n// It is a distinct type rather than a bare string so that a `%v`/`%s` of it \226\128\148 a log line, a\n// panic message, a test failure \226\128\148 prints the redaction instead of the plaintext. The\n// plaintext is reached through `Reveal`, which is spelled to be searchable: a review can ask\n// where it is called.\ntype SecretString struct {\n\tplaintext string\n}\n\nfunc MakeSecret(plaintext string) SecretString {\n\treturn SecretString{plaintext: plaintext}\n}\n\n// Format makes redaction the DEFAULT for EVERY verb. fmt consults `Stringer`/`GoStringer`\n// only for `%v %s %x %X %q` and `%#v`; any other verb \226\128\148 `%d`, `%b`, `%o`, a typo \226\128\148 fell back\n// to struct printing, which rendered the unexported field as `{%!d(string=<plaintext>)}`. A\n// `Formatter` is consulted first for every verb, so there is no verb left that discloses.\n// Flags and width are ignored on purpose: a padded or truncated redaction is still the same\n// fixed text, never a partial disclosure.\nfunc (secret SecretString) Format(state fmt.State, _ rune) {\n\t_, _ = io.WriteString(state, SecretRedaction)\n}\n\n// String keeps the non-fmt callers (string builders, a `Stringer`-typed parameter) redacting\n// too; fmt itself goes through Format above.\nfunc (secret SecretString) String() string { return SecretRedaction }\n\n// GoString covers callers that ask for the Go-syntax form directly.\nfunc (secret SecretString) GoString() string { return SecretRedaction }\n\n// MarshalJSON keeps a secret out of an encoded payload the same way, rather than relying on\n// every codec to remember.\nfunc (secret SecretString) MarshalJSON() ([]byte, error) {\n\treturn []byte(`\"` + SecretRedaction + `\"`), nil\n}\n\n// Reveal hands back the plaintext. Every use is a deliberate disclosure \226\128\148 sending it on the\n// wire, hashing it, comparing it \226\128\148 and is meant to be greppable.\nfunc (secret SecretString) Reveal() string { return secret.plaintext }\n\n// SecretEqual compares two secrets without an early-exit data dependency, so a caller\n// cannot learn a prefix from how long the comparison took. `subtle.ConstantTimeCompare`\n// itself returns 0 for differing LENGTHS without comparing, which is the same shape Racket's\n// `constant-time-bytes=?/secret` has.\nfunc SecretEqual(left, right SecretString) bool {\n\treturn subtle.ConstantTimeCompare([]byte(left.plaintext), []byte(right.plaintext)) == 1\n}\n\n// SecretParam is how a `secret` column's value reaches a SQL statement. Storage is the one\n// place the plaintext legitimately travels, so the emitter used to bind `.Value.Reveal()` \226\128\148\n// a bare string \226\128\148 and every path that RENDERS a bound parameter (the `--debug` SQL capture's\n// `Params` and `Preview`, a trap message quoting the arguments) saw the plaintext (whitebox\n// campaign, 2026-09-02). This type carries the secret to the driver through `driver.Valuer`,\n// which pgx honours when encoding, while every rendering path \226\128\148 fmt, Stringer, JSON \226\128\148 sees\n// the redaction, exactly as for SecretString.\ntype SecretParam struct {\n\tsecret SecretString\n}\n\n// PgSecret is the binding the emitter writes for a `secret` column.\nfunc PgSecret(secret SecretString) SecretParam { return SecretParam{secret: secret} }\n\n// Value hands the plaintext to the database driver \226\128\148 the storage disclosure, and nothing else.\nfunc (param SecretParam) Value() (driver.Value, error) { return param.secret.Reveal(), nil }\n\nfunc (param SecretParam) Format(state fmt.State, _ rune) {\n\t_, _ = io.WriteString(state, SecretRedaction)\n}\nfunc (param SecretParam) String() string   { return SecretRedaction }\nfunc (param SecretParam) GoString() string { return SecretRedaction }\nfunc (param SecretParam) MarshalJSON() ([]byte, error) {\n\treturn []byte(`\"` + SecretRedaction + `\"`), nil\n}\n");
  ("serve.go", "package teslrt\n\nimport (\n\t\"context\"\n\t\"errors\"\n\t\"fmt\"\n\t\"net\"\n\t\"net/http\"\n\t\"net/url\"\n\t\"os\"\n\t\"os/signal\"\n\t\"path\"\n\t\"path/filepath\"\n\t\"strings\"\n\t\"sync\"\n\t\"syscall\"\n\t\"time\"\n)\n\n// Activation: what `main` returning an `App { \226\128\166 }` becomes.\n//\n// The App record is not a runtime value \226\128\148 the compiler lowers it into the startup chain it\n// describes (start each queue's workers, then serve), so what is left here are the two things\n// that chain calls. Everything the App configures is therefore decided at compile time and read\n// here as ordinary arguments.\n\n// ServeOptions is what an `App` says about the HTTP surface. Grouped in a struct rather than\n// passed positionally because most programs set only `Port`, and a five-argument call whose\n// middle three are usually zero reads worse in the emitted code than a literal with named\n// fields.\ntype ServeOptions struct {\n\tPort int\n\t// StaticDir serves files, with an index.html SPA fallback, when set.\n\tStaticDir string\n\t// MountPath scopes exactly the DECLARED api surface (`/api`), while static files, the SPA\n\t// fallback and the health probe keep answering on the raw path \226\128\148 the same split the Racket\n\t// runtime makes, and for its reason: the SPA is precisely the other thing sharing this\n\t// origin that the prefix exists to separate the API from.\n\tMountPath string\n\t// ListenAddress is the interface to bind, from the `listenAddress` server clause:\n\t// \"127.0.0.1\" for `Loopback` (the server sits behind a reverse proxy) and empty for\n\t// `AllInterfaces`. Empty binds every interface, which is Go's and Racket's default.\n\tListenAddress string\n}\n\n// Serve runs the HTTP server until the process is asked to stop, then drains in-flight requests.\n//\n// Timeouts are set rather than left at Go's defaults (which are \"none\"): a server with no read\n// timeout can be held open by a slow client indefinitely, which is the same class of problem the\n// outbound deadlines close on the client side. `ReadHeaderTimeout` in particular is what stops a\n// Slowloris-style hold.\n// Answers Tesl's Unit (an empty struct) rather than nothing, so the emitted `main` can return it\n// the way it returns any other statement's value \226\128\148 the same shape `EnqueueJob` and the cookie\n// writers use.\nfunc Serve(server Server, options ServeOptions) struct{} {\n\tport := options.Port\n\tif port == 0 {\n\t\tport = 8080\n\t}\n\thandler := server.handlerWith(options)\n\thttpServer := newHTTPServer(handler, bindAddress(options), serveWriteTimeout)\n\t// Graceful: an interrupt stops accepting and lets in-flight requests finish, so a deploy does\n\t// not answer a request with a truncated response.\n\tshutdown, stop := signal.NotifyContext(context.Background(),\n\t\tos.Interrupt, syscall.SIGTERM)\n\tdefer stop()\n\tgo func() {\n\t\t<-shutdown.Done()\n\t\tdrain, cancel := context.WithTimeout(context.Background(), 15*time.Second)\n\t\tdefer cancel()\n\t\t_ = httpServer.Shutdown(drain)\n\t}()\n\tannounced := options.ListenAddress\n\tif announced == \"\" {\n\t\tannounced = \"localhost\"\n\t}\n\tfmt.Fprintf(os.Stderr, \"tesl: serving on http://%s:%d\\n\", announced, port)\n\t// main's generated debug scope lives for the server lifetime. Mark the\n\t// blocking lifecycle wait quiescent so a request breakpoint does not wait for\n\t// main to reach a checkpoint that cannot occur until the server exits.\n\tresumeDebugExecution := debugLifecycleQuiesce()\n\terr := httpServer.ListenAndServe()\n\tresumeDebugExecution()\n\tif err != nil && !errors.Is(err, http.ErrServerClosed) {\n\t\tpanic(\"serve: \" + err.Error())\n\t}\n\treturn struct{}{}\n}\n\n// serveWriteTimeout is the per-response write deadline `Serve` installs. Go arms it ONCE per\n// request, so it bounds a whole response \226\128\148 the right shape for a JSON answer and the wrong one\n// for an `sse` stream that lives for the connection; the stream re-arms its own rolling deadline\n// (see `sseWriteDeadline`) instead of inheriting this one.\nconst serveWriteTimeout = 60 * time.Second\n\n// newHTTPServer is the ONE place the production `http.Server` is configured, so a test can run\n// the same server with a shortened `writeTimeout` and meet exactly the deadlines a deployment\n// does. An `httptest.Server` has no timeouts at all, which is how \"WriteTimeout cuts every SSE\n// stream at 60 s\" stayed invisible to every api-test.\nfunc newHTTPServer(handler http.Handler, address string, writeTimeout time.Duration) *http.Server {\n\treturn &http.Server{\n\t\tAddr:              address,\n\t\tHandler:           handler,\n\t\tReadHeaderTimeout: 10 * time.Second,\n\t\tReadTimeout:       30 * time.Second,\n\t\tWriteTimeout:      writeTimeout,\n\t\tIdleTimeout:       120 * time.Second,\n\t}\n}\n\n// bindAddress is where the listener goes: the `listenAddress` clause's interface and the port.\n// Named because it is a RULE rather than a format string \226\128\148 an empty interface binds every one of\n// them, which is the difference between a service a reverse proxy reaches and one the whole\n// network reaches.\nfunc bindAddress(options ServeOptions) string {\n\tport := options.Port\n\tif port == 0 {\n\t\tport = 8080\n\t}\n\treturn fmt.Sprintf(\"%s:%d\", options.ListenAddress, port)\n}\n\n// handlerWith wraps the router with the static-file surface an App may declare. The API routes\n// are reached under `MountPath`; everything else the runtime owns answers on the raw path.\nfunc (server Server) handlerWith(options ServeOptions) http.Handler {\n\tmount := strings.Trim(options.MountPath, \"/\")\n\tstatic := options.StaticDir\n\treturn http.HandlerFunc(func(raw http.ResponseWriter, request *http.Request) {\n\t\t// Every response \226\128\148 API, static file and SPA fallback alike \226\128\148 carries the security header\n\t\t// floor, which is where `dsl/web.rkt` puts it (`harden-servlet` wraps the servlet, after\n\t\t// the two direct-response paths were found carrying none).\n\t\twriter := &hardenedWriter{ResponseWriter: raw}\n\t\t// Runtime-owned SSO routes must win over the static SPA fallback. Without\n\t\t// this check, /auth/<segment>/login serves index.html and the browser never\n\t\t// reaches the provider's login form.\n\t\tif _, _, matched := findSsoMatch(server.SsoRoutes, request.URL.Path); matched {\n\t\t\tserver.ServeHTTP(writer, request)\n\t\t\treturn\n\t\t}\n\t\trouted := request\n\t\tif mount != \"\" {\n\t\t\trequestPath := strings.TrimPrefix(request.URL.Path, \"/\")\n\t\t\t// SSO paths belong to the runtime, not the declared API, so they stay raw.\n\t\t\tif _, _, matched := findSsoMatch(server.SsoRoutes, request.URL.Path); matched {\n\t\t\t\tserver.ServeHTTP(writer, request)\n\t\t\t\treturn\n\t\t\t}\n\t\t\tif requestPath != mount && !strings.HasPrefix(requestPath, mount+\"/\") {\n\t\t\t\t// Not under the mount prefix: only the static surface can answer it.\n\t\t\t\tif static != \"\" && serveStatic(writer, request, static) {\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\twriteResponse(writer, nil, Fail(404, \"not found\"))\n\t\t\t\treturn\n\t\t\t}\n\t\t\ttrimmed := strings.TrimPrefix(requestPath, mount)\n\t\t\trouted = request.Clone(request.Context())\n\t\t\tif trimmed == \"\" {\n\t\t\t\ttrimmed = \"/\"\n\t\t\t}\n\t\t\tif !strings.HasPrefix(trimmed, \"/\") {\n\t\t\t\ttrimmed = \"/\" + trimmed\n\t\t\t}\n\t\t\trouted.URL.Path = trimmed\n\t\t\t// UNDER the mount prefix the declared API is the only surface. The prefix exists to\n\t\t\t// separate the API from the SPA sharing the origin, so a mounted path the API does\n\t\t\t// not declare is an API miss and gets the API's JSON 404 (or 405) \226\128\148 not index.html\n\t\t\t// with a 200, which is what a client that mistyped `/api/task` would otherwise be\n\t\t\t// told to parse as JSON.\n\t\t\t//\n\t\t\t// The runtime-owned SSO routes are excluded: they answer on the RAW path (matched\n\t\t\t// above) and are not part of the declared API, so `/api/auth/<seg>/login` is a miss\n\t\t\t// rather than a second door to the login flow.\n\t\t\tif _, _, matched := findSsoMatch(server.SsoRoutes, routed.URL.Path); matched {\n\t\t\t\twriteResponse(writer, nil, Fail(404, \"not found\"))\n\t\t\t\treturn\n\t\t\t}\n\t\t\tserver.ServeHTTP(writer, routed)\n\t\t\treturn\n\t\t}\n\t\tif server.declaredRouteExists(routed) {\n\t\t\tserver.ServeHTTP(writer, routed)\n\t\t\treturn\n\t\t}\n\t\tif static != \"\" && serveStatic(writer, request, static) {\n\t\t\treturn\n\t\t}\n\t\tserver.ServeHTTP(writer, routed)\n\t})\n}\n\n// declaredRouteExists reports whether the declared API has this path \226\128\148 used to decide between\n// the mounted API and static surfaces without accidentally mounting runtime-owned SSO routes.\nfunc (server Server) declaredRouteExists(request *http.Request) bool {\n\tfor _, route := range server.Routes {\n\t\tif pathMatches(route.Path, request.URL.Path) {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// serveStatic answers a GET from the static directory, falling back to index.html so a\n// single-page app's client-side routes load. Reports whether it answered.\n//\n// Three rules keep this from becoming an arbitrary-file read, and they are checked in the order\n// a request meets them:\n//\n//   - The path is cleaned and checked LEXICALLY to be inside the directory: `..` segments and\n//     absolute paths are the textbook traversal, and an encoded one has been decoded by the\n//     time it is here.\n//   - A segment beginning with `.` is never served. A static directory is usually a build\n//     output, and build outputs carry `.env`, `.git/config`, editor backups \226\128\148 files that are\n//     next to the SPA rather than part of it. (`.well-known/` falls under this too; it is a\n//     deliberate trade, since nothing here can tell it from `.git/`.)\n//   - Symlinks are RESOLVED \226\128\148 on the candidate AND on the root \226\128\148 and containment is re-checked\n//     on the resolved paths. `pnpm` and nix both link build inputs from outside the tree, and\n//     `http.ServeFile` follows a link wherever it points; resolving the root as well means a\n//     root that is itself a symlink (a `current -> release-N` deploy) still contains its files.\n//\n// A dotfile path is not served AND does not fall back to index.html: it reaches the router's\n// own 404, because answering the SPA for `/.env` would be a 200 that says nothing was wrong. A\n// symlink that leaves the root is treated as a file that is not there \226\128\148 its target is never\n// read, and the path gets whatever any unknown path gets (the SPA index, or the 404).\nfunc serveStatic(writer http.ResponseWriter, request *http.Request, directory string) bool {\n\tif request.Method != http.MethodGet && request.Method != http.MethodHead {\n\t\treturn false\n\t}\n\troot, err := resolvedStaticRoot(directory)\n\tif err != nil {\n\t\treturn false\n\t}\n\trelative := strings.TrimPrefix(path.Clean(\"/\"+request.URL.Path), \"/\")\n\tif hasDotSegment(relative) {\n\t\treturn false\n\t}\n\tif relative == \"\" {\n\t\trelative = \"index.html\"\n\t}\n\tif file := containedStaticFile(root, relative); file != \"\" {\n\t\thttp.ServeFile(writer, request, file)\n\t\treturn true\n\t}\n\t// The SPA fallback: an unknown path serves index.html, so client-side routing works on a\n\t// cold load. Only when there IS an index.html \226\128\148 otherwise the router's own 404 is the honest\n\t// answer.\n\tif file := containedStaticFile(root, \"index.html\"); file != \"\" {\n\t\thttp.ServeFile(writer, request, file)\n\t\treturn true\n\t}\n\treturn false\n}\n\n// resolvedStaticRoot is the static directory with every symlink followed, so that the\n// containment check below compares resolved paths on both sides.\nfunc resolvedStaticRoot(directory string) (string, error) {\n\tabsolute, err := filepath.Abs(directory)\n\tif err != nil {\n\t\treturn \"\", err\n\t}\n\treturn filepath.EvalSymlinks(absolute)\n}\n\n// hasDotSegment reports whether any segment of a cleaned, root-relative path begins with `.`.\nfunc hasDotSegment(relative string) bool {\n\tfor _, segment := range strings.Split(relative, \"/\") {\n\t\tif strings.HasPrefix(segment, \".\") {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// containedStaticFile is the regular file `relative` names inside `root`, as its resolved path,\n// or \"\" when there is no such file \226\128\148 including when the path exists but resolves through a\n// symlink to somewhere outside the root, which is treated exactly like a file that is not there.\nfunc containedStaticFile(root, relative string) string {\n\tseparator := string(os.PathSeparator)\n\tcandidate := filepath.Join(root, filepath.FromSlash(relative))\n\tif !strings.HasPrefix(candidate, root+separator) {\n\t\treturn \"\"\n\t}\n\tresolved, err := filepath.EvalSymlinks(candidate)\n\tif err != nil {\n\t\treturn \"\"\n\t}\n\tif !strings.HasPrefix(resolved, root+separator) {\n\t\treturn \"\"\n\t}\n\tinfo, err := os.Stat(resolved)\n\tif err != nil || info.IsDir() {\n\t\treturn \"\"\n\t}\n\treturn resolved\n}\n\n// \226\148\128\226\148\128 Request-level guards \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// Two refusals the Racket runtime applies to every request, mirrored here so a program does not\n// lose them by changing backend. Both are cheap and neither is configurable per route.\n\nvar publicOriginOnce sync.Once\nvar publicOrigin string\n\n// The `publicOrigin` server clause, when the program declares one. It TAKES PRECEDENCE over\n// the environment variable: the clause is compile-time validated and the variable is not,\n// and a deployment that declared its origin should not answer as another because a stray\n// variable disagreed. The same precedence the Racket parameter has.\nvar (\n\tpublicOriginMutex    sync.RWMutex\n\tpublicOriginOverride string\n)\n\n// PublicOrigin is the declared origin, else `TESL_PUBLIC_ORIGIN`: the origin this deployment\n// answers as. Never derived from a request \226\128\148 a Host header is exactly what it guards.\nfunc PublicOrigin() string {\n\tpublicOriginMutex.RLock()\n\tdeclared := publicOriginOverride\n\tpublicOriginMutex.RUnlock()\n\tif declared != \"\" {\n\t\treturn declared\n\t}\n\tpublicOriginOnce.Do(func() {\n\t\tpublicOrigin = strings.TrimSpace(os.Getenv(\"TESL_PUBLIC_ORIGIN\"))\n\t})\n\treturn publicOrigin\n}\n\n// The `healthProbePath` server clause: the ONE path exempt from Host validation, because a load\n// balancer probes host-blind. Exempt from THAT check only \226\128\148 the cross-site guard still applies,\n// and a probe is a GET so it never meets it.\nvar (\n\thealthProbeMutex sync.RWMutex\n\thealthProbePath  string\n)\n\n// SetHealthProbePath is the clause, applied at boot.\nfunc SetHealthProbePath(path string) {\n\thealthProbeMutex.Lock()\n\tdefer healthProbeMutex.Unlock()\n\thealthProbePath = path\n}\n\nfunc healthProbeExempt(path string) bool {\n\thealthProbeMutex.RLock()\n\tdefer healthProbeMutex.RUnlock()\n\treturn healthProbePath != \"\" && path == healthProbePath\n}\n\n// The `contentSecurityPolicy` server clause: the default CSP for responses this runtime serves\n// as HTML. A deployment may replace it with a policy that passes the compiler's CSP baseline;\n// the environment fallback is checked here too because it is deployment input. Unsafe policies\n// fail closed to this baseline rather than weakening every HTML response.\nvar (\n\tcontentSecurityPolicyMutex sync.RWMutex\n\tcontentSecurityPolicy      string\n)\n\nconst defaultContentSecurityPolicy = \"default-src 'self'; base-uri 'self'; object-src 'none'; frame-ancestors 'none'; form-action 'self'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; font-src 'self'; media-src 'self'; worker-src 'self'; manifest-src 'self'; frame-src 'none'\"\n\n// SetContentSecurityPolicy is the clause, applied at boot.\nfunc SetContentSecurityPolicy(policy string) {\n\tcontentSecurityPolicyMutex.Lock()\n\tdefer contentSecurityPolicyMutex.Unlock()\n\tcontentSecurityPolicy = strings.TrimSpace(policy)\n}\n\nfunc htmlContentSecurityPolicy() string {\n\tcontentSecurityPolicyMutex.RLock()\n\tdeclared := contentSecurityPolicy\n\tcontentSecurityPolicyMutex.RUnlock()\n\tif declared != \"\" {\n\t\tif secureContentSecurityPolicy(declared) {\n\t\t\treturn declared\n\t\t}\n\t\treturn defaultContentSecurityPolicy\n\t}\n\tif fromEnv := strings.TrimSpace(os.Getenv(\"TESL_CSP\")); fromEnv != \"\" {\n\t\tif secureContentSecurityPolicy(fromEnv) {\n\t\t\treturn fromEnv\n\t\t}\n\t}\n\treturn defaultContentSecurityPolicy\n}\n\n// secureContentSecurityPolicy is deliberately a small fail-closed parser, not a complete CSP\n// grammar. It checks the properties Tesl promises: required isolation directives are present and\n// no source wildcard, inline execution, eval, or unrestricted data/blob scheme is admitted.\nfunc secureContentSecurityPolicy(policy string) bool {\n\trequired := map[string]bool{\n\t\t\"default-src\": false, \"base-uri\": false, \"object-src\": false,\n\t\t\"frame-ancestors\": false, \"form-action\": false, \"script-src\": false,\n\t\t\"style-src\": false,\n\t}\n\tfor _, rawDirective := range strings.Split(policy, \";\") {\n\t\tfields := strings.Fields(rawDirective)\n\t\tif len(fields) == 0 {\n\t\t\tcontinue\n\t\t}\n\t\tname := strings.ToLower(fields[0])\n\t\tif _, present := required[name]; present {\n\t\t\trequired[name] = true\n\t\t}\n\t\tfor _, source := range fields[1:] {\n\t\t\tswitch strings.ToLower(source) {\n\t\t\tcase \"*\", \"'unsafe-inline'\", \"'unsafe-eval'\", \"data:\", \"blob:\", \"http:\", \"https:\":\n\t\t\t\treturn false\n\t\t\t}\n\t\t}\n\t}\n\tfor _, present := range required {\n\t\tif !present {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n\n// hstsHeaderValue is set ONLY from the CONFIGURED public origin, never from the request: a Host\n// header is untrusted and absent behind a proxy, and HSTS is close to irreversible once a\n// browser has seen it. One year, no includeSubDomains and no preload \226\128\148 Tesl cannot see the\n// subdomain topology. Suppressed for a loopback dev origin.\nfunc hstsHeaderValue() string {\n\torigin := strings.ToLower(PublicOrigin())\n\tif !strings.HasPrefix(origin, \"https://\") {\n\t\treturn \"\"\n\t}\n\thost := hostOf(origin)\n\tif host == \"localhost\" || host == \"[::1]\" || strings.HasPrefix(host, \"127.\") {\n\t\treturn \"\"\n\t}\n\treturn \"max-age=31536000\"\n}\n\n// hardenedWriter adds the response-header floor at the moment the status is written, which is the\n// first point where the Content-Type is known \226\128\148 the CSP applies to HTML and `no-store` to the\n// JSON API, exactly as `dsl/web.rkt` splits them. A header the producer already set WINS: a\n// handler that chose its own Referrer-Policy or CSP means it.\ntype hardenedWriter struct {\n\thttp.ResponseWriter\n\twroteHeader bool\n}\n\nfunc (writer *hardenedWriter) WriteHeader(status int) {\n\tif !writer.wroteHeader {\n\t\twriter.wroteHeader = true\n\t\tapplySecurityHeaders(writer.Header())\n\t}\n\twriter.ResponseWriter.WriteHeader(status)\n}\n\nfunc (writer *hardenedWriter) Write(payload []byte) (int, error) {\n\tif !writer.wroteHeader {\n\t\twriter.WriteHeader(http.StatusOK)\n\t}\n\treturn writer.ResponseWriter.Write(payload)\n}\n\n// Flush passes through so an SSE stream still streams: wrapping a writer without this turns\n// every event into buffered output that arrives at the end.\nfunc (writer *hardenedWriter) Flush() {\n\tif flusher, canFlush := writer.ResponseWriter.(http.Flusher); canFlush {\n\t\tflusher.Flush()\n\t}\n}\n\n// Unwrap is what lets `http.NewResponseController` reach the connection behind this wrapper.\n// Without it `SetWriteDeadline` answers ErrNotSupported and the SSE stream cannot move the\n// server's per-response write deadline \226\128\148 the connection is then cut at `serveWriteTimeout`.\nfunc (writer *hardenedWriter) Unwrap() http.ResponseWriter {\n\treturn writer.ResponseWriter\n}\n\nfunc applySecurityHeaders(header http.Header) {\n\tsetIfAbsent := func(name, value string) {\n\t\tif value != \"\" && header.Get(name) == \"\" {\n\t\t\theader.Set(name, value)\n\t\t}\n\t}\n\tsetIfAbsent(\"X-Content-Type-Options\", \"nosniff\")\n\tsetIfAbsent(\"Referrer-Policy\", \"no-referrer\")\n\tsetIfAbsent(\"X-Frame-Options\", \"DENY\")\n\tsetIfAbsent(\"Strict-Transport-Security\", hstsHeaderValue())\n\tcontentType := strings.ToLower(header.Get(\"Content-Type\"))\n\tswitch {\n\tcase strings.Contains(contentType, \"text/html\"):\n\t\t// A CSP is meaningful for a document only, and the app cannot set one on HTML this\n\t\t// runtime serves (the static file and the SPA fallback are both ours).\n\t\tsetIfAbsent(\"Content-Security-Policy\", htmlContentSecurityPolicy())\n\tcase strings.Contains(contentType, \"application/json\"):\n\t\t// The JSON API answers session-bearing data; a shared cache must not keep it.\n\t\tsetIfAbsent(\"Cache-Control\", \"no-store\")\n\t}\n}\n\n// requestRefusal is the guard pair: a cross-site state-changing request is refused (403), and a\n// Host that does not match the configured public origin is refused (421). Answering the second\n// with 421 rather than 404 is deliberate \226\128\148 it says \"not this origin\", which is what a\n// misconfigured proxy needs to hear.\nfunc requestRefusal(request *http.Request) (Response, bool) {\n\tswitch request.Method {\n\tcase http.MethodPost, http.MethodPut, http.MethodDelete, http.MethodPatch:\n\t\tif refusal, refused := crossSiteRefusal(request); refused {\n\t\t\treturn refusal, true\n\t\t}\n\t}\n\torigin := PublicOrigin()\n\tif origin == \"\" || healthProbeExempt(request.URL.Path) {\n\t\treturn Response{}, false\n\t}\n\tif hostOf(request.Host) == hostOf(origin) {\n\t\treturn Response{}, false\n\t}\n\treturn Fail(421, \"Host does not match the configured public origin\"), true\n}\n\n// crossSiteRefusal is the CSRF guard a state-changing method meets. It matters most for the\n// cookies a PROGRAM sets and reads in its `auth` block: the runtime's own `__Host-session` is\n// `SameSite=Lax`, but a program-defined cookie has whatever attributes the program gave it, and\n// this guard is then the only thing between a form on another site and the handler.\n//\n// Two sources, in order of trust:\n//\n//   - `Sec-Fetch-Site`, when the browser sent one. `same-origin` passes, `cross-site`\n//     is refused, `same-site` must also carry an exact matching Origin, and unknown\n//     values fail closed.\n//   - When it is ABSENT \226\128\148 an older browser (Safari before 16.4, Firefox before 90) or a\n//     non-browser client \226\128\148 the initiator the request names itself: `Origin`, else `Referer`.\n//     If one is present, its complete web origin must equal the configured public origin,\n//     or the request URL's origin when none is configured. `Origin: null` is refused too.\n//\n// A request naming NEITHER passes: curl, a service client and a same-origin fetch that stripped\n// the referrer all look like that, and refusing them would break every non-browser caller for no\n// protection a browser needs. Comparing an initiator to the request Host is still useful when\n// no public origin is configured: a browser cannot choose the target request's Host independently.\nfunc crossSiteRefusal(request *http.Request) (Response, bool) {\n\tsite := strings.ToLower(strings.TrimSpace(request.Header.Get(\"Sec-Fetch-Site\")))\n\tswitch site {\n\tcase \"cross-site\":\n\t\treturn Fail(403, \"cross-site request refused\"), true\n\tcase \"\", \"same-origin\", \"same-site\", \"none\":\n\tdefault:\n\t\treturn Fail(403, \"request with unknown fetch metadata refused\"), true\n\t}\n\toriginHeader := strings.TrimSpace(request.Header.Get(\"Origin\"))\n\tinitiator := originHeader\n\tisReferer := false\n\tif initiator == \"\" {\n\t\tinitiator = strings.TrimSpace(request.Header.Get(\"Referer\"))\n\t\tisReferer = initiator != \"\"\n\t}\n\tif site == \"same-site\" && originHeader == \"\" {\n\t\treturn Fail(403, \"same-site request without an exact Origin refused\"), true\n\t}\n\tif initiator == \"\" {\n\t\treturn Response{}, false\n\t}\n\texpected, valid := requestPublicOrigin(request)\n\tif !valid {\n\t\treturn Fail(403, \"request origin is not configured or valid\"), true\n\t}\n\tactual, valid := canonicalWebOrigin(initiator, isReferer)\n\tif !valid || actual != expected {\n\t\treturn Fail(403, \"cross-site request refused\"), true\n\t}\n\treturn Response{}, false\n}\n\nfunc requestPublicOrigin(request *http.Request) (string, bool) {\n\t// publicOrigin is the authenticated deployment statement for TLS terminated\n\t// upstream. Never infer the external scheme or host from Forwarded or\n\t// X-Forwarded-* headers: a direct client can supply those too.\n\tif configured := strings.TrimSpace(PublicOrigin()); configured != \"\" {\n\t\treturn canonicalWebOrigin(configured, false)\n\t}\n\tscheme := strings.ToLower(request.URL.Scheme)\n\tif scheme == \"\" {\n\t\tif request.TLS != nil {\n\t\t\tscheme = \"https\"\n\t\t} else {\n\t\t\tscheme = \"http\"\n\t\t}\n\t}\n\treturn canonicalWebOrigin(scheme+\"://\"+request.Host, false)\n}\n\nfunc canonicalWebOrigin(value string, allowPath bool) (string, bool) {\n\tparsed, err := url.Parse(strings.TrimSpace(value))\n\tif err != nil || parsed.User != nil || parsed.Host == \"\" || (parsed.Scheme != \"http\" && parsed.Scheme != \"https\") {\n\t\treturn \"\", false\n\t}\n\tif !allowPath && parsed.Path != \"\" && parsed.Path != \"/\" {\n\t\treturn \"\", false\n\t}\n\tif !allowPath && (parsed.RawQuery != \"\" || parsed.Fragment != \"\") {\n\t\treturn \"\", false\n\t}\n\thostname := strings.ToLower(parsed.Hostname())\n\tif hostname == \"\" {\n\t\treturn \"\", false\n\t}\n\tport := parsed.Port()\n\tif (parsed.Scheme == \"http\" && port == \"80\") || (parsed.Scheme == \"https\" && port == \"443\") {\n\t\tport = \"\"\n\t}\n\thost := hostname\n\tif strings.Contains(hostname, \":\") {\n\t\thost = \"[\" + hostname + \"]\"\n\t}\n\tif port != \"\" {\n\t\thost = net.JoinHostPort(hostname, port)\n\t}\n\treturn strings.ToLower(parsed.Scheme) + \"://\" + host, true\n}\n\n// hostOf takes the host out of either a bare Host header or a full origin, without its port: a\n// deployment behind a proxy sees the port the proxy forwards to, not the public one.\nfunc hostOf(value string) string {\n\ttext := strings.TrimSpace(strings.ToLower(value))\n\tif index := strings.Index(text, \"://\"); index >= 0 {\n\t\ttext = text[index+3:]\n\t}\n\tif index := strings.IndexAny(text, \"/?#\"); index >= 0 {\n\t\ttext = text[:index]\n\t}\n\tif strings.HasPrefix(text, \"[\") {\n\t\tif end := strings.Index(text, \"]\"); end >= 0 {\n\t\t\treturn text[:end+1]\n\t\t}\n\t\treturn text\n\t}\n\tif index := strings.LastIndex(text, \":\"); index >= 0 {\n\t\treturn text[:index]\n\t}\n\treturn text\n}\n\n// PortOf narrows a Tesl `Int` to a listening port. A port is a 16-bit number, so anything\n// outside that range is a configuration error worth failing at startup rather than silently\n// binding somewhere else.\nfunc PortOf(value Int) int {\n\tport, exact := value.Int64()\n\tif !exact || port < 1 || port > 65535 {\n\t\tpanic(\"serve: port \" + value.String() + \" is not a valid TCP port (1-65535)\")\n\t}\n\treturn int(port)\n}\n");
  ("server.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"net/http\"\n\t\"os\"\n\t\"runtime/debug\"\n\t\"strings\"\n)\n\n// The HTTP surface an emitted module exposes: the ROUTES an `api` declares, and the\n// SERVER that binds each route's endpoint name to a handler.\n//\n// Emitted modules build these as ordinary values, so a Go author who sheds Tesl can read\n// the routing table, call a handler directly, or mount the server on any net/http mux.\n// Nothing here reaches into request-scoped globals: the per-request state a handler may\n// touch (cookies) is created by the dispatcher and passed in explicitly.\n\ntype Route struct {\n\tMethod   string\n\tPath     string\n\tEndpoint string\n}\n\n// HandlerFunc is one endpoint's implementation. The scope carries the response state the\n// handler is allowed to write (see request.go); `Response` says what to send.\ntype HandlerFunc func(scope *RequestScope, request *http.Request) Response\n\ntype Response struct {\n\tStatus int\n\t// Body is an already-encoded JSON value (map / slice / scalar), rendered by\n\t// EncodeJSONValue so object keys keep the sorted order Racket produces.\n\tBody any\n}\n\n// Fail builds the error body shape the Racket server sends:\n// {\"ok\":false,\"error\":<message>,\"details\":[]}.\nfunc Fail(status int, message string) Response {\n\treturn Response{\n\t\tStatus: status,\n\t\tBody: map[string]any{\n\t\t\t\"ok\":      false,\n\t\t\t\"error\":   message,\n\t\t\t\"details\": []any{},\n\t\t},\n\t}\n}\n\n// StreamFunc is an endpoint that STREAMS rather than answering once: an `sse` route. It takes\n// the writer directly, because its response is written over the life of the connection instead\n// of being built and then sent.\ntype StreamFunc func(writer http.ResponseWriter, request *http.Request)\n\ntype Server struct {\n\tRoutes   []Route\n\tHandlers map[string]HandlerFunc\n\t// Streams holds the SSE endpoints, keyed like Handlers. A route resolves to one or the\n\t// other, never both: `sse` and the request/response methods are different declarations.\n\tStreams map[string]StreamFunc\n\t// The runtime-owned SSO routes an `sso \"<seg>\"` clause mints. They are matched BEFORE\n\t// the declared ones and they own their whole response \226\128\148 a 303 with cookies, not the JSON\n\t// envelope every handler answers in \226\128\148 so they cannot be expressed as a Handler.\n\tSsoRoutes []SsoRoute\n}\n\n// ServeHTTP dispatches by method and path. A path segment written `:name` in the route\n// matches any single segment.\n//\n// The status choices mirror the Racket router: an unknown path is 404, and a known path\n// with the wrong method is 405 \226\128\148 reporting 404 for a method mismatch would tell a client\n// the resource does not exist when it does.\n// callHandler runs one handler and converts a check rejection that escaped its body into\n// the response that rejection describes. Any OTHER panic is left alone: a genuine bug must\n// not be reported to the client as a validation failure.\nfunc callHandler(handler HandlerFunc, scope *RequestScope, request *http.Request) (response Response) {\n\tdefer func() {\n\t\trecovered := recover()\n\t\tif recovered == nil {\n\t\t\treturn\n\t\t}\n\t\tif rejection, isRejection := recovered.(RequestRejection); isRejection {\n\t\t\tresponse = Fail(rejection.Status, rejection.Message)\n\t\t\treturn\n\t\t}\n\t\tresponse = sanitizedTrap(recovered)\n\t}()\n\treturn handler(scope, request)\n}\n\n// sanitizedTrap is what ANY other trap becomes: a 500 whose message is deliberately generic.\n// The trap text never reaches the client: a trap message carries whatever the program was\n// holding (a path, a key, a row), and an `auth` block is exactly where a malformed cookie can\n// provoke one \226\128\148 so a client-triggerable trap must not become a client-readable disclosure. The\n// detail is still available to the operator, on stderr.\nfunc sanitizedTrap(recovered any) Response {\n\tfmt.Fprintf(os.Stderr, \"tesl: handler trapped: %v\\n%s\", recovered, debug.Stack())\n\treturn Fail(500, \"Internal server error\")\n}\n\nfunc (server Server) ServeHTTP(writer http.ResponseWriter, request *http.Request) {\n\t// The two request-level refusals the Racket runtime applies to every request (serve.go):\n\t// a cross-site state-changing request, and a Host that is not this deployment's. Checked\n\t// here rather than in `Serve` so an api-test \226\128\148 which drives this method directly \226\128\148 exercises\n\t// them too.\n\tif refusal, refused := requestRefusal(request); refused {\n\t\twriteResponse(writer, nil, refusal)\n\t\treturn\n\t}\n\t// The SSO routes are matched FIRST. `/auth/<seg>/login` is runtime-owned, and a declared\n\t// route that happened to share the path would otherwise shadow a login \226\128\148 the same\n\t// precedence dsl/web.rkt gives them.\n\tif route, kind, matched := findSsoMatch(server.SsoRoutes, request.URL.Path); matched {\n\t\t// ANY method, as dsl/web.rkt's matcher does. Narrowing this to GET would be the\n\t\t// safer-looking choice and the wrong one: it decides which PROGRAMS run rather than\n\t\t// only what they answer, and a POST to a login path would then reach a declared\n\t\t// handler here while being shadowed there.\n\t\thandleSsoRequest(route, kind, writer, request)\n\t\treturn\n\t}\n\t// The methods declared for a path that matched, for the `Allow` header a 405 MUST carry\n\t// (RFC 9110 \194\16715.5.6) \226\128\148 the answer to \"wrong method\" is useless without the right ones.\n\tvar allowed []string\n\tfor _, route := range server.Routes {\n\t\tif !pathMatches(route.Path, request.URL.Path) {\n\t\t\tcontinue\n\t\t}\n\t\tallowed = append(allowed, route.Method)\n\t\tif route.Method != request.Method {\n\t\t\tcontinue\n\t\t}\n\t\tif stream, streams := server.Streams[route.Endpoint]; streams {\n\t\t\t// A stream owns its own response: status, headers and body are written by the\n\t\t\t// handler over the life of the connection, so nothing is wrapped around it here.\n\t\t\tstream(writer, request)\n\t\t\treturn\n\t\t}\n\t\thandler, found := server.Handlers[route.Endpoint]\n\t\tif !found {\n\t\t\twriteResponse(writer, nil, Fail(500, \"endpoint \"+route.Endpoint+\" has no handler\"))\n\t\t\treturn\n\t\t}\n\t\tscope := NewRequestScope()\n\t\twriteResponse(writer, scope, callHandler(handler, scope, request))\n\t\treturn\n\t}\n\tif len(allowed) > 0 {\n\t\twriter.Header().Set(\"Allow\", strings.Join(allowed, \", \"))\n\t\twriteResponse(writer, nil, Fail(405, \"method not allowed\"))\n\t\treturn\n\t}\n\twriteResponse(writer, nil, Fail(404, \"not found\"))\n}\n\nfunc pathMatches(pattern, path string) bool {\n\tpatternParts := strings.Split(strings.Trim(pattern, \"/\"), \"/\")\n\tpathParts := strings.Split(strings.Trim(path, \"/\"), \"/\")\n\tif len(patternParts) != len(pathParts) {\n\t\treturn false\n\t}\n\tfor index, part := range patternParts {\n\t\tif strings.HasPrefix(part, \":\") {\n\t\t\tif pathParts[index] == \"\" {\n\t\t\t\treturn false\n\t\t\t}\n\t\t\tcontinue\n\t\t}\n\t\tif part != pathParts[index] {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n\n// PathParam reads the segment a `:name` placeholder matched.\nfunc PathParam(pattern, path, name string) (string, bool) {\n\tpatternParts := strings.Split(strings.Trim(pattern, \"/\"), \"/\")\n\tpathParts := strings.Split(strings.Trim(path, \"/\"), \"/\")\n\tif len(patternParts) != len(pathParts) {\n\t\treturn \"\", false\n\t}\n\tfor index, part := range patternParts {\n\t\tif part == \":\"+name {\n\t\t\treturn pathParts[index], true\n\t\t}\n\t}\n\treturn \"\", false\n}\n\nfunc writeResponse(writer http.ResponseWriter, scope *RequestScope, response Response) {\n\t// The body is encoded BEFORE the status is chosen, because encoding can trap \226\128\148 a Float that\n\t// overflowed to +Inf has no JSON spelling \226\128\148 and the handler's `callHandler` recover is\n\t// already behind us by now. Left to net/http the trap would close the connection with a\n\t// stack on stderr and no response; here it becomes the same sanitized 500 every other trap\n\t// is, and a 500 attaches no cookie, so the status is decided before the cookie loop.\n\tbody, encoded := encodeResponseBody(response.Body)\n\tif !encoded {\n\t\tresponse = Fail(500, \"Internal server error\")\n\t\tbody = EncodeJSONValue(response.Body)\n\t}\n\t// Cookies attach to 2xx responses only, matching dsl/web.rkt: a handler that sets a\n\t// cookie and then fails mints no session.\n\tif scope != nil && response.Status >= 200 && response.Status < 300 {\n\t\tfor _, cookie := range scope.CookieHeaders() {\n\t\t\twriter.Header().Add(\"Set-Cookie\", cookie)\n\t\t}\n\t}\n\twriter.Header().Set(\"Content-Type\", \"application/json\")\n\twriter.WriteHeader(response.Status)\n\t_, _ = writer.Write([]byte(body))\n}\n\n// encodeResponseBody renders a response body, reporting a trap as `false` after logging it\n// the way `callHandler` logs a handler trap \226\128\148 the encoder is the last program-controlled step\n// before the bytes leave, and its failure is the program's, not the client's.\nfunc encodeResponseBody(value any) (body string, encoded bool) {\n\tdefer func() {\n\t\tif recovered := recover(); recovered != nil {\n\t\t\t_ = sanitizedTrap(recovered)\n\t\t\tbody, encoded = \"\", false\n\t\t}\n\t}()\n\treturn EncodeJSONValue(value), true\n}\n\n// IntegerSegment parses a path capture declared with `intCodec`.\n//\n// A 400 rather than a 404: the route MATCHED \226\128\148 the shape of the path is right \226\128\148 and what is\n// wrong is the value in it, which is a client error the caller can act on. That is the\n// status `dsl/web.rkt`'s `integer-segment` answers, and the message is its text.\n//\n// Racket accepts anything its `string->number` reads as an integer, which includes `1e3`\n// and `#x10`. This reads decimal digits with an optional sign and nothing else: a path\n// segment is a URL component, and a route that answers to `/tasks/1e3` as well as\n// `/tasks/1000` is two names for one resource.\nfunc IntegerSegment(segment string) Check[Int] {\n\tvalue, err := ParseDecimal(segment)\n\tif err != nil {\n\t\t// The echoed segment is bounded: a client that sent a megabyte of digits does not get\n\t\t// a megabyte back, and an operator log line stays a line.\n\t\tshown := segment\n\t\tif len(shown) > 64 {\n\t\t\tshown = shown[:64] + \"\226\128\166\"\n\t\t}\n\t\treturn Reject[Int](400, \"Expected an integer path segment, got \"+shown)\n\t}\n\treturn Accept(value)\n}\n");
  ("set.go", "package teslrt\n\n// Set is Tesl's `Set a`, held as elements kept SORTED with no duplicates.\n//\n// Same reasoning as Dict (see dict.go): a Go map cannot be keyed by the non-comparable\n// teslrt.Int, and Go randomises map iteration order per run \226\128\148 which would make the same\n// binary print different output across runs, worse than Racket's unspecified-but-stable\n// order. Sorted order is deterministic and free here, since the insertion point is the\n// binary search membership already performs.\n//\n// Racket's `Set.toList` iterates a hash, so element order is UNSPECIFIED in Tesl: a\n// program may observe membership and size, never order. That divergence is real and\n// demonstrated \226\128\148 see the Dict entry in the migration tracker.\n//\n// Ordering comes in from the emitter, which knows the concrete element type at every\n// call site.\ntype Set[A any] struct {\n\tElements []A\n}\n\nfunc SetEmpty[A any]() Set[A] {\n\treturn Set[A]{}\n}\n\nfunc SetSingleton[A any](value A) Set[A] {\n\treturn Set[A]{Elements: []A{value}}\n}\n\nfunc SetSize[A any](s Set[A]) Int {\n\treturn FromInt64(int64(len(s.Elements)))\n}\n\nfunc SetIsEmpty[A any](s Set[A]) bool {\n\treturn len(s.Elements) == 0\n}\n\n// setSearch returns the insertion index and whether the element was present.\nfunc setSearch[A any](s Set[A], value A, less func(A, A) bool) (int, bool) {\n\tlow, high := 0, len(s.Elements)\n\tfor low < high {\n\t\tmiddle := int(uint(low+high) >> 1)\n\t\tswitch {\n\t\tcase less(s.Elements[middle], value):\n\t\t\tlow = middle + 1\n\t\tcase less(value, s.Elements[middle]):\n\t\t\thigh = middle\n\t\tdefault:\n\t\t\treturn middle, true\n\t\t}\n\t}\n\treturn low, false\n}\n\nfunc SetMember[A any](value A, s Set[A], less func(A, A) bool) bool {\n\t_, found := setSearch(s, value, less)\n\treturn found\n}\n\n// SetInsert is a WRITER, so it allocates rather than reusing the caller's spare\n// capacity \226\128\148 the same rule list.go states.\nfunc SetInsert[A any](value A, s Set[A], less func(A, A) bool) Set[A] {\n\tindex, found := setSearch(s, value, less)\n\tif found {\n\t\treturn s\n\t}\n\telements := make([]A, 0, len(s.Elements)+1)\n\telements = append(elements, s.Elements[:index]...)\n\telements = append(elements, value)\n\telements = append(elements, s.Elements[index:]...)\n\treturn Set[A]{Elements: elements}\n}\n\nfunc SetRemove[A any](value A, s Set[A], less func(A, A) bool) Set[A] {\n\tindex, found := setSearch(s, value, less)\n\tif !found {\n\t\treturn s\n\t}\n\telements := make([]A, 0, len(s.Elements)-1)\n\telements = append(elements, s.Elements[:index]...)\n\telements = append(elements, s.Elements[index+1:]...)\n\treturn Set[A]{Elements: elements}\n}\n\n// SetToList hands back a copy in element order, so a caller cannot reach the set's own\n// storage through the list.\nfunc SetToList[A any](s Set[A]) []A {\n\tout := make([]A, len(s.Elements))\n\tcopy(out, s.Elements)\n\treturn out\n}\n\n// SetFromList sorts once and drops duplicates rather than inserting n times, which\n// would be O(n\194\178).\nfunc SetFromList[A any](values []A, less func(A, A) bool) Set[A] {\n\tout := SetEmpty[A]()\n\tif len(values) == 0 {\n\t\treturn out\n\t}\n\tsorted := ListSortBy(values, less)\n\telements := make([]A, 0, len(sorted))\n\tfor index, value := range sorted {\n\t\tif index == 0 || less(elements[len(elements)-1], value) {\n\t\t\telements = append(elements, value)\n\t\t}\n\t}\n\treturn Set[A]{Elements: elements}\n}\n\n// SetUnion, SetIntersection, and SetDifference each merge two ordered runs in one pass,\n// so they are O(n+m) rather than n lookups.\nfunc SetUnion[A any](left, right Set[A], less func(A, A) bool) Set[A] {\n\telements := make([]A, 0, len(left.Elements)+len(right.Elements))\n\tleftIndex, rightIndex := 0, 0\n\tfor leftIndex < len(left.Elements) && rightIndex < len(right.Elements) {\n\t\tswitch {\n\t\tcase less(left.Elements[leftIndex], right.Elements[rightIndex]):\n\t\t\telements = append(elements, left.Elements[leftIndex])\n\t\t\tleftIndex++\n\t\tcase less(right.Elements[rightIndex], left.Elements[leftIndex]):\n\t\t\telements = append(elements, right.Elements[rightIndex])\n\t\t\trightIndex++\n\t\tdefault:\n\t\t\telements = append(elements, left.Elements[leftIndex])\n\t\t\tleftIndex++\n\t\t\trightIndex++\n\t\t}\n\t}\n\telements = append(elements, left.Elements[leftIndex:]...)\n\telements = append(elements, right.Elements[rightIndex:]...)\n\treturn Set[A]{Elements: elements}\n}\n\nfunc SetIntersection[A any](left, right Set[A], less func(A, A) bool) Set[A] {\n\telements := make([]A, 0, min(len(left.Elements), len(right.Elements)))\n\tleftIndex, rightIndex := 0, 0\n\tfor leftIndex < len(left.Elements) && rightIndex < len(right.Elements) {\n\t\tswitch {\n\t\tcase less(left.Elements[leftIndex], right.Elements[rightIndex]):\n\t\t\tleftIndex++\n\t\tcase less(right.Elements[rightIndex], left.Elements[leftIndex]):\n\t\t\trightIndex++\n\t\tdefault:\n\t\t\telements = append(elements, left.Elements[leftIndex])\n\t\t\tleftIndex++\n\t\t\trightIndex++\n\t\t}\n\t}\n\treturn Set[A]{Elements: elements}\n}\n\nfunc SetDifference[A any](left, right Set[A], less func(A, A) bool) Set[A] {\n\telements := make([]A, 0, len(left.Elements))\n\tleftIndex, rightIndex := 0, 0\n\tfor leftIndex < len(left.Elements) && rightIndex < len(right.Elements) {\n\t\tswitch {\n\t\tcase less(left.Elements[leftIndex], right.Elements[rightIndex]):\n\t\t\telements = append(elements, left.Elements[leftIndex])\n\t\t\tleftIndex++\n\t\tcase less(right.Elements[rightIndex], left.Elements[leftIndex]):\n\t\t\trightIndex++\n\t\tdefault:\n\t\t\tleftIndex++\n\t\t\trightIndex++\n\t\t}\n\t}\n\telements = append(elements, left.Elements[leftIndex:]...)\n\treturn Set[A]{Elements: elements}\n}\n\n// SetIsSubset reports whether every element of left is also in right.\nfunc SetIsSubset[A any](left, right Set[A], less func(A, A) bool) bool {\n\trightIndex := 0\n\tfor _, value := range left.Elements {\n\t\tfor rightIndex < len(right.Elements) && less(right.Elements[rightIndex], value) {\n\t\t\trightIndex++\n\t\t}\n\t\tif rightIndex >= len(right.Elements) || less(value, right.Elements[rightIndex]) {\n\t\t\treturn false\n\t\t}\n\t\trightIndex++\n\t}\n\treturn true\n}\n\n// SetEqualBy compares in one pass, since both sides are ordered.\nfunc SetEqualBy[A any](left, right Set[A], equal func(A, A) bool) bool {\n\tif len(left.Elements) != len(right.Elements) {\n\t\treturn false\n\t}\n\tfor index := range left.Elements {\n\t\tif !equal(left.Elements[index], right.Elements[index]) {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n");
  ("sse.go", "package teslrt\n\nimport (\n\t\"sync\"\n)\n\n// Server-Sent Events: `sseChannel C(key) = SseChannel { \226\128\166 }`, `publish C(key) payload`, and the\n// `sse \"/path\" subscribe C(key)` route that streams them.\n//\n// Events flow server\226\134\146client over ordinary HTTP on the SAME port as the API, which is why Tesl\n// has no WebSocket server: a browser subscribes with EventSource and no proxy needs special\n// configuration. The wire format is the one `tesl/sse.rkt` writes, byte for byte:\n//\n//\tan event     data: {\"channel\":\"<name>\",\"payload\":<json>}\\n\\n\n//\ta heartbeat  : heartbeat\\n\\n        every 10s, so a proxy does not reap an idle connection\n//\ton connect   : ok\\n\\n               so the browser fires onopen without waiting 10s\n//\n// PUBLISHING MUST NEVER BLOCK. A publish usually runs inside a request handler, so a listener\n// that is slow \226\128\148 or dead but still registered \226\128\148 would otherwise cost that request. Each\n// connection therefore has a BOUNDED buffer and a full buffer drops the event for that one\n// consumer, counting it. Racket learned this the hard way (issue #32: a day of development\n// left 109 stale listeners on one key, and a chat turn took over a minute).\n\ntype sseListener struct {\n\tevents chan any\n}\n\n// SseChannel is one `sseChannel` declaration: a name, and the listeners registered under each\n// channel KEY. The key is what makes a channel per-entity \226\128\148 `RunEvents(runId)` delivers only to\n// the subscribers of that run \226\128\148 and a channel declared with a fixed string is the broadcast\n// case of the same rule.\ntype SseChannel struct {\n\tname      string\n\tmutex     sync.Mutex\n\tlisteners map[string][]*sseListener\n\t// active counts live connections per channel, mirroring registry membership rather than\n\t// being derived from it: the gauge must not drift when metrics are off for a while.\n\tactive int\n\t// backend is the cross-instance fan-out for a channel declared on a Postgres-backed\n\t// database (`NewSseChannelOn`, pgpubsub.go), and nil for a Memory-backed one. It is set\n\t// once, at construction, before the channel is shared, so reading it needs no lock.\n\tbackend pubsubBackend\n}\n\n// pubsubBackend is what a channel on a Postgres-backed database delegates a publish to.\n//\n// The interface lives here, in the file every program ships, so that `Publish` can ask\n// without this file knowing anything about a database: the one implementation is\n// pgpubsub.go, which ships only with a Postgres-backed program.\ntype pubsubBackend interface {\n\t// active answers whether a publish should go through the backend NOW \226\128\148 for the\n\t// Postgres backend, whether its database is bound. Off a binding (a `test` block over a\n\t// Postgres-backed entity, with no server anywhere) the channel behaves like a Memory one.\n\tactive() bool\n\t// publish hands the event to the backend, which delivers it to THIS process's listeners\n\t// too, the same way it reaches every other instance's. `encoded` is the payload's JSON\n\t// text \226\128\148 the form that crosses the wire, and the form that is stored.\n\tpublish(channel, key string, encoded string)\n}\n\nfunc NewSseChannel(name string) *SseChannel {\n\treturn &SseChannel{name: name, listeners: map[string][]*sseListener{}}\n}\n\nfunc sseChannelAttribute(name string) []Tuple2[string, string] {\n\treturn []Tuple2[string, string]{{Tuple2First: \"tesl.channel\", Tuple2Second: name}}\n}\n\n// Publish delivers one event to every listener on `key`. The payload is the ALREADY-ENCODED\n// JSON value (what the type's codec produces), for the reason the response body is: the wire\n// shape is decided by the codec, and deciding it twice is how the two ends drift.\n//\n// Delivery is non-blocking by construction \226\128\148 see the buffer note above.\n//\n// On a channel with an ACTIVE backend (a Postgres-backed database that is bound) the event is\n// not delivered here at all: it goes to the outbox, and this process's listeners receive it\n// through the same LISTEN path as every other instance's. That is what makes the instances\n// agree \226\128\148 a publish inside a rolled-back `transaction { }` reaches nobody, including the\n// browser connected to the instance that rolled back, and every instance delivers in outbox\n// order.\nfunc Publish(channel *SseChannel, key string, payload any) struct{} {\n\tif channel.backend != nil && channel.backend.active() {\n\t\tchannel.backend.publish(channel.name, key, EncodeJSONValue(payload))\n\t\treturn struct{}{}\n\t}\n\tdeliverLocal(channel, key, payload)\n\treturn struct{}{}\n}\n\n// deliverLocal fans one event out to THIS process's listeners on `key`. It is the whole of\n// `Publish` for a Memory-backed channel, and the last step of the backend's path for a\n// Postgres-backed one.\nfunc deliverLocal(channel *SseChannel, key string, payload any) {\n\tchannel.mutex.Lock()\n\tlisteners := make([]*sseListener, len(channel.listeners[key]))\n\tcopy(listeners, channel.listeners[key])\n\tchannel.mutex.Unlock()\n\tfor _, listener := range listeners {\n\t\tselect {\n\t\tcase listener.events <- payload:\n\t\tdefault:\n\t\t\t// This consumer is a whole buffer behind. The event is dropped for it alone, and\n\t\t\t// counted: a rising counter is the observable symptom of a stuck subscriber.\n\t\t\tCounter(\"tesl.sse.events.dropped\", FromInt64(1), sseChannelAttribute(channel.name))\n\t\t}\n\t}\n}\n\n// ResetChannel drops every listener, for a test block that starts from a channel nobody is on.\n// It is the channel's counterpart of `TableTruncate`.\nfunc ResetChannel(channel *SseChannel) {\n\tchannel.mutex.Lock()\n\tdefer channel.mutex.Unlock()\n\tchannel.listeners = map[string][]*sseListener{}\n\tchannel.active = 0\n}\n");
  ("sse_http.go", "package teslrt\n\nimport (\n\t\"bufio\"\n\t\"fmt\"\n\t\"io\"\n\t\"net/http\"\n\t\"net/http/httptest\"\n\t\"strings\"\n\t\"sync\"\n\t\"time\"\n)\n\n// The HTTP half of Server-Sent Events: the route that STREAMS a channel to a browser, and the\n// api-test surface that subscribes to it. Both need the HTTP runtime, so they live apart from\n// the channel itself \226\128\148 a module that only publishes ships no server.\n\n// sseEventBufferLimit is how many undelivered events ONE connection may hold; see the\n// never-block note on the channel itself.\nconst sseEventBufferLimit = 64\n\n// sseHeartbeatInterval is Racket's 10 seconds.\nconst sseHeartbeatInterval = 10 * time.Second\n\n// sseWriteDeadline bounds ONE write to a stream, re-armed before every frame including the\n// heartbeat. The server's `WriteTimeout` is armed once per request and covers the whole\n// response \226\128\148 right for a JSON answer, wrong for a stream that lives for the connection: left in\n// place it cut every `sse` route at 60 s (the first heartbeat past the deadline failed), so each\n// browser EventSource reconnected once a minute and lost whatever was published in between. A\n// ROLLING deadline rather than none keeps the other half of what `WriteTimeout` was buying: a\n// client that stops reading is still disconnected instead of pinning a goroutine, a listener and\n// a 64-event buffer forever, because a single write that has not completed within this window\n// means the socket is stalled, not merely quiet.\nconst sseWriteDeadline = 30 * time.Second\n\nfunc (channel *SseChannel) register(key string) *sseListener {\n\tlistener := &sseListener{events: make(chan any, sseEventBufferLimit)}\n\tchannel.mutex.Lock()\n\tchannel.listeners[key] = append(channel.listeners[key], listener)\n\tchannel.active++\n\tcount := channel.active\n\tchannel.mutex.Unlock()\n\tGauge(\"tesl.sse.connections.active\", float64(count), sseChannelAttribute(channel.name))\n\treturn listener\n}\n\n// unregister is idempotent: every exit path calls it, and a connection that ended twice (an\n// orderly close racing a cancelled request) must not corrupt the registry.\nfunc (channel *SseChannel) unregister(key string, listener *sseListener) {\n\tchannel.mutex.Lock()\n\tremaining := channel.listeners[key][:0]\n\tremoved := false\n\tfor _, registered := range channel.listeners[key] {\n\t\tif registered == listener && !removed {\n\t\t\tremoved = true\n\t\t\tcontinue\n\t\t}\n\t\tremaining = append(remaining, registered)\n\t}\n\tif len(remaining) == 0 {\n\t\t// Drop the KEY as well: a churn of one-off keys would otherwise leak an entry each.\n\t\tdelete(channel.listeners, key)\n\t} else {\n\t\tchannel.listeners[key] = remaining\n\t}\n\tif removed && channel.active > 0 {\n\t\tchannel.active--\n\t}\n\tcount := channel.active\n\tchannel.mutex.Unlock()\n\tif removed {\n\t\tGauge(\"tesl.sse.connections.active\", float64(count), sseChannelAttribute(channel.name))\n\t}\n}\n\n// SseStream is the `sse \"/path\" subscribe C(key)` route's handler. It streams until the client\n// goes away, and it removes its listener on EVERY exit path \226\128\148 a listener that outlives its\n// connection is charged to every future publish.\nfunc SseStream(channel *SseChannel, key string) func(http.ResponseWriter, *http.Request) {\n\treturn sseStream(channel, key, sseWriteDeadline)\n}\n\n// sseStream is SseStream with the per-write deadline as a parameter, so a test can prove that a\n// stalled client is dropped without waiting out the production window.\nfunc sseStream(channel *SseChannel, key string, writeDeadline time.Duration) func(http.ResponseWriter, *http.Request) {\n\treturn func(writer http.ResponseWriter, request *http.Request) {\n\t\tflusher, canFlush := writer.(http.Flusher)\n\t\tif !canFlush {\n\t\t\t// Nothing can be streamed to this client. Say so rather than opening a connection\n\t\t\t// that would silently never deliver.\n\t\t\thttp.Error(writer, \"streaming unsupported\", http.StatusInternalServerError)\n\t\t\treturn\n\t\t}\n\t\twriter.Header().Set(\"Content-Type\", \"text/event-stream\")\n\t\twriter.Header().Set(\"Cache-Control\", \"no-cache\")\n\t\twriter.Header().Set(\"Connection\", \"keep-alive\")\n\t\twriter.WriteHeader(http.StatusOK)\n\n\t\tlistener := channel.register(key)\n\t\tdefer channel.unregister(key, listener)\n\n\t\t// Rolled forward before EVERY write (see sseWriteDeadline); the controller reaches the\n\t\t// connection through the writer's Unwrap chain. A writer that cannot carry a deadline\n\t\t// (a test recorder) answers ErrNotSupported, which is no reason to refuse the stream \226\128\148\n\t\t// there is then no server timeout to outlive either.\n\t\tcontroller := http.NewResponseController(writer)\n\t\tarmWrite := func() {\n\t\t\t_ = controller.SetWriteDeadline(time.Now().Add(writeDeadline))\n\t\t}\n\n\t\t// An immediate comment so the browser fires onopen now rather than at the first\n\t\t// heartbeat: with chunked encoding it opens on the first body chunk.\n\t\tarmWrite()\n\t\tif _, err := writer.Write([]byte(\": ok\\n\\n\")); err != nil {\n\t\t\treturn\n\t\t}\n\t\tflusher.Flush()\n\n\t\theartbeat := time.NewTicker(sseHeartbeatInterval)\n\t\tdefer heartbeat.Stop()\n\t\tfor {\n\t\t\tselect {\n\t\t\tcase <-request.Context().Done():\n\t\t\t\treturn\n\t\t\tcase event := <-listener.events:\n\t\t\t\tbody := fmt.Sprintf(\"data: %s\\n\\n\", EncodeJSONValue(map[string]any{\n\t\t\t\t\t\"channel\": channel.name,\n\t\t\t\t\t\"payload\": event,\n\t\t\t\t}))\n\t\t\t\tarmWrite()\n\t\t\t\tif _, err := writer.Write([]byte(body)); err != nil {\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\tflusher.Flush()\n\t\t\t\tCounter(\"tesl.sse.events.sent\", FromInt64(1), sseChannelAttribute(channel.name))\n\t\t\tcase <-heartbeat.C:\n\t\t\t\tarmWrite()\n\t\t\t\tif _, err := writer.Write([]byte(\": heartbeat\\n\\n\")); err != nil {\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\tflusher.Flush()\n\t\t\t}\n\t\t}\n\t}\n}\n\n// SseStreamParam is the same route when the channel key comes from a `:param` SEGMENT of the\n// path (`sse \"/events/:userId\" subscribe Notices(userId)`): each connection keys on its own\n// segment, which is what makes the channel per-entity.\nfunc SseStreamParam(channel *SseChannel, pattern, param string) func(http.ResponseWriter, *http.Request) {\n\treturn func(writer http.ResponseWriter, request *http.Request) {\n\t\tkey, found := PathParam(pattern, request.URL.Path, param)\n\t\tif !found {\n\t\t\t// The router matched the pattern, so a missing segment is an emitter bug rather\n\t\t\t// than a client error \226\128\148 say so instead of streaming on an empty key.\n\t\t\thttp.Error(writer, \"stream key segment \"+param+\" is missing\", http.StatusInternalServerError)\n\t\t\treturn\n\t\t}\n\t\tSseStream(channel, key)(writer, request)\n\t}\n}\n\n// \226\148\128\226\148\128 api-test side \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// `subscribe \"/path\"` in an api-test opens a REAL connection to the emitted server and reads\n// the stream, rather than registering on the channel behind the route's back. That way the\n// test meets everything a browser would: the route lookup, the auth check, every declared\n// capture check, and the wire format itself. A subscription the server refuses fails the test\n// where it is written, with the status and message the client would have received.\n\ntype SseTestStream struct {\n\tname   string\n\tserver *httptest.Server\n\tbody   io.ReadCloser\n\tevents chan any\n\t// closed guards the teardown, which every exit path calls.\n\tclosed  bool\n\tmutex   sync.Mutex\n\tbacklog []any\n}\n\n// sseTestBufferLimit bounds what one test stream holds. A test that publishes more than this\n// without collecting is not measuring delivery any more.\nconst sseTestBufferLimit = 256\n\n// SubscribeStream opens `path` on the emitted server as an event stream. `cookies` are the\n// api-test cookie headers, so a stream behind `auth \226\128\166 via cookieAuth` can be subscribed the\n// way the endpoint expects.\nfunc SubscribeStream(server Server, path string, cookies []string) *SseTestStream {\n\ttestServer := httptest.NewServer(server)\n\trequest, err := http.NewRequest(http.MethodGet, testServer.URL+path, nil) //nolint:noctx // torn down by UnsubscribeStream\n\tif err != nil {\n\t\ttestServer.Close()\n\t\tpanic(\"subscribe: \" + path + \": \" + err.Error())\n\t}\n\trequest.Header.Set(\"Accept\", \"text/event-stream\")\n\tfor _, cookie := range cookies {\n\t\trequest.Header.Add(\"Cookie\", cookie)\n\t}\n\tresponse, err := http.DefaultClient.Do(request)\n\tif err != nil || response == nil {\n\t\ttestServer.Close()\n\t\tmessage := \"no response\"\n\t\tif err != nil {\n\t\t\tmessage = err.Error()\n\t\t}\n\t\tpanic(\"subscribe: \" + path + \": \" + message)\n\t}\n\tif response.StatusCode != http.StatusOK {\n\t\tbody, _ := io.ReadAll(io.LimitReader(response.Body, 4096))\n\t\t_ = response.Body.Close()\n\t\ttestServer.Close()\n\t\t// The status and message the CLIENT would have seen: a refused subscription is an\n\t\t// answer about the route, not a missing-events problem for the next assertion.\n\t\tpanic(fmt.Sprintf(\"subscribe failed for %s: %d %s\", path, response.StatusCode,\n\t\t\tstrings.TrimSpace(string(body))))\n\t}\n\tstream := &SseTestStream{\n\t\tname: path, server: testServer, body: response.Body,\n\t\tevents: make(chan any, sseTestBufferLimit),\n\t}\n\tgo stream.read()\n\treturn stream\n}\n\n// read turns the event lines into payloads. A heartbeat or the opening comment is not an\n// event; neither is a malformed line, which ends the stream rather than being reported as\n// data.\nfunc (stream *SseTestStream) read() {\n\treader := bufio.NewReader(stream.body)\n\tfor {\n\t\tline, err := reader.ReadString('\\n')\n\t\tif err != nil {\n\t\t\treturn\n\t\t}\n\t\tif !strings.HasPrefix(line, \"data: \") {\n\t\t\tcontinue\n\t\t}\n\t\tparsed, parseErr := ParseJSON([]byte(strings.TrimRight(strings.TrimPrefix(line, \"data: \"), \"\\r\\n\")))\n\t\tif parseErr != nil {\n\t\t\tcontinue\n\t\t}\n\t\t// What a test collects is the PAYLOAD, which is what Racket's api-test stream yields;\n\t\t// the channel name is already known from the path it subscribed to.\n\t\tevent := parsed\n\t\tif envelope, isObject := parsed.(map[string]any); isObject {\n\t\t\tif payload, present := envelope[\"payload\"]; present {\n\t\t\t\tevent = payload\n\t\t\t}\n\t\t}\n\t\tselect {\n\t\tcase stream.events <- event:\n\t\tdefault:\n\t\t\treturn\n\t\t}\n\t}\n}\n\n// UnsubscribeStream closes the connection and the test server behind it. Emitted at the end of\n// the block, so one block's stream cannot collect another's events.\nfunc UnsubscribeStream(stream *SseTestStream) {\n\tstream.mutex.Lock()\n\talready := stream.closed\n\tstream.closed = true\n\tstream.mutex.Unlock()\n\tif already {\n\t\treturn\n\t}\n\t_ = stream.body.Close()\n\tstream.server.Close()\n}\n\n// drain moves everything currently buffered into the backlog and answers it.\nfunc (stream *SseTestStream) drain() []any {\n\tstream.mutex.Lock()\n\tdefer stream.mutex.Unlock()\n\tfor {\n\t\tselect {\n\t\tcase event := <-stream.events:\n\t\t\tstream.backlog = append(stream.backlog, event)\n\t\tdefault:\n\t\t\tevents := make([]any, len(stream.backlog))\n\t\t\tcopy(events, stream.backlog)\n\t\t\treturn events\n\t\t}\n\t}\n}\n\nfunc (stream *SseTestStream) keep(from int) {\n\tstream.mutex.Lock()\n\tdefer stream.mutex.Unlock()\n\tif from >= len(stream.backlog) {\n\t\tstream.backlog = nil\n\t\treturn\n\t}\n\tstream.backlog = append([]any{}, stream.backlog[from:]...)\n}\n\n// ssePollInterval is Racket's 50ms poll; the collect loop is a poll on both backends because\n// the deadline belongs to the whole collect, not to one event.\nconst ssePollInterval = 50 * time.Millisecond\n\n// CollectCount waits for at least `count` events and answers everything drained \226\128\148 Racket's\n// `finish-all!`, which hands back the extra events rather than hiding them.\n//\n// A timeout is a test FAILURE, not an empty answer: the assertion that follows would otherwise\n// report \"expected non-empty\" for what is really \"the action never published\".\nfunc CollectCount(stream *SseTestStream, count Int, timeoutMillis Int) JsonValue {\n\twanted, exact := count.Int64()\n\tif !exact || wanted < 1 {\n\t\tpanic(\"collect: count must be a positive Int, got \" + count.String())\n\t}\n\tdeadline := time.Now().Add(sseTimeout(timeoutMillis))\n\tfor {\n\t\tevents := stream.drain()\n\t\tif int64(len(events)) >= wanted {\n\t\t\tstream.keep(len(events))\n\t\t\treturn JsonOf(events)\n\t\t}\n\t\tif !time.Now().Before(deadline) {\n\t\t\tpanic(sseTimeoutMessage(stream, timeoutMillis,\n\t\t\t\tfmt.Sprintf(\"count %d\", wanted), events))\n\t\t}\n\t\ttime.Sleep(ssePollInterval)\n\t}\n}\n\n// CollectUntil waits for an event MATCHING the pattern and answers the events up to and\n// including it; the rest stay on the stream for the next collect.\nfunc CollectUntil(stream *SseTestStream, until any, timeoutMillis Int) JsonValue {\n\tdeadline := time.Now().Add(sseTimeout(timeoutMillis))\n\tfor {\n\t\tevents := stream.drain()\n\t\tfor index, event := range events {\n\t\t\tif jsonMatch(until, event) {\n\t\t\t\tstream.keep(index + 1)\n\t\t\t\treturn JsonOf(events[:index+1])\n\t\t\t}\n\t\t}\n\t\tif !time.Now().Before(deadline) {\n\t\t\tpanic(sseTimeoutMessage(stream, timeoutMillis,\n\t\t\t\t\"until \"+EncodeJSONValue(until), events))\n\t\t}\n\t\ttime.Sleep(ssePollInterval)\n\t}\n}\n\n// CollectWithin waits out the whole timeout and answers whatever arrived \226\128\148 including nothing,\n// which is how a test asserts that an action published NO event.\nfunc CollectWithin(stream *SseTestStream, timeoutMillis Int) JsonValue {\n\tdeadline := time.Now().Add(sseTimeout(timeoutMillis))\n\tfor time.Now().Before(deadline) {\n\t\ttime.Sleep(ssePollInterval)\n\t}\n\tevents := stream.drain()\n\tstream.keep(len(events))\n\treturn JsonOf(events)\n}\n\nfunc sseTimeout(timeoutMillis Int) time.Duration {\n\tmillis, exact := timeoutMillis.Int64()\n\tif !exact || millis < 0 {\n\t\tpanic(\"collect: timeout must be a non-negative number of milliseconds, got \" +\n\t\t\ttimeoutMillis.String())\n\t}\n\treturn time.Duration(millis) * time.Millisecond\n}\n\nfunc sseTimeoutMessage(stream *SseTestStream, timeoutMillis Int, description string,\n\tevents []any) string {\n\tmillis, _ := timeoutMillis.Int64()\n\tduration := fmt.Sprintf(\"%dms\", millis)\n\tif millis%1000 == 0 {\n\t\tduration = fmt.Sprintf(\"%ds\", millis/1000)\n\t}\n\treturn fmt.Sprintf(\n\t\t\"collect: timed out after %s waiting for %s\\nreceived %d events on stream %q\\n\"+\n\t\t\t\"hint: did the action that produces events run successfully?\",\n\t\tduration, description, len(events), stream.name)\n}\n");
  ("sso.go", "package teslrt\n\nimport (\n\t\"crypto/hmac\"\n\t\"crypto/sha256\"\n\t\"encoding/base64\"\n\t\"encoding/binary\"\n\t\"encoding/hex\"\n\t\"encoding/json\"\n\t\"net/url\"\n\t\"regexp\"\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n)\n\n// Tesl's SSO runtime \226\128\148 OIDC and plain OAuth2. A port of `dsl/sso.rkt`, and it keeps that\n// module's split: a PURE layer of deterministic security helpers (here) and an ORCHESTRATION\n// layer that drives the HTTP client (sso_flow.go). The account-takeover-class bugs live in\n// the pure layer, which is why it is the half with no I/O in it at all.\n//\n// The third-party identity is exchanged ONCE, at the callback, for Tesl's own\n// `__Host-session` cookie, so every existing session and proof surface is untouched.\n\n// \226\148\128\226\148\128 PKCE (RFC 7636), S256 only \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n// challenge = BASE64URL(SHA256(ASCII(verifier))). `plain` is never produced, and a provider\n// that does not advertise S256 is refused upstream.\nfunc pkceChallenge(verifier string) string {\n\tsum := sha256.Sum256([]byte(verifier))\n\treturn base64.RawURLEncoding.EncodeToString(sum[:])\n}\n\n// \226\148\128\226\148\128 SsoSubjectKey: an INJECTIVE derivation of (issuer, subject) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n// Naive concatenation lets (\"https://a\", \"x|https://b\") collide with (\"https://a|x\",\n// \"https://b\"). Each component is length-prefixed with an 8-byte big-endian length before\n// hashing, so the encoding is injective and a cross-issuer collision is impossible. The\n// result is opaque hex with no email inside it, so a schema cannot key a user on an address.\nfunc ssoSubjectKey(issuer, subject string) string {\n\tprefixed := func(text string) []byte {\n\t\traw := []byte(text)\n\t\tout := make([]byte, 8, 8+len(raw))\n\t\tbinary.BigEndian.PutUint64(out, uint64(len(raw)))\n\t\treturn append(out, raw...)\n\t}\n\tsum := sha256.Sum256(append(prefixed(issuer), prefixed(subject)...))\n\treturn hex.EncodeToString(sum[:])\n}\n\n// \226\148\128\226\148\128 EmailClaim: verified-ness is a CONSTRUCTOR, not a sibling boolean \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n// \"verified\" is reachable ONLY with a positive verification signal and a non-empty address,\n// so a provider that emits no `email_verified` (Entra) can never yield it \226\128\148 the nOAuth\n// containment expressed as a rule rather than as a comment.\nconst (\n\temailNone       = \"none\"\n\temailUnverified = \"unverified\"\n\temailVerified   = \"verified\"\n)\n\nfunc emailClaim(email string, verifiedSignal bool) (string, string) {\n\ttrimmed := strings.TrimSpace(email)\n\tswitch {\n\tcase trimmed == \"\":\n\t\treturn emailNone, \"\"\n\tcase verifiedSignal:\n\t\treturn emailVerified, trimmed\n\tdefault:\n\t\treturn emailUnverified, trimmed\n\t}\n}\n\n// \226\148\128\226\148\128 Domain restriction (runtime-enforced, verified-email only) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n// Case-insensitive over trimmed domains, with the FQDN root canonicalised\n// (`example.com.` is `example.com`) so a trailing-dot form cannot slip past an allow-list\n// written without one. Both the incoming domain AND every allow-list entry go through this,\n// so a homoglyph label is correctly a DIFFERENT domain and is refused fail-closed. Full\n// IDNA/punycode folding is a documented gap, and it is the safe direction: a legitimate IDN\n// written in the other form is a false negative, never a false accept.\nvar trailingDots = regexp.MustCompile(`\\.+$`)\n\nfunc normalizeDomain(domain string) string {\n\treturn trailingDots.ReplaceAllString(strings.ToLower(strings.TrimSpace(domain)), \"\")\n}\n\nfunc emailDomainOf(email string) string {\n\tat := strings.LastIndex(email, \"@\")\n\tif at < 0 || at == len(email)-1 {\n\t\treturn \"\"\n\t}\n\treturn normalizeDomain(email[at+1:])\n}\n\n// An EMPTY allow-list is no restriction. A non-empty one requires the address to be\n// VERIFIED and its domain a member: restricting by an address the provider never verified is\n// the same takeover in disguise.\nfunc emailDomainAllowed(tag, email string, allowed []string) bool {\n\tif len(allowed) == 0 {\n\t\treturn true\n\t}\n\tif tag != emailVerified {\n\t\treturn false\n\t}\n\tdomain := emailDomainOf(email)\n\tfor _, each := range allowed {\n\t\tif normalizeDomain(each) == domain {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// Empty is no restriction. Non-empty requires the `hd` claim to be PRESENT and a member: an\n// absent claim is a refusal, not a pass.\nfunc hostedDomainAllowed(hostedDomain string, allowed []string) bool {\n\tif len(allowed) == 0 {\n\t\treturn true\n\t}\n\tif strings.TrimSpace(hostedDomain) == \"\" {\n\t\treturn false\n\t}\n\tnormalized := normalizeDomain(hostedDomain)\n\tfor _, each := range allowed {\n\t\tif normalizeDomain(each) == normalized {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// \226\148\128\226\148\128 OIDC claim validation (fail-closed) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n// Answers \"\" on success or a short reason on failure. Signature verification is a SEPARATE\n// step: this is \"what login does this token belong to\", not \"who wrote it\".\nvar tenantTemplate = regexp.MustCompile(`\\{tenantid\\}`)\n\nfunc issuerIsTemplate(issuer string) bool { return tenantTemplate.MatchString(issuer) }\n\nfunc audienceContains(audience any, clientID string) bool {\n\tswitch value := audience.(type) {\n\tcase string:\n\t\treturn value == clientID\n\tcase []any:\n\t\tfor _, each := range value {\n\t\t\tif text, isText := each.(string); isText && text == clientID {\n\t\t\t\treturn true\n\t\t\t}\n\t\t}\n\t}\n\treturn false\n}\n\ntype oidcClaimRules struct {\n\tissuer         string\n\tclientID       string\n\tnonce          string\n\tnow            int64\n\tleeway         int64\n\tflowStart      int64\n\tallowedTenants []string\n}\n\nfunc validateOidcClaims(claims map[string]any, rules oidcClaimRules) string {\n\ttext := func(key string) string {\n\t\tvalue, _ := claims[key].(string)\n\t\treturn value\n\t}\n\tsubject, issuer, tenant := text(\"sub\"), text(\"iss\"), text(\"tid\")\n\tswitch {\n\tcase subject == \"\":\n\t\treturn \"subject (sub) absent or empty\"\n\tcase claims[\"iss\"] == nil || issuer == \"\":\n\t\treturn \"issuer (iss) absent\"\n\t}\n\tif issuerIsTemplate(rules.issuer) || len(rules.allowedTenants) > 0 {\n\t\tif len(rules.allowedTenants) == 0 {\n\t\t\treturn \"templated issuer requires a non-empty allowedTenants\"\n\t\t}\n\t\tmember := false\n\t\tfor _, allowed := range rules.allowedTenants {\n\t\t\tif allowed == tenant {\n\t\t\t\tmember = true\n\t\t\t}\n\t\t}\n\t\tif tenant == \"\" || !member {\n\t\t\treturn \"tid not in allowedTenants\"\n\t\t}\n\t\tif issuer != tenantTemplate.ReplaceAllLiteralString(rules.issuer, tenant) {\n\t\t\treturn \"iss does not match the tenant-substituted issuer\"\n\t\t}\n\t} else if issuer != rules.issuer {\n\t\treturn \"iss does not match the configured issuer\"\n\t}\n\treturn validateOidcRest(claims, rules)\n}\n\nfunc validateOidcRest(claims map[string]any, rules oidcClaimRules) string {\n\tif !audienceContains(claims[\"aud\"], rules.clientID) {\n\t\treturn \"aud does not contain the client id\"\n\t}\n\tif authorized, present := claims[\"azp\"].(string); present && authorized != rules.clientID {\n\t\treturn \"azp present and not the client id\"\n\t}\n\tnonce, hasNonce := claims[\"nonce\"].(string)\n\tif !hasNonce || rules.nonce == \"\" ||\n\t\t!hmac.Equal([]byte(nonce), []byte(rules.nonce)) {\n\t\treturn \"nonce absent or mismatched\"\n\t}\n\texpires, hasExpiry := jsonNumber(claims[\"exp\"])\n\tif !hasExpiry || rules.now > expires+rules.leeway {\n\t\treturn \"token expired or exp absent/non-numeric\"\n\t}\n\tissuedAt, hasIssuedAt := jsonNumber(claims[\"iat\"])\n\tif !hasIssuedAt {\n\t\treturn \"iat absent or non-numeric\"\n\t}\n\tif issuedAt > rules.now+rules.leeway {\n\t\treturn \"iat is in the future beyond leeway\"\n\t}\n\tif rules.flowStart > 0 && issuedAt < rules.flowStart-rules.leeway {\n\t\treturn \"iat predates the in-flight login start\"\n\t}\n\treturn \"\"\n}\n\n// jsonNumber reads a JSON number however it was decoded: `json.Number` when the decoder was\n// asked to keep precision (which is how ParseJSON reads a body), float64 otherwise.\nfunc jsonNumber(value any) (int64, bool) {\n\tswitch number := value.(type) {\n\tcase json.Number:\n\t\tparsed, err := number.Int64()\n\t\tif err != nil {\n\t\t\tasFloat, floatErr := number.Float64()\n\t\t\treturn int64(asFloat), floatErr == nil\n\t\t}\n\t\treturn parsed, true\n\tcase float64:\n\t\treturn int64(number), true\n\tcase int64:\n\t\treturn number, true\n\t}\n\treturn 0, false\n}\n\n// \226\148\128\226\148\128 The authorize URL: reserved names refused, everything percent-encoded \226\148\128\226\148\128\226\148\128\226\148\128\nvar reservedAuthorizeParams = []string{\n\t\"client_id\", \"redirect_uri\", \"response_type\", \"scope\", \"state\", \"nonce\",\n\t\"code_challenge\", \"code_challenge_method\", \"code_verifier\", \"client_secret\",\n\t\"grant_type\", \"code\",\n}\n\n// The first reserved name an extra-params list sets, or \"\".\nfunc extraParamsReservedViolation(extra []Tuple2[string, string]) string {\n\tfor _, pair := range extra {\n\t\tfor _, reserved := range reservedAuthorizeParams {\n\t\t\tif pair.Tuple2First == reserved {\n\t\t\t\treturn pair.Tuple2First\n\t\t\t}\n\t\t}\n\t}\n\treturn \"\"\n}\n\n// framework is the flow's own parameters; extra is the app's `extraAuthorizeParams`. Both\n// the key and the value are percent-encoded, so no value can smuggle an `&` or an `=`.\nfunc buildAuthorizeURL(authorizeURL string, framework, extra []Tuple2[string, string]) string {\n\tif bad := extraParamsReservedViolation(extra); bad != \"\" {\n\t\tpanic(\"sso: extraAuthorizeParams may not set the reserved name \" + bad)\n\t}\n\tparts := make([]string, 0, len(framework)+len(extra))\n\tfor _, pair := range append(append([]Tuple2[string, string]{}, framework...), extra...) {\n\t\tparts = append(parts,\n\t\t\turl.QueryEscape(pair.Tuple2First)+\"=\"+url.QueryEscape(pair.Tuple2Second))\n\t}\n\tseparator := \"?\"\n\tif strings.Contains(authorizeURL, \"?\") {\n\t\tseparator = \"&\"\n\t}\n\treturn authorizeURL + separator + strings.Join(parts, \"&\")\n}\n\n// \226\148\128\226\148\128 The `__Host-oauth` cookie: integrity-protected in-flight state \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n// The cookie value is CLIENT-WRITABLE (HttpOnly stops reading, not choosing), so the nonce,\n// the PKCE verifier, the start time and the route segment are authenticated under a subkey\n// DERIVED from the session key with domain separation \226\128\148 an HMAC used as a one-block KDF,\n// never the raw key that signs the session JWT. Verification runs against [current,\n// previous] so a key rotation does not break an in-flight login. NOTHING inside is trusted\n// before the MAC verifies.\nconst oauthCookieKdfContext = \"tesl/sso __Host-oauth v1\"\n\nfunc oauthSubkey(sessionKey string) []byte {\n\tmac := hmac.New(sha256.New, []byte(sessionKey))\n\tmac.Write([]byte(oauthCookieKdfContext))\n\treturn mac.Sum(nil)\n}\n\n// oauthState is what the cookie carries between the login redirect and the callback.\ntype oauthState struct {\n\tSegment  string `json:\"seg\"`\n\tState    string `json:\"state\"`\n\tNonce    string `json:\"nonce\"`\n\tVerifier string `json:\"v\"`\n\tStarted  int64  `json:\"ts\"`\n}\n\nfunc oauthCookieSeal(fields oauthState, sessionKey string) string {\n\tpayload, err := json.Marshal(fields)\n\tif err != nil {\n\t\tpanic(\"sso: the in-flight login state does not encode\")\n\t}\n\tencoded := base64.RawURLEncoding.EncodeToString(payload)\n\tmac := hmac.New(sha256.New, oauthSubkey(sessionKey))\n\tmac.Write([]byte(encoded))\n\treturn encoded + \".\" + base64.RawURLEncoding.EncodeToString(mac.Sum(nil))\n}\n\n// oauthCookieOpen verifies and opens the cookie. `segment` is the CALLBACK's own route\n// segment: a cookie minted at one `sso` clause must not open at another's callback.\nfunc oauthCookieOpen(cookie, segment string, sessionKeys []string) (oauthState, bool) {\n\tvar empty oauthState\n\tparts := strings.Split(cookie, \".\")\n\tif len(parts) != 2 {\n\t\treturn empty, false\n\t}\n\tencoded, presentedMac := parts[0], parts[1]\n\tgiven, err := base64.RawURLEncoding.DecodeString(presentedMac)\n\tif err != nil {\n\t\treturn empty, false\n\t}\n\tverified := false\n\tfor _, key := range sessionKeys {\n\t\tif key == \"\" {\n\t\t\tcontinue\n\t\t}\n\t\tmac := hmac.New(sha256.New, oauthSubkey(key))\n\t\tmac.Write([]byte(encoded))\n\t\tif hmac.Equal(mac.Sum(nil), given) {\n\t\t\tverified = true\n\t\t}\n\t}\n\tif !verified {\n\t\treturn empty, false\n\t}\n\t// The MAC verified: only NOW is the payload parsed and its segment checked.\n\tpayload, err := base64.RawURLEncoding.DecodeString(encoded)\n\tif err != nil {\n\t\treturn empty, false\n\t}\n\tvar fields oauthState\n\tif json.Unmarshal(payload, &fields) != nil {\n\t\treturn empty, false\n\t}\n\tif fields.Segment != segment {\n\t\treturn empty, false\n\t}\n\treturn fields, true\n}\n\n// \226\148\128\226\148\128 Provider defaults, as data \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n// Minimal scopes BY RULE, not by preference: a defaults table is exactly where an over-broad\n// scope silently becomes every app's default. Widening is the app's explicit record update.\n\n// SsoConnection is a configured identity provider. It is OPAQUE on the Tesl side \226\128\148 built by\n// `Sso.defaults` or `Sso.oidc`, narrowed by the allow-list builders, and read by nothing \226\128\148\n// so a program cannot assemble one whose endpoints skipped the rules below.\ntype SsoConnection struct {\n\tKind          string // \"oidc\" | \"oauth2\"\n\tIssuer        string\n\tAuthorizeURL  string\n\tTokenURL      string\n\tUserinfoURL   string\n\tEmailsURL     string\n\tJwksURL       string\n\tEndSessionURL string\n\tSigningAlgs   []string\n\tClientID      string\n\tClientSecret  Secret\n\tScopes        []string\n\n\tSubjectField       string\n\tEmailField         string\n\tEmailVerifiedField string\n\tNameField          string\n\n\tAllowedEmailDomains  []string\n\tAllowedHostedDomains []string\n\tAllowedTenants       []string\n}\n\n// SsoDefaults is `Sso.defaults <Provider> clientId clientSecret`.\nfunc SsoDefaults(provider, clientID string, clientSecret Secret) SsoConnection {\n\tswitch provider {\n\tcase \"Google\":\n\t\treturn SsoConnection{\n\t\t\tKind: \"oidc\", Issuer: \"https://accounts.google.com\",\n\t\t\tClientID: clientID, ClientSecret: clientSecret,\n\t\t\tScopes: []string{\"openid\", \"email\", \"profile\"},\n\t\t}\n\tcase \"GitHub\":\n\t\t// #nosec G101 -- These are PUBLIC endpoint URLs, not credentials. The rule matches\n\t\t// any constant string assigned to a field whose name contains \"token\", and the\n\t\t// OAuth2 spec's name for the exchange endpoint is the token endpoint. The two\n\t\t// credential fields beside them take their values from the caller.\n\t\treturn SsoConnection{\n\t\t\tKind:         \"oauth2\",\n\t\t\tAuthorizeURL: \"https://github.com/login/oauth/authorize\",\n\t\t\tTokenURL:     \"https://github.com/login/oauth/access_token\",\n\t\t\tUserinfoURL:  \"https://api.github.com/user\",\n\t\t\t// A SECOND call for the primary verified address: GitHub's profile email is\n\t\t\t// public and may be unverified, and only a verified one may be trusted.\n\t\t\tEmailsURL: \"https://api.github.com/user/emails\",\n\t\t\tClientID:  clientID, ClientSecret: clientSecret,\n\t\t\tScopes:       []string{\"user:email\"},\n\t\t\tSubjectField: \"id\", EmailField: \"email\", NameField: \"name\",\n\t\t}\n\tcase \"Discord\":\n\t\t// #nosec G101 -- A public endpoint URL, as above.\n\t\treturn SsoConnection{\n\t\t\tKind:         \"oauth2\",\n\t\t\tAuthorizeURL: \"https://discord.com/api/oauth2/authorize\",\n\t\t\tTokenURL:     \"https://discord.com/api/oauth2/token\",\n\t\t\tUserinfoURL:  \"https://discord.com/api/users/@me\",\n\t\t\tClientID:     clientID, ClientSecret: clientSecret,\n\t\t\tScopes:       []string{\"identify\", \"email\"},\n\t\t\tSubjectField: \"id\", EmailField: \"email\",\n\t\t\tEmailVerifiedField: \"verified\", NameField: \"username\",\n\t\t}\n\tdefault:\n\t\tpanic(\"Sso.defaults: unknown provider: \" + provider)\n\t}\n}\n\n// SsoOidc is a generic OIDC connection by ISSUER URL \226\128\148 a self-hosted Keycloak or dex, Okta,\n// Auth0, a single-tenant Entra. The blessed providers above bake real endpoints; this one\n// discovers them from the issuer's /.well-known/openid-configuration, so the same signature\n// and claim trust argument applies.\nfunc SsoOidc(issuer, clientID string, clientSecret Secret) SsoConnection {\n\treturn SsoConnection{\n\t\tKind: \"oidc\", Issuer: issuer,\n\t\tClientID: clientID, ClientSecret: clientSecret,\n\t\tScopes: []string{\"openid\", \"email\", \"profile\"},\n\t}\n}\n\n// The allow-list builders answer a NARROWED copy, which is what makes them chainable and\n// what keeps a connection immutable once a login is using it.\nfunc SsoAllowedEmailDomains(conn SsoConnection, domains []string) SsoConnection {\n\tconn.AllowedEmailDomains = append([]string{}, domains...)\n\treturn conn\n}\n\nfunc SsoAllowedHostedDomains(conn SsoConnection, domains []string) SsoConnection {\n\tconn.AllowedHostedDomains = append([]string{}, domains...)\n\treturn conn\n}\n\nfunc SsoAllowedTenants(conn SsoConnection, tenants []string) SsoConnection {\n\tconn.AllowedTenants = append([]string{}, tenants...)\n\treturn conn\n}\n\n// For the plain-OAuth2 family there is no issuer claim, so the identity key's issuer is\n// SYNTHESISED from the scheme and host of the userinfo URL \226\128\148 stable across a route-segment\n// rename and across an in-path API version bump.\nfunc synthesizeIssuer(userinfoURL string) string {\n\tparsed, err := url.Parse(userinfoURL)\n\tif err != nil || parsed.Scheme == \"\" || parsed.Host == \"\" {\n\t\treturn userinfoURL\n\t}\n\treturn parsed.Scheme + \"://\" + parsed.Host\n}\n\n// \226\148\128\226\148\128 Single-use `state`, honestly scoped (per process) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n// A bounded, TTL'd set of spent `state` values makes a second presentation fail WITHIN a\n// process. Across processes the guarantee is the provider's single-use `code` plus the PKCE\n// binding \226\128\148 this is not a cluster-wide claim. Bounded so it cannot become a\n// memory-amplification primitive.\nconst (\n\tspentStateMax = 10000\n\tspentStateTTL = 600\n)\n\nvar (\n\tspentStateMutex sync.Mutex\n\tspentStates     = map[string]int64{}\n)\n\n// stateSpend answers true when `state` was newly spent (accept) and false when it was\n// already spent (a replay).\nfunc stateSpend(state string, now int64) bool {\n\tspentStateMutex.Lock()\n\tdefer spentStateMutex.Unlock()\n\tfor key, expiry := range spentStates {\n\t\tif expiry < now {\n\t\t\tdelete(spentStates, key)\n\t\t}\n\t}\n\tif _, spent := spentStates[state]; spent {\n\t\treturn false\n\t}\n\tif len(spentStates) >= spentStateMax {\n\t\t// Drop the whole set rather than grow unbounded: the provider's single-use `code`\n\t\t// still holds, so this fails closed to a fresh flow rather than to a leak.\n\t\tspentStates = map[string]int64{}\n\t}\n\tspentStates[state] = now + spentStateTTL\n\treturn true\n}\n\n// SsoSpentStatesReset is the test-only escape hatch: one process running many cases against\n// the same fixed `state` literals has to clear this between them. A real server never calls\n// it, which is why it takes no argument and says so in its name.\nfunc SsoSpentStatesReset() { //nolint:unused // the emitted per-test reset calls it\n\tspentStateMutex.Lock()\n\tdefer spentStateMutex.Unlock()\n\tspentStates = map[string]int64{}\n}\n\n// \226\148\128\226\148\128 SSRF preflight \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n// A reason when the URL's host is a forbidden literal address, \"\" otherwise. A HOSTNAME\n// passes through: the resolve-then-connect-pin step belongs to the HTTP client's socket\n// integration, and the classifier both use is the same one.\nfunc urlSsrfViolation(rawURL string) string {\n\tparsed, err := url.Parse(rawURL)\n\tif err != nil || parsed.Host == \"\" {\n\t\treturn \"URL has no host\"\n\t}\n\thost := parsed.Hostname()\n\tif !literalIP(host) {\n\t\treturn \"\"\n\t}\n\treturn IPForbiddenReason(host)\n}\n\nvar (\n\tdottedQuad = regexp.MustCompile(`^[0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]+$`)\n\tbareIPv6   = regexp.MustCompile(`^[0-9a-fA-F:]+$`)\n)\n\nfunc literalIP(host string) bool {\n\treturn dottedQuad.MatchString(host) || bareIPv6.MatchString(host)\n}\n\n// \226\148\128\226\148\128 The identity handed to `onIdentity` \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// SsoIdentity is the verified third-party identity. Opaque on the Tesl side and read through\n// the accessors below, so an app cannot reach a claim the rules above have not been applied\n// to \226\128\148 the email in particular is present only in the form the provider VERIFIED.\ntype SsoIdentity struct {\n\tKey      string\n\tIssuer   string\n\tProvider string\n\tSubject  string\n\tTenant   string\n\tEmailTag string\n\tEmail    string\n\tName     string\n\tClaims   map[string]any\n}\n\n// SsoSubjectKeyValue is the opaque identity key a schema keys a user on: a hash of\n// (issuer, subject) with no email in it.\ntype SsoSubjectKeyValue struct {\n\tValue string\n}\n\nfunc SsoKeyText(key SsoSubjectKeyValue) string { return key.Value }\n\nfunc SsoSubject(identity SsoIdentity) string { return identity.Subject }\n\n// SsoEmail answers the VERIFIED address only. An app cannot obtain an unverified one, so it\n// cannot trust one by accident \226\128\148 which is the whole of the nOAuth containment.\nfunc SsoEmail(identity SsoIdentity) Maybe[string] {\n\tif identity.EmailTag != emailVerified || identity.Email == \"\" {\n\t\treturn Nothing[string]()\n\t}\n\treturn Something(identity.Email)\n}\n\nfunc SsoTenant(identity SsoIdentity) Maybe[string] {\n\tif identity.Tenant == \"\" {\n\t\treturn Nothing[string]()\n\t}\n\treturn Something(identity.Tenant)\n}\n\n// SsoClaim reads one claim by name, as text. A claim that is absent, null or not a scalar is\n// Nothing rather than a rendering of whatever it was.\nfunc SsoClaim(identity SsoIdentity, name string) Maybe[string] {\n\tvalue, present := identity.Claims[name]\n\tif !present {\n\t\treturn Nothing[string]()\n\t}\n\tswitch typed := value.(type) {\n\tcase string:\n\t\treturn Something(typed)\n\tcase bool:\n\t\treturn Something(strconv.FormatBool(typed))\n\tcase json.Number:\n\t\treturn Something(typed.String())\n\tcase float64:\n\t\treturn Something(strconv.FormatFloat(typed, 'f', -1, 64))\n\t}\n\treturn Nothing[string]()\n}\n");
  ("sso_flow.go", "package teslrt\n\nimport (\n\t\"crypto/subtle\"\n\t\"encoding/base64\"\n\t\"encoding/json\"\n\t\"errors\"\n\t\"net/url\"\n\t\"regexp\"\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n)\n\n// The SSO ORCHESTRATION layer: it drives the HTTP client, which is what makes it stubbable\n// through the same hook an api-test's `stubHttp` installs.\n//\n// Every outbound leg is https-only and SSRF-preflighted, and it does not follow redirects:\n// `fetch` asks the client for `redirectRefused`, so a 3xx from a provider is the leg's final\n// answer and, being non-200, a failed leg. Following it would re-run the https and SSRF\n// checks on a URL the provider chose \226\128\148 not the configured one \226\128\148 and would carry the\n// client_secret_basic Authorization header along. A provider's own `error`/\n// `error_description` text is NEVER reflected \226\128\148 a failure is a fixed reason of our own \226\128\148 and\n// the client secret travels in the Authorization header (client_secret_basic), never in a URL.\n\n// ssoOutcome is what the callback produced: an identity, or a fixed reason.\ntype ssoOutcome struct {\n\tOK       bool\n\tReason   string\n\tIdentity SsoIdentity\n}\n\nfunc ssoFail(reason string) ssoOutcome { return ssoOutcome{Reason: reason} }\n\n// ssoError is the internal failure of one leg. It is converted to a fixed reason at the\n// boundary, so a provider's response text cannot reach a caller through it.\ntype ssoError struct{ reason string }\n\nfunc (err ssoError) Error() string { return err.reason }\n\nfunc requireHTTPS(who, target string) error {\n\tif !strings.HasPrefix(target, \"https://\") {\n\t\treturn ssoError{who + \": endpoint must be https\"}\n\t}\n\tif violation := urlSsrfViolation(target); violation != \"\" {\n\t\treturn ssoError{who + \": SSRF-forbidden host: \" + violation}\n\t}\n\treturn nil\n}\n\n// getJSON and postJSON are the two outbound shapes. A non-200 is a failure of the leg, not\n// a body to inspect: the provider's error text is exactly what must not be reflected.\nfunc getJSON(who, target string, headers []Tuple2[string, string]) (map[string]any, error) {\n\tbody, err := fetch(who, \"GET\", target, headers, \"\")\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tvar parsed map[string]any\n\tif json.Unmarshal([]byte(body), &parsed) != nil {\n\t\treturn nil, ssoError{who + \": response is not a JSON object\"}\n\t}\n\treturn parsed, nil\n}\n\nfunc getJSONArray(who, target string, headers []Tuple2[string, string]) ([]any, error) {\n\tbody, err := fetch(who, \"GET\", target, headers, \"\")\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tvar parsed []any\n\tif json.Unmarshal([]byte(body), &parsed) != nil {\n\t\treturn nil, ssoError{who + \": response is not a JSON array\"}\n\t}\n\treturn parsed, nil\n}\n\nfunc postJSON(who, target string, headers []Tuple2[string, string], body string) (map[string]any, error) {\n\traw, err := fetch(who, \"POST\", target, headers, body)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tvar parsed map[string]any\n\tif json.Unmarshal([]byte(raw), &parsed) != nil {\n\t\treturn nil, ssoError{who + \": response is not a JSON object\"}\n\t}\n\treturn parsed, nil\n}\n\nfunc fetch(who, method, target string, headers []Tuple2[string, string], body string) (string, error) {\n\tif err := requireHTTPS(who, target); err != nil {\n\t\treturn \"\", err\n\t}\n\tvar bodyPointer *string\n\tif method == \"POST\" {\n\t\tbodyPointer = &body\n\t}\n\t// The same client path `HttpClient.get`/`post` take \226\128\148 same header guard, same api-test\n\t// stubs, same egress and TLS treatment \226\128\148 but with redirects REFUSED rather than followed.\n\tresponse := httpRequestPolicy(method, target, headers, bodyPointer, redirectRefused)\n\tstatus, _ := response.Status.Int64()\n\tif status != 200 {\n\t\treturn \"\", ssoError{who + \": non-200 response\"}\n\t}\n\treturn response.Body, nil\n}\n\nfunc formEncode(pairs []Tuple2[string, string]) string {\n\tparts := make([]string, 0, len(pairs))\n\tfor _, pair := range pairs {\n\t\tparts = append(parts,\n\t\t\turl.QueryEscape(pair.Tuple2First)+\"=\"+url.QueryEscape(pair.Tuple2Second))\n\t}\n\treturn strings.Join(parts, \"&\")\n}\n\n// basicAuth is the ONE place the client secret is unwrapped to its raw text: at the HTTP\n// boundary, for client_secret_basic. Everywhere else the connection keeps the redacting\n// `Secret`, so a log line or a formatted error cannot carry it.\nfunc basicAuth(clientID string, clientSecret Secret) string {\n\traw := clientID + \":\" + clientSecret.Value.Reveal()\n\treturn \"Basic \" + base64.StdEncoding.EncodeToString([]byte(raw))\n}\n\n// \226\148\128\226\148\128 OIDC discovery \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n// Fetch, validate, and answer the endpoints. The document's own issuer must equal the\n// configured one exactly, EXCEPT for the templated multi-tenant case, which is accepted here\n// and enforced at claim time by the tid-substitution rule. S256 must be advertised: a\n// provider that does not do PKCE is not one this runtime will start a flow with.\nvar trailingSlashes = regexp.MustCompile(`/+$`)\n\nfunc oidcDiscover(conn SsoConnection) (SsoConnection, error) {\n\tbase := trailingSlashes.ReplaceAllString(conn.Issuer, \"\")\n\tdocument, err := getJSON(\"sso-discovery\", base+\"/.well-known/openid-configuration\", nil)\n\tif err != nil {\n\t\treturn conn, err\n\t}\n\tdocumentIssuer, _ := document[\"issuer\"].(string)\n\tif documentIssuer != conn.Issuer && !issuerIsTemplate(documentIssuer) {\n\t\treturn conn, ssoError{\"sso-discovery: discovery issuer does not match the configured issuer\"}\n\t}\n\tmethods, _ := document[\"code_challenge_methods_supported\"].([]any)\n\tadvertisesS256 := false\n\tfor _, each := range methods {\n\t\tif text, isText := each.(string); isText && text == \"S256\" {\n\t\t\tadvertisesS256 = true\n\t\t}\n\t}\n\tif !advertisesS256 {\n\t\treturn conn, ssoError{\"sso-discovery: provider does not advertise PKCE S256\"}\n\t}\n\tresolved := conn\n\tresolved.AuthorizeURL, _ = document[\"authorization_endpoint\"].(string)\n\tresolved.TokenURL, _ = document[\"token_endpoint\"].(string)\n\tresolved.JwksURL, _ = document[\"jwks_uri\"].(string)\n\tresolved.EndSessionURL, _ = document[\"end_session_endpoint\"].(string)\n\tresolved.SigningAlgs = nil\n\tif algs, ok := document[\"id_token_signing_alg_values_supported\"].([]any); ok {\n\t\tfor _, each := range algs {\n\t\t\tif text, isText := each.(string); isText {\n\t\t\t\tresolved.SigningAlgs = append(resolved.SigningAlgs, text)\n\t\t\t}\n\t\t}\n\t}\n\tif resolved.AuthorizeURL == \"\" || resolved.TokenURL == \"\" {\n\t\treturn conn, ssoError{\"sso-discovery: discovery document is missing an endpoint\"}\n\t}\n\treturn resolved, nil\n}\n\nfunc resolveEndpoints(conn SsoConnection) (SsoConnection, error) {\n\tswitch conn.Kind {\n\tcase \"oidc\":\n\t\treturn oidcDiscover(conn)\n\tcase \"oauth2\":\n\t\treturn conn, nil\n\tdefault:\n\t\treturn conn, ssoError{\"sso: unknown connection kind\"}\n\t}\n}\n\n// \226\148\128\226\148\128 Beginning a login \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n// Resolve the endpoints, build the authorize URL and the sealed `__Host-oauth` cookie. The\n// state, nonce and verifier are SUPPLIED by the caller rather than drawn here, which is what\n// keeps this deterministic and therefore testable.\nfunc ssoBeginLogin(conn SsoConnection, segment, redirectURI, sessionKey,\n\tstate, nonce, verifier string, now int64) (string, string, error) {\n\tendpoints, err := resolveEndpoints(conn)\n\tif err != nil {\n\t\treturn \"\", \"\", err\n\t}\n\tscopes := conn.Scopes\n\tif len(scopes) == 0 {\n\t\tscopes = []string{\"openid\", \"email\", \"profile\"}\n\t}\n\tframework := []Tuple2[string, string]{\n\t\t{Tuple2First: \"client_id\", Tuple2Second: conn.ClientID},\n\t\t{Tuple2First: \"redirect_uri\", Tuple2Second: redirectURI},\n\t\t{Tuple2First: \"response_type\", Tuple2Second: \"code\"},\n\t\t{Tuple2First: \"scope\", Tuple2Second: strings.Join(scopes, \" \")},\n\t\t{Tuple2First: \"state\", Tuple2Second: state},\n\t\t{Tuple2First: \"code_challenge\", Tuple2Second: pkceChallenge(verifier)},\n\t\t{Tuple2First: \"code_challenge_method\", Tuple2Second: \"S256\"},\n\t}\n\tif conn.Kind == \"oidc\" {\n\t\tframework = append(framework, Tuple2[string, string]{\n\t\t\tTuple2First: \"nonce\", Tuple2Second: nonce,\n\t\t})\n\t}\n\tauthorizeURL := buildAuthorizeURL(endpoints.AuthorizeURL, framework, nil)\n\tcookie := oauthCookieSeal(oauthState{\n\t\tSegment: segment, State: state, Nonce: nonce, Verifier: verifier, Started: now,\n\t}, sessionKey)\n\treturn authorizeURL, cookie, nil\n}\n\n// SsoLogoutURL is RP-initiated logout. It RE-DISCOVERS the issuer's endpoints, exactly as\n// login and callback do \226\128\148 a connection carries no cached endpoint state, so a rotated\n// end_session_endpoint is always honoured. A provider that advertises none answers \"\": the\n// caller decides the fallback rather than being handed a guess.\nfunc SsoLogoutURL(conn SsoConnection, postLogoutRedirectURI string) string {\n\tendpoints, err := resolveEndpoints(conn)\n\tif err != nil || endpoints.EndSessionURL == \"\" {\n\t\treturn \"\"\n\t}\n\treturn buildAuthorizeURL(endpoints.EndSessionURL, []Tuple2[string, string]{\n\t\t{Tuple2First: \"client_id\", Tuple2Second: conn.ClientID},\n\t\t{Tuple2First: \"post_logout_redirect_uri\", Tuple2Second: postLogoutRedirectURI},\n\t}, nil)\n}\n\n// \226\148\128\226\148\128 Handling the callback \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nfunc ssoHandleCallback(conn SsoConnection, segment, code, cookie, redirectURI string,\n\tsessionKeys []string, now int64, presentedState string) ssoOutcome {\n\tstate, opened := oauthCookieOpen(cookie, segment, sessionKeys)\n\tif !opened {\n\t\treturn ssoFail(\"invalid or missing login state\")\n\t}\n\t// The `state` check is UNCONDITIONAL (RFC 6749 \194\16710.12). It used to be skipped when the\n\t// parameter was absent, which made it optional to the attacker: start a login in your own\n\t// browser, capture your `code`, send the victim (who holds a legitimate cookie from a\n\t// forced `/login` navigation) to `/callback?code=<yours>` with no `state` \226\128\148 and the\n\t// victim is signed in as YOU (login CSRF / session planting). The sealed cookie and PKCE\n\t// bind the flow to the victim's browser, not to the victim's `code`; for an `oidc`\n\t// connection the id_token `nonce` still catches it, but a plain `oauth2` provider that\n\t// ignores PKCE has nothing else. Constant-time, so a byte-by-byte guess learns nothing.\n\tif presentedState == \"\" ||\n\t\tsubtle.ConstantTimeCompare([]byte(presentedState), []byte(state.State)) != 1 {\n\t\treturn ssoFail(\"state mismatch\")\n\t}\n\t// Single-use `state`, honestly scoped to this process: a second presentation \226\128\148 a user\n\t// double-clicking reload on the callback, or an attacker replaying a captured one \226\128\148\n\t// fails here instead of re-running the token exchange.\n\tif state.State != \"\" && !stateSpend(state.State, now) {\n\t\treturn ssoFail(\"state already used\")\n\t}\n\tendpoints, err := resolveEndpoints(conn)\n\tif err != nil {\n\t\treturn ssoFail(fixedReason(err))\n\t}\n\ttokens, err := postJSON(\"sso-token\", endpoints.TokenURL,\n\t\t[]Tuple2[string, string]{\n\t\t\t{Tuple2First: \"Authorization\", Tuple2Second: basicAuth(conn.ClientID, conn.ClientSecret)},\n\t\t\t{Tuple2First: \"Content-Type\", Tuple2Second: \"application/x-www-form-urlencoded\"},\n\t\t\t{Tuple2First: \"Accept\", Tuple2Second: \"application/json\"},\n\t\t},\n\t\tformEncode([]Tuple2[string, string]{\n\t\t\t{Tuple2First: \"grant_type\", Tuple2Second: \"authorization_code\"},\n\t\t\t{Tuple2First: \"code\", Tuple2Second: code},\n\t\t\t{Tuple2First: \"redirect_uri\", Tuple2Second: redirectURI},\n\t\t\t{Tuple2First: \"code_verifier\", Tuple2Second: state.Verifier},\n\t\t}))\n\tif err != nil {\n\t\treturn ssoFail(fixedReason(err))\n\t}\n\tswitch conn.Kind {\n\tcase \"oidc\":\n\t\treturn finishOidc(conn, segment, endpoints, tokens, state.Nonce, state.Started, now)\n\tcase \"oauth2\":\n\t\treturn finishOauth2(conn, segment, tokens)\n\tdefault:\n\t\treturn ssoFail(\"unknown connection kind\")\n\t}\n}\n\n// fixedReason keeps a leg's own words and nothing the provider wrote: every ssoError is\n// composed here, and anything else becomes a single generic reason.\nfunc fixedReason(err error) string {\n\tvar known ssoError\n\tif errors.As(err, &known) {\n\t\treturn known.reason\n\t}\n\treturn \"sso callback failed\"\n}\n\n// \226\148\128\226\148\128 The JWKS cache, and rotation refetch \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n// A bounded, TTL'd cache keyed by jwks_uri, so an ordinary login does NOT hit the IdP's JWKS\n// endpoint every time (a DoS-amplification vector). A key ROTATION \226\128\148 the token's kid is\n// absent from the cached set \226\128\148 triggers exactly ONE refetch, RATE-LIMITED per url, so an\n// attacker presenting random kids cannot force unbounded refetches. Bounded in size so it\n// cannot become a memory primitive either.\nconst (\n\tjwksCacheTTL      = 300\n\tjwksRefetchWindow = 60\n\tjwksCacheMax      = 64\n)\n\ntype jwksEntry struct {\n\tkeys        jwkSet\n\tfetchedAt   int64\n\tlastRefetch int64\n}\n\nvar (\n\tjwksCacheMutex sync.Mutex\n\tjwksCache      = map[string]jwksEntry{}\n)\n\n// JwksCacheReset is the test-only escape hatch, the same shape as the spent-state reset.\nfunc JwksCacheReset() { //nolint:unused // the emitted per-test reset calls it\n\tjwksCacheMutex.Lock()\n\tdefer jwksCacheMutex.Unlock()\n\tjwksCache = map[string]jwksEntry{}\n}\n\nfunc jwksHasKid(set jwkSet, kid string) bool {\n\tif kid == \"\" {\n\t\treturn len(set.Keys) > 0\n\t}\n\tfor _, key := range set.Keys {\n\t\tif key.Kid == kid {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\nfunc jwksFor(target, kid string, now int64) (jwkSet, error) {\n\tjwksCacheMutex.Lock()\n\tentry, cached := jwksCache[target]\n\tjwksCacheMutex.Unlock()\n\tfresh := cached && now-entry.fetchedAt < jwksCacheTTL\n\tif fresh && jwksHasKid(entry.keys, kid) {\n\t\treturn entry.keys, nil\n\t}\n\tif cached && fresh && now-entry.lastRefetch < jwksRefetchWindow {\n\t\t// An unknown kid inside the rate window: hand back the cached set. The verifier then\n\t\t// fails \"no key matches kid\" fail-closed, with NO extra fetch.\n\t\treturn entry.keys, nil\n\t}\n\tbody, err := fetch(\"sso-jwks\", \"GET\", target, nil, \"\")\n\tif err != nil {\n\t\treturn jwkSet{}, err\n\t}\n\tvar set jwkSet\n\tif json.Unmarshal([]byte(body), &set) != nil {\n\t\treturn jwkSet{}, ssoError{\"sso-jwks: response is not a JWKS\"}\n\t}\n\tjwksCacheMutex.Lock()\n\tif _, present := jwksCache[target]; !present && len(jwksCache) >= jwksCacheMax {\n\t\tjwksCache = map[string]jwksEntry{}\n\t}\n\tjwksCache[target] = jwksEntry{keys: set, fetchedAt: now, lastRefetch: now}\n\tjwksCacheMutex.Unlock()\n\treturn set, nil\n}\n\nfunc idTokenKid(idToken string) string {\n\tparts := strings.Split(idToken, \".\")\n\tif len(parts) == 0 {\n\t\treturn \"\"\n\t}\n\traw, ok := base64URLBytes(parts[0])\n\tif !ok {\n\t\treturn \"\"\n\t}\n\tvar header map[string]any\n\tif json.Unmarshal(raw, &header) != nil {\n\t\treturn \"\"\n\t}\n\tkid, _ := header[\"kid\"].(string)\n\treturn kid\n}\n\n// finishOidc is id_token-AUTHORITATIVE: the subject, the email and every claim come from the\n// signature-verified token, and the UserInfo endpoint is never called. That is why the\n// UserInfo-sub-must-equal-ID-token-sub cross-check has no counterpart here \226\128\148 there is no\n// second `sub` that could disagree. If a UserInfo fetch is ever added to this path, it MUST\n// assert that equality.\nfunc finishOidc(conn SsoConnection, segment string, endpoints SsoConnection,\n\ttokens map[string]any, nonce string, flowStart, now int64) ssoOutcome {\n\tidToken, _ := tokens[\"id_token\"].(string)\n\tif idToken == \"\" {\n\t\treturn ssoFail(\"no id_token in token response\")\n\t}\n\tif endpoints.JwksURL == \"\" {\n\t\treturn ssoFail(\"discovery has no jwks_uri\")\n\t}\n\t// The alg is pinned to discovery \226\136\169 what this implements. A verification failure is\n\t// TERMINAL: there is no downgrade path.\n\tpinned := []string{}\n\tfor _, advertised := range endpoints.SigningAlgs {\n\t\tif advertised == \"RS256\" || advertised == \"ES256\" {\n\t\t\tpinned = append(pinned, advertised)\n\t\t}\n\t}\n\tif len(pinned) == 0 {\n\t\treturn ssoFail(\"no supported id_token signing algorithm advertised\")\n\t}\n\tset, err := jwksFor(endpoints.JwksURL, idTokenKid(idToken), now)\n\tif err != nil {\n\t\treturn ssoFail(fixedReason(err))\n\t}\n\tif reason := verifyJws(idToken, set, pinned); reason != \"\" {\n\t\treturn ssoFail(\"id_token signature verification failed\")\n\t}\n\tparts := strings.Split(idToken, \".\")\n\tif len(parts) < 2 {\n\t\treturn ssoFail(\"malformed id_token\")\n\t}\n\trawClaims, ok := base64URLBytes(parts[1])\n\tif !ok {\n\t\treturn ssoFail(\"malformed id_token\")\n\t}\n\tvar claims map[string]any\n\tif json.Unmarshal(rawClaims, &claims) != nil {\n\t\treturn ssoFail(\"malformed id_token\")\n\t}\n\treason := validateOidcClaims(claims, oidcClaimRules{\n\t\tissuer: conn.Issuer, clientID: conn.ClientID, nonce: nonce,\n\t\tnow: now, leeway: 60, flowStart: flowStart,\n\t\tallowedTenants: conn.AllowedTenants,\n\t})\n\tif reason != \"\" {\n\t\treturn ssoFail(reason)\n\t}\n\tissuer, _ := claims[\"iss\"].(string)\n\tverified, _ := claims[\"email_verified\"].(bool)\n\treturn buildIdentity(conn, segment, issuer, ssoClaimText(claims[\"sub\"]),\n\t\tssoClaimText(claims[\"email\"]), verified, ssoClaimText(claims[\"name\"]),\n\t\tssoClaimText(claims[\"hd\"]), ssoClaimText(claims[\"tid\"]), claims)\n}\n\n// verifiedPrimaryEmail makes the documented SECOND call for providers that have one\n// (GitHub): a profile email may be public and unverified, and only the primary VERIFIED\n// address may be trusted. No such row answers \"\", so the caller falls back to the\n// unverified address rather than fabricating a verified one.\nfunc verifiedPrimaryEmail(conn SsoConnection, accessToken string) string {\n\tif conn.EmailsURL == \"\" {\n\t\treturn \"\"\n\t}\n\trows, err := getJSONArray(\"sso-emails\", conn.EmailsURL, []Tuple2[string, string]{\n\t\t{Tuple2First: \"Authorization\", Tuple2Second: \"Bearer \" + accessToken},\n\t\t{Tuple2First: \"Accept\", Tuple2Second: \"application/json\"},\n\t})\n\tif err != nil {\n\t\treturn \"\"\n\t}\n\tfor _, row := range rows {\n\t\tfields, isObject := row.(map[string]any)\n\t\tif !isObject {\n\t\t\tcontinue\n\t\t}\n\t\tprimary, _ := fields[\"primary\"].(bool)\n\t\tverified, _ := fields[\"verified\"].(bool)\n\t\tif primary && verified {\n\t\t\treturn ssoClaimText(fields[\"email\"])\n\t\t}\n\t}\n\treturn \"\"\n}\n\nfunc finishOauth2(conn SsoConnection, segment string, tokens map[string]any) ssoOutcome {\n\taccessToken, _ := tokens[\"access_token\"].(string)\n\tif accessToken == \"\" {\n\t\treturn ssoFail(\"no access_token in token response\")\n\t}\n\tinfo, err := getJSON(\"sso-userinfo\", conn.UserinfoURL, []Tuple2[string, string]{\n\t\t{Tuple2First: \"Authorization\", Tuple2Second: \"Bearer \" + accessToken},\n\t\t{Tuple2First: \"Accept\", Tuple2Second: \"application/json\"},\n\t})\n\tif err != nil {\n\t\treturn ssoFail(fixedReason(err))\n\t}\n\tsubject := ssoClaimText(info[conn.SubjectField])\n\tif subject == \"\" {\n\t\treturn ssoFail(\"no subject in userinfo\")\n\t}\n\t// Prefer the primary verified address from the second call; else the userinfo one,\n\t// verified only where the provider advertises a verified flag.\n\tprimary := verifiedPrimaryEmail(conn, accessToken)\n\temail := primary\n\tverified := primary != \"\"\n\tif email == \"\" && conn.EmailField != \"\" {\n\t\temail = ssoClaimText(info[conn.EmailField])\n\t\tif conn.EmailVerifiedField != \"\" {\n\t\t\tflag, _ := info[conn.EmailVerifiedField].(bool)\n\t\t\tverified = flag\n\t\t}\n\t}\n\tname := \"\"\n\tif conn.NameField != \"\" {\n\t\tname = ssoClaimText(info[conn.NameField])\n\t}\n\treturn buildIdentity(conn, segment, synthesizeIssuer(conn.UserinfoURL), subject,\n\t\temail, verified, name, \"\", \"\", info)\n}\n\n// ssoClaimText renders a scalar claim as the string an identity carries. A numeric subject\n// (GitHub's `id`) is a number in JSON and a string here, which is what makes one subject\n// type work for every provider. An absent or non-scalar claim is \"\", never a rendering of\n// whatever it was \226\128\148 `claimText` in jwt.go answers \"null\" and JSON-encodes an object, which\n// is right for a JWT claims dictionary and wrong for an identity field.\nfunc ssoClaimText(value any) string {\n\tswitch typed := value.(type) {\n\tcase string:\n\t\treturn typed\n\tcase bool:\n\t\treturn strconv.FormatBool(typed)\n\tcase json.Number:\n\t\treturn typed.String()\n\tcase float64:\n\t\tif typed == float64(int64(typed)) {\n\t\t\treturn strconv.FormatInt(int64(typed), 10)\n\t\t}\n\t\treturn strconv.FormatFloat(typed, 'f', -1, 64)\n\t}\n\treturn \"\"\n}\n\n// buildIdentity applies the runtime-enforced domain restrictions \226\128\148 BEFORE any app code sees\n// the identity \226\128\148 and then assembles it.\nfunc buildIdentity(conn SsoConnection, segment, issuer, subject, email string,\n\temailVerified bool, name, hostedDomain, tenant string, claims map[string]any) ssoOutcome {\n\tif strings.TrimSpace(subject) == \"\" {\n\t\treturn ssoFail(\"empty subject\")\n\t}\n\ttag, address := emailClaim(email, emailVerified)\n\tif !emailDomainAllowed(tag, address, conn.AllowedEmailDomains) {\n\t\treturn ssoFail(\"email domain not allowed\")\n\t}\n\tif !hostedDomainAllowed(hostedDomain, conn.AllowedHostedDomains) {\n\t\treturn ssoFail(\"hosted domain not allowed\")\n\t}\n\treturn ssoOutcome{OK: true, Identity: SsoIdentity{\n\t\tKey:      ssoSubjectKey(issuer, subject),\n\t\tIssuer:   issuer,\n\t\tProvider: segment,\n\t\tSubject:  subject,\n\t\tTenant:   tenant,\n\t\tEmailTag: tag,\n\t\tEmail:    address,\n\t\tName:     name,\n\t\tClaims:   claims,\n\t}}\n}\n");
  ("sso_route.go", "package teslrt\n\nimport (\n\t\"crypto/rand\"\n\t\"encoding/base64\"\n\t\"fmt\"\n\t\"net/http\"\n\t\"os\"\n\t\"strings\"\n\t\"time\"\n)\n\n// The two RUNTIME-OWNED routes an `sso \"<seg>\"` server clause mints: /auth/<seg>/login and\n// /auth/<seg>/callback. They are not handlers a program writes, and that is the point \226\128\148 the\n// OAuth2/OIDC dance is the runtime's, and what reaches app code is one already-verified\n// identity at `onIdentity`.\n//\n// The shapes here are the ones `dsl/web.rkt` produces, because a test written against one\n// backend has to pass on the other: a 303 with Location and Cache-Control: no-store, the\n// `__Host-` cookie attributes, and a FIXED failure page that never carries the provider's\n// text.\n\n// SsoRoute is one `sso` clause, as the emitted server hands it over. The connection and the\n// session key are THUNKS: both read the environment, which a test sets per case, and reading\n// them at boot would freeze the first value a process ever saw.\ntype SsoRoute struct {\n\tSegment      string\n\tConnection   func() SsoConnection\n\tOnIdentity   func(SsoIdentity) string\n\tSessionKey   func() Secret\n\tPublicOrigin string\n\tAfterLogin   string\n}\n\n// SetPublicOriginValue is the `publicOrigin` clause, applied at boot. It takes precedence\n// over TESL_PUBLIC_ORIGIN, exactly as the Racket parameter does \226\128\148 the clause is compile-time\n// validated and the env var is not.\nfunc SetPublicOriginValue(origin string) {\n\tpublicOriginMutex.Lock()\n\tdefer publicOriginMutex.Unlock()\n\tpublicOriginOverride = strings.TrimSpace(origin)\n}\n\nconst ssoOauthCookieName = \"__Host-oauth\"\n\n// The in-flight cookie lives ten minutes: long enough for a human to finish a login at the\n// provider, short enough that a captured one is not a standing key.\nconst ssoOauthCookieMaxAge = 600\n\n// ssoRandomToken is a fresh 256-bit value for a `state`, a `nonce` or a PKCE verifier.\nfunc ssoRandomToken() string {\n\traw := make([]byte, 32)\n\tif _, err := rand.Read(raw); err != nil {\n\t\tpanic(\"sso: the system random source is unavailable\")\n\t}\n\treturn base64.RawURLEncoding.EncodeToString(raw)\n}\n\n// A `__Host-` cookie line: Path=/ plus Secure plus HttpOnly plus SameSite=Lax. Lax rather\n// than Strict so the top-level callback navigation still carries the cookie. No Domain \226\128\148 the\n// `__Host-` prefix forbids one, which is the guarantee the prefix buys.\nfunc ssoCookieLine(name, value string, maxAge int) string {\n\tline := name + \"=\" + value + \"; Path=/; HttpOnly; Secure; SameSite=Lax\"\n\tif maxAge >= 0 {\n\t\tline += fmt.Sprintf(\"; Max-Age=%d\", maxAge)\n\t}\n\treturn line\n}\n\n// The redirect the Tesl surface cannot build: 303 plus Location plus no-store plus any\n// number of Set-Cookie lines.\nfunc ssoRedirect(writer http.ResponseWriter, location string, cookies []string) {\n\tfor _, cookie := range cookies {\n\t\twriter.Header().Add(\"Set-Cookie\", cookie)\n\t}\n\twriter.Header().Set(\"Location\", location)\n\twriter.Header().Set(\"Cache-Control\", \"no-store\")\n\twriter.Header().Set(\"Content-Type\", \"text/plain; charset=utf-8\")\n\twriter.WriteHeader(http.StatusSeeOther)\n\t_, _ = writer.Write(nil)\n}\n\n// A failed flow renders a FIXED page and clears the in-flight cookie \226\128\148 never a JSON error\n// body, never a fallthrough to another route, and never the provider's own text.\nfunc ssoFailure(writer http.ResponseWriter) {\n\twriter.Header().Add(\"Set-Cookie\", ssoCookieLine(ssoOauthCookieName, \"\", 0))\n\twriter.Header().Set(\"Cache-Control\", \"no-store\")\n\twriter.Header().Set(\"Content-Type\", \"text/html; charset=utf-8\")\n\twriter.WriteHeader(http.StatusUnauthorized)\n\t_, _ = writer.Write([]byte(\"<!doctype html><meta charset=\\\"utf-8\\\">\" +\n\t\t\"<title>Sign-in failed</title><p>Sign-in could not be completed. Please try again.\"))\n}\n\n// findSsoMatch resolves /auth/<seg>/login|callback to its route.\nfunc findSsoMatch(routes []SsoRoute, path string) (SsoRoute, string, bool) {\n\tsegments := strings.Split(strings.Trim(path, \"/\"), \"/\")\n\tif len(segments) != 3 || segments[0] != \"auth\" {\n\t\treturn SsoRoute{}, \"\", false\n\t}\n\tkind := segments[2]\n\tif kind != \"login\" && kind != \"callback\" {\n\t\treturn SsoRoute{}, \"\", false\n\t}\n\tfor _, route := range routes {\n\t\tif route.Segment == segments[1] {\n\t\t\treturn route, kind, true\n\t\t}\n\t}\n\treturn SsoRoute{}, \"\", false\n}\n\nfunc (route SsoRoute) redirectURI() string {\n\torigin := route.PublicOrigin\n\tif origin == \"\" {\n\t\torigin = PublicOrigin()\n\t}\n\treturn strings.TrimRight(origin, \"/\") + \"/auth/\" + route.Segment + \"/callback\"\n}\n\nfunc (route SsoRoute) sessionKeyText() string {\n\tif route.SessionKey == nil {\n\t\treturn \"\"\n\t}\n\treturn route.SessionKey().Value.Reveal()\n}\n\n// sessionKeyCandidates is the [current, previous] pair the in-flight cookie is opened under \226\128\148\n// the SAME helper `JWT.verify` uses, so a `sessionPreviousKey` rotation that keeps existing\n// sessions alive also keeps logins that were in flight when the key turned over. Opening\n// under the current key only (the earlier shape) failed every such login with \"invalid or\n// missing login state\": fail-closed, but an availability hole exactly during a rotation.\n// No configured key answers one empty candidate, which `oauthCookieOpen` skips \226\128\148 fail closed.\nfunc (route SsoRoute) sessionKeyCandidates() []string {\n\tif route.SessionKey == nil {\n\t\treturn []string{\"\"}\n\t}\n\treturn sessionKeys(route.SessionKey())\n}\n\n// handleSsoRequest runs one runtime-owned route. A TRAP inside it is a failed sign-in, not a\n// 500: the connection thunk reads the environment and `onIdentity` is app code, and neither\n// may turn a login into a stack trace on the client.\nfunc handleSsoRequest(route SsoRoute, kind string, writer http.ResponseWriter,\n\trequest *http.Request) {\n\tdefer func() {\n\t\tif recovered := recover(); recovered != nil {\n\t\t\tfmt.Fprintf(os.Stderr, \"tesl: sso %s failed: %v\\n\", kind, recovered)\n\t\t\tssoFailure(writer)\n\t\t}\n\t}()\n\tif kind == \"login\" {\n\t\thandleSsoLogin(route, writer)\n\t\treturn\n\t}\n\thandleSsoCallback(route, writer, request)\n}\n\nfunc handleSsoLogin(route SsoRoute, writer http.ResponseWriter) {\n\tauthorizeURL, cookie, err := ssoBeginLogin(route.Connection(), route.Segment,\n\t\troute.redirectURI(), route.sessionKeyText(),\n\t\tssoRandomToken(), ssoRandomToken(), ssoRandomToken(), time.Now().Unix())\n\tif err != nil {\n\t\tfmt.Fprintf(os.Stderr, \"tesl: sso login failed: %v\\n\", err)\n\t\tssoFailure(writer)\n\t\treturn\n\t}\n\tssoRedirect(writer, authorizeURL,\n\t\t[]string{ssoCookieLine(ssoOauthCookieName, cookie, ssoOauthCookieMaxAge)})\n}\n\nfunc handleSsoCallback(route SsoRoute, writer http.ResponseWriter, request *http.Request) {\n\tcode := request.URL.Query().Get(\"code\")\n\tpresentedState := request.URL.Query().Get(\"state\")\n\toauthCookie, err := request.Cookie(ssoOauthCookieName)\n\tif code == \"\" || err != nil || oauthCookie.Value == \"\" {\n\t\tfmt.Fprintf(os.Stderr,\n\t\t\t\"tesl: sso callback denied (%s): missing authorization code or %s cookie\\n\",\n\t\t\troute.Segment, ssoOauthCookieName)\n\t\tssoFailure(writer)\n\t\treturn\n\t}\n\toutcome := ssoHandleCallback(route.Connection(), route.Segment, code, oauthCookie.Value,\n\t\troute.redirectURI(), route.sessionKeyCandidates(), time.Now().Unix(), presentedState)\n\tif !outcome.OK {\n\t\t// Fail closed to the fixed client page, and log the reason server-side: a silently\n\t\t// swallowed callback failure is undebuggable in production.\n\t\tfmt.Fprintf(os.Stderr, \"tesl: sso callback rejected (%s): %s\\n\",\n\t\t\troute.Segment, outcome.Reason)\n\t\tssoFailure(writer)\n\t\treturn\n\t}\n\tsubject := route.OnIdentity(outcome.Identity)\n\ttoken := JwtSign(DictInsert(DictEmpty[string, string](), \"sub\", subject, stringKeyLess),\n\t\troute.SessionKey())\n\t// The session cookie REPLACES any pre-existing one (session fixation). The in-flight\n\t// cookie is spent \226\128\148 its sealed verifier and nonce have no further use \226\128\148 so it is cleared\n\t// here exactly as the failure path clears it.\n\tssoRedirect(writer, route.AfterLogin, []string{\n\t\tssoCookieLine(sessionCookieName, token.Value, sessionPolicySeconds()),\n\t\tssoCookieLine(ssoOauthCookieName, \"\", 0),\n\t})\n}\n");
  ("string.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"strings\"\n\t\"unicode/utf8\"\n)\n\n// Tesl's String is Go's string, but Tesl's string INDICES AND LENGTHS ARE CODE\n// POINTS, because the Racket backend's `string-length`, `substring`, and match\n// positions all count Racket chars. Every function here that exposes a length or an\n// index therefore converts, and none of them may use len() or a byte offset as a\n// Tesl-visible number.\n//\n// Two deliberate, documented differences from the Racket backend, both cases where\n// Go's behavior is the defensible one (see roadmap/next/migrate_to_golang.md):\n//\n//   - StringToInt accepts an optional sign followed by decimal digits, and nothing\n//     else. Racket's `string->number` also accepts reader syntax \226\128\148 \"#x1A\" is 26,\n//     \"1/1\" is the exact integer 1 \226\128\148 which is an implementation leak rather than a\n//     language surface.\n//   - StringTrim trims Unicode whitespace (Go's unicode.IsSpace), where Racket's\n//     default `\\s` is ASCII-only. Case mapping is Go's per-rune simple mapping, so\n//     \"\195\159\" uppercases to \"\195\159\" rather than Racket's full-mapping \"SS\".\nfunc StringLength(s string) Int {\n\treturn FromInt64(int64(utf8.RuneCountInString(s)))\n}\n\nfunc StringIsEmpty(s string) bool {\n\treturn s == \"\"\n}\n\nfunc StringStartsWith(s, prefix string) bool {\n\treturn strings.HasPrefix(s, prefix)\n}\n\nfunc StringEndsWith(s, suffix string) bool {\n\treturn strings.HasSuffix(s, suffix)\n}\n\nfunc StringContains(s, sub string) bool {\n\treturn strings.Contains(s, sub)\n}\n\nfunc StringConcat(left, right string) string {\n\treturn left + right\n}\n\n// StringReplace replaces every occurrence, matching Racket's string-replace.\nfunc StringReplace(s, from, to string) string {\n\treturn strings.ReplaceAll(s, from, to)\n}\n\n// StringSlice is a zero-based, code-point-indexed slice with both bounds clamped,\n// so it is total: no index can panic and no bound can be inverted.\nfunc StringSlice(s string, start, end Int) string {\n\trunes := []rune(s)\n\tlength := int64(len(runes))\n\tlo := clampIndex(start, length)\n\thi := clampIndex(end, length)\n\tif hi < lo {\n\t\thi = lo\n\t}\n\treturn string(runes[lo:hi])\n}\n\n// clampIndex pins an arbitrary-precision index into [0, length]. An Int outside\n// int64 range clamps by sign rather than truncating, which a naive conversion\n// would get exactly backwards.\nfunc clampIndex(index Int, length int64) int64 {\n\tvalue, ok := index.Int64()\n\tif !ok {\n\t\tif index.Sign() < 0 {\n\t\t\treturn 0\n\t\t}\n\t\treturn length\n\t}\n\tif value < 0 {\n\t\treturn 0\n\t}\n\tif value > length {\n\t\treturn length\n\t}\n\treturn value\n}\n\nfunc StringToUpper(s string) string {\n\treturn strings.ToUpper(s)\n}\n\nfunc StringToLower(s string) string {\n\treturn strings.ToLower(s)\n}\n\nfunc StringTrim(s string) string {\n\treturn strings.TrimSpace(s)\n}\n\nfunc StringFromInt(value Int) string {\n\treturn value.String()\n}\n\n// StringToInt parses an optional sign followed by decimal digits; anything else is\n// Nothing. Arbitrary precision is preserved.\nfunc StringToInt(s string) Maybe[Int] {\n\tvalue, err := ParseDecimal(s)\n\tif err != nil {\n\t\treturn Nothing[Int]()\n\t}\n\treturn Something(value)\n}\n\n// StringIndexOf reports the first occurrence as a CODE POINT index, not a byte\n// offset \226\128\148 the two differ for any string with a multi-byte rune before the match.\nfunc StringIndexOf(s, sub string) Maybe[Int] {\n\toffset := strings.Index(s, sub)\n\tif offset < 0 {\n\t\treturn Nothing[Int]()\n\t}\n\treturn Something(FromInt64(int64(utf8.RuneCountInString(s[:offset]))))\n}\n\nfunc StringDropPrefix(s, prefix string) string {\n\treturn strings.TrimPrefix(s, prefix)\n}\n\nfunc StringDropSuffix(s, suffix string) string {\n\treturn strings.TrimSuffix(s, suffix)\n}\n\n// StringPadLeft pads to a code-point width using the first rune of pad. A string\n// already at or over the width is returned unchanged, never truncated.\nfunc StringPadLeft(s string, width Int, pad string) string {\n\tfill, count := padding(s, width, pad)\n\tif count <= 0 {\n\t\treturn s\n\t}\n\treturn strings.Repeat(fill, count) + s\n}\n\nfunc StringPadRight(s string, width Int, pad string) string {\n\tfill, count := padding(s, width, pad)\n\tif count <= 0 {\n\t\treturn s\n\t}\n\treturn s + strings.Repeat(fill, count)\n}\n\nfunc padding(s string, width Int, pad string) (string, int) {\n\tfill, size := utf8.DecodeRuneInString(pad)\n\tif size == 0 {\n\t\treturn \"\", 0\n\t}\n\ttarget, ok := width.Int64()\n\tif !ok {\n\t\t// A width beyond int64 cannot be materialised; treat it as no padding\n\t\t// rather than attempting an allocation that would kill the process.\n\t\treturn string(fill), 0\n\t}\n\tcurrent := int64(utf8.RuneCountInString(s))\n\tif target <= current {\n\t\treturn string(fill), 0\n\t}\n\treturn string(fill), int(target - current)\n}\n\n// maxRepeatBytes bounds the byte length of a String.repeat result. A denial-of-service\n// bound, not a language limit: strings.Repeat only panics on int OVERFLOW, so a\n// request-controlled count of, say, 2^40 would otherwise attempt a terabyte allocation and\n// end the process with an uncatchable out-of-memory fatal rather than a recoverable trap.\nconst maxRepeatBytes = 64 << 20\n\n// StringRepeat is total over the counts a program can mean: negative or beyond-int64 counts\n// yield the empty string (mirroring `padding` above). A count whose result would exceed\n// maxRepeatBytes is different \226\128\148 it is not a value the program could have wanted, and answering\n// \"\" would be a silent wrong result \226\128\148 so it TRAPS, which `callHandler` turns into a sanitized\n// 500 rather than the uncatchable out-of-memory the allocation would have been. The bound is\n// decided from len(s) and the count BEFORE strings.Repeat runs; the division form cannot\n// overflow.\nfunc StringRepeat(s string, times Int) string {\n\tcount, ok := times.Int64()\n\tif !ok || count <= 0 || s == \"\" {\n\t\treturn \"\"\n\t}\n\tif count > int64(maxRepeatBytes)/int64(len(s)) {\n\t\tpanic(fmt.Sprintf(\"String.repeat: the result would be %d \195\151 %d bytes, over the %d-byte bound\",\n\t\t\tcount, len(s), maxRepeatBytes))\n\t}\n\treturn strings.Repeat(s, int(count))\n}\n\n// StringReverse reverses by code point, matching Racket's string->list round trip.\nfunc StringReverse(s string) string {\n\trunes := []rune(s)\n\tfor left, right := 0, len(runes)-1; left < right; left, right = left+1, right-1 {\n\t\trunes[left], runes[right] = runes[right], runes[left]\n\t}\n\treturn string(runes)\n}\n\n// StringRequireNonEmpty is Tesl's `String.requireNonEmpty` check: the proof erases,\n// the rejection does not.\nfunc StringRequireNonEmpty(s string) Check[string] {\n\tif s == \"\" {\n\t\treturn Reject[string](400, \"expected a non-empty string\")\n\t}\n\treturn Accept(s)\n}\n");
  ("table.go", "package teslrt\n\nimport (\n\t\"bytes\"\n\t\"fmt\"\n\t\"runtime\"\n\t\"sort\"\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n\t\"sync/atomic\"\n)\n\n// An in-memory table, the `backend: Memory` store.\n//\n// Rows are held as VALUES, and every read returns a copy of the slice header's contents\n// rather than the table's own storage \226\128\148 the same \"only writers allocate, readers may not\n// alias the store\" rule list.go states, applied here because a table is mutable and long\n// lived where a Tesl list is neither.\n//\n// The mutex is not decoration: an HTTP server serves each request on its own goroutine, so\n// two handlers touching the same table race by construction. The gates run `go test -race`\n// on emitted code, which is what would catch a missing lock.\n//\n// THE LOCK MODEL. No user code ever runs under the lock. A `where` operand or a `set` value is\n// an arbitrary Tesl expression, and it may itself query THIS table (`set price = selectCount\n// \226\128\166`); `sync.RWMutex` is not reentrant, so a predicate evaluated under the read lock wedged the\n// moment a writer queued behind it, and an `apply` evaluated under the write lock wedged at\n// once. So:\n//\n//   - `rows` is IMMUTABLE once published: a writer never assigns into an element of the\n//     published slice and never shortens it in place \226\128\148 it appends (writing only past every\n//     published length) or installs a fresh slice. A reader therefore takes the slice header\n//     under the read lock, releases it, and evaluates on that snapshot with no lock held.\n//   - `version` counts every publication. A writer evaluates `match`/`apply` on a snapshot with\n//     no lock held, then takes the write lock and installs the result ONLY if the version is\n//     still the one it read; otherwise another writer got in between and the whole operation is\n//     recomputed against the new rows, a bounded number of times. The unique-index check stays\n//     under the write lock, where the rows it checks against cannot move.\n//\n// The optimistic retry re-evaluates `match`/`apply` on the new rows, so an operand with a side\n// effect (a clock read, an enqueue) may run more than once \226\128\148 only under contention on one\n// table, which is also when PostgreSQL would have re-evaluated a serialisation failure.\ntype Table[Row any] struct {\n\tmutex   sync.RWMutex\n\trows    []Row\n\tversion uint64\n}\n\nfunc NewTable[Row any]() *Table[Row] {\n\treturn &Table[Row]{}\n}\n\n// snapshot is what a read starts from: the published rows and the version they belong to. The\n// Memory transaction gate prevents an outside reader from taking this snapshot while a\n// transaction has published uncommitted rows. The transaction owner skips the non-reentrant\n// gate and reads its own writes, as it does on PostgreSQL.\nfunc (table *Table[Row]) snapshot() ([]Row, uint64) {\n\tdefer releaseMemoryRead(acquireMemoryRead())\n\ttable.mutex.RLock()\n\tdefer table.mutex.RUnlock()\n\treturn table.rows, table.version\n}\n\n// publishLocked installs `next` as the table's rows. The caller holds the write lock and\n// `next` either IS the current slice grown by append or a fresh slice \226\128\148 never the current\n// slice with an element reassigned, which would race a reader walking its snapshot.\n//\n// The rows being replaced are recorded for rollback first when a Memory `transaction { }` is\n// open on this goroutine (see database.go), so the FIRST write a transaction makes to a table\n// is what a trap restores it to.\nfunc (table *Table[Row]) publishLocked(next []Row) {\n\tif memoryTransactionsOpen.Load() > 0 {\n\t\tif transaction := currentMemoryTransaction(); transaction != nil {\n\t\t\trecordForRollback(transaction, table, table.rows)\n\t\t}\n\t}\n\ttable.rows = next\n\ttable.version++\n}\n\n// restoreRows is the rollback: the rows a transaction first saw, installed as a FRESH slice.\n// A copy rather than the saved header, because appends made during the transaction may have\n// written into the saved header's spare capacity and a reader may hold a snapshot that covers\n// those slots \226\128\148 reusing the array would let a later append overwrite what that reader sees.\nfunc (table *Table[Row]) restoreRows(saved []Row) {\n\ttable.mutex.Lock()\n\tdefer table.mutex.Unlock()\n\ttable.rows = append(make([]Row, 0, len(saved)), saved...)\n\ttable.version++\n}\n\n// How many times a writer recomputes against rows another writer changed under it before\n// giving up. Each retry needs a DIFFERENT writer to have published in the window between the\n// snapshot and the write lock; exhausting it means the table is being rewritten continuously.\nconst tableWriteRetries = 1000\n\nfunc tableWriteContended(operation string) string {\n\treturn \"database: \" + operation + \" on the Memory store gave up after \" +\n\t\tstrconv.Itoa(tableWriteRetries) + \" concurrent modifications of the table; \" +\n\t\t\"another writer is changing it continuously\"\n}\n\n// TableInsert stores a row, rejecting one whose primary key is already present \226\128\148\n// `conflicts(existing, inserted)` compares the two keys, since their type is known only\n// to the emitter. The Racket memory backend keys its store BY the primary key and raises\n// on a duplicate, so this is parity rather than an extra: a table that silently accepted\n// two rows with one key would answer `selectOne` differently on the two backends.\nfunc TableInsert[Row any](table *Table[Row], entity string, row Row, conflicts func(Row, Row) bool,\n\tunique ...UniqueIndex[Row]) Row {\n\tdefer releaseMemoryWrite(acquireMemoryWrite())\n\ttable.mutex.Lock()\n\tdefer table.mutex.Unlock()\n\tcheckUniqueIn(table.rows, entity, row, unique, -1)\n\ttable.publishLocked(insertInto(table.rows, entity, row, conflicts))\n\treturn row\n}\n\n// A declared `unique index [a, b]`. It is an INVARIANT rather than a performance hint, so the\n// in-memory store enforces it: the whole point of that store is that a test fails the way\n// production fails, and skipping the check would let `tesl test` pass on data PostgreSQL\n// rejects. On a Postgres-backed entity the SERVER enforces it \226\128\148 the bootstrap creates the\n// index \226\128\148 so the check here is the memory path's alone.\ntype UniqueIndex[Row any] struct {\n\t// Entity as the declaration names it, which is what the refusal names.\n\tEntity string\n\t// Columns as the declaration lists them, which is what the refusal names.\n\tColumns []string\n\t// Constrained is false when the row holds a NULL in an indexed column: two NULLs are not\n\t// equal, so such a row is unconstrained. PostgreSQL's rule, and Racket's.\n\tConstrained func(Row) bool\n\tSame        func(Row, Row) bool\n\t// Describe renders the indexed values for the refusal.\n\tDescribe func(Row) string\n}\n\n// UniqueIndexOf is what a declaration emits. A constructor rather than a struct literal for\n// the reason `NewDatabase` is one: gofmt ALIGNS the keys of a multi-line composite literal and\n// breaks the alignment run at a nested multi-line value, a rule the emitter would have to\n// reproduce exactly at every shape. A call with one argument per line is stable at every size.\nfunc UniqueIndexOf[Row any](entity string, columns []string, constrained func(Row) bool,\n\tsame func(Row, Row) bool, describe func(Row) string) UniqueIndex[Row] {\n\treturn UniqueIndex[Row]{\n\t\tEntity:      entity,\n\t\tColumns:     columns,\n\t\tConstrained: constrained,\n\t\tSame:        same,\n\t\tDescribe:    describe,\n\t}\n}\n\n// checkUniqueIn checks `row` against `rows`, which are the rows the write is about to publish\n// against \226\128\148 the caller holds the write lock, so they cannot move. `skip` is the position of the\n// row being REPLACED, so an update never conflicts with itself; -1 skips nothing.\nfunc checkUniqueIn[Row any](rows []Row, entity string, row Row, indexes []UniqueIndex[Row],\n\tskip int) {\n\tfor _, index := range indexes {\n\t\tif index.Constrained != nil && !index.Constrained(row) {\n\t\t\tcontinue\n\t\t}\n\t\tfor position, existing := range rows {\n\t\t\tif position == skip || !index.Same(existing, row) {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tpanic(\"entity \" + entity + \" already contains a row with (\" +\n\t\t\t\tstrings.Join(index.Columns, \" \") + \") = \" + index.Describe(row) +\n\t\t\t\t\"; the declared unique index on (\" + strings.Join(index.Columns, \", \") +\n\t\t\t\t\") forbids duplicates\")\n\t\t}\n\t}\n}\n\n// TableInsertMany inserts in order, and a row conflicting with an EARLIER row of the same\n// batch is rejected just as it would be if the two were inserted separately \226\128\148 Racket's\n// insert-many! is a loop over insert-one!.\nfunc TableInsertMany[Row any](table *Table[Row], entity string, rows []Row,\n\tconflicts func(Row, Row) bool, unique ...UniqueIndex[Row]) struct{} {\n\tdefer releaseMemoryWrite(acquireMemoryWrite())\n\ttable.mutex.Lock()\n\tdefer table.mutex.Unlock()\n\tfor _, row := range rows {\n\t\t// Published one at a time, so the rows before a conflicting one STAY when it traps \226\128\148\n\t\t// which is what one insert at a time would have left behind.\n\t\tcheckUniqueIn(table.rows, entity, row, unique, -1)\n\t\ttable.publishLocked(insertInto(table.rows, entity, row, conflicts))\n\t}\n\treturn struct{}{}\n}\n\n// insertInto is `rows` with `row` appended, once no existing row shares its primary key. The\n// caller holds the write lock. Appending is safe under the immutable-when-published rule\n// because it writes only PAST every length a reader may hold.\nfunc insertInto[Row any](rows []Row, entity string, row Row, conflicts func(Row, Row) bool) []Row {\n\tfor _, existing := range rows {\n\t\tif conflicts(existing, row) {\n\t\t\tpanic(fmt.Sprintf(\"insert: entity %s already contains a row with that primary key\", entity))\n\t\t}\n\t}\n\treturn append(rows, row)\n}\n\n// TableSelectOne returns the FIRST row matching, in insertion order. Tesl's `selectOne`\n// yields `Maybe`, so \"no row\" is a value rather than an error.\nfunc TableSelectOne[Row any](table *Table[Row], match func(Row) bool) Maybe[Row] {\n\trows, _ := table.snapshot()\n\tfor _, row := range rows {\n\t\tif match(row) {\n\t\t\treturn Something(row)\n\t\t}\n\t}\n\treturn Nothing[Row]()\n}\n\nfunc TableSelect[Row any](table *Table[Row], match func(Row) bool) []Row {\n\trows, _ := table.snapshot()\n\tout := make([]Row, 0, len(rows))\n\tfor _, row := range rows {\n\t\tif match(row) {\n\t\t\tout = append(out, row)\n\t\t}\n\t}\n\treturn out\n}\n\n// An aggregate walks the rows in place: it needs no copy of them, and on the Memory store\n// it is the whole implementation. On a SQL backend an aggregate must instead become a\n// `SELECT COUNT/SUM/MAX(...) ... WHERE ...` \226\128\148 the work belongs in the database, and the\n// query structure to build it from is the same recovered seed. Nothing here should be\n// carried over to that path.\nfunc TableCount[Row any](table *Table[Row], match func(Row) bool) Int {\n\trows, _ := table.snapshot()\n\tmatched := 0\n\tfor _, row := range rows {\n\t\tif match(row) {\n\t\t\tmatched++\n\t\t}\n\t}\n\treturn FromInt64(int64(matched))\n}\n\n// TableSelectRange is `limit` / `offset` without an `order` clause: rows come back in\n// insertion order, which is the order the un-ordered Racket path yields as well. A\n// negative `limit` means \"no limit\".\nfunc TableSelectRange[Row any](table *Table[Row], match func(Row) bool, offset, limit int) []Row {\n\treturn sliceRange(TableSelect(table, match), offset, limit)\n}\n\n// TableSelectSorted is `order by`, plus any `limit`/`offset` applied after the sort.\n// `less` reports strictly-before, and the sort is STABLE, so rows comparing equal keep\n// their insertion order.\nfunc TableSelectSorted[Row any](table *Table[Row], match func(Row) bool, less func(Row, Row) bool, offset, limit int) []Row {\n\trows := TableSelect(table, match)\n\tsort.SliceStable(rows, func(left, right int) bool { return less(rows[left], rows[right]) })\n\treturn sliceRange(rows, offset, limit)\n}\n\n// TableSelectOneSorted is `selectOne \226\128\166 order \226\128\166`: the first row after sorting.\nfunc TableSelectOneSorted[Row any](table *Table[Row], match func(Row) bool, less func(Row, Row) bool) Maybe[Row] {\n\trows := TableSelectSorted(table, match, less, 0, 1)\n\tif len(rows) == 0 {\n\t\treturn Nothing[Row]()\n\t}\n\treturn Something(rows[0])\n}\n\n// TableFold is the scalar aggregate (`selectSum`): the matching rows' projections\n// combined left to right from `zero`, so an empty table yields `zero` \226\128\148 the same answer\n// SQL's SUM-over-no-rows gives once Tesl has typed it as the column type.\nfunc TableFold[Row any, Value any](table *Table[Row], match func(Row) bool, project func(Row) Value, combine func(Value, Value) Value, zero Value) Value {\n\trows, _ := table.snapshot()\n\ttotal := zero\n\tfor _, row := range rows {\n\t\tif match(row) {\n\t\t\ttotal = combine(total, project(row))\n\t\t}\n\t}\n\treturn total\n}\n\n// TableSumMoney is `selectSum` over a MONEY column. It is not a `TableFold` because the fold's\n// zero would need a currency before any row has been seen; instead the currency is adopted from\n// the first matching row and every later row is checked against it, in ONE pass over one\n// snapshot of the rows \226\128\148 nothing is materialised.\n//\n// The two refusals are Racket's (`money-sum-result`), and both are about answering honestly\n// rather than plausibly: a total over no rows has no currency to carry (`$0.00` would be a\n// guess), and a total across currencies needs a rate, which is dated data a SUM may not invent.\nfunc TableSumMoney[Row any](table *Table[Row], match func(Row) bool, project func(Row) Money,\n\tentity, field string) Money {\n\trows, _ := table.snapshot()\n\ttotal := FromInt64(0)\n\tvar currency Currency\n\tdistinct := map[string]struct{}{}\n\tfor _, row := range rows {\n\t\tif !match(row) {\n\t\t\tcontinue\n\t\t}\n\t\tamount := project(row)\n\t\tif len(distinct) == 0 {\n\t\t\tcurrency = amount.Currency\n\t\t}\n\t\tdistinct[amount.Currency.Code] = struct{}{}\n\t\ttotal = Add(total, amount.MinorUnits)\n\t}\n\treturn MoneySumResult(entity, field, total, currency, len(distinct))\n}\n\n// MoneySumResult is the rule both stores answer a Money sum by, so the two cannot phrase a\n// refusal differently: the counted currencies decide, and the wording is Racket's\n// (`money-sum-result`) down to the count it names.\nfunc MoneySumResult(entity, field string, total Int, currency Currency, distinct int) Money {\n\tif distinct == 0 {\n\t\tpanic(\"field \" + field + \" on entity \" + entity +\n\t\t\t\": cannot sum Money over an empty row set (no currency for the zero total);\" +\n\t\t\t\" guard with a count first\")\n\t}\n\tif distinct > 1 {\n\t\tpanic(\"field \" + field + \" on entity \" + entity +\n\t\t\t\": cannot sum Money across mixed currencies (found \" + FromInt64(int64(distinct)).String() +\n\t\t\t\"); filter by currency first\")\n\t}\n\treturn Money{MinorUnits: total, Currency: currency}\n}\n\n// TableExtreme is `selectMax` / `selectMin`: the projection of the matching rows that no\n// other beats, where `better(candidate, best)` reports that the candidate wins.\n//\n// The answer is a `Maybe`: with no matching row there is no value of the column's type to\n// return, and unlike `selectSum` there is no identity to fall back on. Racket's aggregates\n// answer `Nothing` in the same case.\nfunc TableExtreme[Row any, Value any](table *Table[Row], match func(Row) bool, project func(Row) Value, better func(Value, Value) bool) Maybe[Value] {\n\trows, _ := table.snapshot()\n\tvar best Value\n\tfound := false\n\tfor _, row := range rows {\n\t\tif !match(row) {\n\t\t\tcontinue\n\t\t}\n\t\tcandidate := project(row)\n\t\tif !found || better(candidate, best) {\n\t\t\tbest = candidate\n\t\t\tfound = true\n\t\t}\n\t}\n\tif !found {\n\t\treturn Nothing[Value]()\n\t}\n\treturn Something(best)\n}\n\n// SqlLike is the `like` / `ilike` predicate: `%` matches any run of characters and `_`\n// exactly one, `\\` makes the next character literal (`\\%`, `\\_`, `\\\\` \226\128\148 PostgreSQL's default\n// ESCAPE), and the whole value must match. It is a direct matcher rather than a translation\n// to a regular expression, so a pattern can never inject one.\n//\n// A pattern ending in a lone `\\` is refused with PostgreSQL's own message: the server rejects\n// the statement, so the Memory store must not quietly match something instead.\n//\n// `ilike` folds through Go's Unicode case mapping, where PostgreSQL folds by the column's\n// COLLATION \226\128\148 under the `C` locale that is ASCII only \226\128\148 so non-ASCII case-insensitive matches\n// may differ between the two stores. That is the server's rule, not something reproducible here.\nfunc SqlLike(value, pattern string, foldCase bool) bool {\n\tif foldCase {\n\t\tvalue = strings.ToLower(value)\n\t\tpattern = strings.ToLower(pattern)\n\t}\n\ttext := []rune(value)\n\tglob := likeTokens(pattern)\n\t// Standard backtracking match: `star` remembers where the last `%` was, so a failure\n\t// after it resumes by letting that `%` consume one more character.\n\ttextAt, globAt, star, retry := 0, 0, -1, 0\n\tfor textAt < len(text) {\n\t\tswitch {\n\t\tcase globAt < len(glob) && glob[globAt].matches(text[textAt]):\n\t\t\ttextAt++\n\t\t\tglobAt++\n\t\tcase globAt < len(glob) && glob[globAt].kind == likeAnyRun:\n\t\t\tstar = globAt\n\t\t\tglobAt++\n\t\t\tretry = textAt\n\t\tcase star >= 0:\n\t\t\tglobAt = star + 1\n\t\t\tretry++\n\t\t\ttextAt = retry\n\t\tdefault:\n\t\t\treturn false\n\t\t}\n\t}\n\tfor globAt < len(glob) && glob[globAt].kind == likeAnyRun {\n\t\tglobAt++\n\t}\n\treturn globAt == len(glob)\n}\n\ntype likeTokenKind int\n\nconst (\n\tlikeLiteral likeTokenKind = iota\n\tlikeAnyOne\n\tlikeAnyRun\n)\n\n// One element of a parsed LIKE pattern: a literal character, `_`, or `%`.\ntype likeToken struct {\n\tkind    likeTokenKind\n\tliteral rune\n}\n\nfunc (token likeToken) matches(character rune) bool {\n\tswitch token.kind {\n\tcase likeAnyOne:\n\t\treturn true\n\tcase likeLiteral:\n\t\treturn token.literal == character\n\tcase likeAnyRun:\n\t\t// A run never matches a single character here; the glob walker consumes it.\n\t\treturn false\n\tdefault:\n\t\treturn false\n\t}\n}\n\n// likeTokens parses a pattern once, so the escape is resolved BEFORE matching rather than\n// re-examined at every backtrack.\nfunc likeTokens(pattern string) []likeToken {\n\trunes := []rune(pattern)\n\ttokens := make([]likeToken, 0, len(runes))\n\tfor at := 0; at < len(runes); at++ {\n\t\tswitch runes[at] {\n\t\tcase '\\\\':\n\t\t\tif at+1 >= len(runes) {\n\t\t\t\tpanic(\"database: LIKE pattern must not end with escape character\")\n\t\t\t}\n\t\t\tat++\n\t\t\ttokens = append(tokens, likeToken{kind: likeLiteral, literal: runes[at]})\n\t\tcase '%':\n\t\t\ttokens = append(tokens, likeToken{kind: likeAnyRun})\n\t\tcase '_':\n\t\t\ttokens = append(tokens, likeToken{kind: likeAnyOne})\n\t\tdefault:\n\t\t\ttokens = append(tokens, likeToken{kind: likeLiteral, literal: runes[at]})\n\t\t}\n\t}\n\treturn tokens\n}\n\nfunc sliceRange[Row any](rows []Row, offset, limit int) []Row {\n\tif offset >= len(rows) {\n\t\treturn []Row{}\n\t}\n\trows = rows[offset:]\n\tif limit >= 0 && limit < len(rows) {\n\t\trows = rows[:limit]\n\t}\n\treturn rows\n}\n\n// TableDelete removes every matching row. `delete` is a statement in Tesl, so the count\n// goes nowhere; TableDeleteCount is the form that reports it.\nfunc TableDelete[Row any](table *Table[Row], match func(Row) bool) struct{} {\n\tTableDeleteCount(table, match)\n\treturn struct{}{}\n}\n\nfunc TableDeleteCount[Row any](table *Table[Row], match func(Row) bool) Int {\n\tfor range tableWriteRetries {\n\t\trows, version := table.snapshot()\n\t\t// The predicate runs on the snapshot with no lock held: it may query this table.\n\t\tkept := make([]Row, 0, len(rows))\n\t\tremoved := 0\n\t\tfor _, row := range rows {\n\t\t\tif match(row) {\n\t\t\t\tremoved++\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tkept = append(kept, row)\n\t\t}\n\t\tif table.publishIfUnchanged(version, kept) {\n\t\t\treturn FromInt64(int64(removed))\n\t\t}\n\t}\n\tpanic(tableWriteContended(\"delete\"))\n}\n\n// publishIfUnchanged installs `next` when the table is still at `version` \226\128\148 the rows the caller\n// computed `next` from \226\128\148 and reports whether it did. A false answer means another writer\n// published in between and the caller recomputes.\nfunc (table *Table[Row]) publishIfUnchanged(version uint64, next []Row) bool {\n\tdefer releaseMemoryWrite(acquireMemoryWrite())\n\ttable.mutex.Lock()\n\tdefer table.mutex.Unlock()\n\tif table.version != version {\n\t\treturn false\n\t}\n\ttable.publishLocked(next)\n\treturn true\n}\n\n// A replacement an update computed on its snapshot: the row at `position` becomes `row`.\ntype rowReplacement[Row any] struct {\n\tposition int\n\trow      Row\n}\n\n// replaceIfUnchanged installs the replacements when the table is still at `version`, checking\n// each replaced row against the declared unique indexes under the write lock \226\128\148 which is where\n// the rows it is checked against cannot move \226\128\148 and building a FRESH slice, since assigning\n// into the published one would race a reader's snapshot. Earlier replacements are visible to\n// later checks, so two rows of one update swapping unique values are judged as the sequence\n// they are on the server.\nfunc (table *Table[Row]) replaceIfUnchanged(version uint64, replacements []rowReplacement[Row],\n\tunique []UniqueIndex[Row]) bool {\n\tdefer releaseMemoryWrite(acquireMemoryWrite())\n\ttable.mutex.Lock()\n\tdefer table.mutex.Unlock()\n\tif table.version != version {\n\t\treturn false\n\t}\n\tnext := append(make([]Row, 0, len(table.rows)), table.rows...)\n\tfor _, replacement := range replacements {\n\t\tcheckUniqueIn(next, uniqueEntity(unique), replacement.row, unique, replacement.position)\n\t\tnext[replacement.position] = replacement.row\n\t}\n\ttable.publishLocked(next)\n\treturn true\n}\n\n// TableUpdate replaces every matching row with the result of `apply`. Like `delete`, a\n// plain `update` is a statement, so nothing is reported back.\nfunc TableUpdate[Row any](table *Table[Row], match func(Row) bool, apply func(Row) Row,\n\tunique ...UniqueIndex[Row]) struct{} {\n\tfor range tableWriteRetries {\n\t\trows, version := table.snapshot()\n\t\t// `match` and `apply` run on the snapshot with no lock held: a `set` value may query\n\t\t// this very table, which under the write lock was a deadlock.\n\t\treplacements := []rowReplacement[Row]{}\n\t\tfor index, row := range rows {\n\t\t\tif match(row) {\n\t\t\t\treplacements = append(replacements, rowReplacement[Row]{position: index, row: apply(row)})\n\t\t\t}\n\t\t}\n\t\tif table.replaceIfUnchanged(version, replacements, unique) {\n\t\t\treturn struct{}{}\n\t\t}\n\t}\n\tpanic(tableWriteContended(\"update\"))\n}\n\n// The entity NAME a unique-index refusal carries. `update` does not take one \226\128\148 nothing else in\n// its emission needs it \226\128\148 so it travels on the index, where the refusal is built.\nfunc uniqueEntity[Row any](indexes []UniqueIndex[Row]) string {\n\tif len(indexes) == 0 {\n\t\treturn \"\"\n\t}\n\treturn indexes[0].Entity\n}\n\n// The trap both backends raise when an `updateAndReturnOne` predicate names more than one\n// row. One message, so a program's `expectFail` and its operator log read the same on the\n// Memory store and on Postgres. Declared HERE rather than beside the Postgres half because\n// this file ships with every program and dbquery.go only with a Postgres-backed one \226\128\148 the\n// runtime file gates are exclusion filters, and a constant used by an always-shipped file\n// has to live in an always-shipped file.\nconst updateReturnOneAmbiguous = \"updateAndReturnOne: the predicate matched more than one row; \" +\n\t\"narrow the `where` clause (the primary key or a unique index) so exactly one row is named\"\n\n// TableUpdateReturnOne is `updateAndReturnOne`: it updates the ONE row the predicate names\n// and yields it. It traps when the predicate matched nothing (\"no row updated\" is a failure\n// on both backends rather than a zero value) and it traps when the predicate matched more\n// than one row \226\128\148 updating the first match while Postgres updated every match was a silent\n// disagreement between the store tests run on and the store production runs on, so both\n// now refuse the ambiguous predicate before changing anything.\nfunc TableUpdateReturnOne[Row any](table *Table[Row], match func(Row) bool, apply func(Row) Row,\n\tunique ...UniqueIndex[Row]) Row {\n\tfor range tableWriteRetries {\n\t\trows, version := table.snapshot()\n\t\tmatched := -1\n\t\tfor index, row := range rows {\n\t\t\tif !match(row) {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tif matched >= 0 {\n\t\t\t\tpanic(updateReturnOneAmbiguous)\n\t\t\t}\n\t\t\tmatched = index\n\t\t}\n\t\tif matched < 0 {\n\t\t\tpanic(\"updateAndReturnOne: no row matched\")\n\t\t}\n\t\tupdated := apply(rows[matched])\n\t\treplacement := []rowReplacement[Row]{{position: matched, row: updated}}\n\t\tif table.replaceIfUnchanged(version, replacement, unique) {\n\t\t\treturn updated\n\t\t}\n\t}\n\tpanic(tableWriteContended(\"updateAndReturnOne\"))\n}\n\n// TableTruncate empties the table, for a test that wants a fresh store.\nfunc TableTruncate[Row any](table *Table[Row]) {\n\tdefer releaseMemoryWrite(acquireMemoryWrite())\n\ttable.mutex.Lock()\n\tdefer table.mutex.Unlock()\n\ttable.publishLocked(nil)\n}\n\n// TableAny reports whether any row matches. It is what an `innerJoin` becomes on the in-memory\n// store: the clause filters the MAIN entity's rows to those with a counterpart, and the result\n// is still a list of that entity \226\128\148 so it is an existence test, not a product.\n//\n// That reading is also why the Postgres path emits `exists (\226\128\166)` rather than a real INNER JOIN:\n// a join would DUPLICATE a main row for every counterpart, which a `List Order` cannot hold.\n// The Racket backends disagree here \226\128\148 its memory store tests existence while its Postgres path\n// joins \226\128\148 and the two Go paths agree with each other and with the declared result type.\nfunc TableAny[Row any](table *Table[Row], match func(Row) bool) bool {\n\trows, _ := table.snapshot()\n\tfor _, row := range rows {\n\t\tif match(row) {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// TableGroupFold is the grouped aggregate: it buckets the matching rows by a key, folds\n// each bucket, and answers one (key, value) pair per bucket, ORDERED BY KEY ASCENDING.\n//\n// The order is part of the contract rather than an accident of iteration: the Racket memory\n// backend sorts its buckets and PostgreSQL's `GROUP BY \226\128\166 ORDER BY 1` does the same, and a\n// series a chart draws is only a series if its points are in order.\n//\n// The key is compared through the two functions the emitter supplies rather than being used\n// as a Go map key: a bucket key can be a `PosixMillis`, whose value is an arbitrary-precision\n// integer and therefore not comparable with `==`. Rows are sorted by key and folded in runs,\n// so no key is compared more than the sort needs.\nfunc TableGroupFold[Row any, Key any, Value any](\n\ttable *Table[Row],\n\tmatch func(Row) bool,\n\tkey func(Row) Key,\n\tless func(Key, Key) bool,\n\tequal func(Key, Key) bool,\n\tstep func(Value, Row) Value,\n\tzero Value,\n) []Tuple2[Key, Value] {\n\trows, _ := table.snapshot()\n\ttype keyed struct {\n\t\tkey Key\n\t\trow Row\n\t}\n\tmatched := make([]keyed, 0, len(rows))\n\tfor _, row := range rows {\n\t\tif match(row) {\n\t\t\tmatched = append(matched, keyed{key: key(row), row: row})\n\t\t}\n\t}\n\tsort.SliceStable(matched, func(left, right int) bool {\n\t\treturn less(matched[left].key, matched[right].key)\n\t})\n\tout := []Tuple2[Key, Value]{}\n\tfor index := 0; index < len(matched); {\n\t\tbucket := zero\n\t\tat := index\n\t\tfor ; at < len(matched) && equal(matched[at].key, matched[index].key); at++ {\n\t\t\tbucket = step(bucket, matched[at].row)\n\t\t}\n\t\tout = append(out, Tuple2[Key, Value]{Tuple2First: matched[index].key, Tuple2Second: bucket})\n\t\tindex = at\n\t}\n\treturn out\n}\n\n// TableUpsert is `upsert \226\128\166 onConflict [c] doUpdate [u]`: the row is inserted, unless one\n// already matches on the CONFLICT columns, in which case only the UPDATE columns of that row\n// are overwritten.\n//\n// The two halves are the Racket memory backend's, rule for rule: an existing row is found by\n// its conflict columns (not by its primary key \226\128\148 the conflict target may be any unique\n// index), the merged row is checked against the unique indexes with ITS OWN position skipped\n// (updating a row must not collide with itself), and the insert path checks them with nothing\n// skipped. The row that ends up stored is the answer, so a caller reads back what was\n// written rather than what it asked for.\nfunc TableUpsert[Row any](\n\ttable *Table[Row],\n\tentity string,\n\trow Row,\n\tmatches func(Row, Row) bool,\n\tmerge func(Row, Row) Row,\n\tconflicts func(Row, Row) bool,\n\tunique ...UniqueIndex[Row],\n) Row {\n\tdefer releaseMemoryWrite(acquireMemoryWrite())\n\t// `matches` and `merge` are the emitter's field comparisons over two rows already in\n\t// hand, not Tesl expressions, so they carry no query and may run under the lock.\n\ttable.mutex.Lock()\n\tdefer table.mutex.Unlock()\n\tfor position, existing := range table.rows {\n\t\tif !matches(existing, row) {\n\t\t\tcontinue\n\t\t}\n\t\tmerged := merge(existing, row)\n\t\tcheckUniqueIn(table.rows, entity, merged, unique, position)\n\t\tnext := append(make([]Row, 0, len(table.rows)), table.rows...)\n\t\tnext[position] = merged\n\t\ttable.publishLocked(next)\n\t\treturn merged\n\t}\n\tcheckUniqueIn(table.rows, entity, row, unique, -1)\n\ttable.publishLocked(insertInto(table.rows, entity, row, conflicts))\n\treturn row\n}\n\n// Discard turns a value-returning call into Tesl's `Unit`. It exists for the forms the\n// checker types as Unit while the runtime call still answers something \226\128\148 `upsert` is the\n// one: the stored row is a useful thing for the runtime to hand back and a thing no Tesl\n// program can name, so it is dropped here rather than in a statement the emitter would\n// otherwise have to invent.\nfunc Discard[A any](A) struct{} { return struct{}{} }\n\n// The Memory-transaction machinery lives HERE, not in database.go, for the same reason\n// `updateReturnOneAmbiguous` does: this file ships with every program and database.go only\n// with a Postgres-backed one, and `publishLocked` above needs it in a Memory-only program.\n// \226\148\128\226\148\128 Memory transactions \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// The Memory store has no log to roll back from, so `transaction { }` there is ROLLBACK BY\n// RESTORE: every table the body writes records, on its FIRST write inside the block, the rows it\n// held before that write (table.go, `publishLocked`); a panic out of the body reinstalls those\n// rows on every recorded table, then continues unwinding. Only tables the body touched pay\n// anything, and the record is a slice header \226\128\148 the rows are immutable once published, so no\n// copy is taken on the way in.\n//\n// Transactions take the Memory gate exclusively through commit or rollback. Ordinary reads and\n// writes take it shared, preserving their concurrency with each other but making them wait\n// outside a transaction. The owner skips reacquiring the non-reentrant gate, so it can read its\n// own writes and predicates may query tables without deadlocking. The gate is always taken before\n// a table mutex.\n//\n// Nesting is refused exactly as the Postgres path refuses it, so a program cannot pass its tests\n// with a shape that traps in production. The open transaction is keyed by goroutine, like the\n// Postgres one, and for the same reason: a goroutine started inside the body does not join it.\n\n// memoryTransaction is one open Memory `transaction { }`: the tables it has written and, per\n// table, the rows to reinstall on rollback. It is touched only by the goroutine that owns it.\ntype memoryTransaction struct {\n\trecorded map[any]struct{}\n\trestores []func()\n}\n\n// recordForRollback remembers `rows` as what `table` held before this transaction's first write\n// to it. A later write to the same table is ignored: the rollback target is the state before\n// the transaction, not before the latest statement. A function rather than a method because\n// the table is generic and a method cannot be.\nfunc recordForRollback[Row any](transaction *memoryTransaction, table *Table[Row], rows []Row) {\n\tif _, seen := transaction.recorded[table]; seen {\n\t\treturn\n\t}\n\ttransaction.recorded[table] = struct{}{}\n\ttransaction.restores = append(transaction.restores, func() { table.restoreRows(rows) })\n}\n\nvar openMemoryTransactions sync.Map // goroutine id -> *memoryTransaction\n\n// Transactions exclude every other Memory table operation for their full duration. Ordinary\n// readers and writers use the shared side so they remain concurrent except during a transaction.\nvar memoryTransactionGate sync.RWMutex\n\n// memoryTransactionsOpen lets an operation skip the goroutine-id lookup entirely \226\128\148 the common case\n// of a program with no transaction open anywhere.\nvar memoryTransactionsOpen atomic.Int64\n\n// acquireMemoryWrite enters the shared side for an ordinary write. A transaction's own writes\n// already hold the exclusive side and must not try to take this non-reentrant lock again.\nfunc acquireMemoryWrite() bool {\n\tif memoryTransactionsOpen.Load() > 0 && currentMemoryTransaction() != nil {\n\t\treturn false\n\t}\n\tmemoryTransactionGate.RLock()\n\treturn true\n}\n\nfunc releaseMemoryWrite(acquired bool) {\n\tif acquired {\n\t\tmemoryTransactionGate.RUnlock()\n\t}\n}\n\nfunc acquireMemoryRead() bool {\n\tif memoryTransactionsOpen.Load() > 0 && currentMemoryTransaction() != nil {\n\t\treturn false\n\t}\n\tmemoryTransactionGate.RLock()\n\treturn true\n}\n\nfunc releaseMemoryRead(acquired bool) {\n\tif acquired {\n\t\tmemoryTransactionGate.RUnlock()\n\t}\n}\n\nfunc currentMemoryTransaction() *memoryTransaction {\n\tif found, open := openMemoryTransactions.Load(goroutineID()); open {\n\t\tif transaction, ok := found.(*memoryTransaction); ok {\n\t\t\treturn transaction\n\t\t}\n\t}\n\treturn nil\n}\n\n// WithMemoryTransaction is exported (rather than a package-private helper) because its only\n// caller sits in database.go, which ships only with a Postgres-backed program \226\128\148 in a\n// Memory-only module the function would be dead code the lint gate refuses.\nfunc WithMemoryTransaction(body func()) {\n\tkey := goroutineID()\n\tif _, nested := openMemoryTransactions.Load(key); nested {\n\t\tpanic(\"transaction: a transaction is already open on the Memory store\")\n\t}\n\tmemoryTransactionGate.Lock()\n\ttransaction := &memoryTransaction{recorded: map[any]struct{}{}}\n\topenMemoryTransactions.Store(key, transaction)\n\tmemoryTransactionsOpen.Add(1)\n\tcommitted := false\n\tdefer func() {\n\t\tif !committed {\n\t\t\t// Most recent first, so a table written several times ends at its FIRST recorded\n\t\t\t// state \226\128\148 though `record` keeps only that one, the order also costs nothing.\n\t\t\tfor index := len(transaction.restores) - 1; index >= 0; index-- {\n\t\t\t\ttransaction.restores[index]()\n\t\t\t}\n\t\t}\n\t\topenMemoryTransactions.Delete(key)\n\t\tmemoryTransactionsOpen.Add(-1)\n\t\tmemoryTransactionGate.Unlock()\n\t}()\n\tbody()\n\tcommitted = true\n}\n\n// goroutineID reads the id out of the goroutine's own stack header, which is the only place\n// the runtime exposes it. The header's shape (\"goroutine 17 [running]:\") is fixed by\n// `runtime.Stack` itself; an unreadable one answers 0, which is a key like any other \226\128\148 every\n// goroutine that fails to parse would share one transaction, and none can, because the parse\n// cannot fail for a header this function is looking at.\nfunc goroutineID() uint64 {\n\tvar header [64]byte\n\twritten := runtime.Stack(header[:], false)\n\tfields := bytes.Fields(header[:written])\n\tif len(fields) < 2 {\n\t\treturn 0\n\t}\n\tid, err := strconv.ParseUint(string(fields[1]), 10, 64)\n\tif err != nil {\n\t\treturn 0\n\t}\n\treturn id\n}\n");
  ("telemetry.go", "package teslrt\n\nimport (\n\t\"bytes\"\n\t\"crypto/rand\"\n\t\"encoding/hex\"\n\t\"encoding/json\"\n\t\"fmt\"\n\t\"math\"\n\t\"net/http\"\n\t\"os\"\n\t\"sort\"\n\t\"strings\"\n\t\"sync\"\n\t\"time\"\n)\n\n// `Tesl.Telemetry`: the ambient signals \226\128\148 a telemetry EVENT (`telemetry \"name\" { \226\128\166 }`) and the\n// three metric instruments (`counter`, `histogram`, `gauge`).\n//\n// Ambient by design, and that is a language decision rather than an implementation shortcut: an\n// observability call that needed a capability would either be threaded through every signature\n// or be left out of the code that most needs it. So there is nothing to grant and nothing to\n// pass; what a program configures is the SINK, once, in the App `telemetry` field (or the legacy\n// `initTelemetry` form).\n//\n// Events and metrics accumulate in process, and with `console True` they are written to stderr.\n// A configured non-memory endpoint also receives standard-library-only OTLP/JSON batches from the\n// asynchronous exporter; collector failures never break the application record path.\n//\n// The recorder is guarded by one mutex. Metrics are per (name, attribute-set), which is what\n// makes a counter cumulative rather than per-call, and the attribute set is normalised to a\n// sorted key so `{a=1,b=2}` and `{b=2,a=1}` are one series.\ntype TelemetryEvent struct {\n\tService     string\n\tEndpoint    string\n\tMessage     string\n\tAttributes  []Tuple2[string, string]\n\tTimestampMs int64\n\tTraceID     string\n\tSpanID      string\n}\n\n// MetricKind distinguishes the three instruments. A counter SUMS, a gauge keeps the LAST value,\n// and a histogram keeps the shape of a distribution (count/sum/min/max) \226\128\148 not the bucket\n// boundaries an OTLP histogram carries, which belong with the exporter.\ntype MetricKind int\n\nconst (\n\tMetricCounter MetricKind = iota\n\tMetricHistogram\n\tMetricGauge\n)\n\n// MetricSeries is one instrument at one attribute set. Histograms retain the aggregate shape used\n// by the OTLP exporter; bucket boundaries are intentionally omitted because the Tesl surface does\n// not expose a boundary argument.\ntype MetricSeries struct {\n\tName       string\n\tKind       MetricKind\n\tAttributes []Tuple2[string, string]\n\tCount      int64\n\tSum        float64\n\tLast       float64\n\tMin        float64\n\tMax        float64\n}\n\nvar telemetry = struct {\n\tmutex             sync.Mutex\n\tservice           string\n\tendpoint          string\n\tconsole           bool\n\tmetricsEnabled    bool\n\ttracesEnabled     bool\n\ttraceRatio        float64\n\tmetricsIntervalMs int\n\tevents            eventRing\n\tseries            map[string]*MetricSeries\n\t// instrumentSeries counts the distinct attribute sets each instrument (kind + name) has\n\t// produced, which is what the cardinality cap is measured against.\n\tinstrumentSeries map[string]int\n\texporterStop     chan struct{}\n}{service: \"tesl\", metricsEnabled: true, traceRatio: 1.0,\n\tseries: map[string]*MetricSeries{}, instrumentSeries: map[string]int{}}\n\n// \226\148\128\226\148\128 Bounds \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// Both stores are fed by request-derived data \226\128\148 a label built from a user id, an event per\n// request \226\128\148 and both were unbounded. The spec's promises are the bounds implemented here:\n//\n//\tmaxMetricSeriesPerInstrument   \"each instrument is capped at 2000 distinct attribute sets\n//\t                               \226\128\148 overflow folds into a single {otel.metric.overflow=true}\n//\t                               series\", so a hostile label costs one extra series;\n//\tmaxTelemetryEvents             \"events are buffered in a bounded queue (drop-oldest on\n//\t                               overflow) flushed by a background timer\"; exported events\n//\t                               leave the buffer, and a drop is counted in the exporter's\n//\t                               own `tesl.telemetry.dropped` counter.\n//\n// A sample that is NaN or \194\177Inf is refused at the record path and counted under the same\n// counter: encoding/json cannot represent it, and one such value used to make mustJSON answer\n// nil \226\128\148 blanking the ENTIRE metrics export for the rest of the process.\nconst (\n\tmaxMetricSeriesPerInstrument = 2000\n\tmaxTelemetryEvents           = 10000\n\ttelemetryDroppedMetric       = \"tesl.telemetry.dropped\"\n)\n\nvar metricOverflowAttributes = []Tuple2[string, string]{\n\t{Tuple2First: \"otel.metric.overflow\", Tuple2Second: \"true\"},\n}\n\n// eventRing is the bounded event buffer: a fixed-capacity ring that drops the OLDEST event\n// when full. Every event carries a position in one monotonic sequence, so the exporter can\n// snapshot the buffer, post it, and then remove exactly what it posted \226\128\148 events that arrived\n// meanwhile keep their place, and an overflow that already discarded some of the snapshot\n// does not make the drain discard newer ones in their stead.\ntype eventRing struct {\n\titems    []TelemetryEvent\n\thead     int   // index of the oldest item\n\tcount    int   // items held\n\tfirstSeq int64 // sequence number of the oldest item\n\tdropped  int64 // events discarded because the ring was full\n}\n\nfunc (ring *eventRing) push(event TelemetryEvent) {\n\tif ring.items == nil {\n\t\tring.items = make([]TelemetryEvent, maxTelemetryEvents)\n\t}\n\tif ring.count == len(ring.items) {\n\t\t// Full: overwrite the oldest slot and advance past it.\n\t\tring.items[ring.head] = event\n\t\tring.head = (ring.head + 1) % len(ring.items)\n\t\tring.firstSeq++\n\t\tring.dropped++\n\t\treturn\n\t}\n\tring.items[(ring.head+ring.count)%len(ring.items)] = event\n\tring.count++\n}\n\n// snapshot answers the events oldest-first and the sequence number just past the newest.\nfunc (ring *eventRing) snapshot() ([]TelemetryEvent, int64) {\n\tout := make([]TelemetryEvent, 0, ring.count)\n\tfor index := 0; index < ring.count; index++ {\n\t\tout = append(out, ring.items[(ring.head+index)%len(ring.items)])\n\t}\n\treturn out, ring.firstSeq + int64(ring.count)\n}\n\n// dropBefore removes every event with a sequence number below `seq` \226\128\148 the ones a snapshot\n// taken at `seq` contained and the exporter has since delivered.\nfunc (ring *eventRing) dropBefore(seq int64) {\n\tremove := seq - ring.firstSeq\n\tif remove <= 0 {\n\t\treturn\n\t}\n\tif remove > int64(ring.count) {\n\t\tremove = int64(ring.count)\n\t}\n\tfor index := int64(0); index < remove; index++ {\n\t\tring.items[(ring.head+int(index))%len(ring.items)] = TelemetryEvent{}\n\t}\n\tring.head = (ring.head + int(remove)) % len(ring.items)\n\tring.count -= int(remove)\n\tring.firstSeq += remove\n}\n\nfunc (ring *eventRing) reset() {\n\t// The sequence moves past everything ever held, so a drain carrying a snapshot taken\n\t// before the reset removes nothing recorded after it.\n\tring.firstSeq += int64(ring.count)\n\t// Cleared in place rather than set to nil: `snapshot`/`dropBefore` index the backing\n\t// array and the analyser cannot see that count==0 guards them; releasing the events is\n\t// what matters, and the array is reused by the next `record`.\n\tfor index := range ring.items {\n\t\tring.items[index] = TelemetryEvent{}\n\t}\n\tring.head, ring.count = 0, 0\n\tring.dropped = 0\n}\n\nfunc readCryptoRandom(value []byte) (int, error) {\n\treturn rand.Read(value)\n}\n\n// InitTelemetry is the runtime contract for App's TelemetryConfig lowering. It configures the\n// sink once from the App `telemetry` field; the legacy `initTelemetry service \226\128\166 endpoint \226\128\166 console\n// \226\128\166` form uses the same call. Calling it twice replaces the configuration and clears what was\n// recorded, which is what a fresh process would have.\nfunc InitTelemetry(service, endpoint string, console, metrics, traces bool,\n\tmetricsIntervalMs int, traceRatio float64) struct{} {\n\ttelemetry.mutex.Lock()\n\tdefer telemetry.mutex.Unlock()\n\tif telemetry.exporterStop != nil {\n\t\tclose(telemetry.exporterStop)\n\t\ttelemetry.exporterStop = nil\n\t}\n\tif service != \"\" {\n\t\ttelemetry.service = service\n\t}\n\ttelemetry.endpoint = endpoint\n\ttelemetry.console = console\n\ttelemetry.metricsEnabled = metrics\n\ttelemetry.tracesEnabled = traces\n\ttelemetry.metricsIntervalMs = metricsIntervalMs\n\ttelemetry.traceRatio = traceRatio\n\ttelemetry.events.reset()\n\ttelemetry.series = map[string]*MetricSeries{}\n\ttelemetry.instrumentSeries = map[string]int{}\n\tif endpoint != \"\" && endpoint != \"in-memory\" {\n\t\ttelemetry.exporterStop = make(chan struct{})\n\t\tgo runTelemetryExporter(endpoint, metricsIntervalMs, telemetry.exporterStop)\n\t}\n\treturn struct{}{}\n}\n\n// Telemetry is the `telemetry \"name\" { key = value }` block: one event, with its attributes\n// already rendered to text by the emitter (which knows each field's type, and renders a `secret`\n// as its redaction rather than its payload).\nfunc Telemetry(message string, attributes []Tuple2[string, string]) struct{} {\n\tevent := TelemetryEvent{\n\t\tService:     telemetry.service,\n\t\tEndpoint:    telemetry.endpoint,\n\t\tMessage:     message,\n\t\tAttributes:  attributes,\n\t\tTimestampMs: telemetryNowMillis(),\n\t\tTraceID:     telemetryID(16),\n\t\tSpanID:      telemetryID(8),\n\t}\n\ttelemetry.mutex.Lock()\n\tbefore := telemetry.events.dropped\n\ttelemetry.events.push(event)\n\tif telemetry.events.dropped > before {\n\t\trecordMetricLocked(telemetryDroppedMetric, MetricCounter, 1,\n\t\t\t[]Tuple2[string, string]{{Tuple2First: \"reason\", Tuple2Second: \"event-buffer-full\"}})\n\t}\n\tconsole := telemetry.console\n\ttelemetry.mutex.Unlock()\n\tif console {\n\t\tfmt.Fprintf(os.Stderr, \"[telemetry] %s %s%s\\n\", event.Service, message,\n\t\t\trenderAttributes(attributes))\n\t}\n\treturn struct{}{}\n}\n\n// telemetryNowMillis is the event timestamp. An Int wider than int64 cannot be a wall clock, so\n// the conversion is total here in a way it is not in general.\nfunc telemetryNowMillis() int64 {\n\tmillis, _ := NowMillis().Value.Int64()\n\treturn millis\n}\n\nfunc renderAttributes(attributes []Tuple2[string, string]) string {\n\tif len(attributes) == 0 {\n\t\treturn \"\"\n\t}\n\tparts := make([]string, 0, len(attributes))\n\tfor _, attribute := range attributes {\n\t\tparts = append(parts, attribute.Tuple2First+\"=\"+attribute.Tuple2Second)\n\t}\n\treturn \" {\" + strings.Join(parts, \", \") + \"}\"\n}\n\n// seriesKey is the identity of a metric series: its name plus its attribute set, normalised so\n// the same attributes in a different order are the same series.\nfunc seriesKey(name string, kind MetricKind, attributes []Tuple2[string, string]) string {\n\tpairs := make([]string, 0, len(attributes))\n\tfor _, attribute := range attributes {\n\t\tpairs = append(pairs, attribute.Tuple2First+\"\\x00\"+attribute.Tuple2Second)\n\t}\n\tsort.Strings(pairs)\n\treturn fmt.Sprintf(\"%d\\x00%s\\x00%s\", kind, name, strings.Join(pairs, \"\\x01\"))\n}\n\nfunc recordMetric(name string, kind MetricKind, value float64,\n\tattributes []Tuple2[string, string]) {\n\ttelemetry.mutex.Lock()\n\tdefer telemetry.mutex.Unlock()\n\tif !telemetry.metricsEnabled {\n\t\treturn\n\t}\n\tif math.IsNaN(value) || math.IsInf(value, 0) {\n\t\t// Refused here rather than at export: a series that held one non-finite value could\n\t\t// never be encoded again, and the export dropped every OTHER series with it.\n\t\trecordMetricLocked(telemetryDroppedMetric, MetricCounter, 1,\n\t\t\t[]Tuple2[string, string]{{Tuple2First: \"reason\", Tuple2Second: \"non-finite-sample\"}})\n\t\treturn\n\t}\n\trecordMetricLocked(name, kind, value, attributes)\n}\n\n// recordMetricLocked is the record path proper; the caller holds telemetry.mutex. A new\n// attribute set past the instrument's cap lands in the instrument's single overflow series\n// instead of a series of its own.\nfunc recordMetricLocked(name string, kind MetricKind, value float64,\n\tattributes []Tuple2[string, string]) {\n\tkey := seriesKey(name, kind, attributes)\n\tseries, found := telemetry.series[key]\n\tif !found {\n\t\tinstrument := fmt.Sprintf(\"%d\\x00%s\", kind, name)\n\t\tif telemetry.instrumentSeries[instrument] >= maxMetricSeriesPerInstrument {\n\t\t\tattributes = metricOverflowAttributes\n\t\t\tkey = seriesKey(name, kind, attributes)\n\t\t\tseries, found = telemetry.series[key]\n\t\t} else {\n\t\t\ttelemetry.instrumentSeries[instrument]++\n\t\t}\n\t}\n\tif !found {\n\t\tseries = &MetricSeries{Name: name, Kind: kind, Attributes: attributes,\n\t\t\tMin: value, Max: value}\n\t\ttelemetry.series[key] = series\n\t}\n\tseries.Count++\n\tseries.Sum += value\n\tseries.Last = value\n\tif value < series.Min {\n\t\tseries.Min = value\n\t}\n\tif value > series.Max {\n\t\tseries.Max = value\n\t}\n}\n\n// Counter is `counter \"name\" delta attrs`: CUMULATIVE, which is why the series is kept rather\n// than the call. A negative delta is allowed for the same reason Racket allows it \226\128\148 the\n// instrument records what the program says.\nfunc Counter(name string, delta Int, attributes []Tuple2[string, string]) struct{} {\n\trecordMetric(name, MetricCounter, delta.Float64(), attributes)\n\treturn struct{}{}\n}\n\nfunc Histogram(name string, value float64, attributes []Tuple2[string, string]) struct{} {\n\trecordMetric(name, MetricHistogram, value, attributes)\n\treturn struct{}{}\n}\n\nfunc Gauge(name string, value float64, attributes []Tuple2[string, string]) struct{} {\n\trecordMetric(name, MetricGauge, value, attributes)\n\treturn struct{}{}\n}\n\n// \226\148\128\226\148\128 Inspection seams \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// Not Tesl-surface names: they exist so the runtime's own tests can assert what was recorded,\n// and so a program that has shed Tesl can read its own telemetry without an exporter.\n\nfunc TelemetryEvents() []TelemetryEvent {\n\ttelemetry.mutex.Lock()\n\tdefer telemetry.mutex.Unlock()\n\tevents, _ := telemetry.events.snapshot()\n\treturn events\n}\n\n// TelemetryDroppedEvents is how many events the bounded buffer discarded since the last\n// reset \226\128\148 the number the `tesl.telemetry.dropped` counter also carries.\nfunc TelemetryDroppedEvents() int64 {\n\ttelemetry.mutex.Lock()\n\tdefer telemetry.mutex.Unlock()\n\treturn telemetry.events.dropped\n}\n\nfunc telemetryTraceEnabled() bool {\n\ttelemetry.mutex.Lock()\n\tdefer telemetry.mutex.Unlock()\n\treturn telemetry.tracesEnabled\n}\n\n// MetricSeriesSnapshot is every series, in a deterministic order (by name, then by key), so a\n// test or a dump reads the same way twice.\nfunc MetricSeriesSnapshot() []MetricSeries {\n\ttelemetry.mutex.Lock()\n\tdefer telemetry.mutex.Unlock()\n\tkeys := make([]string, 0, len(telemetry.series))\n\tfor key := range telemetry.series {\n\t\tkeys = append(keys, key)\n\t}\n\tsort.Strings(keys)\n\tout := make([]MetricSeries, 0, len(keys))\n\tfor _, key := range keys {\n\t\tif series := telemetry.series[key]; series != nil {\n\t\t\tout = append(out, *series)\n\t\t}\n\t}\n\tsort.SliceStable(out, func(left, right int) bool { return out[left].Name < out[right].Name })\n\treturn out\n}\n\n// ResetTelemetry clears what was recorded, for a test that asserts on it. The emitted per-test\n// reset calls it for the same reason it truncates tables: one test block's signals must not be\n// another's.\nfunc ResetTelemetry() {\n\ttelemetry.mutex.Lock()\n\tdefer telemetry.mutex.Unlock()\n\ttelemetry.events.reset()\n\ttelemetry.series = map[string]*MetricSeries{}\n\ttelemetry.instrumentSeries = map[string]int{}\n}\n\n// MillisOf narrows a Tesl `Int` interval to the plain int the recorder keeps. An interval outside\n// int64 is a configuration mistake rather than a duration, so it fails at configuration time.\nfunc MillisOf(value Int) int {\n\tmillis, exact := value.Int64()\n\tif !exact || millis < 0 {\n\t\tpanic(\"initTelemetry: \" + value.String() + \" is not a millisecond interval\")\n\t}\n\treturn int(millis)\n}\n\nvar otlpHTTPClient = &http.Client{Timeout: 2 * time.Second}\n\nfunc telemetryID(size int) string {\n\tvalue := make([]byte, size)\n\tif _, err := cryptoRandRead(value); err != nil {\n\t\treturn strings.Repeat(\"0\", size*2)\n\t}\n\treturn hex.EncodeToString(value)\n}\n\nvar cryptoRandRead = func(value []byte) (int, error) { return readCryptoRandom(value) }\n\nfunc runTelemetryExporter(endpoint string, intervalMs int, stop <-chan struct{}) {\n\tif intervalMs <= 0 {\n\t\tintervalMs = 60000\n\t}\n\tticker := time.NewTicker(time.Duration(intervalMs) * time.Millisecond)\n\tdefer ticker.Stop()\n\tfor {\n\t\tselect {\n\t\tcase <-ticker.C:\n\t\t\tfunc() {\n\t\t\t\tdefer func() {\n\t\t\t\t\tif trap := recover(); trap != nil {\n\t\t\t\t\t\tfmt.Fprintf(os.Stderr, \"tesl: telemetry exporter recovered from a trap: %v\\n\", trap)\n\t\t\t\t\t}\n\t\t\t\t}()\n\t\t\t\texportTelemetry(endpoint)\n\t\t\t}()\n\t\tcase <-stop:\n\t\t\treturn\n\t\t}\n\t}\n}\n\n// exportTelemetry posts one interval's snapshot. Metrics are CUMULATIVE and stay; events are\n// a QUEUE \226\128\148 the ones the collector accepted leave the buffer, so an event is exported once,\n// not on every later tick until the process ends (which is what an ever-growing slice did:\n// unbounded memory and O(n\194\178) egress). A failed post keeps them for the next tick, bounded by\n// the ring.\nfunc exportTelemetry(endpoint string) {\n\tmetrics, traces, exportedThrough := telemetryPayloads()\n\tif len(metrics) > 0 {\n\t\tpostOTLP(endpointPath(endpoint, \"/v1/metrics\"), metrics)\n\t}\n\tif len(traces) > 0 && postOTLP(endpointPath(endpoint, \"/v1/traces\"), traces) {\n\t\ttelemetry.mutex.Lock()\n\t\ttelemetry.events.dropBefore(exportedThrough)\n\t\ttelemetry.mutex.Unlock()\n\t}\n}\n\n// postOTLP answers whether the collector ACCEPTED the batch: a 2xx. Anything else \226\128\148 no\n// response, a 5xx, a 429 \226\128\148 is a failed delivery and the caller keeps what it tried to send.\nfunc postOTLP(endpoint string, payload []byte) bool {\n\trequest, err := http.NewRequest(http.MethodPost, endpoint, bytes.NewReader(payload))\n\tif err != nil {\n\t\treturn false\n\t}\n\trequest.Header.Set(\"Content-Type\", \"application/json\")\n\tresponse, err := otlpHTTPClient.Do(request)\n\tif err != nil || response == nil {\n\t\treturn false\n\t}\n\t_ = response.Body.Close()\n\treturn response.StatusCode >= 200 && response.StatusCode < 300\n}\n\nfunc endpointPath(endpoint, suffix string) string {\n\treturn strings.TrimRight(endpoint, \"/\") + suffix\n}\n\n// telemetryPayloads renders the metrics and traces batches, and answers the event sequence\n// the traces batch reaches \226\128\148 what exportTelemetry drains once that batch is delivered.\nfunc telemetryPayloads() (metrics, traces []byte, exportedThrough int64) {\n\ttelemetry.mutex.Lock()\n\tservice := telemetry.service\n\tmetricsEnabled := telemetry.metricsEnabled\n\ttracesEnabled := telemetry.tracesEnabled\n\tseries := make([]MetricSeries, 0, len(telemetry.series))\n\tfor _, value := range telemetry.series {\n\t\tseries = append(series, *value)\n\t}\n\tevents, exportedThrough := telemetry.events.snapshot()\n\ttelemetry.mutex.Unlock()\n\tif metricsEnabled && len(series) > 0 {\n\t\tmetrics = mustJSON(otlpMetrics(service, series))\n\t}\n\tif tracesEnabled && len(events) > 0 {\n\t\ttraces = mustJSON(otlpTraces(service, events))\n\t}\n\treturn metrics, traces, exportedThrough\n}\n\nfunc resource(service string) map[string]any {\n\treturn map[string]any{\"attributes\": []map[string]any{{\n\t\t\"key\": \"service.name\", \"value\": map[string]string{\"stringValue\": service},\n\t}}}\n}\n\nfunc otlpMetrics(service string, series []MetricSeries) map[string]any {\n\tmetrics := make([]map[string]any, 0, len(series))\n\tnow := fmt.Sprint(time.Now().UnixNano())\n\tfor _, value := range series {\n\t\tpoint := map[string]any{\"attributes\": otlpAttributes(value.Attributes), \"timeUnixNano\": now}\n\t\tmetric := map[string]any{\"name\": value.Name}\n\t\tswitch value.Kind {\n\t\tcase MetricCounter:\n\t\t\tpoint[\"asInt\"] = fmt.Sprint(int64(value.Last))\n\t\t\tmetric[\"sum\"] = map[string]any{\"aggregationTemporality\": 2, \"isMonotonic\": true, \"dataPoints\": []any{point}}\n\t\tcase MetricGauge:\n\t\t\tpoint[\"asDouble\"] = value.Last\n\t\t\tmetric[\"gauge\"] = map[string]any{\"dataPoints\": []any{point}}\n\t\tcase MetricHistogram:\n\t\t\tpoint[\"count\"] = fmt.Sprint(value.Count)\n\t\t\tpoint[\"sum\"] = value.Sum\n\t\t\tmetric[\"histogram\"] = map[string]any{\"aggregationTemporality\": 2, \"dataPoints\": []any{point}}\n\t\t}\n\t\tmetrics = append(metrics, metric)\n\t}\n\treturn map[string]any{\"resourceMetrics\": []any{map[string]any{\n\t\t\"resource\": resource(service), \"scopeMetrics\": []any{map[string]any{\"metrics\": metrics}},\n\t}}}\n}\n\nfunc otlpTraces(service string, events []TelemetryEvent) map[string]any {\n\tspans := make([]map[string]any, 0, len(events))\n\tfor _, event := range events {\n\t\tstart := event.TimestampMs * 1_000_000\n\t\tspans = append(spans, map[string]any{\n\t\t\t\"traceId\": event.TraceID, \"spanId\": event.SpanID, \"name\": event.Message,\n\t\t\t\"startTimeUnixNano\": fmt.Sprint(start), \"endTimeUnixNano\": fmt.Sprint(start),\n\t\t\t\"attributes\": otlpAttributes(event.Attributes),\n\t\t})\n\t}\n\treturn map[string]any{\"resourceSpans\": []any{map[string]any{\n\t\t\"resource\": resource(service), \"scopeSpans\": []any{map[string]any{\"spans\": spans}},\n\t}}}\n}\n\nfunc otlpAttributes(attributes []Tuple2[string, string]) []map[string]any {\n\tresult := make([]map[string]any, 0, len(attributes))\n\tfor _, attribute := range attributes {\n\t\tresult = append(result, map[string]any{\n\t\t\t\"key\": attribute.Tuple2First, \"value\": map[string]string{\"stringValue\": attribute.Tuple2Second},\n\t\t})\n\t}\n\treturn result\n}\n\nfunc mustJSON(value any) []byte {\n\tencoded, err := json.Marshal(value)\n\tif err != nil {\n\t\treturn nil\n\t}\n\treturn encoded\n}\n");
  ("time.go", "package teslrt\n\nimport (\n\t\"math/big\"\n\t\"time\"\n)\n\n// PosixMillis is Tesl's canonical instant: milliseconds since the Unix epoch, UTC.\n//\n// It is a NEWTYPE over the exact integer, not an int64 \226\128\148 `tesl/time.rkt` defines it as\n// `(define-newtype PosixMillis Integer)` and Racket's integers are exact and unbounded, so\n// arithmetic on a timestamp cannot silently wrap here either. The type lives in the runtime\n// rather than being emitted per module for the reason `Maybe` does: an instant crosses\n// module boundaries, and two packages declaring their own would be different Go types.\ntype PosixMillis struct {\n\tValue Int\n}\n\n// NowMillis reads the clock. Tesl gates this behind the `time` capability, which the\n// checker enforces; nothing about that survives to run time.\nfunc NowMillis() PosixMillis {\n\treturn PosixMillis{Value: FromInt64(time.Now().UnixMilli())}\n}\n\n// PosixToSeconds truncates toward zero, which is what Racket's `quotient` does \226\128\148 NOT floor,\n// so an instant before the epoch rounds up toward it on both backends.\n// PgGroupZone is the part of a `TimeZone` that a grouped aggregate's SQL needs: a name, or a\n// fixed offset in minutes.\n//\n// It lives in this file \226\128\148 which every program gets \226\128\148 because the two files that need it are\n// gated on DIFFERENT conditions: `dbquery.go` ships only with a Postgres-backed database, and\n// `PgZoneOf` (timetrunc.go) only with a program that buckets by a calendar unit. Declaring it in\n// either one breaks the other, and the gates are exclusion filters: a Memory-backed program that\n// truncates by hour got timetrunc.go WITHOUT dbquery.go and did not compile\n// (`undefined: PgGroupZone`), which is what `example/learn/lesson21-sql-reference.tesl` measured.\n//\n// It carries no tzdata, so an always-shipped home costs three fields and nothing else.\ntype PgGroupZone struct {\n\tName          string\n\tOffsetMinutes int\n\tFixed         bool\n}\n\nfunc PosixToSeconds(instant PosixMillis) Int {\n\treturn MustQuo(instant.Value, FromInt64(1000))\n}\n\nfunc SecondsToPosix(seconds Int) PosixMillis {\n\treturn PosixMillis{Value: Mul(seconds, FromInt64(1000))}\n}\n\nfunc AddMs(instant PosixMillis, delta Int) PosixMillis {\n\treturn PosixMillis{Value: Add(instant.Value, delta)}\n}\n\nfunc SubtractMs(instant PosixMillis, delta Int) PosixMillis {\n\treturn PosixMillis{Value: Sub(instant.Value, delta)}\n}\n\n// DiffMs is later minus earlier, in the argument order Tesl uses: `diffMs a b` = b - a.\nfunc DiffMs(earlier, later PosixMillis) Int {\n\treturn Sub(later.Value, earlier.Value)\n}\n\n// DurationMs is how long ago an instant was, clamped at zero \226\128\148 a clock that went backwards\n// must not produce a negative age (Racket clamps with `max` for the same reason).\nfunc DurationMs(past PosixMillis) Int {\n\telapsed := DiffMs(past, NowMillis())\n\tif Compare(elapsed, FromInt64(0)) < 0 {\n\t\treturn FromInt64(0)\n\t}\n\treturn elapsed\n}\n\n// The units-typed instant surface: `Time.add ts (Duration.hours 2.0)`. The millisecond forms\n// (`addMs`, `diffMs`) stay canonical \226\128\148 they are exact integer arithmetic \226\128\148 and these convert a\n// Duration, which is SI SECONDS as a float, into that exact millisecond count.\n//\n// Seconds \226\134\146 milliseconds rounds HALF-EVEN on the exact rational, the same stance Money takes,\n// so an instant cannot drift by a millisecond over a long series of additions.\nfunc TimeAdd(instant PosixMillis, duration float64) PosixMillis {\n\treturn PosixMillis{Value: Add(instant.Value, DurationToMillis(duration))}\n}\n\nfunc TimeSubtract(instant PosixMillis, duration float64) PosixMillis {\n\treturn PosixMillis{Value: Sub(instant.Value, DurationToMillis(duration))}\n}\n\n// TimeDiff answers (later - earlier) as a Duration in seconds \226\128\148 the typed counterpart of\n// `diffMs`.\nfunc TimeDiff(earlier, later PosixMillis) float64 {\n\tdifference := Sub(later.Value, earlier.Value)\n\tvalue, _ := new(big.Rat).SetInt(difference.bigInt()).Float64()\n\treturn value / 1000.0\n}\n");
  ("timetrunc.go", "package teslrt\n\nimport (\n\t\"strconv\"\n\t\"sync\"\n\t\"time\"\n)\n\n// Calendar truncation, and the `TimeZone` value the buckets are taken in.\n//\n// A rule-for-rule port of `dsl/private/time-trunc.rkt`, which is deliberately dependency-free\n// there for the same reason it is self-contained here: THREE consumers have to agree about\n// where a bucket starts \226\128\148 the `Tesl.Time` surface functions, the query DSL's Memory backend,\n// and the PostgreSQL expressions the emitter generates \226\128\148 and they agree by calling one\n// engine rather than by three implementations happening to match.\n//\n// All arithmetic is exact integer arithmetic with FLOOR division, which is what makes a\n// pre-1970 instant bucket correctly; Go's `/` truncates toward zero, so it is never used on\n// a value that can be negative. Month and year truncation go through Howard Hinnant's\n// public-domain civil_from_days / days_from_civil. A week is the ISO week (Monday start).\n// Proleptic Gregorian, no leap seconds \226\128\148 the civil calendar, like elm/time.\n\nconst (\n\tmsPerHour = 3600000\n\tmsPerDay  = 86400000\n\tmsPerWeek = 604800000\n)\n\n// TimeZone is Tesl's `TimeZone`: UTC, a fixed offset in minutes east of UTC, or one of the\n// baked IANA zones. It carries the zone NAME rather than a `*time.Location`, so it stays\n// comparable \226\128\148 two values are the same zone when they name the same zone \226\128\148 and so its ZERO\n// value is UTC rather than a nil pointer waiting to be dereferenced.\ntype TimeZone struct {\n\tName          string\n\tOffsetMinutes int\n\tFixed         bool\n}\n\n// UtcZone is `Utc`.\nfunc UtcZone() TimeZone { return TimeZone{} }\n\n// FixedOffsetZone is `FixedOffset minutes` \226\128\148 minutes EAST of UTC, so Stockholm in winter is\n// 60 and New York in winter is -300. A fixed offset is not a zone: it does not know about\n// summer time, which is exactly why it is a separate constructor.\nfunc FixedOffsetZone(minutes Int) TimeZone {\n\tvalue, exact := minutes.Int64()\n\tif !exact {\n\t\tpanic(\"FixedOffset: the offset does not fit in a minute count\")\n\t}\n\treturn TimeZone{OffsetMinutes: int(value), Fixed: true}\n}\n\nvar (\n\tzoneCacheMutex sync.Mutex\n\tzoneCache      = map[string]*time.Location{}\n)\n\n// NamedZone is one of the baked IANA zones. The name comes from the compiler's zone\n// catalogue (`compiler/lib/tz_zones.ml`), so it is one of a fixed set rather than a string a\n// program composed \226\128\148 there is no zone-name typo to make at run time. The database is\n// compiled into the binary (see timezone.go), so a lookup cannot fail for a host that has no\n// /usr/share/zoneinfo; it panics rather than falling back to UTC if it ever does, because a\n// timestamp that silently shifts by an hour is the bug this whole module exists to prevent.\nfunc NamedZone(name string) TimeZone {\n\tif _, err := zoneLocation(name); err != nil {\n\t\tpanic(\"TimeZone: \" + name + \" is not in the embedded zone database: \" + err.Error())\n\t}\n\treturn TimeZone{Name: name}\n}\n\nfunc zoneLocation(name string) (*time.Location, error) {\n\tzoneCacheMutex.Lock()\n\tcached, found := zoneCache[name]\n\tzoneCacheMutex.Unlock()\n\tif found {\n\t\treturn cached, nil\n\t}\n\tlocation, err := time.LoadLocation(name)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tzoneCacheMutex.Lock()\n\tzoneCache[name] = location\n\tzoneCacheMutex.Unlock()\n\treturn location, nil\n}\n\n// TzOffsetMinutes is the offset of a zone AT AN INSTANT, in minutes east of UTC. Per\n// instant, not per zone: a named zone is DST-correct without the program tracking summer and\n// winter time, which is the whole reason a `TimeZone` is not an offset.\nfunc TzOffsetMinutes(zone TimeZone, millis int64) int {\n\tswitch {\n\tcase zone.Fixed:\n\t\treturn zone.OffsetMinutes\n\tcase zone.Name == \"\":\n\t\treturn 0\n\tdefault:\n\t\tlocation, err := zoneLocation(zone.Name)\n\t\tif err != nil {\n\t\t\tpanic(\"TimeZone: \" + zone.Name + \" is not in the embedded zone database\")\n\t\t}\n\t\t_, offsetSeconds := time.UnixMilli(millis).In(location).Zone()\n\t\t// Floor rather than truncate: an offset is a whole number of minutes in practice,\n\t\t// but several zones carried a sub-minute offset before 1900.\n\t\treturn int(floorDiv(int64(offsetSeconds), 60))\n\t}\n}\n\n// TimeOffsetAt is the `Time.offsetAt` surface: the zone's offset at an instant, in minutes.\nfunc TimeOffsetAt(zone TimeZone, at PosixMillis) Int {\n\treturn FromInt64(int64(TzOffsetMinutes(zone, posixInt64(at, \"Time.offsetAt\"))))\n}\n\n// TimeTrunc answers the BUCKET-START instant for the wall clock in a zone.\n//\n// A named zone follows PostgreSQL's two-step semantics exactly \226\128\148 the parity suite is the\n// oracle: the instant becomes a local wall clock at the offset AT THAT INSTANT, the wall\n// clock is truncated on the civil calendar, and the local bucket start becomes an instant\n// again using the offset AT THE BUCKET START, re-resolved with one fixup iteration. That\n// last step is what makes a bucket that straddles a DST transition still start at the true\n// local midnight rather than an hour either side of it.\nfunc TimeTrunc(unit string, zone TimeZone, at PosixMillis) PosixMillis {\n\tmillis := posixInt64(at, \"Time.trunc\"+unit)\n\tfirst := TzOffsetMinutes(zone, millis)\n\tlocalStart := localTrunc(unit, millis+int64(first)*60000)\n\tnamed := !zone.Fixed && zone.Name != \"\"\n\tif !named {\n\t\treturn PosixMillis{Value: FromInt64(localStart - int64(first)*60000)}\n\t}\n\tcandidate := localStart - int64(first)*60000\n\tsecond := TzOffsetMinutes(zone, candidate)\n\tthird := TzOffsetMinutes(zone, localStart-int64(second)*60000)\n\treturn PosixMillis{Value: FromInt64(localStart - int64(third)*60000)}\n}\n\nfunc posixInt64(at PosixMillis, who string) int64 {\n\tmillis, exact := at.Value.Int64()\n\tif !exact {\n\t\tpanic(who + \": the instant does not fit in a 64-bit millisecond count\")\n\t}\n\treturn millis\n}\n\n// localTrunc truncates a LOCAL wall-clock millisecond count.\nfunc localTrunc(unit string, local int64) int64 {\n\tswitch unit {\n\tcase \"Hour\":\n\t\treturn floorTo(local, msPerHour)\n\tcase \"Day\":\n\t\treturn floorTo(local, msPerDay)\n\tcase \"Week\":\n\t\t// The ISO week starts on Monday, and epoch day 0 (1970-01-01) is a Thursday, so\n\t\t// shifting by three days aligns Monday to a multiple of a week.\n\t\treturn floorTo(local+3*msPerDay, msPerWeek) - 3*msPerDay\n\tcase \"Month\":\n\t\tyear, month, _ := civilFromDays(floorDiv(local, msPerDay))\n\t\treturn daysFromCivil(year, month, 1) * msPerDay\n\tcase \"Year\":\n\t\tyear, _, _ := civilFromDays(floorDiv(local, msPerDay))\n\t\treturn daysFromCivil(year, 1, 1) * msPerDay\n\tdefault:\n\t\tpanic(\"Time.trunc: unknown unit \" + strconv.Quote(unit))\n\t}\n}\n\n// floorDiv is division that rounds toward NEGATIVE INFINITY, which Go's `/` does not do. The\n// difference is only visible before 1970, which is exactly where a truncating division puts\n// an instant in the wrong bucket.\nfunc floorDiv(value, by int64) int64 {\n\tquotient := value / by\n\tif value%by != 0 && (value < 0) != (by < 0) {\n\t\tquotient--\n\t}\n\treturn quotient\n}\n\nfunc floorTo(value, unit int64) int64 { return floorDiv(value, unit) * unit }\n\n// civilFromDays is Hinnant's civil_from_days: a day count since 1970-01-01 to a civil date.\nfunc civilFromDays(days int64) (int64, int64, int64) {\n\tshifted := days + 719468\n\tera := floorDiv(shifted, 146097)\n\tdayOfEra := shifted - era*146097\n\tyearOfEra := (dayOfEra - dayOfEra/1460 + dayOfEra/36524 - dayOfEra/146096) / 365\n\tyear := yearOfEra + era*400\n\tdayOfYear := dayOfEra - (365*yearOfEra + yearOfEra/4 - yearOfEra/100)\n\tmonthPrime := (5*dayOfYear + 2) / 153\n\tday := dayOfYear - (153*monthPrime+2)/5 + 1\n\tmonth := monthPrime + 3\n\tif monthPrime >= 10 {\n\t\tmonth = monthPrime - 9\n\t}\n\tif month <= 2 {\n\t\tyear++\n\t}\n\treturn year, month, day\n}\n\n// daysFromCivil is Hinnant's days_from_civil: a civil date to a day count since 1970-01-01.\nfunc daysFromCivil(year, month, day int64) int64 {\n\tshiftedYear := year\n\tif month <= 2 {\n\t\tshiftedYear--\n\t}\n\tera := floorDiv(shiftedYear, 400)\n\tyearOfEra := shiftedYear - era*400\n\tmonthPrime := month - 3\n\tif month <= 2 {\n\t\tmonthPrime = month + 9\n\t}\n\tdayOfYear := (153*monthPrime+2)/5 + day - 1\n\tdayOfEra := yearOfEra*365 + yearOfEra/4 - yearOfEra/100 + dayOfYear\n\treturn era*146097 + dayOfEra - 719468\n}\n\n// The five surface functions. Each is one call rather than a `unit` string at the call\n// site, so a typo is a Go compile error rather than a run-time panic \226\128\148 the emitter picks\n// the wrapper from the Tesl name it already resolved.\nfunc TimeTruncHour(zone TimeZone, at PosixMillis) PosixMillis {\n\treturn TimeTrunc(\"Hour\", zone, at)\n}\n\nfunc TimeTruncDay(zone TimeZone, at PosixMillis) PosixMillis {\n\treturn TimeTrunc(\"Day\", zone, at)\n}\n\nfunc TimeTruncWeek(zone TimeZone, at PosixMillis) PosixMillis {\n\treturn TimeTrunc(\"Week\", zone, at)\n}\n\nfunc TimeTruncMonth(zone TimeZone, at PosixMillis) PosixMillis {\n\treturn TimeTrunc(\"Month\", zone, at)\n}\n\nfunc TimeTruncYear(zone TimeZone, at PosixMillis) PosixMillis {\n\treturn TimeTrunc(\"Year\", zone, at)\n}\n\n// PgZoneOf narrows a zone to the part the grouped-aggregate SQL needs (see PgGroupZone). The\n// conversion lives HERE rather than in dbquery.go because this file carries the zone database:\n// a Postgres program that groups by a plain column names the narrow type and never reaches\n// this function, so it ships without tzdata.\n// A CONVERSION rather than a field-by-field literal: the two structs have the same fields in\n// the same order, which staticcheck says outright (S1016) \226\128\148 and if `TimeZone` ever gains a field\n// the conversion stops compiling, which is the loud failure this narrowing wants.\nfunc PgZoneOf(zone TimeZone) PgGroupZone {\n\treturn PgGroupZone(zone)\n}\n");
  ("timezone.go", "package teslrt\n\nimport (\n\t\"strconv\"\n\t\"strings\"\n\t\"time\"\n\t// The IANA database, compiled in. Without it `time.LoadLocation` reads the host's\n\t// /usr/share/zoneinfo, so the same program formats \"Europe/Stockholm\" correctly on a\n\t// developer's laptop and falls back to UTC inside a scratch container \226\128\148 a wrong TIME\n\t// rather than an error. A self-contained binary is the point of this backend, and a\n\t// timestamp that silently shifts by an hour is exactly the class of bug that is found\n\t// in production rather than in a test.\n\t_ \"time/tzdata\"\n)\n\n// formatTime and the calendar surface.\n//\n// The format string is Tesl's own strftime-like vocabulary, not Go's reference-layout one:\n// the two backends have to render a timestamp identically, and `%Y-%m-%d` is what the\n// source says. The directives are exactly those `tesl/time.rkt` implements \226\128\148 anything else\n// passes through as itself, which is what its regexp does.\n\n// FormatTime renders an instant in a named zone.\n//\n// The zone is a STRING here rather than the TimeZone value the truncation family takes,\n// because that is the surface: `formatTime ts \"UTC\" \"%Y-%m-%d\"`. An empty name or \"local\"\n// means the host's zone, matching Racket's `#f` case; an unknown name falls back to UTC\n// rather than trapping, which is also what Racket does when `TZ` names a zone the host has\n// never heard of.\nfunc FormatTime(instant PosixMillis, zone, format string) string {\n\tmillis, exact := instant.Value.Int64()\n\tif !exact {\n\t\tpanic(\"formatTime: the instant does not fit in a 64-bit millisecond count\")\n\t}\n\tmoment := time.UnixMilli(millis).In(formatLocation(zone))\n\treturn renderTimeFormat(moment, millis, format)\n}\n\nfunc formatLocation(zone string) *time.Location {\n\tswitch zone {\n\tcase \"\", \"local\":\n\t\treturn time.Local\n\tcase \"UTC\", \"utc\":\n\t\treturn time.UTC\n\t}\n\tif location, err := time.LoadLocation(zone); err == nil {\n\t\treturn location\n\t}\n\treturn time.UTC\n}\n\n// renderTimeFormat walks the format once, expanding the directives Tesl defines and copying\n// everything else through. `%3N` is milliseconds, and it is read from the ORIGINAL count\n// rather than from the parsed moment so a negative instant keeps Racket's `remainder`\n// semantics (the sign of the dividend).\nfunc renderTimeFormat(moment time.Time, millis int64, format string) string {\n\tvar rendered strings.Builder\n\tfor index := 0; index < len(format); index++ {\n\t\tif format[index] != '%' || index+1 >= len(format) {\n\t\t\trendered.WriteByte(format[index])\n\t\t\tcontinue\n\t\t}\n\t\t// `%3N` is the one two-character directive.\n\t\tif strings.HasPrefix(format[index+1:], \"3N\") {\n\t\t\trendered.WriteString(zeroPad(int(millis%1000), 3))\n\t\t\tindex += 2\n\t\t\tcontinue\n\t\t}\n\t\tswitch format[index+1] {\n\t\tcase 'Y':\n\t\t\trendered.WriteString(zeroPad(moment.Year(), 4))\n\t\tcase 'm':\n\t\t\trendered.WriteString(zeroPad(int(moment.Month()), 2))\n\t\tcase 'd':\n\t\t\trendered.WriteString(zeroPad(moment.Day(), 2))\n\t\tcase 'H':\n\t\t\trendered.WriteString(zeroPad(moment.Hour(), 2))\n\t\tcase 'M':\n\t\t\trendered.WriteString(zeroPad(moment.Minute(), 2))\n\t\tcase 'S':\n\t\t\trendered.WriteString(zeroPad(moment.Second(), 2))\n\t\tcase 'z':\n\t\t\trendered.WriteString(utcOffsetText(moment))\n\t\tcase 'Z':\n\t\t\tname, _ := moment.Zone()\n\t\t\trendered.WriteString(name)\n\t\tcase '%':\n\t\t\trendered.WriteByte('%')\n\t\tdefault:\n\t\t\t// An unknown directive is copied through as it was written, which is what\n\t\t\t// Racket's regexp does with anything outside its alternation.\n\t\t\trendered.WriteByte('%')\n\t\t\trendered.WriteByte(format[index+1])\n\t\t}\n\t\tindex++\n\t}\n\treturn rendered.String()\n}\n\nfunc zeroPad(value, width int) string {\n\ttext := strconv.Itoa(value)\n\tif len(text) >= width {\n\t\treturn text\n\t}\n\treturn strings.Repeat(\"0\", width-len(text)) + text\n}\n\nfunc utcOffsetText(moment time.Time) string {\n\t_, offset := moment.Zone()\n\tsign := \"+\"\n\tif offset < 0 {\n\t\tsign = \"-\"\n\t\toffset = -offset\n\t}\n\treturn sign + zeroPad(offset/3600, 2) + zeroPad((offset%3600)/60, 2)\n}\n");
  ("tuple.go", "package teslrt\n\n// Tuple2 and Tuple3 are Tesl's anonymous products. They live in the runtime for the\n// same reason Maybe does: a tuple crosses module boundaries, so two emitted packages\n// declaring their own would be incompatible Go types.\n//\n// Unlike Maybe they carry NO tag \226\128\148 a single-variant type has nothing to discriminate,\n// and a tag would be a wasted word in a value used as a lightweight pair. The emitter\n// knows this shape and matches `Tuple2 x y -> \226\128\166` by binding the fields directly\n// instead of switching.\n//\n// Field names are the ones the emitter derives for a constructor's payload\n// (constructor name + field name), so `Tuple2.first p` emits as `p.Tuple2First`.\ntype Tuple2[A any, B any] struct {\n\tTuple2First  A\n\tTuple2Second B\n}\n\ntype Tuple3[A any, B any, C any] struct {\n\tTuple3First  A\n\tTuple3Second B\n\tTuple3Third  C\n}\n");
  ("url.go", "package teslrt\n\nimport (\n\t\"strconv\"\n\t\"strings\"\n)\n\n// `Tesl.Url` \226\128\148 an authority-based URL, parsed strictly.\n//\n// A rule-for-rule port of `dsl/private/url-parse.rkt`, NOT a wrapper over `net/url`, and the\n// difference is the point: `net/url` is lenient by design (it is a transport concern), while\n// every rule here exists because a permissive reading of one of them is a bypass \226\128\148\n//\n//\tcontrol characters, spaces and BACKSLASHES are refused ANYWHERE, because a backslash is\n//\ta path separator to some clients and an ordinary character to others;\n//\tUSERINFO is everything before the LAST `@`, which is what browsers and curl do \226\128\148 taking\n//\tthe first `@` instead is itself the bypass (`https://a@trusted.example.com@127.0.0.1/`);\n//\tan UNBRACKETED IPv6 literal is refused rather than guessed at, because it is\n//\tindistinguishable from a bad port;\n//\ta PORT must be 1-5 decimal digits in [1,65535] \226\128\148 an unparseable one fails the URL rather\n//\tthan being dropped, since \"no port\" and \"a port I could not read\" are different facts.\n//\n// The Url value is OPAQUE on the Tesl side: Url.parse is the only way in, so a program\n// cannot hand-build one whose host never went through NormalizeHost.\n\n// Url is the parsed value. Host is CANONICAL (see NormalizeHost) and never empty; Path\n// always starts with `/`. Port, Query, Fragment and UserInfo carry \"was it written\" as well\n// as the value, which is load-bearing for re-serialisation: `?` with nothing after it is not\n// the same URL as no `?` at all.\ntype Url struct {\n\tScheme      string\n\tUserInfo    string\n\tHasUserInfo bool\n\tHost        string\n\tPort        Int\n\tHasPort     bool\n\tPath        string\n\tQuery       string\n\tHasQuery    bool\n\tFragment    string\n\tHasFragment bool\n}\n\nfunc urlSchemeChar(c byte) bool {\n\treturn (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || asciiDigit(c) ||\n\t\tc == '+' || c == '-' || c == '.'\n}\n\nfunc urlControlOrSpace(c byte) bool { return c <= ' ' || c == 0x7f }\n\nfunc schemeDefaultPort(scheme string) (int, bool) {\n\tswitch scheme {\n\tcase \"http\", \"ws\":\n\t\treturn 80, true\n\tcase \"https\", \"wss\":\n\t\treturn 443, true\n\tcase \"ftp\":\n\t\treturn 21, true\n\tdefault:\n\t\treturn 0, false\n\t}\n}\n\n// UrlParse is the only way to make a Url.\nfunc UrlParse(raw string) Maybe[Url] {\n\tif len(raw) == 0 {\n\t\treturn Nothing[Url]()\n\t}\n\tfor index := 0; index < len(raw); index++ {\n\t\tif urlControlOrSpace(raw[index]) || raw[index] == '\\\\' {\n\t\t\treturn Nothing[Url]()\n\t\t}\n\t}\n\tcolon := strings.IndexByte(raw, ':')\n\tif colon <= 0 {\n\t\treturn Nothing[Url]()\n\t}\n\tfirst := raw[0] | 0x20\n\tif first < 'a' || first > 'z' {\n\t\treturn Nothing[Url]()\n\t}\n\tfor index := 0; index < colon; index++ {\n\t\tif !urlSchemeChar(raw[index]) {\n\t\t\treturn Nothing[Url]()\n\t\t}\n\t}\n\tscheme := strings.ToLower(raw[:colon])\n\trest := raw[colon+1:]\n\tif !strings.HasPrefix(rest, \"//\") {\n\t\treturn Nothing[Url]()\n\t}\n\treturn urlAfterSlashes(scheme, rest[2:])\n}\n\nfunc urlAfterSlashes(scheme, text string) Maybe[Url] {\n\tstop := strings.IndexAny(text, \"/?#\")\n\tauthority, remainder := text, \"\"\n\tif stop >= 0 {\n\t\tauthority, remainder = text[:stop], text[stop:]\n\t}\n\tif len(authority) == 0 {\n\t\treturn Nothing[Url]()\n\t}\n\tuserInfo, hasUserInfo, hostPort, ok := splitUserInfo(authority)\n\tif !ok {\n\t\treturn Nothing[Url]()\n\t}\n\thost, port, hasPort, ok := splitHostPort(hostPort)\n\tif !ok {\n\t\treturn Nothing[Url]()\n\t}\n\tcanonical, ok := NormalizeHost(host)\n\tif !ok {\n\t\treturn Nothing[Url]()\n\t}\n\tpath, query, hasQuery, fragment, hasFragment := splitRemainder(remainder)\n\treturn Something(Url{\n\t\tScheme: scheme, UserInfo: userInfo, HasUserInfo: hasUserInfo,\n\t\tHost: canonical, Port: FromInt64(int64(port)), HasPort: hasPort,\n\t\tPath: path, Query: query, HasQuery: hasQuery,\n\t\tFragment: fragment, HasFragment: hasFragment,\n\t})\n}\n\n// splitUserInfo cuts at the LAST `@`. Browsers and curl do the same, and taking the first\n// `@` is itself a bypass: `https://a@trusted.example.com@127.0.0.1/` puts a trusted-looking\n// name in the credentials slot and the real host after it.\nfunc splitUserInfo(authority string) (string, bool, string, bool) {\n\tat := strings.LastIndexByte(authority, '@')\n\tswitch {\n\tcase at < 0:\n\t\treturn \"\", false, authority, true\n\tcase at == len(authority)-1:\n\t\t// `user@` with no host at all.\n\t\treturn \"\", false, \"\", false\n\tdefault:\n\t\treturn authority[:at], true, authority[at+1:], true\n\t}\n}\n\n// splitHostPort reads `host[:port]`. An ambiguous shape or a malformed port fails the URL\n// rather than answering \"no port\": the two are different facts and a caller that reads a\n// missing port as the scheme's default would reach a different server.\nfunc splitHostPort(hostPort string) (string, int, bool, bool) {\n\tif strings.HasPrefix(hostPort, \"[\") {\n\t\tclose := strings.IndexByte(hostPort, ']')\n\t\tif close < 0 {\n\t\t\treturn \"\", 0, false, false\n\t\t}\n\t\thost := hostPort[:close+1]\n\t\ttail := hostPort[close+1:]\n\t\tswitch {\n\t\tcase tail == \"\":\n\t\t\treturn host, 0, false, true\n\t\tcase strings.HasPrefix(tail, \":\"):\n\t\t\tport, ok := parseUrlPort(tail[1:])\n\t\t\tif !ok {\n\t\t\t\treturn \"\", 0, false, false\n\t\t\t}\n\t\t\treturn host, port, true, true\n\t\tdefault:\n\t\t\treturn \"\", 0, false, false\n\t\t}\n\t}\n\tparts := strings.Split(hostPort, \":\")\n\tswitch len(parts) {\n\tcase 1:\n\t\treturn parts[0], 0, false, true\n\tcase 2:\n\t\tport, ok := parseUrlPort(parts[1])\n\t\tif !ok {\n\t\t\treturn \"\", 0, false, false\n\t\t}\n\t\treturn parts[0], port, true, true\n\tdefault:\n\t\t// More than one colon and no brackets: an unbracketed IPv6 literal is\n\t\t// indistinguishable from a bad port, so refuse rather than guess.\n\t\treturn \"\", 0, false, false\n\t}\n}\n\nfunc parseUrlPort(text string) (int, bool) {\n\tif len(text) == 0 || len(text) > 5 {\n\t\treturn 0, false\n\t}\n\tfor index := 0; index < len(text); index++ {\n\t\tif !asciiDigit(text[index]) {\n\t\t\treturn 0, false\n\t\t}\n\t}\n\tvalue, err := strconv.Atoi(text)\n\tif err != nil || value < 1 || value > 65535 {\n\t\treturn 0, false\n\t}\n\treturn value, true\n}\n\n// splitRemainder cuts what follows the authority into path / query / fragment. An empty path\n// is `/`, which is the same resource.\nfunc splitRemainder(remainder string) (string, string, bool, string, bool) {\n\thash := strings.IndexByte(remainder, '#')\n\tbefore, fragment, hasFragment := remainder, \"\", false\n\tif hash >= 0 {\n\t\tbefore, fragment, hasFragment = remainder[:hash], remainder[hash+1:], true\n\t}\n\tquestion := strings.IndexByte(before, '?')\n\tpath, query, hasQuery := before, \"\", false\n\tif question >= 0 {\n\t\tpath, query, hasQuery = before[:question], before[question+1:], true\n\t}\n\tif path == \"\" {\n\t\tpath = \"/\"\n\t}\n\treturn path, query, hasQuery, fragment, hasFragment\n}\n\nfunc UrlScheme(url Url) string { return url.Scheme }\nfunc UrlHost(url Url) string   { return url.Host }\nfunc UrlPath(url Url) string   { return url.Path }\n\n// UrlPort is the port only when it was WRITTEN.\nfunc UrlPort(url Url) Maybe[Int] {\n\tif !url.HasPort {\n\t\treturn Nothing[Int]()\n\t}\n\treturn Something(url.Port)\n}\n\n// UrlEffectivePort is the written port, or the scheme's default. Nothing for a scheme with\n// no registered default \226\128\148 a guess there would be a connection to somewhere unasked-for.\nfunc UrlEffectivePort(url Url) Maybe[Int] {\n\tif url.HasPort {\n\t\treturn Something(url.Port)\n\t}\n\tif port, known := schemeDefaultPort(url.Scheme); known {\n\t\treturn Something(FromInt64(int64(port)))\n\t}\n\treturn Nothing[Int]()\n}\n\n// UrlQuery and UrlFragment answer PRESENT-but-empty when the delimiter was written and\n// Nothing when it was not. The distinction is load-bearing for re-serialisation, which is\n// why they are a Maybe and not a String.\nfunc UrlQuery(url Url) Maybe[string] {\n\tif !url.HasQuery {\n\t\treturn Nothing[string]()\n\t}\n\treturn Something(url.Query)\n}\n\nfunc UrlFragment(url Url) Maybe[string] {\n\tif !url.HasFragment {\n\t\treturn Nothing[string]()\n\t}\n\treturn Something(url.Fragment)\n}\n\n// UrlUserInfo is everything before the LAST `@` of the authority. Exposed rather than\n// dropped: `https://trusted.example.com@127.0.0.1/` puts a trusted-looking name in the\n// credentials slot, and a check that reads the URL as text sees it as the host. A guard that\n// refuses any URL with userinfo present is then one line.\nfunc UrlUserInfo(url Url) Maybe[string] {\n\tif !url.HasUserInfo {\n\t\treturn Nothing[string]()\n\t}\n\treturn Something(url.UserInfo)\n}\n\n// UrlToString rebuilds the URL from its canonical parts. It is not the input text: the\n// scheme and host are canonicalised, and that is the point \226\128\148 what a check examined and what\n// a caller then uses are the same string.\nfunc UrlToString(url Url) string {\n\tvar out strings.Builder\n\tout.WriteString(url.Scheme)\n\tout.WriteString(\"://\")\n\tif url.HasUserInfo {\n\t\tout.WriteString(url.UserInfo)\n\t\tout.WriteByte('@')\n\t}\n\t// An IPv6 host goes back in brackets, which is where it came from.\n\tif strings.Contains(url.Host, \":\") {\n\t\tout.WriteByte('[')\n\t\tout.WriteString(url.Host)\n\t\tout.WriteByte(']')\n\t} else {\n\t\tout.WriteString(url.Host)\n\t}\n\tif url.HasPort {\n\t\tout.WriteByte(':')\n\t\tout.WriteString(url.Port.String())\n\t}\n\tout.WriteString(url.Path)\n\tif url.HasQuery {\n\t\tout.WriteByte('?')\n\t\tout.WriteString(url.Query)\n\t}\n\tif url.HasFragment {\n\t\tout.WriteByte('#')\n\t\tout.WriteString(url.Fragment)\n\t}\n\treturn out.String()\n}\n\n// UrlEqual compares two parsed URLs part by part.\n//\n// Part by part rather than by their text: a URL's parts include whether a delimiter was\n// WRITTEN, and `http://h/?` and `http://h/` are not the same URL even though everything they\n// hold is equal. Comparing the canonical text would say the same thing, and this says it\n// without building two strings to throw away.\n//\n// It exists at all because a `Url` is OPAQUE to the emitter \226\128\148 it sees no fields to walk \226\128\148\n// and because the port is a `teslrt.Int`, which is deliberately not comparable with `==`.\nfunc UrlEqual(left, right Url) bool {\n\treturn left.Scheme == right.Scheme &&\n\t\tleft.HasUserInfo == right.HasUserInfo && left.UserInfo == right.UserInfo &&\n\t\tleft.Host == right.Host &&\n\t\tleft.HasPort == right.HasPort && Equal(left.Port, right.Port) &&\n\t\tleft.Path == right.Path &&\n\t\tleft.HasQuery == right.HasQuery && left.Query == right.Query &&\n\t\tleft.HasFragment == right.HasFragment && left.Fragment == right.Fragment\n}\n");
  ("workers.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"os\"\n\t\"time\"\n)\n\n// StartWorkers activates a queue's workers: `concurrency` goroutines, each claiming and running\n// one job at a time. `dead` selects the dead-letter worker instead of the ordinary one.\nfunc StartWorkers(queue *Queue, handler func(any) JobOutcome, concurrency int, dead bool) struct{} {\n\treturn startWorkers(queue, handler, concurrency, dead, nil)\n}\n\nfunc startWorkers(queue *Queue, handler func(any) JobOutcome, concurrency int, dead bool, activity func(bool)) struct{} {\n\tif concurrency < 1 {\n\t\tconcurrency = 1\n\t}\n\tfor range concurrency {\n\t\tgo func() {\n\t\t\tfailures := 0\n\t\t\tfor {\n\t\t\t\tif activity != nil {\n\t\t\t\t\tactivity(true)\n\t\t\t\t}\n\t\t\t\toutcome, ok := workerIteration(queue, handler, dead)\n\t\t\t\tif !ok {\n\t\t\t\t\t// The STORE failed \226\128\148 the database unreachable, a lease timed out, a\n\t\t\t\t\t// row that will not decode \226\128\148 not the job. `runJob` already turns a\n\t\t\t\t\t// job's own trap into a failed attempt; this guard is for the claim\n\t\t\t\t\t// and completion themselves, which used to unwind the goroutine and,\n\t\t\t\t\t// as an unrecovered panic, take the whole process with it: one\n\t\t\t\t\t// database blip killed the HTTP server too. Racket's worker thread\n\t\t\t\t\t// had the same `with-handlers`. Report, back off, try again.\n\t\t\t\t\tfailures++\n\t\t\t\t\tqueue.waitForWork(workerBackoff(failures))\n\t\t\t\t} else {\n\t\t\t\t\tfailures = 0\n\t\t\t\t\tif !outcome.Ran {\n\t\t\t\t\t\tqueue.waitForWork(queue.idleInterval())\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif activity != nil {\n\t\t\t\t\tactivity(false)\n\t\t\t\t}\n\t\t\t}\n\t\t}()\n\t}\n\treturn struct{}{}\n}\n\n// workerIteration claims and runs one job, answering ok=false when the STORE trapped (the\n// job's own trap is already a JobOutcome). The trap is reported once per occurrence.\nfunc workerIteration(queue *Queue, handler func(any) JobOutcome, dead bool) (outcome JobOutcome, ok bool) {\n\tdefer func() {\n\t\tif trap := recover(); trap != nil {\n\t\t\tfmt.Fprintf(os.Stderr, \"tesl: queue %s: worker could not reach the job store: %v\\n\",\n\t\t\t\tqueue.name, trap)\n\t\t\toutcome, ok = JobOutcome{}, false\n\t\t}\n\t}()\n\tif dead {\n\t\treturn ProcessNextDeadJob(queue, handler), true\n\t}\n\treturn ProcessNextJob(queue, handler), true\n}\n\n// workerBackoff is how long a worker waits after `failures` consecutive store failures:\n// 1 s, 2 s, 4 s \226\128\166 capped at 30 s, and cut short by the doorbell like any other wait.\nfunc workerBackoff(failures int) time.Duration {\n\twait := time.Second << min(failures-1, 5)\n\tif wait > 30*time.Second {\n\t\treturn 30 * time.Second\n\t}\n\treturn wait\n}\n\n// idleInterval is how long a worker that found nothing waits before asking again. Against\n// the in-memory store a claim is a mutex and a heap pop, so 50 ms keeps a test's turnaround\n// short; against a durable store every claim is a round trip to the server, and N workers\n// each polling twenty times a second is a steady load for an idle queue, so one second.\nfunc (queue *Queue) idleInterval() time.Duration {\n\t// The FALLBACK wait: the doorbell (`Enqueue` locally, a `tesl_queue` NOTIFY from any\n\t// instance) wakes a worker earlier. Against the durable store the poll is only insurance\n\t// against a notification lost while the LISTEN connection reconnects \226\128\148 tesl/queue.rkt's\n\t// poller used the same five seconds.\n\tif queue.durable() != nil {\n\t\treturn 5 * time.Second\n\t}\n\treturn 50 * time.Millisecond\n}\n");
]
